// The App Pages designer and its runtime: the palette and the layout grid, the properties panel,
// the action and transform editors, and the engine that runs a saved page. Lifted out of
// apppage.html so the browser can cache it — page.html opens every saved page as
// apppage.html?page=…&mode=run in a frame, and a reader who only ever runs a page should not
// re-download the whole designer each time one is opened.
//
// A classic script, deliberately: every function here is global, which is what the markup's
// onclick= handlers and the HTML this file writes into innerHTML both call into. It loads after
// appcatalog.js (AC) and gridpivot.js and depends on both.

// Placement grid — must match .canvas / .run-canvas in the stylesheet, since a drop position is
// worked out from pixels and turned straight into a row/column. The CSS grid is drawn in half
// rows so a control can be half a row tall; a control's own row stays in whole rows, and only
// its height is allowed the half step.
const COLUMNS = 24;
const HALF_ROW = 38;
const ROW_GAP = 8;
const ROW_PITCH = (HALF_ROW + ROW_GAP) * 2;   // one whole row, gap included: 92px
const MIN_ROW_SPAN = 0.5;
// As tall as a control may be asked to be. A text area laid out to hold a whole response, or a
// grid meant to be read rather than glanced at, is routinely taller than the twelve rows this used
// to stop at — and the page scrolls, so there was never much behind the lower ceiling.
const MAX_ROW_SPAN = 40;

// Sentinel target: instead of filling a control that is already on the page, every run stacks
// another grid underneath the form, newest on top.
const NEW_GRID = '__new_grid__';

// How many rows an action fans out over unless it says otherwise, and how many of those calls
// are in flight at once. A grid of twenty-seven thousand rows is an ordinary thing for one of
// these endpoints to return; a fan-out with no cap over one is a load test of whatever is on the
// other end, run by someone who thought they were looking something up. Both numbers mirror
// AppPageAction — the default cap there and the ceiling here are the page's own manners.
const DEFAULT_ROW_LIMIT = 25;
const FANOUT_CONCURRENCY = 6;
// The column a fan-out into one grid puts each answer's row under, so a hundred rows from a
// hundred calls still say which call each came from. An answer carrying a field of this name
// keeps its own — it is the answer, and renaming its data to make room would be worse.
const FAN_SOURCE_COLUMN = 'source';

// How much of a large result a grid puts in the document at once, and how much of it it reads to
// work out its columns. A response of tens of thousands of rows is a normal thing for one of
// these endpoints to return and a fatal thing to render whole — see moreBar().
const GRID_PAGE = 200;
const COLUMN_SCAN = 200;
// Rows past which "Show all" asks first rather than simply obliging.
const BIG_GRID = 2000;
// How long typing in a column filter settles before the rows are refiltered.
const FILTER_DEBOUNCE = 180;

const PALETTE = [
    { type: 'text',     glyph: 'ab',  label: 'Text' },
    { type: 'textarea', glyph: '¶', label: 'Text Area' },
    { type: 'number',   glyph: '12', label: 'Number' },
    { type: 'date',     glyph: '▦', label: 'Date' },
    { type: 'checkbox', glyph: '✓', label: 'Checkbox' },
    { type: 'select',   glyph: '▾', label: 'Select' },
    { type: 'multiselect', glyph: '≡', label: 'Multi-Select' },
    { type: 'hidden',   glyph: '∅', label: 'Hidden' },
    { type: 'label',    glyph: 'T',  label: 'Label' },
    { type: 'button',   glyph: '▶', label: 'Button' },
    { type: 'multibutton', glyph: '⋮', label: 'Multi-Button' },
    { type: 'link',     glyph: '↗', label: 'Link' },
    { type: 'grid',     glyph: '☷', label: 'Grid' },
    { type: 'tabs',     glyph: '⊞', label: 'Tabs' },
    { type: 'panel',    glyph: '▢', label: 'Panel' },
    { type: 'pie',      glyph: '◔', label: 'Pie Chart' },
    { type: 'piegrid',  glyph: '◕', label: 'Pie + Grids' },
    { type: 'bar',      glyph: '▥', label: 'Bar Chart' },
    { type: 'timeseries', glyph: '⟋', label: 'Time Series' },
    { type: 'line',     glyph: '∿', label: 'Line Chart' },
    { type: 'page',     glyph: '⧉', label: 'Page' }
];

// ── Child pages ──────────────────────────────────────────────────────────
// A page control runs another saved page inside this one, in a frame of its own. The child is the
// ordinary standalone page with two extra parameters: `embed`, the id of the control it sits in —
// which is what tells it to report each trigger's actions up to its parent — and `depth`, how many
// parents are above it. The save refuses a page that leads back to itself; the depth cap is the
// backstop for a loop created by editing another page afterwards.
const PAGE_PARAMS = new URLSearchParams(location.search);
// The parameters the page itself is addressed by. Everything else in the query string names a
// field on the page and is filled into it as the page opens — see #prefillFromUrl.
const RESERVED_PARAMS = ['page', 'mode', 'embed', 'depth'];
// Opened as the page rather than as the designer: apppage.html?page=x&mode=run, which is the link
// handed to whoever uses the page, and the link a child page is framed by. Nothing meant for the
// builder — the unsaved-work guard included — has any business firing there.
const STANDALONE = !!PAGE_PARAMS.get('page') && PAGE_PARAMS.get('mode') === 'run';
const EMBED_ID = PAGE_PARAMS.get('embed') || '';
const CHILD_DEPTH = Math.max(Number(PAGE_PARAMS.get('depth')) || 0, 0);
const MAX_CHILD_DEPTH = 4;
const CHILD_MESSAGE = 'apppage-actions';

// The charts drawn out of rows an action binds. A pie and a pie-with-grids share every piece of
// how a row becomes a wedge; a bar chart shares how a row is read — a category field, and value
// fields that default to counting the rows. See #chartSeries.
const CHART_TYPES = ['pie', 'piegrid', 'bar', 'timeseries', 'line'];
function isChart(type) { return CHART_TYPES.includes(type); }

// The two charts that read rows along an axis and draw a line per series. They share every piece
// of how a row becomes a point — the line column, the value columns, the filters, how values
// landing together are combined, the legend, the zoom — and differ in one thing only: what the x
// of a row is. A time series reads it out of a column of instants; a line chart counts, so a
// row's x is its position in the rows and the axis is the line number. See #seriesX.
// Mirrors AppCatalogService#SERIES_TYPES.
const SERIES_TYPES = ['timeseries', 'line'];
function isSeries(type) { return SERIES_TYPES.includes(type); }

/** Whether this chart's x axis is read from a column of times rather than counted. */
function isTimed(c) { return !!c && c.type === 'timeseries'; }

// What configures a grid's clickable columns and rows: a grid, and a pie with grids for the grids
// it opens. Mirrors AppCatalogService#GRID_OWNER_TYPES.
const GRID_OWNER_TYPES = ['grid', 'piegrid'];

/** What may name a grid to draw itself from: any chart, and another grid. */
function drawsFromGrid(type) {
    return isChart(type) || type === 'grid';
}

// What a tab set may NOT hold. Everything else may, which is the rule: a tab is a place on the
// page with a name over it, and anything that can sit on the page can sit there. Grids and charts
// are what tab sets were built for and stay the obvious ones — a page that answers a question
// with a grid, a pie of it and a bar chart beside them is three tabs rather than three controls
// down a screen — but the form half of a page belongs in tabs just as often: a set whose first
// tab is the fields to fill in and whose others are the readings of what came back, or a wizard
// whose steps are its tabs.
//
// One type stays out. A hidden field cannot be a tab — it is not on screen to be looked at, so a
// tab holding one is a name over nothing, and it has to stay where the page lays it out to go on
// carrying its value.
//
// A tab set may hold another tab set, which is how a strip that has grown too long is grouped:
// eight environments' worth of grids read far better as two tabs of four than as one row of eight
// names nobody can scan. The outer tab then answers for everything inside it at once — see
// #tabsOutcome — so "is UAT fine" is one badge on one tab rather than four tabs to open.
// Mirrors AppCatalogService#NOT_TAB_CHILD_TYPES.
const NOT_TAB_CHILD_TYPES = ['hidden'];
function isTabChild(type) { return !NOT_TAB_CHILD_TYPES.includes(type); }

// ── Containers ───────────────────────────────────────────────────────────
// The two controls that hold other controls instead of content of their own. A tab set shows one
// of its children at a time behind a strip of names; a panel shows all of them at once, laid out
// inside a box with a name on it. Everything else about them is the same thing said twice — a
// child has to be on the page, a child belongs to exactly one container, no container may arrive
// back at itself, and a child is drawn by its container rather than on the layout — so it is
// said once here and both kinds go through it. Mirrors AppCatalogService#CONTAINER_TYPES.
const CONTAINER_TYPES = ['tabs', 'panel'];
function isContainer(type) { return CONTAINER_TYPES.includes(type); }

/** What one container holds, whichever kind it is — the live array, so it can be spliced. */
function childIdsOf(c) {
    if (!c) return [];
    if (c.type === 'tabs')  return (c.tabControlIds = c.tabControlIds || []);
    if (c.type === 'panel') return (c.panelControlIds = c.panelControlIds || []);
    return [];
}

/**
 * The container drawing this control — a tab set or a panel — or null when it is laid out on the
 * page itself.
 *
 * <p>The question nearly everything asks: a control inside a container has no placement of its
 * own on the layout, is not drawn by the canvas or by the run canvas, and is reached through its
 * container's own drawing instead.
 */
function heldBy(controlId) {
    return page.controls.find(c => isContainer(c.type) && childIdsOf(c).includes(controlId)) || null;
}

/** The tabs control holding this control, or null — narrower than {@link #heldBy}, for the
 *  places that mean a tab specifically rather than "drawn by something else". */
function tabsHolding(controlId) {
    const holder = heldBy(controlId);
    return holder && holder.type === 'tabs' ? holder : null;
}

/** What a container holds, in order, skipping any the page no longer has. */
function containerChildren(c) {
    return childIdsOf(c).map(findControl).filter(Boolean);
}

/**
 * Whether putting this control into that container would make a container hold itself — directly,
 * or by way of something it already holds.
 *
 * <p>The one arrangement nesting cannot have. A container inside itself has no depth at which it
 * stops being drawn, so drawing it would recurse until the browser gave up; and it means nothing
 * anyway, since there would be no outermost tab or box for anyone to be looking at. Mirrors
 * AppCatalogService#validateTabCycles.
 */
function wouldNestIntoItself(containerId, childId) {
    return containerReaches(childId, containerId, new Set());
}

/** Whether `targetId` is `fromId`, or is found by following the containers held under it. */
function containerReaches(fromId, targetId, seen) {
    if (fromId === targetId) return true;
    if (seen.has(fromId)) return false;
    seen.add(fromId);
    const set = findControl(fromId);
    if (!set || !isContainer(set.type)) return false;
    return childIdsOf(set).some(id => containerReaches(id, targetId, seen));
}

/**
 * A container's name as somewhere to put something, with whatever holds it in front —
 * "Environments &rsaquo; UAT" rather than "UAT". A page that groups its tabs has several boxes
 * called Detail, and a list of them is only useful if which is which is on the name.
 */
function containerPath(c) {
    const names = [];
    let at = c;
    const seen = new Set();
    while (at && !seen.has(at.controlId)) {
        seen.add(at.controlId);
        names.unshift(controlTitle(at));
        at = heldBy(at.controlId);
    }
    return names.join(' › ');
}

/**
 * Why this container cannot hold that control, or '' where it can — the same three refusals the
 * drop makes, in one place so the dropdown and the drag agree on what is allowed.
 */
function containerRefusal(container, control) {
    if (!container || !control) return '';
    if (container.controlId === control.controlId) return 'a container cannot hold itself';
    if (!isTabChild(control.type)) {
        return 'a hidden field is not on screen, so a place in a container for one would be a name over nothing';
    }
    if (wouldNestIntoItself(container.controlId, control.controlId)) {
        return '"' + controlTitle(control) + '" already holds "' + controlTitle(container) + '"';
    }
    // A pie with grids fills a tab set with a grid per pie; a tab of that same set would be the
    // chart adding tabs beside itself on every run — see #dropIntoTabs.
    if (container.type === 'tabs' && control.type === 'piegrid' && control.tabsControlId === container.controlId) {
        return 'it already puts its own grids into this tab set';
    }
    return '';
}

/** Every container on the page this control could be moved into, deepest path last. */
function containerChoices(control) {
    return page.controls
        .filter(t => isContainer(t.type) && !containerRefusal(t, control))
        .sort((a, b) => containerPath(a).localeCompare(containerPath(b)));
}

/**
 * Moves a control into another container — a tab of another tab set, a place in another panel —
 * or, with no container named, back onto the page itself.
 *
 * <p>The same move the canvas makes by dragging, offered as a list because dragging is only easy
 * while both ends of it are on screen. A tab set eight tabs deep inside a panel near the bottom
 * of a long page is a drop nobody can aim, and moving a control out of a tab means finding the
 * layout underneath it first. Nothing else about the control changes: same id, same field name,
 * same actions aimed at it, and the row and column it kept while it was a tab are where it lands
 * when it comes back out.
 */
function moveToContainer(containerId) {
    const control = findControl(selectedId);
    if (!control) return;
    const was = heldBy(control.controlId);
    if ((was ? was.controlId : '') === containerId) return;

    if (!containerId) {
        releaseFromContainers(control.controlId);
        selectedId = control.controlId;
        AC.setStatus('statusBar', '"' + controlTitle(control) + '" is back on the page, at row '
            + control.row + ' column ' + control.col + '.', 'ok');
        renderAll();
        return;
    }

    const container = findControl(containerId);
    const refusal = containerRefusal(container, control);
    if (refusal) { AC.setStatus('statusBar', 'Cannot move it there: ' + refusal + '.', 'error'); return; }

    // Under whatever is already in the box, keeping the column it was in. A tab set lays its
    // children out itself and ignores both numbers, but a panel is a small layout, and a control
    // arriving at the row it happened to be at on the page would as often as not land on top of
    // something already in there. The drag does not need this because where it was let go is the
    // answer; a pick from a list has no such answer, so the bottom of the box is the one that is
    // never wrong.
    if (container.type === 'panel') {
        const inside = containerChildren(container);
        control.row = inside.reduce((low, k) => Math.max(low, (k.row || 0) + rowSpanOf(k)), 0);
        control.col = Math.min(control.col, COLUMNS - control.span);
    }
    releaseFromContainers(control.controlId);
    childIdsOf(container).push(control.controlId);
    // A container draws everything it holds, so a grid that was hidden stops being hidden as it
    // goes in — the save refuses the pair, and it is a setting the page asked for going away, so
    // it is said out loud rather than quietly unticked. Same bargain as #dropIntoTabs.
    const wasHidden = !!control.hideOnRun;
    control.hideOnRun = false;
    selectedId = control.controlId;
    AC.setStatus('statusBar', '"' + controlTitle(control) + '" moved into ' + containerPath(container)
        + (container.type === 'tabs' ? ', as its last tab' : '')
        + (wasHidden ? '. It is no longer hidden: a container draws what it holds.' : '.'), 'ok');
    renderAll();
}

// The wedge colours, taken in order and wrapped round when a pie has more slices than there are
// colours. Fixed rather than generated so the same list always comes out the same chart, and a
// slice keeps its colour when the one above it is edited.
const PIE_COLORS = ['#0052cc', '#00875a', '#ff8b00', '#5243aa', '#00a3bf',
                    '#de350b', '#36b37e', '#ffab00', '#6554c0', '#ff5630'];

// Controls that hold a value the operator supplies — the ones with a field name, the ones a
// mandatory check applies to, and the ones an action's ${placeholder} can read.
//
// A multi-select is one of them and holds its picks as one comma-separated value, which is what
// lets it be here at all: everything downstream reads a control by field name and gets a string,
// so ${envs} carries "uat,prod" into an input, a path or an assignment without any of them
// knowing the operator picked from a list rather than typed into a box.
// How a text area lays out a value before showing it. Mirrors AppPageControl#textFormat.
const TEXT_FORMATS = [
    { id: 'NONE', label: 'As it comes' },
    { id: 'JSON', label: 'JSON pretty print' },
    { id: 'XML',  label: 'XML pretty print' }
];
const VALUE_TYPES = ['text', 'textarea','number', 'date', 'hidden', 'select', 'multiselect', 'checkbox'];

// Controls that run use case instances when clicked, and the ones a response can land in.
// A link is in both lists, and they mean different halves of it: it runs actions when clicked, and
// what an action binds into it is the address it points at. Either half stands on its own — a link
// with only actions is the trigger it always was, one with only an address is a link the page
// filled in — and a link with both does both, opening in a new tab so the page it ran from is
// still there behind it.
const ACTION_TYPES = ['button', 'link'];
// A pie chart is a target without being something the operator sets off — it is in
// TRIGGERLESS_TYPES for that — and the two are different questions. The rows an action binds
// become its wedges, named and sized by two fields of each row. See #bindChart.
const TARGET_TYPES = ['grid', 'select', 'multiselect', 'text', 'textarea', 'link', 'pie', 'piegrid', 'bar',
                      'timeseries', 'line'];

// Controls another control can write a value into. Wider than TARGET_TYPES: a response has to
// land somewhere that can hold rows or be read back, while an assignment is only a value being
// put somewhere — a number, a date, a checkbox and a hidden field all take one, and a label
// takes one to show.
const ASSIGN_TYPES = VALUE_TYPES.concat('label');

// Controls nothing ever sets off. A grid, a label, a tab set and a panel are not touched by the
// operator — a panel is a box the controls inside it are drawn in, and nobody clicks the box; a
// hidden field is not on screen to be touched at all — it carries a value the rest of the page
// reads, and a value arriving in it deliberately does not fire its own trigger. So a value one of
// these was told to write, or an action it was told to run, could never run: wiring that looks
// alive in the designer and does nothing on the page.
//
// A multi-button is here for a different reason, and it is the one worth spelling out. It is
// clicked — that is the whole of what it does — but the click opens its menu rather than running
// anything, and each entry on that menu is a trigger of its own with its own actions. So the
// control level has nothing to set and nothing to run: wiring written there would be wiring the
// operator could never reach, whichever entry they went on to pick. See #menuProps.
// Mirrors AppCatalogService#TRIGGERLESS_TYPES.
const TRIGGERLESS_TYPES = ['grid', 'label', 'tabs', 'panel', 'hidden', 'multibutton',
                           'pie', 'piegrid', 'bar', 'timeseries', 'line', 'page'];

// What an action does when it runs. USECASE is every action there has ever been — call an
// endpoint, bind what comes back. A special kind produces its answer from what this server
// already knows instead, so it configures nothing about a call because it makes none.
// Mirrors AppPageAction#USECASE / #PERFORMANCE.
const USECASE_ACTION = 'USECASE';
const PERFORMANCE_ACTION = 'PERFORMANCE';
const COMPARE_ACTION = 'COMPARE';
const DATASET_ACTION = 'DATASET';

// How a dataset action's own condition tests a column. These are the dataset library's own
// operator names rather than a set of our own mapped onto them: the condition is sent for the
// library to evaluate, so a name it does not know would be a filter that narrowed nothing.
// Mirrors AppPageDatasetFilter#OPERATORS.
const DATASET_OPERATORS = [
    { op: 'equals',      label: 'equals' },
    { op: 'notEquals',   label: 'not equals' },
    { op: 'contains',    label: 'contains' },
    { op: 'notContains', label: 'not contains' },
    { op: 'startsWith',  label: 'starts with' },
    { op: 'endsWith',    label: 'ends with' }
];
const DATASET_DEFAULT_OPERATOR = 'equals';

// The columns a performance summary comes back under, in the order they are worth reading:
// which endpoint, then how much it is used, then how it behaves. Named here so the grid is laid
// out in that order rather than in whatever order the first row's keys happen to enumerate.
// Mirrors AppPerformanceRow.
const PERFORMANCE_COLUMNS = ['app', 'environment', 'useCase', 'requestCount', 'avgTimeTaken', 'maxTimeTaken'];

// The filters a performance action understands, written as an ordinary action's inputs are:
// {"appName": "${appPick}"}. Anything else in that map is ignored rather than sent, since there
// is no call for it to be sent on.
const PERFORMANCE_FILTERS = ['appName', 'environment', 'useCase'];

// ── Comparing one use case across two environments ───────────────────────
// A compare action runs the same instance with the same inputs against two environments and puts
// what differs between the two answers into a grid. Everything below is what that report is made
// of. Mirrors AppPageAction#COMPARE.

// The columns of the report, in the order they are worth reading: where the difference is, what
// kind it is, what each side said, and — for two numbers — how far apart they are. Named here so
// a grid is laid out this way rather than in whatever order the first row's keys enumerate, and
// so an empty report still arrives with columns.
const COMPARE_COLUMNS = ['path', 'status', 'baseline', 'candidate', 'difference', 'differencePct'];

// What one row of the report says happened at that path. Written as words rather than codes
// because the grid is read by whoever pressed the button, not parsed.
const COMPARE_STATUS = {
    changed:   'CHANGED',
    onlyA:     'ONLY IN BASELINE',
    onlyB:     'ONLY IN CANDIDATE',
    type:      'TYPE CHANGED',
    unpaired:  'TOO MANY TO PAIR',
    tolerated: 'WITHIN THRESHOLD',
    same:      'SAME'
};

// How each response is read before it is compared. Mirrors AppPageAction#COMPARE_JSON / #COMPARE_XML.
const COMPARE_JSON = 'JSON';
const COMPARE_XML = 'XML';

// How much of the comparison reaches the grid. Mirrors AppPageAction#REPORT_DIFFERENCES and friends.
const REPORT_DIFFERENCES = 'DIFFERENCES';
const REPORT_TOLERATED = 'TOLERATED';
const REPORT_EVERYTHING = 'EVERYTHING';

// As many elements as one array is paired up across, when the two sides do not simply hold the
// same elements. Pairing is quadratic — every leftover on one side scored against every leftover
// on the other — so past this many the page pairs what matches outright and reports the rest as
// unmatched rather than locking the browser up on a response nobody meant to diff whole.
const COMPARE_PAIRING_LIMIT = 250;

// How much of a whole subtree one cell of the report shows before it is cut short. A grid cell is
// where you see that something is there and what it roughly is; the response itself is in
// Technical Details, which keeps both sides whole.
const COMPARE_CELL_LIMIT = 500;

// The variables every page has whether or not it declares anything, and what each one stands
// for. Worked out when a trigger fires rather than stored, which is the whole of the difference
// between these and the ad-hoc ones the page carries: a stored variable is a value somebody
// typed, and a built-in is a value the run has. Mirrors AppPageVariable#BUILT_IN.
const BUILT_IN_VARIABLES = [
    { name: 'MACHINE',    what: 'The host this server runs on, without its domain — which box the calls left from.' },
    { name: 'PID',        what: 'The process id of the JVM serving this page — which of the instances on that box answered.' },
    { name: 'DATESTAMP',  what: 'The date the trigger fired, as yyyyMMdd.' },
    { name: 'PREVDATESTAMP', what: 'The business day before that date, as yyyyMMdd — the nearest earlier weekday, so a Monday run looks back to the Friday. Weekends only: no holiday calendar is applied.' },
    { name: 'NEXTDATESTAMP', what: 'The business day after it, on the same rule — a Friday run looks forward to the Monday.' },
    { name: 'DATETIME',   what: 'The moment it fired, as yyyyMMddHHmmss.' },
    { name: 'DATETIMEHR', what: 'The same moment written to be read rather than parsed.' },
    { name: 'UUID',       what: 'A fresh one per call, so every call of a fan-out carries its own; the same one wherever it is written twice in that call.' },
    { name: 'ROWNUM',     what: 'Which row of the source grid this call is for, counting from 1. Only set while an action is running once per row — elsewhere nothing answers to it, so an input written against it keeps the value the instance was saved with.' },
    // The one built-in that is a switch rather than a reading. It is listed here so it is read
    // and written exactly like the others — ${DEBUG} in a request body is a legal thing to
    // send — and marked so the panel draws it as the tick box it is instead of a sample.
    { name: 'DEBUG', toggle: true, what: 'Whether this page keeps the detail behind its calls. On, every request and response a trigger made is held for Technical Details to show. Off, the calls still go out and still fill the page — only the keeping stops, on this page and on the server both. Turn it off where the page runs against production all day and nobody is going to read the sixth-last response.' }
];

// Marks the scope object an action resolves its templates against as one carrying a grid row,
// so a message about an unanswered ${name} can say whether there was a row for it to be a column
// of. Spelled with a $, which the placeholder grammar does not allow inside a name, so no
// template can ever ask for it.
const ROW_SCOPE_MARK = '$fanRow';

// How a row filter tests a cell. CONTAINS is the default because it is what the grid's own
// filter row does, and a filter written on an action should mean what the same text typed into
// the grid means. Mirrors AppPageRowFilter#OPERATORS.
const ROW_FILTER_OPERATORS = [
    { op: 'CONTAINS',     label: 'contains' },
    { op: 'NOT_CONTAINS', label: 'does not contain' },
    { op: 'EQUALS',       label: 'is' },
    { op: 'NOT_EQUALS',   label: 'is not' },
    { op: 'STARTS_WITH',  label: 'starts with' },
    { op: 'ENDS_WITH',    label: 'ends with' },
    { op: 'GT',           label: 'is more than' },
    { op: 'LT',           label: 'is less than' },
    { op: 'EMPTY',        label: 'is empty' },
    { op: 'NOT_EMPTY',    label: 'is not empty' },
    { op: 'REGEX',        label: 'matches (regex)' }
];
// Tests that read the cell alone, so the box beside them is not asking for anything.
const VALUELESS_OPERATORS = ['EMPTY', 'NOT_EMPTY'];

// Where one column of a collected fan-out's grid gets its cell. Mirrors AppPageResultColumn.
const RESULT_COLUMN_KINDS = [
    { kind: 'ROW',    label: 'Column of the source row',  placeholder: 'orderId' },
    { kind: 'PATH',   label: 'Path into the response',    placeholder: 'data.order.status' },
    { kind: 'META',   label: 'Field of the call record',  placeholder: 'statusCode' },
    { kind: 'HEADER', label: 'Response header',           placeholder: 'Content-Type' },
    { kind: 'LABEL',  label: 'What the call was called',  placeholder: '' }
];
// The one kind that reads something there is only one of, so it asks for nothing.
const LABEL_COLUMN = 'LABEL';

// Where an enriched column of a grid gets its cell as the grid fills. Mirrors AppPageEnrichColumn.
const ENRICH_COLUMN_KINDS = [
    { kind: 'META',    label: 'Field of the call record', placeholder: 'statusCode' },
    { kind: 'HEADER',  label: 'Response header',          placeholder: 'Content-Type' },
    { kind: 'VLOOKUP', label: 'VLOOKUP into a dataset',   placeholder: '' },
    { kind: 'GRID_VLOOKUP', label: 'VLOOKUP into a grid', placeholder: '' },
    { kind: 'GRID_VLOOKUP_ROW', label: 'VLOOKUP a whole row from a grid', placeholder: '' },
    { kind: 'REGEX',   label: 'Regex over a column',      placeholder: '(\\w+)-(\\d+)' }
];

/** The enrichment kinds that look into another grid on the page. Mirrors AppPageEnrichColumn.GRID_KINDS. */
const GRID_LOOKUP_KINDS = ['GRID_VLOOKUP', 'GRID_VLOOKUP_ROW'];

/** The one enrichment kind that has no column name of its own: it is named after the row it finds. */
const WHOLE_ROW_LOOKUP = 'GRID_VLOOKUP_ROW';

// How many half-rows a minimized tab set keeps: its strip and nothing else. The layout grid is
// drawn in half rows, so one whole row is two of them.
const COLLAPSED_HALF_ROWS = 2;

/** Whether this action summarises performance rather than running a use case instance. */
function isPerformanceAction(a) { return !!a && a.actionKind === PERFORMANCE_ACTION; }

/** Whether this action runs one instance against two environments and reports what differs. */
function isCompareAction(a) { return !!a && a.actionKind === COMPARE_ACTION; }

/** Whether this action binds a static dataset's rows rather than a response. */
function isDatasetAction(a) { return !!a && a.actionKind === DATASET_ACTION; }

/**
 * Whether this action is one of the kinds that does not read a response into a control the
 * ordinary way — asked wherever the answer is "it has its own shape and its own form", which is
 * most of the places the two special kinds are asked about at all.
 */
function isSpecialAction(a) { return isPerformanceAction(a) || isCompareAction(a) || isDatasetAction(a); }

// Controls that pick from a list of options. The two differ in how many may be picked and in
// nothing else — same option sources, same designer panel, same thing an action fills — so
// everywhere that difference does not matter asks this rather than naming one of them.
function isSelect(type) { return type === 'select' || type === 'multiselect'; }

// How a multi-select's picks are carried as the single value every other part of the page reads.
// A comma because that is what an operator typing the same thing by hand would write, and what a
// use case input expecting a list already takes.
const MULTI_SEPARATOR = ',';

/** A multi-select's chosen options, as the one value the page holds for it. */
function multiValue(select) {
    return [...select.selectedOptions].map(o => o.value).join(MULTI_SEPARATOR);
}

/** The picks a stored value names, for putting a multi-select back the way it was. */
function multiParts(text) {
    return String(text === undefined || text === null ? '' : text)
        .split(MULTI_SEPARATOR).map(part => part.trim()).filter(part => part !== '');
}

// ── A date control's default ─────────────────────────────────────────────
// A date box is the one control that refuses the value it is handed. Every other one shows
// whatever text it is given, so a default typed into the designer is a default the operator
// sees; a date box shows only yyyy-MM-dd and silently empties itself for anything else — which
// is exactly what a default written as ${DATESTAMP}, as 15/09/2026, or as the yyyyMMdd this
// catalog stamps everywhere else is. The box came up blank and nothing said why.
//
// So the default is read here into the one form the box will take, out of every form somebody
// would reasonably have written it in, and the designer is told what it comes to — see
// #renderProps. What cannot be read is still an empty box, but it is an empty box the panel
// has already complained about.

// ── A date control's format ─────────────────────────────────────────────
// The box itself is the browser's date picker and takes yyyy-MM-dd and nothing else; that is not
// negotiable and is not the interesting part. What is, is that yyyy-MM-dd is rarely the form the
// call behind the page wants — a batch endpoint asks for yyyyMMdd, a European one for dd/MM/yyyy
// — and until there was a format here the only way to get one was to pick a date and then
// reformat it by hand in every input that used it.
//
// So a date control holds one day in two forms. The box keeps the ISO one because it must, and
// ${fieldName} keeps the one its designer picked, which is what every input template, every
// assignment and every export sees. A control naming no format holds ISO in both, which is what
// every date control saved before this existed does.

/** The form the date box itself speaks, whatever the control publishes its value in. */
const ISO_FORMAT = 'yyyy-MM-dd';

/** The formats a date control may carry its value in, in the order the panel offers them. */
const DATE_FORMATS = [
    ISO_FORMAT, 'dd/MM/yyyy', 'MM/dd/yyyy', 'dd-MM-yyyy', 'dd.MM.yyyy',
    'yyyy/MM/dd', 'yyyyMMdd', 'dd-MMM-yyyy', 'MMM dd, yyyy'
];

/** Month names as a format writes them, and as one carrying MMM is read back. */
const DATE_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** What a control's dates are written in — ISO for one saved before formats existed. */
function dateFormatOf(control) {
    const wanted = ((control && control.dateFormat) || '').trim();
    return DATE_FORMATS.includes(wanted) ? wanted : ISO_FORMAT;
}

/**
 * Whether a format writes the day before the month. This is the one thing about a date that
 * cannot be worked out from the date: 05/09/2026 is the ninth of May or the fifth of September
 * and only the format says which. Read off the pattern itself rather than listed, so a format
 * added to DATE_FORMATS is understood without being registered anywhere else.
 */
function dayFirst(format) {
    const pattern = String(format || '');
    const day = pattern.indexOf('d'), month = pattern.indexOf('M');
    return day >= 0 && (month < 0 || day < month);
}

/** The month a name stands for, 1 to 12, or 0 when it names none. */
function monthNumber(name) {
    const text = String(name || '').trim().toLowerCase().slice(0, 3);
    return DATE_MONTHS.findIndex(m => m.toLowerCase() === text) + 1;
}

/**
 * A yyyy-MM-dd day written out the way a format asks for it, or nothing at all when what came in
 * was not a day. The tokens are the ones a Java date pattern uses — yyyy, yy, MMM, MM, M, dd, d —
 * so a format shown in the panel reads the same as one written on the server.
 */
function formatDay(iso, format) {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso === undefined || iso === null ? '' : iso).trim());
    if (!m) return '';
    const pattern = (format || '').trim();
    if (!pattern || pattern === ISO_FORMAT) return m[0];
    const year = m[1], month = +m[2], day = +m[3];
    const pad = n => String(n).padStart(2, '0');
    return pattern.replace(/yyyy|yy|MMM|MM|dd|M|d/g, token => {
        if (token === 'yyyy') return year;
        if (token === 'yy')   return year.slice(2);
        if (token === 'MMM')  return DATE_MONTHS[month - 1];
        if (token === 'MM')   return pad(month);
        if (token === 'M')    return String(month);
        if (token === 'dd')   return pad(day);
        return String(day);
    });
}

/**
 * A date control's value as the page holds it: the day it is showing, in the control's own
 * format. Whatever form a date reaches the control in — a typed default, a row's 20260915, the
 * ${DATESTAMP} an action wrote — this is the one form it leaves in.
 */
function dateText(control, iso) {
    return formatDay(iso, dateFormatOf(control));
}

/** The ISO day the box should show, given a value in any form the control accepts. */
function dateIso(control, text) {
    return dateDefault(text, dateFormatOf(control));
}

/** TODAY, and TODAY shifted by a number of days, weeks, months or years: TODAY-1, TODAY+2w. */
const RELATIVE_DAY = /^today\s*(?:([+-])\s*(\d+)\s*([dwmy])?)?$/i;

/**
 * The business-day defaults: BUSINESSDAY for the current business date, LASTBUSINESSDAY and
 * NEXTBUSINESSDAY for the weekday either side of it, and an explicit count for anything further —
 * BUSINESSDAY-3 is three business days back. Weekends only, exactly as ${PREVDATESTAMP} is and for
 * the same reason — see #businessDay.
 *
 * <p>At most four digits, because the count is walked a day at a time: BUSINESSDAY-9999 is
 * thirty-eight years back and costs nothing, and a count of no possible use — BUSINESSDAY-20260915,
 * which is what typing a date after the dash looks like — would otherwise be twenty million trips
 * round #businessDay on every redraw of the canvas, which is every click in the designer. Longer
 * than four digits is not read as a business-day offset at all, so the properties panel says the
 * default cannot be read and the designer can fix it — see #dateDefaultNote.
 */
const BUSINESS_DAY = /^(?:(last|prev|previous|next)\s*)?business\s*(?:day|date)\s*(?:([+-])\s*(\d{1,4}))?$/i;

/** STARTOFMONTH, ENDOFMONTH, STARTOFYEAR, ENDOFYEAR — the edges of the period the run is in. */
const MONTH_EDGE = /^(start|begin|beginning|end)\s*of\s*(month|year)$/i;

/** A year, month and day as the box wants them — or nothing, when they are not a real date. */
function isoDay(year, month, day) {
    const when = new Date(year, month - 1, day);
    // Rejects 31 February rather than showing 3 March: the Date constructor rolls an impossible
    // day forward into the next month, which would put a date on screen nobody wrote.
    if (when.getFullYear() !== year || when.getMonth() !== month - 1 || when.getDate() !== day) return '';
    const pad = n => String(n).padStart(2, '0');
    return year + '-' + pad(month) + '-' + pad(day);
}

/**
 * What a date control opens showing, given what its designer typed as the default: yyyy-MM-dd,
 * or nothing at all when the text is not a date this can read.
 *
 * <p>Placeholders are resolved first, so <code>${DATESTAMP}</code> — and any page variable
 * written in terms of it — is a date rather than a name. Then, in order: yyyy-MM-dd (and the date
 * half of a full timestamp written that way), the yyyyMMdd and yyyyMMddHHmmss the built-ins
 * produce, yyyy/MM/dd, and MM/dd/yyyy.
 *
 * <p>Alongside those: a month written as a name, in either order (15-Sep-2026, Sep 15 2026);
 * TODAY and its shifts; BUSINESSDAY, LASTBUSINESSDAY and NEXTBUSINESSDAY, with a count for
 * anything further back or on; and STARTOFMONTH, ENDOFMONTH, STARTOFYEAR and ENDOFYEAR.
 *
 * <p>That leaves one form nothing in the text can settle: 05/09/2026 is either the ninth of May
 * or the fifth of September and only whoever wrote it knows which. <code>format</code> — the
 * control's own — is what answers it, and a control naming none keeps the month-first reading
 * this had before formats existed. The panel says which way it was read beside the box rather
 * than leaving it to be discovered; a four-digit year first is the unambiguous way to write one,
 * and is read as itself whatever the format says.
 */
function dateDefault(text, format) {
    const raw = resolveTemplate(String(text === undefined || text === null ? '' : text)).trim();
    if (!raw) return '';
    const relative = RELATIVE_DAY.exec(raw);
    if (relative) {
        const by = (relative[1] === '-' ? -1 : 1) * Number(relative[2] || 0);
        const unit = (relative[3] || 'd').toLowerCase();
        const now = new Date();
        const when = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        if (unit === 'd')      when.setDate(when.getDate() + by);
        else if (unit === 'w') when.setDate(when.getDate() + by * 7);
        else if (unit === 'm') when.setMonth(when.getMonth() + by);
        else                   when.setFullYear(when.getFullYear() + by);
        return isoDay(when.getFullYear(), when.getMonth() + 1, when.getDate());
    }
    const business = BUSINESS_DAY.exec(raw);
    if (business) {
        // An explicit count says how many business days and which way round; a bare
        // LASTBUSINESSDAY is one back and NEXTBUSINESSDAY one on, which is already what those
        // names mean everywhere else in the catalog.
        const named = (business[1] || '').toLowerCase();
        const count = business[3] ? Number(business[3]) : (named ? 1 : 0);
        const step  = business[2] ? (business[2] === '-' ? -1 : 1) : (named === 'next' ? 1 : -1);
        const now = new Date();
        let when = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        // BUSINESSDAY on its own is the current business date, and on a Sunday that is the
        // Friday: a page opened over the weekend asking for today's business date means the date
        // the business last had, not one nothing ran on.
        while (!count && (when.getDay() === 0 || when.getDay() === 6)) when.setDate(when.getDate() - 1);
        for (let i = 0; i < count; i++) when = businessDay(when, step);
        return isoDay(when.getFullYear(), when.getMonth() + 1, when.getDate());
    }
    const edge = MONTH_EDGE.exec(raw);
    if (edge) {
        const now = new Date();
        const last = /^end$/i.test(edge[1]);
        if (/^year$/i.test(edge[2])) return isoDay(now.getFullYear(), last ? 12 : 1, last ? 31 : 1);
        const month = now.getMonth() + 1;
        // Day zero of the next month is the last day of this one, so February answers 28 or 29
        // without this having to know which.
        return isoDay(now.getFullYear(), month, last ? new Date(now.getFullYear(), month, 0).getDate() : 1);
    }
    let m = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ][\s\S]*)?$/.exec(raw);
    if (m) return isoDay(+m[1], +m[2], +m[3]);
    m = /^(\d{4})(\d{2})(\d{2})(?:\d{6})?$/.exec(raw);
    if (m) return isoDay(+m[1], +m[2], +m[3]);
    m = /^(\d{4})[\/.](\d{1,2})[\/.](\d{1,2})$/.exec(raw);
    if (m) return isoDay(+m[1], +m[2], +m[3]);
    // A month written as a name settles the order by itself, whichever way round it is written.
    m = /^(\d{1,2})[\s\-\/.]+([A-Za-z]{3,})[\s\-\/.,]+(\d{4})$/.exec(raw);
    if (m && monthNumber(m[2])) return isoDay(+m[3], monthNumber(m[2]), +m[1]);
    m = /^([A-Za-z]{3,})[\s\-\/.]+(\d{1,2})[\s\-\/.,]+(\d{4})$/.exec(raw);
    if (m && monthNumber(m[1])) return isoDay(+m[3], monthNumber(m[1]), +m[2]);
    // Three numbers with the year last, and nothing in them to say which of the other two is the
    // day. The control's own format answers it where it has one — a box that publishes dd/MM/yyyy
    // is handed dd/MM/yyyy — and month first stays the answer for a control naming no format,
    // which is how this read before formats existed.
    m = /^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/.exec(raw);
    if (m) return dayFirst(format) ? isoDay(+m[3], +m[2], +m[1]) : isoDay(+m[3], +m[1], +m[2]);
    return '';
}

let instances = [];         // every instance in the catalog — a page may span apps
// Every use case in the catalog, for one thing only: an instance says which use case it is an
// instance of, and the use case is what declares the variables it takes — their names, their
// types and their defaults. That declaration is what an action's inputs are listed from, so
// picking an instance can offer its variables rather than asking anyone to remember them.
let useCases = [];
let apps = [];               // every app — backs the app picker for a select's ENVIRONMENTS source
let pages = [];
// The static dataset library, by name and with the attributes each one carries, so a control
// sourced from one is wired up by picking a dataset and then picking its columns rather than by
// remembering what they were called. Summaries only — the rows themselves are fetched when the
// page runs, not while it is being designed.
let datasets = [];
// The shared JSONata library — every expression saved centrally, with its text. A transform step
// that names one runs the library's text rather than its own, so this is read at run time as
// well as while designing: an expression corrected in the library is corrected here without
// anyone reopening the page. Re-fetched after a Save as, so an expression saved from this screen
// is immediately one this screen can name.
let jsonataLibrary = [];
// This server's host name and the process id of the JVM behind it, asked for once as the screen
// opens and handed to every run as $MACHINE and $PID. Fetched rather than worked out here
// because a browser can know neither the name of the box it is talking to nor the process on it,
// and that box and that process — the ones the calls actually leave from — are what somebody
// writing $MACHINE or $PID into a request body means.
let machineName = '';
let processId = '';
let page = null;            // the AppPage being edited
let savedPageName = null;   // null while the page has never been saved — decides POST vs PUT
// The page as it stood when it was last opened or saved, as JSON. Whether there is unsaved work
// is answered by comparing against this rather than by a flag set wherever something is edited:
// editing happens in a hundred places here — the canvas, the properties panel, the action and
// transform editors, the variable list, every drag — and a flag that has to be remembered in all
// of them is the flag that will be forgotten in the hundred-and-first, which is the one that
// loses somebody's afternoon. The comparison costs one stringify of a page's worth of JSON, and
// is only ever asked for when something is about to throw the page away. See #isDirty.
let savedFingerprint = '';
let selectedId = null;
// Everything picked out on the canvas when more than one thing is. Laying out a form is moving
// six fields down two rows far more often than it is moving one, and doing that a control at a
// time — six drags, or twelve numbers typed into the panel — is the part of building a page that
// feels like work. A band drawn round them makes it one drag.
//
// Empty or holding one id, the page behaves exactly as it always has: `selectedId` is still the
// control the properties panel is about, and this is the set that travels when it is dragged. The
// two are kept in step by #setSelection, which is the only thing that writes either.
let selectedIds = new Set();
let mode = 'design';
// Which half of the properties panel is showing: whatever is selected, or the page's variables.
// The variables are not a property of any control — they belong to the page and are read by
// every one of its actions — so they have nowhere to live under a selection, and a tab is what
// that difference looks like.
let propsTab = 'props';
// What the Page Actions library is narrowed to. Held here rather than read off its input, the way
// the control list reads off its own: the properties panel is rebuilt from scratch whenever
// anything about the page changes, so the box is not there to be read from between redraws.
// See #filterPageActions.
let pageActionFilter = '';
// What the editor over the page is holding: an action or a transform as a working copy — see
// #openActionEditor — or a copy in the making, which is a set of ticks rather than a draft; see
// #openCopyEditor. Null when nothing is open.
let editor = null;

// Run-mode state, rebuilt from scratch every time the page is previewed.
let values = {};
let errors = [];
// Per-grid rows plus the sort and column filters the operator has applied to them, keyed by the
// grid's own id — a placed control's id, or a generated one for each stacked grid.
let gridState = {};
// What the call behind each grid did, keyed the same way: the outcome its name reports and the
// record its metadata bar folds out. Kept beside the rows rather than in them because a failed
// call has metadata worth reading and no rows at all — see #setGridMeta.
let gridMeta = {};
// Which tab of each tabs control is on screen, keyed by the tabs control's id.
let activeTab = {};
// The tabs a fan-out has added to each tab set this run, keyed by the tab set's id:
// [{ gridId, title, actionId }] in the order the source grid's rows were in. These are not
// controls and never become any — the page holds one tab set, and how many tabs are in it is a
// fact about this run rather than about the design, exactly as a grid's rows are.
let fanTabs = {};
// The error check each fanned-out tab's grid puts its rows through, keyed by that grid's id. A
// fanned-out grid is no control and has no check of its own to carry, so it takes the one written
// on the action that made it — see #rowCheckOf.
let fanRowChecks = {};
// And the display filter each such grid keeps its rows by, for the same reason — see #displayFilterOf.
let fanDisplayFilters = {};
// Static dataset rows fetched during one opening of the page, keyed by dataset name. Two
// controls reading the same dataset ask the server once, and the promise is what is kept, so
// asking at the same moment is the case it was built for. Null outside a run.
let datasetCache = null;
// The options each dropdown is currently showing, keyed by the control's id. They live in the
// DOM — fillOptions writes them straight into the <select> — which is fine while a control is
// drawn once and never drawn again, and is not once a control can be a tab: repainting a tab set
// replaces every pane in it, and a dropdown whose options were only ever in the pane would come
// back empty. So they are kept here as well, and put back after a repaint. See #paintTabs.
let shownOptions = {};
// Where each link control currently points, keyed by the link's id. A link holds no field name, so
// this is where its one value lives: seeded from the link's own URL as the page opens, and
// replaced by whatever an action binds into it.
let linkUrls = {};
// The timer that takes the mark off the control a trigger scrolled to. Held so a second trigger
// cancels the first one's: two marks on a page, one of them left over, says the wrong thing about
// which control has just answered. See #focusControl.
let focusFade = null;
// The slices each pie chart is drawing, keyed by the chart's id, once an action has bound some.
// Absent means nothing has been bound and the chart draws the slices the designer typed in: a
// chart filled from a response and a chart filled by hand are different things, and one that
// came back with no rows has to be able to say so rather than falling back on the design.
let pieData = {};
// What the call behind each chart did, keyed the same way. A chart with no wedges because the
// endpoint answered 503 and one with no wedges because there was nothing to chart look identical
// until something says which happened — the same reason gridMeta exists beside gridState.
let pieMeta = {};
// Both of the above serve every chart: a pie and a pie with grids hold a list of pies, one per value
// column, and a bar chart holds its categories and series. See #paintChart.
//
// What a pie with grids is holding beyond its pies, keyed by its id: the rows it was drawn from and
// the field that names a slice, so a click can filter that pie's grid down to the slice's rows.
let pieGridRows = {};
// The slice last clicked on each pie with grids — { series, key } — so it stays marked.
let chartPick = {};
// The chart currently opened over the page, by control id, or null when none is. Run-mode state
// like everything around it: a reset closes it, and it never exists in the designer.
let zoomedChart = null;
// The rows each chart was last drawn from, keyed by its id — { shape, record, name, call } — so
// the chart can be drawn again from them by a different slice name field without calling anything.
let chartSource = {};
// The slice name field the operator picked on each running chart, which outlives the chart being
// filled again in the same run: a pick is a way of reading these rows, and the next fill is more of them.
let chartKeyPick = {};
// The last thing that ran on its own account, so it can be sent again without the operator
// having to remember which control did it: { controlId } for a button, a link or a select that
// fires on change, or { load: true } for the page's own opening. Held as an id rather than as
// the control, since a reset redraws the page and the object it was drawn from may be replaced.
// Null before anything has run, and again after a reset — see resetRun().
let lastTrigger = null;
// What the last trigger actually put on the wire, in the order its actions were listed:
// { label, at, calls: [{ name, instanceId, inputs, environment, result, error }] }. The whole
// execution record is kept — headers and bodies included — because metaOf() deliberately
// flattens those away and they are precisely what the Technical Details panel exists to show.
// Null until something has run, and again after a reset. See #showTechDetails.
let lastRun = null;
// The Technical Details panel while it is open: null when shut. `secrets` decides whether
// credentials are printed or masked, and is off every time it opens — the document this panel
// hands over is meant to be sent to someone.
let techPanel = null;
let stackedCount = 0;
// One trigger's HTTP calls, keyed by everything the server is told. Two actions that resolve to
// the same instance, environment and inputs share one call: writing the same endpoint twice to
// read its response two ways is the normal way to build one of these pages, and it should not
// cost two round trips. Null outside a trigger, so a stray call is never served from a stale one.
let callCache = null;
// Which instances something in this trigger reads a body from. Settled per instance rather than
// per action, or a metadata action and a grid action on the same endpoint would ask for two
// different responses and defeat the sharing above.
let payloadNeeded = null;
// How many runs are inside the window. The page opening its selects and then its on-load actions
// is one window with two things in it, and the inner one must not close it on the outer one.
let callBatchDepth = 0;
// JSONata is compiled once per expression and evaluated many times — a page run re-evaluates far
// more often than it re-edits. Cleared when a run starts, so an edited expression recompiles.
let compiledTransforms = new Map();
// What ${MACHINE}, ${DATESTAMP} and the rest stand for during the trigger now running, together
// with the page's own ad-hoc variables resolved against them. Rebuilt whenever something sets the
// page off rather than once when it opens, which is what "initialized before the use case is
// executed" has to mean on a page that stays open all afternoon: the date a call carries is the
// date it was made, not the date the tab was opened.
let globals = {};
// Which tab sets the operator has minimized, keyed by the tab set's id. A fact about this run
// rather than about the page — the designer lays out how tall a tab set is, and minimizing it is
// the reader saying they would rather see what is underneath — so it is cleared with every other
// run-mode state when the page opens.
let collapsedTabs = {};
// What each child page has reported this run, keyed by the page control's id: a list of
// { path, label, at, calls: [{ name, ok, error, ... }] }, one entry per trigger the child ran —
// its own and those of any page nested inside it. See #onChildReport.
let childRuns = {};

// ── Loading ──────────────────────────────────────────────────────────────

/**
 * A page is not tied to an app — it routinely reaches across them — so both lists are loaded
 * whole rather than filtered by a selected app.
 */
async function loadCatalog() {
    try {
        [instances, apps, pages, useCases] = await Promise.all([
            AC.listInstances(),
            AC.listApps(),
            AC.api('GET', '/appcatalog/pages'),
            AC.api('GET', '/appcatalog/usecases')
        ]);
        pages = sortPages(pages);
    } catch (e) {
        instances = instances || [];
        apps = apps || [];
        pages = pages || [];
        useCases = useCases || [];
        AC.setStatus('statusBar', 'Failed to load the catalog: ' + e.message, 'error');
    }
    // Asked for separately, and never fatally: the dataset library lives outside the catalog, and
    // a page with no control sourced from one has no business failing to open because it is down.
    // A page that does have one says so where that control is configured.
    try {
        datasets = await AC.api('GET', '/staticdataset');
    } catch (e) {
        datasets = [];
    }
    // And the same for the JSONata library, which is not part of the catalog either. A page with
    // no transform naming a shared expression has no business failing to open because it is
    // down; one that does have such a transform says so where that transform is configured, and
    // refuses to run the step rather than running it against the wrong text.
    await reloadJsonataLibrary();
    // Asked for the same way and just as forgivingly: a page whose $MACHINE comes back empty is
    // a page with one blank value in it, which is not worth refusing to open over.
    try {
        const serverGlobals = await AC.api('GET', '/appcatalog/page-globals') || {};
        machineName = serverGlobals.machine || '';
        processId   = serverGlobals.pid || '';
    } catch (e) {
        machineName = '';
        processId   = '';
    }
    renderPageSelect();
    blankPage();
}

/** The dataset library as options, with what is known about each one beside its name. */
function datasetOptions(selected) {
    const known = datasets.some(d => d.name === selected);
    return '<option value="">— select a dataset —</option>'
        + datasets.map(d => '<option value="' + AC.attr(d.name) + '"' + (d.name === selected ? ' selected' : '') + '>'
            + AC.esc(d.name) + (d.count ? ' (' + d.count + ' rows)' : '') + '</option>').join('')
        // A dataset that has since been deleted, or one the library could not be asked about, is
        // still what this control says it reads — dropping it silently would rewire the page by
        // redrawing it.
        + (selected && !known
            ? '<option value="' + AC.attr(selected) + '" selected>' + AC.esc(selected) + ' (not in the library)</option>'
            : '');
}

/** A dataset's column names, or nothing when it is unknown or has not loaded. */
function datasetColumns(name) {
    const found = datasets.find(d => d.name === name);
    return (found && found.attributes) || [];
}

/**
 * One of a dataset's columns as a dropdown — the point of asking the library for its attributes.
 * Falls back to a text box while the columns are unknown, so a dataset that failed to load, or
 * one added since this tab opened, can still be wired up by typing the name.
 */
function datasetColumnSelect(datasetName, value, onchange, blankLabel) {
    const columns = datasetColumns(datasetName);
    if (!columns.length) {
        return '<input type="text" value="' + AC.attr(value || '') + '" placeholder="column name"'
            + ' oninput="' + onchange + '">';
    }
    return '<select onchange="' + onchange + '">'
        + '<option value="">' + AC.esc(blankLabel || '— none —') + '</option>'
        + columns.map(col => '<option value="' + AC.esc(col) + '"' + (col === value ? ' selected' : '') + '>'
            + AC.esc(col) + '</option>').join('')
        + (value && !columns.includes(value)
            ? '<option value="' + AC.esc(value) + '" selected>' + AC.esc(value) + ' (not a column)</option>' : '')
        + '</select>';
}

/**
 * Fills in the lists a page saved before page-level actions does not carry, so nothing downstream
 * has to keep asking whether they are there.
 */
function hydratePage() {
    page.controls = page.controls || [];
    page.actions = page.actions || [];
    page.onLoadActionIds = page.onLoadActionIds || [];
    page.transforms = page.transforms || [];
    page.variables = page.variables || [];
    // Anything but an explicit false is on, so a page saved before the switch existed opens
    // keeping its detail exactly as it always did. Turning it off is a decision somebody takes.
    page.debug = page.debug !== false;
    page.transforms.forEach(t => {
        t.type = t.type === 'XML2JSON' ? 'XML2JSON' : 'JSONATA';
        // A blank ref is no ref: a page saved before the shared library existed has none at all,
        // and one whose step was switched back to its own expression should read the same way.
        t.jsonataRef = t.type === 'JSONATA' && t.jsonataRef ? String(t.jsonataRef).trim() || null : null;
    });
    page.actions.forEach(hydrateAction);
    page.controls.forEach(c => {
        c.actions = c.actions || [];
        c.actionIds = c.actionIds || [];
        c.assignments = c.assignments || [];
        c.slices = c.slices || [];
        c.sliceColors = c.sliceColors || [];
        // A grid whose rows do nothing carries no row click at all rather than an empty one, so
        // "are these rows clickable" is one question with one answer everywhere it is asked.
        if (c.rowClick) {
            c.rowClick.assignments = c.rowClick.assignments || [];
            c.rowClick.actionIds = c.rowClick.actionIds || [];
        }
        c.actions.forEach(hydrateAction);
        c.trigger = c.trigger === 'CHANGE' ? 'CHANGE' : 'CLICK';
        // Anything but an explicit DESC is ascending, and anything but an explicit ASC or DESC
        // on a dropdown is "leave them as they came" — so a page saved before either setting
        // existed opens showing exactly the order it always did.
        c.sortDirection = c.sortDirection === 'DESC' ? 'DESC' : 'ASC';
        // Likewise the row cap: a page saved before it existed has none, and opens showing
        // every row exactly as it did.
        c.topRows = normalizeTopRows(c.topRows);
        if (c.optionSource) {
            const order = (c.optionSource.sortOrder || '').toUpperCase();
            c.optionSource.sortOrder = order === 'ASC' || order === 'DESC' ? order : 'NONE';
            // And the same for opening on the first option: absent means off, so a page saved
            // before it existed opens on the blank row exactly as it always did.
            c.optionSource.selectFirst = c.optionSource.selectFirst === true;
        }
        c.tabControlIds = c.tabControlIds || [];
        c.panelControlIds = c.panelControlIds || [];
        c.menuOptions = (c.menuOptions || []).map(o => ({
            label: o.label || '', actionIds: o.actionIds || [], color: o.color || ''
        }));
        // Half rows on the way in as well as on the way out, so a page hand-edited to row 0.37
        // opens where the canvas can actually draw it and the drag can reproduce it.
        c.row = Math.max(Math.round((Number(c.row) || 0) * 2) / 2, 0);
        // A line chart with no x column counts the rows, which is what a page saved before the
        // setting existed means by not carrying it.
        c.xField = c.xField || '';
        // And a time series with no offset column reads its whole instant out of its time
        // column, which is what a page saved before the offset existed means by not carrying one.
        c.timeOffsetField = c.timeOffsetField || '';
        c.timeOffsetUnit = TIME_OFFSET_UNITS.some(u => u.id === c.timeOffsetUnit) ? c.timeOffsetUnit : 'SECONDS';
        // Likewise a pie with no slice check judges none of its wedges.
        c.sliceErrorExpression = c.sliceErrorExpression || '';
        c.defaultTabControlId = c.defaultTabControlId || '';
        c.tabsControlId = c.tabsControlId || '';
        c.orientation = c.orientation === 'HORIZONTAL' ? 'HORIZONTAL' : 'VERTICAL';
        c.childPageName = c.childPageName || '';
        // Nothing triggers these, so anything they were told to set or run could never fire.
        // Dropped on load as well as on a type change, so a page written before a hidden field
        // was understood to be untriggerable opens — and saves again — without dead wiring.
        if (TRIGGERLESS_TYPES.includes(c.type)) { c.assignments = []; c.actionIds = []; }
    });
    // A container can only hold controls that are still on the page, and each of them is held by
    // one container and no more. Enforced on load as well as on save so a page edited elsewhere —
    // or one whose grid was deleted by an older build — opens with a strip and a set of boxes
    // that match what is actually there. The claim is shared between tab sets and panels, since
    // "where is this drawn" has to have one answer whichever kind is asking.
    const claimed = new Set();
    page.controls.filter(c => isContainer(c.type)).forEach(t => {
        const kept = childIdsOf(t).filter(id => {
            const child = findControl(id);
            if (!child || !isTabChild(child.type) || claimed.has(id)) return false;
            // Nor a container that, followed down, arrives back at this one: it could not be
            // drawn at any depth. Dropped here rather than only refused on save, because a page
            // carrying one would hang the designer before it could ever be saved again.
            if (wouldNestIntoItself(t.controlId, id)) return false;
            // And never a pie with grids inside the very set it fills — it would add tabs beside
            // itself every run. Refused on save too; dropped here for a page written before
            // either check existed.
            if (child.type === 'piegrid' && child.tabsControlId === t.controlId) return false;
            claimed.add(id);
            return true;
        });
        if (t.type === 'tabs') t.tabControlIds = kept; else t.panelControlIds = kept;
    });
    // A list left behind on a control that is no longer a container would claim its contents off
    // the layout while nothing drew them, so it goes the way any other setting does when its type
    // changes underneath it.
    page.controls.filter(c => !isContainer(c.type)).forEach(c => {
        c.tabControlIds = [];
        c.panelControlIds = [];
    });
    if (page.controls.some(c => c.type !== 'multibutton' && (c.menuOptions || []).length)) {
        page.controls.forEach(c => { if (c.type !== 'multibutton') c.menuOptions = []; });
    }
    tidyDefaultTabs();
}

/**
 * Lets go of any default tab its set no longer holds — a grid dragged out, deleted or moved to
 * another set takes its default-ness with it, rather than the set saving a default it cannot open.
 */
function tidyDefaultTabs() {
    page.controls.forEach(t => {
        if (t.defaultTabControlId && (t.type !== 'tabs' || !(t.tabControlIds || []).includes(t.defaultTabControlId))) {
            t.defaultTabControlId = '';
        }
    });
}

/**
 * An action's chain, as a list, whatever it was saved as. A page written before chains existed
 * carried one transformName; that is the first — and only — step of the chain it always was, so
 * it is folded in and the old key dropped rather than being carried alongside the list where the
 * two could disagree about which one runs.
 */
function hydrateAction(a) {
    a.transformNames = a.transformNames || [];
    if (a.transformName) {
        if (!a.transformNames.length) a.transformNames = [a.transformName];
        delete a.transformName;
    }
    // Every action carries an id now, not just the library's. One written on a control never
    // needed one — nothing named it — but a dependency names exactly that, so pages saved before
    // dependencies existed have theirs minted here. On load rather than on save, so the id an
    // action is picked out by is stable from the moment the page opens and a dependency set on a
    // freshly opened page still resolves after the save that follows it.
    if (!a.actionId) a.actionId = newActionId();
    a.dependsOnActionId = a.dependsOnActionId || '';
    // Fan-out settings a page saved before them does not carry. An action with no row source runs
    // once, exactly as it always did, and the other three are only ever read once one is set.
    a.rowSourceControlId = a.rowSourceControlId || '';
    a.rowOutputMode = a.rowOutputMode === 'TABS' ? 'TABS' : 'ROWS';
    a.rowLabelTemplate = a.rowLabelTemplate || '';
    a.rowErrorExpression = a.rowErrorExpression || '';
    a.displayFilterExpression = a.displayFilterExpression || '';
    a.rowElements = a.rowElements === 'SELECTED' || a.rowElements === 'ALL' ? a.rowElements : '';
    a.rowLimit = a.rowLimit === undefined || a.rowLimit === null ? DEFAULT_ROW_LIMIT : Math.max(+a.rowLimit || 0, 0);
    // Both only mean anything on a fan-out, and both are lists the designer appends to, so an
    // action saved before they existed needs them present rather than absent.
    a.rowFilters = a.rowFilters || [];
    // The rows it keeps out of what it binds. None on an action saved before they existed, which
    // binds everything that came back exactly as it did.
    a.bindFilters = a.bindFilters || [];
    a.rowColumns = a.rowColumns || [];
    a.enrichColumns = a.enrichColumns || [];
    // Further targets the one call's answer is bound into. None on a page saved before them,
    // which binds only the action's own target exactly as it did.
    a.extraBindings = (a.extraBindings || []).map(b => Object.assign(blankBinding(), b,
        { transformNames: (b && b.transformNames) || [], enrichColumns: (b && b.enrichColumns) || [],
          bindFilters: (b && b.bindFilters) || [], pivot: (b && b.pivot) || null }));
    // A group-by before the grid. None on a page saved before it, which shows the rows as bound.
    a.pivot = a.pivot || null;
    // What a comparison holds against what. Only read on a compare action, and absent on every
    // page saved before there was one — so they are defaulted rather than left undefined, which
    // is what the form's selects and number box need to draw at all.
    a.compareEnvironmentA = a.compareEnvironmentA || '';
    a.compareEnvironmentB = a.compareEnvironmentB || '';
    a.compareType = a.compareType === COMPARE_XML ? COMPARE_XML : COMPARE_JSON;
    a.comparePath = a.comparePath || '';
    a.compareTolerancePercent = Math.max(+a.compareTolerancePercent || 0, 0);
    a.compareReport = a.compareReport === REPORT_EVERYTHING ? REPORT_EVERYTHING
                    : a.compareReport === REPORT_TOLERATED ? REPORT_TOLERATED
                    : REPORT_DIFFERENCES;
    // Which dataset a dataset action reads and how it narrows it. Absent on every page saved
    // before there was one, so they are defaulted rather than left undefined — which is what the
    // form's selects and its list of conditions need to draw at all.
    a.datasetName = a.datasetName || '';
    a.datasetFavorite = a.datasetFavorite || '';
    a.datasetFilters = a.datasetFilters || [];
}

/**
 * A further target on an action: everything about reading the response, nothing about making the
 * call. Each field means what the one of the same name on the action means — see bindingsOf.
 */
function blankBinding() {
    return { source: 'PAYLOAD', transformNames: [], targetControlId: '', arrayPath: '', valuePath: '',
             keyField: '', labelField: '', valueField: '', keyValueGrid: false, scalarsOnly: false,
             appendRows: false, enrichColumns: [], bindFilters: [], pivot: null };
}

/**
 * Two names compared the way a reader scans a list: case and accents ignored, and a run of
 * digits read as the number it is, so "page-2" comes before "page-10" rather than after it.
 */
function byName(a, b) {
    return String(a || '').localeCompare(String(b || ''), undefined, { numeric: true, sensitivity: 'base' });
}

/**
 * The catalog's pages in the order every list of them is shown in: alphabetical, by the name the
 * dropdown at the top actually displays. Sorted once as they are loaded rather than in each
 * place that draws them, so the Page dropdown, the pages a link may open and the copy targets are
 * all in the same order and a name is where the eye expects to find it. The server returns them
 * in whatever order it holds them, which is the order they were created — useful to nobody by the
 * time there are thirty.
 */
function sortPages(list) {
    return (list || []).slice().sort((a, b) => byName(a.pageName, b.pageName));
}

function renderPageSelect() {
    AC.fillSelect(document.getElementById('pageSelect'), pages.map(p => p.pageName),
        pages.length ? '— new page —' : 'No pages yet');
    document.getElementById('pageSelect').value = savedPageName || '';
}

async function onPageSelected() {
    const name = document.getElementById('pageSelect').value;
    // Picking another page replaces everything in the designer, so it is asked about first — and
    // before anything is fetched. On a no, the picker goes back to the page that is actually
    // open: leaving it naming a page that was never loaded would be its own kind of lie.
    if (!confirmDiscard(name ? 'Open "' + name + '"' : 'Start a new page')) {
        document.getElementById('pageSelect').value = savedPageName || '';
        return;
    }
    if (!name) { blankPage(); return; }
    try {
        page = await AC.api('GET', '/appcatalog/pages/' + encodeURIComponent(name));
        hydratePage();
        savedPageName = page.pageName;
        selectedId = null;
        clearListFilters();
        setMode('design');
        renderAll();
        // After hydratePage and the render, because both tidy the page as it opens — a page saved
        // before a setting existed is given that setting's default, and renderAll clears a default
        // tab that no longer names a tab. Measuring before that would read every such page as
        // edited the moment it was opened.
        markSaved();
        AC.setStatus('statusBar', '');
    } catch (e) {
        AC.setStatus('statusBar', 'Failed to load page: ' + e.message, 'error');
    }
}

function newPage() {
    if (!confirmDiscard('Start a new page')) return;
    blankPage();
}

/**
 * The designer emptied and handed a page that has never been saved. Split out of {@link #newPage}
 * because the two callers that are not the New button — the catalog finishing loading, and a page
 * that has just been deleted — have nothing to ask about: there is no page left to lose.
 */
function blankPage() {
    page = { pageName: '', title: '', description: '', controls: [], actions: [], onLoadActionIds: [],
             transforms: [], variables: [], debug: true };
    savedPageName = null;
    selectedId = null;
    clearListFilters();
    setMode('design');
    renderAll();
    // A page with nothing on it has nothing to lose, so it does not ask on the way out.
    markSaved();
}

/**
 * A new, unsaved page holding a copy of this one — its controls, actions, transforms and variables
 * as they stand in the designer now, unsaved edits included — under a name no page in the catalog
 * has yet. Nothing is written until Save, so a clone that is not wanted is simply never saved.
 *
 * <p>Control and action ids are kept as they are: they only have to be unique within a page, and
 * keeping them keeps every reference between the controls and actions intact.
 */
function clonePage() {
    if (!savedPageName) return;
    onHeaderInput();
    const source = savedPageName;
    const copy = cloneValue(page);
    const taken = pages.map(p => p.pageName);
    let name = source + '-copy';
    for (let n = 2; taken.includes(name); n++) name = source + '-copy' + n;
    copy.pageName = name;
    copy.title = (page.title || source) + ' (copy)';
    page = copy;
    hydratePage();
    savedPageName = null;
    selectedId = null;
    clearListFilters();
    setMode('design');
    renderPageSelect();
    renderAll();
    // Deliberately not marked saved: a clone exists nowhere but in this tab until Save writes it,
    // which is exactly the state the guard is for. Nothing is lost by cloning either — the copy
    // carries the original's unsaved edits, which is what "as it stands now" above means.
    AC.setStatus('statusBar', 'Cloned "' + source + '" as "' + name + '" — rename it if you like, then Save to create it.', 'ok');
}

// ── Rendering ────────────────────────────────────────────────────────────

function renderAll() {
    document.getElementById('pageName').value = page.pageName || '';
    document.getElementById('pageName').disabled = !!savedPageName;
    document.getElementById('pageNameHint').textContent = savedPageName
        ? 'Fixed once saved — create a new page to use a different name.'
        : 'Unique across the catalog.';
    document.getElementById('pageTitle').value = page.title || '';
    document.getElementById('pageDescription').value = page.description || '';
    document.getElementById('deleteBtn').style.display = savedPageName ? '' : 'none';
    document.getElementById('clonePageBtn').style.display = savedPageName ? '' : 'none';

    const link = document.getElementById('standaloneLink');
    if (savedPageName) {
        link.style.display = '';
        link.href = 'apppage.html?page=' + encodeURIComponent(savedPageName) + '&mode=run';
        link.textContent = 'Open standalone ↗';
    } else {
        link.style.display = 'none';
    }

    tidyDefaultTabs();
    renderPalette();
    renderControlList();
    renderCanvas();
    renderProps();
}

/**
 * The way to the page-level library from anywhere. It has always lived in the properties panel
 * under "nothing selected", which is the right place for it and an unguessable one: the only way
 * in was to know that clicking empty canvas would reveal it. The button says so instead, and
 * carries the counts so the library is visible even while a control is selected.
 */
function showPageActions() {
    propsTab = 'props';
    selectedId = null;
    renderControlList();
    renderCanvas();
    renderProps();
    const panel = document.getElementById('props');
    if (panel) panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

/** Keeps the jump button showing what is in the library, so an empty one is obvious. */
function renderPageActionsButton() {
    const button = document.getElementById('pageActionsBtn');
    if (!button) return;
    const actions = (page.actions || []).length;
    const transforms = (page.transforms || []).length;
    button.textContent = 'Page Actions' + (actions ? ' (' + actions + ')' : '')
        + (transforms ? ' · Transforms (' + transforms + ')' : '');
}

function renderPalette() {
    document.getElementById('palette').innerHTML = PALETTE.map(p =>
        '<div class="palette-item" draggable="true" data-new="' + p.type + '"'
            + ' title="Click to add it under what is already on the layout, or drag it where you want it">' +
            '<span class="glyph">' + AC.esc(p.glyph) + '</span>' + AC.esc(p.label) +
        '</div>'
    ).join('');
    document.querySelectorAll('#palette .palette-item').forEach(el => {
        el.addEventListener('dragstart', e => {
            e.dataTransfer.setData('text/plain', 'new:' + el.dataset.new);
            e.dataTransfer.effectAllowed = 'copy';
        });
        el.addEventListener('click', () => addFromPalette(el.dataset.new));
    });
}

/**
 * The palette's other way in. Dragging is how a control is put somewhere in particular; clicking
 * is how one is added when the answer to "where" is "under the last one" — which is the answer
 * most of the time, and a drag across the panel to say. It matters most below 1200px, where the
 * designer stacks into one column and the palette is no longer beside the canvas at all: adding a
 * control by dragging is a drag down a scrolling page there.
 *
 * <p>A selected panel takes the control instead, the way the panel's own "+ Text" buttons do —
 * with a box open and empty, inside it is nearly always where the next control belongs.
 */
function addFromPalette(type) {
    const selected = findControl(selectedId);
    if (selected && selected.type === 'panel' && isTabChild(type)) {
        addPanelChild(type);
    } else {
        addControl(type, { row: nextLayoutRow(), col: 0 });
    }
    // Added at the bottom of a page taller than the screen, it would otherwise be selected,
    // described in the properties panel, and nowhere to be seen.
    const el = document.querySelector('#canvas .dctl.selected, #canvas .panel-slot.selected');
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

/** The first row under everything on the layout — where a control added by clicking goes. */
function nextLayoutRow() {
    return page.controls.filter(c => !heldBy(c.controlId))
        .reduce((low, c) => Math.max(low, (c.row || 0) + rowSpanOf(c)), 0);
}

/**
 * What is already on the page, as a list beside the layout. Two things keep it readable as a page
 * grows past a handful of controls: the box above it, because typing three letters of a name beats
 * scrolling twenty cards to find it, and cards that carry only what the list is scanned for — a
 * control's name, its type, where it sits, and anything wrong with it. The rest of what a control
 * could say about itself is behind the Details toggle. See #controlList in the stylesheet.
 */
function renderControlList() {
    const list = document.getElementById('controlList');
    // Only offered when there is something to copy and somewhere to copy it to; a button that
    // opens a dialog saying "there is nowhere to put this" is a button worth not having.
    const toPage = document.getElementById('controlsToPageBtn');
    if (toPage) toPage.style.display = page.controls.length && otherPages().length ? '' : 'none';
    // The filter and the toggle are both about a list with something in it; on an empty page they
    // are two more things to read past before placing the first control.
    const search = document.getElementById('controlSearch');
    const detail = document.getElementById('controlDetailBtn');
    if (search) search.style.display = page.controls.length ? '' : 'none';
    if (detail) detail.style.display = page.controls.length ? '' : 'none';
    if (!page.controls.length) {
        list.innerHTML = '<div class="empty-note">Nothing placed yet.</div>';
        return;
    }
    const filter = ((search && search.value) || '').trim().toLowerCase();
    const shown = page.controls.filter(c => matchesControlFilter(c, filter));
    if (!shown.length) {
        list.innerHTML = '<div class="empty-note">No control matches &ldquo;' + AC.esc(filter) + '&rdquo;.</div>';
        return;
    }
    list.innerHTML = shown.map(c => {
        // A grid inside a tab set has no place on the layout, so saying which row it is in
        // would be a lie; the tab set it is in is the answer to "where is this".
        const holder = heldBy(c.controlId);
        return '<div class="record' + (isSelected(c.controlId) ? ' selected' : '') + '" onclick="selectControl(\'' + AC.attr(c.controlId) + '\')">' +
            '<div class="record-name">' + AC.esc(controlTitle(c)) + '</div>' +
            '<div class="record-meta">' +
                '<span class="type-badge ' + AC.esc(c.type) + '">' + AC.esc(c.type) + '</span>' +
                (holder
                    // A tab fills its tab, so its row and column say nothing while it is one; a
                    // control in a panel is laid out inside that panel, so they say everything.
                    ? (holder.type === 'tabs'
                        ? '<span>tab of ' + AC.esc(controlTitle(holder)) + '</span>'
                        : '<span>in ' + AC.esc(controlTitle(holder)) + ' · r' + c.row + ' c' + c.col
                            + ' · ' + c.span + ' col</span>')
                    : '<span>r' + c.row + ' c' + c.col + ' · ' + c.span + ' col'
                        + (rowSpanOf(c) !== 1 ? ' · h' + rowSpanOf(c) : '') + '</span>') +
                (c.type === 'tabs' ? '<span class="record-extra">' + tabChildren(c).length + ' tab'
                    + (tabChildren(c).length === 1 ? '' : 's') + '</span>' : '') +
                (c.type === 'panel' ? '<span class="record-extra">' + containerChildren(c).length + ' control'
                    + (containerChildren(c).length === 1 ? '' : 's') + '</span>' : '') +
                (c.type === 'multibutton' ? '<span class="record-extra">' + (c.menuOptions || []).length + ' entr'
                    + ((c.menuOptions || []).length === 1 ? 'y' : 'ies') + '</span>'
                    + (menuProblems(c).length ? '<span class="badge err">' + menuProblems(c).length
                        + ' unwired</span>' : '') : '') +
                (c.type === 'pie' ? '<span class="record-extra">' + (c.slices || []).length + ' slice'
                    + ((c.slices || []).length === 1 ? '' : 's') + '</span>' : '') +
                ((c.type === 'pie' || c.type === 'piegrid') && (c.sliceErrorExpression || '').trim()
                    ? '<span class="badge record-extra">slice check</span>' : '') +
                (c.type === 'piegrid' ? (findControl(c.tabsControlId)
                    ? '<span class="record-extra">grids → ' + AC.esc(controlTitle(findControl(c.tabsControlId))) + '</span>'
                    : '<span class="badge err">no tab set</span>') : '') +
                (c.type === 'bar' ? '<span class="record-extra">' + (c.orientation === 'HORIZONTAL' ? 'horizontal' : 'vertical') + '</span>' : '') +
                (c.type === 'timeseries' ? (c.timeField
                    ? '<span class="record-extra">time ' + AC.esc(c.timeField)
                        + (timeOffsetOf(c) ? ' + ' + AC.esc(timeOffsetOf(c)) : '') + '</span>'
                    : '<span class="badge err">no time column</span>') : '') +
                // A line chart naming no x column is complete: the line number is its axis.
                (c.type === 'line' ? '<span class="record-extra">x ' + AC.esc(c.xField || 'line number') + '</span>' : '') +
                // A grid that opens already holding something is worth telling apart at a glance
                // from one that is only somewhere an answer lands.
                (c.type === 'grid' && c.datasetName
                    ? '<span class="badge auth record-extra">' + AC.esc(c.datasetName) + '</span>' : '') +
                // A grid nobody will see is the one thing about a grid that cannot be read off
                // the canvas, so the list says it.
                (c.type === 'grid' && c.hideOnRun ? '<span class="badge record-extra">hidden</span>' : '') +
                // A grid that judges its own rows is worth telling apart from one that only
                // shows them: its name carries a verdict when the page runs.
                (c.type === 'grid' && (c.rowErrorExpression || '').trim()
                    ? '<span class="badge err">checks rows</span>' : '') +
                (c.type === 'grid' && (c.displayFilterExpression || '').trim()
                    ? '<span class="badge record-extra">filters rows</span>' : '') +
                (c.type === 'grid' && c.statusCondition
                    ? '<span class="badge record-extra">' + AC.esc(c.statusCondition) + '</span>' : '') +
                (fanOutsOver(c.controlId)
                    ? '<span class="badge record-extra">' + fanOutsOver(c.controlId) + ' fan-out'
                        + (fanOutsOver(c.controlId) === 1 ? '' : 's') + '</span>' : '') +
                (c.mandatory ? '<span class="badge err">required</span>' : '') +
                ((c.assignments || []).length ? '<span class="badge record-extra">sets ' + (c.assignments || []).length + '</span>' : '') +
            '</div>' +
        '</div>';
    }).join('');
}

function controlTitle(c) {
    return c.label || c.fieldName || '(' + c.type + ')';
}

/**
 * Whether a control belongs in the filtered list. Matched against everything that names it rather
 * than the label alone: the field it fills, because that is what the actions and expressions call
 * it by, its type, so "grid" collects every grid on the page, and the container holding it, so a
 * tab set's name gathers its tabs.
 */
function matchesControlFilter(c, filter) {
    if (!filter) return true;
    const holder = heldBy(c.controlId);
    return [c.label, c.fieldName, c.type, holder ? controlTitle(holder) : '']
        .some(text => String(text || '').toLowerCase().includes(filter));
}

/** Concise cards, or every badge a control carries. See #controlList in the stylesheet. */
function toggleControlDetail() {
    const concise = document.getElementById('controlList').classList.toggle('concise');
    const button = document.getElementById('controlDetailBtn');
    if (button) {
        button.textContent = concise ? 'Details' : 'Less';
        button.title = concise
            ? 'Show everything each control has to say about itself'
            : 'Show only a control’s type, where it sits, and anything wrong with it';
    }
}

/**
 * How many actions run once per row of this control. Shown beside a grid in the list because a
 * grid that something fans out over is not an ordinary grid: filtering it changes what the next
 * click calls for, and clearing it stops that action being able to run at all.
 */
function fanOutsOver(controlId) {
    return allActions().filter(a => a.rowSourceControlId === controlId).length;
}

function renderCanvas() {
    const canvas = document.getElementById('canvas');
    // A grid that has been dropped into a tab set is drawn inside that set's chips rather than
    // on the canvas: it has no placement of its own while it lives there, and leaving a second
    // copy of it on the layout would say it did.
    const placed = page.controls.filter(c => !heldBy(c.controlId));
    const rows = Math.max(5, ...placed.map(c => Math.ceil(c.row + rowSpanOf(c)))) + 1;
    canvas.style.gridTemplateRows = 'repeat(' + (rows * 2) + ', ' + HALF_ROW + 'px)';

    canvas.innerHTML = placed.map(c => {
        return '<div class="dctl' + (isSelected(c.controlId) ? ' selected' : '')
            // Marked apart from the single selection so a group reads as one thing being moved
            // rather than as six controls that happen to be lit.
            + (selectedIds.has(c.controlId) ? ' grouped' : '')
            // Dashed here too: a grid that will not be drawn when the page runs should look
            // different on the canvas from one that will, or the layout lies about itself.
            + (!isDrawnOnRun(c) ? ' hidden-ctl' : '')
            + (rowSpanOf(c) <= 0.5 ? ' short' : '') + '" style="' + placement(c) + '"'
            + ' draggable="true" data-id="' + AC.attr(c.controlId) + '"'
            + (c.type === 'tabs' ? ' data-tabs="' + AC.attr(c.controlId) + '"' : '')
            + (c.type === 'panel' ? ' data-panel="' + AC.attr(c.controlId) + '"' : '') + '>'
            + '<div class="dctl-head">'
                + '<span class="type-badge ' + AC.esc(c.type) + '">' + AC.esc(c.type) + '</span>'
                // Underlined where the label is what sets the control off, because that is how it
                // will be drawn when the page runs — see #labelTriggers. A control whose name is
                // the button should look like one on the layout too, or the canvas is hiding the
                // only thing on the page there is to click.
                + '<span class="dctl-label' + (labelTriggers(c) ? ' dctl-link' : '') + '"' + colorStyle(c) + '>'
                    + AC.esc(controlTitle(c)) + (c.mandatory ? ' <span class="req">*</span>' : '') + '</span>'
            + '</div>'
            + designPreview(c)
            + '<div class="resize" data-resize="' + AC.attr(c.controlId) + '"></div>'
            + '<div class="resize-v" data-resize-v="' + AC.attr(c.controlId) + '"></div>'
        + '</div>';
    }).join('');

    canvas.querySelectorAll('.dctl').forEach(el => {
        el.addEventListener('click', e => {
            // Ctrl (or ⌘, or shift) adds and removes; a plain click is the selection, which is
            // also how a group is put down again.
            if (e.ctrlKey || e.metaKey || e.shiftKey) { toggleSelection(el.dataset.id); return; }
            selectControl(el.dataset.id);
        });
        el.addEventListener('dragstart', e => {
            // Dragging one of a group moves the group; dragging anything else is one control
            // moving, and the group is left where it is rather than following the odd one out.
            const group = selectedIds.size > 1 && selectedIds.has(el.dataset.id);
            e.dataTransfer.setData('text/plain', (group ? 'group:' : 'move:') + el.dataset.id);
            e.dataTransfer.effectAllowed = 'move';
        });
    });
    wireTabDropTargets(canvas);
    wirePanelDropTargets(canvas);
    canvas.querySelectorAll('.resize').forEach(el => {
        el.addEventListener('mousedown', e => startResize(e, el.dataset.resize));
        el.addEventListener('dragstart', e => e.preventDefault());
    });
    canvas.querySelectorAll('.resize-v').forEach(el => {
        el.addEventListener('mousedown', e => startResizeHeight(e, el.dataset.resizeV));
        el.addEventListener('dragstart', e => e.preventDefault());
    });
}

function rowSpanOf(c) {
    const value = Number(c.rowSpan);
    return value > 0 ? value : 1;
}

/**
 * How tall a control starts out, in rows.
 *
 * <p>Half a row for everything that is one line of page — a box, a tick, a button, a label, a
 * link. A form of ten fields laid out a whole row each is ten rows of nothing but air between
 * them, and the first thing anybody did with a new control was drag it thinner; starting there
 * makes the common layout the one that needs no dragging, and a control that wants more room
 * still takes it from the bottom edge or the Height field.
 *
 * <p>The exceptions are the controls whose content <em>is</em> height, and which at half a row
 * would show nothing at all: a grid has rows to put on screen, a tab set a strip above them, a
 * pie chart a circle to draw, and a multi-select several options at once — one option high would
 * make it a select that scrolls, which is exactly the control it is not.
 */
const DEFAULT_ROW_SPANS = { grid: 3, tabs: 4, panel: 3, pie: 4, piegrid: 4, bar: 4, timeseries: 5, line: 5, multiselect: 2, page: 6 };
const BASE_ROW_SPAN = 0.5;

function defaultRowSpan(type) {
    return DEFAULT_ROW_SPANS[type] || BASE_ROW_SPAN;
}

/** Row and height are both in half rows; the CSS grid counts in halves, so both double. */
function placement(c) {
    return 'grid-column:' + (c.col + 1) + '/span ' + c.span
         + ';grid-row:' + (Math.round((c.row || 0) * 2) + 1) + '/span ' + Math.round(rowSpanOf(c) * 2);
}

/** Keeps a color property to characters a CSS color value can actually use, dropping anything
 *  that could break out of the style attribute it lands in. */
function cssColor(value) {
    const v = (value || '').trim();
    return /^[#a-zA-Z0-9\s.,%()-]*$/.test(v) ? v : '';
}

/** A `style="color:…"` attribute for a control that named one, or nothing at all. */
function colorStyle(c) {
    const color = cssColor(c.color);
    return color ? ' style="color:' + AC.esc(color) + '"' : '';
}

/** A faint stand-in for what the control will look like once the page runs. */
function designPreview(c) {
    if (c.type === 'button' || c.type === 'link') {
        const count = (c.actions || []).length;
        const goesTo = c.type !== 'link' ? '' : c.linkPageName ? 'page "' + c.linkPageName + '"' : (c.defaultValue || '');
        return '<div class="fake ' + (c.type === 'link' ? 'link' : 'btn') + '">'
            + AC.esc(c.label || (c.type === 'link' ? 'Link' : 'Button'))
            + (goesTo ? ' → ' + AC.esc(goesTo) : '')
            + (count ? ' · ' + count + ' action' + (count > 1 ? 's' : '') : '') + '</div>';
    }
    if (c.type === 'grid') {
        const drills = (c.columnLinks || []).map(l => l.column).filter(Boolean);
        const check = (c.rowErrorExpression || '').trim();
        const shown = (c.displayFilterExpression || '').trim();
        const order = (c.sortColumn || '').trim();
        const top = normalizeTopRows(c.topRows);
        return '<div class="fake grid">grid — '
            + (c.columns && c.columns.length ? AC.esc(c.columns.join(', ')) : 'columns follow the data')
            + (c.leadColumns && c.leadColumns.length ? ' · ' + AC.esc(c.leadColumns.join(', ')) + ' first' : '')
            + (c.hiddenColumns && c.hiddenColumns.length ? ' · ' + AC.esc(c.hiddenColumns.join(', ')) + ' hidden' : '')
            + (c.wrapText ? ' · wrapped' : '')
            + (order ? ' · ' + AC.esc(order) + (c.sortDirection === 'DESC' ? ' ▼' : ' ▲') : '')
            + (top ? ' · top ' + top.toLocaleString() : '')
            + (drills.length ? ' · ' + AC.esc(drills.join(', ')) + ' drills down' : '')
            + (c.rowClick ? ' · rows click through' : '')
            + (findControl(c.sourceGridControlId) ? ' · rows from ' + AC.esc(controlTitle(findControl(c.sourceGridControlId))) : '')
            + (shown ? ' · shows rows where ' + AC.esc(shown) : '')
            + (check ? ' · error if ' + AC.esc(check) : '')
            + (c.statusCondition ? ' · success if ' + AC.esc(c.statusCondition)
                + (c.statusVariable ? ' → ${' + AC.esc(c.statusVariable) + '}' : '') : '') + '</div>';
    }
    if (c.type === 'pie')    return piePreview(c);
    if (c.type === 'piegrid') return pieGridPreview(c);
    if (c.type === 'bar')    return barPreview(c);
    if (isSeries(c.type)) return tsPreview(c);
    if (c.type === 'tabs')   return tabChips(c);
    if (c.type === 'panel')  return panelPreview(c);
    if (c.type === 'multibutton') return menuPreview(c);
    if (c.type === 'page') {
        return '<div class="fake page">' + (c.childPageName
            ? '⧉ runs page "' + AC.esc(c.childPageName) + '" · tallies its actions'
            : 'no page picked yet') + '</div>';
    }
    if (c.type === 'date') {
        const format = dateFormatOf(c);
        const day = dateDefault(c.defaultValue, format);
        const opens = day ? 'opens on ' + formatDay(day, format)
            : (c.defaultValue || '').trim() ? 'default cannot be read' : 'opens empty';
        return '<div class="fake">▦ ' + AC.esc(format) + ' · ' + AC.esc(opens) + '</div>';
    }
    if (c.type === 'label')  return '<div class="fake">' + AC.esc(c.defaultValue || c.label || 'text') + '</div>';
    if (c.type === 'hidden') return '<div class="fake">' + AC.esc(c.fieldName || 'field') + ' = ' + AC.esc(c.defaultValue || '') + '</div>';
    if (isSelect(c.type)) {
        const source = c.optionSource || {};
        const from = source.mode === 'STATIC' ? (source.staticOptions || []).length + ' fixed options'
                   : source.mode === 'USECASE' ? (source.appUseCaseInstanceId || 'no instance')
                   : source.mode === 'ENVIRONMENTS' ? (source.appName || 'no app') + ' environments'
                   : source.mode === 'DATASET' ? (source.datasetName || 'no dataset')
                   : 'empty';
        const order = (source.sortOrder || 'NONE').toUpperCase();
        return '<div class="fake">' + (c.type === 'multiselect' ? '≡ ' : '▾ ') + AC.esc(from)
            + (order === 'ASC' ? ' · sorted ▲' : order === 'DESC' ? ' · sorted ▼' : '')
            + (source.selectFirst ? ' · opens on first' : '')
            + (c.type === 'multiselect' ? ' · several' : '') + '</div>';
    }
    // A text area is drawn filling its control, the way a grid is: it is the one field whose
    // height is a design decision rather than a given, so the layout has to show the height that
    // was decided.
    if (c.type === 'textarea') {
        return '<div class="fake area">' + AC.esc(c.defaultValue || c.placeholder || 'text area') + '</div>';
    }
    return '<div class="fake">' + AC.esc(c.defaultValue || c.placeholder || c.type) + '</div>';
}

// ── Tabs ─────────────────────────────────────────────────────────────────
// A tabs control holds other controls instead of data of its own — any of them but another tab
// set and a hidden field, see NOT_TAB_CHILD_TYPES. They are untouched by it: same ids, same
// columns, same field names, and an action still names the control rather than the tab set it
// happens to be in — so putting one into a tab set is purely a move of where it is drawn, and
// taking it out again puts it back on the layout with everything aimed at it still aimed at it.

/** The grids of one tab set, in tab order, skipping any the page no longer holds. */
function tabChildren(tabs) {
    return containerChildren(tabs);
}

/** The chips a tabs control shows in design mode — one per grid, draggable, each with a way out. */
function tabChips(c) {
    const children = tabChildren(c);
    if (!children.length) {
        return '<div class="fake tabs">drag any control here — each becomes a tab</div>';
    }
    return '<div class="fake tabs"><div class="tab-chips">'
        + children.map(child =>
            '<span class="tab-chip' + (isDefaultTab(c, child.controlId) ? ' default' : '') + '" draggable="true" data-chip="' + AC.attr(child.controlId) + '"'
            + (isDefaultTab(c, child.controlId) ? ' title="Opens on this tab"' : '') + '>'
            + (isDefaultTab(c, child.controlId) ? '★ ' : '') + AC.esc(controlTitle(child))
            // A chip that is itself a strip says so and how many are in it, or a group of four
            // would look exactly like a grid on the layout.
            + (child.type === 'tabs' ? ' <span class="chip-group">▾ ' + tabChildren(child).length + '</span>' : '')
            + '<span class="chip-x" data-chip-out="' + AC.attr(child.controlId) + '" title="Take out of the tabs">×</span>'
            + '</span>').join('')
        + '</div></div>';
}

/**
 * Makes every tabs control on the canvas take a dropped grid, and its chips draggable so the
 * tabs can be put in the order they should be read in. The drop is stopped from reaching the
 * canvas underneath — the canvas would read the same drop as "move this control to row 3".
 */
function wireTabDropTargets(canvas) {
    canvas.querySelectorAll('.dctl[data-tabs]').forEach(el => {
        el.addEventListener('dragover', e => {
            if (!droppableIntoTabs(e)) return;
            e.preventDefault();
            e.stopPropagation();
            el.classList.add('tabs-drop');
        });
        el.addEventListener('dragleave', () => el.classList.remove('tabs-drop'));
        el.addEventListener('drop', e => {
            el.classList.remove('tabs-drop');
            if (!droppableIntoTabs(e)) return;
            e.preventDefault();
            e.stopPropagation();
            dropIntoTabs(el.dataset.tabs, e);
        });
    });
    canvas.querySelectorAll('.tab-chip').forEach(el => {
        el.addEventListener('dragstart', e => {
            e.stopPropagation();
            e.dataTransfer.setData('text/plain', 'chip:' + el.dataset.chip);
            e.dataTransfer.effectAllowed = 'move';
        });
        // The chip sits on the control, so a click on it would otherwise select the tab set
        // when what was wanted was the grid it names.
        el.addEventListener('click', e => { e.stopPropagation(); selectControl(el.dataset.chip); });
    });
    canvas.querySelectorAll('[data-chip-out]').forEach(el => {
        el.addEventListener('click', e => {
            e.stopPropagation();
            detachFromTabs(el.dataset.chipOut, null);
        });
    });
}

/**
 * Whether what is being dragged is something a tab set can hold. Read off the drag types rather
 * than the payload: dragover is not allowed to see the data, so a plain move of a grid and a
 * move of a text box look the same here and both are accepted — the drop itself, which can read
 * the payload, is where a non-grid is turned away.
 */
function droppableIntoTabs(e) {
    return [...e.dataTransfer.types].includes('text/plain');
}

function dropIntoTabs(tabsId, e) {
    const payload = e.dataTransfer.getData('text/plain') || '';
    const tabs = findControl(tabsId);
    if (!tabs) return;

    let gridId = null;
    if (payload.startsWith('new:')) {
        const type = payload.slice(4);
        if (!isTabChild(type)) {
            AC.setStatus('statusBar', 'A tab set holds any control except a hidden field, which is not on '
                + 'screen for a tab to show.', 'error');
            return;
        }
        // Placed where the tab set is, so taking it back out later leaves it somewhere sensible.
        gridId = addControl(type, { row: tabs.row, col: tabs.col }, true);
    } else if (payload.startsWith('move:') || payload.startsWith('chip:')) {
        const control = findControl(payload.slice(5));
        if (!control) return;
        if (!isTabChild(control.type)) {
            AC.setStatus('statusBar', 'A tab set cannot hold a ' + control.type + ': a hidden field is not on '
                + 'screen, so a tab holding one would be a name over nothing.', 'error');
            return;
        }
        // A set may hold another set — that is how a long strip is grouped — but not one that
        // leads back to it, which could not be drawn at any depth.
        if (wouldNestIntoItself(tabs.controlId, control.controlId)) {
            AC.setStatus('statusBar', '"' + controlTitle(control) + '" already holds "' + controlTitle(tabs)
                + '", so putting it inside would make a set hold itself — which has no depth at which it stops '
                + 'being drawn. Take one out of the other first.', 'error');
            return;
        }
        // A pie with grids fills a tab set with a grid per pie. Dropped into that same set it
        // would be adding tabs beside itself on every run, and the operator would lose sight of
        // the chart to look at what it had just produced.
        if (control.type === 'piegrid' && control.tabsControlId === tabs.controlId) {
            AC.setStatus('statusBar', '"' + controlTitle(control) + '" already puts its own grids into this tab set, '
                + 'so it cannot also be a tab of it — point it at another set first.', 'error');
            return;
        }
        gridId = control.controlId;
    } else {
        return;
    }

    // Where it lands is read off the strip as it is currently drawn, which still holds the chip
    // being dragged. Taking that chip out shifts everything after it down one, so a tab dragged
    // rightwards within its own set would come to rest one place short of where it was let go.
    let at = dropIndex(e, tabsId);
    const from = tabs.tabControlIds.indexOf(gridId);
    if (from !== -1 && from < at) at--;

    // Taken out of wherever it was first, so moving a grid between two sets — or out of a panel,
    // or within one set — is one move rather than a grid that is briefly in both.
    releaseFromContainers(gridId);
    // A tab set draws what it holds, so a grid that was hidden stops being hidden as it becomes a
    // tab — a hidden tab is a name over nothing, and the save refuses the pair. Said out loud
    // rather than quietly unticked, since it is a setting the page asked for going away.
    const moving = findControl(gridId);
    const wasHidden = !!(moving && moving.hideOnRun);
    if (wasHidden) moving.hideOnRun = false;

    tabs.tabControlIds.splice(at, 0, gridId);
    selectedId = gridId;
    AC.setStatus('statusBar', wasHidden
        ? '"' + controlTitle(moving) + '" is no longer hidden: a tab set draws the grids it holds, so a hidden '
            + 'one would leave a tab with nothing behind it.'
        : '', wasHidden ? 'ok' : '');
    renderAll();
}

/** Where in the strip the pointer let go — before the first chip whose middle it is left of. */
function dropIndex(e, tabsId) {
    const host = document.querySelector('.dctl[data-tabs="' + CSS.escape(tabsId) + '"]');
    const chips = host ? [...host.querySelectorAll('.tab-chip')] : [];
    for (let i = 0; i < chips.length; i++) {
        const rect = chips[i].getBoundingClientRect();
        if (e.clientY < rect.bottom && e.clientX < rect.left + rect.width / 2) return i;
    }
    return chips.length;
}

/**
 * Takes a grid back out of its tab set and onto the layout. It kept its row and column the whole
 * time it was a tab, so with no cell named it simply reappears where it was; dragging it out
 * onto the canvas names one and it lands there instead.
 */
function detachFromTabs(gridId, cell) {
    const grid = findControl(gridId);
    if (!grid) return;
    releaseFromContainers(gridId);
    if (cell) {
        grid.row = cell.row;
        grid.col = Math.min(cell.col, COLUMNS - grid.span);
    }
    selectedId = gridId;
    renderAll();
}

/** Takes a control out of whichever container was holding it, so a move is one move rather than
 *  a control that is briefly in two places. */
function releaseFromContainers(controlId) {
    page.controls.forEach(c => {
        if (!isContainer(c.type)) return;
        if (c.type === 'tabs')  c.tabControlIds   = (c.tabControlIds || []).filter(id => id !== controlId);
        if (c.type === 'panel') c.panelControlIds = (c.panelControlIds || []).filter(id => id !== controlId);
    });
}

// ── Panels ───────────────────────────────────────────────────────────────
// A control that holds other controls and shows all of them at once, which is the one thing that
// tells it apart from a tab set. It is a box with a name on it: the three fields that make up an
// address, the two dates and a button that make up a range, the half dozen switches that make up
// "how shall this run" — gathered so they read as one thing on the page and move as one thing in
// the designer.
//
// What is inside is laid out exactly as it is on the page: the same twenty-four columns, the same
// half rows, the same drag and the same four boxes in the properties panel. The panel is simply
// the grid those numbers are counted on, so a field at row 0 column 0 is at the top left of the
// box rather than of the page. That is why the canvas draws a panel as a small layout rather than
// as a row of chips the way a tab set does: a tab set's order is all there is to see, and a
// panel's arrangement is the whole of what was designed.
//
// Everything else a control has stays exactly as it was. Same id, same field name, same actions
// aimed at it — putting a control into a panel moves where it is drawn and nothing else, and
// taking it out again puts it back on the layout with all of it still pointing where it pointed.

/** How many half-rows tall the mini layout inside a panel chip is drawn. */
const PANEL_PREVIEW_HALF_ROW = 13;

/** The controls inside a panel, drawn where they will actually be — a small copy of the layout. */
function panelPreview(c) {
    const children = containerChildren(c);
    if (!children.length) {
        return '<div class="fake panel">drag any control in here — it is laid out inside the box</div>';
    }
    // Measured from the topmost control rather than from row 0, so a panel whose contents start
    // at row 4 — because that is where they were on the page before being gathered up — draws
    // them at the top of the box instead of below four rows of nothing.
    const top = Math.min(...children.map(k => k.row || 0));
    const rows = Math.max(1, Math.ceil(Math.max(...children.map(k => (k.row || 0) - top + rowSpanOf(k))) * 2));
    return '<div class="fake panel"><div class="panel-mini" style="grid-template-rows:repeat('
        + rows + ',' + PANEL_PREVIEW_HALF_ROW + 'px)">'
        + children.map(k =>
            '<span class="panel-slot' + (k.controlId === selectedId ? ' selected' : '') + '" draggable="true"'
            + ' data-slot="' + AC.attr(k.controlId) + '"'
            + ' style="grid-column:' + (k.col + 1) + '/span ' + k.span
                + ';grid-row:' + (Math.round(((k.row || 0) - top) * 2) + 1)
                + '/span ' + Math.round(rowSpanOf(k) * 2) + '"'
            + ' title="' + AC.attr(controlTitle(k) + ' — ' + k.type + ', row ' + k.row + ' column ' + k.col) + '">'
            + '<span class="slot-name">' + AC.esc(controlTitle(k)) + '</span>'
            + '<span class="slot-x" data-slot-out="' + AC.attr(k.controlId) + '" title="Take out of the panel">×</span>'
            + '</span>').join('')
        + '</div></div>';
}

/**
 * Makes every panel on the canvas take a dropped control, and the controls already in it
 * draggable so they can be moved about inside the box. The drop is stopped from reaching the
 * canvas underneath, which would otherwise read the same drop as "move this to row 3 of the page".
 */
function wirePanelDropTargets(canvas) {
    canvas.querySelectorAll('.dctl[data-panel]').forEach(el => {
        el.addEventListener('dragover', e => {
            if (!droppableIntoTabs(e)) return;
            e.preventDefault();
            e.stopPropagation();
            el.classList.add('tabs-drop');
        });
        el.addEventListener('dragleave', () => el.classList.remove('tabs-drop'));
        el.addEventListener('drop', e => {
            el.classList.remove('tabs-drop');
            if (!droppableIntoTabs(e)) return;
            e.preventDefault();
            e.stopPropagation();
            dropIntoPanel(el.dataset.panel, e);
        });
    });
    canvas.querySelectorAll('.panel-slot').forEach(el => {
        el.addEventListener('dragstart', e => {
            e.stopPropagation();
            e.dataTransfer.setData('text/plain', 'chip:' + el.dataset.slot);
            e.dataTransfer.effectAllowed = 'move';
        });
        // The slot sits on the panel, so a click on it would otherwise select the panel when
        // what was wanted was the control it names.
        el.addEventListener('click', e => { e.stopPropagation(); selectControl(el.dataset.slot); });
    });
    canvas.querySelectorAll('[data-slot-out]').forEach(el => {
        el.addEventListener('click', e => {
            e.stopPropagation();
            detachFromTabs(el.dataset.slotOut, null);
        });
    });
}

/**
 * A control dropped into a panel: it joins the panel's contents and is placed at the cell it was
 * let go over, read against the panel's own mini layout rather than against the page.
 */
function dropIntoPanel(panelId, e) {
    const payload = e.dataTransfer.getData('text/plain') || '';
    const panel = findControl(panelId);
    if (!panel || panel.type !== 'panel') return;

    let childId = null;
    if (payload.startsWith('new:')) {
        const type = payload.slice(4);
        if (!isTabChild(type)) {
            AC.setStatus('statusBar', 'A panel holds any control except a hidden field, which is not on screen '
                + 'for a box to have a place in.', 'error');
            return;
        }
        childId = addControl(type, { row: 0, col: 0 }, true);
    } else if (payload.startsWith('move:') || payload.startsWith('chip:')) {
        const control = findControl(payload.slice(5));
        if (!control) return;
        if (control.controlId === panelId) return;
        if (!isTabChild(control.type)) {
            AC.setStatus('statusBar', 'A panel cannot hold a ' + control.type + ': a hidden field is not on '
                + 'screen, so a place in a box for one would be a gap in the layout.', 'error');
            return;
        }
        if (wouldNestIntoItself(panel.controlId, control.controlId)) {
            AC.setStatus('statusBar', '"' + controlTitle(control) + '" already holds "' + controlTitle(panel)
                + '", so putting it inside would make a container hold itself — which has no depth at which it '
                + 'stops being drawn. Take one out of the other first.', 'error');
            return;
        }
        childId = control.controlId;
    } else {
        return;
    }

    const child = findControl(childId);
    // Where in the box it was let go, measured off the mini layout as it is drawn — see
    // #panelPreview for why the drawing is offset from the topmost control rather than from row 0.
    const cell = panelCellAt(panelId, e);
    releaseFromContainers(childId);
    childIdsOf(panel).push(childId);
    if (cell) {
        child.row = cell.row;
        child.col = Math.min(cell.col, COLUMNS - child.span);
    }
    // A panel draws everything it holds, so a grid that was hidden stops being hidden as it goes
    // in — for the reason a tab of a tab set does: the save refuses the pair, and it is a setting
    // the page asked for going away, so it is said out loud rather than quietly unticked.
    const wasHidden = !!child.hideOnRun;
    child.hideOnRun = false;
    selectedId = childId;
    AC.setStatus('statusBar', wasHidden
        ? '"' + controlTitle(child) + '" is no longer hidden: a panel draws what it holds.'
        : '', wasHidden ? 'ok' : '');
    renderAll();
}

/** The cell inside a panel's mini layout that the pointer is over, in the panel's own numbers. */
function panelCellAt(panelId, e) {
    const mini = document.querySelector('.dctl[data-panel="' + CSS.escape(panelId) + '"] .panel-mini');
    const panel = findControl(panelId);
    if (!mini || !panel) return null;
    const rect = mini.getBoundingClientRect();
    if (!rect.width || !rect.height) return null;
    const col = Math.floor((e.clientX - rect.left) / (rect.width / COLUMNS));
    const row = Math.floor((e.clientY - rect.top) / PANEL_PREVIEW_HALF_ROW) / 2;
    // Added back to whatever the drawing was offset by, so the cell is in the same numbers the
    // properties panel shows rather than in the preview's own.
    const children = containerChildren(panel).filter(k => k.controlId !== panel.controlId);
    const top = children.length ? Math.min(...children.map(k => k.row || 0)) : 0;
    return { row: Math.max(0, row) + top, col: Math.min(Math.max(0, col), COLUMNS - 1) };
}

/** The panel's own properties: what it holds, and the way out for each of them. */
function panelProps(c) {
    const children = containerChildren(c);
    let html = '<div class="props-section"><div class="props-title"><span>In This Panel</span>'
        + '<button class="tool-btn" onclick="addPanelChild(\'text\')">+ Text</button>'
        + '<button class="tool-btn" onclick="addPanelChild(\'select\')">+ Select</button>'
        + '<button class="tool-btn" onclick="addPanelChild(\'button\')">+ Button</button>'
        + '<button class="tool-btn" onclick="addPanelChild(\'grid\')">+ Grid</button>'
        + '<button class="tool-btn" onclick="addPanelChild(\'panel\')" title="A box inside this one">+ Panel</button></div>'
        + '<span class="hint">Drag any control onto the panel on the canvas and it is laid out inside the box, '
        + 'at the place it was let go. Row, column and width are then places in the panel rather than on the '
        + 'page — the panel is the grid they are counted on — so a panel gathers a form into one thing that '
        + 'moves, and a tab holding one is a tab whose content is that form.</span>';
    if (!children.length) {
        html += '<div class="empty-note">Nothing in this panel yet.</div>';
        return html + '</div>';
    }
    html += children.map(k =>
        '<div class="row-item"><span class="copy-name" style="flex:1;min-width:0;cursor:pointer"'
        + ' onclick="selectControl(\'' + AC.attr(k.controlId) + '\')">' + AC.esc(controlTitle(k)) + '</span>'
        + '<span class="type-badge ' + AC.esc(k.type) + '">' + AC.esc(k.type) + '</span>'
        + '<span class="hint" style="margin:0">r' + k.row + ' c' + k.col + '</span>'
        + '<button class="icon-btn" onclick="detachFromTabs(\'' + AC.attr(k.controlId) + '\', null)"'
        + ' title="Take out of the panel and back onto the layout">×</button></div>').join('');
    html += '<span class="hint">Row and column are places inside the box, so two controls at rows 0 and 0.5 '
        + 'of the same column sit one under the other within it.</span>';
    // What the box answers for as a whole, where it holds anything that has a verdict. The same
    // reading a tab of a group gets, said in the designer so it is clear the panel will carry it.
    const grids = containerGrids(c.controlId).length;
    if (grids) {
        html += '<span class="hint">' + grids + ' grid' + (grids === 1 ? '' : 's')
            + ' in here, however deep. When the page runs, the panel\'s own name carries the worst of what '
            + 'they came back as — and so does the tab holding it, if it is in one.</span>';
    }
    return html + '</div>';
}

/**
 * A control created straight into the selected panel, laid out under whatever is already in
 * there — the usual next thing after adding a panel, and the one move dragging does not make
 * easy while the box is still empty.
 */
function addPanelChild(type) {
    const panel = findControl(selectedId);
    if (!panel || panel.type !== 'panel' || !isTabChild(type)) return;
    const inside = containerChildren(panel);
    // Under the lowest thing in the box, in its first column: a new field goes where a form's
    // next field goes, rather than on top of the one added before it.
    const row = inside.reduce((low, k) => Math.max(low, (k.row || 0) + rowSpanOf(k)), 0);
    const childId = addControl(type, { row: row, col: 0 }, true);
    childIdsOf(panel).push(childId);
    selectedId = childId;
    renderAll();
}

// ── Multi-buttons ────────────────────────────────────────────────────────
// One button that opens a list, each entry of which runs its own page action.
//
// A page offering six things to do with the same inputs used to be six buttons across a row, and
// a row of six buttons is a row nobody can scan, taking the width the grid underneath wanted. A
// multi-button folds that row into one: the click opens the menu, and which entry was picked is
// what decides which call goes out.
//
// So the control itself runs nothing — it is in TRIGGERLESS_TYPES for exactly that reason — and
// every entry is a trigger in its own right. The actions are named out of the page's shared
// library rather than written on the entry, which is what lets one action be an entry here, a
// button elsewhere and a column's drill-down as well, configured once.

/** The entries a page would save: one that has been given neither a name nor an action is a row
 *  the designer added and has not filled in yet, not an entry. */
function menuOptionsOf(c) {
    return (c.menuOptions || []).filter(o => (o.label || '').trim() || (o.actionIds || []).length);
}

/** The entries that could not do their job: no name to read, or no action to run. */
function menuProblems(c) {
    if (c.type !== 'multibutton') return [];
    return menuOptionsOf(c).filter(o => !(o.label || '').trim() || !(o.actionIds || []).length);
}

function menuPreview(c) {
    const entries = menuOptionsOf(c);
    const bad = menuProblems(c).length;
    return '<div class="fake btn">' + AC.esc(c.label || 'Menu') + ' ▾'
        + (entries.length ? ' · ' + entries.length + ' entr' + (entries.length === 1 ? 'y' : 'ies') : ' · no entries')
        + (bad ? ' · ' + bad + ' unwired' : '') + '</div>';
}

/**
 * The menu as the designer edits it: a name and the actions behind it, per entry.
 *
 * <p>The actions are attached as chips rather than picked from one dropdown, for the reason a
 * grid's clickable column attaches them that way: usually an entry runs one action, which is the
 * whole idea, but nothing about "this entry, that call" says it must be exactly one — and an
 * entry that sends two is the same entry, so it should not need a different kind of control to
 * say so.
 */
function menuProps(c) {
    const library = page.actions || [];
    const entries = c.menuOptions || [];
    let html = '<div class="props-section"><div class="props-title"><span>Menu Entries</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="addMenuOption()">+ Add</button></span></div>'
        + '<span class="hint">Clicking the button opens this list; picking an entry runs what is attached to it. '
        + 'The button itself runs nothing, which is why it has no actions of its own — each entry is its own '
        + 'trigger.</span>';

    if (!library.length) {
        html += '<div class="empty-note">This page has no actions yet. Add one under Page Actions first — a menu '
             + 'entry runs a page action, so that is what there is to attach.</div>';
    }
    if (!entries.length) {
        html += '<div class="empty-note">No entries yet. A multi-button with an empty menu is a button that does '
             + 'nothing when it is clicked, and the save refuses one.</div>';
        return html + '</div>';
    }

    html += entries.map((o, i) => {
        const chosen = (o.actionIds || []).filter(id => actionNamed(id));
        const gone = (o.actionIds || []).filter(id => !actionNamed(id));
        return '<div class="menu-entry">'
            + '<div class="row-item">'
                + '<span class="action-num">' + (i + 1) + '</span>'
                + '<input type="text" placeholder="What the entry is called" value="' + AC.attr(o.label || '') + '"'
                    + ' oninput="setMenuOption(' + i + ', \'label\', this.value)" style="flex:1;min-width:0">'
                + '<input type="text" placeholder="colour" value="' + AC.attr(o.color || '') + '"'
                    + ' title="CSS colour for this entry on the menu — a destructive one in red, say"'
                    + ' oninput="setMenuOption(' + i + ', \'color\', this.value)" style="width:72px">'
                + (i > 0 ? '<button class="tool-btn" onclick="moveMenuOption(' + i + ', -1)" title="Earlier">↑</button>' : '')
                + (i < entries.length - 1 ? '<button class="tool-btn" onclick="moveMenuOption(' + i + ', 1)" title="Later">↓</button>' : '')
                + '<button class="icon-btn" onclick="removeMenuOption(' + i + ')" title="Remove this entry">×</button>'
            + '</div>'
            + '<div class="menu-actions">'
                + chosen.map(id => '<span class="tab-chip">' + AC.esc(actionNamed(id).actionLabel || id)
                    + '<span class="chip-x" onclick="detachMenuAction(' + i + ', \'' + AC.attr(id) + '\')"'
                    + ' title="Take this action off the entry">×</span></span>').join('')
                // Said rather than dropped: an action the library no longer holds is what this
                // entry says it runs, and quietly removing it would rewire the page by drawing it.
                + gone.map(id => '<span class="tab-chip err-chip" title="No action on this page answers to '
                    + AC.attr(id) + '">' + AC.esc(id) + ' (gone)'
                    + '<span class="chip-x" onclick="detachMenuAction(' + i + ', \'' + AC.attr(id) + '\')">×</span></span>').join('')
                + (library.some(a => !(o.actionIds || []).includes(a.actionId))
                    ? '<select onchange="attachMenuAction(' + i + ', this.value)">'
                        + '<option value="">' + (chosen.length ? '+ another action' : '— pick the action it runs —') + '</option>'
                        + library.filter(a => !(o.actionIds || []).includes(a.actionId))
                            .map(a => '<option value="' + AC.attr(a.actionId) + '">'
                                + AC.esc(a.actionLabel || a.actionId) + '</option>').join('')
                        + '</select>'
                    : '')
            + '</div>'
            + (!(o.label || '').trim() ? '<span class="hint err-hint">This entry has no name — there would be '
                    + 'nothing on the menu to click.</span>' : '')
            + ((o.actionIds || []).length ? '' : '<span class="hint err-hint">This entry runs nothing — attach an '
                    + 'action or take the entry off.</span>')
            + '</div>';
    }).join('');
    return html + '</div>';
}

function addMenuOption() {
    const c = findControl(selectedId);
    if (!c) return;
    c.menuOptions = c.menuOptions || [];
    c.menuOptions.push({ label: '', actionIds: [], color: '' });
    renderProps();
    renderCanvas();
    renderControlList();
}

function setMenuOption(index, name, value) {
    const c = findControl(selectedId);
    const option = c && (c.menuOptions || [])[index];
    if (!option) return;
    option[name] = value;
    // The panel is not redrawn, which would take the caret out of the box being typed into; the
    // canvas and the list only count the entries, so they keep up on their own.
    renderCanvas();
    renderControlList();
}

function moveMenuOption(index, delta) {
    const c = findControl(selectedId);
    const list = c && c.menuOptions;
    const to = index + delta;
    if (!list || to < 0 || to >= list.length) return;
    [list[index], list[to]] = [list[to], list[index]];
    renderProps();
}

function removeMenuOption(index) {
    const c = findControl(selectedId);
    if (!c || !c.menuOptions) return;
    c.menuOptions.splice(index, 1);
    renderAll();
}

function attachMenuAction(index, actionId) {
    const c = findControl(selectedId);
    const option = c && (c.menuOptions || [])[index];
    if (!option || !actionId) return;
    option.actionIds = (option.actionIds || []).concat([actionId])
        .filter((id, i, all) => all.indexOf(id) === i);
    renderAll();
}

function detachMenuAction(index, actionId) {
    const c = findControl(selectedId);
    const option = c && (c.menuOptions || [])[index];
    if (!option) return;
    option.actionIds = (option.actionIds || []).filter(id => id !== actionId);
    renderAll();
}

// ── Pie chart ────────────────────────────────────────────────────────────
// The one control that draws itself out of a list the designer types rather than out of a call.
// Each row is a name and a number; the chart is those numbers as shares of their total. Nothing
// triggers it and nothing binds into it — see TRIGGERLESS_TYPES — so what is in the list is the
// whole of what is on screen, and the designer sees the finished chart while typing it.

/**
 * A slice's value as a number, or NaN — a blank box is not a zero, it is an unfinished row.
 *
 * <p>Matched against plainly-a-number before it is converted rather than left to Number(), which
 * also takes '0x10' and 'Infinity'. The same shape the save checks, so what the chart draws and
 * what the server will store are the same set of values rather than two overlapping ones —
 * mirrors AppCatalogService#SLICE_NUMBER.
 */
const SLICE_NUMBER = /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/;

function sliceNumber(value) {
    const text = String(value === undefined || value === null ? '' : value).trim();
    if (!SLICE_NUMBER.test(text)) return NaN;
    const number = Number(text);
    return Number.isFinite(number) ? number : NaN;
}

/** The slices a page saves: a row nothing has been typed into is not a slice yet. */
function slicesOf(control) {
    return (control.slices || []).filter(s => (s.key || '').trim() || String(s.value || '').trim());
}

/**
 * A pie's list split into what can be drawn and what cannot: a slice needs a name, and a value
 * that is a number and not below zero, since a pie shows each slice's share of the whole and a
 * share below zero has no wedge. Saving the page refuses the rest — but the page is previewed
 * from what is in the designer rather than from what was last saved, so the chart works out for
 * itself what it cannot draw and says so beside the wedges it could.
 */
function pieSlices(c) {
    const slices = [];
    const problems = [];
    (c.slices || []).forEach(s => {
        const key = (s.key || '').trim();
        const value = sliceNumber(s.value);
        const shown = String(s.value === undefined || s.value === null ? '' : s.value).trim();
        if (!key) { problems.push(s.missing || 'a slice with no name'); return; }
        if (!Number.isFinite(value) || value < 0) {
            problems.push('"' + key + '" = ' + (shown || '(blank)'));
            return;
        }
        // Where the slice came from, when it came from a row: a pie with grids filters its grid
        // to that row when a slice has no name field to filter by. See #pickSlice.
        slices.push({ key: key, value: value, row: s.row });
    });
    return { slices: slices, problems: problems };
}

/**
 * Every pie a chart is drawing, each split into what can be drawn and what cannot. One pie until
 * an action binds several value columns, when each column is a pie of its own; until anything is
 * bound, a plain pie draws the slices typed into it and a pie with grids draws nothing.
 */
function drawnPies(c) {
    const bound = pieData[c.controlId];
    const series = bound || [{ title: '', slices: c.type === 'pie' ? (c.slices || []) : [] }];
    return series.map(s => Object.assign({ title: s.title || '' }, pieSlices({ slices: s.slices })));
}

/** The expression a pie judges its wedges by, or blank — only a pie has wedges to judge. */
function sliceCheckOf(c) {
    return c && (c.type === 'pie' || c.type === 'piegrid') ? (c.sliceErrorExpression || '').trim() : '';
}

/**
 * One wedge as something the check can read: its own two fields, over the row it came from where
 * it came from exactly one.
 *
 * <p>NAME and VALUE last, so they win over columns of those names rather than being shadowed by
 * them — they are the two the expression is guaranteed to have, and a response that happens to
 * carry a "name" column must not quietly change what NAME means.
 */
function sliceCheckRow(c, slice) {
    const source = chartSource[c.controlId];
    const rows = source && source.shape ? source.shape.rows : null;
    // `slice.row` is the row's place in the response — see #sliceOf. A tallied wedge stands for
    // many rows and carries none, so it is judged on NAME and VALUE alone.
    const row = rows && Number.isInteger(slice.row) && isObjectRow(rows[slice.row]) ? rows[slice.row] : null;
    return Object.assign({}, row, { NAME: slice.key, VALUE: slice.value });
}

/**
 * Every wedge the chart is drawing, put through its error check once.
 *
 * <p>Computed where it is needed rather than held beside the chart the way a grid's is. A grid
 * checks tens of thousands of rows and is filtered and re-sorted constantly, so it pays to do it
 * once as the rows land; a pie has a handful of wedges and is redrawn only when something
 * actually changed it, so working it out on the spot keeps the answer true of what is on screen
 * with nothing to invalidate.
 *
 * @return {on, total, errorCount, bad, checkError} — `bad` is a set of wedge positions per pie,
 *         in the order #drawnPies returned them.
 */
function pieChecked(c, pies) {
    const expression = sliceCheckOf(c);
    const off = { on: false, total: 0, errorCount: 0, bad: [], checkError: '' };
    if (!expression) return off;
    const broken = error => ({ on: true, total: 0, errorCount: 0, bad: [], checkError: error });
    const parsed = parseRowCheck(expression);
    if (!parsed.ok) return broken(parsed.error);
    const bad = [];
    let total = 0;
    let errorCount = 0;
    for (const pie of pies) {
        const flagged = new Set();
        for (let i = 0; i < pie.slices.length; i++) {
            total++;
            let wrong;
            // A check that throws on a wedge is a broken check rather than a bad wedge, so the
            // chart says so once instead of marking every wedge after it — the same reading
            // #applyRowCheck makes of a grid.
            try { wrong = evalRowCheck(parsed.node, sliceCheckRow(c, pie.slices[i])); }
            catch (e) { return broken(e.message || String(e)); }
            if (wrong) { flagged.add(i); errorCount++; }
        }
        bad.push(flagged);
    }
    return { on: true, total: total, errorCount: errorCount, bad: bad, checkError: '' };
}

/** The chart's wedges judged, found from its id — nothing for a chart that is not a pie. */
function chartCheck(controlId) {
    const c = findControl(controlId);
    if (!c || !sliceCheckOf(c)) return { on: false, total: 0, errorCount: 0, bad: [], checkError: '' };
    return pieChecked(c, drawnPies(c));
}

/**
 * What happened to the chart, all told — the reading {@link #gridOutcome} makes of a grid, made
 * of a pie: FAILURE when the call behind it failed, ERROR when the call worked but a wedge
 * matches the chart's error check, SUCCESS when neither.
 *
 * <p>A failed call outranks the check, as it does on a grid: it leaves no wedges, and none is not
 * the same as none wrong. A chart nothing has called yet still answers where it has a check and
 * something to check — the slices typed into the designer are a real pie, and saying nothing
 * about them would leave the designer unable to see the check working before wiring the call up.
 */
function chartOutcome(controlId) {
    const info = pieMeta[controlId];
    if (info && info.status !== 'SUCCESS') return 'FAILURE';
    const check = chartCheck(controlId);
    if (check.on && (check.checkError || check.errorCount > 0)) return 'ERROR';
    if (info) return 'SUCCESS';
    return check.on && check.total ? 'SUCCESS' : '';
}

/** The tally a checked pie shows beside its name: how many wedges are wrong, and how many are not. */
function chartCheckBadge(controlId) {
    const check = chartCheck(controlId);
    if (!check.on) return { text: '', cls: 'grid-check', title: '' };
    if (check.checkError) {
        return { text: 'check failed', cls: 'grid-check err',
                 title: 'This chart\'s slice check could not be run: ' + check.checkError };
    }
    if (!check.total) return { text: '', cls: 'grid-check', title: '' };
    const bad = check.errorCount;
    return {
        text: bad.toLocaleString() + ' ERROR / ' + (check.total - bad).toLocaleString() + ' SUCCESS',
        cls: 'grid-check ' + (bad ? 'err' : 'ok'),
        title: bad ? bad.toLocaleString() + ' of ' + check.total.toLocaleString()
                + ' slices match this chart\'s error check.'
            : 'No slice matches this chart\'s error check.'
    };
}

/**
 * How tall a control's own box is in pixels, off the same half-row geometry placement() lays it
 * out with. A chart has to be given a size: the run canvas sizes its rows to their content, so a
 * square asking for the height of its row would be asking the row it is itself sizing.
 */
/** Roughly what a tab set spends on its strip and the gap under it, in pixels. */
const TAB_CHROME = 38;

function controlHeight(c, depth) {
    // A control laid out as a tab has no height of its own on the page — it fills its tab set,
    // less the strip above it — so that is what it is measured against. Its own height has been
    // sitting unused since it was dropped in there, and is what it goes back to when it is taken
    // out, exactly as its row and column are.
    //
    // Followed all the way up rather than one level, because a set may itself be a tab of
    // another: a grid two strips deep has two strips above it, and measuring it against the
    // height its own tab set was given on the layout — a number nothing has read since that set
    // was dropped into a tab — would size it to a box it is not in. The cap is only there because
    // this walks a chain the designer is in the middle of editing.
    const holder = depth > 20 ? null : tabsHolding(c.controlId);
    if (holder) return Math.max(controlHeight(holder, (depth || 0) + 1) - TAB_CHROME, 60);
    const halves = Math.round(rowSpanOf(c) * 2);
    return halves * HALF_ROW + (halves - 1) * ROW_GAP;
}

/** A wedge's colour when the chart names none: the palette, taken in order and wrapped round. */
const PALETTE_AT = (slice, i) => PIE_COLORS[i % PIE_COLORS.length];

/**
 * What colour each wedge of this chart is drawn in: the colour the designer named for that slice,
 * and the palette in order for every slice they did not.
 *
 * <p>Named by slice rather than by position, which is the whole of what makes it worth having. A
 * chart filled from a call has slices whose names are known long before the numbers are — a
 * status pie is going to have an UP wedge and a DOWN wedge whatever today's run returns — and
 * green and red say something about those two that third-colour-round-the-circle never will.
 * Position would also move: a response that came back with DOWN first would otherwise recolour
 * the entire chart, and the operator reading it every morning would have to check the legend
 * before believing any of it.
 *
 * <p>Matched regardless of case, as every other field name on this page is, and a colour the
 * style attribute could not safely hold is ignored rather than written — the save refuses one,
 * so this is only ever reached while it is still being typed.
 */
function chartColorAt(c) {
    const named = new Map();
    ((c && c.sliceColors) || []).forEach(entry => {
        const key = String((entry && entry.key) || '').trim().toLowerCase();
        const color = cssColor((entry && entry.value) || '').trim();
        if (key && color) named.set(key, color);
    });
    if (!named.size) return PALETTE_AT;
    return (slice, i) => named.get(String((slice && slice.key) || '').trim().toLowerCase())
        || PIE_COLORS[i % PIE_COLORS.length];
}

/** One wedge, from angle to angle, drawn out of the centre. Angles run clockwise from 12 o'clock. */
function piePath(cx, cy, r, from, to) {
    const round = n => Math.round(n * 100) / 100;
    const x1 = round(cx + r * Math.cos(from)), y1 = round(cy + r * Math.sin(from));
    const x2 = round(cx + r * Math.cos(to)),   y2 = round(cy + r * Math.sin(to));
    return 'M' + cx + ' ' + cy + ' L' + x1 + ' ' + y1
        + ' A' + r + ' ' + r + ' 0 ' + (to - from > Math.PI ? 1 : 0) + ' 1 ' + x2 + ' ' + y2 + ' Z';
}

/**
 * The circle itself, at a given pixel size. A slice of no size is skipped rather than drawn as a
 * hairline — it is in the legend, where its zero can be read, and a wedge of nothing on the
 * circle is only something to mistake for a rounding error.
 */
/**
 * @param series when the wedges can be clicked, which pie of the chart this is — each wedge then
 *               carries its place so a click can say which slice it was
 * @param picked the name of the slice currently picked, whose neighbours are dimmed
 * @param colorAt what colour a slice is drawn in — see {@link #chartColorAt}; the palette by default
 */
function pieSvg(slices, size, series, picked, colorAt) {
    const paint = colorAt || PALETTE_AT;
    const total = slices.reduce((sum, s) => sum + s.value, 0);
    const cx = size / 2, cy = size / 2, r = size / 2 - 1;
    let angle = -Math.PI / 2;
    const wedges = slices.map((s, i) => {
        const color = paint(s, i);
        const sweep = total > 0 ? (s.value / total) * Math.PI * 2 : 0;
        if (sweep <= 0) return '';
        const from = angle;
        angle += sweep;
        const dim = picked !== undefined && picked !== s.key;
        const extra = series === undefined ? '' : ' data-series="' + series + '" data-slice="' + i + '"';
        const tip = '<title>' + AC.esc(s.key) + ': ' + AC.esc(sliceText(s.value))
            + (total > 0 ? ' (' + Math.round(s.value / total * 1000) / 10 + '%)' : '') + '</title>';
        // One slice holding the whole total has no two distinct edges for an arc to run
        // between, and a path whose ends meet draws nothing at all — so it is a circle.
        if (sweep >= Math.PI * 2 - 1e-9) {
            return '<circle class="wedge' + (dim ? ' dim' : '') + '" cx="' + cx + '" cy="' + cy + '" r="' + r
                + '" fill="' + color + '"' + extra + '>' + tip + '</circle>';
        }
        return '<path' + (dim ? ' class="dim"' : '') + ' d="' + piePath(cx, cy, r, from, angle) + '" fill="' + color + '"'
            + extra + '>' + tip + '</path>';
    }).join('');
    // Nothing to draw still draws the circle, empty: a chart that vanished and a chart of
    // nothing look the same otherwise, and only one of them is what the page meant.
    return '<svg class="pie-svg" width="' + size + '" height="' + size + '"'
        + ' viewBox="0 0 ' + size + ' ' + size + '" role="img" aria-label="Pie chart">'
        + (wedges || '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="#f4f5f7"></circle>')
        + '</svg>';
}

/** A number as the legend shows it — grouped, and without a tail of floating-point noise. */
function sliceText(value) {
    return value.toLocaleString(undefined, { maximumFractionDigits: 3 });
}

/** The names beside the circle: colour, name, value and the share of the total it works out as. */
function pieLegend(slices, problems, series, picked, colorAt, bad) {
    const paint = colorAt || PALETTE_AT;
    const total = slices.reduce((sum, s) => sum + s.value, 0);
    const wrong = i => !!bad && bad.has(i);
    return '<div class="pie-legend">'
        + slices.map((s, i) =>
            '<div class="pie-key' + (picked === s.key ? ' picked' : '') + (wrong(i) ? ' pie-bad-key' : '') + '"'
                + (wrong(i) ? ' title="This slice matches the chart\'s error check."' : '')
                + (series === undefined ? '' : ' data-series="' + series + '" data-slice="' + i + '" role="button" tabindex="0"')
                + '>'
                + '<span class="pie-swatch" style="background:' + AC.esc(paint(s, i)) + '"></span>'
                + '<span class="pie-name" title="' + AC.attr(s.key) + '">' + AC.esc(s.key) + '</span>'
                + '<span class="pie-value">' + AC.esc(sliceText(s.value))
                    + (total > 0 ? ' · ' + Math.round(s.value / total * 1000) / 10 + '%' : '')
                + '</span>'
            + '</div>').join('')
        + (slices.length ? '<div class="pie-total">Total ' + AC.esc(sliceText(total))
            + ' across ' + slices.length + (slices.length === 1 ? ' slice' : ' slices') + '</div>' : '')
        + (problems.length ? '<div class="pie-bad">Not charted: ' + AC.esc(problems.join(', '))
            + ' — a slice needs a name and a number.</div>' : '')
        + '</div>';
}

/** The chart as the designer sees it on the canvas: the real circle, small, and what is in it. */
function piePreview(c) {
    const drawn = pieSlices(c);
    const count = drawn.slices.length;
    const size = Math.min(Math.max(controlHeight(c) - 30, 26), 84);
    return '<div class="fake pie">' + pieSvg(drawn.slices, size, undefined, undefined, chartColorAt(c))
        + '<span>' + (count ? count + (count === 1 ? ' slice' : ' slices')
                + ' · ' + AC.esc(sliceText(drawn.slices.reduce((sum, s) => sum + s.value, 0)))
            : 'no slices yet')
        + (drawn.problems.length ? ' · ' + drawn.problems.length + ' not charted' : '')
        + (c.sourceGridControlId ? ' · ' + chartFedBy(c) : '')
        // Said on the layout the way a grid's own check is, so what the chart judges is readable
        // without selecting it.
        + (sliceCheckOf(c) ? ' · error if ' + AC.esc(sliceCheckOf(c)) : '') + '</span></div>';
}

/**
 * A chart's name, with the outcome of the call that last filled it beside it — and the button
 * that opens it bigger.
 *
 * @param zoom set when this is the big copy, which has its own heading and needs no second way
 *             to open what is already open
 */
function chartLabel(c, zoom) {
    const outcome = chartOutcome(c.controlId);
    // And, where the chart checks its wedges, how many of them passed — the grid's own pairing of
    // "did the call work" with "is what came back right", beside a chart's name for the same reason.
    const check = chartCheckBadge(c.controlId);
    const label = '<label' + colorStyle(c) + '>' + AC.esc(c.label || '')
        + ' <span class="grid-status' + (outcome ? ' ' + GRID_OUTCOME_CLASS[outcome] : '') + '">'
        + AC.esc(outcome.toLowerCase()) + '</span>'
        + (check.text ? ' <span class="' + check.cls + '" title="' + AC.attr(check.title) + '">'
            + AC.esc(check.text) + '</span>' : '') + '</label>';
    const picker = chartKeyPicker(c);
    // A chart is laid out to sit beside everything else on the page, which is the right size for
    // glancing at and the wrong one for reading twenty wedges off. The button is always there —
    // not only once something has filled the chart — because "I cannot read this" is a thing the
    // operator knows before anyone asks them whether the call worked.
    const zoomBtn = zoom ? '' : '<button type="button" class="chart-zoom-btn"'
        + ' onclick="openChartZoom(\'' + AC.attr(c.controlId) + '\')"'
        + ' title="Open this chart bigger">&#10530; Expand</button>';
    // On the label's own line, so the chart below keeps the height it was measured for.
    return (picker || zoomBtn) ? '<div class="chart-head">' + label + picker + zoomBtn + '</div>' : label;
}

/** Where a chart's marks would have been, when the call that was to fill it failed — or nothing. */
function chartFailure(c) {
    const info = pieMeta[c.controlId];
    if (!info || info.status !== 'FAILED') return '';
    return '<div class="pie-fail">' + AC.esc(info.error || 'The call behind this chart failed.')
        + techButton(info) + '</div>';
}

/**
 * The chart as it runs: sized off the control's own height, with the legend beside it.
 *
 * <p>Drawn from whatever an action last bound into it, or — until something has — from the
 * slices typed into the designer. The two are kept apart rather than merged, so a call that came
 * back with nothing to chart empties the circle instead of falling back on numbers that were
 * only ever there to lay the page out with.
 *
 * @param zoom {height} when this is the copy opened over the page, which is drawn to the room the
 *             overlay has rather than to the room the control was given on the layout
 */
function pieRun(c, zoom) {
    const box = zoom ? zoom.height : controlHeight(c);
    const bound = pieData[c.controlId];
    const label = chartLabel(c, zoom);
    const failed = chartFailure(c);
    if (failed) return label + failed;
    const pies = drawnPies(c);
    if (pies.every(p => !p.slices.length && !p.problems.length)) {
        return label + '<div class="grid-empty">'
            + (bound ? 'The call returned nothing to chart.'
                : c.type === 'piegrid' ? 'Nothing charted yet — an action aimed at this chart fills it, and its grids.'
                : 'This pie chart has no slices yet.')
            + '</div>';
    }
    // A pie answers a click where there are rows behind its wedges and somewhere to show them:
    // a pie with grids, once it has grids to open, and a plain pie drawn from a grid, which
    // narrows that grid. Slices typed into the designer are not clickable — there are no rows
    // under them to go and look at.
    const clickable = !!bound && (c.type === 'piegrid' || !!sliceFilterTarget(c));
    const pick = clickable ? chartPick[c.controlId] : null;
    const colorAt = chartColorAt(c);
    // The wedges this chart's own error check calls wrong, marked in the legend where their names
    // are — the pie's answer to a grid drawing a bad row in red.
    const checked = pieChecked(c, pies);
    const piece = (p, s, size) => pieSvg(p.slices, size, clickable ? s : undefined,
            pick && pick.series === s ? pick.key : undefined, colorAt)
        + pieLegend(p.slices, p.problems, clickable ? s : undefined,
            pick && pick.series === s ? pick.key : undefined, colorAt, checked.bad[s]);
    const cls = 'pie-chart' + (clickable ? ' pie-click' : '');
    // The label takes a line above the chart, so the circle gets what is left of the box.
    if (pies.length === 1) {
        const size = Math.max(box - 26, 60);
        return label + '<div class="' + cls + '" style="height:' + size + 'px">' + piece(pies[0], 0, size) + '</div>';
    }
    // One pie per value column, each titled with the column it is sized by. Several side by side
    // get a share of the room rather than all of it, or the first would fill the overlay alone.
    const size = Math.max((zoom ? Math.round(box / Math.min(pies.length, 2)) : box) - 26 - 18, 60);
    return label + '<div class="pie-set' + (clickable ? ' pie-click' : '') + '">' + pies.map((p, s) =>
        '<div class="pie-series"><div class="pie-series-title">' + AC.esc(p.title) + '</div>'
            + '<div class="pie-chart" style="height:' + size + 'px">' + piece(p, s, size) + '</div></div>').join('')
        + '</div>';
}

/** What fills a chart, as its canvas preview says it: the grid it draws itself from, or an action. */
function chartFedBy(c) {
    const grid = c.sourceGridControlId && findControl(c.sourceGridControlId);
    return grid ? 'drawn from <b>' + AC.esc(controlTitle(grid)) + '</b>' : 'filled by an action';
}

/** A pie with grids on the canvas: the circle, and where its grids go. */
function pieGridPreview(c) {
    const tabs = findControl(c.tabsControlId);
    const size = Math.min(Math.max(controlHeight(c) - 30, 26), 84);
    // A pie with grids has nothing typed into it to draw, so the canvas shows a stand-in circle.
    // Named slices are what it is made of where the chart has any: three wedges in the colours
    // this chart actually gives them beats three wedges in the palette's first three.
    const named = (c.sliceColors || []).filter(s => (s.key || '').trim()).slice(0, 4);
    const sample = named.length
        ? named.map((s, i) => ({ key: s.key.trim(), value: named.length - i }))
        : [{ key: 'a', value: 3 }, { key: 'b', value: 2 }, { key: 'c', value: 1 }];
    return '<div class="fake pie">' + pieSvg(sample, size, undefined, undefined, chartColorAt(c))
        + '<span>' + (tabs ? 'a grid per pie, in tabs of <b>' + AC.esc(controlTitle(tabs)) + '</b>'
            : '<span style="color:#bf2600">pick a tab set for its grids</span>')
        + ' · ' + chartFedBy(c)
        + (sliceCheckOf(c) ? ' · error if ' + AC.esc(sliceCheckOf(c)) : '') + '</span></div>';
}

/**
 * A pie with grids in the properties panel: the tab set its grids go into, which it has to have,
 * and what the chart does once the page runs.
 */
function pieGridProps(c) {
    // Not the set this chart is itself a tab of: it would be adding tabs beside itself on every
    // run. The drop refuses the same pairing from the other direction — see #dropIntoTabs.
    const tabSets = page.controls.filter(t => t.type === 'tabs' && !(t.tabControlIds || []).includes(c.controlId));
    return '<div class="props-section"><div class="props-title"><span>Pie + Grids</span></div>'
        + field('Grids Go Into', '<select onchange="setProp(\'tabsControlId\', this.value); renderProps()">'
            + '<option value="">— pick a tab set —</option>'
            + tabSets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === c.tabsControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + '</option>').join('')
            + '</select>',
            tabSets.length
                ? 'Required. Each pie this chart draws gets a grid of its own as a tab in this set, holding every row the '
                    + 'chart was drawn from.'
                : 'Required, and there is no tab set on this page yet — drag a <b>Tabs</b> control onto the layout first.')
        + '<span class="hint">Fill it the way a pie chart is filled: aim an action at it, and name the field that '
        + 'names each slice and the value column(s) that size them — several, comma-separated, draw a pie each. '
        + 'When the page runs, clicking a slice (or its row in the legend) opens that pie' + Q + 's grid, '
        + 'filtered to the rows the slice stands for; clicking it again takes the filter off. The clickable rows '
        + 'and columns below apply to every grid this chart opens.</span></div>'
        + rowClickProps(c)
        + columnLinkProps(c);
}

// ── Bar chart ────────────────────────────────────────────────────────────
// Rows an action binds, grouped by a category column: one bar per category, sized by how many rows
// fall in it or by the sum of a value column across them. Several value columns draw a group of
// bars per category, one per column, with a legend saying which is which.

/** A bar chart's model as the canvas shows it before anything fills it. */
const SAMPLE_BARS = { categories: ['A', 'B', 'C'], series: [{ name: 'count', values: [5, 3, 4] }], problems: [], counting: true };

/** A tick value rounded up to a clean number, so the longest bar is measured against 10, 50, 200… */
function niceMax(value) {
    if (!(value > 0)) return 1;
    const power = Math.pow(10, Math.floor(Math.log10(value)));
    const step = [1, 2, 2.5, 5, 10].find(m => m * power >= value);
    return step * power;
}

/** The bars themselves, vertical or horizontal, sized against the largest value on the chart. */
function barPlot(model, horizontal, height) {
    const max = niceMax(Math.max(0, ...model.series.map(s => Math.max(0, ...s.values.filter(Number.isFinite)))));
    const color = i => PIE_COLORS[i % PIE_COLORS.length];
    const tip = (cat, s, v) => AC.attr(cat + (model.series.length > 1 ? ' · ' + s.name : '') + ': ' + sliceText(v));
    const cats = model.categories.map((cat, k) => {
        const bars = model.series.map((s, i) => {
            const v = s.values[k];
            if (!Number.isFinite(v)) return '';
            const share = v / max * 100;
            return horizontal
                ? '<div class="bar-col"><div class="bar" style="width:' + (share * 0.85) + '%;background:' + color(i)
                    + '" title="' + tip(cat, s, v) + '"></div><span class="bar-val">' + AC.esc(sliceText(v)) + '</span></div>'
                : '<div class="bar-col"><div class="bar" style="height:' + share + '%;background:' + color(i)
                    + '" title="' + tip(cat, s, v) + '"><span class="bar-val">' + AC.esc(sliceText(v)) + '</span></div></div>';
        }).join('');
        return '<div class="bar-cat"' + (horizontal ? '' : ' style="flex-basis:' + Math.max(34, model.series.length * 18) + 'px"') + '>'
            + (horizontal ? '<div class="bar-name" title="' + AC.attr(cat) + '">' + AC.esc(cat) + '</div><div class="bar-area">' + bars + '</div>'
                : '<div class="bar-area">' + bars + '</div><div class="bar-name" title="' + AC.attr(cat) + '">' + AC.esc(cat) + '</div>')
            + '</div>';
    }).join('');
    return '<div class="bar-plot ' + (horizontal ? 'horizontal' : 'vertical') + '" style="height:' + height + 'px">' + cats + '</div>';
}

/** A bar chart's legend: always there for several series, and naming the measure for one. */
function barLegend(model) {
    if (model.series.length === 1) {
        return '<div class="bar-legend"><span>' + AC.esc(model.counting
            ? 'Count of rows per category' : 'Sum of ' + model.series[0].name + ' per category') + '</span></div>';
    }
    return '<div class="bar-legend">' + model.series.map((s, i) =>
        '<span><span class="bar-swatch" style="background:' + PIE_COLORS[i % PIE_COLORS.length] + '"></span>'
            + AC.esc(s.name) + '</span>').join('') + '</div>';
}

/** @param zoom as on {@link #pieRun}: the room the overlay has, when this is the big copy. */
function barRun(c, zoom) {
    const box = zoom ? zoom.height : controlHeight(c);
    const model = pieData[c.controlId];
    const label = chartLabel(c, zoom);
    const failed = chartFailure(c);
    if (failed) return label + failed;
    if (!model || !model.categories.length) {
        return label + '<div class="grid-empty">' + (model ? 'The call returned nothing to chart.'
                : 'Nothing charted yet — an action aimed at this chart fills it.')
            + (model && model.problems.length ? ' Not charted: ' + AC.esc(model.problems.join(', ')) : '') + '</div>';
    }
    const problems = model.problems.length
        ? '<div class="bar-bad">Not charted: ' + AC.esc(model.problems.join(', ')) + ' — a value has to be a number, not below zero.</div>' : '';
    const height = Math.max(box - 26 - 18 - (problems ? 16 : 0), 60);
    return label + '<div class="bar-chart">' + barLegend(model) + problems
        + barPlot(model, c.orientation === 'HORIZONTAL', height) + '</div>';
}

function barPreview(c) {
    const horizontal = c.orientation === 'HORIZONTAL';
    const height = Math.min(Math.max(controlHeight(c) - 30, 26), 84);
    return '<div class="fake bar-fake" style="flex-direction:column;align-items:stretch">'
        + barPlot(SAMPLE_BARS, horizontal, height - 16).replace(/<span class="bar-val">[^<]*<\/span>/g, '')
        + '<span>' + (horizontal ? 'horizontal' : 'vertical') + ' · ' + chartFedBy(c) + '</span></div>';
}

/**
 * Where a chart draws itself from a grid: which grid, and which of its columns name and size the
 * marks. The same two fields an action aimed at the chart asks for, because it is the same reading
 * of rows — only the rows come off a grid that has just finished filling instead of off a response.
 */
function chartGridSourceProps(c) {
    const grids = page.controls.filter(t => t.type === 'grid');
    // chartFieldsEditor reads and writes keyField/valueField; these are the control's own names for them.
    const fields = { keyField: c.gridKeyField || '', valueField: c.gridValueField || '' };
    const set = (name, expr) => 'setProp(\'' + (name === 'keyField' ? 'gridKeyField' : 'gridValueField') + '\', ' + expr + ')';
    return '<div class="props-section"><div class="props-title"><span>Data From Grid</span></div>'
        + field('Grid', '<select onchange="setProp(\'sourceGridControlId\', this.value); renderProps()">'
            + '<option value="">— none: filled by an action —</option>'
            + grids.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === c.sourceGridControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + '</option>').join('')
            + '</select>',
            grids.length
                ? 'Optional. Every time this grid has finished filling — an action, a static dataset, a reset — its rows '
                    + '(after its display filter) are charted here, replacing whatever the chart showed.'
                : 'There is no grid on this page to draw from yet.')
        + (c.sourceGridControlId ? chartFieldsEditor(c.type, fields, set) : '')
        // Worth saying here rather than only being discovered: it is the one thing drawing a
        // plain pie from a grid gains beyond the wedges, and the reason to prefer it over
        // aiming a second action at the chart.
        + (c.sourceGridControlId && c.type === 'pie'
            ? '<span class=hint>While the page runs, clicking a wedge narrows that grid to the rows behind it — '
                + 'clicking the same wedge again puts every row back. So "forty are rejected" and "which forty" are '
                + 'one click apart.</span>'
            : '')
        + '</div>';
}

function barProps(c) {
    return '<div class="props-section"><div class="props-title"><span>Bar Chart</span></div>'
        + field('Orientation', '<select onchange="setProp(\'orientation\', this.value); renderProps()">'
            + '<option value="VERTICAL"' + (c.orientation === 'HORIZONTAL' ? '' : ' selected') + '>Vertical — columns</option>'
            + '<option value="HORIZONTAL"' + (c.orientation === 'HORIZONTAL' ? ' selected' : '') + '>Horizontal — bars</option>'
            + '</select>')
        + '<span class="hint">Aim an action at this chart and say, on the action, where the rows are (the array path), '
        + 'which column is the <b>category</b> — a bar per distinct value — and which is the <b>value</b>. Leave the value '
        + 'blank to count the rows in each category; name a column to add it up per category instead, or name several, '
        + 'comma-separated, for a group of bars per category. Column names match regardless of case.</span></div>';
}

// ── Time series chart ────────────────────────────────────────────────────
// Rows read along a time axis: each row's instant comes out of the chart's time column, the rows
// are grouped into buckets of time, and each bucket is a point — how many rows fell in it, or its
// value column(s) combined. A line column splits the rows into a line per distinct value. While the
// page runs the operator filters the rows by any column and zooms — wheel, drag across the plot,
// the buttons, or a from/to — and with the bucket on Auto a zoom re-buckets, so the closer the
// look the finer the detail. Mirrors AppPageControl#TIME_BUCKETS / #TIME_AGGREGATES.

const TIME_BUCKETS = [
    { id: 'AUTO',            label: 'Auto' },
    { id: 'NONE',            label: 'None — each instant' },
    { id: 'SECOND',          label: '1 second',   ms: 1000 },
    { id: 'MINUTE',          label: '1 minute',   ms: 60000 },
    { id: 'FIVE_MINUTES',    label: '5 minutes',  ms: 300000 },
    { id: 'FIFTEEN_MINUTES', label: '15 minutes', ms: 900000 },
    { id: 'HOUR',            label: '1 hour',     ms: 3600000 },
    { id: 'DAY',             label: '1 day',      ms: 86400000 },
    { id: 'WEEK',            label: '1 week',     ms: 604800000 },
    { id: 'MONTH',           label: '1 month',    ms: 2629746000 }
];
const TIME_AGGREGATES = [
    { id: 'SUM', label: 'Sum' }, { id: 'AVG', label: 'Average' },
    { id: 'MIN', label: 'Minimum' }, { id: 'MAX', label: 'Maximum' }
];
// What a time series' offset column counts, and what one of it is worth in milliseconds.
// Mirrors AppPageControl#TIME_OFFSET_UNITS.
const TIME_OFFSET_UNITS = [
    { id: 'SECONDS', label: 'Seconds',      ms: 1000 },
    { id: 'MINUTES', label: 'Minutes',      ms: 60000 },
    { id: 'HOURS',   label: 'Hours',        ms: 3600000 },
    { id: 'MILLIS',  label: 'Milliseconds', ms: 1 }
];

/** One of TIME_OFFSET_UNITS in milliseconds; anything unrecognised is seconds. */
function timeOffsetMs(id) {
    const unit = TIME_OFFSET_UNITS.find(u => u.id === id);
    return unit ? unit.ms : 1000;
}

function timeOffsetLabel(id) {
    const unit = TIME_OFFSET_UNITS.find(u => u.id === id);
    return (unit ? unit.label : 'Seconds').toLowerCase();
}

/** The offset column a time series adds to its time column, or blank where it names none. */
function timeOffsetOf(c) {
    return isTimed(c) ? String((c && c.timeOffsetField) || '').trim() : '';
}

/**
 * How far past its time column one row sits, in milliseconds — and what was wrong with the cell
 * where it could not be read.
 *
 * <p>For the shape of row whose instant is spread over two columns: a business date, and the
 * seconds or minutes into it. Neither says when the row happened on its own — the date puts the
 * whole day on one tick, and the seconds have no day to be seconds of — so the chart reads both
 * and adds them.
 *
 * <p>A blank cell is no offset rather than a broken row: a column that is only filled in on the
 * rows that ran late is still worth reading, and those rows sit at their date exactly. A cell
 * with something in it that is not a number is a problem, listed beside the chart the way an
 * unreadable time is, because silently treating it as zero would move the point to the wrong
 * place and say nothing about it.
 */
function timeOffsetFor(c, row) {
    const column = timeOffsetOf(c);
    if (!column) return { ms: 0, problem: '' };
    const cell = rowField(row, column);
    if (cell === undefined || cell === null || String(cell).trim() === '') return { ms: 0, problem: '' };
    const number = sliceNumber(cell);
    if (!Number.isFinite(number)) return { ms: 0, problem: cellText(cell) };
    return { ms: number * timeOffsetMs(c.timeOffsetUnit), problem: '' };
}
// Formats offered in the designer's time format box; any other pattern may be typed.
const TIME_FORMAT_SAMPLES = ['yyyymmdd hh24:mi:ss', 'yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm:ss.SSS',
    'yyyy-MM-dd\'T\'HH:mm:ssZ', 'dd/MM/yyyy HH:mm', 'dd-MON-yyyy hh:mi:ss AM', 'yyyyMMdd', 'epoch', 'epoch_s', 'epoch_ms'];
// Auto picks the finest bucket that keeps at most this many on screen.
const TS_AUTO_BUCKETS = 150;
// More lines than this and the smallest are folded into one "Other" line, which a legend can still read.
const TS_MAX_LINES = 12;
// Points are marked with a dot while there are few enough of them to tell apart.
const TS_DOT_LIMIT = 60;
const TS_PROBLEM_SAMPLES = 5;
const MONTH_NAMES = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];

// Run state, keyed by chart id and dropped by a reset like the rest of a chart's run data:
// the time range on screen ({from, to}; absent is everything), the filters as the operator has left
// them (absent is the chart's saved ones), the bucket picked on the page, lines switched off in the
// legend, whether the add-filter form is open, and what was last drawn — which is what the hover
// and the zoom read, so neither has to work the chart out again.
let tsView = {};
let tsFilters = {};
let tsBucketPick = {};
let tsHidden = {};
let tsFilterOpen = {};
let tsDrawn = {};

function resetTimeSeriesState() {
    tsView = {}; tsFilters = {}; tsBucketPick = {}; tsHidden = {}; tsFilterOpen = {}; tsDrawn = {};
}

function tsRegexEscape(text) {
    return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const compiledTimeFormats = new Map();

/**
 * A time format as a regular expression and what each of its groups sets. Oracle and Java
 * spellings are both read — yyyy/YYYY, MM, dd/DD, HH/hh/HH24, mi/MI, ss/SS, SSS/FF, MON/MMM, AM/a,
 * Z/X — and quoted text is literal. MM is the month unless a month was already read; a lower-case
 * mm is the minute once an hour or a month has been read, so "yyyymmdd hh24:mm:ss" means what it
 * looks like it means.
 */
function compileTimeFormat(format) {
    if (compiledTimeFormats.has(format)) return compiledTimeFormats.get(format);
    const token = /'[^']*'|"[^"]*"|HH24|hh24|HH12|hh12|YYYY|yyyy|S{3,9}|FF[1-9]?|ff[1-9]?|MON|Mon|mon|MMM|YY|yy|MM|mm|MI|mi|DD|dd|HH|hh|SS|ss|AM|PM|am|pm|XXX|X|Z|M|m|d|H|h|s|a|\s+|[\s\S]/g;
    const parts = [];
    let source = '';
    let seenHour = false;
    let seenMonth = false;
    const add = (pattern, apply) => { source += '(' + pattern + ')'; parts.push(apply); };
    const setMinute = (o, v) => { o.mi = Number(v); };
    const setMonth = (o, v) => { o.mo = Number(v) - 1; };
    let m;
    while ((m = token.exec(format))) {
        const t = m[0];
        if (/^\s+$/.test(t)) { source += '\\s+'; continue; }
        if (t.length > 1 && (t[0] === '\'' || t[0] === '"')) { source += tsRegexEscape(t.slice(1, -1)); continue; }
        if (/^S{3,9}$/.test(t) || /^[Ff][Ff][1-9]?$/.test(t)) {
            add('\\d{1,9}', (o, v) => { o.ms = Number((v + '00').slice(0, 3)); });
            continue;
        }
        switch (t) {
            case 'YYYY': case 'yyyy': add('\\d{4}', (o, v) => { o.y = Number(v); }); break;
            case 'YY': case 'yy': add('\\d{2}', (o, v) => { o.y = 2000 + Number(v); }); break;
            case 'MON': case 'Mon': case 'mon': case 'MMM':
                seenMonth = true;
                add('[A-Za-z]{3}', (o, v) => { o.mo = MONTH_NAMES.indexOf(v.toLowerCase()); });
                break;
            case 'MM': case 'mm': case 'M': case 'm': {
                const width = t.length === 2 ? '\\d{2}' : '\\d{1,2}';
                const minute = t === 'm' || (t === 'mm' && (seenHour || seenMonth)) || (t !== 'm' && t !== 'mm' && seenMonth);
                if (minute) add(width, setMinute);
                else { seenMonth = true; add(width, setMonth); }
                break;
            }
            case 'MI': case 'mi': add('\\d{2}', setMinute); break;
            case 'DD': case 'dd': add('\\d{2}', (o, v) => { o.d = Number(v); }); break;
            case 'd': add('\\d{1,2}', (o, v) => { o.d = Number(v); }); break;
            case 'HH24': case 'hh24': case 'HH12': case 'hh12': case 'HH': case 'hh': case 'H': case 'h':
                seenHour = true;
                add(t.length === 1 ? '\\d{1,2}' : '\\d{2}', (o, v) => { o.h = Number(v); });
                break;
            case 'SS': case 'ss': add('\\d{2}', (o, v) => { o.s = Number(v); }); break;
            case 's': add('\\d{1,2}', (o, v) => { o.s = Number(v); }); break;
            case 'AM': case 'PM': case 'am': case 'pm': case 'a':
                add('[AaPp]\\.?[Mm]\\.?', (o, v) => { o.ampm = v[0].toLowerCase(); });
                break;
            case 'Z': case 'X': case 'XXX':
                add('[Zz]|[+-]\\d{2}:?\\d{2}|[+-]\\d{2}', (o, v) => { o.tz = v; });
                break;
            default: source += tsRegexEscape(t);
        }
    }
    const compiled = { regex: new RegExp('^\\s*' + source + '\\s*$', 'i'), parts: parts };
    compiledTimeFormats.set(format, compiled);
    return compiled;
}

/** Builds the instant out of the parts a format read: local time, unless the text carried an offset. */
function timeFromParts(o) {
    if (o.ampm === 'p' && o.h < 12) o.h += 12;
    if (o.ampm === 'a' && o.h === 12) o.h = 0;
    if (!(o.mo >= 0 && o.mo <= 11) || o.d < 1 || o.d > 31 || o.h > 23 || o.mi > 59 || o.s > 60) return NaN;
    if (o.tz) {
        const utc = Date.UTC(o.y, o.mo, o.d, o.h, o.mi, o.s, o.ms);
        if (/^z$/i.test(o.tz)) return utc;
        const digits = o.tz.replace(/[^0-9]/g, '');
        const minutes = Number(digits.slice(0, 2)) * 60 + Number(digits.slice(2, 4) || 0);
        return utc - (o.tz[0] === '-' ? -1 : 1) * minutes * 60000;
    }
    const date = new Date(2000, 0, 1);
    date.setFullYear(o.y, o.mo, o.d);
    date.setHours(o.h, o.mi, o.s, o.ms);
    // 31 February rolls into March rather than failing; it is not a date the text meant.
    return date.getDate() === o.d ? date.getTime() : NaN;
}

function parseWithFormat(text, format) {
    const compiled = compileTimeFormat(format);
    const match = compiled.regex.exec(text);
    if (!match) return NaN;
    const o = { y: 1970, mo: 0, d: 1, h: 0, mi: 0, s: 0, ms: 0 };
    compiled.parts.forEach((apply, i) => apply(o, match[i + 1]));
    return timeFromParts(o);
}

/** A bare number as an epoch: milliseconds when it is big enough to be, seconds otherwise. */
function epochGuess(n) {
    return Math.abs(n) >= 1e11 ? n : n * 1000;
}

const ISO_TIME = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:[.,](\d{1,9}))?)?)?\s*(Z|[+-]\d{2}:?\d{2})?$/i;

/**
 * One cell as an instant in epoch milliseconds, or NaN. With no format: ISO-8601 (local time
 * unless it carries an offset), yyyyMMdd and yyyyMMddHHmmss digit runs, and epoch numbers — then
 * whatever the browser's own parser makes of it.
 */
function parseTime(value, format) {
    if (value === undefined || value === null || value === '') return NaN;
    if (value instanceof Date) return value.getTime();
    const text = String(value).trim();
    const fmt = String(format || '').trim();
    const lower = fmt.toLowerCase();
    if (lower === 'epoch' || lower === 'epoch_s' || lower === 'epoch_ms') {
        const n = Number(text);
        if (!text || !Number.isFinite(n)) return NaN;
        return lower === 'epoch_s' ? n * 1000 : lower === 'epoch_ms' ? n : epochGuess(n);
    }
    if (fmt) return parseWithFormat(text, fmt);
    if (/^\d{8}$/.test(text)) return parseWithFormat(text, 'yyyyMMdd');
    if (/^\d{14}$/.test(text)) return parseWithFormat(text, 'yyyyMMddHHmmss');
    if (/^[+-]?\d+(\.\d+)?$/.test(text)) return epochGuess(Number(text));
    const iso = ISO_TIME.exec(text);
    if (iso) {
        return timeFromParts({ y: +iso[1], mo: +iso[2] - 1, d: +iso[3], h: +(iso[4] || 0), mi: +(iso[5] || 0),
            s: +(iso[6] || 0), ms: Number(((iso[7] || '') + '000').slice(0, 3)), tz: iso[8] });
    }
    const parsed = Date.parse(text);
    return Number.isFinite(parsed) ? parsed : NaN;
}

function pad2(n) { return String(n).padStart(2, '0'); }

/** An instant written out in local time, down to the second — and the millisecond when it has one. */
function tsFullLabel(t) {
    const d = new Date(t);
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate())
        + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds())
        + (d.getMilliseconds() ? '.' + String(d.getMilliseconds()).padStart(3, '0') : '');
}

/** The value a datetime-local box takes. */
function tsInputValue(t) {
    if (!Number.isFinite(t)) return '';
    const d = new Date(t);
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate())
        + 'T' + pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
}

function bucketMs(id) {
    const bucket = TIME_BUCKETS.find(b => b.id === id);
    return bucket && bucket.ms ? bucket.ms : 0;
}

/** Floors an instant to a step counted in local time, so an hour bucket starts on the local hour. */
function tzAlign(t, step) {
    const offset = new Date(t).getTimezoneOffset() * 60000;
    return Math.floor((t - offset) / step) * step + offset;
}

/** The start of the bucket an instant falls in. Days, weeks (from Monday) and months follow the calendar. */
function bucketStart(t, id) {
    if (id === 'NONE') return t;
    if (id === 'DAY' || id === 'WEEK' || id === 'MONTH') {
        const d = new Date(t);
        d.setHours(0, 0, 0, 0);
        if (id === 'WEEK') d.setDate(d.getDate() - (d.getDay() + 6) % 7);
        if (id === 'MONTH') d.setDate(1);
        return d.getTime();
    }
    return tzAlign(t, bucketMs(id));
}

function bucketNext(t, id) {
    if (id === 'DAY' || id === 'WEEK' || id === 'MONTH') {
        const d = new Date(t);
        if (id === 'MONTH') d.setMonth(d.getMonth() + 1);
        else d.setDate(d.getDate() + (id === 'WEEK' ? 7 : 1));
        return d.getTime();
    }
    return t + bucketMs(id);
}

/**
 * What a series chart's x axis is read from: the time column of a time series, the x column of a
 * line chart, or — a line chart naming none — nothing at all, which is the whole point of the
 * control: blank means counted, and tsModelOf reads it that way.
 */
function seriesAxis(c) {
    return isTimed(c) ? (c.timeField || '').trim() : (c.xField || '').trim();
}

/** What the x axis is called where a sentence needs a name for it. */
function seriesAxisName(c) {
    return seriesAxis(c) || (isTimed(c) ? 'time' : 'line');
}

/** One point on the axis, written out: an instant, or a line number under its own name. */
function seriesLabel(c, x) {
    if (isTimed(c)) return tsFullLabel(x);
    return seriesAxisName(c) + ' ' + sliceText(Math.round(x * 1000) / 1000);
}

/** The value one of a chart's range boxes shows. */
function seriesInputValue(c, x) {
    if (isTimed(c)) return tsInputValue(x);
    return Number.isFinite(x) ? String(Math.round(x)) : '';
}

/** And what comes back out of it when the operator types into it. */
function seriesInputRead(c, text) {
    const written = String(text == null ? '' : text).trim();
    if (!written) return NaN;
    return isTimed(c) ? new Date(written).getTime() : Number(written);
}

/**
 * The narrowest range a chart will zoom to. Ten milliseconds for a time series, which is below
 * anything it could be drawn from; two lines for a line chart, since one line is a range with
 * nothing across it.
 */
function seriesMinSpan(c) { return isTimed(c) ? 10 : 2; }

/** How much room a single point is given either side of it, so it is not drawn on the edge. */
function seriesPad(c) { return isTimed(c) ? 30000 : 1; }

/** The bucket a chart groups by for a span on screen: the operator's pick, the chart's own, or Auto's. */
function tsBucketFor(c, span) {
    // A line chart has no buckets and cannot have: its axis counts, so a point is one value of
    // it — one line number, or one value of its x column — and rows sharing that value are
    // combined by the aggregate rather than grouped into a span of anything.
    if (!isTimed(c)) return 'NONE';
    const chosen = tsBucketPick[c.controlId] || c.timeBucket || 'AUTO';
    if (chosen !== 'AUTO') return chosen;
    const fixed = TIME_BUCKETS.filter(b => b.ms);
    const fits = fixed.find(b => span / b.ms <= TS_AUTO_BUCKETS);
    return (fits || fixed[fixed.length - 1]).id;
}

function tsBucketLabel(id) {
    const bucket = TIME_BUCKETS.find(b => b.id === id);
    return bucket ? bucket.label : id;
}

/**
 * A series chart's model out of its rows: every row with a readable x, in x order, with its line
 * name and its value(s) read once. Filters, buckets and the range on screen are applied when it
 * is drawn, since the operator changes all three without anything being called.
 *
 * <p>A row's x is the one thing the two charts read differently. A time series parses it out of
 * the time column, and a row whose time will not parse is not on the chart. A line chart counts:
 * with no x column named, a row's x is its position in the rows — 1 for the first that came
 * back, n for the nth — so every row has one and nothing can fail to be read. That is what the
 * control is for. Name an x column on it and that column has to be a number, which can fail the
 * way a time can.
 */
function tsModelOf(shape, control) {
    const { rows, keyField, valueFields } = shape;
    const timed = isTimed(control);
    const axis = seriesAxis(control);
    const offsetColumn = timeOffsetOf(control);
    // A line chart over a bare list of numbers charts the numbers: there is nothing else in the
    // row that could be the value, and counting one row per line would draw a flat line at 1.
    // The same reading a pie makes of the same response.
    const plain = !timed && !valueFields.length && rows.length > 0 && !rows.some(isObjectRow);
    const counting = !valueFields.length;
    const entries = [];
    const problems = [];
    let problemCount = 0;
    const note = text => { problemCount++; if (problems.length < TS_PROBLEM_SAMPLES) problems.push(text); };
    const blankOr = cell => cell === undefined || cell === null || cell === '' ? '(blank)' : cellText(cell);
    if (timed && !axis) note('no time column is set on this chart');
    else rows.forEach((row, i) => {
        // A line chart counting lines reads nothing out of the row, so a row that is not a
        // record is only a problem where a column has to be read off one.
        if (!isObjectRow(row) && (axis || !plain)) { note('row ' + (i + 1) + ' is not a record'); return; }
        const raw = axis ? rowField(row, axis) : undefined;
        let t = !axis ? i + 1 : timed ? parseTime(raw, control.timeFormat) : sliceNumber(raw);
        if (!Number.isFinite(t)) {
            note('row ' + (i + 1) + ' ' + axis + ' = ' + blankOr(raw));
            return;
        }
        // Where the instant is spread over two columns — a date, and the seconds or minutes into
        // it — the second is added here, once the first has been read. A row whose offset cell
        // holds something that is not a number is left at its date and listed, rather than being
        // dropped: the date it carries is real, and losing the row entirely would say less.
        if (timed && offsetColumn) {
            const offset = timeOffsetFor(control, row);
            if (offset.problem) note('row ' + (i + 1) + ' ' + offsetColumn + ' = ' + offset.problem);
            t += offset.ms;
        }
        const values = counting ? null : valueFields.map(f => {
            const cell = rowField(row, f);
            const number = sliceNumber(cell);
            if (!Number.isFinite(number)) note('row ' + (i + 1) + ' ' + f + ' = ' + blankOr(cell));
            return number;
        });
        const line = keyField ? cellText(row, keyField) : '';
        entries.push({ t: t, row: row, line: line === '' && keyField ? '(blank)' : line, values: values,
                       plain: plain ? sliceNumber(row) : undefined });
    });
    entries.sort((a, b) => a.t - b.t);
    // Said once rather than per row, because it is one mistake however many rows arrived: a line
    // chart whose x is the line number has exactly one row per point, so counting them draws a
    // flat line at 1 and the chart says nothing at all.
    if (!timed && counting && !plain && !axis && entries.length) {
        note('every point counts one row, because each line is its own point — name a value column');
    }
    return { kind: 'series', entries: entries, problems: problems, problemCount: problemCount,
             counting: counting, plain: plain, keyField: keyField, valueFields: valueFields,
             columns: columnsOf(rows.filter(isObjectRow)), timed: timed, axis: axis };
}

/** The filters a chart is drawing under right now, as the operator has left them. */
function tsFiltersOf(c) {
    if (!tsFilters[c.controlId]) {
        tsFilters[c.controlId] = (c.chartFilters || [])
            .filter(f => (f.column || '').trim())
            .map(f => ({ column: f.column.trim(), operator: (f.operator || 'CONTAINS').toUpperCase(), value: f.value || '', saved: true }));
    }
    return tsFilters[c.controlId];
}

/** Those filters with the page's values filled in; one whose value resolves to nothing is dropped. */
function tsActiveFilters(c) {
    return tsFiltersOf(c)
        .map(f => ({ column: f.column, operator: f.operator, value: resolveTemplate(f.value || '').trim() }))
        .filter(f => VALUELESS_OPERATORS.includes(f.operator) || f.value !== '');
}

/** The line a point belongs to: its line value, and the value column when there are several. */
function tsSeriesName(model, line, field) {
    if (!model.keyField) return model.counting ? (model.plain ? 'value' : 'count') : field;
    return model.valueFields.length > 1 ? line + ' · ' + field : line;
}

function tsCombine(stat, v) {
    if (!stat) return { sum: v, count: 1, min: v, max: v };
    stat.sum += v; stat.count++;
    if (v < stat.min) stat.min = v;
    if (v > stat.max) stat.max = v;
    return stat;
}

function tsStatValue(stat, agg) {
    switch (agg) {
        case 'COUNT': return stat.count;
        case 'AVG':   return stat.sum / stat.count;
        case 'MIN':   return stat.min;
        case 'MAX':   return stat.max;
        default:      return stat.sum;
    }
}

/** First index in a time-sorted list at or after t. */
function tsLowerBound(list, t, get) {
    let lo = 0, hi = list.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (get(list[mid]) < t) lo = mid + 1; else hi = mid;
    }
    return lo;
}

/**
 * What the chart draws: the rows past its filters, the range on screen, the bucket that range
 * gets, and a line per series with a value per bucket. Lines are chosen and coloured off every
 * filtered row rather than off the range on screen, so zooming never recolours or swaps a line.
 */
function tsCompute(c) {
    const model = pieData[c.controlId];
    const filters = tsActiveFilters(c);
    const kept = filters.length
        ? model.entries.filter(e => filters.every(f => cellPasses(cellText(e.row, f.column), f)))
        : model.entries;
    const fields = model.counting ? [''] : model.valueFields;
    // Counting rows is a count; charting a bare list of numbers is not — each of those points is
    // the number that came back, so it is combined like any named value column.
    const agg = model.counting && !model.plain ? 'COUNT' : (c.timeAggregate || 'SUM');
    const valueAt = (e, k) => model.counting ? (model.plain ? e.plain : 1) : e.values[k];

    const totals = new Map();
    kept.forEach(e => fields.forEach((field, k) => {
        const v = valueAt(e, k);
        if (!Number.isFinite(v)) return;
        const name = tsSeriesName(model, e.line, field);
        totals.set(name, (totals.get(name) || 0) + Math.abs(v));
    }));
    let names = Array.from(totals.keys());
    let folded = false;
    if (names.length > TS_MAX_LINES) {
        const top = new Set(names.slice().sort((a, b) => totals.get(b) - totals.get(a)).slice(0, TS_MAX_LINES - 1));
        names = names.filter(n => top.has(n)).concat('Other');
        folded = true;
    }
    const nameIndex = new Map(names.map((n, i) => [n, i]));

    const fullFrom = kept.length ? kept[0].t : NaN;
    const fullTo = kept.length ? kept[kept.length - 1].t : NaN;
    const view = tsView[c.controlId];
    let from = view ? view.from : fullFrom;
    let to = view ? view.to : fullTo;
    // A range with nothing across it — one instant, one line — is widened either side, or the
    // point would be drawn on the edge of the plot with no axis to read it against.
    if (Number.isFinite(from) && to - from < seriesMinSpan(c)) {
        const pad = seriesPad(c);
        from -= pad;
        to += pad;
    }
    const bucket = tsBucketFor(c, to - from);

    const start = tsLowerBound(kept, from, e => e.t);
    const end = tsLowerBound(kept, to + 1, e => e.t);
    const stats = names.map(() => new Map());
    for (let i = start; i < end; i++) {
        const e = kept[i];
        const b = bucketStart(e.t, bucket);
        fields.forEach((field, k) => {
            const v = valueAt(e, k);
            if (!Number.isFinite(v)) return;
            const name = tsSeriesName(model, e.line, field);
            const s = nameIndex.has(name) ? nameIndex.get(name) : nameIndex.get('Other');
            stats[s].set(b, tsCombine(stats[s].get(b), v));
        });
    }
    // "Other" is several lines added together, point by point, as the loop above combines them.

    const timeSet = new Set();
    stats.forEach(m => m.forEach((_, t) => timeSet.add(t)));
    // A count is zero where nothing happened, and a gap drawn as a straight line would say
    // otherwise. Only a count: a missing line of a list of numbers is a line that did not come
    // back, not a zero, and a line chart has no buckets to walk anyway.
    if (model.counting && !model.plain && bucket !== 'NONE' && Number.isFinite(from)) {
        const first = bucketStart(from, bucket);
        if ((to - first) / Math.max(bucketMs(bucket), 1) <= 5000) {
            for (let t = first; t <= to; t = bucketNext(t, bucket)) timeSet.add(t);
        }
    }
    const times = Array.from(timeSet).sort((a, b) => a - b);
    const hidden = tsHidden[c.controlId] || new Set();
    const series = names.map((name, i) => {
        const values = new Map();
        times.forEach(t => {
            const stat = stats[i].get(t);
            if (stat) values.set(t, tsStatValue(stat, agg));
            else if (model.counting && !model.plain && bucket !== 'NONE') values.set(t, 0);
        });
        return { name: name, color: PIE_COLORS[i % PIE_COLORS.length], hidden: hidden.has(name), values: values };
    });

    let lo = Infinity, hi = -Infinity;
    series.forEach(s => { if (!s.hidden) s.values.forEach(v => { if (v < lo) lo = v; if (v > hi) hi = v; }); });
    if (!Number.isFinite(lo)) { lo = 0; hi = 1; }
    const yMin = lo < 0 ? -niceMax(-lo) : 0;
    const yMax = hi > 0 ? niceMax(hi) : (lo < 0 ? 0 : 1);

    const inView = end - start;
    const drawn = { from: from, to: to, fullFrom: fullFrom, fullTo: fullTo, bucket: bucket, agg: agg,
                    times: times, series: series, yMin: yMin, yMax: yMax, kept: kept.length,
                    inView: inView, total: model.entries.length, folded: folded, filters: filters.length };
    tsDrawn[c.controlId] = drawn;
    return drawn;
}

/** A step for the time axis that gives at most about seven labels. */
const TS_TICK_STEPS = [1, 2, 5, 10, 15, 30].map(s => s * 1000)
    .concat([1, 2, 5, 10, 15, 30].map(m => m * 60000))
    .concat([1, 2, 3, 6, 12].map(h => h * 3600000))
    .concat([1, 2, 7, 14, 30, 91, 182, 365].map(d => d * 86400000));

/**
 * A step for an axis that counts: 1, 2 or 5 times a power of ten, whichever first keeps the
 * labels down to about seven — and never below 1, since half a line is not a line.
 */
function countTickStep(span) {
    const rough = Math.max(span, 1) / 7;
    const scale = Math.pow(10, Math.floor(Math.log10(Math.max(rough, 1))));
    return [1, 2, 5, 10].map(m => m * scale).find(step => span / step <= 7) || 10 * scale;
}

/** The labels along a counted axis: whole numbers, on the step above. */
function countTicks(from, to) {
    const step = countTickStep(to - from);
    const ticks = [];
    let x = Math.ceil(Math.max(from, 1) / step) * step;
    for (; x <= to && ticks.length < 20; x += step) ticks.push({ t: x, text: sliceText(x) });
    // A range narrow enough to hold no multiple of the step still has a point in it to label.
    if (!ticks.length && Number.isFinite(from)) ticks.push({ t: from, text: sliceText(Math.round(from)) });
    return ticks;
}

/** The labels along whichever axis this chart has. */
function seriesTicks(c, from, to) {
    return isTimed(c) ? tsTicks(from, to) : countTicks(from, to);
}

function tsTicks(from, to) {
    const span = to - from;
    const step = TS_TICK_STEPS.find(s => span / s <= 7) || TS_TICK_STEPS[TS_TICK_STEPS.length - 1];
    const ticks = [];
    let t = step >= 86400000 ? bucketStart(from, 'DAY') : tzAlign(from, step);
    if (t < from) t += step;
    for (; t <= to && ticks.length < 20; t += step) ticks.push(t);
    let lastDay = '';
    return ticks.map(t => {
        const d = new Date(t);
        const day = d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
        let text;
        if (step >= 86400000) text = day;
        else {
            text = pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + (step < 60000 ? ':' + pad2(d.getSeconds()) : '');
            if (day !== lastDay) text += '<br>' + day;
        }
        lastDay = day;
        return { t: t, text: text };
    });
}

/** The plot: lines in a stretched SVG, and axis labels in HTML so the text is never stretched with it. */
function tsPlot(c, d, height) {
    const span = d.to - d.from || 1;
    const x = t => (t - d.from) / span * 1000;
    const y = v => (1 - (v - d.yMin) / (d.yMax - d.yMin)) * 1000;
    const pct = n => (n / 10).toFixed(3) + '%';
    const yTicks = [0, 1, 2, 3, 4].map(k => d.yMin + (d.yMax - d.yMin) * k / 4);
    const grid = yTicks.map(v => '<line class="ts-grid' + (v === 0 && d.yMin < 0 ? ' zero' : '') + '" x1="0" x2="1000" y1="'
        + y(v) + '" y2="' + y(v) + '" vector-effect="non-scaling-stroke"/>').join('');
    const visible = d.series.filter(s => !s.hidden);
    const paths = visible.map(s => {
        const pts = d.times.filter(t => s.values.has(t));
        if (!pts.length) return '';
        const path = pts.map((t, i) => (i ? 'L' : 'M') + x(t).toFixed(2) + ' ' + y(s.values.get(t)).toFixed(2)).join('')
            + (pts.length === 1 ? 'l0.01 0' : '');
        return '<path d="' + path + '" stroke="' + s.color + '" vector-effect="non-scaling-stroke"/>';
    }).join('');
    const dots = d.times.length <= TS_DOT_LIMIT ? visible.map(s => d.times.filter(t => s.values.has(t)).map(t =>
        '<i class="ts-dot" style="left:' + pct(x(t)) + ';top:' + pct(y(s.values.get(t))) + ';background:' + s.color + '"></i>').join('')).join('') : '';
    return '<div class="ts-frame" style="height:' + height + 'px">'
        + '<div class="ts-y">' + yTicks.map(v => '<span style="top:' + pct(y(v)) + '">' + AC.esc(sliceText(Math.round(v * 1000) / 1000)) + '</span>').join('') + '</div>'
        + '<div class="ts-main">'
            + '<div class="ts-plot" data-ts-plot="' + AC.attr(c.controlId) + '" title="Drag across to zoom in · wheel to zoom · double-click to reset">'
                + '<svg class="ts-svg" viewBox="0 0 1000 1000" preserveAspectRatio="none">' + grid + paths + '</svg>'
                + dots
                + '<div class="ts-hover"></div><div class="ts-brush"></div><div class="ts-tip"></div>'
            + '</div>'
            + '<div class="ts-x">' + seriesTicks(c, d.from, d.to).map(k => '<span style="left:' + pct(x(k.t)) + '">' + k.text + '</span>').join('') + '</div>'
        + '</div></div>';
}

function tsLegend(c, d, model) {
    const measure = model.counting && !model.plain ? 'Count of rows'
        : (TIME_AGGREGATES.find(a => a.id === d.agg) || {}).label + ' of '
            + (model.plain ? 'the numbers' : model.valueFields.join(', '));
    // A time series says which bucket of time a point covers; a line chart's point is one value
    // of its axis, so what it says is which axis that is.
    const per = isTimed(c) ? AC.esc(tsBucketLabel(d.bucket).replace(/^1 /, '').replace(/^None — each /, ''))
                           + (d.bucket !== 'NONE' && (tsBucketPick[c.controlId] || c.timeBucket || 'AUTO') === 'AUTO' ? ' (auto)' : '')
                           : AC.esc(seriesAxisName(c));
    return '<div class="bar-legend ts-legend"><span class="ts-measure">' + AC.esc(measure) + ' per ' + per + '</span>'
        + (d.series.length > 1 || model.keyField ? d.series.map(s =>
            '<button type="button" class="ts-line' + (s.hidden ? ' off' : '') + '" data-ts-act="toggle" data-ts-line="' + AC.attr(s.name) + '"'
                + ' title="' + (s.hidden ? 'Show' : 'Hide') + ' this line">'
                + '<span class="bar-swatch" style="background:' + s.color + '"></span>' + AC.esc(s.name) + '</button>').join('') : '')
        + (d.folded ? '<span class="hint" style="margin:0">smaller lines folded into Other</span>' : '')
        + '</div>';
}

function tsOperatorLabel(op) {
    const known = ROW_FILTER_OPERATORS.find(o => o.op === op);
    return known ? known.label : op.toLowerCase();
}

/** Distinct values of a column across the chart's rows, for the filter value box to suggest. */
function tsDistinct(model, column) {
    const seen = new Set();
    for (let i = 0; i < model.entries.length && seen.size < 300; i++) {
        const text = cellText(model.entries[i].row, column);
        if (text !== '') seen.add(text);
    }
    return Array.from(seen).sort();
}

function tsDatalistOptions(values) {
    return values.map(v => '<option value="' + AC.attr(v) + '"></option>').join('');
}

/** The row of run-time tools: filters, bucket, zoom and the range on screen. */
function tsToolbar(c, d, model, suffix) {
    const id = c.controlId;
    const chips = tsFiltersOf(c).map((f, i) => '<span class="grid-pin ts-chip' + (f.saved ? ' saved' : '') + '"'
            + (f.saved ? ' title="Set on the chart"' : '') + '>'
            + AC.esc(f.column + ' ' + tsOperatorLabel(f.operator)
                + (VALUELESS_OPERATORS.includes(f.operator) ? '' : ' ' + (resolveTemplate(f.value || '') || '(any)')))
            + '<button type="button" data-ts-act="filter-remove" data-ts-i="' + i + '" title="Take this filter off">×</button></span>').join('');
    const listId = 'tsvals-' + id + (suffix || '');
    const firstColumn = model.columns[0] || '';
    const form = tsFilterOpen[id]
        ? '<span class="ts-form">'
            + '<select data-ts-fcol data-ts-list="' + AC.attr(listId) + '">' + model.columns.map(col =>
                '<option value="' + AC.attr(col) + '">' + AC.esc(col) + '</option>').join('') + '</select>'
            + '<select data-ts-fop>' + ROW_FILTER_OPERATORS.map(o =>
                '<option value="' + o.op + '"' + (o.op === 'EQUALS' ? ' selected' : '') + '>' + AC.esc(o.label) + '</option>').join('') + '</select>'
            + '<input type="text" data-ts-fval list="' + AC.attr(listId) + '" placeholder="value">'
            + '<datalist id="' + AC.attr(listId) + '">' + (firstColumn ? tsDatalistOptions(tsDistinct(model, firstColumn)) : '') + '</datalist>'
            + '<button type="button" class="ts-btn" data-ts-act="filter-add">Add</button>'
            + '<button type="button" class="ts-btn" data-ts-act="filter-cancel" title="Cancel">✕</button></span>'
        : (model.columns.length ? '<button type="button" class="ts-btn" data-ts-act="filter-open" title="Show only rows matching a column">+ Filter</button>' : '');
    const bucketPick = tsBucketPick[id] || c.timeBucket || 'AUTO';
    const zoomed = !!tsView[id];
    const timed = isTimed(c);
    // A line chart has no buckets to pick between — see tsBucketFor — so the picker is not drawn
    // rather than drawn offering spans of time to something that counts.
    const buckets = timed
        ? '<span class="ts-group"><span class="ts-cap">Bucket</span><select data-ts-bucket>'
            + TIME_BUCKETS.map(b => '<option value="' + b.id + '"' + (b.id === bucketPick ? ' selected' : '') + '>'
                + AC.esc(b.id === 'AUTO' ? 'Auto (' + tsBucketLabel(d.bucket) + ')' : b.label) + '</option>').join('')
            + '</select></span>'
        : '';
    const box = which => '<input type="' + (timed ? 'datetime-local" step="1' : 'number" step="1" min="1')
        + '" data-ts-' + which + ' value="' + AC.attr(seriesInputValue(c, which === 'from' ? d.from : d.to)) + '">';
    const back = timed ? 'Move back in time' : 'Move back down the ' + seriesAxisName(c) + 's';
    const forward = timed ? 'Move forward in time' : 'Move on up the ' + seriesAxisName(c) + 's';
    return '<div class="ts-tools">'
        + '<span class="ts-filters">' + chips + form + '</span>'
        + buckets
        + '<span class="ts-group">'
            + '<button type="button" class="ts-btn" data-ts-act="pan-left" title="' + AC.attr(back) + '">◀</button>'
            + '<button type="button" class="ts-btn" data-ts-act="zoom-in" title="Zoom in">＋</button>'
            + '<button type="button" class="ts-btn" data-ts-act="zoom-out" title="Zoom out">－</button>'
            + '<button type="button" class="ts-btn" data-ts-act="pan-right" title="' + AC.attr(forward) + '">▶</button>'
            + '<button type="button" class="ts-btn" data-ts-act="reset"' + (zoomed ? '' : ' disabled') + ' title="Show the whole range">Reset</button>'
        + '</span>'
        + '<span class="ts-group"><span class="ts-cap">From</span>' + box('from')
            + '<span class="ts-cap">To</span>' + box('to') + '</span>'
        + '<span class="ts-count">' + d.inView.toLocaleString() + (d.inView === 1 ? ' row' : ' rows') + ' in view'
            + (d.kept !== d.total ? ' · ' + d.kept.toLocaleString() + ' of ' + d.total.toLocaleString() + ' pass filters' : '') + '</span>'
        + '</div>';
}

/** @param zoom as on {@link #pieRun}: the room the overlay has, when this is the big copy. */
function tsRun(c, zoom) {
    const box = zoom ? zoom.height : controlHeight(c);
    const model = pieData[c.controlId];
    const label = chartLabel(c, zoom);
    const failed = chartFailure(c);
    if (failed) return label + failed;
    if (!model || model.kind !== 'series') {
        return label + '<div class="grid-empty">Nothing charted yet — an action aimed at this chart, or the grid it is drawn from, fills it.</div>';
    }
    // What has to be readable differs with the axis: a time series parses a time, a line chart
    // with an x column reads a number out of it, and a line chart counting lines reads nothing
    // at all — so there only the values can be at fault.
    const why = isTimed(c)
        ? 'a time has to match ' + AC.esc(c.timeFormat ? '"' + c.timeFormat + '"' : 'an ISO date or an epoch') + ', and a value has to be a number'
        : model.axis ? AC.esc(model.axis) + ' and the values have to be numbers'
        : 'a value has to be a number';
    const problems = model.problemCount
        ? '<div class="bar-bad">Not charted (' + model.problemCount.toLocaleString() + '): ' + AC.esc(model.problems.join(', '))
            + (model.problemCount > model.problems.length ? ', …' : '')
            + ' — ' + why + '.</div>'
        : '';
    if (!model.entries.length) {
        return label + '<div class="grid-empty">The call returned nothing to chart.</div>' + problems;
    }
    const d = tsCompute(c);
    const suffix = zoom ? '-z' : '';
    const head = tsToolbar(c, d, model, suffix);
    if (!d.kept) {
        return label + '<div class="ts-chart" data-ts="' + AC.attr(c.controlId) + '">' + head + problems
            + '<div class="grid-empty">No rows pass the filters.</div></div>';
    }
    const height = Math.max(box - 26 - 34 - 20 - 30 - (problems ? 16 : 0), 80);
    return label + '<div class="ts-chart" data-ts="' + AC.attr(c.controlId) + '">' + head
        + tsLegend(c, d, model) + problems + tsPlot(c, d, height) + '</div>';
}

/** A time series on the canvas: a stand-in pair of lines, and what the chart reads. */
function tsPreview(c) {
    const height = Math.min(Math.max(controlHeight(c) - 30, 26), 84);
    const line = (pts, color) => '<polyline fill="none" stroke="' + color + '" stroke-width="2" vector-effect="non-scaling-stroke" points="'
        + pts.map((v, i) => (i * 20) + ',' + (40 - v)).join(' ') + '"/>';
    return '<div class="fake bar-fake" style="flex-direction:column;align-items:stretch">'
        + '<svg viewBox="0 0 200 40" preserveAspectRatio="none" style="width:100%;height:' + Math.max(height - 16, 14) + 'px">'
            + line([10, 18, 14, 26, 22, 30, 24, 34, 28, 32, 36], PIE_COLORS[0])
            + line([4, 8, 6, 12, 9, 7, 14, 11, 16, 13, 18], PIE_COLORS[1]) + '</svg>'
        + '<span>' + (isTimed(c)
                ? (c.timeField ? 'time <b>' + AC.esc(c.timeField) + '</b>' + (c.timeFormat ? ' as ' + AC.esc(c.timeFormat) : '')
                    : '<span style="color:#bf2600">pick a time column</span>')
                    + (timeOffsetOf(c) ? ' + <b>' + AC.esc(timeOffsetOf(c)) + '</b> '
                        + AC.esc(timeOffsetLabel(c.timeOffsetUnit)) : '')
                    + ' · ' + AC.esc(tsBucketLabel(c.timeBucket || 'AUTO').toLowerCase()) + ' buckets'
                // A line chart naming no x column is not missing anything: the line number is
                // the axis it was added for, so that is what the preview says it is drawing.
                : 'x is ' + (seriesAxis(c) ? '<b>' + AC.esc(seriesAxis(c)) + '</b>' : 'the <b>line number</b>'))
            + ((c.chartFilters || []).length ? ' · ' + c.chartFilters.length + ' filter' + (c.chartFilters.length === 1 ? '' : 's') : '')
            + ' · ' + chartFedBy(c) + '</span></div>';
}

/**
 * A series chart in the properties panel: what its x axis is, how points landing together are
 * combined, and the filters it starts out drawing under.
 *
 * <p>The axis is the whole of the difference between the two charts, so it is the whole of the
 * difference between their panels. A time series asks for the column its instants are in and the
 * format they are written in, and has to have one. A line chart asks for nothing it must have:
 * its axis counts the rows, and the box it offers is the optional one for reading x out of a
 * column instead.
 */
function seriesProps(c) {
    const filters = c.chartFilters || [];
    const bucket = c.timeBucket || 'AUTO';
    const agg = c.timeAggregate || 'SUM';
    const timed = isTimed(c);
    const axisPart = timed
        ? '<div class="form-row" style="margin-bottom:0">'
            + field('Time Column', '<input type="text" placeholder="createdAt" value="' + AC.attr(c.timeField || '')
                + '" oninput="setProp(\'timeField\', this.value)">', 'Required. The column each row' + Q + 's time is read from.')
            + field('Time Format', '<input type="text" list="tsFormatList" placeholder="blank: ISO or epoch" value="' + AC.attr(c.timeFormat || '')
                + '" oninput="setProp(\'timeFormat\', this.value); tsTestFormat()">'
                + '<datalist id="tsFormatList">' + TIME_FORMAT_SAMPLES.map(f => '<option value="' + AC.attr(f) + '"></option>').join('') + '</datalist>')
          + '</div>'
          + '<span class="hint">Oracle or Java spelling: <code>yyyymmdd hh24:mi:ss</code>, <code>yyyy-MM-dd HH:mm:ss.SSS</code>, '
            + '<code>dd-MON-yyyy hh:mi:ss AM</code>, <code>yyyy-MM-dd' + Q + 'T' + Q + 'HH:mm:ssZ</code>. A lower-case <code>mm</code> '
            + 'after an hour is the minute, so <code>yyyymmdd hh24:mm:ss</code> works too. <code>epoch</code>, <code>epoch_s</code> '
            + 'and <code>epoch_ms</code> read numbers. Blank reads ISO-8601 and epoch. Times are local unless they carry an offset.</span>'
          + field('Try A Value', '<input type="text" id="tsTryValue" placeholder="20240115 13:45:10" oninput="tsTestFormat()">'
            + '<span class="hint" id="tsTryResult" style="margin:2px 0 0"></span>')
          + '<div class="form-row" style="margin-bottom:0">'
            + field('Offset Column (optional)', '<input type="text" placeholder="elapsedSecs" value="' + AC.attr(c.timeOffsetField || '')
                + '" oninput="setProp(\'timeOffsetField\', this.value)">')
            + field('Offset Is In', '<select onchange="setProp(\'timeOffsetUnit\', this.value)">' + TIME_OFFSET_UNITS.map(u =>
                '<option value="' + u.id + '"' + (u.id === (c.timeOffsetUnit || 'SECONDS') ? ' selected' : '') + '>'
                    + AC.esc(u.label) + '</option>').join('') + '</select>')
          + '</div>'
          + '<span class="hint">For rows whose instant is in <i>two</i> columns rather than one: a date, and how far '
            + 'into it. <code>RUN_DATE = 20240115</code> with <code>ELAPSED_SECS = 3720</code> is 01:02 on the 15th — '
            + 'and neither column says that alone, since the date puts the whole day on one tick and the seconds have '
            + 'no day to be seconds of. Name the second column here and its number, read as the unit chosen, is added '
            + 'on top of the time column above, so every row lands where it actually happened and the buckets below '
            + 'have something finer than a day to group. Leave it blank where the time column already carries the '
            + 'whole instant, which is most of them. A blank cell is no offset — the row sits at its date — and a '
            + 'cell that is not a number is listed beside the chart.</span>'
        : field('X Column (optional)', '<input type="text" placeholder="blank: the line number" value="' + AC.attr(c.xField || '')
                + '" oninput="setProp(\'xField\', this.value)">')
          + '<span class="hint">Leave it blank and the x axis is the <b>line number</b>: the first row that came back is 1, the '
            + 'second 2, and every tick along the bottom is a row of the response. That is what this chart is for — a log, a run '
            + 'of samples, a paged fetch: rows whose <i>order</i> is the sequence, with no timestamp in them to read along '
            + 'instead. Name a column and it is read as a number and used as x, so rows sharing a value share a point.</span>';
    const combine = '<div class="form-row" style="margin-bottom:0">'
        + (timed
            ? field('Bucket', '<select onchange="setProp(\'timeBucket\', this.value)">' + TIME_BUCKETS.map(b =>
                '<option value="' + b.id + '"' + (b.id === bucket ? ' selected' : '') + '>' + AC.esc(b.label) + '</option>').join('') + '</select>')
            : '')
        + field('Combine Values By', '<select onchange="setProp(\'timeAggregate\', this.value)">' + TIME_AGGREGATES.map(a =>
            '<option value="' + a.id + '"' + (a.id === agg ? ' selected' : '') + '>' + AC.esc(a.label) + '</option>').join('') + '</select>')
        + '</div>'
        + '<span class="hint">'
        + (timed
            ? 'Auto picks a bucket from the range on screen, so zooming in shows finer detail. With no value column each point '
                + 'counts the rows in its bucket; with one, the values in a bucket are combined as chosen. '
            : 'Every value of x is its own point, so this only comes into it where several rows share one — then their values '
                + 'are combined as chosen. With no value column each point would be the one row that made it, which is a flat '
                + 'line: name a value column, or bind a plain list of numbers and each line is its number. ')
        + 'The line and value columns are set where the rows come from — on the action aimed at this chart, or under Data From '
        + 'Grid below.</span>';
    return '<div class="props-section"><div class="props-title"><span>' + (timed ? 'Time Series' : 'Line Chart') + '</span></div>'
        + axisPart
        + combine
        + '<div class="props-title" style="margin-top:8px"><span>Filters</span>'
            + '<button type="button" class="secondary" onclick="tsFilterEdit(\'add\')">+ Filter</button></div>'
        + (filters.length ? filters.map((f, i) => '<div class="form-row" style="margin-bottom:4px;align-items:center">'
            + '<input type="text" placeholder="column" value="' + AC.attr(f.column || '') + '" oninput="tsFilterEdit(\'set\', ' + i + ', \'column\', this.value)">'
            + '<select onchange="tsFilterEdit(\'set\', ' + i + ', \'operator\', this.value)">' + ROW_FILTER_OPERATORS.map(o =>
                '<option value="' + o.op + '"' + (o.op === (f.operator || 'CONTAINS') ? ' selected' : '') + '>' + AC.esc(o.label) + '</option>').join('') + '</select>'
            + '<input type="text" placeholder="value or ${field}" value="' + AC.attr(f.value || '') + '" oninput="tsFilterEdit(\'set\', ' + i + ', \'value\', this.value)">'
            + '<button type="button" class="danger" onclick="tsFilterEdit(\'remove\', ' + i + ')" title="Remove">×</button></div>').join('')
            : '<span class="hint">None. Rows can still be filtered by any column while the page runs.</span>')
        + (filters.length ? '<span class="hint">Every filter has to pass. A value may name a control — <code>${statusPick}</code> — and '
            + 'one that resolves to nothing is ignored. The operator can take these off and add others while the page runs.</span>' : '')
        + '</div>';
}

function tsFilterEdit(op, at, name, value) {
    const c = findControl(selectedId);
    if (!c) return;
    const filters = c.chartFilters = c.chartFilters || [];
    if (op === 'add') filters.push({ column: '', operator: 'EQUALS', value: '' });
    else if (op === 'remove') filters.splice(at, 1);
    else if (op === 'set' && filters[at]) { filters[at][name] = value; if (name !== 'operator') { renderCanvas(); return; } }
    renderProps();
    renderCanvas();
}

/** Shows what the designer's sample time reads as under the format being typed. */
function tsTestFormat() {
    const input = document.getElementById('tsTryValue');
    const out = document.getElementById('tsTryResult');
    const c = findControl(selectedId);
    if (!input || !out || !c) return;
    if (!input.value.trim()) { out.textContent = ''; return; }
    const t = parseTime(input.value, c.timeFormat);
    out.style.color = Number.isFinite(t) ? '#006644' : '#bf2600';
    out.textContent = Number.isFinite(t) ? '→ ' + tsFullLabel(t) + ' (local)' : 'Does not match the format';
}

// ── Time series interaction ──────────────────────────────────────────────
// Wired once on the document rather than on each chart, since a chart is redrawn whole on every
// change and may be drawn in a tab or in the zoom overlay as well as on the page.

function tsControlAt(el) {
    const host = el && el.closest && el.closest('[data-ts]');
    const control = host && findControl(host.dataset.ts);
    return control && isSeries(control.type) ? { host: host, control: control } : null;
}

/** Puts a range on screen, kept inside the rows there are; a range as wide as them is no zoom at all. */
function tsSetView(control, from, to) {
    const d = tsDrawn[control.controlId];
    if (!d || !Number.isFinite(from) || !Number.isFinite(to)) return;
    if (to < from) [from, to] = [to, from];
    const full = d.fullTo - d.fullFrom;
    const span = Math.max(to - from, seriesMinSpan(control));
    if (span >= full) delete tsView[control.controlId];
    else {
        if (from < d.fullFrom) from = d.fullFrom;
        if (from + span > d.fullTo) from = d.fullTo - span;
        tsView[control.controlId] = { from: from, to: from + span };
    }
    paintChart(control);
}

function tsZoom(control, factor, anchor) {
    const d = tsDrawn[control.controlId];
    if (!d) return;
    const span = d.to - d.from;
    const next = Math.max(span * factor, seriesMinSpan(control));
    const from = d.from + (span - next) * anchor;
    tsSetView(control, from, from + next);
}

document.addEventListener('click', e => {
    const btn = e.target.closest && e.target.closest('[data-ts-act]');
    const at = btn && tsControlAt(btn);
    if (!at) return;
    const { control, host } = at;
    const id = control.controlId;
    const d = tsDrawn[id];
    switch (btn.dataset.tsAct) {
        case 'zoom-in':  tsZoom(control, 0.5, 0.5); return;
        case 'zoom-out': tsZoom(control, 2, 0.5); return;
        case 'pan-left':
        case 'pan-right': {
            if (!d || !tsView[id]) return;
            const shift = (d.to - d.from) * 0.25 * (btn.dataset.tsAct === 'pan-left' ? -1 : 1);
            tsSetView(control, d.from + shift, d.to + shift);
            return;
        }
        case 'reset': delete tsView[id]; break;
        case 'toggle': {
            const hidden = tsHidden[id] = tsHidden[id] || new Set();
            const name = btn.dataset.tsLine;
            if (hidden.has(name)) hidden.delete(name); else hidden.add(name);
            break;
        }
        case 'filter-open': tsFilterOpen[id] = true; break;
        case 'filter-cancel': delete tsFilterOpen[id]; break;
        case 'filter-add': {
            const column = (host.querySelector('[data-ts-fcol]') || {}).value || '';
            const operator = (host.querySelector('[data-ts-fop]') || {}).value || 'EQUALS';
            const value = (host.querySelector('[data-ts-fval]') || {}).value || '';
            if (!column) return;
            tsFiltersOf(control).push({ column: column, operator: operator, value: value });
            delete tsFilterOpen[id];
            break;
        }
        case 'filter-remove':
            tsFiltersOf(control).splice(Number(btn.dataset.tsI), 1);
            break;
        default: return;
    }
    paintChart(control);
});

document.addEventListener('change', e => {
    const at = tsControlAt(e.target);
    if (!at) return;
    const { control, host } = at;
    const el = e.target;
    if (el.matches('[data-ts-bucket]')) {
        tsBucketPick[control.controlId] = el.value;
        paintChart(control);
    } else if (el.matches('[data-ts-from], [data-ts-to]')) {
        const from = seriesInputRead(control, (host.querySelector('[data-ts-from]') || {}).value);
        const to = seriesInputRead(control, (host.querySelector('[data-ts-to]') || {}).value);
        tsSetView(control, from, to);
    } else if (el.matches('[data-ts-fcol]')) {
        const list = document.getElementById(el.dataset.tsList);
        const model = pieData[control.controlId];
        if (list && model) list.innerHTML = tsDatalistOptions(tsDistinct(model, el.value));
    }
});

document.addEventListener('keydown', e => {
    if (e.key !== 'Enter' || !e.target.matches || !e.target.matches('[data-ts-fval]')) return;
    const add = e.target.closest('[data-ts]').querySelector('[data-ts-act="filter-add"]');
    if (add) { e.preventDefault(); add.click(); }
});

/** Where along a plot a pointer is, from 0 at the left edge to 1 at the right. */
function tsFraction(plot, clientX) {
    const rect = plot.getBoundingClientRect();
    return rect.width ? Math.min(Math.max((clientX - rect.left) / rect.width, 0), 1) : 0.5;
}

let tsWheel = null;
document.addEventListener('wheel', e => {
    const plot = e.target.closest && e.target.closest('[data-ts-plot]');
    const at = plot && tsControlAt(plot);
    if (!at || !e.deltaY) return;
    e.preventDefault();
    // Wheel events come in bursts; the burst is added up and drawn once a frame.
    const factor = e.deltaY < 0 ? 0.8 : 1.25;
    if (tsWheel) { tsWheel.factor *= factor; return; }
    tsWheel = { control: at.control, factor: factor, anchor: tsFraction(plot, e.clientX) };
    requestAnimationFrame(() => {
        const w = tsWheel;
        tsWheel = null;
        tsZoom(w.control, w.factor, w.anchor);
    });
}, { passive: false });

let tsDrag = null;
document.addEventListener('mousedown', e => {
    const plot = e.button === 0 && e.target.closest && e.target.closest('[data-ts-plot]');
    if (!plot || !tsControlAt(plot)) return;
    e.preventDefault();
    tsDrag = { plot: plot, start: tsFraction(plot, e.clientX), x: e.clientX };
});

document.addEventListener('mousemove', e => {
    if (tsDrag) {
        const brush = tsDrag.plot.querySelector('.ts-brush');
        const now = tsFraction(tsDrag.plot, e.clientX);
        brush.style.display = 'block';
        brush.style.left = (Math.min(now, tsDrag.start) * 100) + '%';
        brush.style.width = (Math.abs(now - tsDrag.start) * 100) + '%';
        return;
    }
    const plot = e.target.closest && e.target.closest('[data-ts-plot]');
    if (plot) tsHover(plot, e.clientX);
});

document.addEventListener('mouseup', e => {
    if (!tsDrag) return;
    const drag = tsDrag;
    tsDrag = null;
    drag.plot.querySelector('.ts-brush').style.display = 'none';
    const at = tsControlAt(drag.plot);
    const d = at && tsDrawn[at.control.controlId];
    if (!d || Math.abs(e.clientX - drag.x) < 5) return;
    const end = tsFraction(drag.plot, e.clientX);
    const span = d.to - d.from;
    tsSetView(at.control, d.from + span * Math.min(drag.start, end), d.from + span * Math.max(drag.start, end));
});

document.addEventListener('dblclick', e => {
    const plot = e.target.closest && e.target.closest('[data-ts-plot]');
    const at = plot && tsControlAt(plot);
    if (!at) return;
    delete tsView[at.control.controlId];
    paintChart(at.control);
});

document.addEventListener('mouseout', e => {
    const plot = e.target.closest && e.target.closest('[data-ts-plot]');
    if (!plot || (e.relatedTarget && plot.contains(e.relatedTarget))) return;
    plot.querySelector('.ts-hover').style.display = 'none';
    plot.querySelector('.ts-tip').style.display = 'none';
});

/** The bucket nearest the pointer, marked, with every visible line's value at it. */
function tsHover(plot, clientX) {
    const at = tsControlAt(plot);
    const d = at && tsDrawn[at.control.controlId];
    const line = plot.querySelector('.ts-hover');
    const tip = plot.querySelector('.ts-tip');
    if (!d || !d.times.length) return;
    const frac = tsFraction(plot, clientX);
    const t = d.from + frac * (d.to - d.from);
    let i = tsLowerBound(d.times, t, v => v);
    if (i >= d.times.length || (i > 0 && t - d.times[i - 1] < d.times[i] - t)) i--;
    const near = d.times[Math.max(i, 0)];
    const x = (near - d.from) / ((d.to - d.from) || 1);
    const rows = d.series.filter(s => !s.hidden && s.values.has(near)).map(s =>
        '<div><span class="bar-swatch" style="background:' + s.color + '"></span> ' + AC.esc(s.name)
            + ' <b>' + AC.esc(sliceText(Math.round(s.values.get(near) * 1000) / 1000)) + '</b></div>').join('');
    line.style.display = 'block';
    line.style.left = (x * 100) + '%';
    tip.style.display = 'block';
    tip.innerHTML = '<div class="ts-tip-time">' + AC.esc(seriesLabel(at.control, near))
        + (d.bucket !== 'NONE' ? ' · ' + AC.esc(tsBucketLabel(d.bucket)) : '') + '</div>' + (rows || '<div>no value</div>');
    tip.style.left = x > 0.6 ? '' : 'calc(' + (x * 100) + '% + 10px)';
    tip.style.right = x > 0.6 ? 'calc(' + ((1 - x) * 100) + '% + 10px)' : '';
}

/**
 * A pie's slices in the properties panel — the same key/value rows a select's static option list
 * uses, since it is the same shape of thing: a fixed list typed in by hand. What differs is that
 * the value here has to be a number, so a row that is not one is marked as it is typed rather
 * than waiting for the save to refuse the page.
 */
function pieProps(c) {
    const slices = c.slices || [];
    let html = '<div class="props-section"><div class="props-title"><span>Slices</span></div>'
        + '<div class="form-group"><label>Name / Value</label>';
    html += slices.map((slice, i) => {
        const value = sliceNumber(slice.value);
        const shown = String(slice.value === undefined || slice.value === null ? '' : slice.value).trim();
        // Blank is a row not filled in yet rather than a mistake, so only something typed and
        // unusable is marked.
        const bad = shown && (!Number.isFinite(value) || value < 0);
        return '<div class="opt-row">'
            + '<input type="text" placeholder="name" value="' + AC.attr(slice.key || '') + '" oninput="setSlice(' + i + ', \'key\', this.value)">'
            + '<input type="text" placeholder="number" value="' + AC.attr(shown) + '"'
                + (bad ? ' style="border-color:#de350b"' : '') + ' oninput="setSlice(' + i + ', \'value\', this.value)">'
            + '<button class="icon-btn" onclick="removeSlice(' + i + ')" title="Remove">×</button>'
        + '</div>';
    }).join('');
    return html
        + '<button class="tool-btn" onclick="addSlice()">+ Add Slice</button>'
        + '<span class="hint">Typed in here, these are what the chart draws until an action fills it: aim '
        + 'one at this chart and the rows it binds become the wedges instead, a row per wedge. These stay '
        + 'where they are and come back the moment the action is taken off or the page is reset, so a chart '
        + 'can be laid out with sample numbers and wired up afterwards.</span>'
        + '<span class="hint">The name labels the wedge; the value is its size and has to be a number — '
        + '<code>42</code>, <code>3.5</code>, <code>0</code>. Each wedge is its value\'s share of them all, so any '
        + 'unit works as long as the whole list is in it. A slice that is not a number is left off the chart, '
        + 'and the page will not save with one on it.</span></div></div>';
}

/**
 * Colours worth offering in the box rather than made up on the spot: the four a status chart is
 * actually about, a neutral, and the palette's own versions of each for anyone who would rather
 * the named wedges matched the unnamed ones exactly.
 */
const COLOR_SUGGESTIONS = ['green', 'red', 'orange', 'blue', 'grey',
                           '#00875a', '#de350b', '#ff8b00', '#0052cc', '#5e6c84'];

/**
 * The colours a pie gives slices by name — <b>UP</b> green, <b>DOWN</b> red.
 *
 * <p>Kept apart from the slice list above it because it is a different kind of statement, and on
 * a pie filled from a call there is no slice list to hang it off at all: the numbers arrive from
 * the endpoint, and what is being said here is about the names they will arrive under. So a name
 * that matches nothing on screen today is not a mistake and is not marked as one — it is the
 * ordinary case, waiting for a run that has a DOWN in it.
 */
function sliceColorProps(c) {
    const colors = c.sliceColors || [];
    let html = '<div class="props-section"><div class="props-title"><span>Slice Colours</span>'
        + '<button class="tool-btn" onclick="addSliceColor()">+ Add</button></div>'
        + '<datalist id="sliceColorList">'
        + COLOR_SUGGESTIONS.map(x => '<option value="' + AC.attr(x) + '"></option>').join('')
        + '</datalist>';
    if (!colors.length) {
        html += '<div class="empty-note">Every wedge takes the chart' + Q + 's own palette, in the order the '
             + 'slices arrive.</div>';
    }
    html += colors.map((entry, i) => {
        const typed = String(entry.value === undefined || entry.value === null ? '' : entry.value).trim();
        const color = cssColor(typed).trim();
        return '<div class="color-row">'
            + '<input type="text" placeholder="slice name" value="' + AC.attr(entry.key || '') + '"'
                + ' oninput="setSliceColor(' + i + ', \'key\', this.value)">'
            + '<input type="text" list="sliceColorList" placeholder="green, #36b37e" value="' + AC.attr(typed) + '"'
                + (typed && !color ? ' style="border-color:#de350b"' : '')
                + ' oninput="setSliceColor(' + i + ', \'value\', this.value)">'
            + '<span class="color-chip' + (color ? '' : ' none') + '"'
                + (color ? ' style="background:' + AC.esc(color) + '"' : '')
                + ' title="' + AC.attr(color || 'not a colour this can use') + '"></span>'
            + '<button class="icon-btn" onclick="removeSliceColor(' + i + ')" title="Remove">×</button>'
        + '</div>';
    }).join('');
    return html
        + '<span class="hint">A slice name and the colour its wedge is drawn in — <code>UP</code> green, '
        + '<code>DOWN</code> red. Names match regardless of case, and the colour holds wherever that slice '
        + 'lands in the order, so a response that comes back with DOWN first does not recolour the chart. '
        + 'A slice not named here keeps the palette' + Q + 's next colour, so colouring the two that matter '
        + 'and leaving the rest alone is a complete thing to do.</span>'
        + '<span class="hint">Any CSS colour: a name (<code>green</code>), a hex (<code>#36b37e</code>) or a '
        + 'function (<code>rgb(0,135,90)</code>). The chip beside the box is what it comes out as.</span></div>';
}

function addSliceColor() {
    const c = findControl(selectedId);
    c.sliceColors = c.sliceColors || [];
    c.sliceColors.push({ key: '', value: '' });
    renderProps();
    renderCanvas();
}

/**
 * A pie's error check: which of its wedges are wrong.
 *
 * <p>The grid's row check, turned on the one thing a pie has instead of rows. A grid answers "did
 * the call work" and "are the rows right" separately, and a pie had only the first — so a status
 * pie with a fat red DOWN wedge in it reported <b>success</b>, because the call that drew it had
 * worked. That is the gap this closes, and it matters most where the chart is a tab: the strip is
 * all that is on screen for a tab that is not the one showing, so a tab that goes green on the
 * call alone is a tab nobody needs to open and shouldn't trust.
 *
 * <p>Over the wedge rather than over the row behind it, because the wedge is what a pie is and is
 * the thing that survives every way a pie can be filled — one row per wedge, or a tally of many
 * rows into a few. <code>NAME</code> and <code>VALUE</code> are always there; a wedge that did
 * come from one row can also be tested by that row's own columns.
 */
function sliceCheckProps(c) {
    return '<div class="props-section"><div class="props-title"><span>Error Check</span></div>'
        + field('Slices In Error', '<input type="text" value="' + AC.attr(c.sliceErrorExpression || '')
                + '" placeholder="NAME != SUCCESS &amp;&amp; VALUE &gt; 0" oninput="setSliceCheck(this.value)">',
            'Optional. Every wedge is put through this as the chart is drawn; a wedge it comes out <b>true</b> for '
            + 'is an error, marked in the legend, and the chart' + Q + 's name carries the tally — <b>2 ERROR / 5 '
            + 'SUCCESS</b>. Laid out as a tab, that verdict is what the tab shows, so the tab is green only when the '
            + 'wedges behind it actually are.')
        + '<div id="sliceCheckNote">' + sliceCheckNote(c) + '</div>'
        + '<span class="hint"><code>NAME</code> is the wedge' + Q + 's name and <code>VALUE</code> its number, '
        + 'whatever the chart was filled from. Where each wedge came from a single row — one row per slice, rather '
        + 'than a tally of many — that row' + Q + 's own columns can be named too. Same tests and joins as a grid' + Q
        + 's error check.</span>'
        + '<span class="hint">Separate from whether the call worked, exactly as a grid' + Q + 's is: five wedges '
        + 'back with two of them wrong is a successful call and a failed run. A call that failed outright outranks '
        + 'the check — it left no wedges, and none is not the same as none wrong.</span></div>';
}

/** Whether what has been typed into the slice check can be read, said under the box. */
function sliceCheckNote(c) {
    const expression = ((c && c.sliceErrorExpression) || '').trim();
    if (!expression) return '';
    const parsed = parseRowCheck(expression);
    return parsed.ok
        ? '<span class="hint" style="color:#006644">Reads as a slice check.</span>'
        : '<span class="hint" style="color:#bf2600">This cannot be read: ' + AC.esc(parsed.error)
            + '. The page will not save until it can.</span>';
}

/** Kept up with the typing the same way a grid's row check is — see {@link #setRowCheck}. */
function setSliceCheck(text) {
    const c = findControl(selectedId);
    if (!c) return;
    c.sliceErrorExpression = text;
    const note = document.getElementById('sliceCheckNote');
    if (note) note.innerHTML = sliceCheckNote(c);
    renderCanvas();
}

/**
 * Redraws the canvas so the chart follows what is typed, and moves the chip beside the box by
 * hand. Redrawing the panel instead would take the caret out of the box being typed into, which
 * is why every other list on this screen leaves it alone — the chip is the one part of it that
 * has to keep up, since seeing the colour is the whole reason for typing one.
 */
function setSliceColor(index, name, value) {
    const c = findControl(selectedId);
    if (!c || !(c.sliceColors || [])[index]) return;
    c.sliceColors[index][name] = value;
    if (name === 'value') {
        const row = document.getElementById('props').querySelectorAll('.color-row')[index];
        const chip = row && row.querySelector('.color-chip');
        const color = cssColor(value).trim();
        if (chip) {
            chip.classList.toggle('none', !color);
            chip.setAttribute('style', color ? 'background:' + color : '');
            chip.title = color || 'not a colour this can use';
        }
    }
    renderCanvas();
}

function removeSliceColor(index) {
    const c = findControl(selectedId);
    c.sliceColors.splice(index, 1);
    renderProps();
    renderCanvas();
}

function addSlice() {
    const c = findControl(selectedId);
    c.slices = c.slices || [];
    c.slices.push({ key: '', value: '' });
    renderProps();
    renderCanvas();
}

/** Redraws the canvas so the chart follows what is typed, but not the panel — that takes the caret. */
function setSlice(index, name, value) {
    const c = findControl(selectedId);
    c.slices[index][name] = value;
    renderControlList();
    renderCanvas();
}

function removeSlice(index) {
    const c = findControl(selectedId);
    c.slices.splice(index, 1);
    renderProps();
    renderCanvas();
}

// ── Placement: drag, drop, resize ────────────────────────────────────────

const canvasEl = document.getElementById('canvas');

canvasEl.addEventListener('dragover', e => {
    e.preventDefault();
    canvasEl.classList.add('drag-over');
});
canvasEl.addEventListener('dragleave', () => canvasEl.classList.remove('drag-over'));
canvasEl.addEventListener('drop', e => {
    e.preventDefault();
    canvasEl.classList.remove('drag-over');

    const payload = e.dataTransfer.getData('text/plain') || '';
    const cell = cellAt(e.clientX, e.clientY);

    if (payload.startsWith('new:')) {
        addControl(payload.slice(4), cell);
    } else if (payload.startsWith('chip:')) {
        // A grid dragged out of a tab set and onto the layout: it goes back to being a control
        // on the page, at the cell it was let go over.
        detachFromTabs(payload.slice(5), cell);
    } else if (payload.startsWith('group:')) {
        moveGroup(payload.slice(6), cell);
    } else if (payload.startsWith('move:')) {
        const control = findControl(payload.slice(5));
        if (!control) return;
        control.row = cell.row;
        control.col = Math.min(cell.col, COLUMNS - control.span);
        renderAll();
    }
});

/**
 * Moves everything selected by however far the one being dragged has moved.
 *
 * <p>By a distance rather than to a place, which is the whole of what makes it useful: a form of
 * six fields dragged down two rows is still that form, in the same shape, two rows down. Dropping
 * them all at the cell the pointer is over would stack six controls on top of each other.
 *
 * <p>The distance is then held to what the canvas can take — nothing may be pushed above the
 * first row or past either edge — and held once, for the group. Clamping each control on its own
 * would let the ones with room move while the one at the edge stayed put, which pulls the shape
 * apart exactly when the drag is the thing meant to preserve it. So the whole move gives way to
 * its most constrained member, and the group arrives in the shape it left in.
 */
function moveGroup(anchorId, cell) {
    const anchor = findControl(anchorId);
    const moving = selectedControls();
    if (!anchor || !moving.length) return;

    const half = value => Math.round(value * 2) / 2;
    let dRow = half(cell.row - anchor.row);
    let dCol = Math.min(cell.col, COLUMNS - anchor.span) - anchor.col;

    // As far as the group may go before its nearest member reaches an edge.
    moving.forEach(c => {
        dRow = Math.max(dRow, -(c.row || 0));
        dCol = Math.max(dCol, -c.col);
        dCol = Math.min(dCol, COLUMNS - c.span - c.col);
    });
    if (!dRow && !dCol) return;

    moving.forEach(c => {
        c.row = half((c.row || 0) + dRow);
        c.col = c.col + dCol;
    });
    renderAll();
    AC.setStatus('statusBar', moving.length + ' controls moved.', 'ok');
}

// ── Picking out several controls at once ─────────────────────────────────
// Press on the canvas where there is nothing and drag: everything the band touches is selected,
// and dragging any one of them afterwards moves the lot. The band catches a control it merely
// overlaps rather than only ones it encloses, because a layout is a grid of boxes that touch —
// requiring full enclosure would mean drawing the band exactly along seams the eye cannot see,
// and a band that misses what it was plainly drawn over is worse than one that takes a little
// extra the ctrl-click can put back.

/** How far the pointer has to travel before a press on the canvas is a band and not a click. */
const MARQUEE_SLOP = 4;
let marquee = null;

canvasEl.addEventListener('mousedown', e => {
    // Left button, on the canvas rather than on anything drawn on it: a press that starts on a
    // control is that control being dragged or resized, and belongs to it.
    if (e.button !== 0 || (e.target.closest && e.target.closest('.dctl'))) return;
    const box = document.createElement('div');
    box.className = 'marquee';
    canvasEl.appendChild(box);
    marquee = { x: e.clientX, y: e.clientY, box: box, moved: false,
                add: e.ctrlKey || e.metaKey || e.shiftKey };
    // Otherwise the press selects the text of every label it is dragged across, which on a canvas
    // of controls is the whole page going blue behind the band.
    e.preventDefault();
});

document.addEventListener('mousemove', e => {
    if (!marquee) return;
    if (Math.abs(e.clientX - marquee.x) > MARQUEE_SLOP || Math.abs(e.clientY - marquee.y) > MARQUEE_SLOP) {
        marquee.moved = true;
    }
    if (!marquee.moved) return;
    const rect = canvasEl.getBoundingClientRect();
    const left = Math.min(e.clientX, marquee.x), right = Math.max(e.clientX, marquee.x);
    const top = Math.min(e.clientY, marquee.y), bottom = Math.max(e.clientY, marquee.y);
    Object.assign(marquee.box.style, {
        display: 'block',
        left: (left - rect.left) + 'px',
        top: (top - rect.top) + 'px',
        width: (right - left) + 'px',
        height: (bottom - top) + 'px'
    });
    marquee.band = { left, right, top, bottom };
});

document.addEventListener('mouseup', e => {
    if (!marquee) return;
    const band = marquee.moved ? marquee.band : null;
    const add = marquee.add;
    marquee.box.remove();
    marquee = null;

    // A press that never moved is a click on the empty canvas: it puts the selection down, which
    // is what shows the page's own panel again and the only way back to it once a control has
    // been picked.
    if (!band) { if (!add) setSelection([]); return; }

    const caught = [...canvasEl.querySelectorAll('.dctl')]
        .filter(el => overlaps(el.getBoundingClientRect(), band))
        .map(el => el.dataset.id);
    // Held down, the band adds to what is already picked rather than replacing it — so a group
    // can be gathered from two corners of a page that will not fit under one band.
    const ids = add ? [...selectedIds.size ? selectedIds : (selectedId ? [selectedId] : []), ...caught] : caught;
    setSelection([...new Set(ids)]);
    if (selectedIds.size > 1) AC.setStatus('statusBar', selectedIds.size + ' controls selected — '
        + 'drag any one of them to move them together.', 'ok');
});

/** Whether a control's box and the band the pointer drew have any part in common. */
function overlaps(box, band) {
    return box.right > band.left && box.left < band.right
        && box.bottom > band.top && box.top < band.bottom;
}

// Escape puts a group down without having to find empty canvas to click, which on a page that
// fills its layout there may not be any of.
document.addEventListener('keydown', e => {
    if (e.key !== 'Escape' || mode !== 'design' || selectedIds.size < 2) return;
    if (document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) return;
    setSelection([]);
});

/**
 * Turns a pointer position into the row/column of the cell under it.
 *
 * <p>The row comes back in half-row steps, because that is how finely the layout is drawn: a
 * control is half a row tall by default, so a drop that could only land on whole rows would
 * leave half a row of air under every field, and the only way to close it up would be typing
 * numbers into the properties panel. Dropped between the halves of row one, it lands at 1.5.
 */
function cellAt(clientX, clientY, host) {
    const rect = (host || canvasEl).getBoundingClientRect();
    const pad = host ? 0 : 10;                            // the canvas' own 10px padding
    const usable = rect.width - pad * 2;
    const col = Math.floor((clientX - rect.left - pad) / (usable / COLUMNS));
    const row = Math.floor((clientY - rect.top - pad) / (ROW_PITCH / 2)) / 2;
    return { row: Math.max(0, row), col: Math.min(Math.max(0, col), COLUMNS - 1) };
}

function startResize(e, controlId) {
    e.preventDefault();
    e.stopPropagation();
    const control = findControl(controlId);
    if (!control) return;

    const cellWidth = (canvasEl.getBoundingClientRect().width - 20) / COLUMNS;
    const startX = e.clientX;
    const startSpan = control.span;

    function onMove(move) {
        const span = startSpan + Math.round((move.clientX - startX) / cellWidth);
        const clamped = Math.min(Math.max(span, 1), COLUMNS - control.col);
        if (clamped !== control.span) { control.span = clamped; renderCanvas(); }
    }
    function onUp() {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        renderAll();
    }
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
}

/**
 * Drags the bottom edge to change height. Snaps to half a row, which is as thin as a control
 * goes — enough for a link or a one-line label without a whole row's worth of padding.
 */
function startResizeHeight(e, controlId) {
    e.preventDefault();
    e.stopPropagation();
    const control = findControl(controlId);
    if (!control) return;

    const startY = e.clientY;
    const startSpan = rowSpanOf(control);

    function onMove(move) {
        const moved = (move.clientY - startY) / ROW_PITCH;
        const span = Math.round((startSpan + moved) * 2) / 2;
        const clamped = Math.min(Math.max(span, MIN_ROW_SPAN), MAX_ROW_SPAN);
        if (clamped !== rowSpanOf(control)) { control.rowSpan = clamped; renderCanvas(); }
    }
    function onUp() {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
        renderAll();
    }
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
}

/**
 * Puts a new control on the page and selects it, handing back its id.
 *
 * @param quiet when true the caller redraws — a grid created straight into a tab set is put in
 *              the set before anything is drawn, so the canvas never flashes it onto the layout
 */
function addControl(type, cell, quiet) {
    const control = {
        controlId: 'c-' + Math.random().toString(36).slice(2, 10),
        fieldName: VALUE_TYPES.includes(type) ? nextFieldName(type) : '',
        label: type === 'button' ? 'Run' : type === 'tabs' ? 'Tabs'
            : type === 'multibutton' ? 'Actions' : type === 'panel' ? 'Panel'
            : type.charAt(0).toUpperCase() + type.slice(1),
        type: type,
        // A box is set off by its value changing and a button by being clicked — the defaults
        // that need no visit to the properties panel. Written down rather than left undefined
        // because Click now means something on a box too: its label becomes the link that runs
        // it, and a control that had never said which it wanted would have picked that by
        // accident. See #labelTriggers.
        trigger: ACTION_TYPES.includes(type) ? 'CLICK' : 'CHANGE',
        defaultValue: '',
        mandatory: false,
        placeholder: '',
        helpText: '',
        color: '',
        row: cell.row,
        col: cell.col,
        span: type === 'grid' || type === 'tabs' || type === 'page' ? COLUMNS
            : type === 'panel' ? 12
            : type === 'button' || type === 'multibutton' ? 4 : type === 'pie' || type === 'bar' ? 8
            : type === 'piegrid' || isSeries(type) ? 12 : 6,
        rowSpan: defaultRowSpan(type),
        optionSource: isSelect(type) ? { mode: 'NONE', staticOptions: [], appUseCaseInstanceId: '', arrayPath: '', keyField: '', labelField: '', appName: '', sortOrder: 'NONE', selectFirst: false } : null,
        actions: [],
        assignments: [],
        dateFormat: '',
        columns: [],
        leadColumns: [],
        hiddenColumns: [],
        wrapText: false,
        columnLinks: [],
        rowClick: null,
        rowErrorExpression: '',
        displayFilterExpression: '',
        statusCondition: '',
        statusVariable: '',
        sortColumn: '',
        sortDirection: 'ASC',
        topRows: 0,
        slices: [],
        sliceColors: [],
        sliceErrorExpression: '',
        tabControlIds: [],
        panelControlIds: [],
        menuOptions: [],
        defaultTabControlId: '',
        tabsControlId: '',
        orientation: 'VERTICAL',
        sourceGridControlId: '',
        gridKeyField: '',
        gridValueField: '',
        timeField: '',
        timeFormat: '',
        timeBucket: 'AUTO',
        timeOffsetField: '',
        timeOffsetUnit: 'SECONDS',
        timeAggregate: 'SUM',
        chartFilters: [],
        xField: '',
        childPageName: ''
    };
    control.col = Math.min(control.col, COLUMNS - control.span);
    page.controls.push(control);
    selectedId = control.controlId;
    if (!quiet) renderAll();
    return control.controlId;
}

function nextFieldName(type) {
    const taken = page.controls.map(c => c.fieldName);
    let n = 1;
    while (taken.includes(type + n)) n++;
    return type + n;
}

function findControl(controlId) {
    return page.controls.find(c => c.controlId === controlId) || null;
}

function selectControl(controlId) {
    // Clicking a control is asking about that control, so the panel goes back to the half that
    // can answer. The variables tab is about the page and is still one click away.
    propsTab = 'props';
    setSelection([controlId]);
}

/**
 * Whether a control is picked out on the canvas, by either route — the one the properties panel
 * is about, or one of a band-selected group.
 */
function isSelected(controlId) {
    return controlId === selectedId || selectedIds.has(controlId);
}

/**
 * Puts the selection where it is being asked to go, and redraws everything that shows it.
 *
 * <p>The one place either half of the selection is written, so the two cannot drift apart. The
 * properties panel is about the last id in the list, which on a band is the last control the band
 * caught and on a click is the control clicked — a group still has one control whose settings are
 * on screen, so a selection of six is not a panel with nothing in it.
 */
function setSelection(ids) {
    const live = (ids || []).filter(id => findControl(id));
    selectedIds = new Set(live.length > 1 ? live : []);
    selectedId = live.length ? live[live.length - 1] : null;
    renderControlList();
    renderCanvas();
    renderProps();
}

/**
 * Adds a control to the selection or takes it out again — what a ctrl-click (or a shift-click)
 * on the canvas does, for building a group up a control at a time where a band would have caught
 * something in the middle that should stay where it is.
 */
function toggleSelection(controlId) {
    const ids = [...selectedIds];
    // A single selection is held in selectedId alone, so ctrl-clicking a second control has to
    // start from the first rather than from an empty set.
    if (!ids.length && selectedId) ids.push(selectedId);
    const at = ids.indexOf(controlId);
    if (at >= 0) ids.splice(at, 1);
    else ids.push(controlId);
    propsTab = 'props';
    setSelection(ids);
}

/** Everything currently selected that is really on the layout, as controls. */
function selectedControls() {
    return [...selectedIds].map(findControl).filter(c => c && !heldBy(c.controlId));
}

/**
 * A copy of the selected control, placed just below it — or beside it, when it is a tab of a tab
 * set — with everything it was set up with: its settings, what it writes into, the page actions it
 * triggers, and its own actions.
 *
 * <p>What has to be unique does not come along as it is. The copy takes its own control id, its own
 * field name (a template names a control by it, and two answering to one would make ${name} mean
 * either), a label saying it is a copy, and its own action ids — with a "Runs After" between two of
 * its own actions pointed at the copies, so the copy's chain is its own rather than half the
 * original's. A grid's status variable is a name as well and is cleared for the same reason, and a
 * tab set's tabs are left behind: a grid is in one tab set or another, never both.
 */
function cloneControl() {
    const source = findControl(selectedId);
    if (!source) return;
    const copy = cloneValue(source);
    copy.controlId = 'c-' + Math.random().toString(36).slice(2, 10);
    if (source.fieldName) copy.fieldName = uniqueFieldName(source.fieldName);
    copy.label = copyLabel(source.label || controlTitle(source), page.controls.map(c => c.label || ''));
    const notes = [];

    const ids = new Map();
    (copy.actions || []).forEach(a => {
        const fresh = newActionId();
        ids.set(a.actionId, fresh);
        a.actionId = fresh;
    });
    (copy.actions || []).forEach(a => {
        if (a.dependsOnActionId && ids.has(a.dependsOnActionId)) a.dependsOnActionId = ids.get(a.dependsOnActionId);
    });

    if (copy.statusVariable) { copy.statusVariable = ''; notes.push('its status variable was cleared — names must be unique'); }
    if (copy.type === 'tabs' && (copy.tabControlIds || []).length) {
        copy.tabControlIds = [];
        copy.defaultTabControlId = '';
        notes.push('its tabs stay with the original — drop grids into the copy');
    }
    // And a panel's contents, for the same reason and in the same words: a control is drawn in
    // one container or another, never both, so the copy opens as an empty box to drop into.
    if (copy.type === 'panel' && (copy.panelControlIds || []).length) {
        copy.panelControlIds = [];
        notes.push('the controls inside it stay with the original — drop controls into the copy');
    }

    const holder = heldBy(source.controlId);
    if (holder) {
        // A tab of a tab set, or a control in a panel: the copy goes in beside it, in the same
        // container. A panel's copy keeps the row and column it was cloned with, which is what
        // puts it under the original inside the box rather than on top of it — see below.
        const siblings = childIdsOf(holder);
        siblings.splice(siblings.indexOf(source.controlId) + 1, 0, copy.controlId);
        if (holder.type === 'panel') copy.row = (source.row || 0) + rowSpanOf(source);
    } else {
        // Its own height below it, half rows and all: a half-row field clones onto the next half
        // row rather than skipping one and leaving the gap the designer would have to close.
        copy.row = (source.row || 0) + rowSpanOf(source);
    }
    page.controls.splice(page.controls.indexOf(source) + 1, 0, copy);
    selectedId = copy.controlId;
    renderAll();
    AC.setStatus('statusBar', 'Cloned as "' + controlTitle(copy) + '"' + (notes.length ? ' — ' + notes.join('; ') : '') + '.', 'ok');
}

/** A field name no other control on the page has: the original's with a number after it. */
function uniqueFieldName(base) {
    const taken = page.controls.map(c => c.fieldName).filter(Boolean);
    const stem = String(base).replace(/\d+$/, '') || 'field';
    let n = 2;
    while (taken.includes(stem + n)) n++;
    return stem + n;
}

function deleteControl(asked) {
    const control = findControl(selectedId);
    // `asked` is a group removal, which has confirmed the whole list once already — see
    // #deleteSelection. Asking again, six times, is how a confirmation stops being read.
    if (!control || (!asked && !confirm('Remove "' + controlTitle(control) + '" from the page?'))) return;
    page.controls = page.controls.filter(c => c.controlId !== selectedId);
    // Any action pointing at it would save as a dangling target, so drop the reference too —
    // from the page's library as much as from the controls, since either can name it.
    const clearTarget = a => {
        if (a.targetControlId === selectedId) a.targetControlId = '';
        // And the grid it read its rows from: an action fanning out over a grid that is gone has
        // nothing to run over, and would save naming a control that is not on the page.
        if (a.rowSourceControlId === selectedId) { a.rowSourceControlId = ''; a.rowOutputMode = 'ROWS'; }
        // A further target is nothing but its control, so it goes altogether, as an assignment does.
        a.extraBindings = (a.extraBindings || []).filter(b => b.targetControlId !== selectedId);
        // A lookup into the grid that is gone has nothing to look into, and goes.
        repointGridLookups(a, id => id === selectedId ? '' : id);
    };
    page.controls.forEach(c => (c.actions || []).forEach(clearTarget));
    (page.actions || []).forEach(clearTarget);
    // An assignment that named it goes altogether rather than being blanked: an action with no
    // target is still a call that runs, where an assignment with no target is nothing at all.
    page.controls.forEach(c => { c.assignments = (c.assignments || []).filter(a => a.targetControlId !== selectedId); });
    // And the same for what a grid's clickable columns wrote into, which is the same kind of
    // assignment one level further in.
    page.controls.forEach(c => (c.columnLinks || []).forEach(link => {
        link.assignments = (link.assignments || []).filter(a => a.targetControlId !== selectedId);
    }));
    // And what a grid's clickable rows wrote into, which is the same assignment again.
    page.controls.forEach(c => {
        if (!c.rowClick) return;
        c.rowClick.assignments = (c.rowClick.assignments || []).filter(a => a.targetControlId !== selectedId);
    });
    // A tab set naming a grid that is gone would save as a tab with nothing behind it. Deleting
    // the tab set itself needs no such tidying: its grids keep their own row and column, so they
    // simply reappear on the layout where they were before they became tabs.
    page.controls.forEach(c => {
        if (c.type === 'tabs')  c.tabControlIds   = (c.tabControlIds || []).filter(id => id !== selectedId);
        // A panel naming a control that is gone would draw a gap in its layout, so it goes the
        // same way. Deleting the panel itself needs no such tidying: what was in it keeps its own
        // row and column, so it simply reappears on the layout where those numbers put it.
        if (c.type === 'panel') c.panelControlIds = (c.panelControlIds || []).filter(id => id !== selectedId);
        // A pie with grids whose tab set has gone has nowhere to put them until another is picked.
        if (c.tabsControlId === selectedId) c.tabsControlId = '';
        // A chart drawn from a grid that is gone goes back to being filled by its actions.
        if (c.sourceGridControlId === selectedId) c.sourceGridControlId = '';
        // And a trigger that scrolled to it goes back to leaving the operator where they are —
        // the save refuses a control naming one that is not on the page.
        if (c.focusControlId === selectedId) c.focusControlId = '';
    });
    selectedId = null;
    renderAll();
}

// ── Properties panel ─────────────────────────────────────────────────────

/** The panel's two tabs, with the count so an empty variable list is obvious from the strip. */
function renderPropsTabs() {
    const count = (page.variables || []).length;
    const tabs = [
        { id: 'props',     label: 'Properties' },
        { id: 'variables', label: 'Variables' + (count ? ' (' + count + ')' : '') }
    ];
    document.getElementById('propsTabs').innerHTML = tabs.map(t =>
        '<button class="props-tab' + (t.id === propsTab ? ' active' : '') + '"'
            + ' onclick="selectPropsTab(\'' + t.id + '\')">' + AC.esc(t.label) + '</button>').join('');
}

function selectPropsTab(id) {
    propsTab = id;
    renderProps();
}

function renderProps() {
    renderPageActionsButton();
    renderPropsTabs();
    const host = document.getElementById('props');
    if (propsTab === 'variables') { host.innerHTML = variableProps(); return; }
    // Several controls picked out at once is a different question from any one of them, so it
    // gets a different panel — what is in the group, and the two things worth doing to a group.
    if (selectedIds.size > 1) { host.innerHTML = groupProps(); return; }
    const c = findControl(selectedId);
    if (!c) {
        host.innerHTML = '<div class="empty-note">Select a control to edit it, or drag a new one onto the layout. '
            + 'Below is the page itself: the actions any control can trigger, and the transforms they may reshape a '
            + 'response with.</div>'
            + pageProps();
        return;
    }

    const isValue = VALUE_TYPES.includes(c.type);
    let html = '<div class="stack mini">';

    html += field('Label', '<input type="text" value="' + AC.attr(c.label || '') + '" oninput="setProp(\'label\', this.value)">');
    html += field('Color', '<input type="text" value="' + AC.attr(c.color || '') + '" placeholder="blue, #d63384, rgb(0,82,204)" oninput="setProp(\'color\', this.value)">',
        'CSS color applied to this control\'s label and value when the page runs.');
    if (isValue) {
        html += field('Field Name', '<input type="text" value="' + AC.attr(c.fieldName || '') + '" oninput="setProp(\'fieldName\', this.value)">',
            'How actions refer to this value: <code>${' + AC.esc(c.fieldName || 'name') + '}</code>');
    }
    html += field('Type', typeSelect(c));

    if (c.type === 'date') html += dateFormatProp(c) + datePresetProp(c);
    if (isValue || c.type === 'label') {
        html += field('Default Value', '<input type="text" value="' + AC.attr(c.defaultValue || '') + '" oninput="setProp(\'defaultValue\', this.value)">');
    }
    if (c.type === 'date') html += dateDefaultNote(c);
    if (c.type === 'link') html += linkProps(c);
    if (['text', 'textarea', 'number', 'date'].includes(c.type)) {
        html += field('Placeholder', '<input type="text" value="' + AC.attr(c.placeholder || '') + '" oninput="setProp(\'placeholder\', this.value)">');
    }
    if (c.type === 'textarea') {
        const format = c.textFormat || 'NONE';
        html += field('Format', '<select onchange="setProp(\'textFormat\', this.value)">'
            + TEXT_FORMATS.map(f => '<option value="' + f.id + '"' + (f.id === format ? ' selected' : '') + '>'
                + AC.esc(f.label) + '</option>').join('')
            + '</select>',
            'Applied to whatever an action or an assignment puts into the box. Text that does not parse as '
            + 'the format chosen goes in as it came.');
    }
    if (isValue) {
        html += '<label class="inline-check"><input type="checkbox"' + (c.mandatory ? ' checked' : '')
             + ' onchange="setProp(\'mandatory\', this.checked)"> Mandatory</label>';
        html += field('Help Text', '<input type="text" value="' + AC.attr(c.helpText || '') + '" oninput="setProp(\'helpText\', this.value)">');
    }

    const holder = heldBy(c.controlId);
    html += containerProp(c, holder);
    if (holder && holder.type === 'tabs') {
        html += '<div class="empty-note">Laid out as a tab of <b>' + AC.esc(controlTitle(holder)) + '</b>, so it fills '
             + 'that tab rather than taking a place of its own. Its row and column are kept: take it out of the tabs '
             + 'and it goes back where it was.</div>';
    } else {
        // A control inside a panel is laid out exactly as one on the page is, on the same
        // twenty-four columns and the same half rows — the panel is simply the grid it is laid
        // out on. So the same four boxes, and only the note under them changes.
        html += '<div class="form-row" style="margin-bottom:0">'
             + field('Row', '<input type="number" min="0" step="0.5" value="' + c.row + '" oninput="setProp(\'row\', +this.value)">')
             + field('Column', '<input type="number" min="0" max="' + (COLUMNS - c.span) + '" value="' + c.col + '" oninput="setProp(\'col\', +this.value)">')
             + field('Width', '<input type="number" min="1" max="' + (COLUMNS - c.col) + '" value="' + c.span + '" oninput="setProp(\'span\', +this.value)">')
             + field('Height', '<input type="number" min="0.5" max="' + MAX_ROW_SPAN + '" step="0.5" value="' + rowSpanOf(c) + '" oninput="setProp(\'rowSpan\', +this.value)">')
             + '</div>'
             + (holder ? '<span class="hint" style="margin-top:-4px">Laid out inside the panel <b>'
                    + AC.esc(controlTitle(holder)) + '</b>: the row and column are places in that '
                    + 'panel rather than on the page, and the panel keeps them if it is moved. Take '
                    + 'it out of the panel and it goes onto the layout at the same row and column.</span>'
                : '')
             + '<span class="hint" style="margin-top:-4px">Row and height are both in rows, and both go in halves. '
             + 'A control starts half a row tall, so two of them stacked at rows 1 and 1.5 fill one row of page '
             + 'between them rather than two — which is what lets a form be as tight as it reads. Height runs up to '
             + MAX_ROW_SPAN + ', and a text area, a grid or a pie chart fills the height it is given when the page '
             + 'runs: a text area set to 20 opens twenty rows deep rather than needing to be dragged open.</span>';
    }

    if (isSelect(c.type)) html += selectProps(c);
    if (c.type === 'grid')   html += gridProps(c);
    if (c.type === 'tabs')   html += tabsProps(c);
    if (c.type === 'panel')  html += panelProps(c);
    if (c.type === 'multibutton') html += menuProps(c);
    if (c.type === 'pie')    html += pieProps(c);
    if (c.type === 'piegrid') html += pieGridProps(c);
    if (c.type === 'pie' || c.type === 'piegrid') html += sliceColorProps(c) + sliceCheckProps(c);
    if (c.type === 'bar')    html += barProps(c);
    if (isSeries(c.type)) html += seriesProps(c);
    if (isChart(c.type))     html += chartGridSourceProps(c);
    if (c.type === 'page')   html += childPageProps(c);
    // Drawn in the order they run: what the control sets, then what it triggers.
    if (!TRIGGERLESS_TYPES.includes(c.type)) html += assignProps(c) + triggerProps(c);
    if (ACTION_TYPES.includes(c.type)) html += buttonProps(c);
    // And last, because it is what happens after all of it has finished.
    if (triggersSomething(c)) html += focusProps(c);

    html += '<div class="toolbar" style="margin-top:10px">'
        + '<button class="secondary" onclick="cloneControl()" title="Add a copy of this control, with its settings and actions, below it">Clone Control</button>'
        + '<button class="danger" onclick="deleteControl()">Remove Control</button></div>';
    host.innerHTML = html + '</div>';
}

/**
 * Where this control is drawn: on the page itself, or inside one of the page's containers.
 *
 * <p>The move the canvas already makes by dragging, in a list — because dragging only works
 * while both ends of it are on screen at once, and the two moves that are wanted most often are
 * the two that are hardest to aim: a control out of a tab, where the layout it is going back to
 * is behind the tab set, and a control from one tab of a long strip to another, where the strip
 * may not even be the same strip. Picking the name out of a list is the same move with nothing
 * to aim at.
 *
 * <p>Only containers that could actually hold it are listed — see {@link #containerRefusal} —
 * so the list never offers a move the save would refuse. Nothing appears at all on a page with
 * no containers on it, which is most pages.
 */
function containerProp(c, holder) {
    const choices = containerChoices(c);
    const here = holder ? holder.controlId : '';
    if (!choices.length && !holder) return '';
    // A page saved before one of the refusals existed could be holding this control somewhere the
    // list would not offer; the option is added anyway, so the box says where it actually is.
    const list = !holder || choices.some(t => t.controlId === here) ? choices : [holder].concat(choices);
    return field('Container',
        '<select onchange="moveToContainer(this.value)">'
            + '<option value=""' + (here ? '' : ' selected') + '>&mdash; the page itself &mdash;</option>'
            + list.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === here ? ' selected' : '') + '>'
                + AC.esc(containerPath(t)) + ' (' + (t.type === 'tabs' ? 'tabs' : 'panel') + ')</option>').join('')
        + '</select>',
        'Where this control is drawn: on the page, as a tab of a tab set, or in a panel. Moving it changes '
        + 'nothing else about it &mdash; same field name, and everything aimed at it is still aimed at it. '
        + 'It goes in as the last tab of a tab set, or under whatever is already in a panel, and can be '
        + 'dragged from there; taken back out it lands on the layout at that same row and column.');
}

/**
 * The properties panel while a band has several controls picked out: what is in the group, and
 * what can be done to all of it at once.
 *
 * <p>No settings. Six controls of four different types have almost nothing in common to edit, and
 * a panel offering the few things they do share would be a panel whose contents changed depending
 * on what happened to be selected — which is harder to learn than having none. What a group is
 * for is moving, which is done by dragging it rather than from here; what is offered is the rest:
 * seeing what is in it, taking it all off the page, and putting it down again.
 */
function groupProps() {
    const controls = selectedControls();
    let html = '<div class="stack mini">'
        + '<div class="props-section"><div class="props-title"><span>' + controls.length
            + ' Controls Selected</span></div>'
        + '<span class="hint">Drag any one of them and they all move, keeping the shape they are in. '
        + 'Ctrl-click a control to add it or take it out, ctrl-drag a second band to add what it catches, '
        + 'and click the empty canvas — or press Escape — to put the group down.</span>'
        + '<div class="group-list">' + controls.map(c =>
            '<span class="group-item" onclick="selectControl(\'' + AC.attr(c.controlId) + '\')"'
                + ' title="Show this control on its own">'
                + '<span class="type-badge ' + AC.esc(c.type) + '">' + AC.esc(c.type) + '</span>'
                + AC.esc(controlTitle(c)) + '</span>').join('')
        + '</div>'
        + '</div>';

    return html + '<div class="toolbar" style="margin-top:10px">'
        + '<button class="secondary" onclick="setSelection([])">Clear Selection</button>'
        + '<button class="danger" onclick="deleteSelection()">Remove ' + controls.length + ' Controls</button>'
        + '</div></div>';
}

/**
 * Takes every selected control off the page, one confirmation for the lot.
 *
 * <p>Each goes through {@link #deleteControl}, which is where everything that has to let go of a
 * control being removed already lives — the actions aimed at it, the assignments writing into it,
 * the tab set holding it, the trigger scrolling to it. Doing it any other way here would be a
 * second copy of that list, and the second copy is the one that falls behind.
 */
function deleteSelection() {
    const controls = selectedControls();
    if (!controls.length) return;
    if (!confirm('Remove these ' + controls.length + ' controls from the page?\n\n'
            + controls.map(c => '· ' + controlTitle(c)).join('\n'))) return;
    const ids = controls.map(c => c.controlId);
    selectedIds = new Set();
    ids.forEach(id => { selectedId = id; deleteControl(true); });
    setSelection([]);
    AC.setStatus('statusBar', ids.length + ' controls removed.', 'ok');
}

// ── The page's variables ──────────────────────────────────────────────
// Two lists, and the difference between them is where the value comes from rather than how it is
// written: a built-in is worked out by the run, an ad-hoc one is what somebody typed. Both are
// read as ${NAME} wherever a control is read, so they are shown together.

/**
 * The variables panel: what every page already has, with a live example of each, and the page's
 * own beneath it.
 *
 * <p>The examples are worked out for this moment rather than described in words, because what
 * somebody needs to know about ${DATETIME} is what it will actually put in a request body — and
 * "yyyyMMddHHmmss" is a description of that rather than a look at it. The page's own are resolved
 * against the built-ins in the same pass, so a variable written as ${DATESTAMP}-nightly shows
 * what it comes to as it is typed.
 */
function variableProps() {
    refreshGlobals();
    const variables = page.variables || [];
    let html = '<div class="stack mini">'
        + '<span class="hint">Read anywhere a control is read: an action' + Q + 's inputs, its environment, '
        + 'its array or value path, a fan-out' + Q + 's row label, an assignment. Written '
        + '<code>${NAME}</code>, or <code>$NAME</code> everywhere but a path. A control may not take '
        + 'the name of one, so <code>${NAME}</code> never means two things at once.</span>';

    html += '<div class="props-section"><div class="props-title"><span>Built In</span></div>'
        + '<span class="hint" style="margin-bottom:8px">Every page has these without declaring them. '
        + 'The date and time ones are worked out afresh each time something sets the page off — '
        + 'so a call carries the moment it was made, not the moment the page was opened.</span>';
    html += BUILT_IN_VARIABLES.map(v => {
        // The switch is the one that is set here rather than only read here, so its value is a
        // tick box in place of the sample the rest show. Everything else about the row is the
        // same, because from a template's point of view it is the same kind of thing.
        if (v.toggle) {
            return '<div class="var-built">'
                + '<span class="var-name">$' + AC.esc(v.name) + '</span>'
                + '<label class="var-switch"><input type="checkbox"' + (pageDebug() ? ' checked' : '')
                    + ' onchange="setPageDebug(this.checked)"> '
                    + (pageDebug() ? 'true — keeping the detail' : 'false — detail not kept') + '</label>'
                + '<span class="var-what">' + AC.esc(v.what) + '</span>'
                + '</div>';
        }
        const sample = globals[v.name];
        return '<div class="var-built">'
            + '<span class="var-name">$' + AC.esc(v.name) + '</span>'
            + '<span class="var-sample">' + (sample === undefined || sample === ''
                ? '<i>only inside a fan-out</i>' : AC.esc(String(sample))) + '</span>'
            + '<span class="var-what">' + AC.esc(v.what) + '</span>'
            + '</div>';
    }).join('');
    html += '<span class="hint">Saved with the page, so a page left with its detail off runs that '
        + 'way for everybody who opens it — which is the point of putting it here rather than in '
        + 'the run toolbar, where it would be one operator' + Q + 's setting for one afternoon.</span>';
    html += '</div>';

    html += '<div class="props-section"><div class="props-title"><span>This Page</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="addVariable()">+ Add</button></span></div>';
    if (!variables.length) {
        html += '<div class="empty-note">No variables of its own yet. Add one for anything every action on '
            + 'this page has to carry and no endpoint supplies — who is running it, which batch it belongs '
            + 'to, a prefix built out of the date.</div>';
    }
    html += variables.map((v, i) => {
        const resolved = globals[v.name];
        const templated = (v.value || '').includes('$');
        return '<div class="var-row">'
            + '<input type="text" placeholder="name" value="' + AC.attr(v.name || '')
                + '" oninput="setVariable(' + i + ', \'name\', this.value)">'
            + '<input type="text" placeholder="value, or ${DATESTAMP}-nightly" value="' + AC.attr(v.value || '')
                + '" oninput="setVariable(' + i + ', \'value\', this.value)">'
            + '<button class="icon-btn" onclick="removeVariable(' + i + ')" title="Remove">×</button>'
            + '<input type="text" class="var-note" placeholder="what it is for (optional)" value="'
                + AC.attr(v.description || '') + '" oninput="setVariable(' + i + ', \'description\', this.value)">'
            + (templated && resolved !== undefined
                ? '<span class="hint" style="grid-column:1/-1">Comes to <b>' + AC.esc(String(resolved)) + '</b> right now.</span>'
                : '')
            + '</div>';
    }).join('');
    html += '<span class="hint">A value may be written in terms of the built-ins and of the variables '
        + 'above it, so <code>${DATESTAMP}-${batch}</code> is a legal thing to declare. One naming a '
        + 'variable listed below it reads as not yet set.</span>';
    return html + '</div></div>';
}

/**
 * Flicks the page's detail switch. Redrawn rather than left alone — unlike the text boxes below
 * it there is no caret to lose, and the line beside the box says which way it is set, so it has
 * to be rewritten. The run tools go with it: what Technical Details is about to be able to show
 * has just changed, and the button says so.
 */
function setPageDebug(on) {
    page.debug = !!on;
    renderProps();
    renderRunTools();
}

function addVariable() {
    page.variables = page.variables || [];
    page.variables.push({ name: 'variable' + (page.variables.length + 1), value: '', description: '' });
    renderProps();
}

/**
 * Edits one variable in place. No redraw: every field here is a text box, and redrawing the panel
 * on each keystroke would take the caret with it — the same reason the control properties
 * beside it only redraw the canvas. The strip's count is refreshed on its own, since adding and
 * removing are what move it.
 */
function setVariable(index, name, value) {
    if (!page.variables || !page.variables[index]) return;
    page.variables[index][name] = value;
}

function removeVariable(index) {
    if (!page.variables) return;
    page.variables.splice(index, 1);
    renderProps();
}

/**
 * What a date control will actually open showing, said under the box the default is typed into.
 *
 * <p>A date box is the one control that can refuse what it is handed, and it refuses in silence:
 * a default it cannot read leaves it empty with nothing on screen to say a default was ever set.
 * So the panel answers the question the box will not — here is the date this comes to, or here is
 * why there is no date in it — at the moment the default is typed rather than when somebody
 * previews the page and finds an empty box.
 */
function dateDefaultNote(c) {
    const typed = (c.defaultValue || '').trim();
    const format = dateFormatOf(c);
    const forms = 'Written as <code>2026-09-15</code>, as <code>20260915</code> (what <code>${DATESTAMP}</code> '
        + 'comes to), as <code>15-Sep-2026</code>, as <code>' + AC.esc(formatDay('2026-09-15', format))
        + '</code> — this control&#39;s own format — or as <code>TODAY</code>, <code>TODAY-1</code>, '
        + '<code>TODAY+2w</code>, <code>LASTBUSINESSDAY</code>, <code>BUSINESSDAY-3</code>, '
        + '<code>ENDOFMONTH</code>.';
    if (!typed) return '<span class="hint">The box opens empty. ' + forms + '</span>';
    // Worked out against the built-ins as they stand this second, the way the variables panel
    // shows its examples: what somebody needs to know about ${DATESTAMP} here is the date it
    // will put in the box, not the format string behind it.
    refreshGlobals();
    const day = dateDefault(typed, format);
    if (day) {
        const carried = formatDay(day, format);
        return '<span class="hint">Opens showing <b>' + AC.esc(day) + '</b>'
            + (day === typed ? '' : ' — worked out from "' + AC.esc(typed) + '"') + '.'
            // Only where the two differ, which is the only time there is anything to say: on an
            // ISO control the box and the value are the same string.
            + (carried === day ? '' : ' <code>${' + AC.esc(c.fieldName || 'name') + '}</code> carries <b>'
                + AC.esc(carried) + '</b>.') + '</span>';
    }
    return '<span class="hint" style="color:#bf2600">A date box shows only <code>yyyy-MM-dd</code>, and "'
        + AC.esc(typed) + '" is not a date this can read — so the box would open empty. ' + forms + '</span>';
}

/**
 * The format a date control publishes its value in.
 *
 * <p>Not about what the operator looks at: the box on the running page is the browser's own date
 * picker whatever this says, because that is the only date box there is and it writes dates the
 * way the machine it is running on writes them. This is about what leaves the control —
 * <code>${fieldName}</code> in an input template, an assignment into another control, a CSV
 * export. The endpoint behind a page wants yyyyMMdd or dd/MM/yyyy far more often than it wants
 * ISO, and reformatting a picked date by hand in every input that used it was the alternative.
 */
function dateFormatProp(c) {
    const chosen = dateFormatOf(c);
    return field('Date Format', '<select onchange="setProp(\'dateFormat\', this.value); renderProps()">'
            + DATE_FORMATS.map(f => '<option value="' + AC.attr(f) + '"' + (f === chosen ? ' selected' : '') + '>'
                + AC.esc(f) + (f === ISO_FORMAT ? ' (ISO)' : '') + '</option>').join('')
        + '</select>',
        'What <code>${' + AC.esc(c.fieldName || 'name') + '}</code> carries into inputs, assignments and exports — '
        + '<b>' + AC.esc(formatDay(dateDefault('TODAY'), chosen)) + '</b> for today. The box itself is the '
        + 'browser&#39;s date picker either way; this is the form the value leaves in. A date arriving from '
        + 'anywhere — a row, an action, a default — is read into it, so this is also how '
        + (dayFirst(chosen) ? '<code>05/09/2026</code> is read: <b>day first</b>.'
                            : 'an ambiguous <code>05/09/2026</code> is read: <b>month first</b>.'));
}

/**
 * What the box opens on, offered as the handful of answers pages actually ask for rather than as
 * a line of text to get right. A business date is the one everybody wanted and nobody could
 * spell: it is not yesterday, and on a Monday it is the Friday.
 *
 * <p>Whatever is picked is written into Default Value below, which stays the setting — so a
 * default this list does not offer is still typed there, and is shown here as itself rather than
 * being quietly replaced by whichever option happened to be first.
 */
const DATE_DEFAULTS = [
    { value: '',                 label: '— nothing: the box opens empty —' },
    { value: 'TODAY',            label: 'Current date' },
    { value: 'BUSINESSDAY',      label: 'Current business date' },
    { value: 'LASTBUSINESSDAY',  label: 'Last business date' },
    { value: 'NEXTBUSINESSDAY',  label: 'Next business date' },
    { value: 'TODAY-1',          label: 'Yesterday' },
    { value: 'TODAY+1',          label: 'Tomorrow' },
    { value: 'TODAY-1w',         label: 'A week ago' },
    { value: 'TODAY-1m',         label: 'A month ago' },
    { value: 'STARTOFMONTH',     label: 'First day of this month' },
    { value: 'ENDOFMONTH',       label: 'Last day of this month' },
    { value: 'STARTOFYEAR',      label: 'First day of this year' },
    { value: 'ENDOFYEAR',        label: 'Last day of this year' }
];

/** The option a default nobody would have picked from the list answers to. */
const TYPED_DATE_DEFAULT = '__typed__';

function datePresetProp(c) {
    const typed = (c.defaultValue || '').trim();
    const known = DATE_DEFAULTS.find(d => d.value.toLowerCase() === typed.toLowerCase());
    return field('Opens On', '<select onchange="setDateDefault(this.value)">'
            + (known ? '' : '<option value="' + AC.attr(TYPED_DATE_DEFAULT) + '" selected>— as typed below: '
                + AC.esc(typed) + ' —</option>')
            + DATE_DEFAULTS.map(d => '<option value="' + AC.attr(d.value) + '"'
                + (known && known.value === d.value ? ' selected' : '') + '>' + AC.esc(d.label) + '</option>').join('')
        + '</select>',
        'Worked out afresh every time the page opens, so a page left open overnight comes back on the new '
        + 'date rather than on the one it was saved with. A business date steps over Saturday and Sunday and '
        + 'nothing else — no holiday calendar, which is the same rule <code>${PREVDATESTAMP}</code> follows — '
        + 'and the current business date on a Sunday is the Friday.');
}

/** Picking from the list is typing into Default Value, so there is one setting rather than two. */
function setDateDefault(value) {
    if (value === TYPED_DATE_DEFAULT) return;
    const c = findControl(selectedId);
    if (!c) return;
    c.defaultValue = value;
    renderProps();
    renderCanvas();
}

function field(label, control, hint) {
    return '<div class="form-group"><label>' + AC.esc(label) + '</label>' + control
        + (hint ? '<span class="hint">' + hint + '</span>' : '') + '</div>';
}

function typeSelect(c) {
    return '<select onchange="changeType(this.value)">'
        + PALETTE.map(p => '<option value="' + p.type + '"' + (p.type === c.type ? ' selected' : '') + '>' + AC.esc(p.label) + '</option>').join('')
        + '</select>';
}

/** Grouped by app: the list spans every app, so the app is what tells two instances apart. */
function instanceOptions(selected) {
    const byApp = new Map();
    instances.forEach(i => {
        const app = i.appName || '(no app)';
        if (!byApp.has(app)) byApp.set(app, []);
        byApp.get(app).push(i);
    });
    return '<option value="">— select an instance —</option>'
        + [...byApp.entries()].map(([app, list]) =>
            '<optgroup label="' + AC.attr(app) + '">'
            + list.map(i => {
                const label = i.instanceLabel || (i.appUseCaseName + ' @ ' + i.appEnvironment);
                return '<option value="' + AC.attr(i.appUseCaseInstanceId) + '"' + (i.appUseCaseInstanceId === selected ? ' selected' : '') + '>'
                    + AC.esc(label) + '</option>';
            }).join('')
            + '</optgroup>').join('');
}

// Which destination a link's panel is asking about, keyed by the control's id. Designer state,
// not part of the page: what is saved is the destination itself — a page name, or an address —
// and a link with neither is the plain trigger it has always been able to be.
//
// It has to be held, though, and that is the whole of why this exists. The mode used to be read
// back off the page name, which meant picking "another page in this catalog" set nothing at all:
// there was no page named yet, so the panel was redrawn, read no name, decided the link was an
// address again and put the picker away before anybody could pick from it. The one thing the
// operator had asked for was the one thing not written down.
let linkModePick = {};

/** Whether a link's panel is asking which page it opens, rather than which address. */
function linksToPage(c) {
    return !!(c.linkPageName || linkModePick[c.controlId] === 'PAGE');
}

/**
 * The pages a link may open: every page in the catalog except the one being edited, which a link
 * pointing at itself would only reload.
 */
function pageOptions(selected) {
    // Sorted by the text each option shows rather than by the page name underneath it, which is
    // what these options are read by: a list headed by titles has to be alphabetical by title to
    // look sorted at all. #sortPages orders the catalog itself by name, for the dropdown that
    // shows names.
    return '<option value="">— pick a page —</option>'
        + pages.filter(other => other.pageName !== page.pageName)
            .map(other => ({ page: other, text: other.title ? other.title + ' (' + other.pageName + ')' : other.pageName }))
            .sort((a, b) => byName(a.text, b.text))
            .map(o => '<option value="' + AC.attr(o.page.pageName) + '"' + (o.page.pageName === selected ? ' selected' : '') + '>'
                + AC.esc(o.text) + '</option>').join('');
}

/** Plain app names — the App field of a select's ENVIRONMENTS source. */
function appOptions(selected) {
    return '<option value="">— select an app —</option>'
        + apps.map(a => '<option value="' + AC.attr(a.appName) + '"' + (a.appName === selected ? ' selected' : '') + '>'
            + AC.esc(a.appName) + '</option>').join('');
}

/**
 * Where a link goes: another page in this catalog, or an address typed out.
 *
 * <p>Two fields rather than one box that takes both, because the two are not the same kind of
 * thing to get wrong. A page is picked from what exists, so it cannot be misspelt and is checked
 * again when this page is saved; an address is typed, so it can be anything and is only held to
 * being http, https or rooted here. Naming a page wins over the typed address and over anything
 * an action later binds — a link told to open a page is one somebody meant to open that page.
 */
function linkProps(c) {
    const toPage = linksToPage(c);
    const others = pages.filter(other => other.pageName !== page.pageName);
    let html = '<div class="props-section"><div class="props-title"><span>Destination</span></div>';
    html += field('Opens', '<select onchange="setLinkMode(this.value)">'
        + '<option value="URL"' + (toPage ? '' : ' selected') + '>A web address</option>'
        + '<option value="PAGE"' + (toPage ? ' selected' : '') + '>Another page in this catalog</option>'
        + '</select>');
    if (toPage) {
        html += field('Page', '<select onchange="setProp(\'linkPageName\', this.value); renderProps()">'
            + pageOptions(c.linkPageName) + '</select>',
            !others.length
                ? 'There are no other pages to link to yet. Save a second page and it appears here.'
                : !c.linkPageName
                ? 'Pick one and this link opens it. Until then the link has no destination — it still runs whatever '
                    + 'actions are on it, and shows as plain text rather than offering a click that goes nowhere.'
                : 'Opens that page in its running form — the same thing <b>Open standalone</b> gives you — in a '
                    + 'new tab, so this page and whatever has been filled into it are still here behind it.');
    } else {
        html += field('URL', '<input type="text" value="' + AC.attr(c.defaultValue || '') + '" placeholder="https://…/orders/${orderId}" oninput="setProp(\'defaultValue\', this.value)">',
            'Where this link goes before anything fills it in. Leave it blank and the link is only a '
            + 'trigger until an action targeting it binds an address. <code>http</code>, <code>https</code> '
            + 'or a path on this server.'
            + '<br>Write <code>${fieldName}</code> anywhere in it — in the host, the path or the query — and '
            + 'the running page fills it in from the control of that name, from a page variable or from a '
            + 'built-in like <code>${DATESTAMP}</code>, and keeps it up to date as the operator types. While '
            + 'any of them is unanswered or empty the link shows as plain text and says what it is waiting '
            + 'for, rather than offering a half-built address to follow.');
    }
    return html + '</div>';
}

/** Which page a page control runs inside this one. */
function childPageProps(c) {
    const others = pages.filter(other => other.pageName !== page.pageName);
    return '<div class="props-section"><div class="props-title"><span>Child Page</span></div>'
        + field('Page', '<select onchange="setProp(\'childPageName\', this.value); renderProps()">'
            + pageOptions(c.childPageName) + '</select>',
            others.length
                ? 'Runs that page, in its running form, inside this one. This page shows how many of the child '
                    + 'page\'s actions succeeded and how many failed; click the failed count for what went wrong. '
                    + 'A page that leads back to this one is refused on save.'
                : 'There are no other pages to run here yet. Save a second page and it appears here.')
        + '</div>';
}

/**
 * Switches a link between the two kinds of destination, clearing the one being left behind so the
 * saved page carries only the destination actually in force. Keeping both would store a link
 * whose panel showed one address and whose click went to the other.
 */
function setLinkMode(mode) {
    const c = findControl(selectedId);
    if (!c) return;
    // The pick is what holds the panel open on the page picker before a page has been picked;
    // the destination being left behind goes, so the saved link carries only the one in force.
    // Keeping both would store a link whose panel showed one address and whose click went to the
    // other, and a page name always wins — see #pageLinkUrl.
    if (mode === 'PAGE') {
        linkModePick[c.controlId] = 'PAGE';
        c.defaultValue = '';
    } else {
        delete linkModePick[c.controlId];
        c.linkPageName = '';
    }
    renderControlList();
    renderCanvas();
    renderProps();
}

function selectProps(c) {
    const source = c.optionSource || (c.optionSource = { mode: 'NONE', staticOptions: [] });
    let html = '<div class="props-section"><div class="props-title"><span>Options</span></div>';
    const SOURCE_LABELS = { NONE: 'Empty', STATIC: 'Static list', USECASE: 'Use case instance',
                            ENVIRONMENTS: 'App environments', DATASET: 'Static dataset' };
    html += field('Source',
        '<select onchange="setOption(\'mode\', this.value); renderProps()">'
        + ['NONE', 'STATIC', 'USECASE', 'ENVIRONMENTS', 'DATASET'].map(m => '<option value="' + m + '"' + (source.mode === m ? ' selected' : '') + '>'
            + SOURCE_LABELS[m] + '</option>').join('')
        + '</select>');

    // Asked of every source alike, and of a select an action fills later, because it is a
    // question about the list the operator reads rather than about where the list came from.
    const SORT_LABELS = { NONE: 'As they arrive', ASC: 'Value, A → Z', DESC: 'Value, Z → A' };
    html += field('Sort',
        '<select onchange="setOption(\'sortOrder\', this.value)">'
        + ['NONE', 'ASC', 'DESC'].map(o => '<option value="' + o + '"' + ((source.sortOrder || 'NONE') === o ? ' selected' : '') + '>'
            + SORT_LABELS[o] + '</option>').join('')
        + '</select>',
        'By the value the operator reads, not the key behind it. Numbers sort as numbers, so 1, 2, 10 '
        + 'rather than 1, 10, 2. Applies however the list was filled — including one an action binds in.');

    // Under Sort because it reads off it: "the first option" is the first once the order above has
    // been applied, which is the one at the top of the list the operator is looking at.
    html += '<label class="inline-check"><input type="checkbox"' + (source.selectFirst ? ' checked' : '')
        + ' onchange="setOption(\'selectFirst\', this.checked); renderCanvas()"> Select the first option</label>'
        + '<span class="hint" style="margin-top:-4px">Opens on the first option instead of on the blank row, '
        + 'and fires this control\'s Value change actions as though the operator had picked it — so a page '
        + 'whose grid hangs off a dropdown opens with rows in it. The first <em>after</em> sorting. A value the '
        + 'page already has beats it: one carried in on a link, or a pick that survived the list being '
        + 'refreshed under it, stays put.</span>';

    if (source.mode === 'STATIC') {
        const options = source.staticOptions || [];
        html += '<div class="form-group"><label>Key / Value</label>'
            + options.map((o, i) =>
                '<div class="opt-row">'
                    + '<input type="text" placeholder="key" value="' + AC.attr(o.key || '') + '" oninput="setStaticOption(' + i + ', \'key\', this.value)">'
                    + '<input type="text" placeholder="value" value="' + AC.attr(o.value || '') + '" oninput="setStaticOption(' + i + ', \'value\', this.value)">'
                    + '<button class="icon-btn" onclick="removeStaticOption(' + i + ')" title="Remove">×</button>'
                + '</div>').join('')
            + '<button class="tool-btn" onclick="addStaticOption()">+ Add Option</button>'
            + '<span class="hint">The key is what the use case input receives; the value is what the operator sees.</span></div>';
    }

    if (source.mode === 'USECASE') {
        html += field('Instance', '<select onchange="setOption(\'appUseCaseInstanceId\', this.value)">' + instanceOptions(source.appUseCaseInstanceId) + '</select>',
            'Run when the page opens; its response fills this dropdown.');
        html += field('Array Path', '<input type="text" value="' + AC.attr(source.arrayPath || '') + '" placeholder="data.items" oninput="setOption(\'arrayPath\', this.value)">',
            'Blank when the response is itself the array.');
        html += '<div class="form-row" style="margin-bottom:0">'
             + field('Key Field', '<input type="text" value="' + AC.attr(source.keyField || '') + '" placeholder="id" oninput="setOption(\'keyField\', this.value)">')
             + field('Label Field', '<input type="text" value="' + AC.attr(source.labelField || '') + '" placeholder="name" oninput="setOption(\'labelField\', this.value)">')
             + '</div>';
    }

    if (source.mode === 'ENVIRONMENTS') {
        html += field('App', '<select onchange="setOption(\'appName\', this.value)">' + appOptions(source.appName) + '</select>',
            'Lists every environment configured for this app.');
    }

    // The same two questions the USECASE source asks — which field is the value, which is the
    // text — except that here the answers are known in advance, so they are picked rather than
    // typed. A dataset that has not loaded falls back to typing them; see #datasetColumnSelect.
    if (source.mode === 'DATASET') {
        html += field('Dataset', '<select onchange="setOption(\'datasetName\', this.value); renderProps()">'
            + datasetOptions(source.datasetName) + '</select>',
            datasets.length
                ? 'Its rows fill this dropdown when the page opens — no call made, and every control reading '
                    + 'the same dataset shares one fetch.'
                : 'No static datasets are defined, or the library could not be reached. '
                    + '<a href="staticdatasets.html" target="_blank" rel="noopener">Manage datasets</a>.');
        if (source.datasetName) {
            html += '<div class="form-row" style="margin-bottom:0">'
                 + field('Key Column', datasetColumnSelect(source.datasetName, source.keyField,
                        'setOption(\'keyField\', this.value)', '— first column —'))
                 + field('Label Column', datasetColumnSelect(source.datasetName, source.labelField,
                        'setOption(\'labelField\', this.value)', '— same as the key —'))
                 + '</div>'
                 + '<span class="hint">The key is what an action sends as <code>${'
                    + AC.esc(c.fieldName || 'name') + '}</code>; the label is what the operator picks it by. '
                    + 'Leave the label blank and the key is shown as well as sent.</span>';
        }
    }
    return html + '</div>';
}

function gridProps(c) {
    return '<div class="props-section"><div class="props-title"><span>Grid</span></div>'
        + field('Columns', '<input type="text" value="' + AC.attr((c.columns || []).join(', ')) + '" placeholder="id, status, amount" oninput="setColumns(this.value)">',
            'Comma-separated field names, and the grid shows these and nothing else. Leave blank to show '
            + 'whatever fields the rows carry.')
        + field('First Columns', '<input type="text" value="' + AC.attr((c.leadColumns || []).join(', '))
                + '" placeholder="status, id" oninput="setLeadColumns(this.value)">',
            'Comma-separated field names shown first, in this order; every other column the rows carry follows '
            + 'in the order it arrived. For the answer whose thirty fields are whatever the endpoint returned and '
            + 'whose first two are the ones anybody reads — unlike Columns above, nothing is dropped, so a field '
            + 'nobody thought to name is still there to scroll to. A name the rows do not carry is simply not '
            + 'there, and a run that carries it puts it back at the front.')
        + field('Hidden Columns', '<input type="text" value="' + AC.attr((c.hiddenColumns || []).join(', '))
                + '" placeholder="internalId, correlationToken" oninput="setHiddenColumns(this.value)">',
            'Comma-separated field names the grid does not draw — the other end of Columns above, and the one to '
            + 'reach for when the four fields nobody reads are easier to name than the thirty that stay. The rows '
            + 'still carry them: the error check, the display filter, a clickable column and anything reading '
            + '<code>${column}</code> all still see the value. What goes is the column — not drawn, not filtered, '
            + 'not sorted, not exported.')
        + '<label class="inline-check"><input type="checkbox"' + (c.wrapText ? ' checked' : '')
            + ' onchange="setProp(\'wrapText\', this.checked)"> Wrap text</label>'
        + '<span class="hint" style="margin-top:-4px">Opens with every column fitted on screen and each cell run '
        + 'over as many lines as it needs, instead of one line a cell with the wide columns off the right-hand '
        + 'edge. A cell too long even for that is cut off with a button to open it out. Only how the grid opens — '
        + 'the operator has the same switch in its toolbar.</span>'
        + field('Static Dataset', '<select onchange="setProp(\'datasetName\', this.value); renderProps()">'
            + datasetOptions(c.datasetName) + '</select>',
            c.datasetName
                ? 'Its rows fill this grid as the page opens, before anything is clicked — a list to work down '
                    + 'rather than somewhere an answer lands. An action aimed at this grid still replaces them, '
                    + 'and Reset puts them back.'
                : datasets.length
                    ? 'Optional. Pick one and the grid opens already holding that dataset&#39;s rows instead of '
                        + 'waiting for an action to fill it.'
                    : 'No static datasets are defined, or the library could not be reached. '
                        + '<a href="staticdatasets.html" target="_blank" rel="noopener">Manage datasets</a>.')
        + (c.datasetName && datasetColumns(c.datasetName).length
            ? '<span class="hint">Columns it carries: <code>' + datasetColumns(c.datasetName).map(AC.esc).join('</code>, <code>')
                + '</code>. Name some of them under Columns above to show only those, in that order.</span>'
            : '')
        + gridSortFields(c)
        + field('Display Filter', '<input type="text" value="' + AC.attr(c.displayFilterExpression || '')
                + '" placeholder="STATUS = FAILED || RECORDCOUNT > 0" oninput="setDisplayFilter(this.value)">',
            'Optional. Every row of the response is put through this as the grid fills, and only the rows it comes out '
            + '<b>true</b> for are kept — the rest never reach the grid, its counts, its status or its exports. Same '
            + 'syntax as the error check below, which then judges only the rows this kept.')
        + '<div id="displayFilterNote">' + rowCheckNote({ rowErrorExpression: c.displayFilterExpression }, 'a display filter') + '</div>'
        + field('Error Check', '<input type="text" value="' + AC.attr(c.rowErrorExpression || '')
                + '" placeholder="STATUS != SUCCESS || RECORDCOUNT = 0" oninput="setRowCheck(this.value)">',
            'Optional. Every row is put through this as the grid fills; a row it comes out <b>true</b> for is an error, '
            + 'drawn in red, and the grid\'s name carries the tally — <b>5 ERROR / 15 SUCCESS</b>. Separate from whether '
            + 'the call worked: fifteen rows back with three of them wrong is a successful call and a failed run.')
        + '<div id="rowCheckNote">' + rowCheckNote(c) + '</div>'
        + '<div class="form-row" style="margin-bottom:0">'
            + field('Status', '<select onchange="setGridStatus(\'statusCondition\', this.value)">'
                + [['', '— none —'], ['ROWCOUNT>0', 'ROWCOUNT > 0'], ['ROWCOUNT>=0', 'ROWCOUNT >= 0'], ['ROWCOUNT=0', 'ROWCOUNT = 0']]
                    .map(([v, text]) => '<option value="' + v + '"' + ((c.statusCondition || '') === v ? ' selected' : '') + '>'
                        + AC.esc(text) + '</option>').join('')
                + '</select>')
            + field('Status Variable', '<input type="text" value="' + AC.attr(c.statusVariable || '')
                + '" placeholder="ordersStatus" oninput="setGridStatus(\'statusVariable\', this.value)">')
        + '</div>'
        + '<div id="gridStatusNote">' + gridStatusNote(c) + '</div>'
        + gridHiddenProp(c)
        + '<span class="hint">When the page runs, every grid sorts and filters by any column, keeps the top rows of what is left, and exports what is on screen to CSV, pipe-separated text or a plain HTML table. '
        + 'Its name carries the outcome of the call that filled it, and the call itself — URL, method, status, timing, size — folds out of the top of it.</span>'
        + '</div>'
        + gridSourceGridProps(c)
        + rowClickProps(c)
        + columnLinkProps(c);
}

/**
 * The tick that makes a grid hold its rows without being drawn — see
 * {@link AppPageControl#isHideOnRun()}.
 *
 * <p>Offered on every grid but the ones inside a tab set, which the set draws rather than the
 * layout: hiding one of those would leave a tab with nothing behind it, and the save refuses it.
 * The note says so rather than the tick quietly not being there.
 */
function gridHiddenProp(c) {
    const holder = tabsHolding(c.controlId);
    if (holder) {
        return '<div class="empty-note">Drawn by the tab set <b>' + AC.esc(controlTitle(holder))
            + '</b>, so it cannot be hidden — a hidden tab would be a tab with nothing behind it. '
            + 'Take it out of the set to hide it.</div>';
    }
    // Whoever ticks this is about to lose sight of the grid, so what still happens to it is worth
    // saying next to the tick rather than in documentation they would have to go and find.
    return '<label class="inline-check"><input type="checkbox"' + (c.hideOnRun ? ' checked' : '')
            + ' onchange="setProp(\'hideOnRun\', this.checked); renderProps()"> Hidden when the page runs</label>'
        + '<span class="hint">' + (c.hideOnRun
            ? 'This grid holds its rows but is never drawn, and the space it was laid out in goes back to whatever '
                + 'is below it. Everything else still happens: its static dataset still loads as the page opens, an '
                + 'action aimed at it still fills it, its filter, sort, cap, error check and status variable all '
                + 'still apply, and anything that reads it — a fan-out, a lookup, a chart, another grid — reads it '
                + 'exactly as before. Nobody can filter it by hand, so a fan-out over it runs over every row it holds.'
            : 'For a grid that is plumbing rather than a table to read — the static list a fan-out runs over, the '
                + 'lookup an enriched column reads into, the rows a chart or another grid draws itself from. It '
                + 'still fills and is still read; it simply is not drawn, and gives back the space it was given.')
        + '</span>';
}

/** True when `gridId` takes its rows, directly or down a chain, from `fromId`. */
function gridFedBy(gridId, fromId) {
    const seen = new Set();
    let at = findControl(gridId);
    while (at && at.sourceGridControlId && !seen.has(at.controlId)) {
        if (at.sourceGridControlId === fromId) return true;
        seen.add(at.controlId);
        at = findControl(at.sourceGridControlId);
    }
    return false;
}

/**
 * Where a grid copies its rows from another grid, the way a chart draws itself from one: every
 * time that grid has finished filling, its rows (after its display filter) land here too, and go
 * through this grid's own columns, display filter, sort and error check. Not itself, and not a
 * grid that already takes its rows from this one — either would fill forever.
 */
function gridSourceGridProps(c) {
    const grids = page.controls.filter(t => t.type === 'grid' && t.controlId !== c.controlId && !gridFedBy(t.controlId, c.controlId));
    return '<div class="props-section"><div class="props-title"><span>Rows From Grid</span></div>'
        + field('Grid', '<select onchange="setProp(\'sourceGridControlId\', this.value); renderProps()">'
            + '<option value="">— none —</option>'
            + grids.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === c.sourceGridControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + '</option>').join('')
            + '</select>',
            grids.length
                ? 'Optional. Every time this grid has finished filling — an action, a static dataset, a reset — its rows '
                    + '(after its display filter) are copied here, replacing what this grid showed. An action aimed at '
                    + 'this grid still fills it on its own.'
                : 'There is no other grid on this page to take rows from yet.')
        + '</div>';
}

/**
 * What clicking anywhere in a row does — the row-wide counterpart to the clickable columns
 * below it.
 *
 * <p>The difference between the two is what the click is about. A clickable column is about one
 * cell: click the order id, and the id is what travels. A clickable row is about the row —
 * whatever the operator happened to point at — and the natural shape for a whole record is the
 * JSON it already is, which is what a blank value hands over here.
 *
 * <p>They live together without fighting: a click that lands on a cell of a clickable column
 * runs that column's drill-down and stops there, so the narrower thing the operator aimed at
 * wins, and everywhere else in the row runs this.
 */
function rowClickProps(c) {
    const click = c.rowClick;
    const library = page.actions || [];
    const targets = page.controls.filter(t => t.controlId !== c.controlId && ASSIGN_TYPES.includes(t.type));

    let html = '<div class="props-section"><div class="props-title"><span>Clickable Rows</span>'
        + '<button class="tool-btn" onclick="toggleRowClick()">' + (click ? 'Remove' : '+ Make rows clickable') + '</button>'
        + '</div>';

    if (!click) {
        return html + '<div class="empty-note">Rows do nothing when they are clicked. Turn this on and clicking '
            + 'one puts that row on the page — the whole row as JSON, and any fields of it you name — and runs '
            + 'the actions listed.</div></div>';
    }

    html += '<span class="hint">Clicking a row puts values from <b>that row</b> onto the page, then runs what is '
        + 'ticked below. A <b>blank</b> value hands over the whole row as a JSON object — <code>{"id":"A-7",'
        + '"status":"OPEN"}</code> — which is what a hidden field or a text area holds and an action sends on as '
        + '<code>${' + AC.esc(rowJsonExample(c, targets)) + '}</code>. Written with something, <code>${field}</code> '
        + 'is read off the clicked row first and off the page' + Q + 's own controls for whatever the row does not '
        + 'answer.</span>';

    const assignments = click.assignments || [];
    html += '<div class="sub-title"><span>Sets</span>'
        + (targets.length ? '<button class="tool-btn" onclick="addRowClickAssignment()">+ Add</button>' : '')
        + '</div>';
    if (!targets.length) {
        html += '<div class="empty-note">Nothing to write into — add a text area, a hidden field or a label for the '
            + 'row' + Q + 's JSON to land in.</div>';
    } else if (!assignments.length) {
        html += '<div class="empty-note">Sets nothing yet.</div>';
    } else {
        html += assignments.map((a, s) =>
            '<div class="assign-row">'
                + '<select onchange="setRowClickAssignment(' + s + ', \'targetControlId\', this.value)">'
                    + '<option value="">— pick a control —</option>'
                    + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                        + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
                + '</select>'
                + '<input type="text" placeholder="the whole row as JSON" value="' + AC.attr(a.value || '') + '"'
                    + ' oninput="setRowClickAssignment(' + s + ', \'value\', this.value)">'
                + '<button class="icon-btn" onclick="removeRowClickAssignment(' + s + ')" title="Remove">×</button>'
            + '</div>').join('');
    }

    html += '<div class="sub-title"><span>Runs</span></div>';
    if (!library.length) {
        html += '<div class="empty-note">The page has no actions yet — '
            + '<button class="tool-btn" onclick="showPageActions()">add one</button> and it can run from here.</div>';
    } else {
        const chosen = click.actionIds || [];
        html += library.map(a => {
            const on = chosen.includes(a.actionId);
            const order = on ? chosen.indexOf(a.actionId) + 1 : 0;
            return '<label class="inline-check"><input type="checkbox"' + (on ? ' checked' : '')
                + ' onchange="toggleRowClickAction(\'' + AC.attr(a.actionId) + '\', this.checked)"> '
                + (order ? '<b>' + order + '.</b> ' : '') + AC.esc(a.actionLabel || a.actionId) + '</label>';
        }).join('');
    }
    // Turned on and left empty, the rows would be drawn as clickable and answer a click with
    // nothing — so the save refuses it. Said here, where it can be put right, rather than only at
    // the save, where it arrives as a refusal to store the whole page.
    if (!assignments.length && !(click.actionIds || []).length) {
        html += '<div class="empty-note" style="color:#bf2600">Clickable rows that set nothing and run nothing '
             + 'would answer a click with nothing, so the page will not save. Set a value, tick an action, or '
             + 'remove this.</div>';
    }
    return html + '</div>';
}

/**
 * A name to write the row's JSON into in the hint above, taken from whatever the designer has
 * already pointed the first assignment at — so the example says what to type on <em>this</em>
 * page rather than naming a field that is not on it.
 */
function rowJsonExample(c, targets) {
    const first = ((c.rowClick && c.rowClick.assignments) || []).find(a => a.targetControlId && !(a.value || '').trim());
    const target = first && findControl(first.targetControlId);
    return (target && target.fieldName) || 'rowJson';
}

// ── Clickable rows ───────────────────────────────────────────────────────
// The same mutators the clickable columns have, against the one row click a grid carries rather
// than against a list of them. Absent rather than empty when the rows do nothing: "are these
// rows clickable" is one question, and a grid carrying an empty row click would answer it twice.

function toggleRowClick() {
    const c = selectedGrid();
    if (!c) return;
    c.rowClick = c.rowClick ? null : { assignments: [], actionIds: [] };
    renderProps();
    renderCanvas();
}

function addRowClickAssignment() {
    const c = selectedGrid();
    if (!c || !c.rowClick) return;
    c.rowClick.assignments = (c.rowClick.assignments || []).concat([{ targetControlId: '', value: '' }]);
    renderProps();
    renderCanvas();
}

/** No redraw of the panel: the value box is typed into, and redrawing would take the caret. */
function setRowClickAssignment(at, name, value) {
    const c = selectedGrid();
    const assignment = c && c.rowClick && (c.rowClick.assignments || [])[at];
    if (!assignment) return;
    assignment[name] = value;
    // Except when a target is picked, which is a dropdown and also settles what the hint above
    // can name as the field an action reads the row's JSON out of.
    if (name === 'targetControlId') renderProps();
    renderCanvas();
}

function removeRowClickAssignment(at) {
    const c = selectedGrid();
    if (!c || !c.rowClick) return;
    c.rowClick.assignments = (c.rowClick.assignments || []).filter((a, i) => i !== at);
    renderProps();
    renderCanvas();
}

function toggleRowClickAction(actionId, on) {
    const c = selectedGrid();
    if (!c || !c.rowClick) return;
    const ids = c.rowClick.actionIds || [];
    c.rowClick.actionIds = on ? ids.concat([actionId]).filter((id, i, all) => all.indexOf(id) === i)
                              : ids.filter(id => id !== actionId);
    renderProps();
    renderCanvas();
}

/**
 * The order a grid opens in: which field its rows are sorted by before anybody clicks a heading,
 * and which way round.
 *
 * <p>Worth having as a setting rather than leaving to the operator because the first screenful is
 * the one most grids are read for — newest trade at the top, largest break first — and a grid
 * that arrives in the order an endpoint happened to return its rows makes that a click every
 * single run. It is only a starting order: every heading still sorts, this column included.
 *
 * <p>The column is picked from a list wherever one is known — the names typed under Columns, or
 * the attributes of the dataset behind the grid — and typed where it is not, which is the same
 * bargain {@link #datasetColumnSelect} makes. A grid whose columns follow the data has no list to
 * offer until it has run, so the name is taken on trust and ignored at run time if the rows turn
 * out not to carry it.
 */
function gridSortFields(c) {
    const configured = (c.columns || []).filter(Boolean);
    const known = configured.length ? configured : datasetColumns(c.datasetName || '');
    const chosen = c.sortColumn || '';
    const picker = known.length
        ? '<select onchange="setGridSort(\'sortColumn\', this.value)">'
            + '<option value="">— as they arrive —</option>'
            + known.map(col => '<option value="' + AC.attr(col) + '"' + (col === chosen ? ' selected' : '') + '>'
                + AC.esc(col) + '</option>').join('')
            + (chosen && !known.includes(chosen)
                ? '<option value="' + AC.attr(chosen) + '" selected>' + AC.esc(chosen) + ' (not a column)</option>' : '')
            + '</select>'
        : '<input type="text" value="' + AC.attr(chosen) + '" placeholder="column name"'
            + ' oninput="setGridSort(\'sortColumn\', this.value)">';
    const direction = '<select onchange="setGridSort(\'sortDirection\', this.value)">'
        + '<option value="ASC"' + (c.sortDirection === 'DESC' ? '' : ' selected') + '>Ascending</option>'
        + '<option value="DESC"' + (c.sortDirection === 'DESC' ? ' selected' : '') + '>Descending</option>'
        + '</select>';
    const top = '<input type="number" min="0" step="1" placeholder="all"'
        + ' value="' + AC.attr(c.topRows > 0 ? c.topRows : '') + '"'
        + ' oninput="setGridSort(\'topRows\', this.value)">';
    return '<div class="form-row" style="margin-bottom:0">'
            + field('Sort By', picker)
            + field('Direction', direction)
            + field('Top Rows', top)
        + '</div>'
        + '<div id="gridSortNote">' + gridSortNote(c) + '</div>';
}

/**
 * What the chosen order and cap will do, kept up to date as they are chosen — see
 * {@link #setGridSort}. Both are optional and read as a pair: the cap is what "top" means, and
 * the order is what makes a particular ten rows the top ten rather than an arbitrary ten.
 */
function gridSortNote(c) {
    const chosen = (c.sortColumn || '').trim();
    const top = normalizeTopRows(c.topRows);
    const order = chosen
        ? 'The grid opens sorted by <code>' + AC.esc(chosen) + '</code>, '
            + (c.sortDirection === 'DESC' ? 'largest or latest first' : 'smallest or earliest first') + '. '
            + 'Clicking any heading re-sorts it as usual, and clicking this one turns the order round. '
            + 'Ignored on a run whose rows carry no such field.'
        : 'Optional. Leave Sort By and the grid shows its rows in the order they came back, as it always has.';
    if (!top) {
        return '<span class="hint">' + order
            + ' Leave Top Rows blank to show every row that comes back.</span>';
    }
    const many = top === 1 ? '<b>first row</b>' : '<b>first ' + top.toLocaleString() + ' rows</b>';
    return '<span class="hint">' + order
        + (chosen
            ? ' It opens showing only the ' + many + ', once it is in that order.'
            : ' It opens showing only the ' + many + ' — but with no Sort By set those are whichever rows '
                + 'the call happened to return first, which is rarely what "top" is meant to mean.')
        + ' The cap is what the grid counts, exports and analyzes, not just what it draws, and the '
        + 'operator can raise it, lower it or clear it from the box above the grid.</span>';
}

/**
 * The grid's starting order. Its own setter rather than {@link #setProp} for the reason the row
 * check has one: the note under the pair has to keep up with what is picked, and redrawing the
 * whole panel to move it would take the caret out of the column name being typed into.
 */
function setGridSort(name, value) {
    const c = findControl(selectedId);
    if (!c) return;
    // The cap is a count, not text: held as a number so the page saves one and every reader can
    // compare it without parsing. A box cleared, or filled with something that is not a whole
    // count of rows, is no cap — see {@link #normalizeTopRows}.
    c[name] = name === 'topRows' ? normalizeTopRows(value) : value;
    const note = document.getElementById('gridSortNote');
    if (note) note.innerHTML = gridSortNote(c);
    renderControlList();
    renderCanvas();
}

/** What the grid's status will do, kept up to date as it is set — see {@link #setGridStatus}. */
function gridStatusNote(c) {
    if (!c.statusCondition) {
        return '<span class="hint">Optional. Judge the grid as a whole by how many rows it holds after filtering: '
            + '<b>ROWCOUNT = 0</b> suits a grid of errors, where nothing found is the success.</span>';
    }
    const name = (c.statusVariable || '').trim();
    if (name && !/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
        return '<span class="hint" style="color:#bf2600">A variable name is letters, digits and underscores, '
            + 'starting with a letter or an underscore. The page will not save until it is.</span>';
    }
    return '<span class="hint">SUCCESS when the rows left after filtering satisfy <code>' + AC.esc(c.statusCondition)
        + '</code>, FAILED otherwise — and FAILED whenever the call that fills the grid fails. '
        + (name ? 'Actions read it as <code>${' + AC.esc(name) + '}</code>; it is blank until the grid is filled.'
                : 'Name a variable to let actions and other grids read it.') + '</span>';
}

/** Its own setter for the reason {@link #setGridSort} has one: the note keeps up without a redraw. */
function setGridStatus(name, value) {
    const c = findControl(selectedId);
    if (!c) return;
    c[name] = name === 'statusVariable' ? value.trim() : value;
    const note = document.getElementById('gridStatusNote');
    if (note) note.innerHTML = gridStatusNote(c);
    renderControlList();
    renderCanvas();
}

/**
 * What the row check says as it is typed: what it is written in, or what is wrong with it.
 *
 * <p>Shown here rather than only at the save, because an expression is fiddly to get right and
 * the round trip through a save is a poor place to find out you left a bracket open. The save
 * still refuses it — see AppCatalogService#validateRowErrorExpression — but by then this has
 * usually already said so.
 */
function rowCheckNote(c, what) {
    const expression = (c.rowErrorExpression || '').trim();
    if (!expression) {
        return '<span class="hint">Columns by name — <code>STATUS</code>, <code>RECORDCOUNT</code> — matched however '
            + 'they are capitalised. Tests: <code>=</code> <code>!=</code> <code>&gt;</code> <code>&lt;</code> '
            + '<code>&gt;=</code> <code>&lt;=</code> <code>~</code> (contains) <code>!~</code> (does not). Join them '
            + 'with <code>||</code> or <code>&amp;&amp;</code>, negate with <code>!</code>, group with brackets. '
            + 'A word that is not one of the row\'s columns is the text itself, so neither side of '
            + '<code>STATUS != SUCCESS</code> needs quoting; quote one — <code>\'N/A\'</code> — to mean it literally '
            + 'where a column shares its name.</span>';
    }
    const parsed = parseRowCheck(expression);
    return parsed.ok
        ? '<span class="hint" style="color:#006644">Reads as ' + (what || 'an error check') + '.</span>'
        : '<span class="hint" style="color:#bf2600">This cannot be read: ' + AC.esc(parsed.error)
            + '. The page will not save until it can.</span>';
}

/**
 * The grid's clickable columns: which cells drill down, and what a click on each one does.
 *
 * <p>Per column rather than per grid because a row routinely carries more than one thing worth
 * following — the order and the customer who placed it — and clicking either should ask a
 * different question. The grid itself stays untriggerable: there is no clicking a grid, only a
 * cell in one.
 */
function columnLinkProps(c) {
    const links = c.columnLinks || [];
    const library = page.actions || [];
    const targets = page.controls.filter(t => t.controlId !== c.controlId && ASSIGN_TYPES.includes(t.type));

    let html = '<div class="props-section"><div class="props-title"><span>Clickable Columns</span>'
             + '<button class="tool-btn" onclick="addColumnLink()">+ Add</button></div>'
             + '<span class="hint">A column whose cells drill down. Clicking one puts values from '
             + '<b>that row</b> onto the page, then runs the actions listed — click an order id and the grid '
             + 'below reloads for it. In a value, <code>${field}</code> is read off the clicked row first and '
             + 'off the page\'s own controls for whatever the row does not answer; blank hands over the '
             + 'clicked cell itself.</span>';

    if (!links.length) {
        html += '<div class="empty-note">No columns drill down — this grid is somewhere answers land and stop.</div>';
    }

    html += links.map((link, i) => {
        const assignments = link.assignments || [];
        const chosen = link.actionIds || [];

        let block = '<div class="col-link"><div class="col-link-head">'
            + '<input type="text" placeholder="column name" value="' + AC.attr(link.column || '') + '"'
            + ' oninput="setColumnLink(' + i + ', \'column\', this.value)">'
            + '<button class="icon-btn" onclick="removeColumnLink(' + i + ')" title="Stop this column drilling down">×</button>'
            + '</div>';

        block += '<div class="sub-title"><span>Sets</span>'
            + (targets.length ? '<button class="tool-btn" onclick="addColumnLinkAssignment(' + i + ')">+ Add</button>' : '')
            + '</div>';
        if (!targets.length) {
            block += '<div class="empty-note">Nothing to write into — add a text box, a hidden field or a label.</div>';
        } else if (!assignments.length) {
            block += '<div class="empty-note">Sets nothing yet.</div>';
        } else {
            block += assignments.map((a, s) =>
                '<div class="assign-row">'
                    + '<select onchange="setColumnLinkAssignment(' + i + ', ' + s + ', \'targetControlId\', this.value)">'
                        + '<option value="">— pick a control —</option>'
                        + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                            + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
                    + '</select>'
                    + '<input type="text" placeholder="the clicked cell" value="' + AC.attr(a.value || '') + '"'
                        + ' oninput="setColumnLinkAssignment(' + i + ', ' + s + ', \'value\', this.value)">'
                    + '<button class="icon-btn" onclick="removeColumnLinkAssignment(' + i + ', ' + s + ')" title="Remove">×</button>'
                + '</div>').join('');
        }

        block += '<div class="sub-title"><span>Runs</span></div>';
        if (!library.length) {
            block += '<div class="empty-note">The page has no actions yet — '
                + '<button class="tool-btn" onclick="showPageActions()">add one</button> and it can run from here.</div>';
        } else {
            block += library.map(a => {
                const on = chosen.includes(a.actionId);
                const order = on ? chosen.indexOf(a.actionId) + 1 : 0;
                return '<label class="inline-check"><input type="checkbox"' + (on ? ' checked' : '')
                    + ' onchange="toggleColumnLinkAction(' + i + ', \'' + AC.attr(a.actionId) + '\', this.checked)"> '
                    + (order ? '<b>' + order + '.</b> ' : '') + AC.esc(a.actionLabel || a.actionId) + '</label>';
            }).join('');
        }
        return block + '</div>';
    }).join('');

    return html + '</div>';
}

/**
 * What a tab set holds, and the ways to change it that do not involve dragging. The dragging is
 * the point — a tab set is built by pulling grids onto it on the layout — but a list with arrows
 * is what makes the order editable when the chips are too small to aim at, and what says plainly
 * which grids are in here when the control is only a few rows tall.
 */
function tabsProps(c) {
    const children = tabChildren(c);
    let html = '<div class="props-section"><div class="props-title"><span>Tabs</span>'
        + '<button class="tool-btn" onclick="addTabChild(\'grid\')">+ Grid</button>'
        + '<button class="tool-btn" onclick="addTabChild(\'pie\')">+ Pie</button>'
        + '<button class="tool-btn" onclick="addTabChild(\'bar\')">+ Bar</button>'
        + '<button class="tool-btn" onclick="addTabChild(\'text\')">+ Text</button>'
        + '<button class="tool-btn" onclick="addTabChild(\'tabs\')" title="A group of tabs inside this one">+ Tabs</button>'
        + '<button class="tool-btn" onclick="addTabChild(\'panel\')" title="A box of controls as this tab\'s content">+ Panel</button></div>'
        + '<span class="hint">Drag any control from the layout — or a new one from the palette — onto this '
        + 'control and it becomes a tab. Ten of them down a page become ten tabs over one. A tab shows its '
        + 'name, and how the call behind it went where it is a grid or a chart; actions still target the '
        + 'control itself, so nothing else has to change to move one in here. The only thing that cannot come '
        + 'in is a hidden field, which is not on screen for a tab to show.</span>'
        + '<span class="hint">A tab may be <b>another tab set</b>, which is how a strip that has grown too long '
        + 'is grouped: eight environments’ worth of grids read far better as two tabs of four than as one '
        + 'row of eight names. The outer tab then answers for everything inside it at once — <b>success</b> only '
        + 'where every tab within it is, <b>error</b> where one of them found bad rows, <b>failure</b> where a '
        + 'call failed — so the whole group is one badge to read rather than four tabs to open. Nest as deep as '
        + 'the page needs; the only arrangement refused is a set that ends up holding itself.</span>'
        + '<span class="hint">A tab may also be a <b>panel</b>, which is the way to give one tab a whole small '
        + 'form rather than a single control — and the tab then answers for every grid inside that panel, '
        + 'exactly as it does for a group of tabs.</span>';

    if (!children.length) {
        return html + '<div class="empty-note">No tabs yet.</div></div>';
    }
    // A default only means something once there is a choice of tab to open on.
    const choosable = children.length > 1;
    html += children.map((child, i) =>
        '<div class="opt-row" style="grid-template-columns:' + (choosable ? '30px ' : '') + '1fr 30px 30px 30px">'
            + (choosable
                ? '<button class="tool-btn" onclick="setDefaultTab(\'' + AC.attr(child.controlId) + '\')"'
                    + ' title="' + (isDefaultTab(c, child.controlId) ? 'The default tab — click to open on the first tab instead'
                        : 'Make this the tab the set opens on') + '"'
                    + (isDefaultTab(c, child.controlId) ? ' style="color:#ff8b00;border-color:#0052cc;background:#deebff"' : '') + '>'
                    + (isDefaultTab(c, child.controlId) ? '★' : '☆') + '</button>'
                : '')
            + '<button class="tool-btn" style="text-align:left' + (isDefaultTab(c, child.controlId) ? ';font-weight:600' : '') + '" onclick="selectControl(\'' + AC.attr(child.controlId) + '\')">'
                + (i + 1) + '. ' + AC.esc(controlTitle(child))
                + (child.type === 'tabs'
                    ? ' (' + tabChildren(child).length + ' tab' + (tabChildren(child).length === 1 ? '' : 's') + ' inside)'
                    : '') + '</button>'
            + (i > 0 ? '<button class="tool-btn" onclick="moveTab(' + i + ', -1)" title="Earlier">←</button>' : '<span></span>')
            + (i < children.length - 1 ? '<button class="tool-btn" onclick="moveTab(' + i + ', 1)" title="Later">→</button>' : '<span></span>')
            + '<button class="icon-btn" onclick="detachFromTabs(\'' + AC.attr(child.controlId) + '\', null)" title="Take out of the tabs">×</button>'
        + '</div>').join('');
    if (choosable) {
        html += '<span class="hint">★ marks the default tab: the one showing when the page opens, and marked on the '
            + 'strip. With none starred the set opens on its first tab.</span>';
    }
    return html + '</div>';
}

/** Whether this grid is the tab its set opens on. */
function isDefaultTab(tabs, gridId) {
    return !!tabs && !!gridId && tabs.defaultTabControlId === gridId && (tabs.tabControlIds || []).length > 1;
}

/** Stars a tab of the selected set as its default, or — clicked on the starred one — unstars it. */
function setDefaultTab(gridId) {
    const tabs = findControl(selectedId);
    if (!tabs || tabs.type !== 'tabs') return;
    tabs.defaultTabControlId = tabs.defaultTabControlId === gridId ? '' : gridId;
    renderAll();
}

/** A grid or a chart created straight into the selected tab set — the usual next thing after adding one. */
function addTabChild(type) {
    const tabs = findControl(selectedId);
    if (!tabs || tabs.type !== 'tabs' || !isTabChild(type)) return;
    const childId = addControl(type, { row: tabs.row, col: tabs.col }, true);
    const child = findControl(childId);
    child.label = 'Tab ' + (tabs.tabControlIds.length + 1);
    tabs.tabControlIds.push(childId);
    selectedId = tabs.controlId;
    renderAll();
}

function moveTab(index, delta) {
    const tabs = findControl(selectedId);
    if (!tabs) return;
    const target = index + delta;
    if (target < 0 || target >= tabs.tabControlIds.length) return;
    [tabs.tabControlIds[index], tabs.tabControlIds[target]] = [tabs.tabControlIds[target], tabs.tabControlIds[index]];
    renderAll();
}

/** Every metadata field an action can bind, for the cheat-sheet the METADATA source puts up. */
const META_FIELDS = ['url', 'statusCode', 'status', 'httpMethod', 'timeTaken', 'appName', 'environment',
    'envClass', 'useCase', 'executionId', 'requestSize', 'responseSize', 'executedVia', 'instanceLabel',
    'appUseCaseInstanceId', 'startedAt', 'startedAtText', 'runIndex', 'runCount', 'unresolvedVariables', 'error'];

/**
 * What a path can do beyond dotted names, said once because both path fields say it. The
 * placeholder part is the reason it is worth saying: a path is resolved when the action runs, so
 * it can name the row the operator picked rather than a row fixed at design time.
 */
const PATH_HINT = 'Segments split on <code>.</code> or <code>/</code>; <code>[0]</code> indexes and '
    + '<code>[id="A-7"]</code> filters; <code>${fieldName}</code> fills in a control\'s value — '
    + '<code>data[id="${auctionId}"]/referenceEntities</code>. A name read off an array maps over it.';

/**
 * An apostrophe, for the hints below. Several of them are assembled inside attributes and inside
 * single-quoted strings at once, where a bare <code>'</code> ends the string it is in and an
 * escaped one has to survive a round trip that not every one of these makes; the entity is the
 * one form that means an apostrophe wherever it lands.
 */
const Q = '&#39;';

/**
 * What holding one action back means, said once because the card and the summary both lean on it.
 */
const DEPENDS_HINT = 'Holds this action back until the one named here has come back and bound what it '
    + 'returned, instead of going out with the rest. That is what lets its inputs read '
    + '<code>${fieldName}</code> off a box — or its path read a row — that the earlier action has just '
    + 'filled in. Left at nothing, which is the default, it goes out together with every other '
    + 'independent action in the same trigger: faster, and what you want unless one genuinely needs '
    + 'the other. Whatever it waits for has to be something the same trigger runs, and if that fails, '
    + 'or is itself skipped, this action is never sent. It still shares a call with anything else '
    + 'in the trigger that resolves to the same instance, environment and inputs, so tick "Always '
    + 'make its own call" below when the point of waiting is to send something again rather than '
    + 'to read something new.';

/**
 * The actions this one could wait for. A control's action may wait for anything else that control
 * runs — a page action it triggers, or another written on it — because they go out together and
 * the order between them is the only thing a dependency changes. A library action may only wait
 * for another library action: it runs wherever it happens to be attached, and one particular
 * control's own action is not there to be waited for from the next control along.
 *
 * <p>Read off the editor rather than taken as an argument, because the card is the editor's body
 * and there is nowhere else it is drawn — see {@link #renderEditor}.
 */
function dependencyPeers(a) {
    if (!editor || editor.kind !== 'action') return [];
    const mine = a.actionId;
    if (editor.scope === 'page') return (page.actions || []).filter(x => x.actionId !== mine);
    const control = findControl(editor.controlId) || {};
    return actionsByIds(control.actionIds).concat(control.actions || [])
        .filter(x => x.actionId !== mine);
}

/**
 * The peers as options. A dependency on something no longer there is kept in the list rather than
 * quietly dropped: the select would otherwise fall back to "nothing", which reads as an action
 * that never had a dependency — the one thing a stale reference must not be mistaken for.
 */
function dependencyOptions(a) {
    const peers = dependencyPeers(a);
    const chosen = a.dependsOnActionId || '';
    const dangling = chosen && !peers.some(p => p.actionId === chosen);
    return '<option value="">&mdash; nothing; runs with the rest &mdash;</option>'
        + peers.map(p => '<option value="' + AC.attr(p.actionId) + '"' + (p.actionId === chosen ? ' selected' : '') + '>'
            + AC.esc(p.actionLabel || p.actionId)
            + (isPageAction(p.actionId) ? ' (page action)' : '') + '</option>').join('')
        + (dangling ? '<option value="' + AC.attr(chosen) + '" selected>'
            + AC.esc(chosen) + ' &mdash; no longer on this page</option>' : '');
}

function isPageAction(actionId) {
    return (page.actions || []).some(x => x.actionId === actionId);
}

/** An action anywhere on the page by id, for naming whatever something else waits for. */
function actionNamed(actionId) {
    return actionId ? allActions().find(a => a.actionId === actionId) || null : null;
}

/**
 * The note a trigger gets when it runs an action that waits for one it does not itself run. The
 * wait belongs to the action, not to the control, so attaching it somewhere the thing it waits
 * for is not attached leaves it with nothing to wait for — it simply goes out with the rest.
 *
 * <p>Said here, in the designer, rather than at run time: it is a wiring mistake only the person
 * building the page can fix, and complaining about it on every click would put it in front of the
 * one person who cannot.
 */
function dependencyNote(list) {
    const present = new Set(list.map(a => a.actionId));
    const unmet = list.filter(a => a.dependsOnActionId && !present.has(a.dependsOnActionId));
    if (!unmet.length) return '';
    return '<div class="empty-note">' + unmet.map(a => {
        const waited = actionNamed(a.dependsOnActionId);
        return '<b>' + AC.esc(a.actionLabel || 'An action') + '</b> waits for '
            + (waited ? '<b>' + AC.esc(waited.actionLabel || waited.actionId) + '</b>'
                      : 'an action that is no longer here')
            + ', which this control does not run';
    }).join('; ') + ' — so nothing holds it back and it goes out with the others. Attach what it '
        + 'waits for here as well, or clear the wait on the action itself.</div>';
}

/**
 * Where an action's answers may land, which depends on how many answers it is going to have.
 * Run once, it is the long-standing list. Fanned out over a grid's rows it is narrower and means
 * something different: a tab set, because each row's answer is a table of its own, or a single
 * control the answers are collected into one at a time — a grid, a row per call, or a dropdown,
 * an option per call. Nothing else can hold one answer per row.
 */
function targetsFor(a) {
    // A summary is a table of six columns and a row per endpoint; a comparison is a table of the
    // paths that differ. Nothing else on a page holds a table, so either kind offers grids and
    // nothing else however it is otherwise set up.
    // A dataset's rows are ordinary rows, so they go wherever a list of rows goes: a grid, a
    // dropdown, a chart. Not a box or a link — each of those holds one value read out of a
    // response by path, and there is no response here for a path to read.
    if (isDatasetAction(a)) {
        return page.controls.filter(t => t.type === 'grid' || isSelect(t.type) || isChart(t.type));
    }
    if (isSpecialAction(a)) return page.controls.filter(t => t.type === 'grid');
    if (a.rowSourceControlId && a.rowOutputMode === 'TABS') return page.controls.filter(t => t.type === 'tabs');
    // Collected answers are a list, and a list fills a picker as readily as a table: forty calls
    // asking which of these are still open, and the ones that are become the dropdown the next
    // click is made from.
    if (a.rowSourceControlId) return page.controls.filter(t => t.type === 'grid' || isSelect(t.type));
    return page.controls.filter(t => TARGET_TYPES.includes(t.type));
}

/**
 * What an action can fan out over — every grid on the page except the one it fills, a row per
 * call, and every select or multi-select, an element per call.
 */
function rowSourceOptions(a) {
    const option = t => '<option value="' + AC.attr(t.controlId) + '"'
        + (t.controlId === a.rowSourceControlId ? ' selected' : '') + '>'
        + AC.esc(controlTitle(t)) + (isSelect(t.type) ? ' (' + t.type + ')' : '') + '</option>';
    // Never the control this action fills: a fan-out reading the rows it is about to overwrite
    // would be running over whatever the last click left behind.
    const grids = page.controls.filter(t => t.type === 'grid' && t.controlId !== a.targetControlId);
    const lists = page.controls.filter(t => isSelect(t.type) && t.controlId !== a.targetControlId);
    return '<option value="">— run once, against the page —</option>'
        + (grids.length ? '<optgroup label="Each row of a grid">' + grids.map(option).join('') + '</optgroup>' : '')
        + (lists.length ? '<optgroup label="Each element of a list">' + lists.map(option).join('') + '</optgroup>' : '');
}

// ── An action's inputs ───────────────────────────────────────────────────
// A use case declares what it expects to be handed — orderId, asOfDate, region — and an instance
// saves a value for each of them. What an action on a page does is vary some of those: this one
// takes its order id from the box the operator typed into, and leaves everything else as the
// instance has it.
//
// That was a map of JSON and nothing else, which asks whoever writes it to remember both halves
// from memory — what the use case's variables are called and what the page's controls are called
// — and misspells either of them in silence, since a name nothing answers to is quietly left out
// rather than reported. So the variables are listed instead, one row each, saying where that
// row's value comes from: the instance's own, a control on this page, or something typed here.
//
// The map is still underneath and still reachable, because a value that mixes text with a
// placeholder — "ORD-${orderId}" — or is built out of two of them is a real thing to want, and
// no list of dropdowns writes it.

/** The use case behind an instance: what declares the variables the instance carries values for. */
function useCaseOf(instance) {
    if (!instance) return null;
    return useCases.find(u => u.appName === instance.appName && u.useCaseName === instance.appUseCaseName) || null;
}

/**
 * The variables one action can supply, in the order they are worth reading: what the use case
 * declares, then anything the instance was saved with that it no longer declares, then anything
 * this action already writes that neither of them names.
 *
 * <p>The last two are why this is a union rather than simply the declaration. A use case that has
 * dropped a variable leaves every instance still carrying it, and an action written before the
 * declaration existed may name one of its own — and a list showing only what is declared would
 * hide values the page is actually sending behind a tidier screen.
 */
function actionInputVariables(a) {
    const instance = instances.find(x => x.appUseCaseInstanceId === a.appUseCaseInstanceId);
    const saved = (instance && instance.appUseCaseInstanceInputs) || {};
    const seen = new Map();
    const add = (name, declared, type, fallback) => {
        if (!name || seen.has(name)) return;
        seen.set(name, { name: name, declared: declared, type: type || 'string',
                         instanceValue: saved[name], defaultValue: fallback });
    };
    (((useCaseOf(instance) || {}).appUseCaseInputs) || []).forEach(v => add(v.name, true, v.type, v.defaultValue));
    Object.keys(saved).forEach(name => add(name, false));
    Object.keys(a.inputs || {}).forEach(name => add(name, false));
    return [...seen.values()];
}

// Which half of the inputs editor an action is showing, and which way each of its variables is
// being answered. Designer state, not part of the page: what is saved is the map itself, and a
// variable answered by nothing is simply a name the map does not carry.
//
// It has to be held all the same, and that is the whole of why this exists. A row switched to "a
// control on this page" has written nothing yet — there is no control picked — so the redraw that
// follows would read the empty map back, decide the variable is answered by the instance and put
// the row where it started, before anybody could pick from the dropdown it had just been given.
// The same shape of bug as #linkModePick, and held the same way.
let inputVarMode = {};
let inputsAsJson = {};

/**
 * One action's place in the designer state above. The instance is part of it because picking a
 * different one asks about a different set of variables entirely.
 */
function inputsKey(a, i, fns) {
    return (a.appUseCaseInstanceId || '-') + '#' + i + '#' + fns.inputs;
}

/** Where a variable's value comes from — what the row was last set to, or what its value says. */
function inputVarModeOf(a, key, name) {
    const held = inputVarMode[key + '|' + name];
    if (held) return held;
    const written = (a.inputs || {})[name];
    if (written === undefined || written === null) return 'DEFAULT';
    return typeof written === 'string' && /^\$\{[A-Za-z0-9_.\-]+\}$/.test(written) ? 'CONTROL' : 'CONSTANT';
}

/** The name a <code>${field}</code> row points at, or blank while it points at nothing yet. */
function inputVarField(a, name) {
    const written = (a.inputs || {})[name];
    const m = typeof written === 'string' ? /^\$\{([A-Za-z0-9_.\-]+)\}$/.exec(written) : null;
    return m ? m[1] : '';
}

/**
 * One variable of one action, written the way the row it came from means it. Shared by the three
 * places an action is edited, exactly as the JSON textarea's three mutators are.
 *
 * @param what 'MODE' where the value comes from, 'VALUE' the value itself
 * @return whether the panel has to be redrawn — a mode change asks a different question, so the
 *         field beside it becomes a different field
 */
function applyInputVar(a, key, name, what, value) {
    if (!a.inputs) a.inputs = {};
    if (what === 'MODE') {
        inputVarMode[key + '|' + name] = value;
        // Whatever was there answered the question that has just been replaced: a constant is not
        // a field name and a field name is not a constant, so neither survives being carried
        // across. The row is emptied, and an empty row is one the instance answers for itself.
        delete a.inputs[name];
        return true;
    }
    const written = inputVarModeOf(a, key, name) === 'CONTROL' ? (value ? '${' + value + '}' : '') : value;
    // Blank means "not sent", which is what leaves the instance the value it was saved with.
    // Writing an empty string would overwrite that value with nothing, which is a different thing
    // and almost never the thing meant.
    if (written === '') delete a.inputs[name]; else a.inputs[name] = written;
    return false;
}

/** Switches one action's inputs between the list of variables and the raw map. */
function toggleInputsJson(key) {
    inputsAsJson[key] = !inputsAsJson[key];
}

/**
 * What a variable can be read off, written <code>${name}</code> either way so the list is one of
 * names rather than of kinds: the page's own controls, the variables every page carries, and —
 * under a fan-out — the columns of the row the call is being made for, which win over a control
 * of the same name and so are listed first.
 */
function inputSourceOptions(a, selected) {
    const option = (name, label) => '<option value="' + AC.attr(name) + '"'
        + (name === selected ? ' selected' : '') + '>' + AC.esc(label || name) + '</option>';
    const controls = page.controls.filter(c => VALUE_TYPES.includes(c.type) && c.fieldName);
    const source = findControl(a.rowSourceControlId);
    const columns = !source ? [] : isSelect(source.type) ? ['key', 'label'] : (source.columns || []);
    const variables = (page.variables || []).map(v => v.name).filter(Boolean);
    let html = '<option value="">— pick where it comes from —</option>';
    if (columns.length) html += '<optgroup label="Each row' + Q + 's own column">'
        + columns.map(c => option(c)).join('') + '</optgroup>';
    if (controls.length) html += '<optgroup label="Controls on this page">'
        + controls.map(c => option(c.fieldName, controlTitle(c) + ' (${' + c.fieldName + '})')).join('') + '</optgroup>';
    if (variables.length) html += '<optgroup label="This page' + Q + 's variables">'
        + variables.map(v => option(v, '${' + v + '}')).join('') + '</optgroup>';
    html += '<optgroup label="Built in">'
        + BUILT_IN_VARIABLES.map(v => option(v.name, '${' + v.name + '}')).join('') + '</optgroup>';
    // A name nothing on the page answers to is still what this action reads. Dropping it from the
    // list would rewire the page by redrawing it — the dropdown would settle on whatever happened
    // to be first — so it is offered back, said to be missing.
    if (selected && !columns.includes(selected) && !variables.includes(selected)
            && !controls.some(c => c.fieldName === selected)
            && !BUILT_IN_VARIABLES.some(v => v.name === selected)) {
        html += option(selected, selected + ' — nothing on the page answers to this');
    }
    return html;
}

/**
 * One variable: what it is called, what the instance holds for it, and where this action's value
 * comes from.
 */
function inputVarRow(a, i, fns, key, v) {
    const mode = inputVarModeOf(a, key, v.name);
    const name = String(v.name).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const call = (what, expr) => fns.inputVar + '(' + i + ', \'' + name + '\', \'' + what + '\', ' + expr + ')';
    const text = value => value === undefined || value === null ? ''
        : typeof value === 'object' ? JSON.stringify(value) : String(value);
    // What this variable is worth without the action: the instance's saved value, or failing that
    // whatever the use case declares as its default. Shown on every row, because "leave it alone"
    // is only a decision somebody can make if they can see what leaving it alone sends.
    const held = text(v.instanceValue) || text(v.defaultValue);
    const written = (a.inputs || {})[v.name];

    const widget = mode === 'CONTROL'
        ? '<select onchange="' + call('VALUE', 'this.value') + '">'
            + inputSourceOptions(a, inputVarField(a, v.name)) + '</select>'
        : mode === 'CONSTANT'
        ? '<input type="text" placeholder="' + AC.attr(held || 'sent as written') + '" value="'
            + AC.attr(text(written)) + '" oninput="' + call('VALUE', 'this.value') + '">'
        : '<input type="text" disabled value="' + AC.attr(held) + '" placeholder="— nothing saved —">';

    return '<div class="input-var">'
        + '<div class="input-var-head">'
            + '<span class="input-var-name">' + AC.esc(v.name) + '</span>'
            + '<span class="input-var-type' + (v.declared ? '' : ' undeclared') + '">'
                + AC.esc(v.declared ? v.type : 'not declared') + '</span>'
        + '</div>'
        + '<div class="input-var-row">'
            + '<select onchange="' + call('MODE', 'this.value') + '">'
                + '<option value="DEFAULT"' + (mode === 'DEFAULT' ? ' selected' : '') + '>Instance' + Q + 's own</option>'
                + '<option value="CONTROL"' + (mode === 'CONTROL' ? ' selected' : '') + '>From a control</option>'
                + '<option value="CONSTANT"' + (mode === 'CONSTANT' ? ' selected' : '') + '>Fixed value</option>'
            + '</select>'
            + widget
        + '</div>'
    + '</div>';
}

/** The raw map, which is what every one of these editors used to be on its own. */
function inputsTextarea(a, i, fns) {
    return '<textarea spellcheck="false" placeholder=\'{"orderId": "${orderId}"}\' oninput="'
        + fns.inputs + '(' + i + ', this.value)">'
        + AC.esc(a.inputs && Object.keys(a.inputs).length ? JSON.stringify(a.inputs, null, 2) : '')
        + '</textarea>';
}

/**
 * The Inputs field: the use case's variables one row each, and the raw map behind them.
 *
 * <p>An action with no instance picked yet — or one whose use case declares nothing and whose
 * instance was saved with nothing — has no variables to list, so it gets the map on its own,
 * which is what this field has always been.
 *
 * @param note what these particular inputs are for, said before the shared explanation
 */
function inputsEditor(a, i, fns, note) {
    const key = inputsKey(a, i, fns);
    const variables = actionInputVariables(a);
    const json = !!inputsAsJson[key];
    const lead = note ? note + ' ' : '';

    if (!variables.length) {
        return field('Inputs', inputsTextarea(a, i, fns), lead
            + (a.appUseCaseInstanceId
                ? 'This instance' + Q + 's use case declares no variables, so there is nothing to list here yet. '
                : 'Pick an instance above and the variables it takes are listed here, each with a control to read '
                    + 'it from. ')
            + 'Use case input name to a value. <code>${fieldName}</code> picks up a control; anything else is '
            + 'passed as written. Unnamed inputs keep the instance' + Q + 's own value.');
    }

    return '<div class="form-group"><label class="with-tool">Inputs'
        + '<button class="tool-btn" onclick="toggleInputsJson(\'' + AC.attr(key) + '\'); ' + fns.redraw + '()">'
            + (json ? '← One row each' : 'Edit as JSON →') + '</button></label>'
        + (json ? inputsTextarea(a, i, fns)
                : variables.map(v => inputVarRow(a, i, fns, key, v)).join(''))
        + '<span class="hint">' + lead + (json
            ? 'The map exactly as it is sent: use case input name to a value. <code>${fieldName}</code> picks up '
                + 'a control, anything else is passed as written, and a name left out of it keeps the value the '
                + 'instance was saved with.'
            : 'A row per variable the use case takes. <b>Instance' + Q + 's own</b> sends nothing, leaving the value '
                + 'the instance was saved with — shown greyed beside it. <b>From a control</b> sends whatever the '
                + 'operator has put in that control at the moment the action runs. <b>Fixed value</b> sends exactly '
                + 'what is typed, and typing nothing sends nothing. Switch to JSON for whatever these three do not '
                + 'cover — a value that mixes text with a placeholder, or one built out of two of them.')
        + '</span></div>';
}

/**
 * One action's editor. Identical whether the action lives on a control, in the page's library, or
 * as the working copy open in the editor over the page — only which mutators the inputs call
 * differs, which `fns` carries — so the three can never drift into offering different fields.
 *
 * <p>A `fns` with no `remove` is the editor's: reordering and removing an action are things you
 * do to a list, and inside the dialog there is no list to do them to.
 */
function actionCard(a, i, count, fns) {
    const targets = targetsFor(a);
    const target = targets.find(t => t.controlId === a.targetControlId);
    const fanOut = !!a.rowSourceControlId;
    const perTab = fanOut && a.rowOutputMode === 'TABS';
    const rowSource = findControl(a.rowSourceControlId);
    // A box and a link are each filled from one attribute — the text one shows, the address the
    // other points at — so they ask for a value path instead of the array path the many-row
    // targets need.
    const isLink = !!target && target.type === 'link';
    const singleValue = !!target && (target.type === 'text' || target.type === 'textarea' || isLink);
    // Reading one object down the page as key/value is a thing a whole grid does. Under a
    // fan-out into one grid there is no whole grid to do it to — each answer is a row among the
    // others — so it is only offered where a grid still holds one answer: the ordinary case, and
    // a tab per row, where every tab is its own grid.
    const isGridTarget = !fanOut
        ? (a.targetControlId === NEW_GRID || (target && target.type === 'grid'))
        : perTab;
    // Adding to what a grid holds needs a grid that is still there next run, so it is offered on
    // a placed grid and nowhere else: "new grid" builds another one per run and already keeps
    // them all, and a tab per row builds a grid per call with nothing in it to add to.
    const appendGrid = !perTab && !!target && target.type === 'grid';
    // A chart takes many rows the way a grid does — one wedge each — so it asks for an array
    // path, and for the two fields that turn a row into a named, sized slice.
    const isPie = !!target && isChart(target.type);
    // A dropdown takes a list the way a grid does, so a collected fan-out may fill one — but it
    // shows one field per row rather than a table, which is what the group-by below turns on.
    const listTarget = !!target && isSelect(target.type);
    const meta = a.source === 'METADATA';
    const sourceIsList = !!rowSource && isSelect(rowSource.type);
    const set = (name, expr) => fns.set + '(' + i + ', \'' + name + '\', ' + expr + ')';

    const head = '<div class="action-card">'
        + '<div class="action-head"><span class="action-num">' + (i + 1) + '</span>'
        + '<input type="text" placeholder="action name" value="' + AC.attr(a.actionLabel || '') + '" oninput="' + set('actionLabel', 'this.value') + '">'
        + (i > 0 ? '<button class="tool-btn" onclick="' + fns.move + '(' + i + ', -1)" title="Earlier">↑</button>' : '')
        + (i < count - 1 ? '<button class="tool-btn" onclick="' + fns.move + '(' + i + ', 1)" title="Later">↓</button>' : '')
        + (fns.remove ? '<button class="icon-btn" onclick="' + fns.remove + '(' + i + ')" title="Remove">×</button>' : '')
        + '</div>'
        + field('Does', '<select onchange="' + fns.kind + '(' + i + ', this.value)">'
            + '<option value="' + USECASE_ACTION + '"' + (isSpecialAction(a) ? '' : ' selected') + '>Run a use case instance</option>'
            + '<option value="' + PERFORMANCE_ACTION + '"' + (isPerformanceAction(a) ? ' selected' : '') + '>Show performance details</option>'
            + '<option value="' + COMPARE_ACTION + '"' + (isCompareAction(a) ? ' selected' : '') + '>Compare two environments</option>'
            + '<option value="' + DATASET_ACTION + '"' + (isDatasetAction(a) ? ' selected' : '') + '>Load a static dataset</option>'
            + '</select>')
        + field('Runs After', '<select onchange="' + set('dependsOnActionId', 'this.value') + '">'
            + dependencyOptions(a) + '</select>', DEPENDS_HINT);

    // A special kind calls nothing, so none of what follows — an instance, an environment, a
    // response to read a path out of — describes anything it does. Its own short form is drawn
    // instead rather than the long one with most of its fields disabled, which would leave the
    // panel asking questions the action has no answers to.
    if (isPerformanceAction(a)) return head + performanceFields(a, i, targets, target, fns, set) + '</div>';
    if (isCompareAction(a)) return head + compareFields(a, i, targets, fns, set) + '</div>';
    if (isDatasetAction(a)) return head + datasetFields(a, i, targets, target, fns, set) + '</div>';

    // What the call is — sent once, however many places its answer goes.
    const callPart = field('Instance', '<select onchange="' + set('appUseCaseInstanceId', 'this.value') + '">' + instanceOptions(a.appUseCaseInstanceId) + '</select>')
        + field('For Each Row Of', '<select onchange="' + set('rowSourceControlId', 'this.value') + '">'
            + rowSourceOptions(a) + '</select>',
            fanOut && sourceIsList
                ? 'Sent once per element of <b>' + AC.esc(controlTitle(rowSource)) + '</b>, all of them at once. Below, '
                    + '<code>${' + AC.esc(rowSource.fieldName || 'field') + '}</code> is that one element rather than every pick '
                    + 'joined together, <code>${key}</code> is its value and <code>${label}</code> the text shown for it — '
                    + 'so <code>{"env": "${' + AC.esc(rowSource.fieldName || 'field') + '}"}</code> makes a call per element. '
                    + '<code>${ROWNUM}</code> is which element it is, from 1.'
                : fanOut
                ? 'Sent once per row of <b>' + AC.esc(rowSource ? controlTitle(rowSource) : 'a control that is no longer here')
                    + '</b>, all of them at once. Below, <code>${column}</code> is that row&#39;s cell before it is '
                    + 'anything on the page — so <code>{"orderId": "${id}"}</code> asks about each row&#39;s own id, '
                    + 'and a name the row has no column for still falls back to the control of that name. '
                    + '<code>${ROWNUM}</code> is which row it is, from 1, and <code>${UUID}</code> is a fresh one per call.'
                : 'Leave this alone and the action runs once, reading the page&#39;s own controls. Point it at a grid '
                    + 'and it runs once per row of that grid instead — the list a lookup just produced is usually '
                    + 'the list the next call has to be made for. Point it at a select or a multi-select and it runs '
                    + 'once per element of the list.')
        + (sourceIsList
            ? field('Elements', '<select onchange="' + set('rowElements', 'this.value') + '">'
                + '<option value=""' + (!a.rowElements ? ' selected' : '') + '>Default — '
                    + (rowSource.type === 'multiselect' ? 'the picked ones' : 'every option') + '</option>'
                + '<option value="SELECTED"' + (a.rowElements === 'SELECTED' ? ' selected' : '') + '>Only the picked ones</option>'
                + '<option value="ALL"' + (a.rowElements === 'ALL' ? ' selected' : '') + '>Every option in the list</option>'
                + '</select>',
                'Which elements of the list get a call. A multi-select defaults to what the operator picked; a select, which '
                    + 'only ever has one pick, defaults to every option.')
            : '')
        + (fanOut
            ? '<div class="form-row" style="margin-bottom:0">'
                + field('Answers Land', '<select onchange="' + set('rowOutputMode', 'this.value') + '">'
                    + '<option value="ROWS"' + (perTab ? '' : ' selected') + '>All in one grid, a row per call</option>'
                    + '<option value="TABS"' + (perTab ? ' selected' : '') + '>A tab each, a grid per call</option>'
                    + '</select>')
                + field('Most Rows', '<input type="number" min="0" step="1" value="' + AC.attr(a.rowLimit === undefined ? DEFAULT_ROW_LIMIT : a.rowLimit)
                    + '" oninput="' + set('rowLimit', '+this.value') + '">')
              + '</div>'
            + field('Each Called', '<input type="text" placeholder="${id}" value="' + AC.attr(a.rowLabelTemplate || '')
                + '" oninput="' + set('rowLabelTemplate', 'this.value') + '">',
                perTab
                    ? 'What each tab is named, read off the row it came from — <code>${id}</code> names every tab after '
                        + 'its own row. Blank numbers them.'
                    : 'What goes in the leading <code>' + FAN_SOURCE_COLUMN + '</code> column, so a row in the collected '
                        + 'grid says which call produced it. Blank numbers them.')
            + (perTab
                ? field('Display Filter', '<input type="text" value="' + AC.attr(a.displayFilterExpression || '')
                        + '" placeholder="STATUS = FAILED || RECORDCOUNT > 0" oninput="'
                        + set('displayFilterExpression', 'this.value') + '; refreshActionRowCheckNote(this, \'filter\')">',
                    'Optional. Put through every row of every tab' + Q + 's response as its grid fills; only the rows it '
                    + 'comes out <b>true</b> for are kept. Same syntax as the error check, which then judges only those rows.')
                    + '<div class="action-rowcheck-note" data-note="filter">'
                    + rowCheckNote({ rowErrorExpression: a.displayFilterExpression }, 'a display filter') + '</div>'
                + field('Error Check', '<input type="text" value="' + AC.attr(a.rowErrorExpression || '')
                        + '" placeholder="STATUS != SUCCESS || RECORDCOUNT = 0" oninput="'
                        + set('rowErrorExpression', 'this.value') + '; refreshActionRowCheckNote(this, \'check\')">',
                    'Optional. Put through every row of every tab' + Q + 's grid as it fills; a row it comes out <b>true</b> '
                    + 'for is an error, drawn in red. A tab whose call worked but holds such a row reads <b>ERROR</b> '
                    + 'rather than <b>SUCCESS</b>; one whose call failed reads <b>FAILURE</b> whatever its rows say.')
                    + '<div class="action-rowcheck-note" data-note="check">' + rowCheckNote(a) + '</div>'
                : '')
            + '<span class="hint">Only the rows on screen are called for: a grid the operator has filtered is one they '
                + 'have narrowed on purpose. <b>Most Rows</b> caps it however they filtered — 0 lifts the cap, which on '
                + 'a grid of any size is a great many calls at once, so the page says how many it left alone rather '
                + 'than quietly obliging. Calls resolving to the same instance, environment and inputs still share one '
                + 'flight unless <i>Always make its own call</i> is ticked below.</span>'
            + rowFilterEditor(a, i, fns)
            : '')
        + field('Environment', '<input type="text" value="' + AC.attr(a.environmentOverride || '') + '" placeholder="${envSelect}" oninput="' + set('environmentOverride', 'this.value') + '">',
            'Overrides which environment this run calls. <code>${fieldName}</code> picks up a control (usually a select sourced from App environments); leave blank to use the instance\'s own environment.')
        + inputsEditor(a, i, fns);

    // Where the answer goes: the action's own target, which is the first of its targets.
    const bindPart = field('Bind From', '<select onchange="' + fns.source + '(' + i + ', this.value)">'
            + '<option value="PAYLOAD"' + (meta ? '' : ' selected') + '>Response payload</option>'
            + '<option value="METADATA"' + (meta ? ' selected' : '') + '>Call metadata (URL, status, timing)</option>'
            + '</select>',
            meta
                ? 'Binds the call\'s own record instead of its body — and the body is never sent to the browser at all, so this stays cheap however large the response is. A failed call still binds, which is the point: the status code is what you came for. Fields: <code>'
                    + META_FIELDS.join('</code>, <code>') + '</code>.'
                : 'The response body, as every action has always bound.')
        + field('Transforms', chainEditor(a, i, fns),
            (page.transforms || []).length
                ? 'The page\'s named steps, run in the order listed over what was bound, before the path below '
                    + 'reads out of the last one\'s output. An XML response wants an <code>xml&#8594;json</code> step '
                    + 'first, then whatever JSONata reshapes the result. Add none to bind the response as it arrived.'
                : 'No transforms yet — add them under Transforms in the page\'s own panel, then any action can chain them.')
        + field('Target', '<select onchange="' + set('targetControlId', 'this.value') + '">'
            + '<option value="">— no target —</option>'
            // A tab per row has to go into a tab set that is already laid out; there is nowhere
            // for "a new grid per run" to put a whole set of them.
            + (perTab ? ''
                : '<option value="' + NEW_GRID + '"' + (a.targetControlId === NEW_GRID ? ' selected' : '') + '>+ New grid ('
                    + (fanOut ? 'one holding every row' : 'one per run') + ')</option>')
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
            + '</select>',
            perTab && !targets.length
                ? 'Nowhere to put the tabs yet — drag a <b>Tabs</b> control onto the layout and aim this at it. Each '
                    + 'row of the source grid then gets a tab of its own, holding that call' + Q + 's answer.'
                : perTab
                ? 'A grid per row, laid out as tabs inside this set, each named after the row it came from. The tab '
                    + 'set' + Q + 's own grids stay where they are — these are added beside them, and Reset takes '
                    + 'them away again.'
                : fanOut && listTarget
                ? 'Every row' + Q + 's answer becomes an option of this dropdown, read through the key and label '
                    + 'fields below — so forty calls asking which of these are still open leave the operator a '
                    + 'picker of the ones that are. An answer that is itself a list contributes an option each, '
                    + 'and a call that failed contributes the row saying so, which the filters below can drop.'
                : fanOut
                ? 'Every row' + Q + 's answer becomes a row of this one grid, under a leading <code>'
                    + FAN_SOURCE_COLUMN + '</code> column saying which call produced it. An answer that is itself a '
                    + 'list contributes all of its rows, so a hundred calls returning three rows each read as three '
                    + 'hundred.'
                : a.targetControlId === NEW_GRID
                ? 'Every run adds its own grid below the form, newest on top, instead of replacing the last one.'
                : isLink
                ? 'What this binds becomes the address the link points at, so the operator can click '
                    + 'through to whatever the call named. It opens in a new tab, and only '
                    + '<code>http</code>, <code>https</code> or a path on this server is taken — anything '
                    + 'else is reported and the link is left without an address.'
                : isPie && target.type === 'timeseries'
                ? 'The rows this binds are read along the chart' + Q + 's time column and bucketed — a line per value of the '
                    + 'line column below (or one line), each point counting its rows or combining the value column(s).'
                : isPie && target.type === 'line'
                ? 'The rows this binds are read along the chart' + Q + 's x axis — which, unless the chart names an x column, '
                    + 'is the row' + Q + 's own position, so every tick along the bottom is a line of this response. A line per '
                    + 'value of the line column below, or one line, drawn from the value column(s).'
                : isPie && target.type === 'bar'
                ? 'The rows this binds are grouped by the category column below — a bar per category — and sized by '
                    + 'how many rows each holds, or by the sum of the value column(s).'
                : isPie && target.type === 'piegrid'
                ? 'The rows this binds become the chart' + Q + 's wedges, and each pie also fills a grid of its own in '
                    + 'the chart' + Q + 's tab set with those rows — click a slice to see just its rows there.'
                : isPie
                ? 'The rows this binds become the chart' + Q + 's wedges — one per row — in place of any '
                    + 'slices typed into the chart itself. Those are kept and come back if this action is '
                    + 'ever taken off, so a chart can be laid out with sample numbers and wired up afterwards.'
                : undefined)
        + (singleValue
            ? field('Value Path', '<input type="text" value="' + AC.attr(a.valuePath || '') + '" placeholder="'
                    + (isLink ? (meta ? 'url' : 'data.report.href') : (meta ? 'statusCode' : 'data.order.status')) + '" oninput="' + set('valuePath', 'this.value') + '">',
                isLink
                    ? (meta
                        ? 'Which metadata field the link points at — <code>url</code> is the one worth having here, '
                            + 'so the operator can open the endpoint the call actually went to.'
                        : 'Path to the address this link points at — <code>data.report.href</code>. ' + PATH_HINT)
                : meta
                    ? 'Which metadata field this box shows — <code>statusCode</code>, <code>url</code>, <code>timeTaken</code>. Blank puts the whole record in as JSON.'
                    : 'Path to the one attribute this box shows — <code>data.order.status</code> or <code>$.items[0].name</code>. ' + PATH_HINT + ' Blank puts the whole response in.')
            : field('Array Path', '<input type="text" value="' + AC.attr(a.arrayPath || '') + '" placeholder="data[id=&quot;${auctionId}&quot;]/entities" oninput="' + set('arrayPath', 'this.value') + '">',
                meta ? 'Leave blank — the metadata record is what gets bound.'
                : fanOut ? PATH_HINT + ' Read out of each call' + Q + 's own answer, and a <code>${name}</code> in it '
                    + 'is that call' + Q + 's row before it is anything on the page.'
                : PATH_HINT))
        + (isGridTarget
            ? '<label class="inline-check"><input type="checkbox"' + (a.keyValueGrid ? ' checked' : '')
                + ' onchange="' + set('keyValueGrid', 'this.checked') + '"> '
                + (meta ? 'Down the page as key/value (off: one row per run, so runs stack into a comparable table)'
                        : 'Show an object result as a key/value grid') + '</label>'
                + scalarsOnlyBox(a, set)
            : '')
        + appendRowsBox(a, set, appendGrid)
        + (fanOut && !perTab ? resultColumnEditor(a, i, fns) : '')
        // Every grid this action fills can take them: its own target, a new grid, each call's
        // row of a collected fan-out, or each tab of a tab-per-row one.
        + (a.targetControlId && (fanOut || isGridTarget)
            ? enrichColumnEditor(a.enrichColumns || [], (op, at, name, value) => fns.rows + '(' + i
                + ', \'enrichColumns\', \'' + op + '\', ' + at + ', ' + (name ? '\'' + name + '\'' : 'null')
                + ', ' + (value === undefined ? 'null' : value) + ')', fanOut)
            : '')
        // Which rows reach the control, on anything that takes a list of them: a grid, a new
        // grid, a dropdown, the grid a fan-out collects into, or each grid of a tab per row.
        // Drawn after the enriched columns and before the group-by, which is the order they run
        // in — a filter may test an enriched column, and what is grouped is what passed.
        + (a.targetControlId && (fanOut || isGridTarget || (target && isSelect(target.type)))
            ? bindFilterEditor(a.bindFilters || [],
                (op, at, name, value) => fns.rows + '(' + i + ', \'bindFilters\', \'' + op + '\', ' + at
                    + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')',
                target && isSelect(target.type) ? 'dropdown' : 'grid')
            : '')
        // A grouped table has one grid to go in: the action's own, a new one, or the grid a
        // fan-out collects into. A tab per row has a grid per call and no one table to group,
        // and a dropdown shows one field per row rather than a table at all.
        + (a.targetControlId && !listTarget && ((fanOut && !perTab) || (!fanOut && isGridTarget))
            ? pivotEditor(a.pivot, (op, at, name, value) => 'pivotDraft(-1, \'' + op + '\', ' + at + ', '
                + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')')
            : '')
        + (target && isSelect(target.type)
            ? '<div class="form-row" style="margin-bottom:0">'
                + field('Key Field', '<input type="text" value="' + AC.attr(a.keyField || '') + '" oninput="' + set('keyField', 'this.value') + '">')
                + field('Label Field', '<input type="text" value="' + AC.attr(a.labelField || '') + '" oninput="' + set('labelField', 'this.value') + '">')
              + '</div>'
            : '')
        + (isPie ? chartFieldsEditor(target.type, a, set) : '');

    const ownCall = '<label class="inline-check"><input type="checkbox"' + (a.ownCall ? ' checked' : '')
            + ' onchange="' + set('ownCall', 'this.checked') + '"> Always make its own call</label>'
        + '<span class="hint">Off, this action shares one HTTP call with any other action in the same '
            + 'trigger that resolves to the same instance, environment and inputs — writing two actions to read '
            + 'one response two ways costs one call. Tick it when the call itself is the point and must go out '
            + 'every time, like a POST that re-sends something.</span>';

    // In the editor, an action run once can bind its answer into several targets: they are laid
    // out as tabs — the action's own target first — so one is a click away rather than a scroll
    // down past all the others, and another is added from the same strip.
    if (fns.binding && !fanOut) return head + callPart + bindingTabs(a, bindPart, fns) + ownCall + '</div>';
    return head + callPart + bindPart + (fns.binding ? extraBindingsEditor(a, fanOut, fns) : '') + ownCall + '</div>';
}

/** What a target's tab is called: the control it fills, or what is still missing. */
function bindingTabTitle(b) {
    if (!b.targetControlId) return 'No target';
    if (b.targetControlId === NEW_GRID) return 'New grid';
    const target = findControl(b.targetControlId);
    return target ? controlTitle(target) + ' (' + target.type + ')' : 'Missing control';
}

/**
 * The action's targets as a tab strip over the one being edited. The first tab is the action's own
 * target — the fields that always were on the card — and each further target has a tab after it.
 * Which tab is open is kept on the editor, so a redraw (a changed target, an added transform) stays
 * on the target being worked on.
 */
function bindingTabs(a, ownPart, fns) {
    const bindings = a.extraBindings || [];
    const count = bindings.length + 1;
    const open = Math.min(Math.max((editor && editor.bindingTab) || 0, 0), count - 1);
    const call = (op, at, name, value) => fns.binding + '(\'' + op + '\', ' + at
        + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')';
    const tab = (index, title) => '<button type="button" class="binding-tab' + (index === open ? ' active' : '') + '"'
        + ' onclick="openBindingTab(' + index + ')" title="' + AC.attr(title) + '">'
        + '<span class="action-num">' + (index + 1) + '</span>' + AC.esc(title) + '</button>';

    return '<div class="props-title" style="margin-top:8px"><span>Targets</span></div>'
        + '<div class="binding-tabs">'
            + tab(0, bindingTabTitle(a))
            + bindings.map((b, at) => tab(at + 1, bindingTabTitle(b))).join('')
            + '<button type="button" class="binding-tab add" onclick="' + call('add', -1) + '" '
                + 'title="Bind this same call' + Q + 's answer into another control">+ Add target</button>'
        + '</div>'
        + '<div class="binding-pane">'
            + (open === 0 ? ownPart : bindingCard(bindings[open - 1], open - 1, bindings.length, call))
        + '</div>'
        + (count > 1 ? '' : '<span class="hint">One call, however many targets: add another to bind this same answer '
            + 'into more controls — a grid, a select, a pie chart and a text area from one response — each reading '
            + 'it on its own terms.</span>');
}

/** Switches the action editor to one of its targets' tabs. */
function openBindingTab(index) {
    if (!editor) return;
    editor.bindingTab = index;
    renderEditor();
}

/**
 * The action's further targets: the same response bound again, each its own way. One call can so
 * fill a grid, a select, a pie chart and a text area together, each with its own source, chain,
 * path and fields — the action's own target above is simply the first of them.
 *
 * <p>A fan-out has an answer per row rather than one response, so it takes none; any it already
 * carries are listed with a note to take them off, since the catalog refuses them on save.
 */
function extraBindingsEditor(a, fanOut, fns) {
    const bindings = a.extraBindings || [];
    const call = (op, at, name, value) => fns.binding + '(\'' + op + '\', ' + at
        + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')';

    if (fanOut) {
        return bindings.length
            ? '<div class="empty-note">This action runs once per row, so its ' + bindings.length + ' other target'
                + (bindings.length > 1 ? 's are' : ' is') + ' not used — a fan-out has an answer per row rather '
                + 'than one response to bind several ways. <button class="tool-btn" onclick="'
                + call('clear', -1) + '">Remove them</button></div>'
            : '';
    }

    return '<div class="props-title" style="margin-top:8px"><span>Also Bind To</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="' + call('add', -1) + '">+ Add target</button></span></div>'
        + (bindings.length
            ? bindings.map((b, at) => bindingCard(b, at, bindings.length, call)).join('')
            : '<div class="empty-note">Only the target above. Add another to bind this same call' + Q + 's answer '
                + 'into more controls — a grid, a select, a pie chart and a text area from one response.</div>')
        + '<span class="hint">One call, however many targets: each reads the response on its own terms — '
            + 'payload or metadata, its own transforms, its own path and fields — and one that cannot bind '
            + 'says so on its own control without stopping the rest.</span>';
}

/** One further target: where it reads from, how it reshapes, which control, and what that control needs. */
function bindingCard(b, at, count, call) {
    const targets = page.controls.filter(t => TARGET_TYPES.includes(t.type));
    const target = targets.find(t => t.controlId === b.targetControlId);
    const type = target ? target.type : '';
    const meta = b.source === 'METADATA';
    const isLink = type === 'link';
    const singleValue = type === 'text' || type === 'textarea' || isLink;
    const isGrid = b.targetControlId === NEW_GRID || type === 'grid';
    const set = (name, expr) => call('set', at, name, expr);
    const input = (name, placeholder) => '<input type="text" placeholder="' + AC.attr(placeholder) + '" value="'
        + AC.attr(b[name] || '') + '" oninput="' + set(name, 'this.value') + '">';

    return '<div class="action-card">'
        + '<div class="action-head"><span class="action-num">' + (at + 2) + '</span>'
            + '<span class="sum-title">' + AC.esc(b.targetControlId === NEW_GRID ? 'New grid'
                : target ? controlTitle(target) + ' (' + type + ')' : 'Choose a control') + '</span>'
            + (at > 0 ? '<button class="tool-btn" onclick="' + call('move', at, null, '-1') + '" title="Earlier">↑</button>' : '')
            + (at < count - 1 ? '<button class="tool-btn" onclick="' + call('move', at, null, '1') + '" title="Later">↓</button>' : '')
            + '<button class="icon-btn" onclick="' + call('remove', at) + '" title="Remove this target">×</button>'
        + '</div>'
        + field('Bind From', '<select onchange="' + set('source', 'this.value') + '">'
            + '<option value="PAYLOAD"' + (meta ? '' : ' selected') + '>Response payload</option>'
            + '<option value="METADATA"' + (meta ? ' selected' : '') + '>Call metadata (URL, status, timing)</option>'
            + '</select>')
        + field('Transforms', chainEditor(b, at, { chain: 'bindingChainDraft' }))
        + field('Target', '<select onchange="' + set('targetControlId', 'this.value') + '">'
            + '<option value="">— choose a control —</option>'
            + '<option value="' + NEW_GRID + '"' + (b.targetControlId === NEW_GRID ? ' selected' : '') + '>+ New grid (one per run)</option>'
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === b.targetControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
            + '</select>')
        + (!b.targetControlId ? ''
            : singleValue
            ? field('Value Path', input('valuePath', isLink ? (meta ? 'url' : 'data.report.href') : (meta ? 'statusCode' : 'data.order.status')),
                meta ? 'Which metadata field — blank puts the whole record in as JSON.'
                     : PATH_HINT + ' Blank puts the whole response in.')
            : field('Array Path', input('arrayPath', 'data.items'), meta ? 'Leave blank — the metadata record is what gets bound.' : PATH_HINT))
        + (isGrid
            ? '<label class="inline-check"><input type="checkbox"' + (b.keyValueGrid ? ' checked' : '')
                + ' onchange="' + set('keyValueGrid', 'this.checked') + '"> Show an object result as a key/value grid</label>'
              + scalarsOnlyBox(b, set)
              + appendRowsBox(b, set, type === 'grid')
              + enrichColumnEditor(b.enrichColumns || [], (op, col, name, value) => 'bindingEnrichDraft(' + at
                + ', \'' + op + '\', ' + col + ', ' + (name ? '\'' + name + '\'' : 'null')
                + ', ' + (value === undefined ? 'null' : value) + ')', false)
            : '')
        + (isSelect(type)
            ? '<div class="form-row" style="margin-bottom:0">'
                + field('Key Field', input('keyField', 'id'))
                + field('Label Field', input('labelField', 'name'))
              + '</div>'
            : '')
        + (isGrid || isSelect(type)
            ? bindFilterEditor(b.bindFilters || [],
                (op, i, name, value) => 'bindingFilterDraft(' + at + ', \'' + op + '\', ' + i + ', '
                    + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')',
                isSelect(type) ? 'dropdown' : 'grid')
            : '')
        + (isGrid
            ? pivotEditor(b.pivot, (op, v, name, value) => 'pivotDraft(' + at + ', \'' + op + '\', ' + v + ', '
                + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')')
            : '')
        + (isChart(type) ? chartFieldsEditor(type, b, set) : '')
        + '</div>';
}

/**
 * The narrowing that goes with reading an object as a key/value grid: leave the properties that
 * are themselves objects or arrays out of it altogether.
 *
 * <p>Only offered under a ticked key/value box, because that is the only place it means anything
 * — a response that is already an array of rows has its own columns, and what is complex in one
 * of those rows is a question for the grid's columns rather than for this.
 *
 * <p>Worth having because of what these grids are usually pointed at. A status record, an
 * instance description, a health payload: twenty scalars worth reading, and half a dozen
 * sub-documents nobody opened the grid for. Off, each of those is a cell of JSON text — a line of
 * braces in a column sized for a status, unsortable and unfilterable — and the twenty are lost
 * among them.
 */
function scalarsOnlyBox(a, set) {
    if (!a.keyValueGrid) return '';
    return '<label class="inline-check"><input type="checkbox"' + (a.scalarsOnly ? ' checked' : '')
        + ' onchange="' + set('scalarsOnly', 'this.checked') + '"> Scalar attributes only</label>'
        + '<span class="hint">Leaves out every property whose value is an object or an array, so the grid holds '
        + 'the plain attributes — text, numbers, true/false, empty — and nothing else. Off, a nested value goes '
        + 'into its cell as the JSON text it is.</span>';
}

/**
 * Whether this action adds its rows to the grid or replaces them — the same tick box on an
 * action, on one of its further targets, and on a fan-out collecting its answers into a grid,
 * since all three fill a placed grid the same way.
 *
 * <p>Worth having because of what these grids are routinely used for: the same call made against
 * one environment after another, or one order after another, read as a single table. Replacing
 * was the only thing a grid could do, so the way to compare two runs was to aim them at "new
 * grid" and read two grids side by side — which loses the sort, the filters and the export that
 * are about the set as a whole.
 *
 * @param on whether the target can take it at all; false leaves the box off the card entirely
 */
function appendRowsBox(a, set, on) {
    if (!on) return '';
    return '<label class="inline-check"><input type="checkbox"' + (a.appendRows ? ' checked' : '')
        + ' onchange="' + set('appendRows', 'this.checked') + '"> Add to the rows already in the grid</label>'
        + '<span class="hint">Off, every run replaces what the grid holds. On, the rows join the ones underneath '
        + 'them — so a button run once per environment builds one table of all of them — and the grid keeps its '
        + 'sort, its filters and its cap across the runs. A column this answer carries and the last one did not '
        + 'is added rather than lost. <b>Clear rows</b> in the grid' + Q + 's own toolbar empties it again, and so '
        + 'does <b>Reset</b>.</span>';
}

/**
 * The two fields that turn a row into a chart's marks, named for what they do on that chart: a
 * slice's name and size on a pie, a bar's category and value on a bar chart. The value box takes
 * several columns, comma-separated — a pie each, or a group of bars per category.
 */
function chartFieldsEditor(type, a, set) {
    if (isSeries(type)) return seriesFieldsEditor(type, a, set);
    const bar = type === 'bar';
    const input = (name, placeholder) => '<input type="text" placeholder="' + AC.attr(placeholder) + '" value="'
        + AC.attr(a[name] || '') + '" oninput="' + set(name, 'this.value') + '">';
    return '<div class="form-row" style="margin-bottom:0">'
            + field(bar ? 'Category Column' : 'Slice Name Field', input('keyField', 'status'))
            + field(bar ? 'Value Column(s)' : 'Slice Value Field(s)', input('valueField', bar ? 'count — or amount, fees' : 'count, amount'))
        + '</div>'
        + (bar
            ? '<span class="hint">A bar per distinct value of the category column. Leave the value blank and each bar is '
                + 'how many rows fall in its category; name a column and it is that column added up across them; name '
                + 'several, comma-separated — <code>amount, fees</code> — and each category gets a bar per column, with a '
                + 'legend. Column names match regardless of case. A value that is not a number, or is below zero, is '
                + 'listed beside the chart as uncharted.</span>'
            : '<span class="hint">Which field of each row names the wedge, and which one sizes it. For '
                + '<code>[{"status":"OPEN","count":12}, …]</code> that is <code>status</code> and '
                + '<code>count</code>. Name several value fields, comma-separated — <code>count, amount</code> — and the '
                + 'chart draws a pie per field, side by side. Leave the name blank and each row is charted under its own '
                + 'position; leave the value blank and rows are counted per name (or, for a list of plain numbers, each is '
                + 'the number). Field names match regardless of case. A row whose value is not a number, or is below zero, '
                + 'is listed beside the chart as uncharted rather than dropped in silence.</span>');
}

/** The line and value columns of a series chart, wherever its rows come from. */
function seriesFieldsEditor(type, a, set) {
    const timed = type === 'timeseries';
    const input = (name, placeholder) => '<input type="text" placeholder="' + AC.attr(placeholder) + '" value="'
        + AC.attr(a[name] || '') + '" oninput="' + set(name, 'this.value') + '">';
    return '<div class="form-row" style="margin-bottom:0">'
            + field('Line Column (optional)', input('keyField', 'host'))
            + field('Value Column(s)', input('valueField', timed ? 'blank counts rows — or elapsedMs' : 'elapsedMs'))
        + '</div>'
        + '<span class="hint">A line per distinct value of the line column; blank draws one line. '
        + (timed
            ? 'Leave the value blank and each point is how many rows fall in its time bucket; name a column and its values in a '
                + 'bucket are combined as the chart says (sum, average, min or max); name several, comma-separated, for a line '
                + 'each. The time column and its format are set on the chart itself.'
            : 'Name the column whose numbers are the line — <code>elapsedMs</code>, <code>queueDepth</code> — or several, '
                + 'comma-separated, for a line each. Left blank, a response that is a plain list of numbers charts those '
                + 'numbers, and one that is a list of records has nothing to plot but a count of 1 per row. What x is — the '
                + 'line number, or a column — is set on the chart itself.')
        + '</span>';
}

/**
 * Every edit to the working copy's further targets. Choosing a control or a source redraws, since
 * each decides which fields are asked for; typing into a path does not, or the caret would go.
 */
function bindingDraft(op, at, name, value) {
    if (!editor) return;
    const a = editor.draft;
    const bindings = a.extraBindings = a.extraBindings || [];
    // Tab 0 is the action's own target, so further target `at` is tab at + 1.
    if (op === 'add') {
        bindings.push(blankBinding());
        editor.bindingTab = bindings.length;
    } else if (op === 'clear') {
        bindings.length = 0;
        editor.bindingTab = 0;
    } else if (op === 'remove') {
        bindings.splice(at, 1);
        // The tab that was open closes onto its neighbour; one further along keeps its target open.
        const openTab = editor.bindingTab || 0;
        editor.bindingTab = openTab > at + 1 ? openTab - 1 : Math.min(openTab, bindings.length);
    } else if (op === 'move') {
        const to = at + value;
        if (to < 0 || to >= bindings.length) return;
        [bindings[at], bindings[to]] = [bindings[to], bindings[at]];
        // The target being moved stays the one on screen.
        editor.bindingTab = to + 1;
    } else if (op === 'set' && bindings[at]) {
        bindings[at][name] = value;
        // As on the action itself: a metadata record reads best down the page as key/value.
        if (name === 'source') bindings[at].keyValueGrid = value === 'METADATA';
        if (name === 'targetControlId') {
            dropUnusablePivot(bindings[at], false);
            dropUnusableBindFilters(bindings[at], false);
            dropUnusableAppend(bindings[at], false);
        }
        if (name !== 'source' && name !== 'targetControlId' && name !== 'keyValueGrid') return;
    }
    renderEditor();
}

/** Edits one further target's enriched columns — the same list routine the action's own use. */
function bindingEnrichDraft(at, op, col, name, value) {
    if (!editor || !(editor.draft.extraBindings || [])[at]) return;
    rowListSteps(editor.draft.extraBindings, at, 'enrichColumns', op, col, name, value);
    if (rowListRedraws(op, name)) renderEditor();
}

/** The same, for the filters a further target keeps its rows by. */
function bindingFilterDraft(at, op, i, name, value) {
    if (!editor || !(editor.draft.extraBindings || [])[at]) return;
    rowListSteps(editor.draft.extraBindings, at, 'bindFilters', op, i, name, value);
    if (rowListRedraws(op, name)) renderEditor();
}

// ── Grouping a grid's rows ───────────────────────────────────────────────
// An action filling a grid can group what it bound before the grid sees it: the call's rows are
// collected out of sight, grouped down by some columns and across by others, and the grid is
// filled with the table that makes. The arithmetic is gridpivot.js — the Analyze screen's — and
// Analyze's "Add to page as action" is the usual way one arrives; this is where it is read and
// adjusted afterwards, or written by hand.

const PIVOT_ORDER_LABELS = { key: 'A → Z', valueDesc: 'Largest first', valueAsc: 'Smallest first' };

/**
 * The group-by on an action or on one of its further targets.
 *
 * @param p    the pivot being edited; null or empty for none
 * @param call builds the handler text for (op, at, name, valueExpression)
 */
function pivotEditor(p, call) {
    const on = !!p;
    const head = '<div class="props-title" style="margin-top:8px"><span>Group By</span>'
        + '<span class="props-jump">' + (on
            ? '<button class="tool-btn" onclick="' + call('off', -1) + '">Remove</button>'
            : '<button class="tool-btn" onclick="' + call('on', -1) + '">+ Group rows</button>')
        + '</span></div>';
    if (!on) {
        return head + '<div class="empty-note">None — the grid shows the rows as they were bound. '
            + 'Group them to show a summary instead: a line per value of some columns, a column per value of '
            + 'others, and a count, sum, average, min or max in each cell. <b>Analyze</b> on a running grid builds '
            + 'one by dragging and adds it here.</div>';
    }

    const list = name => '<input type="text" placeholder="' + (name === 'rows' ? 'desk, status' : 'region') + '" value="'
        + AC.attr((p[name] || []).join(', ')) + '" oninput="' + call('set', -1, name, 'this.value') + '">';
    const check = (name, label) => '<label class="inline-check"><input type="checkbox"' + (p[name] !== false ? ' checked' : '')
        + ' onchange="' + call('set', -1, name, 'this.checked') + '"> ' + label + '</label>';
    const order = name => '<select onchange="' + call('set', -1, name, 'this.value') + '">'
        + GridPivot.ORDERS.map(o => '<option value="' + o + '"' + ((p[name] || 'key') === o ? ' selected' : '') + '>'
            + PIVOT_ORDER_LABELS[o] + '</option>').join('') + '</select>';
    const values = p.values || [];

    return head
        + '<div class="form-row" style="margin-bottom:0">'
            + field('Rows', list('rows'))
            + field('Columns', list('cols'))
        + '</div>'
        + '<div class="props-title" style="margin-top:4px"><span>Values</span>'
            + '<span class="props-jump"><button class="tool-btn" onclick="' + call('addValue', -1) + '">+ Add</button></span></div>'
        + (values.length ? values.map((v, at) => {
            const rowCount = v.agg === GridPivot.ROW_COUNT_AGG;
            return '<div class="chain-step">'
                + '<select onchange="' + call('setValue', at, 'agg', 'this.value') + '">'
                    + '<option value="' + GridPivot.ROW_COUNT_AGG + '"' + (rowCount ? ' selected' : '') + '>Row count</option>'
                    + Object.keys(GridPivot.AGGS).map(k => '<option value="' + k + '"' + (v.agg === k ? ' selected' : '') + '>'
                        + GridPivot.AGGS[k].label + ' of</option>').join('')
                + '</select>'
                + (rowCount ? '' : '<input type="text" placeholder="column" value="' + AC.attr(v.field || '')
                    + '" oninput="' + call('setValue', at, 'field', 'this.value') + '">')
                + '<button class="icon-btn" onclick="' + call('removeValue', at) + '" title="Remove">×</button>'
                + '</div>';
        }).join('')
        : '<div class="empty-note">None — each cell counts its rows.</div>')
        + '<div class="form-row" style="margin-bottom:0">'
            + field('Row Order', order('rowOrder'))
            + field('Column Order', order('colOrder'))
        + '</div>'
        + check('grandRow', 'Total row') + check('grandCol', 'Total column') + check('blanks', 'Keep blank values')
        + '<span class="hint">Comma-separated column names, outermost first; they match regardless of case. The grid '
            + 'gets a column per row field, then one per column group per value — <code>EMEA / Q3 · Sum of amount</code> — '
            + 'in place of the columns it was laid out with. Largest / smallest order by the total of the first value. '
            + '<b>Keep blank values</b> off drops rows with an empty group column instead of grouping them under '
            + '<i>(blank)</i>.</span>';
}

/** Every edit to a group-by, against whichever object carries it. */
function pivotSteps(holder, op, at, name, value) {
    if (op === 'on') {
        holder.pivot = GridPivot.toSpec(GridPivot.defaults());
        return true;
    }
    if (op === 'off') { holder.pivot = null; return true; }
    const p = holder.pivot;
    if (!p) return false;
    p.values = p.values || [];
    if (op === 'set') {
        p[name] = name === 'rows' || name === 'cols'
            ? String(value || '').split(',').map(s => s.trim()).filter(Boolean)
            : value;
        return false;
    }
    if (op === 'addValue') { p.values.push({ field: '', agg: 'sum' }); return true; }
    if (op === 'removeValue') { p.values.splice(at, 1); return true; }
    if (op === 'setValue' && p.values[at]) {
        p.values[at][name] = value;
        if (name === 'agg' && value === GridPivot.ROW_COUNT_AGG) p.values[at].field = '';
        // Only choosing between the row count and a column changes what the line asks for.
        return name === 'agg';
    }
    return false;
}

/**
 * Takes a group-by off whatever can no longer show one — a target that is not a grid, or a tab per
 * row — rather than leaving it out of sight on the panel for the save to refuse.
 */
function dropUnusablePivot(holder, tabsPerRow) {
    if (!holder || !holder.pivot) return;
    const id = holder.targetControlId;
    const target = id && id !== NEW_GRID ? findControl(id) : null;
    const grid = id === NEW_GRID || (target && target.type === 'grid');
    if (!grid || tabsPerRow) holder.pivot = null;
}

/**
 * And the filters off whatever no longer takes a list of rows for them to narrow. Same reason as
 * the group-by above: a target changed from a grid to a text box leaves tests nothing would ever
 * make, and it is better to lose them with the target that could use them than to have the save
 * refuse a page over wiring that is no longer on the panel.
 */
function dropUnusableBindFilters(holder, fanOut) {
    if (!holder || !(holder.bindFilters || []).length) return;
    const id = holder.targetControlId;
    if (!id) { holder.bindFilters = []; return; }
    if (id === NEW_GRID || fanOut) return;
    const target = findControl(id);
    if (!target || !(target.type === 'grid' || isSelect(target.type))) holder.bindFilters = [];
}

/**
 * And the append off a target that is no longer a placed grid — a text box, a chart, "new grid",
 * a tab per row. Same reason as the two above: the card stops offering the tick box the moment
 * the target changes, so a setting left ticked underneath it could never be unticked, and at run
 * time it would be quietly ignored. Better to lose it with the target it was about.
 */
function dropUnusableAppend(holder, tabsPerRow) {
    if (!holder || !holder.appendRows) return;
    const target = holder.targetControlId && holder.targetControlId !== NEW_GRID
        ? findControl(holder.targetControlId) : null;
    if (tabsPerRow || !target || target.type !== 'grid') holder.appendRows = false;
}

/** A group-by in the action dialog: on the action itself at -1, or on its further target `bindingAt`. */
function pivotDraft(bindingAt, op, at, name, value) {
    if (!editor) return;
    const holder = bindingAt < 0 ? editor.draft : (editor.draft.extraBindings || [])[bindingAt];
    if (!holder) return;
    if (pivotSteps(holder, op, at, name, value)) renderEditor();
}

function bindingChainDraft(at, op, step, value) {
    if (!editor || !(editor.draft.extraBindings || [])[at]) return;
    chainSteps(editor.draft.extraBindings, at, op, step, value);
    renderEditor();
}

/**
 * Which rows of the source grid this fan-out will actually call for, beyond the ones the operator
 * has already filtered down to on the grid itself.
 *
 * <p>The two narrowings are different things and both are wanted. The grid's own filter row is
 * the operator narrowing this one time; these are the page narrowing every time — "only the
 * failed ones", "only today's" — which is a fact about what the action is for and belongs with
 * it rather than in an instruction to type something into a box before clicking.
 */
function rowFilterEditor(a, i, fns) {
    const source = findControl(a.rowSourceControlId);
    const known = source && isSelect(source.type) ? ['key', 'label'] : (source && source.columns) || [];
    const call = (op, at, name, value) => fns.rows + '(' + i + ', \'rowFilters\', \'' + op + '\', ' + at
        + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')';

    return filterListEditor(a.rowFilters || [], call, 'Only Rows Where',
        'Every row on screen is called for.',
        'Each one has to pass. The cell is compared as the grid shows it, and text '
        + 'tests ignore case, so a filter here narrows the grid the same way the same text typed into its '
        + 'filter row does. A value may be written <code>${field}</code> to test against a control the '
        + 'operator sets; one that comes out empty drops the filter rather than matching nothing, so an '
        + 'untouched dropdown means <i>any</i>.'
        + (known.length ? ' This grid is laid out with <code>' + known.map(AC.esc).join('</code>, <code>')
            + '</code>.' : ' This grid takes its columns from whatever fills it, so the names are whatever '
            + 'that response carries.'));
}

/**
 * Which of the rows it just read actually go into the control — see {@link AppPageAction#bindFilters}.
 *
 * <p>A grid and a dropdown both take a list, and neither always wants all of it. The endpoint that
 * answers with every order is the grid of the open ones; the instance list that answers with every
 * environment is the dropdown of the production ones. The alternatives were a JSONata transform
 * per reading, or binding the lot and leaving the operator to type into the grid's filter row
 * every time — and a dropdown has no filter row to type into at all.
 *
 * <p>Same tests, written the same way, as the filters above: this is the narrowing on the way
 * <em>in</em>, that one the narrowing of what a fan-out calls for.
 *
 * @param what how to describe the control in the note, since a dropdown has no rows to speak of
 */
function bindFilterEditor(filters, call, what) {
    return filterListEditor(filters, call, 'Only Keep Rows Where',
        'Everything that came back goes in.',
        'Each one has to pass, and what does not pass never reaches the ' + what + '. The cell is compared as '
        + 'text and text tests ignore case. A value may be written <code>${field}</code> to test against a '
        + 'control the operator sets — so a dropdown above can narrow what fills the one below — and one that '
        + 'comes out empty drops its filter rather than matching nothing, which makes an untouched control mean '
        + '<i>any</i>. Applied after the path and the enriched columns, so a filter may test a column that came '
        + 'off the call record, and before any group-by, so what is grouped is what passed.');
}

/** One list of row tests in the panel: the rows, and the sentence under them. */
function filterListEditor(filters, call, title, empty, hint) {
    return '<div class="props-title" style="margin-top:8px"><span>' + AC.esc(title) + '</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="' + call('add', -1) + '">+ Add</button></span></div>'
        + (filters.length ? filters.map((f, at) => {
            const operator = (f.operator || 'CONTAINS').toUpperCase();
            const valueless = VALUELESS_OPERATORS.includes(operator);
            return '<div class="chain-step">'
                + '<input type="text" placeholder="column" value="' + AC.attr(f.column || '')
                    + '" oninput="' + call('set', at, 'column', 'this.value') + '">'
                + '<select onchange="' + call('set', at, 'operator', 'this.value') + '">'
                + ROW_FILTER_OPERATORS.map(o => '<option value="' + o.op + '"'
                    + (o.op === operator ? ' selected' : '') + '>' + AC.esc(o.label) + '</option>').join('')
                + '</select>'
                + (valueless ? '' : '<input type="text" placeholder="value or ${field}" value="'
                    + AC.attr(f.value || '') + '" oninput="' + call('set', at, 'value', 'this.value') + '">')
                + '<button class="icon-btn" onclick="' + call('remove', at) + '" title="Remove">×</button>'
                + '</div>';
        }).join('')
        : '<div class="empty-note">' + empty + '</div>')
        + '<span class="hint">' + hint + '</span>';
}

/**
 * Columns added to the grid a collected fan-out fills, beside the ones the answers brought.
 *
 * <p>The grid is whatever came back either way: a source column, then every field of every answer
 * under the endpoint's own names. What these add is what the answer does not carry — the id that
 * was asked about, the status code, the timing, a header — worked out once per call and written
 * onto every row that call produced. Which is also what lets a failed call say why: its metadata
 * and header columns are filled even where its response columns are empty.
 */
function resultColumnEditor(a, i, fns) {
    const columns = a.rowColumns || [];
    const source = findControl(a.rowSourceControlId);
    const call = (op, at, name, value) => fns.rows + '(' + i + ', \'rowColumns\', \'' + op + '\', ' + at
        + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')';

    return '<div class="props-title" style="margin-top:8px"><span>Collected Columns</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="' + call('add', -1) + '">+ Add</button></span></div>'
        + (columns.length ? columns.map((column, at) => {
            const kind = (column.kind || 'PATH').toUpperCase();
            const chosen = RESULT_COLUMN_KINDS.find(k => k.kind === kind) || RESULT_COLUMN_KINDS[1];
            return '<div class="chain-step">'
                + '<span class="chain-num">' + (at + 1) + '</span>'
                + '<input type="text" placeholder="column name" value="' + AC.attr(column.name || '')
                    + '" oninput="' + call('set', at, 'name', 'this.value') + '">'
                + '<select onchange="' + call('set', at, 'kind', 'this.value') + '">'
                + RESULT_COLUMN_KINDS.map(k => '<option value="' + k.kind + '"'
                    + (k.kind === kind ? ' selected' : '') + '>' + AC.esc(k.label) + '</option>').join('')
                + '</select>'
                + (kind === LABEL_COLUMN ? ''
                    : kind === 'META' ? metaFieldSelect(column.expression, call('set', at, 'expression', 'this.value'))
                    : '<input type="text" placeholder="' + AC.attr(chosen.placeholder)
                    + '" value="' + AC.attr(column.expression || '') + '" oninput="'
                    + call('set', at, 'expression', 'this.value') + '">')
                + (at > 0 ? '<button class="tool-btn" onclick="' + call('move', at, null, '-1') + '" title="Earlier">↑</button>' : '')
                + (at < columns.length - 1 ? '<button class="tool-btn" onclick="' + call('move', at, null, '1') + '" title="Later">↓</button>' : '')
                + '<button class="icon-btn" onclick="' + call('remove', at) + '" title="Remove">×</button>'
                + '</div>';
        }).join('')
        : '<div class="empty-note">None — the grid gets a leading <code>' + FAN_SOURCE_COLUMN + '</code> '
            + 'column and then whatever fields each answer carries, and a call that failed contributes a row '
            + 'saying so and nothing else.</div>')
        + '<span class="hint">Added beside the columns the answers brought, never instead of them: the '
        + '<code>' + FAN_SOURCE_COLUMN + '</code> column, the array path above and every field each answer '
        + 'carries are all still there. A cell can come from the row the call was made for'
        + (source ? ' (a column of <b>' + AC.esc(controlTitle(source)) + '</b>, or <code>ROWNUM</code>)' : '')
        + ', from a path into the response, from the call' + Q + 's own record — <code>'
        + META_FIELDS.slice(0, 5).join('</code>, <code>') + '</code> and the rest — or from one response '
        + 'header by name. Each is worked out once per call and written onto every row that call produced, '
        + 'so a call whose path found eight rows gets eight rows carrying the same status code. A column of '
        + 'the same name as one the answer brought overwrites it, and a grid with its own column list gets '
        + 'these appended to it.</span>';
}

/**
 * Columns added to every row of a grid as it is populated: a field of the call record, a response
 * header, or a VLOOKUP — this row's value in one column matched against a static dataset's row
 * key, bringing back another of that dataset's columns.
 *
 * @param columns the list being edited
 * @param call    builds the handler text for (op, at, name, valueExpression)
 * @param fanOut  whether the grid is filled once per row, which changes whose record a row reads
 */
function enrichColumnEditor(columns, call, fanOut) {
    return '<div class="props-title" style="margin-top:8px"><span>Enriched Columns</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="' + call('add', -1) + '">+ Add</button></span></div>'
        + (columns.length ? columns.map((column, at) => {
            const kind = (column.kind || 'META').toUpperCase();
            const chosen = ENRICH_COLUMN_KINDS.find(k => k.kind === kind) || ENRICH_COLUMN_KINDS[0];
            const wholeRow = kind === WHOLE_ROW_LOOKUP;
            const text = (name, placeholder) => '<input type="text" placeholder="' + AC.attr(placeholder)
                + '" value="' + AC.attr(column[name] || '') + '" oninput="' + call('set', at, name, 'this.value') + '">';
            // The grid picker, shared by the two kinds that look into a grid rather than a dataset.
            const gridPick = '<select onchange="' + call('set', at, 'gridControlId', 'this.value') + '">'
                + '<option value="">— pick a grid —</option>'
                + page.controls.filter(t => t.type === 'grid').map(t => '<option value="' + AC.attr(t.controlId) + '"'
                    + (t.controlId === column.gridControlId ? ' selected' : '') + '>' + AC.esc(controlTitle(t)) + '</option>').join('')
                + '</select>';
            return '<div class="chain-step">'
                + '<span class="chain-num">' + (at + 1) + '</span>'
                // A whole-row lookup is named after the row it finds, so what it asks for here is
                // the prefix those names get — and asks for it in the same place, because it is the
                // same question: what the columns it adds are going to be called.
                + (wholeRow ? text('prefix', 'column prefix (optional)')
                    : '<input type="text" placeholder="column name" value="' + AC.attr(column.name || '')
                        + '" oninput="' + call('set', at, 'name', 'this.value') + '">')
                + '<select onchange="' + call('set', at, 'kind', 'this.value') + '">'
                + ENRICH_COLUMN_KINDS.map(k => '<option value="' + k.kind + '"'
                    + (k.kind === kind ? ' selected' : '') + '>' + AC.esc(k.label) + '</option>').join('')
                + '</select>'
                + (kind === 'META' ? metaFieldSelect(column.expression, call('set', at, 'expression', 'this.value'))
                    : kind === 'HEADER' || kind === 'REGEX' ? text('expression', chosen.placeholder) : '')
                + (at > 0 ? '<button class="tool-btn" onclick="' + call('move', at, null, '-1') + '" title="Earlier">↑</button>' : '')
                + (at < columns.length - 1 ? '<button class="tool-btn" onclick="' + call('move', at, null, '1') + '" title="Later">↓</button>' : '')
                + '<button class="icon-btn" onclick="' + call('remove', at) + '" title="Remove">×</button>'
                + '</div>'
                + (kind !== 'VLOOKUP' ? ''
                    : '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">look up</span>' + text('lookupColumn', 'grid column')
                        + '<span class="sub-word">in</span>'
                        + '<select onchange="' + call('set', at, 'datasetName', 'this.value') + '">'
                            + datasetOptions(column.datasetName) + '</select>'
                      + '</div>'
                      + '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">where</span>'
                        + datasetColumnSelect(column.datasetName, column.keyColumn,
                            call('set', at, 'keyColumn', 'this.value'), '— row key column —')
                        + '<span class="sub-word">matches, return</span>'
                        + datasetColumnSelect(column.datasetName, column.returnColumn,
                            call('set', at, 'returnColumn', 'this.value'), '— column to return —')
                      + '</div>')
                + (kind !== 'GRID_VLOOKUP' ? ''
                    : '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">look up</span>' + text('lookupColumn', 'this grid' + Q + 's column')
                        + '<span class="sub-word">in</span>' + gridPick
                      + '</div>'
                      + '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">where</span>'
                        + gridColumnInput(column.gridControlId, column.keyColumn, call('set', at, 'keyColumn', 'this.value'), 'row key column')
                        + '<span class="sub-word">matches, return</span>'
                        + gridColumnInput(column.gridControlId, column.returnColumn, call('set', at, 'returnColumn', 'this.value'), 'column to return')
                      + '</div>')
                + (!wholeRow ? ''
                    : '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">look up</span>' + text('lookupColumn', 'this grid' + Q + 's column')
                        + '<span class="sub-word">in</span>' + gridPick
                      + '</div>'
                      + '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">where</span>'
                        + gridColumnInput(column.gridControlId, column.keyColumn, call('set', at, 'keyColumn', 'this.value'), 'row key column')
                        + '<span class="sub-word">matches, bring back every other column</span>'
                      + '</div>')
                + (kind !== 'REGEX' ? ''
                    : '<div class="chain-step chain-sub">'
                        + '<span class="sub-word">over</span>' + text('lookupColumn', 'this grid' + Q + 's column')
                        + '<span class="sub-word">, the cell gets</span>'
                        + text('replacement', '$1 — blank for the first group')
                      + '</div>');
        }).join('')
        : '<div class="empty-note">None — the grid shows the rows as they were bound.</div>')
        + '<span class="hint">Worked out for every row as the grid fills, and added beside the columns the '
        + 'response brought — a column of the same name is overwritten. A <b>call record</b> field or a '
        + '<b>response header</b> is the same on every row '
        + (fanOut ? 'that one call produced, so a collected grid shows each call' + Q + 's own. '
                  : 'of the grid, since one call filled it. ')
        + 'A <b>VLOOKUP</b> takes this row' + Q + 's value in the grid column, finds the first dataset row whose '
        + 'key column holds it — ignoring case and surrounding spaces — and brings back the chosen column; '
        + 'no match leaves the cell empty. A <b>VLOOKUP into a grid</b> does the same against the rows another grid on '
        + 'this page holds when this one fills — so that grid has to be filled first: have this action <i>Run After</i> '
        + 'the one that fills it. A <b>whole row</b> lookup matches the same way but names no column to bring back: '
        + 'every column the matched row has comes across at once, under its own name behind the prefix — leave the '
        + 'prefix blank and a name this grid already uses is overwritten. The key column itself is not brought back; '
        + 'this row already has that value in the column that was looked up. A <b>regex</b> runs its pattern over one '
        + 'of this grid' + Q + 's columns and fills the new one with what comes out: <code>$1</code>, <code>$2</code> '
        + 'for the capturing groups, <code>$&amp;</code> for the whole match, and blank for the first group. Write the '
        + 'pattern <code>/like this/i</code> to ignore case, <code>/…/s</code> for a dot that crosses lines, or '
        + '<code>/…/g</code> to collect every match into the cell. Columns are worked out in order, so a lookup or a '
        + 'pattern can read a column an earlier one added. A grid with its own column list gets these appended to it.</span>';
}

/**
 * One of a grid's columns, for a lookup into that grid: picked from the columns the grid was laid
 * out with when it has a list, and typed otherwise — a grid whose columns follow its data has no
 * columns to offer until the page runs. A saved value outside the list is kept as an option.
 */
function gridColumnInput(gridId, current, onchange, placeholder) {
    const grid = findControl(gridId);
    const columns = (grid && grid.columns) || [];
    if (!columns.length) {
        return '<input type="text" placeholder="' + AC.attr(placeholder) + '" value="' + AC.attr(current || '')
            + '" oninput="' + onchange + '">';
    }
    const options = current && !columns.includes(current) ? [current, ...columns] : columns;
    return '<select onchange="' + onchange + '"><option value="">— ' + AC.esc(placeholder) + ' —</option>'
        + options.map(col => '<option value="' + AC.attr(col) + '"' + (col === current ? ' selected' : '') + '>'
            + AC.esc(col) + '</option>').join('')
        + '</select>';
}

/**
 * The call-record field a META column reads, picked rather than typed: the fields are a fixed
 * set, and a misspelt one fills its column with nothing. A saved value outside the set is kept
 * as an option so opening the page does not quietly change what it reads.
 */
function metaFieldSelect(current, onchange) {
    const fields = current && !META_FIELDS.includes(current) ? [current, ...META_FIELDS] : META_FIELDS;
    return '<select onchange="' + onchange + '">'
        + fields.map(f => '<option value="' + AC.attr(f) + '"' + (f === current ? ' selected' : '') + '>'
            + AC.esc(f) + '</option>').join('')
        + '</select>';
}

// ── Editing a fan-out's filters and columns ──────────────────────────────────
// Both are lists hanging off one action, edited the same four ways, and an action is edited in
// three places — on a control, in the page's library, in the dialog over the page. One mutator
// per place, all three over one routine, exactly as the transform chain beside them is.

function rowListSteps(actions, index, list, op, at, name, value) {
    const a = actions[index];
    const items = a[list] = a[list] || [];
    if (op === 'add') {
        items.push(list === 'datasetFilters'
            ? { attribute: '', op: DATASET_DEFAULT_OPERATOR, value: '' }
            : list === 'rowFilters' || list === 'bindFilters'
            ? { column: '', operator: 'CONTAINS', value: '' }
            : list === 'enrichColumns'
            ? { name: 'enriched' + (items.length + 1), kind: 'META', expression: META_FIELDS[0],
                datasetName: '', lookupColumn: '', keyColumn: '', returnColumn: '', gridControlId: '',
                prefix: '', replacement: '' }
            : { name: 'column' + (items.length + 1), kind: 'PATH', expression: '' });
    } else if (op === 'remove') {
        items.splice(at, 1);
    } else if (op === 'move') {
        const target = at + value;
        if (target < 0 || target >= items.length) return;
        [items[at], items[target]] = [items[target], items[at]];
    } else if (op === 'set' && items[at]) {
        const was = name === 'kind' ? (items[at].kind || 'META').toUpperCase() : null;
        items[at][name] = value;
        // What the expression box holds is a different thing for each kind — a call-record field, a
        // header name, a regex — so one kind's is not carried into the next, where a header name
        // would sit there reading as a perfectly valid pattern that matches nothing anybody wanted.
        if (list === 'enrichColumns' && was !== null && was !== String(value || '').toUpperCase()) {
            items[at].expression = '';
            // Every kind but the whole-row lookup is a column with a name, and the whole-row lookup
            // is the one that never asked for one — so a column switched away from it would be a
            // column with no name, which the catalog refuses at the save. Named here instead, where
            // there is still a box on the screen to change it in.
            if (!items[at].name && String(value || '').toUpperCase() !== WHOLE_ROW_LOOKUP) {
                items[at].name = 'enriched' + (at + 1);
            }
        }
        // The field dropdown shows its first option selected; make the column read what it shows.
        if ((list === 'rowColumns' || list === 'enrichColumns') && name === 'kind' && value === 'META'
                && !META_FIELDS.includes(items[at].expression)) {
            items[at].expression = META_FIELDS[0];
        }
        // A different dataset has different columns, so the ones picked from the last are dropped.
        if (list === 'enrichColumns' && (name === 'datasetName' || name === 'gridControlId')) {
            items[at].keyColumn = '';
            items[at].returnColumn = '';
        }
    }
}

/**
 * Whether the panel has to be drawn again. Adding, removing and reordering change what is on it;
 * so does picking a test or a kind, since each decides whether the box beside it is asked for at
 * all. Typing into one of those boxes changes nothing but the value, and redrawing would take the
 * caret with it.
 */
function rowListRedraws(op, name) {
    return op !== 'set' || name === 'operator' || name === 'kind' || name === 'datasetName' || name === 'gridControlId';
}

function rowListAction(index, list, op, at, name, value) {
    rowListSteps(findControl(selectedId).actions, index, list, op, at, name, value);
    if (rowListRedraws(op, name)) renderProps();
}

function rowListPageAction(index, list, op, at, name, value) {
    rowListSteps(page.actions, index, list, op, at, name, value);
    if (rowListRedraws(op, name)) renderProps();
}

function rowListDraft(index, list, op, at, name, value) {
    if (!editor) return;
    rowListSteps([editor.draft], 0, list, op, at, name, value);
    if (rowListRedraws(op, name)) renderEditor();
}

/**
 * A performance action's form, which is short because the action is: it reads the run history
 * this server already holds, so there is no endpoint to name, no environment to send it to and
 * no response for a path to be read out of. What is left is the grid the table lands in and, if
 * the page wants one, a filter narrowing which endpoints are in it.
 */
function performanceFields(a, i, targets, target, fns, set) {
    const filters = a.inputs && Object.keys(a.inputs).length ? a.inputs : null;
    const unknown = filters ? Object.keys(filters).filter(k => !PERFORMANCE_FILTERS.includes(k)) : [];
    return field('Target', '<select onchange="' + set('targetControlId', 'this.value') + '">'
            + '<option value="">— no target —</option>'
            + '<option value="' + NEW_GRID + '"' + (a.targetControlId === NEW_GRID ? ' selected' : '') + '>+ New grid (one per run)</option>'
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (grid)</option>').join('')
            + '</select>',
            targets.length || a.targetControlId === NEW_GRID
                ? 'The summary is a table — <code>' + PERFORMANCE_COLUMNS.join('</code>, <code>') + '</code>, a row '
                    + 'per app, environment and use case, busiest first — so it goes in a grid and nowhere else.'
                : 'Nowhere to put it yet — drag a <b>Grid</b> onto the layout and aim this at it, or let each run '
                    + 'stack a new grid of its own.')
        + field('Filters', '<textarea spellcheck="false" placeholder=\'{"appName": "${appPick}"}\' oninput="' + fns.inputs + '(' + i + ', this.value)">'
            + AC.esc(filters ? JSON.stringify(filters, null, 2) : '') + '</textarea>',
            (unknown.length
                ? '<b>' + AC.esc(unknown.join(', ')) + '</b> ' + (unknown.length > 1 ? 'are not filters' : 'is not a filter')
                    + ' this understands and will be ignored. '
                : '')
            + 'Narrows which endpoints are summarised: <code>' + PERFORMANCE_FILTERS.join('</code>, <code>')
            + '</code>. <code>${fieldName}</code> picks up a control, so a grid under an app dropdown narrows as '
            + 'the operator chooses. Leave it empty to summarise every app.')
        + '<span class="hint">Summarised over the runs this server still remembers — the recent window the '
            + 'Global Runs page lists, not all time — and counting failed calls with the successful ones, since '
            + 'a call that took nine seconds to fail is the one you came here to find. It makes no call of its '
            + 'own, so it costs nothing to put on a page and nothing to run.</span>';
}

/**
 * A dataset action's form, which is short for the reason a performance summary's is: it calls
 * nothing, so there is no instance to name, no environment to send it to and no response for a
 * path to be read out of. What is left is which dataset, which of its rows, and where they go.
 *
 * <p>The columns are dropdowns rather than boxes wherever the library knows what they are — the
 * dataset's own attributes are exactly what a filter tests and what a dropdown's key and label are
 * read off, so there is no reason to make anyone remember how they were spelled.
 */
function datasetFields(a, i, targets, target, fns, set) {
    const name = a.datasetName || '';
    const known = datasets.find(d => d.name === name);
    const favorites = (known && known.favorites) || [];
    const columns = datasetColumns(name);
    const listTarget = !!target && isSelect(target.type);
    const chartTarget = !!target && isChart(target.type);

    let html = field('Dataset', '<select onchange="' + set('datasetName', 'this.value') + '">'
            + datasetOptions(name) + '</select>',
            name
                ? (columns.length
                    ? 'Columns it carries: <code>' + columns.map(AC.esc).join('</code>, <code>') + '</code>.'
                    : 'Its columns are not known here — it may have failed to load, or have been added since this '
                        + 'tab was opened. The boxes below take a column name typed by hand.')
                : 'The list this action binds, out of the Static Datasets library. It is read where it already '
                    + 'is, so the action makes no call of its own and costs nothing to run.');

    html += field('Saved Filter', '<select onchange="' + set('datasetFavorite', 'this.value') + '">'
            + '<option value="">— the whole dataset —</option>'
            + favorites.map(f => '<option value="' + AC.attr(f.name) + '"'
                + (f.name === a.datasetFavorite ? ' selected' : '') + '>' + AC.esc(f.name) + '</option>').join('')
            // A favourite that has since been deleted, or one on a dataset the library could not be
            // asked about, is still what this action says it applies — dropping it silently would
            // rewire the action by redrawing it.
            + (a.datasetFavorite && !favorites.some(f => f.name === a.datasetFavorite)
                ? '<option value="' + AC.attr(a.datasetFavorite) + '" selected>' + AC.esc(a.datasetFavorite)
                    + ' (not saved on this dataset)</option>' : '')
            + '</select>',
            favorites.length
                ? 'One of the filters saved on this dataset, applied before the rows come back. A question the '
                    + 'library has already been taught is asked by name here rather than copied into the rows below.'
                : 'None saved on this dataset yet. Save one on the <b>Static Datasets</b> page and every page '
                    + 'reading it can ask for it by name.');

    html += datasetFilterEditor(a, i, fns);

    html += field('Target', '<select onchange="' + set('targetControlId', 'this.value') + '">'
            + '<option value="">— no target —</option>'
            + '<option value="' + NEW_GRID + '"' + (a.targetControlId === NEW_GRID ? ' selected' : '') + '>+ New grid (one per run)</option>'
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
            + '</select>',
            targets.length || a.targetControlId === NEW_GRID
                ? 'Rows, so they go in a grid, a dropdown or a chart. A text box and a link each hold one value '
                    + 'read out of a response by path, and there is no response here to read one out of.'
                : 'Nowhere to put them yet — drag a <b>Grid</b>, a <b>Select</b> or a chart onto the layout and '
                    + 'aim this at it, or let each run stack a new grid of its own.');

    if (listTarget) {
        html += '<div class="form-row" style="margin-bottom:0">'
            + field('Key Column', datasetColumnSelect(name, a.keyField,
                set('keyField', 'this.value'), '— the first column —'))
            + field('Label Column', datasetColumnSelect(name, a.labelField,
                set('labelField', 'this.value'), '— same as the key —'))
            + '</div>'
            + '<span class="hint">Which column of each row becomes the option' + Q + 's value, and which one the '
            + 'text the operator reads. The filter above narrows the rows; these two decide what is left of each.</span>';
    } else if (chartTarget) {
        html += chartFieldsEditor(target.type, a, set);
    }

    return html + '<span class="hint">Read straight out of the dataset library, which does the filtering — a page '
        + 'pulling a dozen rows out of fifty thousand is handed a dozen. It makes no call of its own, so there is '
        + 'no environment, no transform chain and no path: its answer is already rows.</span>';
}

/**
 * The conditions a dataset action writes for itself, on top of whatever saved filter it names.
 * Each is a column, a test and a value — and the value is the point of writing one here rather
 * than saving it on the dataset: it may be a <code>${field}</code> template, so the list reloads
 * to whatever the operator has just picked.
 */
function datasetFilterEditor(a, i, fns) {
    const filters = a.datasetFilters || [];
    const call = (op, at, name, value) => fns.rows + '(' + i + ', \'datasetFilters\', \'' + op + '\', ' + at
        + ', ' + (name ? '\'' + name + '\'' : 'null') + ', ' + (value === undefined ? 'null' : value) + ')';

    return '<div class="props-title" style="margin-top:8px"><span>Only Rows Where</span>'
        + '<span class="props-jump"><button class="tool-btn" onclick="' + call('add', -1) + '">+ Add</button></span></div>'
        + (filters.length ? filters.map((f, at) => {
            const op = f.op || DATASET_DEFAULT_OPERATOR;
            return '<div class="chain-step">'
                + datasetColumnSelect(a.datasetName, f.attribute, call('set', at, 'attribute', 'this.value'), '— column —')
                + '<select onchange="' + call('set', at, 'op', 'this.value') + '">'
                + DATASET_OPERATORS.map(o => '<option value="' + o.op + '"'
                    + (o.op === op ? ' selected' : '') + '>' + AC.esc(o.label) + '</option>').join('')
                + '</select>'
                + '<input type="text" placeholder="value or ${field}" value="' + AC.attr(f.value || '')
                    + '" oninput="' + call('set', at, 'value', 'this.value') + '">'
                + '<button class="icon-btn" onclick="' + call('remove', at) + '" title="Remove">×</button>'
                + '</div>';
        }).join('')
        : '<div class="empty-note">Every row the saved filter left.</div>')
        + '<span class="hint">Each one has to pass, and so does the saved filter above. Written '
        + '<code>${field}</code>, a value is the page' + Q + 's own control — so a grid under a region dropdown '
        + 'reloads to that region — and one that comes out empty drops its condition rather than looking for the '
        + 'rows whose column is blank, which makes an untouched control mean <i>any</i>. Matched in the dataset '
        + 'library, so the rows that fail never reach this page.</span>';
}

/**
 * A compare action's form. It names one instance and two environments rather than one, and then
 * says what part of each answer is held against the other and how closely: a path into the
 * response, whether the response is JSON or XML, the chain that reshapes each side first, and
 * the threshold under which two numbers count as the same.
 *
 * <p>What it does not ask for is everything an ordinary action asks about reading a response into
 * a control — an array path, a key field, a chart's value field. The answer here is a fixed table
 * of differences, so there is nothing about its shape left to configure.
 */
function compareFields(a, i, targets, fns, set) {
    const xml = a.compareType === COMPARE_XML;
    const tolerance = a.compareTolerancePercent === undefined || a.compareTolerancePercent === null
        ? 0 : a.compareTolerancePercent;
    const report = a.compareReport || REPORT_DIFFERENCES;
    return field('Instance', '<select onchange="' + set('appUseCaseInstanceId', 'this.value') + '">'
            + instanceOptions(a.appUseCaseInstanceId) + '</select>',
            'Run twice — once against each environment below — with the same inputs both times. The '
            + 'instance' + Q + 's own environment is not used by either run.')
        + '<div class="form-row" style="margin-bottom:0">'
            + field('Baseline', '<input type="text" value="' + AC.attr(a.compareEnvironmentA || '')
                + '" placeholder="${envA}" oninput="' + set('compareEnvironmentA', 'this.value') + '">')
            + field('Candidate', '<input type="text" value="' + AC.attr(a.compareEnvironmentB || '')
                + '" placeholder="${envB}" oninput="' + set('compareEnvironmentB', 'this.value') + '">')
          + '</div>'
        + '<span class="hint">The two environments held against each other. <code>${fieldName}</code> picks up a '
            + 'control — usually two selects sourced from App environments — so the operator chooses the pair. The '
            + 'baseline is the side a difference is reported as being <b>from</b>: what it holds and the candidate '
            + 'does not reads <b>' + COMPARE_STATUS.onlyA + '</b>.</span>'
        + inputsEditor(a, i, fns, 'Sent identically to both environments — the whole point is that the only thing '
            + 'differing between the two calls is where they went.')
        + field('Read As', '<select onchange="' + set('compareType', 'this.value') + '">'
            + '<option value="' + COMPARE_JSON + '"' + (xml ? '' : ' selected') + '>JSON</option>'
            + '<option value="' + COMPARE_XML + '"' + (xml ? ' selected' : '') + '>XML</option>'
            + '</select>',
            xml
                ? 'Each response is parsed as an XML document and compared as the tree it describes — elements as '
                    + 'keys, a repeated tag as a list, attributes under <code>@attributes</code>. Attribute order '
                    + 'and the whitespace between elements are not part of that tree, so neither can show up as a '
                    + 'difference.'
                : 'Each response is compared as the JSON it arrived as.')
        + field('Transforms', chainEditor(a, i, fns),
            'Optional, and run over <b>each side separately</b> before anything is compared — so two environments '
            + 'that answer with the same facts in different wrappers can still be held against each other. Same '
            + 'steps the rest of the page uses.')
        + field('Compare', '<input type="text" value="' + AC.attr(a.comparePath || '')
            + '" placeholder="$" oninput="' + set('comparePath', 'this.value') + '">',
            'What inside each answer is compared. Blank or <code>$</code> compares the whole response; '
            + '<code>data.order.lines</code> compares just that. Same path grammar as everywhere else — '
            + '<code>items[0]</code> indexes, <code>data[id="${orderId}"]</code> filters, and '
            + '<code>${fieldName}</code> picks up a control. Read out of whatever the transforms above produced.')
        + '<div class="form-row" style="margin-bottom:0">'
            + field('Threshold %', '<input type="number" min="0" step="0.01" value="' + AC.attr(tolerance)
                + '" oninput="' + set('compareTolerancePercent', '+this.value') + '">')
            + field('Report', '<select onchange="' + set('compareReport', 'this.value') + '">'
                + '<option value="' + REPORT_DIFFERENCES + '"' + (report === REPORT_DIFFERENCES ? ' selected' : '') + '>Only what differs</option>'
                + '<option value="' + REPORT_TOLERATED + '"' + (report === REPORT_TOLERATED ? ' selected' : '') + '>What differs, tolerated ones marked</option>'
                + '<option value="' + REPORT_EVERYTHING + '"' + (report === REPORT_EVERYTHING ? ' selected' : '') + '>Everything compared</option>'
                + '</select>')
          + '</div>'
        + '<span class="hint">How far two <b>numbers</b> may differ before it counts, as a percentage of the '
            + 'larger of them — <code>0.1</code> accepts a tenth of a percent, <code>0</code> accepts nothing. It '
            + 'applies to numbers only: a text value is the same or it is not, whatever the threshold says.</span>'
        + field('Target', '<select onchange="' + set('targetControlId', 'this.value') + '">'
            + '<option value="">— no target —</option>'
            + '<option value="' + NEW_GRID + '"' + (a.targetControlId === NEW_GRID ? ' selected' : '') + '>+ New grid (one per run)</option>'
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (grid)</option>').join('')
            + '</select>',
            targets.length || a.targetControlId === NEW_GRID
                ? 'The report is a table — <code>' + COMPARE_COLUMNS.join('</code>, <code>') + '</code>, a row per '
                    + 'difference — so it goes in a grid and nowhere else. A run that found nothing fills it with '
                    + 'no rows, which is the answer you were hoping for.'
                : 'Nowhere to put it yet — drag a <b>Grid</b> onto the layout and aim this at it, or let each run '
                    + 'stack a new grid of its own.')
        + '<span class="hint">The order elements come back in is never a difference: two lists holding the same '
            + 'things in a different sequence compare equal, and elements are paired up by what they hold rather '
            + 'than by where they sit. Past ' + COMPARE_PAIRING_LIMIT + ' elements that do not match outright, a '
            + 'list is reported as <b>' + COMPARE_STATUS.unpaired + '</b> rather than lined up, so narrow '
            + '<b>Compare</b> to the part that matters on responses that big. Both calls go out at once, and '
            + 'neither is shared with the rest of the trigger' + Q + 's calls.</span>';
}

/**
 * One action's chain of transforms: the steps it runs, in order, and a way to add another. Shown
 * as a numbered list rather than one select because the order is not incidental — an
 * xml&#8594;json step has to come before the JSONata that reads what it produced, and a chain
 * that is drawn out of order is a chain nobody can see is out of order.
 */
function chainEditor(a, i, fns) {
    const chain = a.transformNames || [];
    const call = (op, at, value) => fns.chain + '(' + i + ', \'' + op + '\', ' + at + ', ' + value + ')';
    let html = chain.map((name, s) =>
        '<div class="chain-step"><span class="chain-num">' + (s + 1) + '</span>'
        + '<select onchange="' + call('set', s, 'this.value') + '">'
        + transformOptions(name, '— remove this step —') + '</select>'
        + (s > 0 ? '<button class="tool-btn" onclick="' + call('move', s, '-1') + '" title="Earlier">↑</button>' : '')
        + (s < chain.length - 1 ? '<button class="tool-btn" onclick="' + call('move', s, '1') + '" title="Later">↓</button>' : '')
        + '<button class="icon-btn" onclick="' + call('remove', s, 'null') + '" title="Remove">×</button>'
        + '</div>').join('');
    return html + '<select onchange="' + call('add', -1, 'this.value') + '">'
        + transformOptions('', chain.length ? '+ add another step' : '+ add a transform') + '</select>';
}

/**
 * The page's transform library as options, headed by whatever the blank one means where it is
 * used — "add a step" on the chain's last select, "remove this step" on a step's own. The type
 * rides along in the label so a chain reads as what it does rather than as names alone.
 *
 * <p>Plain escaping, not attr(): a name is a key matched against an action's chain and it comes
 * back out through <code>this.value</code>, so it has to survive the round trip. attr() escapes
 * for a JS string as well, which would put a backslash in front of an apostrophe and stop the
 * name matching itself — the same reason a grid's column headers escape plainly.
 */
function transformOptions(selected, blankLabel) {
    return '<option value="">' + AC.esc(blankLabel || '— none —') + '</option>'
        + (page.transforms || []).filter(t => t.name).map(t =>
            '<option value="' + AC.esc(t.name) + '"' + (t.name === selected ? ' selected' : '') + '>'
            + AC.esc(t.name) + ' (' + transformTypeLabel(t) + ')</option>').join('');
}

/** How a step's kind is written wherever one is named. */
function transformTypeLabel(t) {
    return t && t.type === 'XML2JSON' ? 'xml→json' : t && t.jsonataRef ? 'shared' : 'jsonata';
}

// ── The shared JSONata library ───────────────────────────────────────────
// A step either carries its expression or names one kept centrally. Naming one is what makes the
// same reshaping, wanted on four pages, one expression rather than four copies that drift — so
// everything below reads the expression through #transformExpression rather than off the step.

async function reloadJsonataLibrary() {
    try {
        jsonataLibrary = await AC.api('GET', '/jsonata');
    } catch (e) {
        jsonataLibrary = [];
    }
}

/** One shared expression by name, or nothing when the library has not got it (or is not loaded). */
function sharedJsonata(name) {
    return jsonataLibrary.find(j => j.name === name) || null;
}

/**
 * The JSONata a step actually runs: the library's, when it names one, and its own otherwise.
 * A name the library no longer holds resolves to nothing rather than to the step's own leftover
 * expression — an expression left behind by a step that was converted to a reference is what it
 * used to say, and running it now would be running a version somebody deliberately replaced.
 */
function transformExpression(t) {
    if (!t) return '';
    if (t.jsonataRef) {
        const shared = sharedJsonata(t.jsonataRef);
        return shared ? (shared.expression || '') : '';
    }
    return t.expression || '';
}

/** The library as options for the picker a step uses to name one. */
function sharedJsonataOptions(selected) {
    const known = jsonataLibrary.some(j => j.name === selected);
    return '<option value="">— pick a shared expression —</option>'
        + jsonataLibrary.map(j => '<option value="' + AC.attr(j.name) + '"'
            + (j.name === selected ? ' selected' : '') + '>' + AC.esc(j.name)
            + (j.description ? ' — ' + AC.esc(j.description) : '') + '</option>').join('')
        // A name the library has not got is still what this step says it runs. Dropping it
        // silently would rewire the page by redrawing it, and the step would then quietly run
        // whatever the first entry happened to be.
        + (selected && !known
            ? '<option value="' + AC.attr(selected) + '" selected>' + AC.esc(selected) + ' (not in the library)</option>'
            : '');
}

const CONTROL_FNS = { set: 'setAction', move: 'moveAction', remove: 'removeAction',
                      inputs: 'setActionInputs', inputVar: 'setActionInputVar',
                      redraw: 'renderProps',
                      source: 'setActionSource', chain: 'chainAction',
                      kind: 'setActionKind',
                      open: 'openControlActionEditor', copy: 'copyControlAction',
                      clone: 'cloneControlAction', toPage: 'copyControlActionToPage',
                      rows: 'rowListAction' };
const PAGE_FNS    = { set: 'setPageAction', move: 'movePageAction', remove: 'removePageAction',
                      inputs: 'setPageActionInputs', inputVar: 'setPageActionInputVar',
                      redraw: 'renderProps',
                      source: 'setPageActionSource', chain: 'chainPageAction',
                      kind: 'setPageActionKind',
                      open: 'openPageActionEditor', clone: 'clonePageAction',
                      toPage: 'copyPageActionToPage', rows: 'rowListPageAction' };

/**
 * One action as a card: what it runs, what it reshapes on the way, and where it puts the answer.
 * Enough to pick the action you meant out of six without reading six forms — the form itself
 * opens over the page when the card is clicked. See {@link #openActionEditor}.
 */
function actionSummary(a, i, count, fns) {
    const performance = isPerformanceAction(a);
    const compare = isCompareAction(a);
    const dataset = isDatasetAction(a);
    const instance = instances.find(x => x.appUseCaseInstanceId === a.appUseCaseInstanceId);
    // A performance action names no instance and never will, so the line that would say which
    // one says what the action does instead — and is not greyed out for the instance it is not
    // missing. A comparison does name one, and says which two environments it runs it against,
    // since that pair is the whole of what the action is for.
    const runs = performance ? 'performance summary — no call made'
               // A dataset action names no instance either, and what it does name is the one thing
               // worth reading off the card: which list it is about to put on the page.
               : dataset ? (a.datasetName
                    ? 'static dataset "' + a.datasetName + '"'
                        + (a.datasetFavorite ? ', filtered by "' + a.datasetFavorite + '"' : '') + ' — no call made'
                    : 'no dataset chosen yet')
               : instance ? (instance.instanceLabel || (instance.appUseCaseName + ' @ ' + instance.appEnvironment))
                    + (compare ? ' — ' + (a.compareEnvironmentA || 'baseline?') + ' vs ' + (a.compareEnvironmentB || 'candidate?') : '')
               : a.appUseCaseInstanceId ? 'instance no longer in the catalog' : 'no instance chosen yet';
    const target = findControl(a.targetControlId);
    const extra = performance || compare || dataset || a.rowSourceControlId ? [] : (a.extraBindings || []);
    const where = [a.targetControlId === NEW_GRID ? 'a new grid per run'
                : target ? controlTitle(target) + ' (' + target.type + ')'
                : a.targetControlId ? 'a control that is no longer here'
                : extra.length ? '' : 'nothing — run for its effect']
        .concat(extra.map(b => {
            const t = findControl(b.targetControlId);
            return b.targetControlId === NEW_GRID ? 'a new grid per run'
                : t ? controlTitle(t) + ' (' + t.type + ')' : 'a control not chosen yet';
        }))
        .filter(Boolean).join(', ');
    const rowSource = a.rowSourceControlId ? findControl(a.rowSourceControlId) : null;
    const fanOut = a.rowSourceControlId
        ? 'per row of ' + (rowSource ? controlTitle(rowSource) : 'a grid that is gone')
            + (a.rowOutputMode === 'TABS' ? ', a tab each' : '')
        : '';
    const chain  = a.transformNames || [];
    const inputs = Object.keys(a.inputs || {});
    const filters = a.rowSourceControlId ? (a.rowFilters || []) : [];
    const columns = a.rowSourceControlId && a.rowOutputMode !== 'TABS' ? (a.rowColumns || []) : [];
    const waitsFor = actionNamed(a.dependsOnActionId);
    // An action that binds its answer nowhere. Legitimate — an action can be run purely for its
    // effect at the other end — but far more often it is an action half wired: a target picked
    // and then the control deleted, or a new action nobody finished. Either way it is the one
    // thing about an action that cannot be told from the rest of the card, so it is marked rather
    // than left to read like any other line, and the designer decides which of the two it is.
    const noTarget = !performance && !compare && !dataset && !a.targetControlId && !extra.length;
    // Where this action is triggered from, for a page action — see #actionUsage. A control's own
    // action is run by the control it is written on and has nothing to answer here.
    const shared = isPageAction(a.actionId);
    const usedBy = shared ? actionUsage(a.actionId) : [];
    const move = (delta, title, glyph) =>
        '<button class="tool-btn" onclick="event.stopPropagation();' + fns.move + '(' + i + ', ' + delta + ')" title="'
            + title + '">' + glyph + '</button>';

    return '<div class="sum-card' + (noTarget ? ' no-target' : '')
            + (shared && !usedBy.length ? ' unused' : '') + '" onclick="' + fns.open + '(' + i + ')"'
            + ' title="Open this action">'
        + '<div class="sum-head">'
            + '<span class="action-num">' + (i + 1) + '</span>'
            // The name carries itself as its own tooltip: two lines of a 330px column hold a long
            // one, and the longest ones are exactly the ones worth reading whole.
            + '<span class="sum-title" title="' + AC.attr(a.actionLabel || 'Untitled action') + '">'
                + AC.esc(a.actionLabel || 'Untitled action') + '</span>'
            // Said on the first line rather than among the badges below: "does anything run
            // this" is what the reader is scanning the library for, and it belongs beside the
            // name they are scanning.
            + (shared ? (usedBy.length
                    ? '<span class="badge ok-badge" title="' + AC.attr('Triggered by ' + usedBy.join(', ')) + '">used by '
                        + usedBy.length + '</span>'
                    : '<span class="badge err" title="Nothing on this page triggers this action — no control, no '
                        + 'clickable column or row, no menu entry, and not the page opening. It can be removed, '
                        + 'unless it is waiting to be wired up to something not added yet.">not used</span>')
                : '')
            + '<span class="sum-btns">'
                + (i > 0 ? move(-1, 'Earlier', '↑') : '')
                + (i < count - 1 ? move(1, 'Later', '↓') : '')
                + (fns.clone ? '<button class="tool-btn" onclick="event.stopPropagation();' + fns.clone + '(' + i + ')"'
                    + ' title="Duplicate this action here">&#10064;</button>' : '')
                + (fns.copy ? '<button class="tool-btn" onclick="event.stopPropagation();' + fns.copy + '(' + i + ')"'
                    + ' title="Copy this action onto another control">⧉</button>' : '')
                + (fns.toPage && otherPages().length
                    ? '<button class="tool-btn" onclick="event.stopPropagation();' + fns.toPage + '(' + i + ')"'
                        + ' title="Copy this action onto another page">↗</button>' : '')
                + '<button class="icon-btn" onclick="event.stopPropagation();' + fns.remove + '(' + i + ')" title="Remove">×</button>'
            + '</span>'
        + '</div>'
        + '<div class="sum-line">'
            + '<span' + (instance || performance || (dataset && a.datasetName) ? '' : ' class="muted"') + '>' + AC.esc(runs) + '</span>'
            + (performance ? '<span class="badge auth">performance</span>' : '')
            + (dataset ? '<span class="badge auth">dataset</span>' : '')
            + (isMetadataAction(a) && !performance && !dataset ? '<span class="badge auth">metadata</span>' : '')
            + (a.ownCall ? '<span class="badge warn">own call</span>' : '')
            + (fanOut ? '<span class="badge' + (rowSource ? '' : ' err') + '">' + AC.esc(fanOut) + '</span>' : '')
        + '</div>'
        + '<div class="sum-line">'
            + '<span' + (noTarget ? ' class="target-none"' : '') + '>&rarr; ' + AC.esc(where) + '</span>'
            + (noTarget ? '<span class="badge err" title="This action binds what comes back into nothing. That is '
                    + 'a complete action if the call is worth making for its effect at the other end — but far more '
                    + 'often it is a target that was never picked, or one whose control has since been deleted.">'
                    + 'no target</span>' : '')
            + (waitsFor ? '<span class="badge">after ' + AC.esc(waitsFor.actionLabel || waitsFor.actionId) + '</span>'
                : a.dependsOnActionId ? '<span class="badge err">waits for an action that is gone</span>' : '')
            + (chain.length ? '<span class="badge">' + chain.length + ' transform' + (chain.length > 1 ? 's' : '') + '</span>' : '')
            // Both change what the action does rather than only how it is configured: one
            // decides which rows are called for at all, the other what the collected grid is
            // made of — so the card says so without being opened.
            + (filters.length ? '<span class="badge">' + filters.length + ' row filter' + (filters.length > 1 ? 's' : '') + '</span>' : '')
            + (columns.length ? '<span class="badge">' + columns.length + ' column' + (columns.length > 1 ? 's' : '') + '</span>' : '')
            + (GridPivot.isActive(a.pivot) ? '<span class="badge" title="' + AC.attr(GridPivot.describe(a.pivot)) + '">grouped</span>' : '')
            // Whether a run replaces the grid or adds to it changes what the operator is looking
            // at after the second click, so the card says so without being opened.
            + (bindingsOf(a).some(appendsToGrid)
                ? '<span class="badge" title="Its rows are added to the ones already in the grid">appends</span>' : '')
            + (inputs.length ? '<span>' + inputs.length + ' input' + (inputs.length > 1 ? 's' : '') + '</span>' : '')
        + '</div>'
        + '</div>';
}

function buttonProps(c) {
    const actions = c.actions || [];
    let html = '<div class="props-section"><div class="props-title"><span>Actions On This ' + AC.esc(c.type) + '</span>'
             + '<span class="props-jump">'
             + (controlsWithActions().length
                 ? '<button class="tool-btn" onclick="openCopyEditor()" title="Copy what another control runs onto '
                     + 'this one, or this one\'s onto others">Copy…</button>'
                 : '')
             + '<button class="tool-btn" onclick="addAction()">+ Add</button></span></div>';

    if (!actions.length && !(c.actionIds || []).length) {
        html += '<div class="empty-note">No actions — this ' + AC.esc(c.type) + ' does nothing yet. '
             + 'Add one here, or attach a page action above to share it with other controls.</div>';
    }
    actions.forEach((a, i) => { html += actionSummary(a, i, actions.length, CONTROL_FNS); });
    return html + '</div>';
}

/**
 * What this control writes into other controls when it is triggered. A select that puts the id
 * it just picked into a text box, and only then reloads a grid from it, is one control doing two
 * things in a fixed order — the values land first, so an action reading <code>${orderId}</code>
 * sees what was just put there rather than what was there before.
 *
 * <p>Offered wherever a trigger is: a button may fill fields in as well as run something, which
 * is how a "use last order" button is written.
 */
function assignProps(c) {
    const targets = page.controls.filter(t => t.controlId !== c.controlId && ASSIGN_TYPES.includes(t.type));
    const assignments = c.assignments || [];
    let html = '<div class="props-section"><div class="props-title"><span>Sets Values</span>'
             + (targets.length ? '<button class="tool-btn" onclick="addAssignment()">+ Add</button>' : '')
             + '</div>';

    if (!targets.length) {
        return html + '<div class="empty-note">Nothing to write into yet — add a text box, a hidden field '
             + 'or a label, and this ' + AC.esc(c.type) + ' can put a value there.</div></div>';
    }
    if (!assignments.length) {
        html += '<div class="empty-note">Sets nothing. Add one to have this ' + AC.esc(c.type)
             + ' fill in another control ' + (ACTION_TYPES.includes(c.type) ? 'when it is clicked'
                 : c.trigger === 'CHANGE' ? 'when it changes' : 'when its label is clicked')
             + ', before its actions run.</div>';
    }

    const own = c.fieldName ? 'this control\u2019s value (${' + c.fieldName + '})' : 'text, or ${fieldName}';
    html += assignments.map((a, i) =>
        '<div class="assign-row">'
            + '<select onchange="setAssignment(' + i + ', \'targetControlId\', this.value)">'
                + '<option value="">— pick a control —</option>'
                + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"' + (t.controlId === a.targetControlId ? ' selected' : '') + '>'
                    + AC.esc(controlTitle(t)) + ' (' + t.type + ')</option>').join('')
            + '</select>'
            + '<input type="text" placeholder="' + AC.attr(own) + '" value="' + AC.attr(a.value || '')
                + '" oninput="setAssignment(' + i + ', \'value\', this.value)">'
            + '<button class="icon-btn" onclick="removeAssignment(' + i + ')" title="Remove">×</button>'
        + '</div>').join('');

    return html + '<span class="hint">Left: the control written into. Right: what it is given — blank hands over '
        + 'this control\u2019s own value, otherwise text with <code>${fieldName}</code> filling in any control on the '
        + 'page. Written in the order listed, before any action below runs, so an action can send what was just set. '
        + 'Setting a value does not fire the other control\u2019s own trigger — attach anything that should also run '
        + 'here, under Page Actions.</span></div>';
}

/**
 * Whether this control sets anything off at all, which decides whether it is worth asking where
 * the operator should be looking afterwards.
 *
 * <p>Three ways of being a trigger, and all three count. An ordinary control is one — a button, a
 * link, a select that runs on change. A multi-button is one per entry rather than as itself. And
 * a grid is one through its clickable rows and columns, which is the case the scroll setting was
 * most written for: drilling into a row puts the detail somewhere else on the page entirely.
 */
function triggersSomething(c) {
    if (c.type === 'multibutton') return !!menuOptionsOf(c).length;
    if (GRID_OWNER_TYPES.includes(c.type)) return !!(c.rowClick || (c.columnLinks || []).length);
    if (TRIGGERLESS_TYPES.includes(c.type)) return false;
    // Wired up rather than merely able to be: the setting is about what happens after something
    // has run, and offering it on a text box that does nothing is one more box to read past.
    return !!(actionsFor(c).length || assignmentsOf(c).length);
}

/**
 * Where the operator should be looking once this control has finished running.
 *
 * <p>The setting exists because a page worth building is usually taller than a screen. The form
 * is at the top, the button is in the form, and the grid it fills is below the fold and often
 * behind a tab as well — so the run succeeds, the status line says so, and the answer is
 * somewhere the operator has to go and find. Named here, the page opens the tab and scrolls
 * there by itself, and marks the control for a moment so which of several grids answered is not
 * a guess.
 */
function focusProps(c) {
    // A hidden field and a grid holding its rows without being drawn are the two controls that
    // are never on screen, so scrolling to either is scrolling to nothing — the save refuses both
    // and the list does not offer them.
    const targets = page.controls.filter(t => t.controlId !== c.controlId
        && t.type !== 'hidden' && !t.hideOnRun);
    let html = '<div class="props-section"><div class="props-title"><span>After It Runs</span></div>';
    if (!targets.length) {
        return html + '<div class="empty-note">Nothing to scroll to yet — this is the only control on the '
             + 'page.</div></div>';
    }
    html += field('Scroll To', '<select onchange="setProp(\'focusControlId\', this.value)">'
            + '<option value="">— stay where the operator is —</option>'
            + targets.map(t => '<option value="' + AC.attr(t.controlId) + '"'
                + (t.controlId === c.focusControlId ? ' selected' : '') + '>'
                + AC.esc(controlTitle(t)) + ' (' + AC.esc(t.type) + ')</option>').join('')
            + '</select>',
        'Brought into view once everything this ' + AC.esc(c.type) + ' set off has finished, and marked for a '
            + 'couple of seconds so it is obvious which control answered. A control inside a tab set is reached '
            + 'by opening the tab it is behind — a minimized set is opened too. Whether the run worked or not: a '
            + 'grid that came back empty because the call failed is exactly what somebody needs to see.');
    return html + '</div>';
}

/**
 * Which of the page's actions this control triggers, and what sets them off. Offered for every
 * control, not just buttons: a select that reloads a grid when it changes is the same wiring as
 * a button that reloads it when clicked.
 */
/**
 * What sets this control off. Its own field rather than part of {@link #triggerProps} because a
 * control with assignments and no actions is offered it too, and that is on the other side of the
 * early return for a page whose action library is still empty.
 */
function triggerField(c) {
    return field('Runs On', '<select onchange="setProp(\'trigger\', this.value); renderProps()">'
            + '<option value="CLICK"' + (c.trigger === 'CHANGE' ? '' : ' selected') + '>Click</option>'
            + '<option value="CHANGE"' + (c.trigger === 'CHANGE' ? ' selected' : '') + '>Value change</option>'
            + '</select>',
        ACTION_TYPES.includes(c.type)
            ? 'A button or link normally runs on click.'
            : c.trigger === 'CHANGE'
                ? 'Value change fires when the operator picks a different option or leaves the field — not on every keystroke.'
                : 'Click turns this control\'s label into a link — there is nothing else on a box to click. The '
                    + 'field goes on taking a value as it always did, and the name written over it is what sets '
                    + 'the values and runs the actions, so a form asks for its answer when somebody has finished '
                    + 'filling it in rather than on every change.');
}

function triggerProps(c) {
    const library = page.actions || [];
    const chosen = c.actionIds || [];
    // Over everything this control runs, page-level and inline together: an action waits for
    // another action, and which of the two lists either of them lives in has nothing to do with
    // whether the wait can be honoured.
    const note = dependencyNote(actionsFor(c));
    let html = '<div class="props-section"><div class="props-title"><span>Page Actions</span>'
             + (controlsWithActions().length
                 ? '<button class="tool-btn" onclick="openCopyEditor()" title="Copy what another control runs onto '
                     + 'this one, or this one\'s onto others">Copy…</button>'
                 : '')
             + '</div>' + note;

    // Offered as soon as there is anything for it to set off, which is not only when the page has
    // an action library: a control that does nothing but write a value into another one is a whole
    // control, and when it does that is as much a decision there as it is for one that calls out.
    // On the rows as written rather than on the finished ones, so the field is there the moment
    // an assignment is added rather than a panel redraw after its target is picked.
    if (library.length || (c.assignments || []).length) html += triggerField(c);

    if (!library.length) {
        return html + '<div class="empty-note">The page has no actions yet — '
             + '<button class="tool-btn" onclick="showPageActions()">add one</button> and it can be attached here.'
             + '</div></div>';
    }

    html += '<div class="form-group"><label>Attached</label>'
         + library.map(a => {
             const on = chosen.includes(a.actionId);
             const order = on ? chosen.indexOf(a.actionId) + 1 : 0;
             return '<label class="inline-check"><input type="checkbox"' + (on ? ' checked' : '')
                 + ' onchange="toggleControlAction(\'' + AC.attr(a.actionId) + '\', this.checked)"> '
                 + (order ? '<b>' + order + '.</b> ' : '') + AC.esc(a.actionLabel || a.actionId) + '</label>';
         }).join('')
         + '<span class="hint">Sent at once when the control is triggered, then bound in the order they '
         + 'were attached — so one of them cannot read what another is about to write. An action that has '
         + 'to read another one\'s answer says so on itself, under Runs After, and is held back until '
         + 'that one has bound. The same action can be attached to as many controls as you like.</span></div>';

    return html + '</div>';
}

/**
 * The panel shown when nothing is selected: the page's own action library and what runs when the
 * page opens. Deliberately where "no control selected" already lived — a page-level thing belongs
 * in the properties panel when the properties panel is not busy with a control.
 */
/**
 * The cards of the Page Actions library, narrowed to whatever the filter box matches. Its own
 * function and its own element because typing in that box redraws only this: redrawing the whole
 * properties panel would rebuild the box and take the caret out of it with every keystroke.
 */
function pageActionCards() {
    const actions = page.actions || [];
    if (!actions.length) return '<div class="empty-note">No page actions yet.</div>';
    const filter = pageActionFilter.trim().toLowerCase();
    // An action's place in the library is what the move, clone and remove buttons on its card act
    // on, so the index is taken before the filter rather than after it.
    const shown = actions.map((a, i) => ({ action: a, index: i }))
        .filter(x => matchesActionFilter(x.action, filter));
    if (!shown.length) {
        return '<div class="empty-note">No action matches &ldquo;' + AC.esc(filter) + '&rdquo;.</div>';
    }
    return (filter ? '<div class="usage-line">' + shown.length + ' of ' + actions.length + ' shown</div>' : '')
        + shown.map(x => actionSummary(x.action, x.index, actions.length, PAGE_FNS)).join('');
}

/**
 * Whether an action belongs in the filtered library. Matched against everything its card is
 * recognised by, not the name alone: the instance it calls, so an environment collects every action
 * aimed at it, the controls it binds into, so a grid's name collects everything that fills it, and
 * the transforms it chains.
 */
function matchesActionFilter(a, filter) {
    if (!filter) return true;
    const instance = instances.find(x => x.appUseCaseInstanceId === a.appUseCaseInstanceId);
    const parts = [a.actionLabel, a.actionId];
    if (instance) parts.push(instance.instanceLabel, instance.appUseCaseName, instance.appEnvironment);
    bindingsOf(a).forEach(b => {
        const target = findControl(b.targetControlId);
        if (target) parts.push(controlTitle(target), target.fieldName);
    });
    (a.transformNames || []).forEach(name => parts.push(name));
    return parts.some(text => String(text || '').toLowerCase().includes(filter));
}

/** Narrows the library in place, leaving the box that was typed into alone. */
function filterPageActions(text) {
    pageActionFilter = text || '';
    const host = document.getElementById('pageActionCards');
    if (host) host.innerHTML = pageActionCards();
}

/**
 * Both list filters dropped, for whenever the designer is handed a different page. A filter typed
 * to find something on the page that was open names nothing on the one replacing it, and a list
 * that opens empty because of it reads as a page that lost its controls.
 */
function clearListFilters() {
    pageActionFilter = '';
    const search = document.getElementById('controlSearch');
    if (search) search.value = '';
}

function pageProps() {
    const actions = page.actions || [];
    const unused = unusedPageActions();
    let html = '<div class="stack mini">'
        + '<div class="props-section"><div class="props-title"><span>Page Actions</span>'
        + '<span class="props-jump">'
        + (unused.length
            ? '<button class="tool-btn" onclick="removeUnusedPageActions()" title="Remove the ' + unused.length
                + ' action' + (unused.length === 1 ? '' : 's') + ' nothing on this page triggers">Remove '
                + unused.length + ' unused</button>'
            : '')
        + (actionsWithOrigin().length && otherPages().length
            ? '<button class="tool-btn" onclick="openPageCopyEditor()" title="Copy an action from this page '
                + 'onto another page">To page…</button>'
            : '')
        + '<button class="tool-btn" onclick="addPageAction()">+ Add</button></span></div>'
        + '<span class="hint">Actions defined once here and attached to any number of controls — a button, a '
        + 'select that reloads on change, the page opening. Select a control to attach them. Click one to open it.</span>';

    // Offered from the point where scrolling the library costs more than typing into a box.
    if (actions.length > 3) {
        html += '<input class="list-search" id="pageActionSearch" type="text" autocomplete="off"'
            + ' style="margin-top:7px" placeholder="Filter by name, instance or target…"'
            + ' value="' + AC.attr(pageActionFilter) + '" oninput="filterPageActions(this.value)">';
    }

    // What the library adds up to, before the cards themselves. A page of twenty shared actions
    // where four are attached to nothing is a page with four things to tidy, and that is worth
    // knowing without reading twenty cards to work it out.
    if (actions.length) {
        html += '<div class="usage-line' + (unused.length ? ' has-unused' : '') + '">'
            + (actions.length - unused.length) + ' of ' + actions.length + ' triggered by something'
            + (unused.length ? ' · <b>' + unused.length + ' used by nothing</b>' : '')
            + '</div>';
    }

    html += '<div id="pageActionCards">' + pageActionCards() + '</div>';
    html += '</div>';

    html += transformProps();

    html += '<div class="props-section"><div class="props-title"><span>On Page Load</span></div>'
         + dependencyNote(actionsByIds(page.onLoadActionIds));
    if (!actions.length) {
        html += '<div class="empty-note">Add a page action first.</div>';
    } else {
        const chosen = page.onLoadActionIds || [];
        html += actions.map(a => {
            const on = chosen.includes(a.actionId);
            const order = on ? chosen.indexOf(a.actionId) + 1 : 0;
            return '<label class="inline-check"><input type="checkbox"' + (on ? ' checked' : '')
                + ' onchange="togglePageLoadAction(\'' + AC.attr(a.actionId) + '\', this.checked)"> '
                + (order ? '<b>' + order + '.</b> ' : '') + AC.esc(a.actionLabel || a.actionId) + '</label>';
        }).join('')
        + '<span class="hint">Run once as soon as the page opens — all sent at once, bound in the order '
        + 'attached, and only after every select has filled its own options, so an action may read what '
        + 'they settled on.</span>';
    }
    return html + '</div></div>';
}

// ── Property mutations ───────────────────────────────────────────────────
// Text inputs update the model and redraw the canvas only: redrawing the properties panel on
// every keystroke would take the caret with it.

function setProp(name, value) {
    const c = findControl(selectedId);
    if (!c) return;
    // Column and width are each clamped against the other, exactly as dragging the right edge
    // already is: a width of 24 typed onto a control in column 12 asks for columns 13 to 36 of a
    // twenty-four-column grid, and the browser answers by inventing the extra twelve — a canvas
    // that silently stops matching the page it is meant to be designing.
    if (name === 'col')     value = Math.min(Math.max(value || 0, 0), COLUMNS - c.span);
    // Half a row is as fine as the layout grid is drawn, and the row snaps to it exactly as the
    // height does: row 1.5 is the lower half of row one, which is where the field under a
    // half-row label goes. Anything between the two halves would be a placement the canvas could
    // not draw and the drag could not reproduce.
    if (name === 'row')     value = Math.max(Math.round((value || 0) * 2) / 2, 0);
    if (name === 'span')    value = Math.min(Math.max(value || 1, 1), COLUMNS - c.col);
    // Half a row is as thin as the grid draws, so the height snaps to that step.
    if (name === 'rowSpan') value = Math.min(Math.max(Math.round((value || 1) * 2) / 2, MIN_ROW_SPAN), MAX_ROW_SPAN);
    c[name] = value;
    renderControlList();
    renderCanvas();
}

/**
 * The grid's row check. Its own setter rather than {@link #setProp} because the note under the
 * box has to keep up with the typing, and redrawing the whole panel to move it would take the
 * caret out of the box being typed into — so only the note is rewritten.
 */
function setRowCheck(text) {
    const c = findControl(selectedId);
    if (!c) return;
    c.rowErrorExpression = text;
    const note = document.getElementById('rowCheckNote');
    if (note) note.innerHTML = rowCheckNote(c);
    renderCanvas();
}

/** The grid's display filter, kept up with the typing the same way as {@link #setRowCheck}. */
function setDisplayFilter(text) {
    const c = findControl(selectedId);
    if (!c) return;
    c.displayFilterExpression = text;
    const note = document.getElementById('displayFilterNote');
    if (note) note.innerHTML = rowCheckNote({ rowErrorExpression: text }, 'a display filter');
    renderCanvas();
}

/**
 * The note under an action's error check, kept up with the typing. Found from the box itself
 * rather than by id, because the same card is drawn for a control's action, a page action and the
 * editor's working copy, and more than one of them can be on screen at once.
 */
function refreshActionRowCheckNote(input, which) {
    const card = input.closest('.action-card');
    const note = card && card.querySelector('.action-rowcheck-note[data-note="' + which + '"]');
    if (note) note.innerHTML = rowCheckNote({ rowErrorExpression: input.value },
        which === 'filter' ? 'a display filter' : 'an error check');
}

function changeType(type) {
    const c = findControl(selectedId);
    if (!c) return;
    const was = c.type;
    c.type = type;
    // Only a chart or a grid draws itself from a grid, and only a grid is drawn from — the save refuses either left behind.
    if (!drawsFromGrid(type)) c.sourceGridControlId = '';
    if (!isChart(type)) { c.gridKeyField = ''; c.gridValueField = ''; }
    if (type !== 'grid') page.controls.forEach(other => {
        if (other.sourceGridControlId === c.controlId) other.sourceGridControlId = '';
    });
    // A field turned into a grid, a tab set, a pie chart or a multi-select is half a row tall,
    // which is a control with nowhere to draw what it now holds. It is given that type's own
    // starting height instead — and only when it is under it, so a grid deliberately laid out
    // taller than three rows stays where it was put.
    if (rowSpanOf(c) < defaultRowSpan(type)) c.rowSpan = defaultRowSpan(type);
    // Kept across select ⇄ multi-select: the two are configured identically, and someone
    // switching one for the other is changing how many may be picked, not what there is to pick.
    if (isSelect(type) && !c.optionSource) c.optionSource = { mode: 'NONE', staticOptions: [] };
    // A button and a link differ only in how much room they take, so switching between the two
    // keeps the actions that were already wired up.
    // Inline actions belong to a button or a link; page-level ones the control triggers survive
    // the change, so a button turned into a select keeps its wiring and just fires on change.
    // Only a button or a link becoming a box resets what sets it off: the thing that was clicked
    // has gone, and changing the value is the obvious way in to the control that replaced it.
    // Between two boxes the trigger is kept — a text field turned into a date field is the same
    // field, and its label was a link before the change for the reason it still is one after.
    if (!ACTION_TYPES.includes(type)) {
        c.actions = [];
        if (ACTION_TYPES.includes(was)) c.trigger = 'CHANGE';
    }
    else c.trigger = 'CLICK';
    // Nothing triggers a grid, a label, a tab set or a hidden field, so what this control was
    // set to write and what it was set to run both go with the type rather than being kept as
    // wiring that can never fire; and a control that has stopped being something a value can be
    // put into is dropped from whatever was writing into it, the same way a deleted one would be.
    if (TRIGGERLESS_TYPES.includes(type)) { c.assignments = []; c.actionIds = []; }
    if (!ASSIGN_TYPES.includes(type)) {
        page.controls.forEach(other => {
            other.assignments = (other.assignments || []).filter(a => a.targetControlId !== c.controlId);
        });
    }
    if (!VALUE_TYPES.includes(type)) { c.fieldName = ''; c.mandatory = false; }
    else if (!c.fieldName) c.fieldName = nextFieldName(type);
    // A tab set holds grids and charts, so a control that stops being one of those leaves the set
    // it was in, and a set that stops being a set lets go of what it was holding. Everything goes
    // back on the layout, which is where its row and column have been waiting the whole time.
    if (!isTabChild(type)) releaseFromContainers(c.controlId);
    // Only a grid opens holding a dataset's rows, so that goes with the type rather than being
    // left as a setting nothing reads.
    if (type !== 'grid') c.datasetName = '';
    // Only a grid or a list of options has rows to fan an action out over.
    if (type !== 'grid' && !isSelect(type)) {
        allActions().forEach(a => {
            if (a.rowSourceControlId === c.controlId) { a.rowSourceControlId = ''; a.rowOutputMode = 'ROWS'; }
        });
    }
    if (type !== 'tabs') c.tabControlIds = [];
    else c.tabControlIds = c.tabControlIds || [];
    // A panel that stops being one lets go of what it was holding, which goes back onto the
    // layout — the row and column it kept the whole time it was in the box are now places on
    // the page again, which is exactly where they were before it was gathered up.
    if (type !== 'panel') c.panelControlIds = [];
    else c.panelControlIds = c.panelControlIds || [];
    // And a menu is a multi-button's alone: on anything else it would be a list nothing draws,
    // and the save refuses one left behind.
    if (type !== 'multibutton') c.menuOptions = [];
    else c.menuOptions = c.menuOptions || [];
    // Clickable columns are a grid's alone: a control that has stopped being one has no cells to
    // click, so they go with the type rather than sitting in the saved page unreachable.
    if (!GRID_OWNER_TYPES.includes(type)) c.columnLinks = [];
    else c.columnLinks = c.columnLinks || [];
    // And its clickable rows, for the same reason: a control that is no longer a grid has no rows
    // to click on, so what a click was to do goes with the type.
    if (!GRID_OWNER_TYPES.includes(type)) c.rowClick = null;
    // A row check is a grid's alone for the same reason: nothing else has rows to put through it,
    // and the save refuses one left behind on a control that is no longer a grid.
    if (type !== 'grid') c.rowErrorExpression = '';
    if (type !== 'grid') c.displayFilterExpression = '';
    // And its status, which counts the rows it holds.
    if (type !== 'grid') { c.statusCondition = ''; c.statusVariable = ''; }
    // Only a grid can hold its rows without being drawn: a control that takes a value and is not
    // drawn is a hidden field, which is a type of its own.
    if (type !== 'grid') c.hideOnRun = false;
    // Same again for the order it opens in: only a grid has rows to put in one, so a control that
    // has stopped being a grid lets go of the column it was sorted by rather than carrying a
    // setting nothing would ever read.
    if (type !== 'grid') { c.sortColumn = ''; c.sortDirection = 'ASC'; c.topRows = 0; }
    // The columns it shows first go the same way and for the same reason: they are an order over
    // columns, and a control that is no longer a grid has none.
    if (type !== 'grid') c.leadColumns = [];
    else c.leadColumns = c.leadColumns || [];
    // The columns it does not draw, and whether it draws them wrapped, go the same way and for
    // the same reason: both are about a table of rows, and this control no longer has one.
    if (type !== 'grid') { c.hiddenColumns = []; c.wrapText = false; }
    else c.hiddenColumns = c.hiddenColumns || [];
    // And the form a date is written in, which only a date control has a date to write.
    if (type !== 'date') c.dateFormat = '';
    // Slices are a pie's whole content and mean nothing on anything else, so they go with the
    // type rather than sitting in the saved page behind a control that cannot draw them.
    if (type !== 'pie') c.slices = [];
    else c.slices = c.slices || [];
    // Named colours belong to either pie, since either draws wedges by name; anything else has no
    // slices for them to be about.
    if (type !== 'pie' && type !== 'piegrid') c.sliceColors = [];
    else c.sliceColors = c.sliceColors || [];
    // And the check over those wedges, for the reason a grid's row check goes with the type:
    // nothing else has slices to put through it, and the save refuses one left behind.
    if (type !== 'pie' && type !== 'piegrid') c.sliceErrorExpression = '';
    // The tab set a pie with grids fills is its alone; a tab set that stops being one can no longer
    // be filled, or open on a default tab.
    if (type !== 'piegrid') c.tabsControlId = '';
    if (type !== 'tabs') {
        c.defaultTabControlId = '';
        page.controls.forEach(other => { if (other.tabsControlId === c.controlId) other.tabsControlId = ''; });
    }
    if (type === 'bar') c.orientation = c.orientation === 'HORIZONTAL' ? 'HORIZONTAL' : 'VERTICAL';
    // Filters belong to either chart that reads rows along an axis; the axis itself belongs to
    // one of them each — a time column to the time series, an x column to the line chart — and
    // the save refuses either on the other, or on anything else.
    if (!isSeries(type)) { c.chartFilters = []; }
    else { c.timeAggregate = c.timeAggregate || 'SUM'; c.chartFilters = c.chartFilters || []; }
    if (type !== 'timeseries') {
        c.timeField = ''; c.timeFormat = ''; c.timeBucket = 'AUTO';
        // The offset is a second column added to the time column, so it goes wherever that does.
        c.timeOffsetField = ''; c.timeOffsetUnit = 'SECONDS';
    } else {
        c.timeBucket = c.timeBucket || 'AUTO';
        c.timeOffsetUnit = c.timeOffsetUnit || 'SECONDS';
    }
    if (type !== 'line') c.xField = '';
    // Only a link opens another page, so a control that has stopped being one lets go of the
    // page it named rather than carrying a setting nothing would ever read.
    if (type !== 'link') { c.linkPageName = ''; delete linkModePick[c.controlId]; }
    // The same for the page a page control runs.
    if (type !== 'page') c.childPageName = '';
    renderAll();
}

function setOption(name, value) {
    const c = findControl(selectedId);
    if (!c) return;
    c.optionSource = c.optionSource || { mode: 'NONE', staticOptions: [] };
    c.optionSource[name] = value;
    renderCanvas();
}

function addStaticOption() {
    const c = findControl(selectedId);
    c.optionSource.staticOptions = c.optionSource.staticOptions || [];
    c.optionSource.staticOptions.push({ key: '', value: '' });
    renderProps();
    renderCanvas();
}

function setStaticOption(index, name, value) {
    findControl(selectedId).optionSource.staticOptions[index][name] = value;
}

function removeStaticOption(index) {
    const c = findControl(selectedId);
    c.optionSource.staticOptions.splice(index, 1);
    renderProps();
    renderCanvas();
}

function addAssignment() {
    const c = findControl(selectedId);
    c.assignments = c.assignments || [];
    c.assignments.push({ targetControlId: '', value: '' });
    renderProps();
    renderControlList();
}

/** No redraw of the panel: the value box is typed into, and redrawing would take the caret. */
function setAssignment(index, name, value) {
    const c = findControl(selectedId);
    c.assignments[index][name] = value;
    renderControlList();
}

function removeAssignment(index) {
    const c = findControl(selectedId);
    c.assignments.splice(index, 1);
    renderProps();
    renderControlList();
}

function setColumns(text) {
    const c = findControl(selectedId);
    c.columns = text.split(',').map(s => s.trim()).filter(Boolean);
    renderCanvas();
}

function setLeadColumns(text) {
    const c = findControl(selectedId);
    c.leadColumns = text.split(',').map(s => s.trim()).filter(Boolean);
    renderCanvas();
}

function setHiddenColumns(text) {
    const c = findControl(selectedId);
    c.hiddenColumns = text.split(',').map(s => s.trim()).filter(Boolean);
    renderCanvas();
}

function blankAction(label) {
    return { actionId: newActionId(), actionLabel: label, actionKind: USECASE_ACTION, appUseCaseInstanceId: '',
             environmentOverride: '', inputs: {}, targetControlId: '', arrayPath: '', valuePath: '',
             keyField: '', labelField: '', valueField: '', dependsOnActionId: '',
             keyValueGrid: false, scalarsOnly: false, appendRows: false, source: 'PAYLOAD', transformNames: [], ownCall: false,
             rowSourceControlId: '', rowOutputMode: 'ROWS', rowLabelTemplate: '', rowErrorExpression: '', displayFilterExpression: '', rowElements: '', rowLimit: DEFAULT_ROW_LIMIT,
             rowFilters: [], bindFilters: [], rowColumns: [], enrichColumns: [], extraBindings: [], pivot: null,
             compareEnvironmentA: '', compareEnvironmentB: '', compareType: COMPARE_JSON, comparePath: '',
             compareTolerancePercent: 0, compareReport: REPORT_DIFFERENCES,
             datasetName: '', datasetFavorite: '', datasetFilters: [] };
}

/** Page actions are referred to by id from every control that triggers them, so each needs one. */
function newActionId() {
    return 'a-' + Math.random().toString(36).substring(2, 10);
}

/**
 * What a duplicate is called: the original's name with "copy" after it, numbered if that name is
 * taken too. Names are what an action is picked out by — in the card list, in the tick-list a
 * control attaches from, in the status line a run writes — so two of them reading the same is
 * worth this much arithmetic to avoid.
 */
function copyLabel(label, taken) {
    return uniqueLabel((label || 'Untitled action') + ' copy', taken);
}

/**
 * A name that is not already in use, numbered from 2 if it is. Kept apart from {@link #copyLabel}
 * because an action copied onto another page keeps the name it had — there is no original beside
 * it over there for "copy" to distinguish it from — and only a clash needs the arithmetic.
 */
function uniqueLabel(name, taken) {
    const base = name || 'Untitled action';
    if (!taken.includes(base)) return base;
    let n = 2;
    while (taken.includes(base + ' ' + n)) n++;
    return base + ' ' + n;
}

function addAction() {
    const c = findControl(selectedId);
    c.actions = c.actions || [];
    c.actions.push(blankAction('Action ' + (c.actions.length + 1)));
    renderProps();
    renderCanvas();
    // A blank action has nothing to say on a card, so adding one opens it rather than leaving
    // an empty card to be clicked.
    openControlActionEditor(c.actions.length - 1);
}

// Fields that decide which other fields the card even asks for, and so redraw it: the target's
// type settles whether key/label or a value path is wanted, and whether the action fans out —
// and into what — settles the rest of them, the list of targets included.
// keyValueGrid is here for a narrower reason than the rest: it is the only one of them that
// decides whether one further field is asked for rather than a whole section, and it is a tick
// box, so a redraw costs nothing that was being typed.
// compareType is here for the same reason keyValueGrid is: it changes one field's hint rather
// than a section, and it is a two-option select, so a redraw costs nothing that was being typed.
// datasetName is here because it decides what every column dropdown under it may offer, and which
// saved filters there are to choose from at all.
const REDRAWING_FIELDS = ['targetControlId', 'rowSourceControlId', 'rowOutputMode', 'keyValueGrid',
                          'compareType', 'datasetName',
                          // The instance decides which variables the Inputs field lists, so the
                          // panel has to be redrawn around a new one rather than left listing the
                          // previous use case's.
                          'appUseCaseInstanceId'];

/**
 * A different dataset has different columns and different saved filters, so what was picked out of
 * the last one goes — the same rule an enriched column's lookup follows when its dataset changes.
 *
 * <p>The conditions are left alone rather than emptied. A column dropped here is one pick to make
 * again; a list of conditions dropped here is somebody's afternoon, and one naming a column the new
 * dataset has not got is shown saying exactly that rather than silently matching nothing.
 */
function dropDatasetColumns(a, name) {
    if (name !== 'datasetName' || !a) return;
    a.datasetFavorite = '';
    a.keyField = '';
    a.labelField = '';
    a.valueField = '';
}

function setAction(index, name, value) {
    const c = findControl(selectedId);
    c.actions[index][name] = value;
    dropDatasetColumns(c.actions[index], name);
    if (REDRAWING_FIELDS.includes(name)) renderProps();
    renderCanvas();
}

/**
 * Switches what an action does, clearing what the kind it is leaving behind had configured and
 * the kind it is arriving at has no use for.
 *
 * <p>Cleared rather than kept out of sight, because these settings are checked when the page is
 * saved: a performance action still carrying a transform chain or a fan-out would be refused for
 * wiring its panel no longer shows, which is the worst kind of refusal to be handed. What the two
 * kinds genuinely share stays — the name, the target grid, the filters that were written as
 * inputs, and what this action waits for.
 */
function applyActionKind(a, kind) {
    a.actionKind = kind === PERFORMANCE_ACTION ? PERFORMANCE_ACTION
                 : kind === COMPARE_ACTION ? COMPARE_ACTION
                 : kind === DATASET_ACTION ? DATASET_ACTION
                 : USECASE_ACTION;
    // A dataset action keeps what is about the rows and loses what is about a call. The key and
    // label fields stay, because they mean on it exactly what they mean on an ordinary action
    // filling the same dropdown, and so do the filters, the group-by and the enriched lookups —
    // all three are questions about rows, and rows are what this produces.
    if (isDatasetAction(a)) {
        a.appUseCaseInstanceId = '';
        a.environmentOverride = '';
        a.inputs = {};
        a.arrayPath = '';
        a.valuePath = '';
        a.transformNames = [];
        a.source = 'PAYLOAD';
        a.keyValueGrid = false;
        a.scalarsOnly = false;
        a.ownCall = false;
        a.rowSourceControlId = '';
        a.rowLabelTemplate = '';
        a.rowErrorExpression = '';
        a.displayFilterExpression = '';
        // Both describe fanning out, which this cannot do — and both are checked at the save, so a
        // leftover would have the page refused for wiring its panel no longer shows. The filters
        // that narrow what it binds are a different list and stay: they are about the rows.
        a.rowFilters = [];
        a.rowColumns = [];
        // The two enriched kinds that read the call — there is none to read, and the catalog
        // refuses them rather than letting a column sit quietly empty down every row.
        a.enrichColumns = (a.enrichColumns || []).filter(column => {
            const columnKind = String((column && column.kind) || 'META').toUpperCase();
            return columnKind !== 'META' && columnKind !== 'HEADER';
        });
        // One list, so one control it goes in.
        a.extraBindings = [];
        clearNonDatasetTarget(a);
        return;
    }
    // Leaving this kind behind: what it read, and how it narrowed what it read, describe nothing
    // any other kind does — and a leftover would be checked at the save against a form that no
    // longer shows it.
    a.datasetName = '';
    a.datasetFavorite = '';
    a.datasetFilters = [];
    // A comparison keeps the instance, the inputs and the transform chain — all three mean on it
    // exactly what they mean on an ordinary action, and an action switched to compare is usually
    // one somebody has already got working against one environment. What goes is the wiring that
    // reads a response into a control, since its report has a shape of its own.
    if (isCompareAction(a)) {
        a.environmentOverride = '';
        a.arrayPath = '';
        a.valuePath = '';
        a.keyField = '';
        a.labelField = '';
        a.valueField = '';
        a.source = 'PAYLOAD';
        a.keyValueGrid = false;
        a.scalarsOnly = false;
        a.rowSourceControlId = '';
        a.rowLabelTemplate = '';
        a.rowErrorExpression = '';
        a.displayFilterExpression = '';
        // Both describe fanning out, which a comparison cannot do, and both are checked at the
        // save — so a leftover has the page refused over wiring the panel no longer shows, which
        // is the worst kind of refusal to be handed.
        a.rowFilters = [];
        a.rowColumns = [];
        a.enrichColumns = [];
        a.extraBindings = [];
        // The report has its own six columns and its own rows, so a group-by written for the
        // grid this action used to fill, and filters written against that grid's columns, are
        // tests against columns that no longer exist. The grid's own filter row is what narrows
        // a report once it is on screen.
        a.bindFilters = [];
        a.pivot = null;
        // Nor is there a tick box for adding to what the grid holds, so a leftover one would be
        // state nobody could see and nobody could turn off.
        a.appendRows = false;
        // Two calls, made on purpose against two environments, so the per-trigger cache that
        // collapses identical calls has nothing to collapse — but the flag says what is true.
        a.ownCall = true;
        clearNonGridTarget(a);
        return;
    }
    if (!isPerformanceAction(a)) return;
    a.appUseCaseInstanceId = '';
    a.environmentOverride = '';
    a.arrayPath = '';
    a.valuePath = '';
    a.keyField = '';
    a.labelField = '';
    a.valueField = '';
    a.transformNames = [];
    a.source = 'PAYLOAD';
    a.keyValueGrid = false;
    a.scalarsOnly = false;
    a.ownCall = false;
    a.rowSourceControlId = '';
    a.rowLabelTemplate = '';
    a.rowErrorExpression = '';
    a.displayFilterExpression = '';
    // Both describe fanning out, which a summary cannot do, and both are checked at the save —
    // so a leftover has the page refused over wiring the panel no longer shows. The filters that
    // narrow what reaches the grid, and the group-by before it, are different lists and stay:
    // both are about the rows, and the summary has rows like anything else.
    a.rowFilters = [];
    a.rowColumns = [];
    // It makes no call, so there is no record and no header for an enriched column to read — and
    // the catalog refuses them outright rather than letting one sit empty down every row.
    a.enrichColumns = [];
    // A summary fills one grid; there is no response for further targets to read.
    a.extraBindings = [];
    clearNonGridTarget(a);
}

/**
 * Lets go of a target that is not a grid — what the two table-shaped kinds do on arrival, since a
 * grid is the only place either of them can put its answer. Dropped rather than carried into a
 * panel that would not offer it: a target the form does not show is a target nobody can correct,
 * and the page would be refused on save for wiring its own designer had hidden.
 */
/**
 * Drops a target a dataset action cannot fill — a text box or a link kept from when this was an
 * ordinary action — while keeping one it can. Unlike the other special kinds this is not "a grid
 * or nothing": a dropdown and a chart hold a list of rows as readily as a grid does, and an action
 * switched over to a dataset is very often one already aimed at exactly such a control.
 */
function clearNonDatasetTarget(a) {
    if (!a.targetControlId || a.targetControlId === NEW_GRID) return;
    const target = findControl(a.targetControlId);
    if (!target || !(target.type === 'grid' || isSelect(target.type) || isChart(target.type))) {
        a.targetControlId = '';
    }
}

function clearNonGridTarget(a) {
    const target = findControl(a.targetControlId);
    if (a.targetControlId && a.targetControlId !== NEW_GRID && (!target || target.type !== 'grid')) {
        a.targetControlId = '';
    }
}

function setActionKind(index, kind) {
    applyActionKind(findControl(selectedId).actions[index], kind);
    renderProps();
    renderCanvas();
}

function setPageActionKind(index, kind) {
    applyActionKind(page.actions[index], kind);
    renderProps();
    renderControlList();
}

function setDraftKind(index, kind) {
    if (!editor) return;
    applyActionKind(editor.draft, kind);
    renderEditor();
}

/**
 * Switching an action to metadata turns the key/value grid on, since a metadata record read down
 * the page is what a "call details" panel wants; switching back turns it off again, because an
 * ordinary array response has no use for it.
 */
function setActionSource(index, value) {
    const a = findControl(selectedId).actions[index];
    a.source = value;
    a.keyValueGrid = value === 'METADATA';
    renderProps();
    renderCanvas();
}

/** Inputs are typed as JSON; an unparseable draft is kept as-is rather than thrown away mid-edit. */
function setActionInputs(index, text) {
    const c = findControl(selectedId);
    try {
        c.actions[index].inputs = text.trim() ? JSON.parse(text) : {};
        AC.setStatus('statusBar', '');
    } catch (e) {
        AC.setStatus('statusBar', 'Action inputs are not valid JSON yet: ' + e.message, 'error');
    }
}

/** One variable of one inline action, from the list the Inputs field draws. See #applyInputVar. */
function setActionInputVar(index, name, what, value) {
    const a = findControl(selectedId).actions[index];
    if (applyInputVar(a, inputsKey(a, index, CONTROL_FNS), name, what, value)) renderProps();
}

function moveAction(index, delta) {
    const actions = findControl(selectedId).actions;
    const target = index + delta;
    if (target < 0 || target >= actions.length) return;
    [actions[index], actions[target]] = [actions[target], actions[index]];
    renderProps();
}

function removeAction(index) {
    const [removed] = findControl(selectedId).actions.splice(index, 1);
    // A wait on an action that has just gone would leave the one waiting held back by nothing,
    // which at run time reads as an action that mysteriously never went out. Cleared here, the
    // same way a target pointing at a deleted control is.
    clearWaitsOn(removed && removed.actionId);
    renderProps();
    renderCanvas();
}

/** Drops every dependency naming this action, wherever on the page it was written. */
function clearWaitsOn(actionId) {
    if (!actionId) return;
    allActions().forEach(a => { if (a.dependsOnActionId === actionId) a.dependsOnActionId = ''; });
}

/**
 * A second action that is the first one with a field or two changed — the common case being the
 * same instance read a different way, or the same call written to another grid. The duplicate is
 * a deep copy sitting straight after the original, so the pair reads together in the list and
 * editing either one leaves the other alone, and it opens so the change it was made for can be
 * made now rather than after hunting it back down.
 */
function cloneControlAction(index) {
    const c = findControl(selectedId);
    const source = (c.actions || [])[index];
    if (!source) return;
    const copy = cloneValue(source);
    // Its own id, for the same reason a duplicated library entry takes one: an action is waited
    // for by id, and a second one carrying the first's would be the first as far as any
    // dependency could tell. What it waits for is kept — the duplicate sits on the same control,
    // so whatever the original waits for is still in the same trigger.
    copy.actionId = newActionId();
    copy.actionLabel = copyLabel(source.actionLabel, c.actions.map(a => a.actionLabel || ''));
    c.actions.splice(index + 1, 0, copy);
    renderProps();
    renderCanvas();
    openControlActionEditor(index + 1);
}

/**
 * Every edit to an action's chain, against whichever list the action lives in. One function for
 * four operations because a step select set back to blank means "drop this step", which is the
 * same splice as the × beside it, and because the two moves are the same swap in either
 * direction. Redrawing is left to the caller: the same chain is edited in the properties panel
 * and in the editor over the page, and only the caller knows which of the two is on screen.
 */
function chainSteps(actions, index, op, at, value) {
    const a = actions[index];
    const chain = a.transformNames = a.transformNames || [];
    if (op === 'add') {
        if (!value) return;
        chain.push(value);
    } else if (op === 'set') {
        if (value) chain[at] = value; else chain.splice(at, 1);
    } else if (op === 'remove') {
        chain.splice(at, 1);
    } else if (op === 'move') {
        const target = at + value;
        if (target < 0 || target >= chain.length) return;
        [chain[at], chain[target]] = [chain[target], chain[at]];
    }
}

function chainAction(index, op, at, value) {
    chainSteps(findControl(selectedId).actions, index, op, at, value);
    renderProps();
}

// ── The page's own action library ────────────────────────────────────────
// The same four mutations as above against page.actions rather than a control's, plus the
// reference-keeping a shared action needs: removing one has to take it off every control that
// triggers it, or the page would refuse to save pointing at an action that is not there.

function addPageAction() {
    page.actions = page.actions || [];
    const action = blankAction('Action ' + (page.actions.length + 1));
    action.actionId = newActionId();
    page.actions.push(action);
    renderProps();
    openPageActionEditor(page.actions.length - 1);
}

/**
 * The same duplicate as on a control, plus the two things a library entry needs. It takes its own
 * id, since an action is attached by id and a second entry carrying the first one's would be the
 * first one; and it is attached to nothing, because a duplicate that arrived already triggered
 * everywhere the original is would have every one of those controls quietly running twice.
 */
function clonePageAction(index) {
    const source = (page.actions || [])[index];
    if (!source) return;
    const copy = cloneValue(source);
    copy.actionId = newActionId();
    copy.actionLabel = copyLabel(source.actionLabel, page.actions.map(a => a.actionLabel || ''));
    page.actions.splice(index + 1, 0, copy);
    renderProps();
    AC.setStatus('statusBar', 'Duplicated as "' + copy.actionLabel + '" — it is attached to nothing yet.', 'ok');
    openPageActionEditor(index + 1);
}

function setPageAction(index, name, value) {
    page.actions[index][name] = value;
    dropDatasetColumns(page.actions[index], name);
    if (REDRAWING_FIELDS.includes(name)) renderProps();
    if (name === 'actionLabel') renderControlList();
}

function setPageActionSource(index, value) {
    const a = page.actions[index];
    a.source = value;
    a.keyValueGrid = value === 'METADATA';
    renderProps();
}

function setPageActionInputs(index, text) {
    try {
        page.actions[index].inputs = text.trim() ? JSON.parse(text) : {};
        AC.setStatus('statusBar', '');
    } catch (e) {
        AC.setStatus('statusBar', 'Action inputs are not valid JSON yet: ' + e.message, 'error');
    }
}

function setPageActionInputVar(index, name, what, value) {
    const a = page.actions[index];
    if (applyInputVar(a, inputsKey(a, index, PAGE_FNS), name, what, value)) renderProps();
}

function chainPageAction(index, op, at, value) {
    chainSteps(page.actions, index, op, at, value);
    renderProps();
}

function movePageAction(index, delta) {
    const target = index + delta;
    if (target < 0 || target >= page.actions.length) return;
    [page.actions[index], page.actions[target]] = [page.actions[target], page.actions[index]];
    renderProps();
}

function removePageAction(index) {
    const [removed] = page.actions.splice(index, 1);
    page.controls.forEach(c => {
        c.actionIds = (c.actionIds || []).filter(id => id !== removed.actionId);
        // A clickable column names actions the same way a control does, so it loses them the
        // same way — otherwise the column would stay marked live and run nothing.
        (c.columnLinks || []).forEach(link => {
            link.actionIds = (link.actionIds || []).filter(id => id !== removed.actionId);
        });
        // Clickable rows name actions the same way, and lose them the same way.
        if (c.rowClick) {
            c.rowClick.actionIds = (c.rowClick.actionIds || []).filter(id => id !== removed.actionId);
        }
        // And a multi-button's menu entries, which are the same attachment one level in. An
        // entry left naming nothing would be a line on the menu that looks live and does not run.
        (c.menuOptions || []).forEach(o => {
            o.actionIds = (o.actionIds || []).filter(id => id !== removed.actionId);
        });
    });
    page.onLoadActionIds = (page.onLoadActionIds || []).filter(id => id !== removed.actionId);
    clearWaitsOn(removed.actionId);
    renderAll();
}

/**
 * Everywhere one page action is attached, named the way the designer would recognise it.
 *
 * <p>The question the library could not answer until now. A page that has grown to twenty shared
 * actions has some that six controls run and some that nothing runs at all — left behind by a
 * button that was deleted, a column that stopped drilling down, an idea that was replaced — and
 * from the library alone the two look exactly alike. So every card says which it is, and an
 * unused one can be taken off without first opening every control on the page to check.
 *
 * <p>What counts is being somewhere the operator could set it off: attached to a control, on a
 * clickable column or row, on a menu entry, or in the page's on-load list. Being waited for by
 * another action is not one of them and deliberately so — a "runs after" is an ordering between
 * two actions, not a way for either of them to be run, so an action nothing triggers is unused
 * however many others are queued behind it.
 */
function actionUsage(actionId) {
    const used = [];
    if ((page.onLoadActionIds || []).includes(actionId)) used.push('the page opening');
    page.controls.forEach(c => {
        const name = controlTitle(c);
        if ((c.actionIds || []).includes(actionId)) used.push(name);
        (c.columnLinks || []).forEach(link => {
            if ((link.actionIds || []).includes(actionId)) used.push(name + ' · ' + (link.column || 'a column'));
        });
        if (c.rowClick && (c.rowClick.actionIds || []).includes(actionId)) used.push(name + ' · rows');
        (c.menuOptions || []).forEach(o => {
            if ((o.actionIds || []).includes(actionId)) used.push(name + ' · ' + (o.label || 'a menu entry'));
        });
    });
    return used;
}

/** The page actions nothing on the page triggers — see {@link #actionUsage}. */
function unusedPageActions() {
    return (page.actions || []).filter(a => !actionUsage(a.actionId).length);
}

/**
 * Takes every page action nothing triggers off the page at once.
 *
 * <p>The point of saying which actions are unused is being able to act on it, and going through
 * them one card at a time is the thing the badge was meant to save. Confirmed rather than simply
 * done, and the message names them, because "unused" is a reading of the page as it is now: an
 * action attached to a control that has not been added yet is genuinely unused and genuinely
 * about to be wanted.
 */
function removeUnusedPageActions() {
    const unused = unusedPageActions();
    if (!unused.length) return;
    const names = unused.map(a => '• ' + (a.actionLabel || a.actionId)).join('\n');
    if (!confirm('Remove ' + unused.length + ' page action' + (unused.length === 1 ? '' : 's')
        + ' that nothing on this page triggers?\n\n' + names
        + '\n\nAnything waiting on them stops waiting.')) return;
    unused.forEach(a => {
        const at = page.actions.indexOf(a);
        if (at === -1) return;
        page.actions.splice(at, 1);
        clearWaitsOn(a.actionId);
    });
    AC.setStatus('statusBar', unused.length + ' unused action' + (unused.length === 1 ? '' : 's') + ' removed.', 'ok');
    renderAll();
}

// ── The page's transform library ─────────────────────────────────────────
// Named steps rather than ones written on each action: the endpoint that returns an auction
// returns it the same way whichever button asked for it, so the expression that flattens it into
// rows is one expression however many actions bind it — and the step that turns that endpoint's
// XML into JSON is one step however many expressions run after it.

/** Every action on the page, wherever it lives — the library's and the ones written on controls. */
function allActions() {
    return (page.actions || []).concat(...page.controls.map(c => c.actions || []));
}

/** Which actions chain a step, so an unused one is visible as unused. */
function transformUsers(name) {
    if (!name) return [];
    return allActions().filter(a => [a].concat(a.extraBindings || [])
            .some(b => (b.transformNames || []).includes(name)))
        .map(a => a.actionLabel || a.actionId || 'an action');
}

function transformProps() {
    const transforms = page.transforms || [];
    let html = '<div class="props-section"><div class="props-title"><span>Transforms</span>'
        + '<span>'
            + (jsonataLibrary.length
                ? '<button class="tool-btn" onclick="addSharedTransform()" title="Add a step that runs a shared expression">+ Shared</button> '
                : '')
            + '<button class="tool-btn" onclick="addTransform()">+ Add</button>'
        + '</span></div>'
        + '<span class="hint">Named steps, run in the browser over whatever an action bound, before that '
        + 'action&#39;s path reads out of the result. An action chains as many as it needs — '
        + '<code>xml&#8594;json</code> then JSONata then more JSONata — so each reshaping is written once and '
        + 'every action that wants it names it. A step may run an expression from the '
        + '<a href="appjsonata.html" target="_blank">shared library</a> instead of one written here, which is how '
        + 'the same reshaping is shared with other pages rather than copied into them.</span>';

    if (!transforms.length) {
        html += '<div class="empty-note">No transforms yet.</div>';
    }

    transforms.forEach((t, i) => { html += transformSummary(t, i, transforms.length); });
    return html + '</div>';
}

/** One transform as a card — its kind, its name, what it does and who uses it. */
function transformSummary(t, i, count) {
    const users = transformUsers(t.name);
    const xml = t.type === 'XML2JSON';
    const move = (delta, title, glyph) =>
        '<button class="tool-btn" onclick="event.stopPropagation();moveTransform(' + i + ', ' + delta + ')" title="'
            + title + '">' + glyph + '</button>';

    return '<div class="sum-card" onclick="openTransformEditor(' + i + ')" title="Open this transform">'
        + '<div class="sum-head">'
            + '<span class="xform-tag' + (xml ? ' xml' : t.jsonataRef ? ' shared' : '') + '">'
                + transformTypeLabel(t) + '</span>'
            + '<span class="sum-title">' + AC.esc(t.name || 'unnamed') + '</span>'
            + '<span class="sum-btns">'
                + (i > 0 ? move(-1, 'Earlier', '↑') : '')
                + (i < count - 1 ? move(1, 'Later', '↓') : '')
                + '<button class="icon-btn" onclick="event.stopPropagation();removeTransform(' + i + ')" title="Remove">×</button>'
            + '</span>'
        + '</div>'
        + (t.description ? '<div class="sum-line">' + AC.esc(t.description) + '</div>' : '')
        + (xml || !t.jsonataRef ? ''
            : '<div class="sum-line">shared · <b>' + AC.esc(t.jsonataRef) + '</b>'
                + (sharedJsonata(t.jsonataRef) ? '' : ' <span style="color:#bf2600">(not in the library)</span>')
                + '</div>')
        + (xml ? '' : '<code class="sum-expr">'
            + AC.esc(oneLine(transformExpression(t))
                || (t.jsonataRef ? 'the library has no expression under that name' : 'no expression yet'))
            + '</code>')
        + '<div class="sum-line">' + (users.length
            ? '<span>chained by ' + users.length + ' action' + (users.length > 1 ? 's' : '') + '</span>'
            : '<span class="muted">not chained by anything yet</span>') + '</div>'
        + '</div>';
}

/** A multi-line expression as the single line a card has room for. */
function oneLine(text) {
    const flat = String(text || '').replace(/\s+/g, ' ').trim();
    return flat.length > 120 ? flat.slice(0, 119) + '…' : flat;
}

function addTransform() {
    page.transforms = page.transforms || [];
    page.transforms.push({ name: 'transform' + (page.transforms.length + 1), type: 'JSONATA',
                           expression: '', description: '', jsonataRef: null });
    renderProps();
    // Straight into the editor: a transform is its expression, and an empty one has nothing to
    // show on a card anyway.
    openTransformEditor(page.transforms.length - 1);
}

/**
 * A step that runs a shared expression, added already pointing at the library. The same dialog
 * as any other step — it just opens on the half of it that names one, since somebody who pressed
 * "+ Shared" has already said which half they meant.
 */
function addSharedTransform() {
    page.transforms = page.transforms || [];
    // An empty ref rather than none: empty is "shared, not yet picked", which is what opens the
    // dialog on the library half. Pre-picked only when there is one thing it could mean.
    page.transforms.push({ name: 'transform' + (page.transforms.length + 1), type: 'JSONATA',
                           expression: '', description: '',
                           jsonataRef: jsonataLibrary.length === 1 ? jsonataLibrary[0].name : '' });
    renderProps();
    openTransformEditor(page.transforms.length - 1);
}

/**
 * Renaming takes the chains that name it along, so a step can be renamed after it has been wired
 * up. Without that every action pointing at the old name would quietly drop that step — a page
 * that still saves and still runs, just not as designed.
 */
function renameTransform(previous, next) {
    if (!previous || previous === next) return;
    allActions().forEach(a => [a].concat(a.extraBindings || []).forEach(b =>
        b.transformNames = (b.transformNames || []).map(n => n === previous ? next : n)));
}

function moveTransform(index, delta) {
    const target = index + delta;
    if (target < 0 || target >= page.transforms.length) return;
    [page.transforms[index], page.transforms[target]] = [page.transforms[target], page.transforms[index]];
    renderProps();
}

function removeTransform(index) {
    const [removed] = page.transforms.splice(index, 1);
    allActions().forEach(a => [a].concat(a.extraBindings || []).forEach(b =>
        b.transformNames = (b.transformNames || []).filter(n => n !== removed.name)));
    renderProps();
}

// ── Editing one action or transform ──────────────────────────────────────
// Both libraries list their contents as cards and open the thing itself over the page. The
// properties panel is 330px wide, which is a fine width for "which of these did I mean" and a
// hopeless one for a JSONata expression or a map of JSON inputs — the two fields anyone actually
// comes here to write.
//
// The dialog edits a copy, so Cancel is a real cancel: the panel behind it goes on showing the
// action as it was until Save says otherwise. That also makes the transform rename safe to do at
// the end, in one move, rather than following every keystroke through every chain that names it.

/** Mutators aimed at the working copy. No move or remove: inside the dialog there is no list. */
const EDITOR_FNS = { set: 'setDraft', move: '', remove: '', inputs: 'setDraftInputs',
                     inputVar: 'setDraftInputVar', redraw: 'renderEditor',
                     source: 'setDraftSource', chain: 'chainDraft', kind: 'setDraftKind',
                     rows: 'rowListDraft', binding: 'bindingDraft' };

function cloneValue(value) { return JSON.parse(JSON.stringify(value)); }

function openPageActionEditor(index)    { openActionEditor('page', index, null); }
function openControlActionEditor(index) { openActionEditor('control', index, selectedId); }

function openActionEditor(scope, index, controlId) {
    const list = scope === 'page' ? (page.actions || []) : ((findControl(controlId) || {}).actions || []);
    if (!list[index]) return;
    editor = { kind: 'action', scope: scope, index: index, controlId: controlId, draft: cloneValue(list[index]) };
    renderEditor();
}

function openTransformEditor(index) {
    const transform = (page.transforms || [])[index];
    if (!transform) return;
    editor = { kind: 'transform', index: index, draft: cloneValue(transform) };
    renderEditor();
}

function renderEditor() {
    const host = document.getElementById('editorHost');
    if (!editor) { host.innerHTML = ''; return; }

    const isCopy = editor.kind === 'copy';
    const isToPage = editor.kind === 'topage';
    const isControls = editor.kind === 'controls';
    const isAction = editor.kind === 'action';
    const source = isCopy ? findControl(editor.sourceId) : null;
    const title = isCopy ? (source ? controlTitle(source) : 'nothing to copy')
        : isToPage || isControls ? (savedPageName || page.pageName || 'this page')
        : isAction ? (editor.draft.actionLabel || 'Untitled action')
        : (editor.draft.name || 'Untitled transform');
    const kind = isCopy ? 'Copy actions'
        : isToPage ? 'Copy to another page'
        : isControls ? 'Copy controls to another page'
        : isAction ? (editor.scope === 'page' ? 'Page action' : 'Action on this control')
        : 'Transform';
    const body = isCopy ? copyEditorBody()
        : isToPage ? pageCopyBody()
        : isControls ? controlCopyBody()
        : isAction ? actionCard(editor.draft, 0, 1, EDITOR_FNS)
        : transformEditorBody(editor.draft);

    host.innerHTML = '<div class="editor-modal">'
        + '<div class="editor-box">'
            + '<div class="editor-head">'
                + '<span class="editor-title">' + AC.esc(kind) + ' · ' + AC.esc(title) + '</span>'
                + '<button class="icon-btn" onclick="closeEditor()" title="Close without saving">×</button>'
            + '</div>'
            + '<div class="editor-body">' + body + '</div>'
            + '<div class="editor-foot">'
                + (isCopy
                    ? '<button class="primary" onclick="applyCopy()">Copy</button>'
                    : isToPage
                    ? '<button class="primary" onclick="applyPageCopy()">Copy</button>'
                    : isControls
                    ? '<button class="primary" onclick="applyControlCopy()">Copy</button>'
                    : '<button class="primary" onclick="saveEditor()">Save</button>')
                + '<button class="secondary" onclick="closeEditor()">Cancel</button>'
                + '<span id="editorStatus" class="status-bar"></span>'
            + '</div>'
        + '</div>'
    + '</div>';
}

/** The transform's own fields, written against the working copy the same way an action's are. */
function transformEditorBody(t) {
    const xml = t.type === 'XML2JSON';
    return '<div class="xform-card stack">'
        + field('Name', '<input type="text" value="' + AC.esc(t.name || '') + '" placeholder="flattenRows"'
            + ' oninput="setDraft(0, \'name\', this.value)">',
            'How an action names this step in its chain. Renaming it takes every chain that names it along.')
        + field('Does', '<select onchange="setDraft(0, \'type\', this.value)">'
            + '<option value="JSONATA"' + (xml ? '' : ' selected') + '>JSONata expression</option>'
            + '<option value="XML2JSON"' + (xml ? ' selected' : '') + '>XML &#8594; JSON</option>'
            + '</select>')
        + (xml
            ? '<span class="hint">Parses what it is handed as an XML document — elements become keys, repeats '
                + 'become arrays, attributes land under <code>@attributes</code> and text under <code>#text</code>. '
                + 'Nothing to write; it reads the body as it arrived, so it goes first in a chain.</span>'
            : expressionSourceFields(t))
        + field('Notes', '<input type="text" value="' + AC.esc(t.description || '') + '" placeholder="what it reshapes"'
            + ' oninput="setDraft(0, \'description\', this.value)">')
        + '</div>';
}

/**
 * Where a JSONata step's expression comes from — written here, or named in the shared library —
 * and the fields that go with whichever it is.
 *
 * <p>Asked as a choice rather than inferred from whether a name happens to be filled in, because
 * the two are genuinely different things to have decided: an expression written here belongs to
 * this page and changes when this page changes, while a shared one belongs to everybody and
 * changes under this page's feet, on purpose. Save as… moves an expression from the first to the
 * second in one step, which is the way nearly every shared expression starts life: written on the
 * page that first needed it, then wanted by a second page.
 */
function expressionSourceFields(t) {
    // Absent means "written here"; present but empty means "shared, not yet picked". The two
    // have to be told apart or a step switched to the library, before a name has been chosen
    // out of a library of many, would snap straight back to the other half of the dialog.
    const shared = t.jsonataRef !== null && t.jsonataRef !== undefined;
    const entry = shared ? sharedJsonata(t.jsonataRef) : null;

    return field('Expression from',
            '<select onchange="setTransformSource(this.value)">'
            + '<option value="page"' + (shared ? '' : ' selected') + '>Written on this page</option>'
            + '<option value="library"' + (shared ? ' selected' : '') + '>The shared JSONata library</option>'
            + '</select>')
        + (shared
            ? field('Shared expression', '<select onchange="setDraft(0, \'jsonataRef\', this.value)">'
                    + sharedJsonataOptions(t.jsonataRef) + '</select>',
                    'The library holds the expression; this page holds only the name. Correcting it in the library '
                        + 'corrects every page, use case and request that names it — which is the point of naming '
                        + 'it rather than pasting it.')
                + (entry
                    ? '<div class="form-group"><label>Which is</label>'
                        + '<textarea readonly spellcheck="false">' + AC.esc(entry.expression || '') + '</textarea>'
                        + '<span class="hint">' + (entry.description ? AC.esc(entry.description) + ' · ' : '')
                        + 'Edit it in the <a href="appjsonata.html#' + encodeURIComponent(t.jsonataRef)
                        + '" target="_blank">JSONata library</a>.</span></div>'
                    : '<span class="hint" style="color:#bf2600">The library has nothing under '
                        + (t.jsonataRef ? '"' + AC.esc(t.jsonataRef) + '"' : 'that name')
                        + '. This page will not save, and the step will not run, until it names one that is there.</span>')
            : field('Expression', '<textarea spellcheck="false" placeholder=\'data.items.{"id": id, "who": owner.name}\''
                    + ' oninput="setDraft(0, \'expression\', this.value)">' + AC.esc(t.expression || '') + '</textarea>',
                    'Evaluated over whatever the step before it produced. '
                        + '<code>${fieldName}</code> fills in a control\'s value before the expression is compiled — '
                        + '<code>data[id = "${orderId}"]</code> keeps the row the operator asked about. Write the quotes '
                        + 'yourself: the value goes in as it stands, which is what lets a number compare as a number. '
                        + 'Only the braced form is taken; <code>$sum</code>, <code>$map</code> and a bare <code>$</code> '
                        + 'stay JSONata\'s own.')
                + '<div class="form-group"><div class="toolbar">'
                    + '<button class="tool-btn" onclick="saveTransformToLibrary()">Save as&hellip;</button>'
                    + '<a class="hint" href="appjsonata.html" target="_blank">Open the JSONata library</a>'
                + '</div><span class="hint">Save as&hellip; puts this expression in the shared library under a name, '
                    + 'and turns this step into a reference to it — so the next page that wants the same reshaping '
                    + 'names it instead of copying it.</span></div>');
}

/**
 * Switching a step between its own expression and a shared one. The expression it had is kept on
 * the draft while the dialog is open, so changing your mind twice does not cost you what you
 * wrote; {@link #saveEditor} is what decides which of the two the saved step keeps.
 */
function setTransformSource(source) {
    if (!editor) return;
    if (source === 'library') {
        // Pre-selected when there is only one thing it could mean. With a library of many, the
        // picker opens empty rather than guessing, and the page will not save until it is
        // answered — which is better than saving a step pointing at whatever was alphabetically
        // first.
        editor.draft.jsonataRef = editor.draft.jsonataRef
            || (jsonataLibrary.length === 1 ? jsonataLibrary[0].name : '');
    } else {
        editor.draft.jsonataRef = null;
    }
    renderEditor();
}

/**
 * Save as… — this step's expression into the shared library, and this step turned into a
 * reference to it.
 *
 * <p>The expression is saved as it stands, <code>${field}</code> placeholders included: they are
 * filled in on the page that runs the step, so an expression that reads a control keeps reading
 * one wherever else it is named. The library page will not resolve them when it tries the
 * expression, and says so.
 */
async function saveTransformToLibrary() {
    if (!editor || editor.kind !== 'transform') return;
    const expression = (editor.draft.expression || '').trim();
    if (!expression) {
        AC.setStatus('editorStatus', 'There is no expression to save yet.', 'error');
        return;
    }

    const suggested = editor.draft.name || 'transform';
    const name = (prompt('Save this expression in the shared JSONata library as:', suggested) || '').trim();
    if (!name) return;

    if (sharedJsonata(name)
            && !confirm('"' + name + '" is already in the library. Replace what it holds?\n\n'
                + 'Everything else that names it will run this expression instead.')) return;

    try {
        const entry = { name: name, description: editor.draft.description || '', expression: expression,
                        sampleInput: (sharedJsonata(name) || {}).sampleInput || '' };
        if (sharedJsonata(name)) {
            await AC.api('PUT', '/jsonata/' + encodeURIComponent(name), entry);
        } else {
            await AC.api('POST', '/jsonata', entry);
        }
        await reloadJsonataLibrary();
        // The step becomes the reference. Its own copy goes, so there is one answer to "what does
        // this step run" — the library's — rather than two that will differ by next month.
        editor.draft.jsonataRef = name;
        editor.draft.expression = '';
        renderEditor();
        AC.setStatus('editorStatus', 'Saved to the library as "' + name
            + '". This step now references it.', 'ok');
    } catch (e) {
        AC.setStatus('editorStatus', 'Could not save it to the library: ' + e.message, 'error');
    }
}

/**
 * One field of the working copy. The index the action editor passes is ignored — there is one
 * draft — and only the fields that decide which other fields are asked for redraw the dialog,
 * since a text input redrawn on every keystroke takes the caret with it.
 */
function setDraft(index, name, value) {
    if (!editor) return;
    editor.draft[name] = value;
    dropDatasetColumns(editor.draft, name);
    if (editor.kind === 'action') {
        const fanOut = !!editor.draft.rowSourceControlId;
        dropUnusablePivot(editor.draft, fanOut && editor.draft.rowOutputMode === 'TABS');
        dropUnusableBindFilters(editor.draft, fanOut);
        dropUnusableAppend(editor.draft, fanOut && editor.draft.rowOutputMode === 'TABS');
    }
    // jsonataRef redraws with the rest: picking a shared expression changes what the dialog can
    // show of it, and a picker that leaves the previous one's text underneath is worse than one
    // that flickers.
    if (REDRAWING_FIELDS.includes(name) || name === 'type' || name === 'jsonataRef') renderEditor();
}

function setDraftInputs(index, text) {
    if (!editor) return;
    try {
        editor.draft.inputs = text.trim() ? JSON.parse(text) : {};
        AC.setStatus('editorStatus', '');
    } catch (e) {
        AC.setStatus('editorStatus', 'Inputs are not valid JSON yet: ' + e.message, 'error');
    }
}

function setDraftInputVar(index, name, what, value) {
    if (!editor) return;
    const a = editor.draft;
    if (applyInputVar(a, inputsKey(a, index, EDITOR_FNS), name, what, value)) renderEditor();
}

function setDraftSource(index, value) {
    if (!editor) return;
    editor.draft.source = value;
    editor.draft.keyValueGrid = value === 'METADATA';
    renderEditor();
}

function chainDraft(index, op, at, value) {
    if (!editor) return;
    chainSteps([editor.draft], 0, op, at, value);
    renderEditor();
}

/**
 * Puts the working copy back where it came from. A transform is checked first: an unnamed one
 * is unnameable by any chain, and two with one name make "which step does this action run"
 * unanswerable — both are refused by the catalog on save, and finding that out here rather than
 * at the end of the page is the whole reason to check.
 */
function saveEditor() {
    if (!editor) return;

    if (editor.kind === 'transform') {
        const name = (editor.draft.name || '').trim();
        if (!name) { AC.setStatus('editorStatus', 'A transform needs a name — that is how an action chains it.', 'error'); return; }
        if ((page.transforms || []).some((t, i) => i !== editor.index && t.name === name)) {
            AC.setStatus('editorStatus', 'Another transform is already called "' + name + '".', 'error');
            return;
        }
        const shared = (editor.draft.jsonataRef || '').trim();
        if (shared && editor.draft.type !== 'XML2JSON' && !sharedJsonata(shared)) {
            AC.setStatus('editorStatus', 'The library has nothing called "' + shared
                + '" — pick one that is there, or write the expression on this page.', 'error');
            return;
        }
        editor.draft.name = name;
        // One source of truth per step: a shared step keeps only the name, and a page one keeps
        // only its expression. Saved this way rather than left with both so nothing downstream
        // has to decide which of two expressions the step meant.
        editor.draft.jsonataRef = shared || null;
        if (shared) editor.draft.expression = '';
        renameTransform((page.transforms[editor.index] || {}).name, name);
        page.transforms[editor.index] = editor.draft;
    } else {
        const list = editor.scope === 'page' ? page.actions : ((findControl(editor.controlId) || {}).actions);
        if (!list || !list[editor.index]) { closeEditor(); return; }
        // The id is the library's handle on this action — every control that triggers it names
        // it by that — and the working copy carries it through untouched.
        list[editor.index] = editor.draft;
    }

    editor = null;
    renderEditor();
    renderAll();
}

function closeEditor() {
    editor = null;
    renderEditor();
    renderProps();
}

// Escape closes the dialog the same way Cancel does — the edits are a working copy, so nothing
// that was saved is at stake.
document.addEventListener('keydown', e => { if (e.key === 'Escape' && editor) closeEditor(); });
// The details panel closes the same way, and is checked second: the two are never both open,
// but if they ever were the one on top is the one Escape should take away.
document.addEventListener('keydown', e => { if (e.key === 'Escape' && techPanel) closeTechDetails(); });

// ── Copying what one control runs onto others ────────────────────────────
// Two buttons that run the same three calls against different inputs is the ordinary shape of
// one of these pages, and the second of them used to be built by writing all three out again.
// This takes what a control runs and puts it on any number of others.
//
// The two kinds of wiring are copied as what they are. An action written on the control is
// cloned, so tuning the copy afterwards leaves the original alone — that is what "its own"
// means. A page action is attached by id rather than duplicated: the library entry is the same
// entry wherever it is triggered from, which is the whole point of the library, and copying it
// would leave two entries to keep in step for no gain.

/** Whether there is anything on a control worth copying. */
function controlRuns(c) {
    return !!c && !!((c.actions || []).length || (c.actionIds || []).length);
}

/** Every control the dialog can copy from. */
function controlsWithActions() {
    return page.controls.filter(controlRuns);
}

/**
 * Opens the copy dialog. From a control's own Actions section everything that control runs is
 * ticked, since copying a button usually means copying all of it; from one action's card, that
 * action alone.
 *
 * <p>Opened on a control that runs nothing — the ordinary way to build the second button of a
 * pair — the dialog has to start somewhere it can copy from, so it starts at the first control
 * that has anything and ticks the control you came from as the destination. That way one button
 * in the Actions section answers both "copy this elsewhere" and "copy something here".
 */
function openCopyEditor(sourceId, actionIndex) {
    const asked = findControl(sourceId != null ? sourceId : selectedId);
    const source = controlRuns(asked) ? asked : (controlsWithActions()[0] || asked);
    if (!source) return;
    editor = {
        kind: 'copy',
        sourceId: source.controlId,
        indexes: actionIndex != null ? [actionIndex] : (source.actions || []).map((a, i) => i),
        actionIds: actionIndex != null ? [] : (source.actionIds || []).slice(),
        targets: asked && asked.controlId !== source.controlId && !TRIGGERLESS_TYPES.includes(asked.type)
                 ? [asked.controlId] : []
    };
    renderEditor();
}

function copyControlAction(index) { openCopyEditor(selectedId, index); }

/** Another source means another set of actions, so what was ticked cannot survive the switch. */
function setCopySource(controlId) {
    if (!editor) return;
    const source = findControl(controlId);
    if (!source) return;
    editor.sourceId = controlId;
    editor.indexes = (source.actions || []).map((a, i) => i);
    editor.actionIds = (source.actionIds || []).slice();
    // Copying a control onto itself would double what it runs, so it leaves the destinations.
    editor.targets = editor.targets.filter(id => id !== controlId);
    renderEditor();
}

// What is ticked to copy decides which destinations can take it, so those two redraw the dialog.
// A destination decides nothing else, and redrawing on one would only take the scroll position
// of a long list with it.

function toggleCopyAction(index, on) {
    if (!editor) return;
    editor.indexes = on ? editor.indexes.concat([index]) : editor.indexes.filter(i => i !== index);
    renderEditor();
}

function toggleCopyPageAction(actionId, on) {
    if (!editor) return;
    editor.actionIds = on ? editor.actionIds.concat([actionId])
                          : editor.actionIds.filter(id => id !== actionId);
    renderEditor();
}

function toggleCopyTarget(controlId, on) {
    if (!editor) return;
    editor.targets = on ? editor.targets.concat([controlId])
                        : editor.targets.filter(id => id !== controlId);
}

/** Where the copy is taken from, what of it, and which controls it goes onto. */
function copyEditorBody() {
    const source = findControl(editor.sourceId);
    const sources = controlsWithActions();
    const inline = source ? (source.actions || []) : [];
    const attached = source ? (source.actionIds || []) : [];
    const library = page.actions || [];

    let html = '<div class="stack mini">';

    html += field('From', '<select onchange="setCopySource(this.value)">'
        + sources.map(c => '<option value="' + AC.attr(c.controlId) + '"'
            + (c.controlId === editor.sourceId ? ' selected' : '') + '>'
            + AC.esc(controlTitle(c)) + ' (' + c.type + ')</option>').join('')
        + '</select>', 'Every control on the page that runs anything.');

    html += '<div class="props-section"><div class="props-title"><span>What To Copy</span></div>';
    if (!inline.length && !attached.length) {
        html += '<div class="empty-note">This control runs nothing.</div>';
    } else {
        html += '<div class="copy-list">'
            + inline.map((a, i) =>
                '<label class="inline-check"><input type="checkbox"'
                + (editor.indexes.includes(i) ? ' checked' : '')
                + ' onchange="toggleCopyAction(' + i + ', this.checked)"> '
                + '<span class="copy-name">' + AC.esc(a.actionLabel || ('Action ' + (i + 1))) + '</span>'
                + '<span class="badge">its own</span></label>').join('')
            + attached.map(id => {
                const a = library.find(x => x.actionId === id);
                return '<label class="inline-check"><input type="checkbox"'
                    + (editor.actionIds.includes(id) ? ' checked' : '')
                    + ' onchange="toggleCopyPageAction(\'' + AC.attr(id) + '\', this.checked)"> '
                    + '<span class="copy-name">' + AC.esc((a && a.actionLabel) || id) + '</span>'
                    + '<span class="badge auth">page action</span></label>';
            }).join('')
            + '</div>'
            + '<span class="hint">An action of the control&#39;s own is copied — a clone, so tuning one of them '
            + 'afterwards leaves the other alone. A page action is attached rather than duplicated: it is the '
            + 'same library entry wherever it runs from, so editing it once still changes it everywhere.</span>';
    }
    html += '</div>';

    // A control that is never triggered could not run any of this, so it is not offered at all;
    // one that is triggered but holds no actions of its own is, since page actions can still be
    // attached to it — and it says so rather than quietly taking half of what was ticked.
    const wantsOwn = editor.indexes.length > 0;
    const wantsPage = editor.actionIds.length > 0;
    const targets = page.controls.filter(c =>
        c.controlId !== editor.sourceId && !TRIGGERLESS_TYPES.includes(c.type));

    html += '<div class="props-section"><div class="props-title"><span>Onto</span></div>';
    if (!targets.length) {
        html += '<div class="empty-note">Nowhere to copy to yet — a grid, a label, a tab set and a hidden field '
             + 'are never triggered, so nothing can be run from them. Add another button, link or select.</div>';
    } else {
        html += '<div class="copy-list">' + targets.map(t => {
            const takesOwn = ACTION_TYPES.includes(t.type);
            const takesNothing = wantsOwn && !takesOwn && !wantsPage;
            const note = wantsOwn && !takesOwn
                ? 'a ' + t.type + ' holds no actions of its own' + (wantsPage ? ' — page actions only' : '')
                : '';
            return '<label class="inline-check' + (takesNothing ? ' off' : '') + '">'
                + '<input type="checkbox"' + (editor.targets.includes(t.controlId) ? ' checked' : '')
                + (takesNothing ? ' disabled' : '')
                + ' onchange="toggleCopyTarget(\'' + AC.attr(t.controlId) + '\', this.checked)"> '
                + '<span class="copy-name">' + AC.esc(controlTitle(t)) + '</span>'
                + '<span class="type-badge ' + AC.esc(t.type) + '">' + AC.esc(t.type) + '</span>'
                + (note ? '<span class="copy-note">' + AC.esc(note) + '</span>' : '')
                + '</label>';
        }).join('') + '</div>'
            + '<span class="hint">Appended to whatever the control already runs, after what is there, so nothing '
            + 'it was already doing is lost.</span>';
    }

    return html + '</div></div>';
}

/**
 * Does the copy. A control that could not take part of what was ticked is not silently passed
 * over: the status bar says how many were skipped and why, since "I ticked six and four arrived"
 * with no explanation is the kind of thing that gets blamed on the save.
 */
function applyCopy() {
    if (!editor) return;
    const source = findControl(editor.sourceId);
    if (!source) { closeEditor(); return; }

    const actions = (source.actions || []).filter((a, i) => editor.indexes.includes(i));
    const ids = (source.actionIds || []).filter(id => editor.actionIds.includes(id));
    if (!actions.length && !ids.length) {
        AC.setStatus('editorStatus', 'Nothing ticked to copy.', 'error');
        return;
    }
    const targets = editor.targets.map(id => findControl(id))
        .filter(t => t && t.controlId !== source.controlId && !TRIGGERLESS_TYPES.includes(t.type));
    if (!targets.length) {
        AC.setStatus('editorStatus', 'Nothing ticked to copy onto.', 'error');
        return;
    }

    let copied = 0, linked = 0, skipped = 0;
    const touched = new Set();
    targets.forEach(t => {
        if (actions.length) {
            if (ACTION_TYPES.includes(t.type)) {
                t.actions = (t.actions || []).concat(copiesOf(actions));
                copied += actions.length;
                touched.add(t.controlId);
            } else {
                skipped += actions.length;
            }
        }
        if (ids.length) {
            // Attaching the same action twice would run it twice, so an id the control already
            // triggers is left where it is rather than appended again.
            const before = (t.actionIds || []).length;
            t.actionIds = (t.actionIds || []).concat(ids).filter((id, i, all) => all.indexOf(id) === i);
            linked += t.actionIds.length - before;
            if (t.actionIds.length > before) touched.add(t.controlId);
        }
    });

    const many = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
    const parts = [];
    if (copied) parts.push(many(copied, 'action') + ' copied');
    if (linked) parts.push(many(linked, 'page action') + ' attached');
    let message = parts.length
        ? parts.join(', ') + ' onto ' + many(touched.size, 'control') + '.'
        : 'Nothing changed — everything ticked was already there.';
    // Not put through many(): what was skipped is a count of copies that did not happen, and there is no
    // word for that which pluralises without reading worse than the bare number does.
    if (skipped) message += ' ' + skipped + ' skipped: only a button or a link carries actions of its own.';

    editor = null;
    renderEditor();
    renderAll();
    AC.setStatus('statusBar', message, parts.length ? 'ok' : '');
}

/**
 * A set of inline actions as copies fit to live on another control. Each takes a fresh id — an
 * action is waited for by id, and two carrying one id would be one action as far as any
 * dependency could tell — and every wait among them is moved onto the copy rather than left
 * pointing back at the original, so the pair that were ordered against each other still are.
 *
 * <p>A wait on a page action is left alone: the library entry is the same entry wherever it is
 * triggered from, so naming it still means what it meant. A wait on something that was not
 * ticked is cleared instead of carried over — the copy is going to a control that does not run
 * it, and a wait nothing can honour is worse than none.
 */
function copiesOf(actions) {
    const copies = actions.map(cloneValue);
    const remap = new Map();
    copies.forEach((copy, i) => { remap.set(actions[i].actionId, copy.actionId = newActionId()); });
    copies.forEach(copy => {
        const waited = copy.dependsOnActionId;
        if (!waited || isPageAction(waited)) return;
        copy.dependsOnActionId = remap.get(waited) || '';
    });
    return copies;
}


// ── Copying an action onto another page ─────────────────────────────────
// The same call written on two pages is as ordinary as the same call written on two buttons, and
// until now the only way across was to open the other page and type the whole action out again.
//
// What crosses is a copy, never a reference: a page is stored whole, so there is no library
// spanning two of them for an action to be shared out of. Everything the action names has to
// cross with it or be let go of, and which of the two happened is said afterwards rather than
// left to be found out later:
//
//   · the transforms it chains come along, unless the destination already has one by that name,
//     in which case the one already there is what the copy will run;
//   · the control it fills is looked for on the destination by field name and then by label,
//     since a control id is minted per page and names nothing on another one. Found, the copy
//     targets it; not found, the copy binds nowhere and says so;
//   · a wait on another action crossing at the same time is kept, pointing at that action's copy.
//     A wait on anything else is dropped — what it named is not over there to be waited for.
//
// Copies land in the destination's page-action library rather than on a control, because the
// control they came from is not there either. Attaching them is the one thing left to do by hand.

/** Every action on the page paired with where it lives, for a list that has to name both. */
function actionsWithOrigin() {
    const list = (page.actions || []).map(a => ({ action: a, origin: 'page action', page: true }));
    page.controls.forEach(c => (c.actions || []).forEach(a =>
        list.push({ action: a, origin: 'on ' + controlTitle(c), page: false })));
    return list.filter(e => e.action.actionId);
}

/** The pages this one can copy onto: every other page in the catalog. */
function otherPages() {
    return pages.map(p => p.pageName).filter(name => name && name !== savedPageName);
}

/**
 * Opens the cross-page copy dialog with the action it was opened from ticked — or, from the
 * library header, with nothing ticked, since "copy something to another page" has no one action
 * in mind until one is picked.
 */
function openPageCopyEditor(actionId) {
    editor = { kind: 'topage', actionIds: actionId ? [actionId] : [], targets: [] };
    renderEditor();
}

function copyControlActionToPage(index) {
    const a = ((findControl(selectedId) || {}).actions || [])[index];
    openPageCopyEditor(a && a.actionId);
}

function copyPageActionToPage(index) {
    const a = (page.actions || [])[index];
    openPageCopyEditor(a && a.actionId);
}

function togglePageCopyAction(actionId, on) {
    if (!editor) return;
    editor.actionIds = on ? editor.actionIds.concat([actionId])
                          : editor.actionIds.filter(id => id !== actionId);
    renderEditor();
}

function togglePageCopyTarget(pageName, on) {
    if (!editor) return;
    editor.targets = on ? editor.targets.concat([pageName])
                        : editor.targets.filter(name => name !== pageName);
}

/** What is being copied, and onto which pages. */
function pageCopyBody() {
    const entries = actionsWithOrigin();
    const destinations = otherPages();

    let html = '<div class="stack mini">';

    html += '<div class="props-section"><div class="props-title"><span>What To Copy</span></div>';
    if (!entries.length) {
        html += '<div class="empty-note">This page has no actions to copy.</div>';
    } else {
        html += '<div class="copy-list">' + entries.map(e => {
            // An action naming no instance is refused by whichever page it is saved on, so it is
            // said here rather than arriving as a failure after the round trip. A performance
            // action is the exception and not really one: it names no instance because it calls
            // nothing, so there is nothing missing from it.
            // A dataset action is the other exception, and for the same reason: it names a dataset
            // rather than an instance, because it calls nothing.
            const half = !e.action.appUseCaseInstanceId
                && !isPerformanceAction(e.action) && !isDatasetAction(e.action);
            return '<label class="inline-check"><input type="checkbox"'
                + (editor.actionIds.includes(e.action.actionId) ? ' checked' : '')
                + ' onchange="togglePageCopyAction(\'' + AC.attr(e.action.actionId) + '\', this.checked)"> '
                + '<span class="copy-name">' + AC.esc(e.action.actionLabel || 'Untitled action') + '</span>'
                + '<span class="badge' + (e.page ? ' auth' : '') + '">' + AC.esc(e.origin) + '</span>'
                + (half ? '<span class="copy-note">names no instance yet — the other page will refuse it</span>' : '')
                + '</label>';
        }).join('')
            + '</div>'
            + '<span class="hint">Copied as it stands in this editor, saved or not — what is on screen is what '
            + 'crosses. The transforms it chains cross with it; one the other page already has by that name is '
            + 'left alone and used as it is.</span>';
    }
    html += '</div>';

    html += '<div class="props-section"><div class="props-title"><span>Onto</span></div>';
    if (!destinations.length) {
        html += '<div class="empty-note">There is no other page to copy onto yet.</div>';
    } else {
        html += '<div class="copy-list">' + destinations.map(name =>
            '<label class="inline-check"><input type="checkbox"'
            + (editor.targets.includes(name) ? ' checked' : '')
            + ' onchange="togglePageCopyTarget(\'' + AC.attr(name) + '\', this.checked)"> '
            + '<span class="copy-name">' + AC.esc(name) + '</span></label>').join('')
            + '</div>'
            + '<span class="hint">Each one is loaded, added to and saved on the spot; the page you are editing is '
            + 'not saved by this and is left exactly as it is. Copies land in the destination&#39;s Page Actions '
            + 'library attached to nothing, so open that page to put them on a control. A control the action fills '
            + 'is looked for over there by field name, then by label — if it is not there the copy binds nowhere '
            + 'until you point it somewhere.</span>';
    }

    return html + '</div></div>';
}

// ── Copying controls onto another page ──────────────────────────────────
// The other half of the same problem: a screen someone has built — the two inputs, the button,
// the grid the answer lands in, and everything wired between them — is routinely the starting
// point for the next screen, and copying it used to mean laying the whole thing out again.
//
// A control crosses with what it runs. An action written on it comes along as a copy; a page
// action it triggers is copied into the destination's library and attached to the copy there,
// since there is no library spanning two pages for one entry to be shared out of. Everything
// those actions name is followed one step further: the transforms they chain cross too, and
// every reference between the copied controls — what an action fills, what it fans out over,
// what an assignment writes into, which grids a tab set holds — is repointed at the copy rather
// than at an id that means nothing over there.
//
// Two things are deliberately not copies. A value control whose field name the destination
// already uses for a control of the same type is not copied at all: that page already has the
// box, the templates coming across already say ${thatName}, and a second one would be two boxes
// answering to one name — which is what the destination's own save refuses. And a reference to
// something that did not cross and is not over there is cleared rather than guessed at.

/** Everything the copy dialog can take: every control on the page. */
function copyableControls() {
    return page.controls;
}

/**
 * Opens the control copy dialog, with the control it was opened from ticked — or, from the
 * panel header, with nothing ticked, since "copy controls to another page" has no one control in
 * mind until one is picked.
 */
function openControlCopyEditor(controlId) {
    editor = { kind: 'controls', controlIds: controlId ? [controlId] : [], targets: [] };
    renderEditor();
}

function toggleControlCopy(controlId, on) {
    if (!editor) return;
    editor.controlIds = on ? editor.controlIds.concat([controlId])
                           : editor.controlIds.filter(id => id !== controlId);
    renderEditor();
}

function toggleControlCopyTarget(pageName, on) {
    if (!editor) return;
    editor.targets = on ? editor.targets.concat([pageName])
                        : editor.targets.filter(name => name !== pageName);
}

/**
 * The controls that will actually cross, given what was ticked. A container brings what it holds
 * with it whether or not that was ticked: a tab set is its tabs and a panel is what is in it, and
 * one arriving empty because its contents were left behind is not the control that was copied.
 *
 * <p>Followed all the way down rather than one level, since a container may hold a container: a
 * tab holding a panel of four fields has to bring the panel and the four fields, or the tab
 * arrives as a name over nothing.
 */
function copySelection(ids) {
    const wanted = new Set(ids);
    // A pie with grids brings the tab set its grids go into, and so — below — that set's own grids.
    page.controls.forEach(c => {
        if (c.type === 'piegrid' && wanted.has(c.controlId) && c.tabsControlId) wanted.add(c.tabsControlId);
    });
    // Repeated until nothing new is found, which is what follows the nesting however deep it goes
    // without needing to know how deep that is. It settles, because the page has finitely many
    // controls and a container cannot arrive back at itself.
    for (let added = true; added; ) {
        added = false;
        page.controls.forEach(c => {
            if (!isContainer(c.type) || !wanted.has(c.controlId)) return;
            childIdsOf(c).forEach(id => { if (!wanted.has(id)) { wanted.add(id); added = true; } });
        });
    }
    return page.controls.filter(c => wanted.has(c.controlId));
}

/** What is being copied, which of it is being brought along, and onto which pages. */
function controlCopyBody() {
    const picked = copySelection(editor.controlIds);
    const pickedIds = new Set(picked.map(c => c.controlId));
    const destinations = otherPages();

    let html = '<div class="stack mini">';

    html += '<div class="props-section"><div class="props-title"><span>What To Copy</span></div>';
    if (!page.controls.length) {
        html += '<div class="empty-note">This page has no controls to copy.</div>';
    } else {
        html += '<div class="copy-list">' + page.controls.map(c => {
            const ticked = editor.controlIds.includes(c.controlId);
            // A control held by a tab set or a panel that is itself crossing comes along
            // regardless, and says so rather than looking as though it had been left out.
            const dragged = !ticked && pickedIds.has(c.controlId);
            const holder = heldBy(c.controlId);
            return '<label class="inline-check' + (dragged ? ' off' : '') + '">'
                + '<input type="checkbox"' + (ticked || dragged ? ' checked' : '')
                + (dragged ? ' disabled' : '')
                + ' onchange="toggleControlCopy(\'' + AC.attr(c.controlId) + '\', this.checked)"> '
                + '<span class="copy-name">' + AC.esc(controlTitle(c)) + '</span>'
                + '<span class="type-badge ' + AC.esc(c.type) + '">' + AC.esc(c.type) + '</span>'
                + (dragged ? '<span class="copy-note">comes with ' + AC.esc(controlTitle(holder)) + '</span>'
                    : controlRuns(c) ? '<span class="copy-note">runs '
                        + ((c.actions || []).length + (c.actionIds || []).length) + '</span>' : '')
                + '</label>';
        }).join('') + '</div>'
            + '<span class="hint">Copied as it stands in this editor, saved or not. What each control runs crosses '
            + 'with it: an action written on the control as its own copy, a page action it triggers as a new entry '
            + 'in the other page&#39;s library, attached to the copy. The transforms those actions chain cross too; '
            + 'one the other page already has by that name is left alone and used as it is.</span>';
    }
    html += '</div>';

    html += '<div class="props-section"><div class="props-title"><span>Onto</span></div>';
    if (!destinations.length) {
        html += '<div class="empty-note">There is no other page to copy onto yet.</div>';
    } else {
        html += '<div class="copy-list">' + destinations.map(name =>
            '<label class="inline-check"><input type="checkbox"'
            + (editor.targets.includes(name) ? ' checked' : '')
            + ' onchange="toggleControlCopyTarget(\'' + AC.attr(name) + '\', this.checked)"> '
            + '<span class="copy-name">' + AC.esc(name) + '</span></label>').join('')
            + '</div>'
            + '<span class="hint">Each one is loaded, added to and saved on the spot; the page you are editing is not '
            + 'saved by this and is left exactly as it is. The copies keep their layout relative to each other and '
            + 'land below whatever the destination already has, so nothing over there is covered up. A field name '
            + 'that page already uses is not copied a second time — the copies wire up to the control it already '
            + 'has, which is what their <code>${name}</code> templates were going to mean over there anyway.</span>';
    }

    return html + '</div></div>';
}

/**
 * Puts copies of these controls, and of everything they run, onto another page. Mutates the
 * destination page object; the caller saves it. Hands back what happened, since a copy that
 * quietly lost a target or a step of its chain is noticed a week later, by which time nobody
 * remembers that it was copied at all.
 */
function graftControls(controls, target) {
    target.controls   = target.controls   || [];
    target.actions    = target.actions    || [];
    target.transforms = target.transforms || [];

    const report = { added: 0, reused: [], actions: 0, attached: 0, brought: 0, dropped: 0, unbound: [] };
    const usedControlIds = new Set(target.controls.map(c => c.controlId));
    const usedIds  = new Set(actionIdsOn(target));
    const takenLabels = target.actions.map(a => a.actionLabel || '');
    const alreadyThere = new Set(target.transforms.map(t => t.name));
    // Old control id over here to the id that answers for it over there — whether that is a copy
    // this run made or a control the destination already had.
    const idMap = new Map();
    const copies = [];

    // Laid out directly below whatever is already on the destination, keeping the block's own
    // shape: two controls side by side here are side by side there, a row apart here is a row
    // apart there. The whole block moves by one number, so it lands flush under what is there
    // rather than either on top of it or three rows past it — and onto an empty page it lands at
    // the top, which is where a page that is only this copy should start.
    //
    // A control inside a tab set or a panel is not counted: it has no placement on the layout
    // while it is in there, and the row it is remembering could be anywhere.
    const occupied = target.controls.filter(c => !target.controls.some(t =>
        isContainer(t.type) && (t.tabControlIds || []).concat(t.panelControlIds || []).includes(c.controlId)));
    const floor = occupied.reduce((low, c) => Math.max(low, (c.row || 0) + rowSpanOf(c)), 0);
    const top = controls.reduce((high, c) => Math.min(high, c.row || 0), Number.MAX_SAFE_INTEGER);
    const shift = controls.length ? floor - top : 0;

    controls.forEach(source => {
        // A value control the destination already has under this name is that control: the
        // templates crossing with it already say ${name}, and a second one carrying the name
        // would be exactly what that page's own save refuses.
        const existing = VALUE_TYPES.includes(source.type) && (source.fieldName || '').trim()
            ? target.controls.find(c => c.type === source.type
                    && (c.fieldName || '').trim() === (source.fieldName || '').trim())
            : null;
        if (existing) {
            idMap.set(source.controlId, existing.controlId);
            report.reused.push(source.fieldName);
            return;
        }
        const copy = cloneValue(source);
        let id = 'c-' + Math.random().toString(36).substring(2, 10);
        while (usedControlIds.has(id)) id = 'c-' + Math.random().toString(36).substring(2, 10);
        usedControlIds.add(id);
        idMap.set(source.controlId, copy.controlId = id);
        copy.row = (copy.row || 0) + shift;
        // A field name the destination uses for a control of another type has to give way: two
        // controls of one name is what its save refuses, whatever their types.
        if (VALUE_TYPES.includes(copy.type) && (copy.fieldName || '').trim()
                && target.controls.some(c => (c.fieldName || '').trim() === copy.fieldName.trim())) {
            copy.fieldName = freeFieldName(copy.fieldName, target);
        }
        copies.push(copy);
        report.added++;
    });

    /** A page action this copy triggers, copied into the destination's library once. */
    const pageActionMap = new Map();
    const bringPageAction = actionId => {
        if (pageActionMap.has(actionId)) return pageActionMap.get(actionId);
        const original = (page.actions || []).find(a => a.actionId === actionId);
        if (!original) return null;
        const copy = cloneValue(original);
        let id = newActionId();
        while (usedIds.has(id)) id = newActionId();
        usedIds.add(id);
        copy.actionId = id;
        copy.actionLabel = uniqueLabel(original.actionLabel || 'Untitled action', takenLabels);
        takenLabels.push(copy.actionLabel);
        target.actions.push(copy);
        pageActionMap.set(actionId, copy);
        report.attached++;
        return copy;
    };

    // Every page action any copied control triggers — from its own list and from its grid's
    // clickable columns — and every action written on one, all brought across before anything is
    // repointed: the repointing resolves names against this set, so the set has to be whole
    // first, or an action reached only from a column would be renumbered after it was read.
    copies.forEach(copy => {
        copy.actionIds = (copy.actionIds || []).map(id => {
            const brought = bringPageAction(id);
            return brought ? brought.actionId : null;
        }).filter(Boolean);
        (copy.columnLinks || []).forEach(link => {
            link.actionIds = (link.actionIds || []).map(id => {
                const brought = bringPageAction(id);
                return brought ? brought.actionId : null;
            }).filter(Boolean);
        });
        if (copy.rowClick) {
            copy.rowClick.actionIds = (copy.rowClick.actionIds || []).map(id => {
                const brought = bringPageAction(id);
                return brought ? brought.actionId : null;
            }).filter(Boolean);
        }
        // And a multi-button's menu entries, which name page actions exactly as the three above
        // do: a menu that crossed without them would arrive as a list of entries that run nothing,
        // which the other page's save refuses.
        (copy.menuOptions || []).forEach(o => {
            o.actionIds = (o.actionIds || []).map(id => {
                const brought = bringPageAction(id);
                return brought ? brought.actionId : null;
            }).filter(Boolean);
        });
        (copy.actions || []).forEach(a => {
            let id = newActionId();
            while (usedIds.has(id)) id = newActionId();
            usedIds.add(id);
            // Keyed by the original id so a wait written between two of this control's own
            // actions still names the right one after both have been renumbered.
            pageActionMap.set('inline:' + a.actionId, { actionId: id });
            a.actionId = id;
            report.actions++;
        });
    });

    /** What an old action id means over there, whichever kind of action it was. */
    const actionIdFor = old => {
        if (!old) return '';
        const inline = pageActionMap.get('inline:' + old);
        if (inline) return inline.actionId;
        const library = pageActionMap.get(old);
        return library ? library.actionId : '';
    };

    /** What an old control id means over there — a copy, or a control that was already there. */
    const controlIdFor = old => idMap.get(old) || '';

    const repoint = (a, owner) => {
        a.dependsOnActionId = actionIdFor(a.dependsOnActionId);
        const bringChain = chain => (chain || []).map(step => {
            if (alreadyThere.has(step) || target.transforms.some(t => t.name === step)) return step;
            const definition = (page.transforms || []).find(t => t.name === step);
            if (!definition) { report.dropped++; return null; }
            target.transforms.push(cloneValue(definition));
            report.brought++;
            return step;
        }).filter(Boolean);
        a.transformNames = bringChain(a.transformNames);

        const wanted = a.targetControlId;
        if (wanted && wanted !== NEW_GRID) {
            const found = controlIdFor(wanted) || matchedIdOn(findControl(wanted), target);
            a.targetControlId = found;
            if (!found) report.unbound.push(a.actionLabel || owner);
        }
        // A further target with nowhere to go over there is dropped: it is nothing but its control.
        a.extraBindings = (a.extraBindings || []).map(b => {
            b.transformNames = bringChain(b.transformNames);
            if (b.targetControlId === NEW_GRID) return b;
            const found = controlIdFor(b.targetControlId) || matchedIdOn(findControl(b.targetControlId), target);
            if (!found) { report.unbound.push(a.actionLabel || owner); return null; }
            b.targetControlId = found;
            return b;
        }).filter(Boolean);
        // A fan-out reads its rows from a grid, which has to be one over there — and if it is
        // not, the action runs once against the page rather than pointing at nothing.
        if (a.rowSourceControlId) {
            const found = controlIdFor(a.rowSourceControlId) || matchedIdOn(findControl(a.rowSourceControlId), target);
            a.rowSourceControlId = found;
            if (!found) { a.rowOutputMode = 'ROWS'; report.unbound.push(a.actionLabel || owner); }
        }
        if (!repointGridLookups(a, id => controlIdFor(id) || matchedIdOn(findControl(id), target))) {
            report.unbound.push(a.actionLabel || owner);
        }
    };

    copies.forEach(copy => (copy.actions || []).forEach(a => repoint(a, controlTitle(copy))));
    pageActionMap.forEach((brought, key) => {
        if (String(key).startsWith('inline:')) return;
        repoint(brought, brought.actionLabel || 'a page action');
    });

    copies.forEach(copy => {
        // What this control writes into: kept where the destination has somewhere to write, and
        // dropped where it has not, since an assignment with no target is nothing at all.
        copy.assignments = (copy.assignments || []).map(assignment => {
            const found = controlIdFor(assignment.targetControlId)
                || matchedIdOn(findControl(assignment.targetControlId), target);
            if (!found) return null;
            assignment.targetControlId = found;
            return assignment;
        }).filter(Boolean);

        // What a grid's clickable columns write into. What they run was brought across with
        // everything else the copies trigger, above.
        (copy.columnLinks || []).forEach(link => {
            link.assignments = (link.assignments || []).map(assignment => {
                const found = controlIdFor(assignment.targetControlId)
                    || matchedIdOn(findControl(assignment.targetControlId), target);
                if (!found) return null;
                assignment.targetControlId = found;
                return assignment;
            }).filter(Boolean);
        });
        // The same again for what its clickable rows write into.
        if (copy.rowClick) {
            copy.rowClick.assignments = (copy.rowClick.assignments || []).map(assignment => {
                const found = controlIdFor(assignment.targetControlId)
                    || matchedIdOn(findControl(assignment.targetControlId), target);
                if (!found) return null;
                assignment.targetControlId = found;
                return assignment;
            }).filter(Boolean);
            // A row click that crossed over with nothing left to set and nothing to run would be
            // refused on save as a click that does nothing, so it goes rather than travels broken.
            if (!copy.rowClick.assignments.length && !(copy.rowClick.actionIds || []).length) copy.rowClick = null;
        }

        // A tab set holds the grids that crossed with it; one that did not is not a tab.
        if (copy.type === 'tabs') {
            copy.tabControlIds = (copy.tabControlIds || []).map(controlIdFor).filter(Boolean);
            copy.defaultTabControlId = controlIdFor(copy.defaultTabControlId);
            if (!copy.tabControlIds.includes(copy.defaultTabControlId)) copy.defaultTabControlId = '';
        }
        // And a panel holds what crossed with it, for the same reason and in the same way. The
        // contents always do cross — see #copySelection — so this is the renumbering rather than
        // a filter, and the filter is only there for the same reason the tab set's is.
        if (copy.type === 'panel') {
            copy.panelControlIds = (copy.panelControlIds || []).map(controlIdFor).filter(Boolean);
        }
        // A pie with grids fills the tab set that crossed with it, or one of the same name over there.
        if (copy.type === 'piegrid' && copy.tabsControlId) {
            copy.tabsControlId = controlIdFor(copy.tabsControlId)
                || matchedIdOn(findControl(copy.tabsControlId), target);
            if (!copy.tabsControlId) report.unbound.push(controlTitle(copy));
        }
        // A chart drawn from a grid draws from the one that crossed with it, or one of the same name.
        if (drawsFromGrid(copy.type) && copy.sourceGridControlId) {
            copy.sourceGridControlId = controlIdFor(copy.sourceGridControlId)
                || matchedIdOn(findControl(copy.sourceGridControlId), target) || '';
            if (!copy.sourceGridControlId) report.unbound.push(controlTitle(copy));
        }
    });

    target.controls = target.controls.concat(copies);
    return report;
}

/**
 * A field name nothing on the destination is using yet, numbered from 2. Only reached where the
 * destination has a control of that name and another type, which is rare and worth surviving:
 * the alternative is refusing the copy over a name clash between two unrelated things.
 */
function freeFieldName(name, target) {
    const base = (name || 'field').trim();
    let n = 2;
    while (target.controls.some(c => (c.fieldName || '').trim() === base + n)) n++;
    return base + n;
}

/**
 * The id of the control on another page that answers to the same name as this one, or nothing.
 * Wider than {@link #matchingControl}, which is about where a response may land; this is asked
 * about assignment targets and fan-out sources as well, where the question is only "is the same
 * control over there".
 */
/**
 * Points an action's lookups into a grid — on the action and on each of its further targets — at
 * whatever `resolve` makes of the grid's id, dropping a lookup column whose grid has no counterpart:
 * the catalog refuses a lookup into a grid that is not there. Also what a deleted grid goes through,
 * with a resolver that finds nothing for it.
 *
 * @return false when any lookup column was dropped
 */
function repointGridLookups(action, resolve) {
    let kept = true;
    const repoint = holder => {
        holder.enrichColumns = (holder.enrichColumns || []).filter(column => {
            if (!GRID_LOOKUP_KINDS.includes(enrichKind(column)) || !column.gridControlId) return true;
            const found = resolve(column.gridControlId);
            if (!found) { kept = false; return false; }
            column.gridControlId = found;
            return true;
        });
    };
    repoint(action);
    (action.extraBindings || []).forEach(repoint);
    return kept;
}

function matchedIdOn(source, target) {
    if (!source) return '';
    const key  = c => (c.fieldName || '').trim().toLowerCase();
    const name = c => (c.label || '').trim().toLowerCase();
    const controls = (target.controls || []).filter(c => c.type === source.type);
    const found = (key(source)  && controls.find(c => key(c)  === key(source)))
               || (name(source) && controls.find(c => name(c) === name(source)));
    return found ? found.controlId : '';
}

/**
 * Does the control copy: one page loaded, added to and saved at a time, so a destination that
 * refuses the save stops at itself rather than taking the rest of the run down with it.
 */
async function applyControlCopy() {
    if (!editor || editor.kind !== 'controls') return;

    const picked = copySelection(editor.controlIds);
    if (!picked.length)         { AC.setStatus('editorStatus', 'Nothing ticked to copy.', 'error'); return; }
    if (!editor.targets.length) { AC.setStatus('editorStatus', 'Nothing ticked to copy onto.', 'error'); return; }

    const destinations = editor.targets.slice();
    AC.setStatus('editorStatus', 'Copying onto ' + destinations.length
        + ' page' + (destinations.length > 1 ? 's' : '') + '…');

    const done = [], failed = [], reused = new Set(), unbound = [];
    let added = 0, actions = 0, attached = 0, brought = 0, dropped = 0;
    for (const name of destinations) {
        try {
            const target = await AC.api('GET', '/appcatalog/pages/' + encodeURIComponent(name));
            const report = graftControls(picked, target);
            await AC.api('PUT', '/appcatalog/pages/' + encodeURIComponent(name), target);
            done.push(name);
            added += report.added;
            actions += report.actions;
            attached += report.attached;
            brought += report.brought;
            dropped += report.dropped;
            report.reused.forEach(f => reused.add(f));
            if (report.unbound.length) unbound.push(name);
        } catch (e) {
            failed.push(name + ' — ' + e.message);
        }
    }

    const many = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
    let message = done.length ? many(added, 'control') + ' copied onto ' + done.join(', ') + '.' : '';
    if (actions)        message += ' ' + many(actions, 'action') + ' came with them.';
    if (attached)       message += ' ' + many(attached, 'page action') + ' added to the destination library.';
    if (brought)        message += ' ' + many(brought, 'transform') + ' carried across.';
    if (dropped)        message += ' ' + many(dropped, 'chained step') + ' dropped — not on this page either.';
    if (reused.size)    message += ' Wired up to the field'
        + (reused.size === 1 ? '' : 's') + ' already there: ' + [...reused].join(', ') + '.';
    if (unbound.length) message += ' On ' + unbound.join(', ') + ' something a copy pointed at was not over there, '
        + 'so it binds nowhere yet.';
    if (failed.length)  message += ' Failed: ' + failed.join('; ');

    if (!done.length) { AC.setStatus('editorStatus', message || 'Nothing was copied.', 'error'); return; }

    editor = null;
    renderEditor();
    renderProps();
    AC.setStatus('statusBar', message.trim(), failed.length ? 'error' : 'ok');
}

/** Ids already spoken for on a page, so a copy arriving on it can be given one that is not. */
function actionIdsOn(target) {
    const ids = (target.actions || []).map(a => a.actionId);
    (target.controls || []).forEach(c => (c.actions || []).forEach(a => ids.push(a.actionId)));
    return ids.filter(Boolean);
}

/**
 * The control on another page that answers to the same name as this one. A control id is minted
 * per page, so it says nothing over there; a field name does — it is what that page's own
 * templates already refer to the control by — and a label is what is left when the target has no
 * field name of its own, as a grid or a pie chart has not.
 */
function matchingControl(source, target) {
    if (!source) return null;
    const controls = (target.controls || []).filter(c => c.type === source.type && TARGET_TYPES.includes(c.type));
    const key  = c => (c.fieldName || '').trim().toLowerCase();
    const name = c => (c.label || '').trim().toLowerCase();
    return (key(source)  && controls.find(c => key(c)  === key(source)))
        || (name(source) && controls.find(c => name(c) === name(source)))
        || null;
}

/**
 * Puts copies of these actions into another page's library, carrying across everything they name
 * that can be carried and letting go of the rest. Mutates the destination page object; the caller
 * saves it. Hands back what happened, since a copy that quietly lost its target or a step of its
 * chain is the kind of thing that is noticed a week later.
 */
function graftActions(actions, target) {
    target.controls   = target.controls   || [];
    target.actions    = target.actions    || [];
    target.transforms = target.transforms || [];

    const taken   = target.actions.map(a => a.actionLabel || '');
    const usedIds = new Set(actionIdsOn(target));
    const copies  = actions.map(cloneValue);
    const remap   = new Map();
    const report  = { cleared: 0, brought: 0, reused: 0, dropped: 0, unbound: [] };
    // What the destination held before any of this arrived, so a step carried across for the
    // first copy is not then reported as one the destination already had for the second.
    const alreadyThere = new Set(target.transforms.map(t => t.name));

    copies.forEach((copy, i) => {
        // Its own id, and one the destination is not already using: an action is waited for by
        // id, and two answering to one id is exactly what that page's save refuses.
        let id = newActionId();
        while (usedIds.has(id)) id = newActionId();
        usedIds.add(id);
        remap.set(actions[i].actionId, copy.actionId = id);
        // Its own name kept, unless the destination already has one reading the same — a library
        // is picked from by name, and two entries reading alike are two guesses.
        copy.actionLabel = uniqueLabel(actions[i].actionLabel || 'Untitled action', taken);
        taken.push(copy.actionLabel);
    });

    copies.forEach(copy => {
        // Only a wait on something crossing alongside it can be honoured over there.
        const waited = copy.dependsOnActionId;
        if (waited) copy.dependsOnActionId = remap.get(waited) || '';

        // The chain has to name steps the destination holds, or that page's save is refused.
        const bringChain = chain => (chain || []).map(step => {
            if (alreadyThere.has(step)) { report.reused++; return step; }
            if (target.transforms.some(t => t.name === step)) return step;
            const definition = (page.transforms || []).find(t => t.name === step);
            if (!definition) { report.dropped++; return null; }
            target.transforms.push(cloneValue(definition));
            report.brought++;
            return step;
        }).filter(Boolean);
        copy.transformNames = bringChain(copy.transformNames);

        // A control id means nothing on another page, so the copy either finds the same control
        // by name over there or arrives pointing at nothing rather than at something arbitrary.
        const wanted = copy.targetControlId;
        if (wanted && wanted !== NEW_GRID) {
            const match = matchingControl(findControl(wanted), target);
            copy.targetControlId = match ? match.controlId : '';
            if (!match) { report.cleared++; report.unbound.push(copy.actionLabel); }
        }
        // The further targets by the same rule, except that one finding no match is dropped
        // rather than blanked, since the catalog refuses a target with no control.
        copy.extraBindings = (copy.extraBindings || []).map(b => {
            b.transformNames = bringChain(b.transformNames);
            if (b.targetControlId === NEW_GRID) return b;
            const match = matchingControl(findControl(b.targetControlId), target);
            if (!match) { report.cleared++; report.unbound.push(copy.actionLabel); return null; }
            b.targetControlId = match.controlId;
            return b;
        }).filter(Boolean);

        // And the grid a fan-out reads its rows from, held to the same rule. Not finding one
        // leaves the copy running once against the page rather than pointing at a grid that is
        // not there, which is the one thing that page's save would refuse outright.
        if (copy.rowSourceControlId) {
            const match = matchedIdOn(findControl(copy.rowSourceControlId), target);
            copy.rowSourceControlId = match || '';
            if (!match) {
                copy.rowOutputMode = 'ROWS';
                report.cleared++;
                report.unbound.push(copy.actionLabel);
            }
        }
        if (!repointGridLookups(copy, id => matchedIdOn(findControl(id), target))) {
            report.cleared++;
            report.unbound.push(copy.actionLabel);
        }
    });

    target.actions = target.actions.concat(copies);
    return report;
}

/**
 * Does the cross-page copy: one page loaded, added to and saved at a time, so a destination that
 * refuses the save — one with a problem of its own, or one someone else has changed since — stops
 * at itself rather than taking the rest of the run down with it.
 */
async function applyPageCopy() {
    if (!editor || editor.kind !== 'topage') return;

    const picked = actionsWithOrigin()
        .filter(e => editor.actionIds.includes(e.action.actionId))
        .map(e => e.action);
    if (!picked.length)         { AC.setStatus('editorStatus', 'Nothing ticked to copy.', 'error'); return; }
    if (!editor.targets.length) { AC.setStatus('editorStatus', 'Nothing ticked to copy onto.', 'error'); return; }

    const destinations = editor.targets.slice();
    AC.setStatus('editorStatus', 'Copying onto ' + destinations.length
        + ' page' + (destinations.length > 1 ? 's' : '') + '…');

    const done = [], failed = [], unbound = [];
    let brought = 0, reused = 0, dropped = 0;
    for (const name of destinations) {
        try {
            const target = await AC.api('GET', '/appcatalog/pages/' + encodeURIComponent(name));
            const report = graftActions(picked, target);
            await AC.api('PUT', '/appcatalog/pages/' + encodeURIComponent(name), target);
            done.push(name);
            brought += report.brought;
            reused  += report.reused;
            dropped += report.dropped;
            if (report.unbound.length) unbound.push(name);
        } catch (e) {
            failed.push(name + ' — ' + e.message);
        }
    }

    const many = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
    let message = done.length ? many(picked.length, 'action') + ' copied onto ' + done.join(', ') + '.' : '';
    if (brought)        message += ' ' + many(brought, 'transform') + ' carried across.';
    if (reused)         message += ' ' + many(reused, 'chained step') + ' already on the destination, left as it is.';
    if (dropped)        message += ' ' + many(dropped, 'chained step') + ' dropped — not on this page either.';
    if (unbound.length) message += ' On ' + unbound.join(', ') + ' a copy found no control to fill, so it binds nowhere yet.';
    if (failed.length)  message += ' Failed: ' + failed.join('; ');

    if (!done.length) { AC.setStatus('editorStatus', message || 'Nothing was copied.', 'error'); return; }

    editor = null;
    renderEditor();
    renderProps();
    AC.setStatus('statusBar', message.trim(), failed.length ? 'error' : 'ok');
}

/** Attaching appends, so the order actions are ticked in is the order they run in. */
// ── Clickable columns ────────────────────────────────────────────────────
// The same three things a control does — name a target, give it a value, run actions — written
// against one column of a grid instead. Kept apart from the control mutators because what they
// reach into is nested one deeper, not because it behaves any differently.

/**
 * The selected control as a grid, or nothing — every mutator below starts here. A pie with grids
 * counts: the grids it opens click through by its own clickable columns and rows.
 */
function selectedGrid() {
    const c = findControl(selectedId);
    if (!c || !GRID_OWNER_TYPES.includes(c.type)) return null;
    c.columnLinks = c.columnLinks || [];
    return c;
}

function addColumnLink() {
    const c = selectedGrid();
    if (!c) return;
    c.columnLinks.push({ column: '', assignments: [], actionIds: [] });
    renderProps();
    renderCanvas();
}

function removeColumnLink(index) {
    const c = selectedGrid();
    if (!c) return;
    c.columnLinks.splice(index, 1);
    renderProps();
    renderCanvas();
}

/** The column name updates the model and the canvas only — redrawing the panel per keystroke
 *  would take the caret out of the box being typed in, exactly as it would for any other text. */
function setColumnLink(index, name, value) {
    const c = selectedGrid();
    if (!c || !c.columnLinks[index]) return;
    c.columnLinks[index][name] = value;
    renderCanvas();
}

function addColumnLinkAssignment(index) {
    const c = selectedGrid();
    if (!c || !c.columnLinks[index]) return;
    c.columnLinks[index].assignments = (c.columnLinks[index].assignments || []).concat([{ targetControlId: '', value: '' }]);
    renderProps();
    renderCanvas();
}

function setColumnLinkAssignment(index, at, name, value) {
    const c = selectedGrid();
    const link = c && c.columnLinks[index];
    const assignment = link && (link.assignments || [])[at];
    if (!assignment) return;
    assignment[name] = value;
    renderCanvas();
}

function removeColumnLinkAssignment(index, at) {
    const c = selectedGrid();
    const link = c && c.columnLinks[index];
    if (!link) return;
    link.assignments = (link.assignments || []).filter((a, i) => i !== at);
    renderProps();
    renderCanvas();
}

function toggleColumnLinkAction(index, actionId, on) {
    const c = selectedGrid();
    const link = c && c.columnLinks[index];
    if (!link) return;
    const ids = link.actionIds || [];
    link.actionIds = on ? ids.concat([actionId]).filter((id, i, all) => all.indexOf(id) === i)
                        : ids.filter(id => id !== actionId);
    renderProps();
    renderCanvas();
}

function toggleControlAction(actionId, on) {
    const c = findControl(selectedId);
    if (!c) return;
    c.actionIds = c.actionIds || [];
    c.actionIds = on ? c.actionIds.concat([actionId]).filter((id, i, all) => all.indexOf(id) === i)
                     : c.actionIds.filter(id => id !== actionId);
    renderProps();
    renderCanvas();
}

function togglePageLoadAction(actionId, on) {
    page.onLoadActionIds = page.onLoadActionIds || [];
    page.onLoadActionIds = on ? page.onLoadActionIds.concat([actionId]).filter((id, i, all) => all.indexOf(id) === i)
                              : page.onLoadActionIds.filter(id => id !== actionId);
    renderProps();
}

function onHeaderInput() {
    page.title = document.getElementById('pageTitle').value;
    page.description = document.getElementById('pageDescription').value;
}

// ── Unsaved work ─────────────────────────────────────────────────────────

/**
 * What the designer is holding, as one string: the page's own JSON, and the name box beside it —
 * the name lives in the box rather than in the model until Save reads it, and naming a new page
 * is an edit worth keeping like any other.
 *
 * <p>Run mode writes nothing into the page — everything a run produces lives in its own state —
 * which is why this reads the same before and after a preview.
 */
function pageFingerprint() {
    const box = document.getElementById('pageName');
    return ((box && box.value) || '').trim() + '\u0000' + JSON.stringify(page);
}

/** Called wherever the page becomes the saved one: on load, on save, and on a page emptied. */
function markSaved() { savedFingerprint = pageFingerprint(); }

function isDirty() { return !!page && pageFingerprint() !== savedFingerprint; }

/**
 * Asked before anything that throws the current page away, `what` naming what is about to happen.
 * True to go ahead — which is immediate when there is nothing to lose, so the question is only
 * ever put when it is a real one.
 */
function confirmDiscard(what) {
    if (!isDirty()) return true;
    return confirm('This page has changes that have not been saved.\n\n' + what + ' anyway?');
}

// ── Save / delete ────────────────────────────────────────────────────────

async function savePage() {
    page.pageName = document.getElementById('pageName').value.trim();
    onHeaderInput();

    if (!page.pageName) { AC.setStatus('statusBar', 'Page name is required.', 'error'); return; }
    // A row whose target was never picked writes nothing anywhere; it is a half-finished line in
    // the editor rather than something the saved page should carry.
    page.controls.forEach(c => {
        c.assignments = assignmentsOf(c);
        c.slices = slicesOf(c);
    });

    try {
        const saved = savedPageName
            ? await AC.api('PUT', '/appcatalog/pages/' + encodeURIComponent(savedPageName), page)
            : await AC.api('POST', '/appcatalog/pages', page);
        page = saved;
        hydratePage();
        savedPageName = saved.pageName;
        pages = sortPages(await AC.api('GET', '/appcatalog/pages'));
        renderPageSelect();
        renderAll();
        // What was just written is what the guard measures against from here on. Set after the
        // round trip rather than before it: a save that fell over left the work unsaved, and the
        // page has to go on knowing that.
        markSaved();
        AC.setStatus('statusBar', 'Saved "' + saved.pageName + '".', 'ok');
    } catch (e) {
        AC.setStatus('statusBar', 'Save failed: ' + e.message, 'error');
    }
}

async function deletePage() {
    if (!savedPageName || !AC.confirmDelete('page', savedPageName)) return;
    try {
        await AC.api('DELETE', '/appcatalog/pages/' + encodeURIComponent(savedPageName));
        pages = pages.filter(p => p.pageName !== savedPageName);
        renderPageSelect();
        blankPage();
        AC.setStatus('statusBar', 'Deleted.', 'ok');
    } catch (e) {
        AC.setStatus('statusBar', 'Delete failed: ' + e.message, 'error');
    }
}

// ── Run mode ─────────────────────────────────────────────────────────────

function setMode(next) {
    mode = next;
    // Nothing of the run survives into the designer, this least of all: it is drawn over the
    // whole screen, and the screen underneath is about to be a different one.
    if (next !== 'run') closeChartZoom();
    document.getElementById('designer').style.display = next === 'design' ? '' : 'none';
    document.getElementById('runner').style.display = next === 'run' ? '' : 'none';
    document.getElementById('runBtn').style.display = next === 'design' ? '' : 'none';
    document.getElementById('designBtn').style.display = next === 'run' ? '' : 'none';
    if (next === 'run') startRun();
}

/**
 * The values a link carried, written over the defaults as the page opens. "Here is the link for
 * order 12345" is the commonest thing anybody wants to say about one of these pages, and until now
 * the only thing a link could say was which page to open.
 *
 * <p>Anything in the query string that is not one of the parameters the page is addressed by is
 * read as a field name: apppage.html?page=order-lookup&mode=run&orderId=12345 opens the page with
 * orderId already filled in. A name no control answers to is ignored rather than complained about
 * — a link outlives the page it points at, and a field that has since been renamed should not stop
 * the rest of the link working.
 *
 * @return the field names that were filled, so the caller can tell whether anything was.
 */
function prefillFromUrl() {
    const filled = [];
    page.controls.forEach(c => {
        if (!VALUE_TYPES.includes(c.type) || !c.fieldName) return;
        if (RESERVED_PARAMS.includes(c.fieldName) || !PAGE_PARAMS.has(c.fieldName)) return;
        const raw = PAGE_PARAMS.get(c.fieldName);
        // Read exactly as the control's own default is, so a link can say what a default can say:
        // a checkbox is on or off, and a date box takes TODAY-1 as readily as a date — which is
        // what lets a saved link go on meaning "yesterday" tomorrow.
        values[c.fieldName] = c.type === 'checkbox' ? ['true', '1', 'yes'].includes(raw.trim().toLowerCase())
            : c.type === 'date' ? dateText(c, dateIso(c, raw))
            : raw;
        filled.push(c.fieldName);
    });
    return filled;
}

/**
 * This page, running, with the values now in it — the link to hand somebody who needs to see what
 * is on the screen. Only what has a value goes in, so the link stays about what was filled in
 * rather than listing every empty box on the page.
 */
function runLinkUrl() {
    const url = new URL('apppage.html', location.href);
    url.searchParams.set('page', savedPageName);
    url.searchParams.set('mode', 'run');
    page.controls.forEach(c => {
        if (!VALUE_TYPES.includes(c.type) || !c.fieldName) return;
        if (RESERVED_PARAMS.includes(c.fieldName)) return;
        const held = values[c.fieldName];
        // A checkbox that is off is left out rather than written as false: absent and off are the
        // same thing to the page opening, and the shorter link is the one somebody can read.
        const text = c.type === 'checkbox' ? (held ? 'true' : '')
            : held === undefined || held === null ? '' : String(held);
        if (text !== '') url.searchParams.set(c.fieldName, text);
    });
    return url.href;
}

async function copyRunLink() {
    if (!savedPageName) return;
    const href = runLinkUrl();
    try {
        await navigator.clipboard.writeText(href);
        AC.setStatus('runStatus', 'Link copied — it opens this page with the values now in it.', 'ok');
    } catch (e) {
        // The clipboard is refused outside a secure context, which an internal tool served over
        // plain http routinely is. A link is no use in an error message, so it goes somewhere it
        // can be read and copied by hand instead.
        window.prompt('Copy this link — it opens this page with the values now in it:', href);
    }
}

async function startRun() {
    values = {};
    errors = [];
    gridState = {};
    gridMeta = {};
    pieData = {};
    pieMeta = {};
    pieGridRows = {};
    chartSource = {};
    chartKeyPick = {};
    chartPick = {};
    zoomedChart = null;
    shownOptions = {};
    resetTimeSeriesState();
    activeTab = {};
    fanTabs = {};
    fanRowChecks = {};
    fanDisplayFilters = {};
    collapsedTabs = {};
    childRuns = {};
    closeChildFailures();
    datasetCache = new Map();
    linkUrls = {};
    lastTrigger = null;
    lastRun = null;
    closeTechDetails();
    document.getElementById('stackedGrids').innerHTML = '';
    page.controls.forEach(c => {
        // A link's address is its default the same way a text box's value is: what the designer
        // wrote is what the operator sees until something binds over it. A link pointed at
        // another page has that page's address instead, and keeps it — see #pageLinkUrl.
        if (c.type === 'link') linkUrls[c.controlId] = pageLinkUrl(c) || c.defaultValue || '';
        if (!VALUE_TYPES.includes(c.type)) return;
        values[c.fieldName] = c.type === 'checkbox' ? c.defaultValue === 'true' : (c.defaultValue || '');
    });
    // A grid's status variable exists from the start, blank, so ${name} is known before it is filled.
    page.controls.forEach(c => {
        if (c.type === 'grid' && c.statusCondition && c.statusVariable) values[c.statusVariable] = '';
    });
    compiledTransforms = new Map();
    // After the controls have their defaults and before anything goes out, because a variable may
    // be written in terms of a control and the page opening is a trigger like any other: what its
    // select options and its on-load actions carry is the moment it opened.
    refreshGlobals();
    // And the date boxes after that, because theirs is the one default that has to be worked out
    // rather than simply held: a date box shows yyyy-MM-dd and nothing else, and ${DATESTAMP} —
    // or TODAY-1 — is not that until the built-ins above have settled what it stands for.
    page.controls.forEach(c => {
        if (c.type === 'date') values[c.fieldName] = dateText(c, dateIso(c, c.defaultValue));
    });
    // Last of the three, because what a link carried beats every default it is written over — the
    // date boxes above included. The variables are then worked out again over it: one written in
    // terms of a field means the value the page actually opened with, which on a link with values
    // in it is the link's. Before renderRun and before anything goes out, so the operator sees
    // what the link asked for and the on-load actions send it.
    if (prefillFromUrl().length) refreshGlobals();
    renderRun();
    // One call window over the whole opening of the page: two selects sourced from the same
    // instance, or an on-load action over the endpoint a select already fetched, are one call.
    beginCallBatch(actionsByIds(page.onLoadActionIds));
    try {
        // Two phases, and only two. Inside each, everything goes out at once; between them
        // the page waits, because an on-load action routinely reads a select the operator has
        // not touched yet and it should see the value that select actually settled on. Folding
        // the two together would shave a round trip off the opening and hand those actions
        // empty dropdowns, which is not a trade worth making.
        //
        // The dataset-backed grids fill in the same phase: they are the same kind of thing as a
        // sourced dropdown — something the page opens already holding rather than something a
        // click produces — and an on-load action fanning out over one of them has to find its
        // rows there. Sent alongside the dropdowns rather than after them, since neither reads
        // the other.
        await Promise.all([loadSelectOptions(), loadDatasetGrids()]);
        const onLoad = actionsByIds(page.onLoadActionIds);
        if (onLoad.length) {
            // The page opening is a trigger like any other, and on a page whose work is all done
            // on load it is the only one there is — so it is what Replay offers until the
            // operator does something of their own.
            lastTrigger = { load: true, label: 'Page load' };
            await runActions(onLoad, 'Page load', null);
        }
    } finally {
        endCallBatch();
        renderRunTools();
    }
}

/**
 * The page as it was the moment it opened: every value back at its default, every grid, chart,
 * error and stacked result gone, and the on-load actions run again.
 *
 * <p>Which is precisely what previewing the page does, so it is the same call. An operator who
 * has filled a form in wrongly, or who has stacked a screen's worth of grids under it, should
 * not have to leave the page and come back to get a clean one — and on the standalone link
 * there is nowhere to come back from.
 */
async function resetRun() {
    await startRun();
    // The on-load actions report on themselves; with none, nothing else would say the button
    // had done anything at all.
    if (!errors.length && !actionsByIds(page.onLoadActionIds).length) {
        AC.setStatus('runStatus', 'Page reset.', 'ok');
    }
}

/**
 * Runs the last trigger again, exactly as it ran the first time: the same assignments, then the
 * same actions, against the page as it stands now. Not a replay of the response — the calls go
 * out again — which is the point of it: the same button, pressed again, after something at the
 * other end has changed.
 *
 * <p>The control is looked up by id rather than held onto, because a reset redraws the page; and
 * the element to grey out while it runs is found afresh for the same reason.
 */
async function replayLastTrigger() {
    if (!lastTrigger) return;
    // Sent now rather than replayed from what came back, so the date, the time and the UUID it
    // carries are this send's rather than the first one's — which is the whole point of a
    // replay: the same button, pressed again, after something at the other end has changed.
    refreshGlobals();
    if (lastTrigger.load) {
        const onLoad = actionsByIds(page.onLoadActionIds);
        if (!onLoad.length) { lastTrigger = null; renderRunTools(); return; }
        beginCallBatch(onLoad);
        try {
            await runActions(onLoad, 'Page load', null);
        } finally {
            endCallBatch();
        }
        return;
    }
    // A click on a grid a pie with grids opened was on that pie's grid, which is not a control itself.
    const control = findControl(lastTrigger.controlId)
        || ((lastTrigger.column !== undefined || lastTrigger.rowClick) ? gridOwner(lastTrigger.controlId) : null);
    if (!control) {
        // Only reachable by editing the page between the run and the replay, but then the button
        // would be offering something that no longer exists.
        errors = [];
        addError('The control that last ran is no longer on this page.');
        lastTrigger = null;
        renderRunTools();
        return;
    }
    // A row click replays against the row that was clicked, for the reason a cell click does: the
    // rows may well have been replaced by what the click itself ran, and "the same thing, sent
    // now" means the same row either way.
    if (lastTrigger.rowClick) {
        const click = rowClickOf(control.controlId);
        if (!click) {
            errors = [];
            addError('The rows of that grid no longer click through.');
            lastTrigger = null;
            renderRunTools();
            return;
        }
        const actions = actionsByIds(click.actionIds);
        errors = [];
        clearActionTargets(actions, control.controlId);
        applyRowAssignments((click.assignments || []).filter(a => a.targetControlId),
            lastTrigger.row, rowJson(lastTrigger.row), lastTrigger.label);
        renderErrors();
        if (!actions.length) return;
        await runActions(actions, lastTrigger.label, null, true);
        return;
    }
    // A cell click is replayed against the row that was clicked, which is carried on the trigger
    // rather than looked up again: the rows may well have been replaced by what the click itself
    // ran, and "the same drill-down, sent now" means the same row either way.
    if (lastTrigger.column !== undefined) {
        const link = columnLinkNamed(control, lastTrigger.column);
        if (!link) {
            errors = [];
            addError('The column that last ran no longer drills down.');
            lastTrigger = null;
            renderRunTools();
            return;
        }
        const actions = actionsByIds(link.actionIds);
        errors = [];
        clearActionTargets(actions, control.controlId);
        const assignments = (link.assignments || []).filter(a => a.targetControlId);
        applyRowAssignments(assignments, lastTrigger.row, cellText(lastTrigger.row, lastTrigger.column), lastTrigger.label);
        renderErrors();
        if (!actions.length) return;
        await runActions(actions, lastTrigger.label, null, true);
        return;
    }
    // A multi-button replays the entry that was picked rather than the button, which is the only
    // thing "the same thing, sent now" can mean here: the button itself runs nothing, and six
    // entries behind one click would otherwise all replay as whichever the list happened to
    // start with. Found again by name rather than held, so an entry taken off the menu between
    // the run and the replay says so instead of running what has moved into its place.
    if (lastTrigger.menuLabel !== undefined) {
        const option = (control.menuOptions || []).find(o => o.label === lastTrigger.menuLabel);
        if (!option) {
            errors = [];
            addError('"' + lastTrigger.menuLabel + '" is no longer on that menu.');
            lastTrigger = null;
            renderRunTools();
            return;
        }
        const actions = actionsByIds(option.actionIds);
        errors = [];
        clearActionTargets(actions, control.controlId);
        renderErrors();
        if (!actions.length) return;
        await runActions(actions, lastTrigger.label, null, true);
        return;
    }
    const host = document.getElementById('rc-' + control.controlId);
    const element = host && (host.querySelector('[data-run]') || host.querySelector('[data-field]'));
    await runControlActions(control, element);
}

/**
 * Keeps the run-mode buttons saying what they will do. Replay names the trigger it would send,
 * so "again" is never a guess about which one, and is dead until there is one; Technical Details
 * counts the calls it would open and is dead until a trigger has made some.
 */
function renderRunTools() {
    const tech = document.getElementById('techBtn');
    if (tech) {
        const count = lastRun ? lastRun.calls.length : 0;
        tech.disabled = !count;
        tech.textContent = 'Technical Details' + (count ? ' (' + count + ')' : '');
        tech.title = !count ? 'Nothing has been triggered yet.'
            : pageDebug()
                ? 'The URL, headers, body, status and response of each of the ' + count + ' call'
                    + (count === 1 ? '' : 's') + ' "' + oneLine(lastRun.label || '')
                    + '" made — as a page you can save or send on.'
                // Still worth opening with the detail off — where each call went, what it
                // answered and how long it took are all still there. Only the bodies are not,
                // and saying so on the button beats the reader finding out inside.
                : 'Where each of the ' + count + ' call' + (count === 1 ? '' : 's') + ' "'
                    + oneLine(lastRun.label || '') + '" made went and what it answered. '
                    + '${DEBUG} is off on this page, so the request and response bodies were not kept.';
    }
    const replay = document.getElementById('replayBtn');
    if (!replay) return;
    const label = lastTrigger && lastTrigger.label ? oneLine(lastTrigger.label) : '';
    replay.disabled = !lastTrigger;
    replay.textContent = label ? 'Replay: ' + (label.length > 24 ? label.slice(0, 23) + '…' : label)
        : 'Replay Last Trigger';
    replay.title = lastTrigger
        ? 'Run "' + label + '" again — the same values, the same calls, sent now.'
        : 'Nothing has been triggered yet.';
    const reset = document.getElementById('resetRunBtn');
    if (reset) reset.title = 'Clear everything this run has produced and open the page again from the start.';
    const share = document.getElementById('shareLinkBtn');
    if (share) {
        // A page that has never been saved has no address to hand anybody, and a page being read
        // rather than built already came from one of these links.
        share.style.display = savedPageName && !STANDALONE ? '' : 'none';
        share.title = 'Copy a link that opens this page with the values now filled in.';
    }
}

/**
 * Opens the window inside which identical calls are shared, and adds what this run is going to
 * want a body from. A nested run — the on-load actions inside the page's own opening — joins
 * the window already open rather than starting a second, so the sharing spans the whole event
 * and the inner run cannot close the window on the outer one.
 */
function beginCallBatch(actions) {
    if (callBatchDepth++ === 0) {
        callCache = new Map();
        payloadNeeded = new Set();
    }
    (actions || []).forEach(a => {
        if (a && a.appUseCaseInstanceId && bindingsOf(a).some(b => !isMetadataAction(b))) {
            payloadNeeded.add(a.appUseCaseInstanceId);
        }
    });
}

function endCallBatch() {
    if (--callBatchDepth > 0) return;
    callBatchDepth = 0;
    callCache = null;
    payloadNeeded = null;
}

/**
 * Whether this action's call may leave its bodies on the server. A metadata action normally can
 * — that is the point of it — but not when something else in the same trigger is going to bind
 * the body of the same instance, because then the two can be one call and the body is coming
 * over regardless.
 */
function isMetadataOnly(action) {
    // Every target has to be reading metadata: one binding that wants the body brings it over.
    return bindingsOf(action).every(isMetadataAction)
        && !(payloadNeeded && payloadNeeded.has(action.appUseCaseInstanceId));
}

/**
 * Whether a control is drawn at all while the page runs: a hidden field never was, and a grid
 * ticked hidden has asked not to be. Everything that is not drawing still happens to both of
 * them — the field carries its value, the grid holds its rows — which is why this is a question
 * about the canvas rather than about the control existing.
 */
function isDrawnOnRun(c) {
    return c.type !== 'hidden' && !(c.type === 'grid' && c.hideOnRun);
}

function renderRun() {
    document.getElementById('runTitle').textContent = page.title || page.pageName || 'Untitled page';
    document.getElementById('runDesc').textContent = page.description || '';
    renderErrors();
    renderRunTools();

    const canvas = document.getElementById('runCanvas');
    // Hidden controls carry a value but occupy no space — laying them out would leave holes.
    // A grid ticked hidden is the same bargain for rows: it still fills, is still read by
    // whatever fans out over it or looks into it, and simply is not drawn — see #gridHiddenProp.
    // A grid or chart inside a tab set is drawn by the tab set, not here: it has no placement of
    // its own, and laying it out as well would put the same control on the page twice.
    canvas.innerHTML = page.controls.filter(c => isDrawnOnRun(c) && !heldBy(c.controlId)).map(c =>
        '<div class="run-ctl ' + AC.esc(c.type) + '-ctl" style="' + runPlacement(c) + '" id="rc-' + AC.attr(c.controlId) + '">'
            + runControl(c) + '</div>').join('');

    wireTabStrips(canvas);
    paintChildSummary();

    page.controls.forEach(c => {
        // Painted off its own host rather than the control's, since a tabbed grid's host lives
        // inside the tab set's pane and it has no run-ctl of its own.
        if (c.type === 'grid') paintGrid(c.controlId);
        wireRunControl(c);
    });
    // Once, after everything above has been drawn: a group's badge reads what is under it, and
    // on a page whose groups hold only charts nothing in the loop above would have asked for it.
    paintTabsetStatuses();
}

/**
 * What one control on the running page listens for: the operator changing its value, and the
 * operator setting it off.
 *
 * <p>Found by the control's own run host rather than by walking the canvas, which is what lets a
 * control be a tab: its host is then the tab's pane, inside the set, with no place of its own on
 * the layout. And it is a function of its own rather than a loop in renderRun for the same
 * reason — repainting a tab set replaces its panes, and what was in them has to be wired up
 * again. See #paintTabs.
 */
function wireRunControl(c) {
    const host = document.getElementById('rc-' + c.controlId);
    if (!host) return;
    // A multi-button's triggers are its entries rather than itself, so it is wired a menu at a
    // time — there is no [data-run] on it for the wiring below to find.
    if (c.type === 'multibutton') { wireMenuButton(c, host); return; }
    const input = host.querySelector('[data-field]');
    if (input) {
        input.addEventListener(isSelect(c.type) || c.type === 'checkbox' ? 'change' : 'input', () => {
            values[c.fieldName] = valueOfInput(c, input);
            // On every keystroke rather than when the field is left: a link written over this box
            // is showing where it currently goes, and an address a character behind what is typed
            // is one somebody follows to the wrong place. See #paintTemplatedLinks.
            paintTemplatedLinks();
        });
        // A value control wired to CHANGE sets whatever it was told to set and runs its
        // actions whenever the operator moves it — picking a different environment and
        // having the grid below reload itself, or picking an order and having its id land in
        // the box the next action sends. Bound on
        // 'change' even for a text box, so it fires when the field is left rather than on
        // every keystroke; nobody means to make a call per character typed.
        if (c.trigger === 'CHANGE' && (actionsFor(c).length || assignmentsOf(c).length)) {
            input.addEventListener('change', () => {
                values[c.fieldName] = valueOfInput(c, input);
                runControlActions(c, input);
            });
        }
    }
    // On a link or a button that is the control itself; on everything else that runs on click,
    // the label written over the box — see #labelTriggers.
    const trigger = host.querySelector('[data-run]');
    if (!trigger) return;
    trigger.addEventListener('click', () => runControlActions(c, trigger));
    // A link is an anchor, and an anchor with no address is not activated by the keyboard the
    // way the button this used to be was. Enter and space are wired back on for exactly that
    // case: once it has an address the browser activates it itself, and doing it here as well
    // would run the actions twice. A triggering label is an anchor that never has an address,
    // so it is always this that makes it reachable.
    if (c.type === 'link' || labelTriggers(c)) {
        trigger.addEventListener('keydown', e => {
            if (trigger.hasAttribute('href') || (e.key !== 'Enter' && e.key !== ' ')) return;
            e.preventDefault();
            trigger.click();
        });
    }
}

/**
 * Clicking a tab shows its grid; clicking the button at the end of the strip minimizes the whole
 * set. Every pane stays in the document either way — see .tabset-pane.
 */
function wireTabStrips(canvas) {
    canvas.querySelectorAll('[data-tab-min]').forEach(el =>
        el.addEventListener('click', () => toggleTabsCollapsed(el.dataset.tabMin)));
    canvas.querySelectorAll('[data-tab-child]').forEach(el => {
        el.addEventListener('click', () => {
            const tabsId = el.dataset.tab;
            activeTab[tabsId] = el.dataset.tabChild;
            const host = document.getElementById('rc-' + tabsId);
            if (!host) return;
            // Only this set's own buttons and panes. A set may hold another set, and that inner
            // strip is inside this host too — switching the outer tab must not reach down and
            // move the inner one, which is showing whatever the operator last left it on.
            const mine = '[data-tab="' + CSS.escape(tabsId) + '"]';
            host.querySelectorAll(mine).forEach(tab =>
                tab.classList.toggle('active', tab.dataset.tabChild === activeTab[tabsId]));
            host.querySelectorAll('[data-pane-of="' + CSS.escape(tabsId) + '"]').forEach(pane =>
                pane.classList.toggle('pane-off', pane.dataset.pane !== activeTab[tabsId]));
        });
    });
}

/**
 * A tab set as it runs: the strip, and every one of its grids drawn into its own pane with all
 * but the selected one held off screen. All of them are in the document because all of them are
 * real: an action fills the grid it names whether or not that grid's tab happens to be showing,
 * and the rows, filters and sort it left behind are still there when the tab is picked.
 */
/**
 * Every tab a set is showing right now: the grids laid out into it in the designer, then
 * whatever a fan-out has added this run. The two are the same thing on the strip — a name, a
 * status and a grid behind it — and differ only in whether the page or the run put them there,
 * which is why one list serves both.
 */
function runTabsOf(c) {
    return tabChildren(c).map(k => ({ gridId: k.controlId, title: controlTitle(k), style: colorStyle(k),
                                      type: k.type, required: !!k.mandatory && VALUE_TYPES.includes(k.type) }))
        .concat((fanTabs[c.controlId] || []).map(t => ({ gridId: t.gridId, title: t.title, style: '', type: 'grid' })));
}

/**
 * How the call behind a chart in a tab set went, as the strip says it. A chart's own label
 * carries this where the chart is laid out on the page; inside a tab the label is the strip, so
 * the badge moves there with it.
 */
function chartTabStatus(controlId) {
    const outcome = chartOutcome(controlId);
    const check = chartCheckBadge(controlId);
    return '<span class="grid-status' + (outcome ? ' ' + GRID_OUTCOME_CLASS[outcome] : '') + '"'
        + ' data-chart-status="' + AC.attr(controlId) + '">' + AC.esc(outcome.toLowerCase()) + '</span>'
        // A checked pie carries its tally onto the strip too, exactly as a grid does: "the call
        // worked and two of the five wedges are wrong" is the thing worth reading without opening
        // the tab, and it is the reason the tab is amber rather than green.
        + '<span class="' + check.cls + '" data-chart-check="' + AC.attr(controlId) + '"'
        + ' title="' + AC.attr(check.title) + '">' + AC.esc(check.text) + '</span>';
}

/** Moves those badges after a chart has been drawn again, without redrawing the strip under it. */
function paintChartTabStatus(controlId) {
    const el = document.querySelector('[data-chart-status="' + CSS.escape(controlId) + '"]');
    if (el) {
        const outcome = chartOutcome(controlId);
        el.className = 'grid-status' + (outcome ? ' ' + GRID_OUTCOME_CLASS[outcome] : '');
        el.textContent = outcome.toLowerCase();
    }
    const tally = document.querySelector('[data-chart-check="' + CSS.escape(controlId) + '"]');
    if (tally) {
        const check = chartCheckBadge(controlId);
        tally.className = check.cls;
        tally.textContent = check.text;
        tally.title = check.title;
    }
}

/**
 * How one thing on a strip went, whatever kind of thing it is: a grid's own outcome, a chart's,
 * or — for anything that holds other controls — the worst of everything inside it.
 *
 * <p>Kept in one place because the tab does not care what is behind it. "Is UAT fine" is the same
 * question whether UAT's tab is a grid, a group of four tabs, or a panel holding a form and the
 * two grids it fills; and each of those has to answer it the same way or the strip becomes a
 * thing that has to be read differently depending on what is in it.
 */
function childOutcome(id, type, seen) {
    if (type === 'grid') return gridOutcome(id);
    if (isChart(type))   return chartOutcome(id);
    if (isContainer(type)) return tabsOutcome(id, seen).status;
    return '';
}

/**
 * How everything inside a container went, as one verdict.
 *
 * <p>The reason a set is worth putting inside a tab at all. Grouping eight environments into two
 * tabs of four only helps if the outer tab says whether anything in there needs opening — a group
 * that looked the same whatever was behind it would just be one more click on the way to the
 * answer. So the outer tab is <b>success</b> only where every tab within it is.
 *
 * <p>A panel rolls up the same way, and that is what makes a tab honest about what it holds. A
 * tab whose content is a panel of four grids is not a tab with nothing to say — it is a tab with
 * four verdicts behind it, and reading it as blank would hide exactly the thing the strip is for.
 * So the walk goes through every container, however they are nested: a panel inside a tab inside
 * a panel answers for every grid below it.
 *
 * <p>The worst of what is inside wins, and the order is the one the individual badges already
 * use: a failed call outranks bad rows, because a call that failed left nothing to judge. Things
 * with nothing to say — a text box, a button, a grid nothing has filled — are not counted
 * against the group and not counted for it either; a container holding only those has no verdict,
 * and shows none, rather than claiming success for calls that have not been made.
 *
 * <p>The tally counts what actually had a verdict rather than how many tabs there are, which is
 * why a panel of four grids reads "3 of 4 OK" on the tab above it rather than "0 of 1": the
 * numbers a panel contributes are its own, passed up whole.
 *
 * @return {status, total, bad} — `total` counts the children that had a verdict, `bad` those
 *         that were not SUCCESS.
 */
function tabsOutcome(containerId, seen) {
    seen = seen || new Set();
    // Cannot happen on a page that saved — a container holding itself is refused — but a page
    // being edited passes through states that have not been checked yet, and hanging the browser
    // is not how the designer should find out.
    if (seen.has(containerId)) return { status: '', total: 0, bad: 0 };
    seen.add(containerId);
    const set = findControl(containerId);
    if (!set || !isContainer(set.type)) return { status: '', total: 0, bad: 0 };
    const RANK = { '': 0, SUCCESS: 1, ERROR: 2, FAILURE: 3 };
    let worst = '';
    let total = 0;
    let bad = 0;
    const children = set.type === 'tabs' ? runTabsOf(set)
        : containerChildren(set).map(k => ({ gridId: k.controlId, type: k.type }));
    children.forEach(k => {
        // A container inside a container contributes everything under it rather than one
        // verdict: four grids in a panel are four things that ran, and rolling them into a
        // single tally entry would make "3 of 4 OK" read "0 of 1" one box further out.
        if (isContainer(k.type)) {
            const inner = tabsOutcome(k.gridId, seen);
            if (!inner.status) return;
            total += inner.total;
            bad += inner.bad;
            if (RANK[inner.status] > RANK[worst]) worst = inner.status;
            return;
        }
        const status = childOutcome(k.gridId, k.type, seen);
        if (!status) return;
        total++;
        if (status !== 'SUCCESS') bad++;
        if (RANK[status] > RANK[worst]) worst = status;
    });
    return { status: worst, total: total, bad: bad };
}

/** Every grid anywhere inside a container, however deep — what its badge is answering for. */
function containerGrids(containerId, seen) {
    seen = seen || new Set();
    if (seen.has(containerId)) return [];
    seen.add(containerId);
    const set = findControl(containerId);
    if (!set || !isContainer(set.type)) return [];
    return containerChildren(set).reduce((found, k) =>
        found.concat(k.type === 'grid' ? [k] : isContainer(k.type) ? containerGrids(k.controlId, seen) : []), []);
}

/** The rolled-up verdict on the tab that holds a whole group, and the count behind it. */
function tabsetTabStatus(tabsId) {
    const roll = tabsOutcome(tabsId);
    const tally = tabsetTally(roll);
    return '<span class="grid-status' + (roll.status ? ' ' + GRID_OUTCOME_CLASS[roll.status] : '') + '"'
        + ' data-tabset-status="' + AC.attr(tabsId) + '">' + AC.esc(roll.status.toLowerCase()) + '</span>'
        + '<span class="' + tally.cls + '" data-tabset-check="' + AC.attr(tabsId) + '"'
        + ' title="' + AC.attr(tally.title) + '">' + AC.esc(tally.text) + '</span>';
}

/** "4 of 4 OK" under a group's verdict — what the badge alone does not say is how many.
 *  Counted in things that ran rather than in tabs, since a panel contributes several. */
function tabsetTally(roll) {
    if (!roll.total) return { text: '', cls: 'grid-check', title: '' };
    const good = roll.total - roll.bad;
    return {
        text: good.toLocaleString() + ' of ' + roll.total.toLocaleString() + ' OK',
        cls: 'grid-check ' + (roll.bad ? 'err' : 'ok'),
        title: roll.bad
            ? roll.bad.toLocaleString() + ' of the ' + roll.total.toLocaleString()
                + ' things in here did not come back clean.'
            : 'Every one of the ' + roll.total.toLocaleString() + ' things in here is a success.'
    };
}

/**
 * Repaints every group's rolled-up badge, wherever one is drawn.
 *
 * <p>Called whenever any grid or chart on the page has been filled, rather than being worked out
 * from which group the thing that changed was in: a group's verdict depends on everything below
 * it however deep that goes, there are only ever a handful of strips on a page, and the badges
 * are written into in place — so redoing all of them costs nothing and cannot go stale, while
 * tracking the one that needed it could.
 */
function paintTabsetStatuses() {
    document.querySelectorAll('[data-tabset-status]').forEach(el => {
        const roll = tabsOutcome(el.dataset.tabsetStatus);
        el.className = 'grid-status' + (roll.status ? ' ' + GRID_OUTCOME_CLASS[roll.status] : '');
        el.textContent = roll.status.toLowerCase();
        const tally = tabsetTally(roll);
        const badge = document.querySelector('[data-tabset-check="' + CSS.escape(el.dataset.tabsetStatus) + '"]');
        if (!badge) return;
        badge.className = tally.cls;
        badge.textContent = tally.text;
        badge.title = tally.title;
    });
}

function tabsRun(c) {
    const tabs = runTabsOf(c);
    if (!tabs.length) return '<div class="grid-empty">This tab set holds nothing yet.</div>';

    const chosen = activeTab[c.controlId];
    // What the operator last picked, else the tab the designer starred, else the first.
    const preferred = isDefaultTab(c, c.defaultTabControlId) ? c.defaultTabControlId : null;
    const active = tabs.some(k => k.gridId === chosen) ? chosen
        : tabs.some(k => k.gridId === preferred) ? preferred : tabs[0].gridId;
    activeTab[c.controlId] = active;
    const shut = !!collapsedTabs[c.controlId];

    return '<div class="tabset' + (shut ? ' shut' : '') + '">'
        + '<div class="tabset-strip">' + tabs.map(k =>
            '<button type="button" class="tabset-tab' + (k.gridId === active ? ' active' : '') + '"'
                + ' data-tab="' + AC.attr(c.controlId) + '" data-tab-child="' + AC.attr(k.gridId) + '"'
                + k.style + (k.gridId === preferred ? ' title="The default tab"' : '') + '>'
                + (k.gridId === preferred ? '<span class="tab-default" aria-label="default tab">★</span>' : '')
                + AC.esc(k.title)
                // The label is hidden inside the pane, so a mandatory field's marker moves to
                // the strip with the name it belongs to.
                + (k.required ? ' <span class="req">*</span>' : '')
                + (k.type === 'grid'
                    ? '<span class="grid-status" data-grid-status="' + AC.attr(k.gridId) + '"></span>'
                        + '<span class="grid-check" data-grid-check="' + AC.attr(k.gridId) + '"></span>'
                        + '<span class="grid-check" data-grid-verdict="' + AC.attr(k.gridId) + '"></span>'
                    // A tab holding a whole group — another strip, or a panel with grids in it —
                    // answers for all of them at once, which is the reason for grouping them:
                    // the outer strip says whether anything in there needs opening, without the
                    // operator opening it to find out. A tab whose panel holds four grids reads
                    // as those four grids did, not as blank.
                    : isContainer(k.type) ? tabsetTabStatus(k.gridId)
                    : isChart(k.type) ? chartTabStatus(k.gridId) : '')
            + '</button>').join('')
            // On the strip rather than beside the control's label, because the strip is what is
            // left when the body goes: the same button minimizes it and brings it back, and it
            // is still where it was while everything below has moved up to meet it.
            + '<button type="button" class="tabset-min" data-tab-min="' + AC.attr(c.controlId) + '"'
                + ' title="' + (shut ? 'Open this tab set again'
                    : 'Minimize this tab set so what is under it comes up the page') + '">'
                + (shut ? '▸ ' + tabs.length + ' tab' + (tabs.length === 1 ? '' : 's') : '▾')
            + '</button>'
            + '</div>'
        + '<div class="tabset-body">' + tabs.map(k => {
            const off = k.gridId === active ? '' : ' pane-off';
            // A grid's pane holds the rows and nothing else: paintGrid finds it by data-grid, and
            // the name and outcome the grid would have carried are on the strip above.
            if (k.type === 'grid') {
                return '<div class="tabset-pane' + off + '" data-pane="' + AC.attr(k.gridId) + '"'
                    + ' data-pane-of="' + AC.attr(c.controlId) + '">'
                    + '<div class="data-grid" data-grid="' + AC.attr(k.gridId) + '"></div></div>';
            }
            // Everything else is drawn exactly as it would be on the layout, in a pane that is
            // its own run host. paintChart, fillOptions and the wiring in renderRun all find a
            // control by rc-<id>, and a control laid out as a tab has no run-ctl of its own on
            // the canvas to be found — so the pane is the one, carrying the same classes the
            // layout would have given it. Which is what lets any control be a tab: the fields to
            // fill in on the first tab, the readings of what they produced on the others.
            const child = findControl(k.gridId);
            const type = child ? child.type : '';
            // Which set the pane belongs to, so switching a tab moves only its own panes: a
            // nested set's panes are inside this one's host too, and the strip above them is
            // showing whatever the operator last left it on.
            return '<div class="tabset-pane run-ctl ' + AC.esc(type) + '-ctl'
                + (isChart(type) ? ' chart-pane' : '') + off + '" data-pane="' + AC.attr(k.gridId) + '"'
                + ' data-pane-of="' + AC.attr(c.controlId) + '"'
                + ' id="rc-' + AC.attr(k.gridId) + '">' + (child ? runControl(child) : '') + '</div>';
        }).join('') + '</div>'
        + '</div>';
}

/**
 * A panel as it runs: the box, its name on the top edge, and everything it holds laid out inside
 * it at once.
 *
 * <p>Each child is drawn into a host of its own carrying the same <code>run-ctl</code> classes
 * and the same <code>rc-&lt;id&gt;</code> the layout would have given it, exactly as a tab's pane
 * does — which is what lets any control live in a panel without anything downstream knowing.
 * paintGrid, paintChart, fillOptions and the wiring in renderRun all find a control by that id
 * and neither know nor care that it is in a box.
 *
 * <p>The layout inside is the page's own grid one box in: twenty-four columns, half rows, and the
 * child's own row and column read against the panel rather than against the page. The rows are
 * measured from the topmost child so a panel gathered from halfway down a page draws its contents
 * at the top of the box rather than below a band of nothing.
 *
 * <p>The name carries the same rolled-up verdict a tab of a group does, where there is anything
 * inside with a verdict to give: a box holding four grids says how those four went without being
 * opened, which is the whole reason for putting them in one.
 */
function panelRun(c) {
    const children = containerChildren(c).filter(isDrawnOnRun);
    const roll = tabsOutcome(c.controlId);
    const tally = tabsetTally(roll);
    const head = '<div class="panel-head">'
        + '<span class="panel-name"' + colorStyle(c) + '>' + AC.esc(controlTitle(c)) + '</span>'
        + '<span class="grid-status' + (roll.status ? ' ' + GRID_OUTCOME_CLASS[roll.status] : '') + '"'
            + ' data-tabset-status="' + AC.attr(c.controlId) + '">' + AC.esc(roll.status.toLowerCase()) + '</span>'
        + '<span class="' + tally.cls + '" data-tabset-check="' + AC.attr(c.controlId) + '"'
            + ' title="' + AC.attr(tally.title) + '">' + AC.esc(tally.text) + '</span>'
        + '</div>';
    if (!children.length) {
        return '<div class="panel-box">' + head + '<div class="grid-empty">This panel holds nothing yet.</div></div>';
    }
    const top = Math.min(...children.map(k => k.row || 0));
    return '<div class="panel-box">' + head + '<div class="panel-body">'
        + children.map(k =>
            '<div class="run-ctl ' + AC.esc(k.type) + '-ctl" id="rc-' + AC.attr(k.controlId) + '"'
            + ' style="grid-column:' + (k.col + 1) + '/span ' + k.span
                + ';grid-row:' + (Math.round(((k.row || 0) - top) * 2) + 1)
                + '/span ' + Math.round(rowSpanOf(k) * 2) + '">'
            + runControl(k) + '</div>').join('')
        + '</div></div>';
}

/**
 * A multi-button as it runs: the button, and the menu it opens under it.
 *
 * <p>The whole list is in the document from the start rather than built on the click, so every
 * entry is wired up once with the rest of the page — the same reason a tab's pane is there
 * whether or not the tab is showing.
 *
 * <p>An entry the page cannot run is shown greyed out rather than left off. The save refuses a
 * menu with one on it, so this is only ever reached on a page being previewed mid-edit, and a
 * missing entry would read as a menu that had quietly lost something rather than as one still
 * being written.
 */
function menuRun(c, style) {
    const entries = menuOptionsOf(c);
    return '<div class="menu-button" data-menu="' + AC.attr(c.controlId) + '">'
        + '<button type="button" class="primary" data-menu-open="1"' + style + '>'
            + AC.esc(c.label || 'Menu') + ' ▾</button>'
        + '<div class="menu-pop">'
        + (entries.length ? entries.map((o, i) => {
            const runnable = actionsByIds(o.actionIds).length;
            const colour = cssColor(o.color);
            return '<button type="button" class="menu-item" data-menu-entry="' + i + '"'
                + (runnable ? '' : ' disabled title="This entry has no action attached to it."')
                + (colour ? ' style="color:' + AC.esc(colour) + '"' : '') + '>'
                + AC.esc(o.label || '(unnamed)') + '</button>';
        }).join('') : '<div class="menu-empty">Nothing on this menu yet.</div>')
        + '</div></div>';
}

/** Opens and closes one multi-button's menu, and runs the entry that was picked. */
function wireMenuButton(c, host) {
    const box = host.querySelector('.menu-button');
    if (!box) return;
    const open = host.querySelector('[data-menu-open]');
    if (open) {
        open.addEventListener('click', e => {
            e.stopPropagation();
            const showing = box.classList.toggle('open');
            // Only one menu stands open at a time, and clicking anywhere else shuts it — what a
            // menu does everywhere else, and the only way out that does not need the button.
            document.querySelectorAll('.menu-button.open').forEach(other => {
                if (other !== box) other.classList.remove('open');
            });
            if (showing) document.addEventListener('click', function shut() {
                box.classList.remove('open');
                document.removeEventListener('click', shut);
            }, { once: true });
        });
    }
    host.querySelectorAll('[data-menu-entry]').forEach(el => {
        el.addEventListener('click', e => {
            e.stopPropagation();
            box.classList.remove('open');
            runMenuOption(c, Number(el.dataset.menuEntry), el);
        });
    });
}

/**
 * One entry of a multi-button picked: run what is attached to it.
 *
 * <p>The same shape as {@link #runControlActions}, less the half that does not apply — the
 * control has no assignments and no actions of its own, because each entry is the trigger rather
 * than the button. What the entry runs is emptied before the calls go out for the reason a
 * button's targets are: picking "Cancel the order" and getting an error has to look like nothing
 * came back, because nothing did.
 */
function runMenuOption(c, index, element) {
    refreshGlobals();
    const option = menuOptionsOf(c)[index];
    if (!option) return;
    const actions = actionsByIds(option.actionIds);
    const label = (c.label || controlTitle(c)) + ' · ' + (option.label || 'entry');
    // Which entry, not just which control: the replay button has to send the one that was picked
    // rather than whichever happens to be first on the menu.
    lastTrigger = { controlId: c.controlId, menuLabel: option.label, label: label };
    renderRunTools();
    clearActionTargets(actions, c.controlId);
    errors = [];
    renderErrors();
    if (!actions.length) {
        addError('"' + label + '" has no actions attached to it.');
        renderErrors();
        return;
    }
    // The setting is the control's rather than the entry's: a menu is one control whose entries
    // are different ways of asking, and where the answer lands is a fact about the control.
    return thenFocus(runActions(actions, label, element, true), c);
}

// ── Bringing the answer into view ────────────────────────────────────────
// A page long enough to be worth building is a page where the button and the grid it fills are
// not on screen together. The run works, the status line says so, and the rows are two screens
// down behind a tab nobody opened. What follows is the other half of the click: the control the
// trigger named is opened, scrolled to and marked, so the answer finds the operator rather than
// the other way round. See AppPageControl#getFocusControlId.

/**
 * What a trigger does once everything it set off has finished: brings the control it named into
 * view, if it named one.
 *
 * <p>Whether the run succeeded or not. A grid that came back empty because the call failed is
 * carrying that failure on itself, and that is as worth being shown as the rows would have been —
 * scrolling only on success would leave the one case somebody has to see undisplayed.
 */
function focusAfterRun(control) {
    if (control && control.focusControlId) focusControl(control.focusControlId);
}

/**
 * Runs something and then scrolls to what the trigger named, whichever way the run went.
 *
 * <p>Whatever the run handed back is handed back unchanged, and a run that fell over still fails
 * afterwards: this is a step added to the end of a trigger, not a place errors go to be handled.
 * The scroll happens on both paths because the failure is exactly what the operator has been sent
 * to look at.
 */
function thenFocus(running, control) {
    return Promise.resolve(running).then(
        value => { focusAfterRun(control); return value; },
        error => { focusAfterRun(control); throw error; });
}

/**
 * Puts one control in front of the operator: opens whatever it is shut inside, scrolls the page
 * to it, and marks it for a moment.
 *
 * <p>The mark is not decoration. A page with four grids on it scrolled to one of them says
 * nothing about which of the four just ran — they all look the same, and the one that answered is
 * the question being asked. Two seconds of outline answers it and then gets out of the way.
 */
function focusControl(controlId) {
    if (!findControl(controlId)) return;
    revealContainers(controlId);
    const host = runHostOf(controlId);
    if (!host) return;
    // Gliding there is how the operator keeps track of where the page went; somebody who has
    // asked their machine for less movement gets the same landing in one step instead.
    const still = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    host.scrollIntoView({ behavior: still ? 'auto' : 'smooth', block: 'center' });
    // Taken off and put back rather than simply added: a second click on the same button has to
    // flash again, and a class that is already there does not restart an animation by itself.
    host.classList.remove('run-focused');
    void host.offsetWidth;
    host.classList.add('run-focused');
    clearTimeout(focusFade);
    focusFade = setTimeout(() => host.classList.remove('run-focused'), 2200);
}

/**
 * Where a control is drawn on the running page. Nearly always its own <code>rc-&lt;id&gt;</code>
 * host — and, for a grid laid out as a tab, the pane holding its rows instead: a grid's pane is
 * the rows and nothing else, so it is the one control on a running page with no host of its own.
 */
function runHostOf(controlId) {
    return document.getElementById('rc-' + controlId)
        || document.querySelector('[data-pane="' + CSS.escape(controlId) + '"]');
}

/**
 * Opens everything a control is shut inside, outermost first: the tab sets holding it are
 * switched to the tab it is behind and minimized ones are opened again, so scrolling to it
 * afterwards lands on something that is actually on screen.
 *
 * <p>Outermost first because an inner strip is inside the outer one's pane: switching the inner
 * tab while the outer pane is still off screen would be moving something nobody can see, and the
 * outer switch would then be the thing that has to know to leave it alone.
 *
 * <p>A panel needs nothing done to it — it draws everything it holds at once — but it is still
 * walked through, since a tab set may hold a panel which holds the grid.
 */
function revealContainers(controlId) {
    const chain = [];
    let id = controlId;
    // The page cannot nest a container inside itself, but a page being edited briefly can, so the
    // walk is capped rather than trusted.
    for (let depth = 0; depth < 20; depth++) {
        const holder = heldBy(id);
        if (!holder) break;
        chain.push({ holder: holder, childId: id });
        id = holder.controlId;
    }
    chain.reverse().forEach(step => {
        if (step.holder.type === 'tabs') showTab(step.holder.controlId, step.childId);
    });
}

/**
 * Switches a tab set to one of its tabs from code, exactly as clicking that tab does — and opens
 * the set first where it has been minimized, since a tab picked inside a shut set would otherwise
 * be a pane nobody can see.
 */
function showTab(tabsId, childId) {
    if (collapsedTabs[tabsId]) toggleTabsCollapsed(tabsId);
    activeTab[tabsId] = childId;
    const host = document.getElementById('rc-' + tabsId);
    if (!host) return;
    // Only this set's own buttons and panes, for the reason the click handler says: a set may
    // hold another set, whose strip is inside this host too and is showing whatever the operator
    // last left it on. See #wireTabStrips.
    const mine = '[data-tab="' + CSS.escape(tabsId) + '"]';
    host.querySelectorAll(mine).forEach(tab =>
        tab.classList.toggle('active', tab.dataset.tabChild === childId));
    host.querySelectorAll('[data-pane-of="' + CSS.escape(tabsId) + '"]').forEach(pane =>
        pane.classList.toggle('pane-off', pane.dataset.pane !== childId));
}

/**
 * Minimizes a tab set, or opens it again, and moves everything under it to match.
 *
 * <p>Hiding the body alone would not be worth a button: the control keeps the rows of the layout
 * grid it was given, so the space it was occupying would still be there and the thing underneath
 * would still be off the bottom of the screen. What makes this "see the one below" rather than
 * "see less of this one" is that the rows it is not using go back — see #runPlacement.
 */
function toggleTabsCollapsed(tabsId) {
    const control = findControl(tabsId);
    if (!control) return;
    collapsedTabs[tabsId] = !collapsedTabs[tabsId];
    paintTabs(control);
    applyRunPlacement();
}

/**
 * Where a control sits while the page is running, which is where it was designed to sit less
 * whatever the minimized tab sets above it have handed back.
 *
 * <p>The layout is an explicit row per control rather than document order, so a control that
 * shrinks does not pull the next one up by itself — the rows it vacated stay in the grid as
 * empty ones. Everything below is therefore lifted by exactly what was freed, which leaves
 * controls beside the minimized set where they are and controls under it where they would have
 * been had it always been that tall.
 */
function runPlacement(c) {
    const shut = c.type === 'tabs' && collapsedTabs[c.controlId];
    const half = shut ? COLLAPSED_HALF_ROWS : Math.round(rowSpanOf(c) * 2);
    const lift = page.controls.reduce((freed, other) => {
        if (other.row >= c.row || heldBy(other.controlId)) return freed;
        if (other.type === 'tabs' && collapsedTabs[other.controlId])
            return freed + Math.max(Math.round(rowSpanOf(other) * 2) - COLLAPSED_HALF_ROWS, 0);
        return freed + hiddenGridRows(other);
    }, 0);
    return 'grid-column:' + (c.col + 1) + '/span ' + c.span
         + ';grid-row:' + Math.max(Math.round((c.row || 0) * 2) + 1 - lift, 1) + '/span ' + half;
}

/**
 * The half-rows a hidden grid hands back to the controls below it, or none where handing them
 * back would take something else with them.
 *
 * <p>A grid that is not drawn still has the rows the layout gave it, so on its own it would leave
 * an empty band exactly where the page had a twelve-row reference table — which is the hole that
 * hiding it was meant to close. So the rows go back and everything below comes up.
 *
 * <p>But only where the band is the hidden grid's alone. A hidden grid laid out beside a control
 * that is still drawn shares its rows with it, and lifting the page past those rows would pull
 * what is below up over the control still standing there. Then the band stays, which costs a gap
 * beside a control rather than two controls on top of each other.
 */
function hiddenGridRows(c) {
    if (c.type !== 'grid' || !c.hideOnRun) return 0;
    const top = c.row, bottom = c.row + rowSpanOf(c);
    const beside = page.controls.some(other => other !== c && isDrawnOnRun(other)
        && !heldBy(other.controlId)
        && other.row < bottom && other.row + rowSpanOf(other) > top);
    return beside ? 0 : Math.round(rowSpanOf(c) * 2);
}

/**
 * Re-places every control where {@link #runPlacement} now says it goes. The styles are written
 * onto the hosts that are already there rather than the canvas being drawn again: a redraw would
 * take the scroll position, the focus and every wired listener with it, which is a lot to spend
 * on moving things up a page.
 */
function applyRunPlacement() {
    page.controls.forEach(c => {
        if (!isDrawnOnRun(c) || heldBy(c.controlId)) return;
        const host = document.getElementById('rc-' + c.controlId);
        if (host) host.setAttribute('style', runPlacement(c));
    });
}

/**
 * Whether this control is set off by its own label being clicked.
 *
 * <p>A button and a link are the controls with something to click; everything else on a form is a
 * box, and a box that ran its actions when it was clicked would run them every time somebody put
 * the caret in it. So a value control wired to Click is triggered by its <em>label</em> instead —
 * the name above the box becomes a link, and clicking it sets the values and runs the actions
 * exactly as Value change does when the box is left.
 *
 * <p>Which is the wiring a form wants more often than a button is. "Order id" over a box, and the
 * name itself is the "look it up": no second control beside the field, no row of buttons under a
 * form of ten fields, and the thing you click is the thing it is about. The box still takes a
 * value the ordinary way — what the label adds is a way to ask for it on demand rather than on
 * every change, which is the difference between a field somebody is still typing into and one
 * they have finished with.
 *
 * <p>Only where there is something to run: a label that offers a click and answers nothing is
 * worse than a plain label, which is the same bargain {@link #linkRun} strikes over an address.
 */
function labelTriggers(c) {
    // Anything that is not CHANGE is a click, exactly as everywhere else that reads the setting:
    // a page saved with Click on a select said Click, and until now that was wiring that could
    // never fire — there was nothing on the control for the operator to click.
    return c.trigger !== 'CHANGE'
        && !ACTION_TYPES.includes(c.type) && !TRIGGERLESS_TYPES.includes(c.type)
        && !!(actionsFor(c).length || assignmentsOf(c).length);
}

/**
 * A value control's label as it runs: the name of the field, or that name as the link that sets
 * the control off — see {@link #labelTriggers}.
 *
 * <p>The control's colour goes on the anchor rather than on the label when it is one, so a label
 * given a colour in the designer keeps it and the rest read as the links they are.
 */
function runLabel(c, style) {
    const star = c.mandatory ? ' <span class="req">*</span>' : '';
    if (!labelTriggers(c)) {
        return '<label' + style + '>' + AC.esc(c.label || c.fieldName || '') + star + '</label>';
    }
    // The control's own title rather than a label that may be blank: an unnamed field is a row of
    // empty space, and an unnamed field that is the only way to run the page would be a row of
    // empty space with the trigger hidden in it.
    // role and tabindex for the same reason an addressless link carries them: an anchor with no
    // href is not a control as far as the browser is concerned, and this one is the only way to
    // reach what the label runs. The keyboard half is wired in #wireRunControl.
    return '<label><a class="run-link label-link" data-run="1" role="button" tabindex="0"' + style
        + ' title="' + AC.attr(labelTriggerTitle(c)) + '">' + AC.esc(controlTitle(c)) + star + '</a></label>';
}

/** What clicking a label will do, as the tooltip on it. */
function labelTriggerTitle(c) {
    const runs = actionsFor(c).length;
    const sets = assignmentsOf(c).length;
    const parts = [];
    if (sets)  parts.push('set ' + sets + (sets === 1 ? ' value' : ' values'));
    if (runs)  parts.push('run ' + runs + (runs === 1 ? ' action' : ' actions'));
    return 'Click to ' + parts.join(' and ');
}

function runControl(c) {
    const style = colorStyle(c);
    const label = runLabel(c, style);
    const hint = c.helpText ? '<span class="hint">' + AC.esc(c.helpText) + '</span>' : '';
    const value = values[c.fieldName];

    switch (c.type) {
        case 'button':
            return '<button class="primary" data-run="1"' + style + '>' + AC.esc(c.label || 'Run') + '</button>';
        case 'multibutton':
            return menuRun(c, style);
        case 'link':
            return linkRun(c, style);
        case 'label':
            return '<div class="static-label"' + style + '>' + AC.esc(c.defaultValue || c.label || '') + '</div>';
        case 'grid':
            // The name carries the outcome of whatever last filled the grid, so "did that work"
            // is answered where the grid is rather than only in the error list at the top.
            return '<label' + style + '>' + AC.esc(c.label || c.fieldName || '')
                    + ' <span class="grid-status" data-grid-status="' + AC.attr(c.controlId) + '"></span>'
                    // And, where the grid checks its rows, how many of them passed — see
                    // #paintGridCheck. A successful call over wrong rows is still a failed run.
                    + ' <span class="grid-check" data-grid-check="' + AC.attr(c.controlId) + '"></span>'
                    // And its status by row count, where it has one — see #paintGridVerdict.
                    + ' <span class="grid-check" data-grid-verdict="' + AC.attr(c.controlId) + '"></span></label>'
                + '<div class="data-grid" data-grid="' + AC.attr(c.controlId) + '"></div>';
        case 'tabs':
            return tabsRun(c);
        case 'panel':
            return panelRun(c);
        case 'pie':
        case 'piegrid':
            return pieRun(c);
        case 'bar':
            return barRun(c);
        case 'timeseries':
        case 'line':
            return tsRun(c);
        case 'page':
            return childPageRun(c, style);
        case 'select':
            return label + '<select data-field="' + AC.attr(c.fieldName) + '"' + style + '><option value="">—</option></select>' + hint;
        // No blank option: on a list where several may be picked, "none" is picking none of them
        // rather than picking a row that means none. The box fills the height the control was
        // given, so how many options are on screen at once is a layout decision like any other.
        case 'multiselect':
            return label + '<select multiple data-field="' + AC.attr(c.fieldName) + '"' + style + '></select>' + hint;
        case 'textarea':
            return label + '<textarea data-field="' + AC.attr(c.fieldName) + '" placeholder="' + AC.attr(c.placeholder || '') + '"' + style + '>' + AC.esc(value || '') + '</textarea>' + hint;
        case 'checkbox':
            return label + '<label class="inline-check"' + style + '><input type="checkbox" data-field="' + AC.attr(c.fieldName) + '"'
                + (value ? ' checked' : '') + '> ' + AC.esc(c.placeholder || '') + '</label>' + hint;
        default:
            // The box is the browser's date picker and speaks yyyy-MM-dd whatever the control
            // publishes, so a value the page is holding in the control's own format is read back
            // to a day before it goes in one.
            return label + '<input type="' + (c.type === 'number' ? 'number' : c.type === 'date' ? 'date' : 'text')
                + '" data-field="' + AC.attr(c.fieldName) + '" value="'
                + AC.attr((c.type === 'date' ? dateIso(c, value) : value) || '')
                + '" placeholder="' + AC.attr(c.placeholder || '') + '"' + style + '>' + hint;
    }
}

/**
 * A link as it runs. Always an anchor, so an address that lands in it is a real link — one that
 * middle-clicks, copies and shows itself in the browser's status bar — rather than a button
 * dressed up as one.
 *
 * <p>Which leaves the case where it has no address yet, since an anchor without an href is not a
 * link and is not focusable either. The role and tabindex put back what the button gave it, and
 * only when there is something to trigger: a link that is nothing but a place for an action to
 * put an address stays plain text until the address arrives, rather than offering a click that
 * would answer "this has nothing to do".
 */
function linkRun(c, style) {
    const live = actionsFor(c).length || assignmentsOf(c).length;
    const url = linkAddress(c);
    return '<a class="run-link" data-link="1"' + (live ? ' data-run="1"' : '')
        + linkAttrs(url, live) + linkWaitingTitle(c, url) + style + '>'
        + AC.esc(linkText(c, url)) + '</a>';
}

/**
 * Where a link actually points now: the address it is holding with every <code>${field}</code> in
 * it filled in from the page.
 *
 * <p>A link whose address is written in terms of the form above it is the ordinary case of one —
 * <code>https://reports/orders/${orderId}</code> under the box the operator types the order into,
 * and no action, no binding and no second click to get there. Anything the page can answer
 * answers: a control's value, a page variable, a built-in like <code>${DATESTAMP}</code>. What is
 * read is whatever the link is holding, so an address an action bound is resolved the same way a
 * typed one is.
 *
 * <p>Nothing, rather than a half-filled address, while a placeholder in it is unanswered or empty.
 * A link is followed by somebody who cannot see where it goes until they are there, so
 * <code>…/orders/</code> with the id missing is worse than a link that is plainly not ready yet:
 * it is a click that lands somewhere wrong, or on somebody else's record. Not ready shows as
 * plain text and says what it is waiting for — see {@link #linkWaitingTitle}.
 */
function linkAddress(c) {
    const raw = linkUrls[c.controlId];
    return linkMissing(raw).length ? '' : resolveTemplate(raw);
}

/**
 * The placeholders in an address that the page cannot fill in yet — unknown to it, or known and
 * empty — by the name they were written under, in the order they appear and without repeats.
 * Empty for an address with no placeholders in it at all, which is every link saved before they
 * were allowed here.
 */
function linkMissing(url) {
    const text = url === undefined || url === null ? '' : String(url);
    const missing = [];
    text.replace(/\$\{([A-Za-z0-9_.\-]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g, (match, braced, bare) => {
        const field = braced || bare;
        const value = scopedHas(field) ? scopedValue(field) : undefined;
        const blank = value === undefined || value === null || String(value) === '';
        if (blank && !missing.includes(field)) missing.push(field);
        return match;
    });
    return missing;
}

/** Why a link is not a link yet, as the tooltip on it — or nothing, when it is one. */
function linkWaitingTitle(c, url) {
    if (url) return '';
    const missing = linkMissing(linkUrls[c.controlId]);
    if (!missing.length) return '';
    return ' title="' + AC.attr('Waiting for ' + missing.map(name => '${' + name + '}').join(', ')) + '"';
}

/**
 * Redraws every link whose address is written in terms of the page, because something the page
 * holds has just changed. Called wherever a value lands — the operator typing in a box, an
 * assignment, an action binding a response — so a link under a form follows the form rather than
 * showing where it pointed when the page opened.
 *
 * <p>Only the templated ones: a link holding a plain address has nothing to follow, and redrawing
 * it on every keystroke would be work for no difference.
 */
function paintTemplatedLinks() {
    page.controls.forEach(c => {
        if (c.type !== 'link') return;
        const raw = linkUrls[c.controlId];
        if (typeof raw === 'string' && raw.includes('$')) paintLink(c);
    });
}

/**
 * The address a link pointed at another page goes to, or nothing when it was not pointed at one.
 *
 * <p>The standalone form of that page — the same link the designer's <b>Open standalone</b>
 * hands out — because somebody following a link between pages wants the page, not the builder
 * around it. Rooted at this server, so it satisfies {@link #safeUrl} exactly as a typed
 * <code>/</code> address does rather than needing an exception made for it.
 */
function pageLinkUrl(c) {
    const name = (c.linkPageName || '').trim();
    return name ? '/apppage.html?page=' + encodeURIComponent(name) + '&mode=run' : '';
}

/**
 * What a link shows: its label, and failing that the destination itself — the page's name where
 * it opens one, since the query string that address really is says far less than the name does.
 */
function linkText(c, url) {
    return c.label || c.linkPageName || safeUrl(url) || 'Link';
}

/** The attributes that make a link a link, or — with no address — a focusable trigger. */
function linkAttrs(url, live) {
    const safe = safeUrl(url);
    if (safe) return ' href="' + AC.esc(safe) + '" target="_blank" rel="noopener noreferrer"';
    return live ? ' role="button" tabindex="0"' : '';
}

/**
 * An address a link may actually point at, or nothing. Only http, https and a path rooted on this
 * server survive: an address bound out of a response is data, and a <code>javascript:</code> one
 * in an href would be that data running as this page. Anything else is refused rather than
 * quietly rewritten into something that looked close enough — see {@link #bindLink}, which says
 * so out loud.
 */
function safeUrl(url) {
    const text = (url === undefined || url === null ? '' : String(url)).trim();
    if (/^\/[^\/]/.test(text)) return text;   // rooted here; a second slash is another host
    return /^https?:\/\//i.test(text) ? text : '';
}

/**
 * Redraws one link after its address changed. The anchor itself is kept — it carries the click
 * that runs the link's own actions — and only what it points at and what it says are moved.
 */
function paintLink(control) {
    const el = document.querySelector('#rc-' + CSS.escape(control.controlId) + ' [data-link]');
    if (!el) return;
    const url = linkAddress(control);
    const safe = safeUrl(url);
    if (safe) {
        el.href = safe;
        el.target = '_blank';
        el.rel = 'noopener noreferrer';
        el.removeAttribute('role');
        el.removeAttribute('tabindex');
    } else {
        ['href', 'target', 'rel'].forEach(name => el.removeAttribute(name));
        if (el.hasAttribute('data-run')) { el.setAttribute('role', 'button'); el.setAttribute('tabindex', '0'); }
    }
    // What it is still waiting for, where it is waiting for something: a link that has gone quiet
    // because the box above it is empty should say so under the pointer rather than look broken.
    const missing = url ? [] : linkMissing(linkUrls[control.controlId]);
    if (missing.length) el.title = 'Waiting for ' + missing.map(name => '${' + name + '}').join(', ');
    else el.removeAttribute('title');
    el.textContent = linkText(control, url);
}

/**
 * The page's error section: every failure the run produced, in one place, or nothing at all.
 *
 * <p>A failure that came out of a call carries that call's place in the run and gets a button
 * beside it, because "the endpoint returned 500" provokes exactly one question and it is always
 * the same one: what did we send, and what came back. The button opens the technical details on
 * that call alone rather than on the whole trigger, which on a run of six is five sections the
 * reader would have had to scroll past to reach the one that just complained.
 */
function renderErrors() {
    const host = document.getElementById('pageErrors');
    if (!errors.length) { host.innerHTML = ''; return; }
    host.innerHTML = '<div class="page-errors"><div class="err-title">' + errors.length
        + (errors.length === 1 ? ' problem' : ' problems') + '</div><ul>'
        + errors.map(e => '<li>' + AC.esc(e.message)
            + (e.call === null ? ''
                : '<button type="button" class="err-why" onclick="showTechDetails(' + e.call + ')"'
                    + ' title="The URL, the headers, what was sent and what came back for this call">'
                    + 'View request &amp; response</button>')
            + '</li>').join('') + '</ul></div>';
}

/**
 * @param call which of the last run's calls this failure came out of, when it came out of one.
 *             Left off by everything that failed before a call was made — a missing mandatory
 *             field, a target that is no longer on the page — since there is nothing to show.
 */
function addError(message, call) {
    errors.push({ message: message, call: (call === undefined || call === null) ? null : call });
    renderErrors();
}

/**
 * The button that opens the call behind a record, wherever a record is shown. Written out only
 * when the panel would actually have that call to show: a grid keeps its metadata bar long after
 * later triggers have replaced what the panel holds, and a button that opened the wrong call
 * under the right heading would be worse than no button.
 */
function techButton(info) {
    if (!info || info.call === null || info.call === undefined) return '';
    if (!lastRun || info.runAt !== lastRun.at) return '';
    return '<button type="button" class="tool-btn" onclick="showTechDetails(' + info.call + ')"'
        + ' title="The URL, the headers, what was sent and what came back for this call">'
        + 'View request &amp; response</button>';
}

/**
 * Fills every select's options as the page opens: the static ones outright, and the ones that
 * have to ask the server all at once rather than one after another. A page with five sourced
 * dropdowns used to open in five round trips laid end to end, and that wait was most of the time
 * before the operator could touch anything.
 *
 * <p>Fetched together, filled in the order the controls are listed, so the error list and the
 * values the on-load actions go on to read come out the same however the responses were
 * staggered. Two selects sourced from the same instance already share one flight through the
 * call batch this runs inside; environment lists are shared here by app name, which is the same
 * idea applied to the one call that does not go through it.
 *
 * <p>Each select is still reported on its own: one dropdown with a broken source leaves the
 * other four filled, exactly as it did when they were fetched one at a time.
 */
async function loadSelectOptions() {
    const selects = page.controls.filter(c => isSelect(c.type));
    const envCalls = new Map();

    // Every request is started here, before any of them is waited on — that is the whole of the
    // parallelism. Rejections are turned into values rather than left for the loop below: one
    // failing while the page is still waiting on its siblings has nobody handling it yet, and
    // the browser would report it as unhandled before the loop ever reached it.
    const pending = selects.map(c => {
        const source = c.optionSource || {};
        if (source.mode === 'DATASET' && source.datasetName) {
            // Not wrapped either, and shared with any other control reading the same dataset —
            // see #datasetRows, which caches the flight rather than the answer.
            return datasetRows(source.datasetName).then(data => ({ dataset: data }), error => ({ error: error }));
        }
        if (source.mode === 'USECASE' && source.appUseCaseInstanceId) {
            // Called straight out, not wrapped: runInstance is async, so a synchronous
            // failure inside it comes back as a rejection like any other.
            return runInstance(source.appUseCaseInstanceId, {}, 'Options for "' + controlTitle(c) + '"')
                .then(data => ({ data: data }), error => ({ error: error }));
        }
        if (source.mode === 'ENVIRONMENTS' && source.appName) {
            // One GET per app, not per dropdown: two selects listing the same app's environments
            // are asking the identical question, and the call cache the use case sources share
            // does not cover this endpoint.
            if (!envCalls.has(source.appName)) envCalls.set(source.appName, AC.listEnvironments(source.appName));
            return envCalls.get(source.appName).then(envs => ({ envs: envs }), error => ({ error: error }));
        }
        return null;
    });

    for (let i = 0; i < selects.length; i++) {
        const c = selects[i];
        const source = c.optionSource || {};
        if (source.mode === 'STATIC') {
            fillOptions(c, (source.staticOptions || []).map(o => ({ value: o.key, label: o.value || o.key })));
            continue;
        }
        // A select with no source configured, or one naming neither an instance nor an app, has
        // nothing to fetch and keeps the empty list it was rendered with.
        if (!pending[i]) continue;

        const settled = await pending[i];
        if (source.mode === 'DATASET') {
            if (settled.error) {
                addError('Options for "' + controlTitle(c) + '": ' + settled.error.message);
                continue;
            }
            fillOptions(c, (settled.dataset.rows || []).map(r => optionOf(r, source.keyField, source.labelField)));
            continue;
        }
        if (source.mode === 'USECASE') {
            const name = 'Options for "' + controlTitle(c) + '"';
            if (settled.error) { addError(settled.error.message); continue; }
            try {
                const rows = rowsAt(settled.data, source.arrayPath, name);
                fillOptions(c, rows.map(r => optionOf(r, source.keyField, source.labelField)));
            } catch (e) {
                addError(e.message);
            }
        } else {
            if (settled.error) { addError('Options for "' + controlTitle(c) + '": ' + settled.error.message); continue; }
            fillOptions(c, settled.envs.map(e => ({ value: e.environment,
                label: e.environment + (e.envClass ? ' (' + e.envClass + ')' : '') })));
        }
    }
}

/**
 * One static dataset's rows, fetched once per opening of the page however many controls read it.
 * The promise is cached rather than the answer, so two controls asking at the same moment share
 * one flight — the same bargain the call cache makes for use case instances.
 *
 * <p>A dataset whose own load failed comes back as a perfectly good HTTP 200 carrying an
 * {@code error}, since the failure is the dataset's rather than the request's. Turned into a
 * rejection here so every caller reports it the way it reports anything else that went wrong.
 */
function datasetRows(name) {
    if (!datasetCache) datasetCache = new Map();
    if (!datasetCache.has(name)) {
        datasetCache.set(name, AC.api('GET', '/staticdataset/' + encodeURIComponent(name) + '/data')
            .then(data => {
                if (data && data.error) throw new Error('static dataset "' + name + '": ' + data.error);
                return data;
            }));
    }
    return datasetCache.get(name);
}

/**
 * Fills every grid that names a static dataset as the page opens, so the page starts holding the
 * list rather than waiting for something to be clicked before it shows one.
 *
 * <p>Fetched together and filled in the order the controls are listed, for the same reason the
 * dropdowns are: the page reads the same however the responses were staggered. A grid whose
 * dataset could not be read says so where the rows would have been, in the metadata bar every
 * grid already has, as well as in the error list.
 */
async function loadDatasetGrids() {
    const grids = page.controls.filter(c => c.type === 'grid' && c.datasetName);
    // Started before any is waited on, and rejections turned into values here rather than left
    // for the loop: one failing while the page waits on its siblings has nobody handling it yet.
    const pending = grids.map(c => datasetRows(c.datasetName).then(data => ({ data: data }), error => ({ error: error })));

    for (let i = 0; i < grids.length; i++) {
        const c = grids[i];
        const settled = await pending[i];
        if (settled.error) {
            const message = '"' + controlTitle(c) + '" could not be filled: ' + settled.error.message;
            gridMeta[c.controlId] = callRecord(null, 'FAILED', message, null);
            paintGrid(c.controlId);
            addError(message);
            continue;
        }
        // No call behind these rows, so no record either: the metadata bar has nothing true to
        // say about a URL, a status or a timing, and inventing one would be worse than the bar
        // simply not being there.
        delete gridMeta[c.controlId];
        bindGrid(c, settled.data.rows || []);
    }
}

function optionOf(row, keyField, labelField) {
    if (row === null || typeof row !== 'object') return { value: String(row), label: String(row) };
    const value = keyField ? rowField(row, keyField) : Object.values(row)[0];
    const label = labelField ? rowField(row, labelField) : value;
    return { value: value === undefined || value === null ? '' : String(value),
             label: label === undefined || label === null ? '' : String(label) };
}

/**
 * What a control's input element currently says, as the page holds it: a boolean for a checkbox,
 * every pick joined for a multi-select, the day in the control's own format for a date, and the
 * box's own text for everything else.
 */
function valueOfInput(c, input) {
    if (c.type === 'checkbox')    return input.checked;
    if (c.type === 'multiselect') return multiValue(input);
    // The picker only ever hands back yyyy-MM-dd or nothing, so an emptied box is emptied here
    // too rather than formatted into something that looks like a date nobody picked.
    if (c.type === 'date')        return dateText(c, input.value);
    return input.value;
}

/**
 * Whether this dropdown opens on its first option rather than on the blank row — asked of the
 * control, not of whatever filled it, for the same reason the order is: it is a decision about the
 * list the operator reads.
 */
function picksFirst(c) {
    return (c.optionSource || {}).selectFirst === true;
}

/**
 * Puts a dropdown's options in the order its designer asked for, whatever put them there — the
 * list fetched as the page opens, and the list an action binds into it later. Sorted here rather
 * than at each of those, so "this select reads A to Z" is one setting on the control instead of a
 * property of whichever call happened to fill it.
 *
 * <p>By the label, which is the value the operator reads: the key behind it is routinely an id
 * nobody sees, and ordering a list by something invisible looks like no order at all. The
 * comparison is the grid's own — see {@link #compareCells} — so a list of numbers runs 1, 2, 10
 * rather than 1, 10, 2.
 */
function sortedOptions(c, options) {
    const order = ((c.optionSource || {}).sortOrder || 'NONE').toUpperCase();
    if (order !== 'ASC' && order !== 'DESC') return options;
    const direction = order === 'DESC' ? -1 : 1;
    // Copied before sorting: the array handed in is routinely mapped straight off a cached
    // response, and reordering it in place would reorder what the next control reads.
    return options.slice().sort((a, b) => compareCells(String(a.label), String(b.label)) * direction);
}

function fillOptions(c, options, quiet) {
    const select = document.querySelector('#rc-' + CSS.escape(c.controlId) + ' select');
    if (!select) return;
    const previous = values[c.fieldName];
    const multi = c.type === 'multiselect';
    const shown = sortedOptions(c, options);
    // Kept as well as written in, so a redraw of whatever the control is drawn inside can put
    // them back rather than leaving an empty dropdown behind — see #shownOptions.
    shownOptions[c.controlId] = options;
    select.innerHTML = (multi ? '' : '<option value="">—</option>')
        + shown.map(o => '<option value="' + AC.attr(o.value) + '">' + AC.esc(o.label) + '</option>').join('');
    // Keep whatever was already chosen (or the control's default) when it survives the refresh.
    // On a multi-select that is each pick judged separately: a refreshed list that dropped one of
    // five keeps the other four rather than throwing the lot away over the one that went.
    let picked = false;
    if (multi) {
        const wanted = multiParts(previous);
        [...select.options].forEach(o => { o.selected = wanted.includes(o.value); });
        // Nothing survived — which is the case "select the first" is for. Judged after the keeping
        // above rather than instead of it: a default is what the control falls back to, never
        // something that overwrites a pick somebody made.
        if (picksFirst(c) && !multiValue(select) && select.options.length) {
            select.options[0].selected = true;
            picked = true;
        }
        values[c.fieldName] = multiValue(select);
    } else if (previous && [...select.options].some(o => o.value === previous)) {
        select.value = previous;
        values[c.fieldName] = select.value;
    } else {
        // Index 0 is the blank row this control was just given, not an option anybody supplied —
        // so the first real option is the one after it, and a list that came back empty has none.
        if (picksFirst(c) && select.options.length > 1) {
            select.selectedIndex = 1;
            picked = true;
        }
        values[c.fieldName] = select.value;
    }
    // Dispatched rather than simply set, so the page reacts to the default the way it reacts to
    // the operator: the value-change listeners run, and a select wired to CHANGE runs its actions
    // — which is the point of the setting, since a dropdown that opens on an environment is meant
    // to open with that environment's rows under it. Not awaited, for the same reason a pick is
    // not: the value is settled here and now, and what hangs off it fills in as it arrives.
    // Skipped on a repaint, which is putting back what was already there rather than choosing it.
    if (picked && !quiet) select.dispatchEvent(new Event('change'));
}

/**
 * The actions a control actually runs: the page-level ones it names, in the order it names them,
 * then any written directly onto it. Both forms are honoured because the inline form predates the
 * page library and every page saved before it must keep working; a control that has been moved
 * over to the library simply has nothing left in the inline list.
 */
function actionsFor(control) {
    return actionsByIds(control.actionIds).concat(control.actions || []);
}

/** Page-level actions by id, skipping any the library no longer holds. */
function actionsByIds(ids) {
    return (ids || []).map(id => (page.actions || []).find(a => a.actionId === id)).filter(Boolean);
}

/** The assignments a control really applies: a row with no target is an unfinished one. */
function assignmentsOf(control) {
    return (control.assignments || []).filter(a => a.targetControlId);
}

/**
 * What a control does when it is triggered — clicked, or changed, depending on how it is wired:
 * it writes the values it was told to write, then runs its actions. Either half may be empty. A
 * select that only fills in a text box is a whole control, and so is one that only reloads a
 * grid; the two together are the ordinary case of picking something and looking it up.
 */
function runControlActions(control, element) {
    // The moment this trigger fired, settled before its assignments read a variable and before
    // its actions resolve an input against one — see #refreshGlobals.
    refreshGlobals();
    const actions = actionsFor(control);
    const label = control.label || controlTitle(control);
    // Recorded before it runs rather than after: a trigger that failed is the one most worth
    // being able to send again once whatever it fell over is fixed. A control that neither sets
    // nor runs anything is not recorded at all — replaying it would only repeat the complaint
    // that it is misconfigured, which is a job for the designer rather than for this button.
    if (actions.length || assignmentsOf(control).length) {
        lastTrigger = { controlId: control.controlId, label: label };
        renderRunTools();
    }
    // Everything these actions are aimed at is emptied before the calls go out, so one that
    // fails leaves its part of the page blank rather than showing the previous trigger's rows
    // underneath the inputs that did not produce them.
    // Picking a different environment and getting an error has to look like nothing came back,
    // because nothing did; a grid still holding the old environment's rows reads as if it had.
    clearActionTargets(actions, control.controlId);

    // Emptied first, written second: an assignment aimed at a control an action also fills is
    // this trigger's own value and has to survive the emptying rather than be undone by it.
    errors = [];
    const configured = assignmentsOf(control).length;
    const assigned = applyAssignments(control, label);
    renderErrors();

    if (!actions.length) {
        // Putting a value somewhere is a complete job. Only a control that neither sets nor runs
        // anything is misconfigured — and worth saying so, since it looks alive and does nothing.
        // Judged on what was configured, not on what landed: assignments that were written and
        // then failed have already said so, and "no values to set" would contradict them.
        if (!configured) addError('"' + label + '" has nothing to do — no actions, and no values to set.');
        else AC.setStatus('runStatus', errors.length ? ''
            : assigned + (assigned > 1 ? ' values' : ' value') + ' set.', 'ok');
        // Setting values is a complete job, so a trigger that only sets them still scrolls to
        // what it named — the label it just filled in is as worth being shown as a grid is.
        focusAfterRun(control);
        return;
    }
    return thenFocus(runActions(actions, label, element, true), control);
}

/**
 * A cell in a clickable column: put values from the row that was clicked onto the page, then run
 * what that column runs.
 *
 * <p>The same shape as {@link #runControlActions} and for the same reasons — the targets are
 * emptied before the calls go out, the values land before the actions read them — with one
 * difference that is the whole point of it: the clicked row is in scope, so an assignment value
 * of <code>${orderId}</code> is the id in the row the operator pointed at rather than whatever
 * a box on the page happened to hold.
 *
 * <p>The row is taken out of the filtered, sorted view rather than out of the rows as they
 * arrived, because that is the one the operator can see to click. It is looked up again here
 * rather than captured when the cell was drawn: anything that changes the view repaints the
 * rows, so the index is never read against a view it was not written for.
 */
function runColumnLink(gridId, column, rowIndex, cell) {
    refreshGlobals();
    const grid = gridOwner(gridId);
    const link = grid && columnLinkNamed(grid, column);
    const state = gridState[gridId];
    if (!link || !state) return;

    const row = visibleRows(state)[rowIndex];
    if (row === undefined) return;

    const actions = actionsByIds(link.actionIds);
    const label = controlTitle(grid) + ' · ' + column;
    // Held with the row itself rather than with its index, so a replay asks about the row that
    // was actually clicked even after a filter has moved it or another call has replaced the
    // rows underneath it.
    lastTrigger = { controlId: gridId, column: column, row: row, label: label };
    renderRunTools();
    clearActionTargets(actions, gridId);

    errors = [];
    const assignments = (link.assignments || []).filter(a => a.targetControlId);
    const assigned = applyRowAssignments(assignments, row, cellText(row, column), label);
    renderErrors();

    if (!actions.length) {
        // Putting the clicked row's id where the rest of the page can read it is a complete job;
        // the save already refuses a column that does neither, so there is nothing to warn about.
        if (!errors.length) {
            AC.setStatus('runStatus', assigned + (assigned === 1 ? ' value' : ' values') + ' set.', 'ok');
        }
        focusAfterRun(grid);
        return;
    }
    // Named on the grid that was clicked: drilling into a row is the case the setting was written
    // for — the detail lands somewhere else on the page, and that is where the operator is going.
    return thenFocus(runActions(actions, label, cell, true), grid);
}

/**
 * The control whose clickable columns and rows a grid on the running page answers to: a placed
 * grid itself, or — for a grid a pie with grids opened (see #pieGridId) — that pie. Nothing for a
 * stacked grid or one a "new grid" target built.
 */
function gridOwner(gridId) {
    const control = findControl(gridId);
    if (control) return GRID_OWNER_TYPES.includes(control.type) ? control : null;
    const made = /^pg-(.+)-\d+$/.exec(String(gridId || ''));
    const owner = made && findControl(made[1]);
    return owner && owner.type === 'piegrid' ? owner : null;
}

/**
 * What a grid's rows do when they are clicked, or nothing. Only a placed grid control has an
 * answer: a stacked grid and the one a "new grid" target builds have no control behind them to
 * have been configured, the same reason their cells are text.
 */
function rowClickOf(gridId) {
    const control = gridOwner(gridId);
    if (!control) return null;
    const click = control.rowClick;
    if (!click || (!(click.assignments || []).length && !(click.actionIds || []).length)) return null;
    return click;
}

/**
 * A row clicked: put the row onto the page, then run what the grid runs.
 *
 * <p>The same shape as {@link #runColumnLink}, and the difference is the one the setting exists
 * for: what a blank assignment hands over. A column has a cell the operator pointed at, and that
 * cell is what travels; a row has no one cell, so the whole row travels — as the JSON object it
 * already is, which is the shape a hidden field can hold and an action can send on whole.
 *
 * <p>The row is taken out of the filtered, sorted view for the reason a column link's is: that is
 * the one the operator could see to click. It is looked up again here rather than captured when
 * the row was drawn, so the index is never read against a view it was not written for.
 */
function runRowClick(gridId, rowIndex, element) {
    refreshGlobals();
    const grid = gridOwner(gridId);
    const click = rowClickOf(gridId);
    const state = gridState[gridId];
    if (!click || !state) return;

    const row = visibleRows(state)[rowIndex];
    if (row === undefined) return;

    const actions = actionsByIds(click.actionIds);
    const label = controlTitle(grid) + ' · row';
    // Held with the row itself rather than with its index, so a replay asks about the row that
    // was actually clicked even after a filter has moved it or another call has replaced the
    // rows underneath it.
    lastTrigger = { controlId: gridId, rowClick: true, row: row, label: label };
    renderRunTools();
    clearActionTargets(actions, gridId);

    errors = [];
    const assigned = applyRowAssignments((click.assignments || []).filter(a => a.targetControlId),
        row, rowJson(row), label);
    renderErrors();

    if (!actions.length) {
        // Putting the clicked row where the rest of the page can read it is a complete job; the
        // save already refuses a row click that does neither, so there is nothing to warn about.
        if (!errors.length) {
            AC.setStatus('runStatus', assigned + (assigned === 1 ? ' value' : ' values') + ' set.', 'ok');
        }
        focusAfterRun(grid);
        return;
    }
    return thenFocus(runActions(actions, label, element, true), grid);
}

/**
 * The clicked row as the one value a blank row-click assignment hands over: the JSON object it
 * already is, columns and all, so a hidden field can hold it and an action can send it on whole.
 * Laid out flat rather than indented — it is going into a box, an input template or a request
 * body, and none of those is read down the page.
 */
function rowJson(row) {
    if (row === undefined || row === null) return '';
    return typeof row === 'object' ? JSON.stringify(row) : String(row);
}

/**
 * Writes a clickable column's assignments, reading each value against the clicked row, and hands
 * back how many landed. The control form of this is {@link #applyAssignments}; they differ only
 * in where a value comes from.
 */
function applyRowAssignments(assignments, row, cellValue, label) {
    let done = 0;
    assignments.forEach(assignment => {
        const target = findControl(assignment.targetControlId);
        if (!target) {
            addError(label + ': cannot set a control that is no longer on this page.');
            return;
        }
        const value = rowTemplate(assignment.value, row, cellValue);
        if (setControlValue(target, value)) done++;
        else addError(label + ': "' + value + '" is not one of the options in "' + controlTitle(target) + '".');
    });
    paintTemplatedLinks();
    return done;
}

/**
 * What one of a clickable column's assignments hands over: the text it was written with, with
 * <code>${field}</code> read off the clicked row first and off the page's own controls for
 * whatever the row does not answer — so <code>${orderId}</code> is the row's id while
 * <code>${env}</code> beside it is still what the environment select is showing. Blank hands
 * over the clicked cell itself, the way a blank assignment on a control hands over that
 * control's value.
 *
 * <p>A placeholder neither answers becomes empty rather than throwing, which is where this parts
 * company with {@link #resolvePath}: a path that silently matched nothing would hand back an
 * empty grid with no explanation, while an assignment that lands empty is on the page in a box
 * the operator can see.
 */
function rowTemplate(template, row, cellValue) {
    const text = (template || '').trim();
    if (!text) return cellValue;
    return text.replace(/\$\{([A-Za-z0-9_.\-]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g, (match, braced, bare) => {
        const field = braced || bare;
        const fromRow = rowField(row, field);
        const value = (fromRow === undefined || fromRow === null) ? values[field] : fromRow;
        if (value === undefined || value === null) return '';
        return typeof value === 'object' ? JSON.stringify(value) : String(value);
    });
}

/**
 * Writes this control's assignments into the controls they name, in the order they are listed,
 * and hands back how many landed.
 *
 * <p>Run before the control's actions, which is the point of them: picking an option can put
 * that choice in the box an action then sends as <code>${orderId}</code>, and the mandatory
 * check the actions start with sees the filled-in field rather than the empty one.
 *
 * <p>A value arriving in a control does not set off that control's own trigger. It is not the
 * operator changing it, and one control silently starting another's actions is a page nobody can
 * follow; whatever should also run belongs on this control, after the assignment.
 */
function applyAssignments(control, label) {
    let done = 0;
    assignmentsOf(control).forEach(assignment => {
        const target = findControl(assignment.targetControlId);
        if (!target) {
            addError(label + ': cannot set a control that is no longer on this page.');
            return;
        }
        const value = assignmentValue(control, assignment);
        if (setControlValue(target, value)) done++;
        else addError(label + ': "' + value + '" is not one of the options in "' + controlTitle(target) + '".');
    });
    // A value has just landed in a control, so a link written over that control now points
    // somewhere else — see #paintTemplatedLinks.
    paintTemplatedLinks();
    return done;
}

/**
 * What one assignment hands over: the text it was written with, with <code>${fieldName}</code>
 * filled in from the page — or, left blank, this control's own value. Blank on a button or a
 * link, which hold no value of their own, therefore empties the target, which is how a "clear
 * the form" control is written.
 */
function assignmentValue(control, assignment) {
    const template = (assignment.value || '').trim();
    if (template) return resolveTemplate(template);
    const own = values[control.fieldName];
    return own === undefined || own === null ? '' : String(own);
}

/**
 * Puts a value into a control and into the page's record of it together, so an action reading
 * <code>${fieldName}</code> straight afterwards sees it.
 *
 * <p>False when a select was handed something it has no option for: the box would show one thing
 * while the page held another, so it holds nothing and the caller says what happened.
 */
function setControlValue(control, text) {
    if (control.type === 'label') {
        const host = document.querySelector('#rc-' + CSS.escape(control.controlId) + ' .static-label');
        if (host) host.textContent = text;
        return true;
    }
    const input = document.querySelector('#rc-' + CSS.escape(control.controlId) + ' [data-field]');
    if (control.type === 'checkbox') {
        const on = text === 'true' || text === '1' || text === 'on';
        values[control.fieldName] = on;
        if (input) input.checked = on;
        return true;
    }
    // Assigning into a multi-select is choosing the options the value names — all of them, so
    // one value can put a whole set of picks in place. What it holds afterwards is what the list
    // actually had options for, and it says so when that is less than it was handed.
    if (control.type === 'multiselect') {
        const wanted = multiParts(text);
        values[control.fieldName] = wanted.join(MULTI_SEPARATOR);
        if (!input) return true;
        [...input.options].forEach(o => { o.selected = wanted.includes(o.value); });
        values[control.fieldName] = multiValue(input);
        return wanted.length === multiParts(values[control.fieldName]).length;
    }
    if (control.type === 'textarea') text = formatText(control, text);
    // A date box takes yyyy-MM-dd and nothing else, so a value arriving in one is read the way its
    // default is — a row's 20260915, or the ${DATESTAMP} an action wrote, lands as a date rather
    // than as a box that quietly stayed empty. The box then gets that day and the page gets it in
    // the control's own format, which is the same two forms the control holds any other time.
    // Text this cannot read goes in exactly as it came, which is what every other control does
    // with a value it cannot use.
    if (control.type === 'date') {
        const iso = dateIso(control, text);
        values[control.fieldName] = iso ? dateText(control, iso) : text;
        if (input) input.value = iso || text;
        return true;
    }
    values[control.fieldName] = text;
    // A hidden control holds its value without ever being on screen to hold it.
    if (!input) return true;
    input.value = text;
    if (control.type !== 'select') return true;
    // Assigning to a select is choosing one of its options; the browser refuses anything else,
    // so what it settled on is what the page holds.
    values[control.fieldName] = input.value;
    return !text || input.value === text;
}

/**
 * Empties every control this list of actions binds into.
 *
 * <p>The control that triggered the run is skipped: it is holding the value the operator has
 * just chosen, and an action that refills its own dropdown would otherwise throw that choice
 * away the moment the call behind it failed. A "new grid" target is skipped too — it builds
 * another grid per run rather than overwriting one, so it has nothing of its own to go stale.
 * So is a grid this run is adding to: emptying it first is exactly what appending is asking not
 * to happen, and the rows it already holds are the point of the setting.
 */
function clearActionTargets(actions, triggeredById) {
    const cleared = new Set();
    (actions || []).forEach(action => bindingsOf(action).forEach(binding => {
        const id = binding.targetControlId;
        if (!id || id === NEW_GRID || id === triggeredById || cleared.has(id)) return;
        if (appendsToGrid(binding)) return;
        cleared.add(id);
        const target = findControl(id);
        if (target) clearControl(target);
    }));
}

/**
 * Whether this binding adds its rows to what its grid already holds rather than replacing them.
 * Asked of the control as well as of the setting: a page saved with it on and then re-laid out
 * so the target is a select, a chart or nothing at all has an append that no longer means
 * anything, and it must not then keep the old target from being emptied.
 */
function appendsToGrid(binding) {
    if (!binding || !binding.appendRows) return false;
    const id = binding.targetControlId;
    // A "new grid" target already keeps every run — as a grid each, rather than as one table.
    if (!id || id === NEW_GRID) return false;
    const target = findControl(id);
    return !!target && target.type === 'grid';
}

/** One control back to the state it was in before anything had been bound into it. */
function clearControl(control) {
    if (control.type === 'tabs') {
        // Only the tabs a fan-out added go: the ones laid out in the designer are the page, and
        // an action aimed at one of those grids clears that grid on its own account.
        clearFanTabs(control.controlId, null);
        paintTabs(control);
        return;
    }
    if (control.type === 'grid') {
        // Dropped rather than set to no rows: "No data yet" is the truthful thing to say before
        // a call has answered, where "No rows returned" would claim one already had. The last
        // call's own record goes with them for the same reason — a status and a URL left behind
        // would be describing a call whose rows are no longer on the page.
        delete gridState[control.controlId];
        delete gridMeta[control.controlId];
        paintGrid(control.controlId);
        return;
    }
    if (isChart(control.type)) {
        // Dropped rather than emptied, so the chart goes back to the slices the designer typed
        // in — which is what it showed before anything was bound, and the truthful thing to show
        // again. The last call's record goes with them, for the reason a grid's does: a status
        // and a URL left behind would describe a call whose wedges are no longer on the page.
        clearChartData(control);
        delete pieMeta[control.controlId];
        paintChart(control);
        return;
    }
    if (isSelect(control.type)) {
        fillOptions(control, []);
        return;
    }
    if (control.type === 'link') {
        // Emptied rather than put back to the link's own URL, exactly as a text box is emptied
        // rather than put back to its default: the address the last call named is gone, and
        // leaving one behind would offer a destination this run has not produced.
        //
        // A link that opens another page is the exception, and is not really one: that address
        // is the control rather than something a call produced, so there is nothing there to go
        // stale and clearing it would break a link no action ever filled in.
        linkUrls[control.controlId] = pageLinkUrl(control);
        paintLink(control);
        return;
    }
    values[control.fieldName] = '';
    const input = document.querySelector('#rc-' + CSS.escape(control.controlId) + ' [data-field]');
    if (input) input.value = '';
}

/**
 * Runs a list of actions: nothing goes out until every mandatory field is filled, then all of
 * them go out together and the page waits for the lot. A trigger with six actions behind it
 * costs about one round trip rather than six, which is the point of doing it this way — the
 * calls do not depend on one another, and making the fifth wait on the fourth only made the
 * page slower.
 *
 * <p>Fired together, bound in the order they are listed. Binding is where the page changes, so
 * a stacked grid, an error and the status line all read as the order the actions were written
 * in rather than as whichever call happened to answer first: the same trigger produces the same
 * page every time, however the network staggered the responses.
 *
 * <p>An action that names another under Runs After is held out of that first wave and sent once
 * the one it waits for has come back and bound. Only then are its inputs and its environment
 * resolved, which is the whole reason to wait: they read the page as the earlier action left it,
 * so one call can genuinely feed the next. Actions waiting on the same action form a wave of
 * their own and still go out together, so a chain costs a round trip per level rather than one
 * per action, and an action with nothing to wait for never waits for anything.
 *
 * <p>A failure stops what was waiting on it and nothing else. The rest of its own wave are
 * already in flight by the time it comes back bad; everything downstream of it is not sent at
 * all and says so, since an action whose input was to come out of a call that failed has nothing
 * to send. Every action is reported on and every problem is listed, rather than the first error
 * standing in for all of them.
 *
 * <p>A metadata action binds whatever its call did, so a failed call still fills in the URL and
 * the status code that explain it.
 */
async function runActions(actions, label, element, keepErrors) {
    // Kept when the caller has already put something in the list: a control's assignments run
    // before its actions and report into the same place.
    if (!keepErrors) errors = [];
    renderErrors();
    AC.setStatus('runStatus', '');
    // Dropped before the checks below rather than after them: a trigger that never got as far
    // as sending anything has no technical details, and offering the previous trigger's under
    // this one's name would be worse than offering nothing.
    lastRun = null;
    renderRunTools();

    const missing = page.controls.filter(c => c.mandatory && VALUE_TYPES.includes(c.type)
        && (values[c.fieldName] === '' || values[c.fieldName] === undefined || values[c.fieldName] === null));
    if (missing.length) {
        missing.forEach(c => addError((c.label || c.fieldName) + ' is required.'));
        return;
    }
    if (!actions.length) {
        addError('"' + label + '" has no actions configured.');
        return;
    }

    if (element) element.classList.add('busy');
    AC.setStatus('runStatus', 'Running ' + actions.length + ' action' + (actions.length > 1 ? 's' : '') + '…');
    beginCallBatch(actions);
    try {
        const names = actions.map(a => a.actionLabel || a.appUseCaseInstanceId || 'Action');
        const plan = runWaves(actions);

        // What the page put on the wire, which is a different thing from what the instance was
        // saved with — the technical details are only worth reading if they report the former.
        // The inputs and the environment are filled in as each action is about to be sent rather
        // than all at once up front: an action in a later wave resolves its own against the page
        // the wave before it left behind, and one that is never sent has none to report.
        const record = actions.map((action, i) => ({
            name: names[i],
            instanceId: action.appUseCaseInstanceId,
            inputs: null,
            environment: '',
            metadataOnly: isMetadataOnly(action),
            // Marked rather than left out of the record: an action that produced rows on the
            // page and no entry here would read as one the trigger skipped. It is in the list
            // saying what it is, which is that there was no call to report.
            performance: isPerformanceAction(action),
            // A comparison replaces this entry with one per side the moment it is sent, so this
            // is what the record says about it only if it never got that far.
            compare: isCompareAction(action),
            // As with a summary: marked rather than left out, so an action that filled a grid off a
            // dataset is in the list saying what it is rather than reading as one that was skipped.
            dataset: isDatasetAction(action),
            datasetName: action.datasetName || '',
            result: null,
            error: ''
        }));
        lastRun = { label: label, at: Date.now(), calls: record };
        // What each fan-out did, since "3 of 4 actions completed" says nothing about the forty
        // calls one of those actions turned into, or about the rows its cap left alone.
        const fanNotes = [];

        let done = 0;
        const succeeded = new Array(actions.length).fill(false);
        // What each action resolved its templates against, kept so the paths that read its
        // answer are resolved against the same thing its request was. Filled as each call is
        // about to go out, for the same reason the inputs beside it are.
        const scopes = new Array(actions.length).fill(null);
        // Not sent, and why. It reads into the same places a failure does — the error list, the
        // grid or the chart that was to be filled — because from the page's point of view an
        // action that could not go out and one that went out and failed leave the same hole.
        const notSent = (i, why) => {
            record[i].error = why;
            noteTargetFailure(actions[i], names[i], null, why, i);
            addError(why);
        };

        for (const wave of plan.waves) {
            // Whoever was waiting on something that did not come back has nothing to send.
            const live = [];
            wave.forEach(i => {
                const on = plan.waitsFor[i];
                if (on < 0 || succeeded[on]) live.push(i);
                else notSent(i, names[i] + ' was not sent: it waits for "' + names[on] + '", which did not succeed.');
            });
            if (!live.length) continue;

            // Every call in the wave is started before any of them is waited on — that is the
            // whole of the parallelism. Two actions resolving to the same instance, environment
            // and inputs still share one flight: the batch caches the promise, not the answer,
            // so asking at the same moment is exactly the case it was built for.
            //
            // Rejections are turned into values here rather than left to the await below. A
            // promise that fails while the page is still waiting on its siblings has nobody
            // handling it yet, and the browser would report it as unhandled before the loop
            // below ever reached it.
            const calls = live.map(i => {
                // A performance action makes no outward call at all — it asks this server to
                // summarise what it already knows. Its filters are resolved against the page
                // exactly as an ordinary action's inputs are, so a grid under an app dropdown
                // narrows as the operator chooses.
                if (isPerformanceAction(actions[i])) {
                    record[i].inputs = resolveInputs(actions[i].inputs, actionScope(null));
                    return Promise.resolve()
                        .then(() => runPerformance(record[i].inputs, names[i]))
                        .then(rows => ({ rows: rows }), error => ({ error: error }));
                }
                // A comparison is one action and two calls, sent together against two
                // environments. Like a fan-out it writes its own entries into the record — one
                // per side — so both requests and both responses are there to be read after.
                if (isCompareAction(actions[i])) {
                    return Promise.resolve()
                        .then(() => runCompare(actions[i], names[i], record, i))
                        .then(cmp => ({ cmp: cmp }), error => ({ error: error }));
                }
                // A dataset action makes no outward call either — it asks the dataset library for
                // the rows it already holds. Its conditions are resolved against the page exactly
                // as an ordinary action's inputs are, so a grid under a region dropdown narrows as
                // the operator chooses, and what it asked is kept for the record.
                if (isDatasetAction(actions[i])) {
                    const asked = datasetQueryOf(actions[i]);
                    record[i].inputs = asked.described;
                    return Promise.resolve()
                        .then(() => runDataset(actions[i], names[i], asked.query))
                        .then(rows => ({ dsRows: rows }), error => ({ error: error }));
                }
                // A fan-out is one action and many calls. It resolves its own inputs a row at a
                // time and writes its own entries into the record, so nothing is resolved for it
                // here; what comes back is every row's answer rather than one.
                if (isFanOut(actions[i])) {
                    return Promise.resolve()
                        .then(() => runFanOut(actions[i], names[i], record, i))
                        .then(fan => ({ fan: fan }), error => ({ error: error }));
                }
                // One scope for this call, settled before any of it is resolved, so a $UUID in
                // the body and the same $UUID in the path that reads the answer are one value.
                scopes[i] = actionScope(null);
                record[i].inputs = resolveInputs(actions[i].inputs, scopes[i]);
                record[i].environment = resolveTemplate(actions[i].environmentOverride, scopes[i]);
                return Promise.resolve()
                    .then(() => runExecution(record[i].instanceId, record[i].inputs, names[i],
                            record[i].environment, record[i].metadataOnly, actions[i].ownCall))
                    .then(result => ({ result: result }), error => ({ error: error }));
            });

            // Bound in the order the actions were listed, not in the order they answered, so the
            // same trigger produces the same page however the network staggered the responses.
            for (let k = 0; k < live.length; k++) {
                const i = live[k];
                const action = actions[i];
                const name = names[i];
                const settled = await calls[k];
                const result = settled.result === undefined ? null : settled.result;
                // The record gets what is worth keeping; everything below binds from `result`
                // itself, which is whole whatever the switch says. See #runDetail.
                if (!settled.fan && !settled.rows && !settled.cmp && !settled.dsRows) record[i].result = runDetail(result);
                try {
                    if (settled.error) throw settled.error;

                    // A summary is rows and nothing else — there is no call behind it whose
                    // status or URL a grid could report — so it goes straight in under the
                    // columns it is known to have.
                    if (settled.rows) {
                        bindPerformance(action, name, settled.rows, i);
                        done++;
                        succeeded[i] = true;
                        continue;
                    }

                    // The same for a dataset's rows: they arrived without a call behind them, so
                    // there is no status or URL for the grid to report — only which list they are.
                    if (settled.dsRows) {
                        await bindDataset(action, name, settled.dsRows, i);
                        done++;
                        succeeded[i] = true;
                        continue;
                    }

                    // A comparison has made both its calls and reported both; what is left is to
                    // read the two answers and put what differs where it was aimed. The line it
                    // hands back goes in the status beside a fan-out's, since "one action
                    // completed" says nothing about whether the two environments agreed.
                    if (settled.cmp) {
                        fanNotes.push(await bindCompare(action, name, settled.cmp, i));
                        done++;
                        succeeded[i] = true;
                        continue;
                    }

                    // A fan-out has already made its calls and already reported each of them;
                    // what is left is to put the answers where they were aimed. It counts as
                    // succeeded once it has, so an action waiting on it reads a page that is
                    // filled in — the same rule every other action answers to.
                    if (settled.fan) {
                        fanNotes.push(await bindFanOut(actions[i], names[i], settled.fan));
                        done++;
                        succeeded[i] = true;
                        continue;
                    }

                    const failure = failureMessage(result, name);
                    if (!failure) {
                        // Every target is bound, even after one of them could not be: the grid
                        // whose path was wrong says so, and the select beside it still fills.
                        const problems = await bindEveryTarget(action, name, result, i, scopes[i]);
                        if (problems.length) {
                            record[i].error = problems.join(' ');
                            problems.forEach(problem => addError(problem, i));
                            continue;
                        }
                        done++;
                        // Counted as succeeded only once it has bound, since that is what anything
                        // waiting on it is waiting for: a call that came back 200 and whose response
                        // no path could be read out of has put nothing on the page to be read.
                        succeeded[i] = true;
                    } else {
                        // A failure is bound as well as reported, whenever there is anything to
                        // bind. A metadata action always has something — the status code of a
                        // failure is the whole reason someone put a metadata panel on the page —
                        // and a payload action has something whenever the call answered with a
                        // body: a 400 that explains itself in JSON is worth reading, and the
                        // action's transforms are exactly what turn it into rows. The grid,
                        // chart or panel still says the call failed, since its record carries
                        // the failure with it.
                        const why = await bindFailure(action, name, result, i, failure, scopes[i]);
                        record[i].error = why;
                        addError(why, i);
                        // Left as not succeeded whatever was bound: an action waiting on this one
                        // is waiting for an answer, and a 500 with a body is not one.
                    }
                } catch (e) {
                    // The grid or chart this action was aimed at says so, rather than staying
                    // empty and leaving the error list at the top of the page as the only sign
                    // anything went out at all. Then the next action is reported on as well: it
                    // went out too, and saying nothing about it would leave the page half
                    // explained.
                    record[i].error = e.message || String(e);
                    noteTargetFailure(action, name, result, e.message || String(e), i);
                    addError(e.message || String(e), i);
                }
            }
        }

        // Anything left in a cycle, reported by name. Nothing in one can go first, so nothing in
        // one could ever go at all — and a page that quietly ran four of its six actions would
        // be far harder to account for than one that says which two it could not run.
        plan.cyclic.forEach(i => notSent(i, names[i] + ' was not sent: it and "'
            + names[plan.waitsFor[i]] + '" are waiting on each other, so neither could go first.'));

        AC.setStatus('runStatus', errors.length ? '' : done + ' of ' + actions.length + ' action'
            + (actions.length > 1 ? 's' : '') + ' completed.'
            + (fanNotes.length ? ' ' + fanNotes.join(' ') : ''), 'ok');
    } finally {
        endCallBatch();
        if (element) element.classList.remove('busy');
        // The details button only means anything once there is a run behind it, and this is the
        // moment there is one — including when the run went badly, which is when it is read.
        renderRunTools();
        // Every link written over the page, once, now the run has finished putting values into it:
        // an address built out of a field an action has just filled in is only right after it has.
        paintTemplatedLinks();
        // A page running inside another one tells its parent what this trigger's actions did.
        if (lastRun) reportRunToParent(lastRun);
    }
}

// ── Child pages ──────────────────────────────────────────────────────────

/** Whether this page is running inside a parent page's page control. */
function isChildPage() {
    return !!EMBED_ID && window.parent && window.parent !== window;
}

/**
 * A child page's name as a link to the page itself — its standalone running form, the same
 * address the designer's <b>Open standalone</b> hands out — opened in its own tab, because the
 * frame it is named over is the copy embedded here and following the name should not throw the
 * parent away. Plain text where nothing is picked or the name is not in the catalog: a link to
 * a page that is not there tells the reader less than the bare name does.
 *
 * @param name the page the control embeds
 * @param text the heading as it should read, already escaped
 */
function childPageLink(name, text) {
    if (!name || !pages.some(p => p.pageName === name)) return text;
    const href = '/apppage.html?page=' + encodeURIComponent(name) + '&mode=run';
    return '<a class="child-page-link" href="' + AC.esc(href) + '" target="_blank" rel="noopener"'
        + ' title="Open &quot;' + AC.esc(name) + '&quot; in its own tab">' + text + '</a>';
}

/**
 * A page control as it runs: its heading with the child's tally, and the child page in a frame.
 * The frame is only created here, and renderRun only runs when the page opens or is reset, so the
 * child keeps its state for as long as the parent is left alone.
 */
function childPageRun(c, style) {
    const title = AC.esc(c.label || c.childPageName || 'Page');
    const head = '<div class="child-head"><label' + style + '>' + childPageLink(c.childPageName, title) + '</label>'
        + '<span class="child-counts" data-child-counts="' + AC.attr(c.controlId) + '"></span></div>';
    if (!c.childPageName) return head + '<div class="empty-note">No page picked for this control.</div>';
    if (!pages.some(p => p.pageName === c.childPageName)) {
        return head + '<div class="empty-note">Page "' + AC.esc(c.childPageName) + '" is not in the catalog.</div>';
    }
    if (CHILD_DEPTH >= MAX_CHILD_DEPTH) {
        return head + '<div class="empty-note">Not opened: pages are nested more than ' + MAX_CHILD_DEPTH + ' deep here.</div>';
    }
    const src = 'apppage.html?page=' + encodeURIComponent(c.childPageName) + '&mode=run'
        + '&embed=' + encodeURIComponent(c.controlId) + '&depth=' + (CHILD_DEPTH + 1);
    return head + '<iframe data-child-page="' + AC.attr(c.controlId) + '" src="' + AC.attr(src) + '"'
        + ' title="' + AC.attr(c.childPageName) + '"></iframe>';
}

/**
 * What one call of a trigger comes to in a child's report: enough to count it and to say why it
 * failed, without the request and response bodies, which stay in the child's Technical Details.
 */
function childCallSummary(call) {
    const result = call.result || {};
    return {
        name: call.name || '',
        ok: !call.error,
        error: call.error || '',
        instanceId: call.instanceId || '',
        environment: call.environment || result.environment || '',
        inputs: call.inputs || null,
        performance: !!call.performance,
        dataset: !!call.dataset,
        status: result.status || '',
        statusCode: result.statusCode === undefined ? null : result.statusCode,
        httpMethod: result.httpMethod || '',
        url: result.url || '',
        timeTaken: result.timeTaken === undefined ? null : result.timeTaken,
        appName: result.appName || '',
        useCase: result.useCase || ''
    };
}

function reportRunToParent(run) {
    if (!isChildPage()) return;
    postToParent({
        type: CHILD_MESSAGE,
        path: [page.title || page.pageName || 'Page'],
        label: run.label || '',
        at: run.at || Date.now(),
        calls: (run.calls || []).map(childCallSummary)
    });
}

function postToParent(message) {
    try {
        window.parent.postMessage(message, location.origin);
    } catch (e) {
        // A parent that cannot be told is a parent without a tally; the page itself still works.
    }
}

/**
 * A report from one of this page's child frames. Which control it belongs to is decided by the
 * frame that sent it, not by anything in the message, so a stale frame from before a reset — or
 * anything else on the page posting messages — is simply not counted. A page that is itself a
 * child passes the report on up, so its parent's tally includes the pages nested inside it.
 */
function onChildReport(e) {
    if (e.origin !== location.origin) return;
    const data = e.data;
    if (!data || data.type !== CHILD_MESSAGE || !Array.isArray(data.calls)) return;
    const frame = [...document.querySelectorAll('iframe[data-child-page]')]
        .find(f => f.contentWindow === e.source);
    if (!frame) return;
    const controlId = frame.dataset.childPage;
    const path = Array.isArray(data.path) ? data.path.map(String) : [];
    const run = { path: path, label: String(data.label || ''), at: Number(data.at) || Date.now(), calls: data.calls };
    (childRuns[controlId] = childRuns[controlId] || []).push(run);
    paintChildSummary();
    if (isChildPage()) {
        postToParent(Object.assign({}, data, { path: [page.title || page.pageName || 'Page'].concat(path) }));
    }
    if (childDetails && (childDetails.controlId === null || childDetails.controlId === controlId)) {
        renderChildFailures();
    }
}
window.addEventListener('message', onChildReport);

/** Every call a child page has reported, with the trigger it belongs to beside it. */
function childCalls(controlId) {
    const out = [];
    (childRuns[controlId] || []).forEach(run => run.calls.forEach(call => out.push({ run: run, call: call })));
    return out;
}

function childTally(controlId) {
    const calls = childCalls(controlId);
    const failed = calls.filter(x => !x.call.ok).length;
    return { triggers: (childRuns[controlId] || []).length, total: calls.length, ok: calls.length - failed, failed: failed };
}

function childPageControls() {
    return page.controls.filter(c => c.type === 'page');
}

function tallyHtml(controlId, t) {
    if (!t.total) return '<span class="child-none">No actions run yet</span>';
    return '<span class="child-ok" title="Actions that succeeded">✓ ' + t.ok + ' succeeded</span>'
        + '<button type="button" class="child-fail" data-child-fail="' + AC.attr(controlId) + '"'
        + (t.failed ? ' title="Show the actions that failed"' : ' disabled') + '>✗ ' + t.failed + ' failed</button>';
}

/**
 * The tallies, drawn into each page control's heading and into the panel above the canvas that
 * lists every child page on this one together.
 */
function paintChildSummary() {
    const children = childPageControls();
    document.querySelectorAll('[data-child-counts]').forEach(el => {
        el.innerHTML = tallyHtml(el.dataset.childCounts, childTally(el.dataset.childCounts));
    });

    const host = document.getElementById('childSummary');
    if (!host) return;
    if (!children.length) { host.innerHTML = ''; return; }
    const tallies = children.map(c => ({ c: c, t: childTally(c.controlId) }));
    const failed = tallies.reduce((n, x) => n + x.t.failed, 0);
    host.innerHTML = '<div class="child-summary">'
        + '<div class="child-summary-title"><span>Child Pages</span>'
            + (failed ? '<button type="button" class="tool-btn" data-child-fail-all="1">All failures (' + failed + ')</button>' : '')
        + '</div>'
        + '<table><thead><tr><th>Page</th><th class="num">Triggers</th><th class="num">Actions</th><th>Result</th></tr></thead><tbody>'
        + tallies.map(x =>
            '<tr><td>' + childPageLink(x.c.childPageName, AC.esc(x.c.label || x.c.childPageName || '(no page)'))
                + (x.c.label && x.c.childPageName ? ' <span class="hint">' + AC.esc(x.c.childPageName) + '</span>' : '') + '</td>'
            + '<td class="num">' + x.t.triggers + '</td>'
            + '<td class="num">' + x.t.total + '</td>'
            + '<td><span class="child-counts">' + tallyHtml(x.c.controlId, x.t) + '</span></td></tr>').join('')
        + '</tbody></table></div>';
}

// Delegated, since the tallies are redrawn every time a report arrives.
document.addEventListener('click', e => {
    const one = e.target.closest('[data-child-fail]');
    if (one && !one.disabled) { showChildFailures(one.dataset.childFail); return; }
    if (e.target.closest('[data-child-fail-all]')) showChildFailures(null);
});

// The failures panel while it is open: { controlId } for one child page, or controlId null for all.
let childDetails = null;

function showChildFailures(controlId) {
    childDetails = { controlId: controlId };
    renderChildFailures();
}

function closeChildFailures() {
    childDetails = null;
    const host = document.getElementById('childDetailsHost');
    if (host) host.innerHTML = '';
}

function renderChildFailures() {
    const host = document.getElementById('childDetailsHost');
    if (!host || !childDetails) return;
    const controls = childDetails.controlId === null ? childPageControls()
        : childPageControls().filter(c => c.controlId === childDetails.controlId);
    const failures = [];
    controls.forEach(c => childCalls(c.controlId).forEach(x => { if (!x.call.ok) failures.push(Object.assign({ control: c }, x)); }));
    // Newest first: the failure somebody just watched happen is the one they clicked for.
    failures.sort((a, b) => b.run.at - a.run.at);

    const title = childDetails.controlId === null ? 'All child pages'
        : (controls[0] ? (controls[0].label || controls[0].childPageName) : 'Child page');
    const row = (label, value) => value === '' || value === null || value === undefined ? ''
        : '<dt>' + AC.esc(label) + '</dt><dd>' + AC.esc(String(value)) + '</dd>';

    host.innerHTML = '<div class="editor-modal" onclick="if (event.target === this) closeChildFailures()">'
        + '<div class="editor-box">'
            + '<div class="editor-head">'
                + '<span class="editor-title">Failed actions · ' + AC.esc(title) + ' (' + failures.length + ')</span>'
                + '<button class="icon-btn" onclick="closeChildFailures()" title="Close">×</button>'
            + '</div>'
            + '<div class="editor-body">'
            + (failures.length ? '<div class="child-fail-list">' + failures.map(f => {
                const call = f.call;
                const inputs = call.inputs && Object.keys(call.inputs).length
                    ? '<dt>Inputs</dt><dd><pre>' + AC.esc(JSON.stringify(call.inputs, null, 2)) + '</pre></dd>' : '';
                return '<div class="child-fail-item">'
                    + '<div class="cf-head"><span class="cf-name">' + AC.esc(call.name || 'Action') + '</span>'
                        + '<span class="cf-when">' + AC.esc(new Date(f.run.at).toLocaleString()) + '</span></div>'
                    + '<div class="cf-error">' + AC.esc(call.error) + '</div>'
                    + '<dl>'
                        + row('Page', f.run.path.join(' › '))
                        + (childDetails.controlId === null ? row('Page control', f.control.label || f.control.childPageName) : '')
                        + row('Trigger', f.run.label)
                        + row('Status', [call.status, call.statusCode].filter(v => v !== '' && v !== null).join(' '))
                        + row('Request', [call.httpMethod, call.url].filter(Boolean).join(' '))
                        + row('Time taken', call.timeTaken === null ? '' : call.timeTaken + ' ms')
                        + row('App', call.appName)
                        + row('Use case', call.useCase)
                        + row('Environment', call.environment)
                        + row('Instance', call.instanceId)
                        + inputs
                    + '</dl>'
                + '</div>';
            }).join('') + '</div>'
                : '<div class="empty-note">No failed actions.</div>')
            + '</div>'
        + '</div>'
    + '</div>';
}

// ── Performance summaries ────────────────────────────────────────────────
// A page that has to answer "which of these endpoints is slow" used to mean leaving it, reading
// Global Runs and doing the arithmetic by eye. A performance action puts the arithmetic on the
// page: a grid of app, environment, use case, how many calls and how long they took, filled from
// the run history this server already keeps.

/**
 * The performance summary, narrowed by whatever filters the action carried.
 *
 * <p>Only the three names the endpoint understands are sent; anything else in the map is dropped
 * rather than passed on, since a filter the server does not know would either be ignored there or
 * narrow nothing here, and the designer's panel already says which names count. A filter that
 * resolved to nothing is dropped too — an empty box under a grid means "every app", not "an app
 * with no name".
 */
async function runPerformance(filters, name) {
    const query = PERFORMANCE_FILTERS
        .map(key => [key, (filters && filters[key] !== undefined && filters[key] !== null) ? String(filters[key]).trim() : ''])
        .filter(pair => pair[1] !== '')
        .map(pair => encodeURIComponent(pair[0]) + '=' + encodeURIComponent(pair[1]));
    const rows = await AC.api('GET', '/appcatalog/performance' + (query.length ? '?' + query.join('&') : ''));
    if (!Array.isArray(rows)) throw new Error(name + ': the performance summary came back in a shape this page cannot read.');
    return rows;
}

/**
 * Puts a summary where the action aimed it, under the columns it is known to have rather than
 * whatever the first row's keys enumerate — the order they are worth reading in is fixed, and a
 * summary that came back empty would otherwise arrive with no columns at all.
 */
function bindPerformance(action, name, rows, call) {
    const record = callRecord(null, 'SUCCESS', '', call,
        "summarised from this server's run history — no call made");
    if (action.targetControlId === NEW_GRID) {
        const grouped = groupedForGrid(action, rows, PERFORMANCE_COLUMNS);
        noteFilledBy(pushStackedGrid(name, grouped.rows, grouped.columns, record), action);
        return;
    }
    const target = findControl(action.targetControlId);
    if (!target) { addError(name + ': its target is no longer on this page.', call); return; }
    gridMeta[target.controlId] = record;
    // The known columns are a fallback rather than an override: a grid told which columns to
    // show was told that on purpose — a page that only cares about the average has no use for
    // four other columns — and only a grid that was left to follow its data needs to be handed
    // the order these are worth reading in.
    const grouped = groupedForGrid(action, rows, (target.columns && target.columns.length) ? null : PERFORMANCE_COLUMNS);
    // A summary is recomputed over the whole history every run, so appending is only worth
    // ticking where the two runs summarise different things — one app's endpoints, then
    // another's — and read as one table. It is the operator's call either way.
    bindGrid(target, grouped.rows, grouped.columns, appendsToGrid(action));
    noteFilledBy(target.controlId, action);
}

// ── Static datasets on a page ────────────────────────────────────────────
// The reference lists this server already holds — desks, regions, books, the services being
// watched — used to reach a page in two fixed ways: a grid wired straight to a dataset, or a
// dropdown sourced from one. Both fill themselves as the page opens and both show the whole of
// it, so a page wanting "the desks in the region just picked" had to wrap the list in a use case
// and call it over HTTP to ask a question this server could answer out of what it holds. A
// dataset action is that question as an ordinary action: it runs when something is clicked, and
// it narrows.

/**
 * What this action is about to ask the dataset library for: the saved filter it names, plus its
 * own conditions with their templates resolved against the page — and the same thing written out
 * for the record, since "which rows did this grid come from" is the first question anyone asks of
 * a filtered list.
 *
 * <p>A condition whose template resolved to nothing is dropped rather than sent. An untouched box
 * under a grid means "every region", not "the rows whose region is blank" — and the second reading
 * would quietly produce an empty grid that looks exactly like a dataset with nothing in it.
 */
function datasetQueryOf(action) {
    const scope = actionScope(null);
    const conditions = [];
    const described = {};
    if (action.datasetFavorite) described['saved filter'] = action.datasetFavorite;
    (action.datasetFilters || []).forEach(filter => {
        if (!filter || !filter.attribute) return;
        const op = filter.op || DATASET_DEFAULT_OPERATOR;
        const value = resolveTemplate(filter.value, scope);
        if (value === '') return;
        conditions.push({ attribute: filter.attribute, op: op, value: value });
        described[filter.attribute + ' ' + op] = value;
    });
    return {
        query: { favorite: action.datasetFavorite || '', conditions: conditions },
        described: Object.keys(described).length ? described : null
    };
}

/**
 * The rows, asked for by condition rather than pulled down and narrowed here — so a page taking a
 * dozen rows out of a dataset of fifty thousand is handed a dozen.
 *
 * <p>A dataset whose own load failed answers with a perfectly good HTTP 200 carrying an
 * {@code error}, since the failure is the dataset's rather than the request's. Turned into a
 * thrown error here so the action reports it the way it reports anything else that went wrong.
 */
async function runDataset(action, name, query) {
    if (!action.datasetName) throw new Error(name + ': no static dataset chosen.');
    let answer;
    try {
        answer = await AC.api('POST', '/staticdataset/' + encodeURIComponent(action.datasetName) + '/query', query);
    } catch (e) {
        // Named, because the message on its own — "Unknown favorite 'open'" — says what went wrong
        // and nothing about which of the page's actions it went wrong in.
        throw new Error(name + ': static dataset "' + action.datasetName + '" could not be read: '
            + (e.message || String(e)));
    }
    if (answer && answer.error) {
        throw new Error(name + ': static dataset "' + action.datasetName + '" could not be read: ' + answer.error);
    }
    if (!answer || !Array.isArray(answer.rows)) {
        throw new Error(name + ': the rows of "' + action.datasetName + '" came back in a shape this page cannot read.');
    }
    return answer.rows;
}

/**
 * Puts a dataset's rows where the action aimed them — a grid, a new grid, a dropdown or a chart —
 * reading each row the same way an ordinary action's would be read: the filters it keeps rows by,
 * the columns it looks up elsewhere, the group-by before the grid, the key and label that turn a
 * row into an option.
 *
 * <p>What the record says is the one thing that differs. There was no call, so there is no status,
 * no URL and no timing for a grid's metadata bar to report — and inventing one would be worse than
 * the bar saying plainly where these rows actually came from.
 */
async function bindDataset(action, name, rows, call) {
    const record = callRecord(null, 'SUCCESS', '', call,
        'read from static dataset "' + action.datasetName + '" — no call made');

    if (action.targetControlId === NEW_GRID) {
        const grouped = await datasetGridRows(action, name, rows, null, call);
        noteFilledBy(pushStackedGrid(name, grouped.rows, grouped.columns, record), action);
        return;
    }
    const target = findControl(action.targetControlId);
    if (!target) { addError(name + ': its target is no longer on this page.', call); return; }

    if (target.type === 'grid') {
        // Recorded before the rows go in, so the grid is painted once already knowing what it has
        // to say about where they came from — the same order bindAction uses for a response.
        gridMeta[target.controlId] = record;
        const grouped = await datasetGridRows(action, name, rows, target.columns, call);
        bindGrid(target, grouped.rows, grouped.columns, appendsToGrid(action));
        noteFilledBy(target.controlId, action);
        return;
    }
    if (isChart(target.type)) {
        drawChartFrom(target, chartRowsAt(keptForBinding(action, rows), action, '', name), record, name, call);
        return;
    }
    // Filtered on the rows rather than on the options made from them, so a filter may test a
    // column the dropdown does not show — keep the desks whose region is EMEA, and show their names.
    fillOptions(target, keptForBinding(action, rows).map(r => optionOf(r, action.keyField, action.labelField)));
}

/**
 * A dataset's rows made ready for a grid: looked up, filtered and grouped exactly as a response's
 * rows are. The lookups are handed no call record, which is why the catalog refuses the two
 * enriched kinds that read one — the rest look into another dataset or another grid on the page,
 * and have everything they need.
 */
async function datasetGridRows(action, name, rows, columns, call) {
    const bound = rowsForGridAction(rows, action, '', name);
    const lookups = await enrichmentLookups(action, name, call);
    return groupedForGrid(action, keptForBinding(action, enrichRows(bound.rows, action, null, lookups)),
        withEnrichedColumns(bound.columns || columns, action));
}

// ── Comparing one use case across two environments ────────────────────────
// "Does UAT still say what production says?" used to mean running the same instance twice by
// hand, saving both responses and diffing them somewhere else — which loses the inputs, the
// environments and the moment the instant the files are closed. A compare action is that
// question as a button: one instance, one set of inputs, two environments, one table of what
// differs.
//
// Two things about the comparison itself are worth stating up front, because both are what makes
// the table short enough to read. Order is never a difference — two lists holding the same
// elements in a different sequence are equal, and elements are paired up by what they hold
// rather than by where they sit. And two numbers within the action's threshold of each other are
// the same number, so a page comparing prices does not report every one of them as changed
// because the two environments round differently.

/**
 * Both calls, sent at once, and both reported in the run's record the way a fan-out reports its
 * own — one entry apiece, so Technical Details shows two requests and two responses rather than
 * one call standing in for a comparison that made two.
 *
 * <p>Either side failing stops the action. A diff against a 500 is not a diff; it would report
 * every field in the baseline as missing from the candidate, which is true and useless and looks
 * exactly like the catastrophic regression nobody wants to be told about by accident.
 */
async function runCompare(action, name, record, firstAt) {
    const scope = actionScope(null);
    const inputs = resolveInputs(action.inputs, scope);
    const envA = resolveTemplate(action.compareEnvironmentA, scope);
    const envB = resolveTemplate(action.compareEnvironmentB, scope);
    if (!envA || !envB) {
        throw new Error(name + ': it compares two environments and '
            + (!envA && !envB ? 'neither' : 'one') + ' of them resolved to nothing'
            + ' — whatever "' + (!envA ? action.compareEnvironmentA : action.compareEnvironmentB)
            + '" reads has no value on this page yet.');
    }
    if (envA === envB) {
        throw new Error(name + ': both sides resolved to "' + envA + '", so there is nothing to compare — '
            + 'it would run the same environment twice and report no differences.');
    }

    const sides = [
        { role: 'baseline',  environment: envA, at: firstAt, result: null, error: '' },
        { role: 'candidate', environment: envB, at: -1,      result: null, error: '' }
    ];
    sides.forEach(side => {
        side.label = name + ' · ' + side.role + ' (' + side.environment + ')';
        const entry = { name: side.label, instanceId: action.appUseCaseInstanceId, inputs: inputs,
                        environment: side.environment, metadataOnly: false, result: null, error: '' };
        if (side.at >= 0) record[side.at] = entry;
        else { side.at = record.length; record.push(entry); }
        side.entry = entry;
    });

    AC.setStatus('runStatus', name + ': ' + envA + ' vs ' + envB + '…');

    await Promise.all(sides.map(async side => {
        try {
            // Always its own call. The two differ by environment and the trigger's cache already
            // keys on that, but a comparison reusing an answer some other action in the same
            // trigger happened to fetch is the one place a shared flight could quietly compare
            // something other than what this action asked for.
            side.result = await runExecution(action.appUseCaseInstanceId, inputs, side.label,
                    side.environment, false, true);
            side.entry.result = runDetail(side.result);
            const failure = failureMessage(side.result, side.label);
            if (failure) { side.error = failure; side.entry.error = failure; }
        } catch (e) {
            side.error = e.message || String(e);
            side.entry.error = side.error;
        }
    }));

    const broken = sides.filter(side => side.error);
    if (broken.length) {
        throw new Error(name + ': there is nothing to compare because '
            + (broken.length === 2 ? 'neither call came back. ' : 'one call did not come back. ')
            + broken.map(side => side.error).join(' '));
    }
    return { sides: sides, envA: envA, envB: envB, inputs: inputs };
}

/**
 * What one side of a comparison actually holds: its body read as JSON or as XML, put through the
 * action's transform chain, then narrowed by its path. The same three steps in the same order an
 * ordinary action reads a response in — and run per side, so an endpoint whose two environments
 * wrap the same facts differently can still be compared once a step has unwrapped them.
 */
async function compareSideValue(action, name, side) {
    const data = action.compareType === COMPARE_XML
        ? compareXmlOf(side.result, name, side.role)
        : payloadOf(side.result);
    const reshaped = await applyTransforms(data, action, name + ' · ' + side.role);
    return pathGet(reshaped, resolvePath(action.comparePath || '', name + ' · ' + side.role, null));
}

/**
 * One side's body as the tree its XML describes. The server's own transform counts as the
 * document when it produced text; anything else it produced is already structured and is not
 * XML to be parsed, so the body as it arrived is used instead.
 */
function compareXmlOf(result, name, role) {
    const transformed = result ? result.transformedResponse : null;
    const text = typeof transformed === 'string' ? transformed : (result ? result.responseBody : '');
    if (typeof text !== 'string' || !text.trim()) {
        throw new Error(name + ': the ' + role + ' answer had no XML to compare — its response was empty.');
    }
    const doc = new DOMParser().parseFromString(text.trim(), 'application/xml');
    const failure = doc.querySelector('parsererror');
    if (failure) {
        throw new Error(name + ': the ' + role + ' answer could not be parsed as XML: '
            + failure.textContent.trim().split('\n')[0]);
    }
    return xmlNodeToObj(doc.documentElement);
}

/** What one side of a comparison is, for deciding whether the two are even the same shape. */
function compareKind(value) {
    if (value === undefined) return 'absent';
    if (Array.isArray(value)) return 'array';
    // null is a value somebody's endpoint chose to send, not an absence — a field that went from
    // null to 7 changed, and saying so beats calling it a type change or saying nothing.
    if (value !== null && typeof value === 'object') return 'object';
    return 'scalar';
}

/**
 * Whether a value can stand in a numeric comparison — a number, or text that is one.
 *
 * <p>Text counts because XML has no types: every value in an XML document arrives as a string,
 * and a threshold that only applied to JSON numbers would do nothing at all on the half of the
 * comparisons this action exists for. A consequence worth knowing: <code>007</code> and
 * <code>7</code> are the same number and so not a difference. Booleans do not count — true is
 * not 1 here, whatever JavaScript says.
 */
function isComparableNumber(value) {
    if (typeof value === 'number') return isFinite(value);
    if (typeof value !== 'string') return false;
    const text = value.trim();
    return text !== '' && isFinite(Number(text));
}

/** One value as the text two sides are compared by when neither is a number. */
function compareText(value) {
    if (value === null) return 'null';
    if (value === undefined) return '';
    if (typeof value === 'object') return canonicalCompare(value);
    return String(value);
}

/**
 * A value written so that two values equal in every way that matters here produce the same text —
 * object keys in order, array elements sorted, a number and the text of that number alike. It is
 * what pairs up the elements of two lists, and what a whole subtree shows as in a report cell.
 *
 * <p>Sorting the elements is the order-insensitivity, at every depth: a list of the same things
 * in another sequence canonicalises identically, so it is not a difference and never reaches the
 * pairing at all.
 */
function canonicalCompare(value) {
    if (value === undefined) return '~';
    if (value === null) return 'null';
    if (Array.isArray(value)) return '[' + value.map(canonicalCompare).sort().join(',') + ']';
    if (typeof value === 'object') {
        return '{' + Object.keys(value).sort()
            .map(key => JSON.stringify(key) + ':' + canonicalCompare(value[key])).join(',') + '}';
    }
    if (isComparableNumber(value)) return '#' + Number(value);
    return JSON.stringify(String(value));
}

/**
 * Every row of the report, from the two values the paths picked out. Rows carry every outcome —
 * changed, tolerated, missing, and matching — and which of them reach the grid is the action's
 * <b>Report</b> setting, applied once at the end. Only the matching ones are expensive to
 * produce, so <code>opts.all</code> turns them off for the cost probes the pairing runs.
 */
function walkCompare(a, b, path, rows, opts) {
    const ka = compareKind(a);
    const kb = compareKind(b);
    if (ka === 'absent' && kb === 'absent') return;
    if (ka === 'absent') { rows.push(compareRow(path, COMPARE_STATUS.onlyB, undefined, b)); return; }
    if (kb === 'absent') { rows.push(compareRow(path, COMPARE_STATUS.onlyA, a, undefined)); return; }
    if (ka !== kb) { rows.push(compareRow(path, COMPARE_STATUS.type, a, b)); return; }
    if (ka === 'object') { compareObjects(a, b, path, rows, opts); return; }
    if (ka === 'array')  { compareArrays(a, b, path, rows, opts); return; }
    compareScalars(a, b, path, rows, opts);
}

/** Both sides' properties, in one sorted pass, so the report reads in a stable order either way. */
function compareObjects(a, b, path, rows, opts) {
    const keys = [...new Set(Object.keys(a).concat(Object.keys(b)))].sort();
    keys.forEach(key => walkCompare(a[key], b[key], path + comparePathStep(key), rows, opts));
}

/** One property as it is written in a report path — dotted where it can be, bracketed where not. */
function comparePathStep(key) {
    return /^[A-Za-z_@#][A-Za-z0-9_\-@#]*$/.test(key) ? '.' + key : '["' + key + '"]';
}

/**
 * Two lists, compared as the sets of things they hold rather than as sequences. Elements are
 * paired first by being identical and then by being the closest thing left on the other side;
 * what is still unpaired afterwards is reported as present on one side only.
 */
function compareArrays(a, b, path, rows, opts) {
    const paired = pairCompareElements(a, b, opts);
    paired.matched.forEach(pair =>
        walkCompare(a[pair.a], b[pair.b], path + compareIndexStep(pair.a, pair.b), rows, opts));
    paired.onlyA.forEach(i => rows.push(compareRow(path + '[' + i + ']', COMPARE_STATUS.onlyA, a[i], undefined)));
    paired.onlyB.forEach(j => rows.push(compareRow(path + '[' + j + ']', COMPARE_STATUS.onlyB, undefined, b[j])));
    // Said out loud rather than left to be inferred from a list that is suddenly all "only in".
    // Every element below this row is reported as present on one side alone because none of them
    // could be lined up, not because all of them genuinely changed.
    if (paired.unpaired) {
        rows.push(compareRow(path, COMPARE_STATUS.unpaired,
            paired.onlyA.length + ' unmatched of ' + a.length,
            paired.onlyB.length + ' unmatched of ' + b.length));
    }
}

/**
 * Which element of each list a pair is, where they are sitting in different places — the whole
 * point being that a list is not a sequence here, so a path claiming one index for both sides
 * would be saying something untrue about one of them.
 */
function compareIndexStep(i, j) {
    return i === j ? '[' + i + ']' : '[' + i + '↔' + j + ']';
}

/**
 * Pairs up two lists' elements. Identical elements go first, matched off against each other by
 * their canonical form, which is what makes a reordered list free: nothing is left to score.
 * Whatever remains is scored against every remaining element on the other side — the score being
 * how many differences that pairing would report — and taken cheapest first.
 *
 * <p>Past {@link #COMPARE_PAIRING_LIMIT} leftovers on a side the scoring is skipped rather than
 * run: it is quadratic, each score walks two subtrees, and a page that locked the browser up on
 * a response someone pointed it at by accident would be worse than one that says plainly that
 * these elements could not be lined up. That is what <code>unpaired</code> reports.
 */
function pairCompareElements(a, b, opts) {
    const matched = [];
    const leftA = [];
    const takenB = new Set();
    const byCanonical = new Map();
    b.forEach((element, j) => {
        const key = canonicalCompare(element);
        if (!byCanonical.has(key)) byCanonical.set(key, []);
        byCanonical.get(key).push(j);
    });
    a.forEach((element, i) => {
        const queue = byCanonical.get(canonicalCompare(element));
        if (queue && queue.length) {
            const j = queue.shift();
            takenB.add(j);
            matched.push({ a: i, b: j });
            return;
        }
        leftA.push(i);
    });
    const leftB = b.map((element, j) => j).filter(j => !takenB.has(j));

    if (!leftA.length || !leftB.length) {
        return { matched: matched, onlyA: leftA, onlyB: leftB, unpaired: false };
    }
    if (leftA.length > COMPARE_PAIRING_LIMIT || leftB.length > COMPARE_PAIRING_LIMIT) {
        return { matched: matched, onlyA: leftA, onlyB: leftB, unpaired: true };
    }

    // Every remaining pairing, cheapest first. Greedy rather than optimal: an assignment this
    // size solved properly is a different kind of program, and on the lists these responses
    // actually hold — a handful of rows that moved, not a permutation of five hundred — taking
    // the closest pair and then the closest of what is left lands in the same place.
    const scored = [];
    const probe = { tol: opts.tol, all: false };
    leftA.forEach(i => leftB.forEach(j => scored.push({ a: i, b: j, cost: compareCost(a[i], b[j], probe) })));
    scored.sort((x, y) => x.cost - y.cost || x.a - y.a || x.b - y.b);
    const usedA = new Set();
    const usedB = new Set();
    scored.forEach(pair => {
        if (usedA.has(pair.a) || usedB.has(pair.b)) return;
        usedA.add(pair.a);
        usedB.add(pair.b);
        matched.push({ a: pair.a, b: pair.b });
    });
    return {
        matched: matched.sort((x, y) => x.a - y.a),
        onlyA: leftA.filter(i => !usedA.has(i)),
        onlyB: leftB.filter(j => !usedB.has(j)),
        unpaired: false
    };
}

/**
 * How badly two elements match, as the number of differences pairing them would report. A
 * difference inside the threshold costs nothing, which is the point of having a threshold: two
 * rows that agree to within a tenth of a percent are the same row moved, not two different rows.
 */
function compareCost(a, b, probe) {
    const rows = [];
    walkCompare(a, b, '', rows, probe);
    return rows.filter(row => row.status !== COMPARE_STATUS.tolerated).length;
}

/**
 * Two values that are neither objects nor lists. Numbers — including numbers written as text,
 * which is every number in an XML document — are compared by how far apart they are relative to
 * the larger of the two, so one threshold means the same thing on a price and on a notional.
 * Everything else is compared as text, where a threshold means nothing: an identifier a tenth of
 * a percent different is a different identifier.
 */
function compareScalars(a, b, path, rows, opts) {
    if (isComparableNumber(a) && isComparableNumber(b)) {
        const na = Number(a);
        const nb = Number(b);
        const delta = nb - na;
        const scale = Math.max(Math.abs(na), Math.abs(nb));
        const pct = scale === 0 ? 0 : Math.abs(delta) / scale * 100;
        if (na === nb) { if (opts.all) rows.push(compareRow(path, COMPARE_STATUS.same, a, b, 0, 0)); return; }
        rows.push(compareRow(path, pct <= opts.tol ? COMPARE_STATUS.tolerated : COMPARE_STATUS.changed,
                a, b, delta, pct));
        return;
    }
    if (compareText(a) === compareText(b)) {
        if (opts.all) rows.push(compareRow(path, COMPARE_STATUS.same, a, b));
        return;
    }
    rows.push(compareRow(path, COMPARE_STATUS.changed, a, b));
}

/** One row of the report, under the six columns every row of it has. */
function compareRow(path, status, a, b, delta, pct) {
    return {
        path: path || '$',
        status: status,
        baseline: compareCell(a),
        candidate: compareCell(b),
        difference: delta === undefined ? '' : roundCompare(delta, 10),
        differencePct: pct === undefined ? '' : roundCompare(pct, 6)
    };
}

/** A number with its floating-point dust swept off, so a cell reads 0.3 rather than 0.30000000000000004. */
function roundCompare(value, places) {
    if (!isFinite(value)) return value;
    return Number(value.toFixed(places));
}

/**
 * One side's value in a cell. A whole subtree shows as its canonical form — which is what an
 * element present on one side only is, and reading it beats a cell saying "object" — and is cut
 * short, since a grid cell is not where a two-megabyte document gets read.
 */
function compareCell(value) {
    if (value === undefined) return '';
    if (value === null) return 'null';
    if (typeof value !== 'object') return value;
    const text = canonicalCompare(value);
    return text.length > COMPARE_CELL_LIMIT ? text.slice(0, COMPARE_CELL_LIMIT) + '…' : text;
}

/** Which of the rows the walk produced this action actually shows. */
function keptCompareRows(rows, report) {
    if (report === REPORT_EVERYTHING) return rows;
    if (report === REPORT_TOLERATED) return rows.filter(row => row.status !== COMPARE_STATUS.same);
    return rows.filter(row => row.status !== COMPARE_STATUS.same && row.status !== COMPARE_STATUS.tolerated);
}

/**
 * Reads both answers, compares them and puts the report where the action aimed it — and hands
 * back a line about what it found, since "1 of 1 action completed" says nothing about whether
 * the two environments agreed, which is the only thing anyone ran this for.
 */
async function bindCompare(action, name, cmp, call) {
    const [baseline, candidate] = await Promise.all(cmp.sides.map(side => compareSideValue(action, name, side)));
    const report = action.compareReport || REPORT_DIFFERENCES;
    const opts = { tol: Math.max(+action.compareTolerancePercent || 0, 0), all: report === REPORT_EVERYTHING };
    const found = [];
    walkCompare(baseline, candidate, '$', found, opts);

    const differing = found.filter(row => row.status !== COMPARE_STATUS.same
                                       && row.status !== COMPARE_STATUS.tolerated).length;
    const tolerated = found.filter(row => row.status === COMPARE_STATUS.tolerated).length;
    const summary = name + ': ' + cmp.envA + ' vs ' + cmp.envB + ' — '
        + (differing ? differing + ' difference' + (differing === 1 ? '' : 's') : 'no differences')
        + (tolerated ? ', ' + tolerated + ' within the ' + opts.tol + '% threshold' : '') + '.';

    const rows = keptCompareRows(found, report);
    // Kept as a success whatever it found: the call went out, both sides answered and the
    // comparison ran. Differences are the answer, not a failure — the grid says how many in the
    // line under its name, and the rows say which.
    const record = callRecord(cmp.sides[0].result, 'SUCCESS', '', call,
            cmp.envA + ' vs ' + cmp.envB + ' — ' + differing + ' difference' + (differing === 1 ? '' : 's')
            + (tolerated ? ', ' + tolerated + ' within threshold' : ''));

    if (action.targetControlId === NEW_GRID) {
        const grouped = groupedForGrid(action, rows, COMPARE_COLUMNS);
        noteFilledBy(pushStackedGrid(name, grouped.rows, grouped.columns, record), action);
        return summary;
    }
    const target = findControl(action.targetControlId);
    if (!target) throw new Error(name + ': its target is no longer on this page.');
    gridMeta[target.controlId] = record;
    // The known columns are a fallback rather than an override, exactly as they are for a
    // performance summary: a grid told to show three of them was told that on purpose. A group-by
    // is read the same way too — the report is a table like any other, and "how many of each
    // status" is a fair question to put to it from Analyze.
    const grouped = groupedForGrid(action, rows, (target.columns && target.columns.length) ? null : COMPARE_COLUMNS);
    bindGrid(target, grouped.rows, grouped.columns, appendsToGrid(action));
    noteFilledBy(target.controlId, action);
    return summary;
}

// ── Running one action once per row of a grid ─────────────────────────────
// A page that looks a list up and then has to ask the same question of every line on it used to
// be the operator clicking a row, reading the answer, clicking the next row. This sends the lot:
// one action, written once, run once per row, with each row's own columns answering the
// ${placeholders} that the page's controls answer for an ordinary run.
//
// What comes back is either a row apiece in one grid — the shape for "the status of each of
// these forty orders" — or a grid apiece behind tabs, for when each answer is a table in its own
// right and stacking them into one would lose which rows came from where.

/** Whether this action runs once per row of a grid rather than once against the page. */
function isFanOut(action) {
    return !!action && !!action.rowSourceControlId;
}

/**
 * The rows one fan-out will actually run over, and how many it is leaving alone.
 *
 * <p>Taken from what is on screen rather than from everything the grid holds: a grid the
 * operator has filtered is one they have narrowed on purpose, and calling for the rows they
 * filtered out would be sending calls nobody asked for. The cap is applied on top of that, and
 * what it left behind is reported rather than quietly dropped — "it only did the first
 * twenty-five" is otherwise the kind of thing noticed a week later.
 */
function fanOutRows(action, name) {
    const source = findControl(action.rowSourceControlId);
    if (!source) throw new Error(name + ': the control it runs over is no longer on this page.');
    if (isSelect(source.type)) return listFanOutRows(action, name, source);
    const state = gridState[source.controlId];
    if (!state) {
        throw new Error(name + ': "' + controlTitle(source) + '" has no rows yet — whatever fills it has to run first.');
    }
    const shown = visibleRows(state);
    // Two narrowings, applied in the order they were made. The operator's filters on the grid
    // came first and are already in `shown`; the action's own are the narrowing the page means
    // every time it runs, and go on top.
    const filters = activeRowFilters(action);
    const matching = filters.length ? shown.filter(row => rowMatchesFilters(row, filters)) : shown;
    if (!matching.length) {
        throw new Error(name + ': "' + controlTitle(source) + '" has no rows'
            + (filters.length ? " matching this action's filters"
                : isFiltered(state) ? ' matching the filters on it' : '')
            + ', so there is nothing to run over.');
    }
    return cappedFanOut(action, source, shown, matching);
}

/** The cap applied to what a fan-out matched, and what it left alone said out loud. */
function cappedFanOut(action, source, shown, matching) {
    const limit = action.rowLimit === undefined || action.rowLimit === null ? DEFAULT_ROW_LIMIT : action.rowLimit;
    const rows = limit > 0 ? matching.slice(0, limit) : matching;
    return { source: source, rows: rows, skipped: matching.length - rows.length,
             filteredOut: shown.length - matching.length };
}

/**
 * The elements of a select or multi-select a fan-out runs over, each as a row: its value under
 * <code>key</code>, <code>value</code> and the list's own field name — so <code>${envs}</code> in an
 * input is this one element rather than every pick joined — and its text under <code>label</code>.
 *
 * <p>Which elements is the action's to say: the picks, or every option. Left to default, a
 * multi-select runs over what the operator picked and a select, whose one pick would make a
 * fan-out of one, over every option it offers.
 */
function listFanOutRows(action, name, source) {
    const select = document.querySelector('#rc-' + CSS.escape(source.controlId) + ' select');
    if (!select) throw new Error(name + ': "' + controlTitle(source) + '" is not on the page to read its elements from.');
    const which = action.rowElements || (source.type === 'multiselect' ? 'SELECTED' : 'ALL');
    const options = [...select.options].filter(o => o.value !== '');
    const shown = which === 'SELECTED' ? options.filter(o => o.selected) : options;
    if (!shown.length) {
        throw new Error(name + ': "' + controlTitle(source) + '" has '
            + (which === 'SELECTED' ? 'nothing picked' : 'no options') + ', so there is nothing to run over.');
    }
    const rows = shown.map(o => {
        const row = { key: o.value, label: o.textContent, value: o.value };
        if (source.fieldName) row[source.fieldName] = o.value;
        return row;
    });
    const filters = activeRowFilters(action);
    const matching = filters.length ? rows.filter(row => rowMatchesFilters(row, filters)) : rows;
    if (!matching.length) {
        throw new Error(name + ': no element of "' + controlTitle(source) + '" matches this action\'s filters, so there is nothing to run over.');
    }
    return cappedFanOut(action, source, rows, matching);
}

/**
 * This action's row filters as they stand right now: the column, the test, and what to test
 * against with the page's own values filled in, so a filter may be written against a control the
 * operator sets rather than against a fixed string.
 *
 * <p>A filter whose value resolves to nothing is dropped rather than kept as a test nothing can
 * pass. An empty box under a grid means "any", the same as it does in the grid’s own filter row —
 * a page whose filter is <code>${statusPick}</code> and whose operator has picked nothing is
 * asking about every row, not about none of them. The tests that read the cell alone are kept
 * whatever is beside them, since for those the empty box is the whole question.
 */
function activeRowFilters(action) {
    return filtersNow(action.rowFilters);
}

/** The same reading, of whichever list of filters is asked for. */
function filtersNow(list) {
    return (list || [])
        .map(filter => ({
            column: (filter.column || '').trim(),
            operator: (filter.operator || 'CONTAINS').toUpperCase(),
            value: resolveTemplate(filter.value || '').trim()
        }))
        .filter(filter => filter.column
            && (VALUELESS_OPERATORS.includes(filter.operator) || filter.value !== ''));
}

/**
 * The rows of what a binding read that actually go into its control — see #bindFilterEditor.
 *
 * <p>Called at the last moment before the rows are handed over, and on the rows as they will be
 * seen: after the path has picked them out and after any enriched columns have been added, so a
 * filter can test a column that came off the call record rather than out of the body, and before
 * a group-by, so what is grouped is what passed.
 */
function keptForBinding(binding, rows) {
    const filters = filtersNow(binding && binding.bindFilters);
    if (!filters.length || !Array.isArray(rows)) return rows;
    return rows.filter(row => rowMatchesFilters(row, filters));
}

/** Every filter has to pass: they narrow, and two of them narrow further than one. */
function rowMatchesFilters(row, filters) {
    return filters.every(filter => cellPasses(cellText(row, filter.column), filter));
}

/**
 * One cell against one test. The cell is the text the grid shows, which is what the operator
 * filtering the same column by eye is reading, so the two narrow a grid the same way.
 *
 * <p>Text tests ignore case for that reason too. More-than and less-than compare as numbers when
 * both sides are numbers and as text otherwise, which is the rule the grid already sorts a
 * column by. A regular expression that will not compile fails every row rather than throwing:
 * a fan-out is a great many calls, and a typo in a filter should stop it rather than send it.
 */
function cellPasses(cell, filter) {
    const text = String(cell === undefined || cell === null ? '' : cell);
    const lower = text.toLowerCase();
    const wanted = String(filter.value).toLowerCase();
    switch (filter.operator) {
        case 'NOT_CONTAINS': return !lower.includes(wanted);
        case 'EQUALS':       return lower === wanted;
        case 'NOT_EQUALS':   return lower !== wanted;
        case 'STARTS_WITH':  return lower.startsWith(wanted);
        case 'ENDS_WITH':    return lower.endsWith(wanted);
        case 'GT':           return compareCells(text, filter.value) > 0;
        case 'LT':           return compareCells(text, filter.value) < 0;
        case 'EMPTY':        return text.trim() === '';
        case 'NOT_EMPTY':    return text.trim() !== '';
        case 'REGEX':
            try { return new RegExp(filter.value).test(text); } catch (e) { return false; }
        default:             return lower.includes(wanted);
    }
}

/** What one row's call is called, wherever its answer shows up. */
function fanOutLabel(action, scope, index) {
    const written = resolveTemplate(action.rowLabelTemplate, scope).trim();
    if (written) return written;
    // An element of a list already has a name, and it is a better one than its position.
    const source = findControl(action.rowSourceControlId);
    if (source && isSelect(source.type) && scope && scope.label) return String(scope.label);
    return 'Row ' + (index + 1);
}

/**
 * Runs `items` through `worker` with at most `limit` of them in flight, answering in the order
 * the items were in. All of them going out at once is what a fan-out over twelve rows wants and
 * exactly what one over a thousand must not do — the endpoint on the other end is a real service,
 * and this is a page someone opened to look something up rather than a load test.
 */
async function runPooled(items, limit, worker) {
    const answers = new Array(items.length);
    let next = 0;
    const lanes = new Array(Math.min(Math.max(limit, 1), items.length)).fill(0).map(async () => {
        for (;;) {
            const i = next++;
            if (i >= items.length) return;
            answers[i] = await worker(items[i], i);
        }
    });
    await Promise.all(lanes);
    return answers;
}

/**
 * Sends one action once per row and hands back what each row produced, in the grid's own order.
 *
 * <p>Every call is reported in the run's own record — a fan-out of forty rows is forty entries in
 * Technical Details, each named after its row — which is why `record` and `firstAt` are passed
 * in: the first row takes over the entry the action itself was given, and the rest are appended.
 * Numbering them that way leaves every index already handed out pointing where it did.
 *
 * <p>Nothing is thrown for a row that failed. A fan-out where three of forty came back 404 has
 * thirty-seven answers worth showing and three worth saying so about, and it is the caller that
 * knows where to put either. A row that failed is told apart two ways: {@code failure} is one
 * that answered with a body the caller should still read and bind, {@code error} one with
 * nothing to read at all.
 */
async function runFanOut(action, name, record, firstAt) {
    const plan = fanOutRows(action, name);
    const calls = plan.rows.map((row, i) => ({
        row: row,
        // Settled here, once, before the row is labelled or sent: everything this one call
        // resolves — its label, its inputs, its environment, the path that reads its answer —
        // reads the same ${ROWNUM} and the same ${UUID}. See #actionScope.
        scope: actionScope(row, i),
        label: '',
        at: i === 0 ? firstAt : -1,
        result: null,
        error: '',
        failure: ''
    }));
    calls.forEach((call, i) => { call.label = fanOutLabel(action, call.scope, i); });

    AC.setStatus('runStatus', name + ': ' + calls.length + ' call' + (calls.length === 1 ? '' : 's')
        + ' over "' + controlTitle(plan.source) + '"…');

    await runPooled(calls, FANOUT_CONCURRENCY, async call => {
        const rowName = name + ' · ' + call.label;
        // Resolved per row, at the moment that row is sent — the same rule an ordinary action
        // follows, one row at a time.
        let inputs, environment;
        try {
            inputs = resolveInputs(action.inputs, call.scope);
            environment = resolveTemplate(action.environmentOverride, call.scope);
        } catch (e) {
            call.error = e.message || String(e);
            return;
        }
        const entry = { name: rowName, instanceId: action.appUseCaseInstanceId,
                        inputs: inputs, environment: environment,
                        metadataOnly: isMetadataOnly(action), result: null, error: '' };
        if (call.at >= 0) record[call.at] = entry;
        else { call.at = record.length; record.push(entry); }

        try {
            call.result = await runExecution(action.appUseCaseInstanceId, inputs, rowName,
                    environment, entry.metadataOnly, action.ownCall);
            entry.result = runDetail(call.result);
            const failure = failureMessage(call.result, rowName);
            if (failure) {
                entry.error = failure;
                // A metadata action reads a failed call quite deliberately — the status code is
                // what it came for — and a payload action reads one that answered with a body,
                // for the same reason an ordinary action does: the body of a 400 is usually why
                // it was a 400. Either way the row is still marked as having failed. Only a
                // failure with nothing behind it has no answer to put anywhere.
                if (isMetadataAction(action) || hasPayload(call.result)) call.failure = failure;
                else call.error = failure;
            }
        } catch (e) {
            call.error = e.message || String(e);
            entry.error = call.error;
        }
    });

    return { source: plan.source, calls: calls, skipped: plan.skipped, filteredOut: plan.filteredOut };
}

/**
 * Puts a fan-out's answers where the action aimed them, and hands back a line about how it went.
 * Each answer is read with its own row in scope, so a path may narrow by the row it is asking
 * about as readily as an input may.
 */
async function bindFanOut(action, name, fan) {
    const failed = fan.calls.filter(c => c.error || c.failure).length;
    if (action.rowOutputMode === 'TABS') await bindFanOutTabs(action, name, fan);
    else                                 await bindFanOutRows(action, name, fan);

    return name + ': ' + fan.calls.length + ' call' + (fan.calls.length === 1 ? '' : 's')
        + ' over "' + controlTitle(fan.source) + '".'
        + (fan.filteredOut ? ' ' + fan.filteredOut + ' row' + (fan.filteredOut === 1 ? '' : 's')
                + ' did not match its filters.' : '')
        + (fan.skipped ? ' ' + fan.skipped + ' further row' + (fan.skipped === 1 ? '' : 's')
                + ' left alone by the cap on this action.' : '')
        + (failed ? ' ' + failed + ' of them failed.' : '');
}

/** One grid per row, laid out as tabs inside the tab set the action targets. */
async function bindFanOutTabs(action, name, fan) {
    const target = findControl(action.targetControlId);
    if (!target || target.type !== 'tabs') {
        throw new Error(name + ': a tab per row needs a tab set to put them in, and its target is '
            + (target ? 'a ' + target.type + '.' : 'no longer on this page.'));
    }
    // This action's own tabs from last time go, rather than the new ones being added beside them:
    // a second run over a shorter list would otherwise leave the first run's rows sitting in tabs
    // that no longer answer to anything. Another action's tabs in the same set are left alone.
    clearFanTabs(target.controlId, action.actionId);

    const lookups = await enrichmentLookups(action, name);
    const added = [];
    for (let i = 0; i < fan.calls.length; i++) {
        const call = fan.calls[i];
        const rowName = name + ' · ' + call.label;
        const gridId = 'fan-' + action.actionId + '-' + i;
        added.push({ gridId: gridId, title: call.label, actionId: action.actionId });
        delete gridState[gridId];
        // Recorded before the grid is filled, which is when its rows are put through the check.
        if ((action.rowErrorExpression || '').trim()) fanRowChecks[gridId] = action.rowErrorExpression.trim();
        else delete fanRowChecks[gridId];
        if ((action.displayFilterExpression || '').trim()) fanDisplayFilters[gridId] = action.displayFilterExpression.trim();
        else delete fanDisplayFilters[gridId];
        if (call.error) {
            gridMeta[gridId] = callRecord(call.result, 'FAILED', call.error, call.at);
            continue;
        }
        // A row that failed with a body still fills its tab — the record on it says failure and
        // says why, exactly as an ordinary action's grid does.
        gridMeta[gridId] = callRecord(call.result, call.failure ? 'FAILED' : 'SUCCESS', call.failure, call.at);
        try {
            const data = await rootFor(call.result, action, rowName);
            const bound = rowsForGridAction(data, action, resolvePath(action.arrayPath, rowName, call.scope), rowName);
            setGridData(gridId, keptForBinding(action, enrichRows(bound.rows, action, call.result, lookups)),
                withEnrichedColumns(bound.columns || target.columns, action), call.label);
        } catch (e) {
            const why = call.failure ? call.failure + ' Its response could not be read either: '
                    + (e.message || String(e)) : (e.message || String(e));
            gridMeta[gridId] = callRecord(call.result, 'FAILED', why, call.at);
            addError(why, call.at);
        }
    }
    fanTabs[target.controlId] = (fanTabs[target.controlId] || []).concat(added);
    paintTabs(target);
}

/**
 * Every row's answer as rows of the one control the action targets: the leading source column,
 * then whatever that call answered with, then the columns the action named. A grid shows them as
 * a table; a select or multi-select shows them as its options, a row apiece.
 *
 * <p>Collected columns are added to that, never instead of it — see #collectedAnswerRows. The
 * grid is still the table of what came back, under the endpoint's own field names and expanded
 * by the array path exactly as it is with no columns named; what the named ones add is the id
 * that was asked about, the status code, the timing, a header — the things the response itself
 * does not carry. Which is why a call that failed still fills its row: its metadata and header
 * columns are exactly what say why.
 */
async function bindFanOutRows(action, name, fan) {
    const columns = (action.rowColumns || []).filter(column => column && column.name);
    const lookups = await enrichmentLookups(action, name);
    const collected = await collectedAnswerRows(action, name, fan, lookups, columns);
    // Over the whole collection rather than per call, which is what makes it useful here: "only
    // the ones that came back failed" is a question about the forty rows, not about each one.
    const rows = keptForBinding(action, collected);

    if (action.targetControlId === NEW_GRID) {
        // Nothing fixed: the rows carry the answer's own fields and the named columns alike, and
        // a stacked grid follows them.
        const grouped = groupedForGrid(action, rows, null);
        noteFilledBy(pushStackedGrid(name, grouped.rows, grouped.columns, null), action);
        return;
    }
    const target = findControl(action.targetControlId);
    // An action with no target at all is a fan-out run for its effect, and reports only how the
    // calls went — which the caller has already said in the status line.
    if (!target) return;
    // A dropdown takes the same collected list the grid does, an option per row: the key and the
    // label are read off each row exactly as they are for an action that ran once, so "ask about
    // each of these forty and let me pick from the ones that answered" needs no grid in between.
    // The rows are already through the enrichment, the filters and the cap by this point.
    if (isSelect(target.type)) {
        fillOptions(target, rows.map(r => optionOf(r, action.keyField, action.labelField)));
        return;
    }
    if (target.type !== 'grid') {
        throw new Error(name + ': a row per call needs a grid or a dropdown to collect them in, and its target is a '
            + target.type + '.');
    }
    // No one call behind these rows, so the record is not one of them: the bar would have to pick
    // one of forty calls to describe, and Technical Details already lists all of them. What it
    // gets instead is a record of the fan-out itself — how many calls it made and how many failed.
    //
    // Which matters well beyond the bar. A grid with no record at all has no outcome (see
    // #gridOutcome), so it said nothing on its own name, nothing on the tab that shows it and
    // nothing in the tally of the group above that — a grid filled by forty calls, three of which
    // came back wrong, sat in a tab set that read as fine. The record is what lets it answer.
    //
    // Written before the rows go in, so the paint that fills the grid is already the paint that
    // reports on it, rather than leaving the badge a run behind.
    gridMeta[target.controlId] = fanRecord(fan);
    const grouped = groupedForGrid(action, rows,
        withEnrichedColumns(withResultColumns(target.columns, columns), action));
    bindGrid(target, grouped.rows, grouped.columns, appendsToGrid(action));
    noteFilledBy(target.controlId, action);
    paintGridStatus(target.controlId);
}

/**
 * What a fan-out did, as the record the grid it collected into carries: a line saying how many
 * calls went out over which grid, and FAILED the moment any of them did.
 *
 * <p>FAILED on one call in forty, rather than on all forty, because the grid is then holding an
 * incomplete answer — and a table that is missing the rows nobody was told were missing is worse
 * than one that says so. It is the same reading the status line makes of the same run.
 *
 * <p>No {@code meta}: there is no one URL, status code or timing to report, and inventing one out
 * of the first call would describe thirty-nine others it knows nothing about. So the bar shows
 * the line and does not open; the calls themselves are in Technical Details, all of them.
 */
function fanRecord(fan) {
    const failed = fan.calls.filter(c => c.error || c.failure).length;
    const over = fan.source ? ' over "' + controlTitle(fan.source) + '"' : '';
    return callRecord(null, failed ? 'FAILED' : 'SUCCESS',
        failed ? failed + ' of ' + fan.calls.length + ' calls failed — these rows are what came back '
                + 'from the rest.' : '',
        null,
        fan.calls.length.toLocaleString() + ' call' + (fan.calls.length === 1 ? '' : 's') + over);
}

/**
 * Every call's answer as it came, under the leading source column, with the action's named columns
 * written onto each of its rows. Each call's rows are enriched with that call's own record and
 * headers.
 *
 * <p>The named columns are worked out once per call and copied onto every row that call produced,
 * because that is what they are: a property of the call, not of the row. A call whose array path
 * found eight rows gets eight rows all saying the same status code, the same URL and the same id
 * off the source grid — which is the table somebody reading a fan-out wanted, rather than eight
 * rows of the answer and a ninth of the call.
 *
 * <p>Written before the enrichment and after the answer, which is the order of how specific the
 * three are: the response brought its own fields, a named column may deliberately restate one
 * under a name the reader knows, and an enriched column — a lookup that can read what the other
 * two put there — is worked out last of all.
 *
 * @param columns the action's named columns, already filtered down to the ones with a name
 */
async function collectedAnswerRows(action, name, fan, lookups, columns) {
    const named = (columns || []).length > 0;
    // Reported once rather than once per row: a path that needs a value nothing answers to is one
    // mistake, not forty. See #resultColumnCell.
    const problems = new Set();
    const rows = [];
    for (const call of fan.calls) {
        // Read once per call however many rows and columns read out of it: transforming a body is
        // the expensive half, and the answer rows and the named columns read the same transformed
        // thing.
        const read = await readFanCall(action, name + ' · ' + call.label, call);
        const own = answerRowsOf(action, name, call, read);
        const meta = fanCallMeta(call);
        const cells = named ? resultColumnCells(action, name, call, meta, columns, read, problems) : null;
        if (cells) own.forEach(row => Object.assign(row, cells));
        for (const row of enrichRows(own, action, call.result, lookups, meta)) rows.push(row);
    }
    problems.forEach(problem => addError(problem));
    return rows;
}

/**
 * A grid's column list with the action's named columns added at the end. A grid with no list
 * follows its rows, which already carry them, so nothing is passed back for it to follow instead —
 * the same bargain {@link #withEnrichedColumns} strikes, and for the same reason: handing a list
 * to a grid that has none would cut it down to exactly that list.
 */
function withResultColumns(columns, resultColumns) {
    const extra = (resultColumns || []).map(column => column.name);
    if (!columns || !columns.length || !extra.length) return columns;
    return columns.concat(extra.filter((name, at) => !columns.includes(name) && extra.indexOf(name) === at));
}

/** The record a fan-out call's metadata columns read: the call's own, or why there was none. */
function fanCallMeta(call) {
    return call.result ? metaOf(call.result) : { status: 'ERROR', error: call.error || call.failure || '' };
}

/**
 * One fan-out call's transformed body, read once for everything that reads out of it — the rows
 * the array path finds and the named columns' paths alike. A call that never reached an endpoint
 * has no body to read and no error to report about reading it: why it failed is on the record the
 * metadata columns read, not here.
 */
async function readFanCall(action, rowName, call) {
    if (!call.result) return { data: null, error: '' };
    try { return { data: await rootFor(call.result, action, rowName), error: '' }; }
    catch (e) { return { data: null, error: e.message || String(e) }; }
}

/** One fan-out call's contribution to the collected grid: the rows its array path found. */
function answerRowsOf(action, name, call, read) {
    const rowName = name + ' · ' + call.label;
    if (call.error) return [fanRow(call.label, { status: 'FAILED', error: call.error })];
    if (read.error) {
        return [fanRow(call.label, { status: 'FAILED',
            error: (call.failure ? call.failure + ' ' : '') + read.error })];
    }
    try {
        const found = pathGet(read.data, resolvePath(action.arrayPath, rowName, call.scope));
        if (found === undefined || found === null) {
            // A row that failed says so here rather than "nothing found": there was
            // something to read, it was read, and the path found nothing in it — which for a
            // failed call is almost always because what came back was the error, not the
            // answer the path was written for.
            return [call.failure ? fanRow(call.label, { status: 'FAILED', error: call.failure })
                                 : fanRow(call.label, { status: 'NOTHING FOUND' })];
        }
        // An answer that is itself a list contributes all of its rows, each still saying
        // which call produced it — a hundred calls returning three rows each is three
        // hundred rows of one table, which is the table someone wanted.
        if (Array.isArray(found)) return found.map(entry => fanRow(call.label, entry));
        return [fanRow(call.label, found)];
    } catch (e) {
        return [fanRow(call.label, { status: 'FAILED',
            error: (call.failure ? call.failure + ' ' : '') + (e.message || String(e)) })];
    }
}

/**
 * What the columns the action named hold for one call — see {@link AppPageResultColumn}. One set
 * of cells per call, copied onto every row that call produced.
 *
 * <p>Filled whatever happened to the call, and that is the difference they make. The response's
 * own fields can only describe a call that answered; these describe one that did not, because the
 * status code, the URL and the id that was asked about are all knowable about a call that came
 * back empty — so a failed call's row says why rather than only that.
 *
 * <p>What could not be read is reported once rather than once per row: a path that needs a value
 * nothing answers to is one mistake, not forty.
 */
function resultColumnCells(action, name, call, meta, columns, read, problems) {
    const rowName = name + ' · ' + call.label;
    if (read.error) problems.add(name + ': a response could not be read — ' + read.error);
    const cells = {};
    columns.forEach(column => {
        cells[column.name] = resultColumnCell(action, column, call, read.data, meta, name, rowName, problems);
    });
    return cells;
}

/** Which of the four places a column reads from; anything unrecognised reads the response. */
function columnKind(column) {
    return ((column && column.kind) || 'PATH').toUpperCase();
}

/** The key of `scope` that `name` means, ignoring case; `name` itself when none matches. */
function scopeKey(scope, name) {
    if (!scope || typeof scope !== 'object' || name in scope) return name;
    const lower = String(name).trim().toLowerCase();
    return Object.keys(scope).find(key => key.toLowerCase() === lower) || name;
}

/**
 * One cell of one call's row. Empty where there was nothing to read, which is the truthful thing
 * to put in a cell whose call failed — and better than the message, which would be the same
 * message forty times down a column somebody is trying to read a status out of. The message is
 * collected in `problems` and reported once above the grid instead.
 */
function resultColumnCell(action, column, call, data, meta, name, rowName, problems) {
    const expression = column.expression || '';
    switch (columnKind(column)) {
        case 'LABEL':
            return call.label;
        case 'ROW':
            // Read off the call's scope rather than its row, so a column may name ROWNUM or the
            // call's own UUID as readily as it names something the grid came with.
            // Matched without regard to case, as headers are: an exact match wins, else the first
            // key that differs only in case.
            return cellText(call.scope, scopeKey(call.scope, expression));
        case 'META': {
            const value = meta[expression];
            return value === undefined || value === null ? '' : value;
        }
        case 'HEADER':
            return headerValue(call.result, expression);
        default: {
            if (!call.result || data === null || data === undefined) return '';
            try {
                const found = pathGet(data, resolvePath(expression, rowName, call.scope));
                return found === undefined || found === null ? ''
                    : typeof found === 'object' ? JSON.stringify(found) : found;
            } catch (e) {
                problems.add(name + ' column "' + column.name + '": '
                    + (e.message || String(e)));
                return '';
            }
        }
    }
}

/**
 * One response header by name, without regard to case, since a header name is case-insensitive
 * on the wire and nobody writing <code>Content-Type</code> into a column means a different header
 * from the one the endpoint spelled <code>content-type</code>. Repeats are joined rather than
 * one of them picked: a call carrying three Set-Cookie headers has three, and a cell showing one
 * of them would be a cell that lies about the call.
 */
function headerValue(result, wanted) {
    const headers = result && result.responseHeaders;
    if (!headers || !wanted) return '';
    const key = Object.keys(headers).find(k => k.toLowerCase() === String(wanted).toLowerCase());
    if (key === undefined) return '';
    const value = headers[key];
    return Array.isArray(value) ? value.join(', ')
        : value === undefined || value === null ? '' : String(value);
}

// ── Enriched columns ─────────────────────────────────────────────────────
// Columns worked out per row as a grid is populated — a call record field, a response header, or
// a VLOOKUP into a static dataset. See AppPageEnrichColumn.

// Each dataset's rows indexed by a key column, built once per fetch of the rows however many
// lookups and binds read it. Keyed by the fetched object, so a page reopened — which fetches
// afresh — never reads an index of the old rows.
const lookupIndexes = new WeakMap();

/** The kind of one enriched column, upper-cased, with a blank one reading as META. */
function enrichKind(column) {
    return ((column && column.kind) || 'META').toUpperCase();
}

/**
 * The enriched columns an action or binding carries that can be added: the named ones, and the
 * whole-row lookups, which have no name of their own — they are named after the row they find.
 */
function enrichColumnsOf(action) {
    return ((action && action.enrichColumns) || [])
        .filter(column => column && (column.name || enrichKind(column) === WHOLE_ROW_LOOKUP));
}

/**
 * The columns one enriched column adds to a row. One apiece for every kind but the whole-row lookup,
 * which adds every column the grid it looks into is holding, each behind its prefix.
 *
 * <p>Read off that grid rather than declared, so the columns follow what the call actually returned
 * — and read here rather than passed in, so the column list a grid is given and the cells its rows
 * get are worked out from the same place. A grid that has not been filled yet contributes the columns
 * it was laid out with, or none; either way the lookup reports itself empty when it runs.
 */
function enrichColumnNames(column) {
    if (enrichKind(column) !== WHOLE_ROW_LOOKUP) return [column.name];
    const prefix = column.prefix || '';
    return wholeRowColumns(column).map(name => prefix + name);
}

/**
 * What to call one enriched column when something has to be said about it — its name, or, for the
 * whole-row lookup that has none, its prefix or the column it matches on.
 */
function enrichColumnLabel(column) {
    if (enrichKind(column) !== WHOLE_ROW_LOOKUP) return column.name;
    if (column.prefix) return column.prefix + '*';
    return 'whole row on ' + (column.lookupColumn || '?');
}

/** The columns a whole-row lookup brings back: what its grid holds now, else what it was laid out with. */
function wholeRowColumns(column) {
    const grid = findControl(column.gridControlId);
    if (!grid || grid.type !== 'grid') return [];
    const state = gridState[grid.controlId];
    const columns = (state && state.allColumns) || grid.columns || [];
    // Never the key column: it holds what this row was matched on, which this row already has in
    // the column that was looked up — a second copy of it under another name is noise.
    const key = String(column.keyColumn || '').trim().toLowerCase();
    return columns.filter(name => String(name).trim().toLowerCase() !== key);
}

/**
 * A grid's column list with the enriched columns added at the end. A grid with no list follows its
 * rows, which already carry them, so nothing is passed back for it to follow instead.
 */
function withEnrichedColumns(columns, action) {
    const extra = enrichColumnsOf(action).reduce((all, column) => all.concat(enrichColumnNames(column)), []);
    if (!columns || !columns.length || !extra.length) return columns;
    return columns.concat(extra.filter((name, at) => !columns.includes(name) && extra.indexOf(name) === at));
}

/** How a value is compared in a lookup: as text, ignoring case and the spaces around it — as Excel does. */
function lookupKey(value) {
    return value === undefined || value === null ? '' : String(value).trim().toLowerCase();
}

/**
 * The datasets an action's lookups read, fetched before any row is enriched and each indexed by the
 * key column its lookup matches against. One that cannot be read is reported once, here, and its
 * column comes back empty on every row rather than failing the grid — the rows the call brought
 * are still worth showing.
 *
 * @return each VLOOKUP column to its index (key → first dataset row holding it), or to null
 */
async function enrichmentLookups(action, name, call) {
    const lookups = new Map();
    for (const column of enrichColumnsOf(action)) {
        const kind = enrichKind(column);
        const said = name + ' column "' + enrichColumnLabel(column) + '": ';
        if (GRID_LOOKUP_KINDS.includes(kind)) {
            lookups.set(column, gridLookupIndex(column, said, call));
            continue;
        }
        if (kind !== 'VLOOKUP') continue;
        lookups.set(column, null);
        if (!column.datasetName || !column.keyColumn || !column.returnColumn || !column.lookupColumn) {
            addError(said + 'the lookup needs a grid column, a dataset, its key column and a column to return.', call);
            continue;
        }
        let data;
        try { data = await datasetRows(column.datasetName); }
        catch (e) { addError(said + (e.message || String(e)), call); continue; }
        const attributes = (data && data.attributes) || [];
        const missing = [column.keyColumn, column.returnColumn].filter(wanted => attributes.length
            && !attributes.some(a => String(a).toLowerCase() === String(wanted).trim().toLowerCase()));
        if (missing.length) {
            addError(said + 'static dataset "' + column.datasetName + '" has no column '
                + missing.map(m => '"' + m + '"').join(' or ') + '.', call);
        }
        lookups.set(column, lookupIndex(data, column.keyColumn));
    }
    return lookups;
}

/**
 * A lookup into another grid on the page: the rows that grid holds right now, indexed by its key
 * column. Read at the moment this grid fills rather than fetched, so the grid looked into has to be
 * filled already — one that is not, or lacks a column, is reported once and the column comes back
 * empty on every row, the rule a dataset lookup follows. The index is built off the grid's current
 * rows, so a grid filled again is indexed afresh.
 */
function gridLookupIndex(column, said, call) {
    const grid = findControl(column.gridControlId);
    // A whole-row lookup names no column to return: every column of the row it finds comes back.
    const wholeRow = enrichKind(column) === WHOLE_ROW_LOOKUP;
    if (!grid || grid.type !== 'grid' || !column.keyColumn || !column.lookupColumn
            || (!wholeRow && !column.returnColumn)) {
        addError(said + 'the lookup needs a grid column, a grid to look into, its key column'
            + (wholeRow ? '.' : ' and a column to return.'), call);
        return null;
    }
    const state = gridState[grid.controlId];
    if (!state) {
        addError(said + 'grid "' + controlTitle(grid) + '" holds no rows yet — have this action Run After the one that fills it.', call);
        return null;
    }
    // Against everything the grid holds rather than everything it is showing: a column the
    // operator turned off in the chooser is off the screen, not out of the rows, and a lookup
    // reads the rows.
    const has = wanted => state.allColumns.some(c => String(c).toLowerCase() === String(wanted).trim().toLowerCase());
    const wanted = wholeRow ? [column.keyColumn] : [column.keyColumn, column.returnColumn];
    const missing = state.rows.length ? wanted.filter(name => !has(name)) : [];
    if (missing.length) {
        addError(said + 'grid "' + controlTitle(grid) + '" has no column ' + missing.map(m => '"' + m + '"').join(' or ') + '.', call);
    }
    return lookupIndex({ rows: state.rows }, column.keyColumn, state.rows);
}

/** One dataset's rows by the value in `keyColumn`; the first row holding a key keeps it. */
function lookupIndex(data, keyColumn, cacheKey) {
    // Cached against whatever identifies these rows: the fetched dataset, or a grid's own rows array.
    const owner = cacheKey || data;
    let byColumn = lookupIndexes.get(owner);
    if (!byColumn) { byColumn = new Map(); lookupIndexes.set(owner, byColumn); }
    if (!byColumn.has(keyColumn)) {
        const index = new Map();
        for (const row of (data && data.rows) || []) {
            if (!row || typeof row !== 'object') continue;
            const key = lookupKey(row[scopeKey(row, keyColumn)]);
            if (key !== '' && !index.has(key)) index.set(key, row);
        }
        byColumn.set(keyColumn, index);
    }
    return byColumn.get(keyColumn);
}

/**
 * The rows with the action's enriched columns added, in the order they are listed so a lookup can
 * read what an earlier column added. Copies rather than writing into the rows handed in: those are
 * the parsed response, which another of the action's targets may be reading at the same moment.
 *
 * @param result  the call the rows came from; null where there was none
 * @param lookups what {@link #enrichmentLookups} fetched for this action
 * @param meta    the record the call-record columns read, when the caller already has one
 */
function enrichRows(rows, action, result, lookups, meta) {
    const columns = enrichColumnsOf(action);
    if (!columns.length) return rows;
    const record = meta || (result ? metaOf(result) : null);
    return rows.map(row => {
        const out = row !== null && typeof row === 'object' && !Array.isArray(row)
            ? Object.assign({}, row) : { value: row };
        columns.forEach(column => {
            if (enrichKind(column) === WHOLE_ROW_LOOKUP) addWholeRow(column, out, lookups);
            else out[column.name] = enrichedCell(column, out, result, record, lookups);
        });
        return out;
    });
}

/**
 * The rows a grid is about to be filled with, grouped first when the action carries a pivot — see
 * AppPagePivot. The rows it was handed are read and never kept: the grid is filled with the
 * grouped table alone, under the columns the grouping produced, whatever columns the grid was
 * laid out with. Without a pivot both come back untouched.
 *
 * <p>Grouped with gridpivot.js, the code the Analyze screen groups with, so a pivot added to the
 * page from there fills its grid with exactly the table it showed. Cells are read the way this
 * grid reads them, ignoring case, so a pivot written against "Status" groups the rows' "status".
 */
function groupedForGrid(action, rows, columns) {
    const spec = action && action.pivot;
    if (!GridPivot.isActive(spec)) return { rows: rows, columns: columns };
    return GridPivot.table(rows, GridPivot.fromSpec(spec), { read: cellText });
}

/**
 * Remembers which action — or which further target of one — filled a grid, so Analyze on that grid
 * can offer to add its analysis back onto the page as an action making the same call. Kept on the
 * grid's state, which goes whenever its rows do.
 */
function noteFilledBy(gridId, action) {
    if (gridState[gridId]) gridState[gridId].filledBy = action;
}

/**
 * Every column of the row a whole-row lookup found, written onto this row behind its prefix — and
 * written empty where it found nothing, so the grid keeps the same columns down every row whether
 * that row matched or not. See AppPageEnrichColumn.GRID_VLOOKUP_ROW.
 *
 * <p>The columns are the ones {@link #enrichColumnNames} put in the grid's column list, so the two
 * cannot drift: a column in the list with no cell under it would be a column of blanks, and a cell
 * under no column would be carried in the rows and never drawn.
 */
function addWholeRow(column, row, lookups) {
    const index = lookups && lookups.get(column);
    const found = index ? index.get(lookupKey(row[scopeKey(row, column.lookupColumn)])) : null;
    const prefix = column.prefix || '';
    wholeRowColumns(column).forEach(name => {
        const value = found ? found[scopeKey(found, name)] : undefined;
        row[prefix + name] = value === undefined || value === null ? '' : value;
    });
}

/**
 * What a regex column makes of one cell: the pattern run over the column it reads, and the match
 * turned into text by the replacement — {@code $1}, {@code $2} … for the capturing groups, {@code $&}
 * for the whole match and {@code $$} for a literal dollar. No replacement means the first group, or
 * the whole match where the pattern captures nothing, which is what the pattern was written for in
 * the ordinary case. No match, no column to read, or a pattern that will not compile leaves the cell
 * empty — one that will not compile is refused at the save, so it can only be one saved elsewhere.
 *
 * <p>A pattern with the `g` flag fills the cell with every match, joined by ", ": "all the ids in
 * this message" is as reasonable a question as "the id in this message", and the flag is how the
 * operator asks it.
 */
function regexCell(column, row) {
    const text = row[scopeKey(row, column.lookupColumn)];
    if (text === undefined || text === null || text === '') return '';
    const pattern = compiledRegex(column.expression);
    if (!pattern) return '';
    const subject = String(text);
    // A fresh index every row: one regex object is reused down the column, and a global or sticky
    // one remembers where it stopped — which would make the second row read from the middle.
    pattern.lastIndex = 0;
    if (!pattern.global) {
        const match = pattern.exec(subject);
        return match ? expandMatch(match, column.replacement) : '';
    }
    const all = [];
    let match;
    while ((match = pattern.exec(subject)) !== null) {
        all.push(expandMatch(match, column.replacement));
        if (match.index === pattern.lastIndex) pattern.lastIndex++;   // an empty match would not advance
    }
    return all.join(', ');
}

// Each pattern compiled once however many rows and columns read it, and a bad one remembered as bad
// so a grid of ten thousand rows does not build and throw away ten thousand of them.
const compiledRegexes = new Map();

/**
 * One enrichment pattern as a RegExp, or null where it will not compile. Written `/pattern/flags` it
 * carries flags — `i` to ignore case, `s` for a dot that crosses lines, `g` for every match; written
 * plainly it is the pattern itself, so a pattern that happens to begin and end with a slash needs no
 * escaping unless it also ends in something that reads as flags.
 */
function compiledRegex(expression) {
    const text = String(expression || '').trim();
    if (!text) return null;
    if (!compiledRegexes.has(text)) {
        const slashes = /^\/(.+)\/([gimsuy]*)$/.exec(text);
        let made = null;
        try { made = slashes ? new RegExp(slashes[1], slashes[2]) : new RegExp(text); }
        catch (e) { made = null; }
        compiledRegexes.set(text, made);
    }
    return compiledRegexes.get(text);
}

/** One match as the replacement describes it; no replacement means the first group, else the match. */
function expandMatch(match, replacement) {
    const template = replacement === undefined || replacement === null ? '' : String(replacement);
    if (!template) {
        const first = match.length > 1 ? match[1] : match[0];
        return first === undefined ? '' : first;
    }
    return template.replace(/\$\$|\$&|\$(\d+)/g, (whole, group) => {
        if (whole === '$$') return '$';
        if (whole === '$&') return match[0];
        const value = match[Number(group)];
        return value === undefined || value === null ? '' : String(value);
    });
}

/** One enriched cell of one row. Empty wherever there was nothing to read. */
function enrichedCell(column, row, result, record, lookups) {
    const kind = enrichKind(column);
    if (kind === 'HEADER') return headerValue(result, column.expression);
    if (kind === 'REGEX') return regexCell(column, row);
    if (kind === 'VLOOKUP' || kind === 'GRID_VLOOKUP') {
        const index = lookups && lookups.get(column);
        if (!index) return '';
        const found = index.get(lookupKey(row[scopeKey(row, column.lookupColumn)]));
        if (!found) return '';
        const value = found[scopeKey(found, column.returnColumn)];
        return value === undefined || value === null ? '' : value;
    }
    const value = record ? record[column.expression] : undefined;
    return value === undefined || value === null ? '' : value;
}

/**
 * One row of a collected fan-out: the call it came from, then whatever that call answered with.
 * An answer already carrying a field of that name keeps its own — it is the data, and renaming it
 * to make room for a label would be the page rewriting the response.
 */
function fanRow(label, answer) {
    const row = {};
    row[FAN_SOURCE_COLUMN] = label;
    if (answer !== null && typeof answer === 'object' && !Array.isArray(answer)) return Object.assign(row, answer);
    row.value = answer;
    return row;
}

/**
 * Takes a tab set's fanned-out tabs away — all of them, or only one action's. The grids behind
 * them go too: a tab whose rows are still in memory but which is no longer on the strip is a grid
 * nothing can reach and nothing will ever clear.
 */
function clearFanTabs(tabsId, actionId) {
    const kept = [];
    (fanTabs[tabsId] || []).forEach(tab => {
        if (actionId && tab.actionId !== actionId) { kept.push(tab); return; }
        delete gridState[tab.gridId];
        delete gridMeta[tab.gridId];
        delete fanRowChecks[tab.gridId];
        delete fanDisplayFilters[tab.gridId];
        if (activeTab[tabsId] === tab.gridId) delete activeTab[tabsId];
    });
    if (kept.length) fanTabs[tabsId] = kept; else delete fanTabs[tabsId];
}

/** Redraws one tab set where it stands and paints everything inside it. */
function paintTabs(control) {
    const host = document.getElementById('rc-' + control.controlId);
    if (!host) return;
    host.innerHTML = tabsRun(control);
    // One call over the new markup, which reaches the nested strips inside it as well: every
    // strip this set redrew needs its buttons live again, not only the topmost one.
    wireTabStrips(host);
    repaintTabChildren(control);
    paintTabsetStatuses();
}

/**
 * Gives back to everything inside a redrawn tab set what replacing its markup took away.
 *
 * <p>Down through nested sets as well as across one strip. {@link #tabsRun} redraws a group's
 * whole subtree in one go, so a grid two strips down has just had its host replaced by an empty
 * one exactly as a grid one strip down has — and the rows, the wiring and the options all live in
 * the DOM rather than in the markup, so each has to be put back wherever it is.
 */
function repaintTabChildren(control, depth) {
    if ((depth || 0) > 20) return;   // a page mid-edit; a saved one cannot nest into itself
    const inside = control.type === 'tabs' ? runTabsOf(control)
        : containerChildren(control).map(k => ({ gridId: k.controlId, type: k.type }));
    inside.forEach(tab => {
        if (tab.type === 'grid') { paintGrid(tab.gridId); return; }
        const child = findControl(tab.gridId);
        if (!child) return;
        // A container inside this one was redrawn with it, so everything under it needs the same
        // — a panel of fields in a tab goes as dead as a nested strip would if it were skipped.
        if (isContainer(child.type)) { repaintTabChildren(child, (depth || 0) + 1); return; }
        // Drawn again rather than left as tabsRun wrote it, so a pie with grids gets its slice
        // clicks wired back on: what carried them was replaced along with the strip above it.
        if (isChart(child.type)) { paintChart(child); return; }
        // And anything else gets back what replacing its pane took away: the listeners that keep
        // the page's values up to date and fire what the control triggers, and — for a dropdown —
        // the options something has already put into it, which live in the DOM and nowhere else
        // until they are kept here. Without this a tab set holding a form would quietly go dead
        // the first time a fan-out added a tab to it.
        wireRunControl(child);
        if (isSelect(child.type) && shownOptions[child.controlId]) {
            fillOptions(child, shownOptions[child.controlId], true);
        }
    });
}

/**
 * The actions grouped into the waves they go out in: everything with nothing to wait for first,
 * then everything waiting on one of those, and so on down. Each wave is sent together, so a
 * chain three deep costs three round trips rather than one per action, and a trigger where
 * nothing waits for anything is a single wave — exactly what it was before waiting existed.
 *
 * <p>An action whose dependency is not in this list has nothing to wait for and joins the first
 * wave. The wait is written on the action, not on the control, so attaching it somewhere the
 * other one is not attached leaves it unheld; the designer is told so beside the wiring, which is
 * the only place it can be put right — see {@link #dependencyNote}.
 *
 * <p>A cycle has no wave it could belong to: nothing in it can start, so nothing in it ever
 * would. Rather than leave those actions in a list that is never reached, they are handed back
 * separately so the run can name each of them and say why it did not send it.
 *
 * @return the waves in order, the index each action waits for (-1 for none), and the indexes of
 *         the actions caught in a cycle
 */
function runWaves(actions) {
    // First occurrence wins: the same page action attached twice to one control is one action
    // as far as anything waiting on it is concerned, and the earlier of the two is the one
    // whose answer a later wave would be reading.
    const at = new Map();
    actions.forEach((a, i) => { if (a.actionId && !at.has(a.actionId)) at.set(a.actionId, i); });
    const waitsFor = actions.map(a => {
        const found = a.dependsOnActionId ? at.get(a.dependsOnActionId) : undefined;
        return found === undefined ? -1 : found;
    });

    const waves = [];
    const placed = new Array(actions.length).fill(false);
    for (;;) {
        // Collected before any of them is marked, or an action would join the same wave as the
        // one it waits for and the wait would buy nothing.
        const wave = [];
        for (let i = 0; i < actions.length; i++) {
            if (placed[i]) continue;
            if (waitsFor[i] < 0 || placed[waitsFor[i]]) wave.push(i);
        }
        if (!wave.length) break;
        wave.forEach(i => { placed[i] = true; });
        waves.push(wave);
    }
    const cyclic = [];
    for (let i = 0; i < actions.length; i++) if (!placed[i]) cyclic.push(i);
    return { waves: waves, waitsFor: waitsFor, cyclic: cyclic };
}

/**
 * Puts one action's result where it is aimed — a stacked grid, a placed grid, a box, a dropdown.
 *
 * <p>{@code result} is the whole execution record rather than just what was bound out of it: a
 * grid reports the call behind it — the URL, the method, the status, how long it took, how big
 * the answer was — and that is on the record, not in the rows.
 *
 * @param failure when the call failed, what to say about it. The data is bound exactly as a
 *                successful call's would be — it came off the same response — but everything
 *                that shows a record shows this one as a failure, so a grid filled from a 500
 *                never reads as a grid that worked. See {@link #bindFailure}.
 */
async function bindAction(action, data, name, result, call, failure, scope) {
    if (!action.targetControlId) return;
    const outcome = failure ? 'FAILED' : 'SUCCESS';
    const why = failure || '';

    // Both paths are resolved here rather than where they are read, so a path naming a control
    // sees the values as they stand at the moment this action binds — including anything an
    // earlier action in the same trigger has just put on the page.
    const arrayPath = resolvePath(action.arrayPath, name, scope);
    const valuePath = resolvePath(action.valuePath, name, scope);

    if (action.targetControlId === NEW_GRID) {
        const stacked = rowsForGridAction(data, action, arrayPath, name);
        const lookups = await enrichmentLookups(action, name, call);
        const grouped = groupedForGrid(action, keptForBinding(action, enrichRows(stacked.rows, action, result, lookups)),
            withEnrichedColumns(stacked.columns, action));
        noteFilledBy(pushStackedGrid(name, grouped.rows, grouped.columns, callRecord(result, outcome, why, call)), action);
        return;
    }
    const target = findControl(action.targetControlId);
    if (!target) { addError(name + ': its target is no longer on this page.', call); return; }
    if (target.type === 'grid') {
        const bound = rowsForGridAction(data, action, arrayPath, name);
        const lookups = await enrichmentLookups(action, name, call);
        // Recorded before the rows go in, so the grid is painted once, already knowing what it
        // has to say about the call that filled it.
        gridMeta[target.controlId] = callRecord(result, outcome, why, call);
        const grouped = groupedForGrid(action, keptForBinding(action, enrichRows(bound.rows, action, result, lookups)),
            withEnrichedColumns(bound.columns || target.columns, action));
        bindGrid(target, grouped.rows, grouped.columns, appendsToGrid(action));
        noteFilledBy(target.controlId, action);
    } else if (isChart(target.type)) {
        // Same shape as the grid above and for the same reason: the marks are read out first, so
        // a path that finds nothing leaves the last record where it was, and then the record goes
        // in before them, so the chart is drawn once already knowing what it has to say about the
        // call behind it.
        const shape = chartRowsAt(data, action, arrayPath, name);
        drawChartFrom(target, shape, callRecord(result, outcome, why, call), name, call);
    } else if (target.type === 'link') {
        bindLink(target, pathGet(data, valuePath), valuePath, name, call);
    } else if (target.type === 'text' || target.type === 'textarea') {
        bindValue(target, pathGet(data, valuePath), valuePath, name, call);
    } else {
        // Filtered on the rows rather than on the options made from them, so a filter may test a
        // column the dropdown does not show — keep the environments whose class is PROD, and
        // show their names.
        fillOptions(target, keptForBinding(action, rowsAt(data, arrayPath, name))
            .map(r => optionOf(r, action.keyField, action.labelField)));
    }
}

/**
 * Puts a failed call where the action was aimed anyway, and hands back what to say about it.
 *
 * <p>A call that came back 4xx or 5xx with a body has answered — just not with the answer that
 * was wanted — and that body is very often the most useful thing on the screen: the validation
 * errors, the rejected rows, the message the endpoint took the trouble to write. So it is read
 * exactly as a success would be, transforms and paths and all, and bound into the grid, chart
 * or box the action names. What stops it reading as a call that worked is the record that goes
 * in with it, which says failure and carries the reason.
 *
 * <p>A failure with nothing to read — no body, or nothing the action's chain could make of it —
 * falls back to what has always happened: the target says it failed and shows why. The message
 * then carries both halves, since a chain that could not read the body is usually a chain
 * meeting an error page rather than the response it was written against.
 *
 * @return the message to report, which is {@code failure} unless reading the body added to it
 */
async function bindFailure(action, name, result, call, failure, scope) {
    let why = failure;
    const roots = new Map();
    for (const binding of bindingsOf(action)) {
        const label = bindingName(binding, name);
        if (!result || (!isMetadataAction(binding) && !hasPayload(result))) {
            noteOneTargetFailure(binding, label, result, failure, call);
            continue;
        }
        try {
            await bindAction(binding, await sharedRoot(roots, result, binding, label), label, result, call, failure, scope);
        } catch (e) {
            const unread = ' Its response could not be read either: ' + (e.message || String(e));
            noteOneTargetFailure(binding, label, result, failure + unread, call);
            why += unread;
        }
    }
    return why;
}

/**
 * Where one action's answer goes: the target written on the action itself, then each of its
 * further bindings, laid over the action so every binding reads exactly like an action of its own
 * whose call has already been made. A fan-out and a performance summary have only the first —
 * neither has one response to read twice, and the catalog refuses the others on them.
 *
 * <p>The fields a binding does not carry are blanked rather than inherited: a select's key field
 * written on the action has nothing to say about the pie chart the second binding fills.
 */
function bindingsOf(action) {
    if (!action || isSpecialAction(action) || isFanOut(action)) return [action];
    const extra = (action.extraBindings || []).filter(b => b && b.targetControlId);
    return [action].concat(extra.map(b => Object.assign({}, action, blankBinding(), b,
        { extraBindings: [], bindingOf: action })));
}

/**
 * What a binding is called in what it reports. The action's own target keeps the action's name,
 * which is what every action has always reported under; a further binding adds the control it
 * fills, since "Orders: nothing found at path" twice over does not say which of the two it was.
 */
function bindingName(binding, name) {
    if (!binding || !binding.bindingOf) return name;
    const target = binding.targetControlId === NEW_GRID ? null : findControl(binding.targetControlId);
    return name + ' → ' + (binding.targetControlId === NEW_GRID ? 'new grid'
        : target ? controlTitle(target) : 'a control that is no longer here');
}

/**
 * The root a binding reads out of, computed once per source and transform chain within one bind —
 * a body of some megabytes is parsed once however many of the action's targets read it untouched.
 */
function sharedRoot(roots, result, binding, name) {
    const key = JSON.stringify([isMetadataAction(binding), binding.transformNames || []]);
    if (!roots.has(key)) roots.set(key, rootFor(result, binding, name));
    return roots.get(key);
}

/**
 * Binds a successful call into every target the action has, each one on its own: a binding whose
 * path finds nothing marks its own control as failed and the rest still bind.
 *
 * @return what went wrong, one message per binding that could not bind; empty when all of them did
 */
async function bindEveryTarget(action, name, result, call, scope) {
    const problems = [];
    const roots = new Map();
    for (const binding of bindingsOf(action)) {
        const label = bindingName(binding, name);
        try {
            await bindAction(binding, await sharedRoot(roots, result, binding, label), label, result, call, '', scope);
        } catch (e) {
            // A shared root that failed once fails every binding sharing it; each still says so.
            const why = e.message || String(e);
            noteOneTargetFailure(binding, label, result, why, call);
            problems.push(why);
        }
    }
    return problems;
}

/**
 * A path with the page's own values filled in — {@code data[id="${auctionId}"]/referenceEntities}
 * reads the row the operator picked rather than one fixed when the page was designed. Only the
 * braced form is substituted: a bare {@code $} starts a path far more often than it names a
 * field, and {@code $.items[0]} has always been a legal thing to write here.
 *
 * <p>An unanswered placeholder throws rather than becoming empty. An empty filter silently
 * matches nothing, and "the grid came back empty" is a much worse thing to hand someone than
 * "the path needs a value this page has not got".
 */
function resolvePath(path, name, row) {
    if (!path) return path || '';
    return String(path).replace(/\$\{([A-Za-z0-9_.\-]+)\}/g, (match, field) => {
        const value = scopedValue(field, row);
        if (value === undefined || value === null || value === '') {
            throw new Error(name + ': the path needs ' + match + ', and "' + field + '"'
                + (row && ROW_SCOPE_MARK in row
                    ? ' is neither a column of the row, a control on this page, nor a page variable.'
                    : ' is neither a control on this page nor a page variable.'));
        }
        return String(value);
    });
}

/**
 * What a {@code ${name}} means where it is written: a column of the row an action is being run
 * for, and failing that a control of that name on the page.
 *
 * <p>The row wins because that is the whole point of fanning out — one action written once,
 * asking about each row in turn — while the page still answers for everything the row has no
 * column for, so a fan-out can carry the environment select's value along with the row's own id
 * without the grid having to hold a column for it.
 *
 * <p>Present-but-empty still counts as the row's answer: a blank cell is what that row says, and
 * quietly falling through to a control of the same name would send another row's business.
 */
function scopedValue(field, row) {
    // A row's column answers whatever case it is written in; controls and variables keep theirs.
    if (row && typeof row === 'object' && scopeKey(row, field) in row) return row[scopeKey(row, field)];
    if (field in values) return values[field];
    return globals[field];
}

/** Whether anything in scope answers to this name at all — see {@link #scopedValue}. */
function scopedHas(field, row) {
    return (row && typeof row === 'object' && scopeKey(row, field) in row) || (field in values) || (field in globals);
}

// ── The page's variables ──────────────────────────────────────────────
// Beneath the row and beneath the controls sits a third answer to ${name}: the values the page
// has rather than the ones the operator supplies. Some are the run's own — the machine, the
// moment, a fresh UUID — and the rest are whatever the page declared. Both are read exactly as a
// control is, which is the point: nothing downstream needs to know where ${DATESTAMP} came from
// any more than it needs to know ${orderId} came from a text box.

/**
 * Works out what the built-in variables stand for now, then resolves the page's own against
 * them. Called when something sets the page off rather than when the page opens, so the date and
 * time a call carries are the date and time it was made.
 *
 * <p>The ad-hoc ones are resolved in the order they are listed and into the same object they are
 * read out of, so each may be written in terms of the built-ins and of the ones above it —
 * <code>${DATESTAMP}-${runBy}</code> is a legal thing to declare. Above them and not below: a
 * variable naming one listed later reads as not yet set, rather than as whatever it held the
 * last time the page ran.
 *
 * <p>ROWNUM is deliberately absent. It is a fact about a row, and outside a fan-out there is no
 * row — so an input written against it is left off the call entirely and the instance keeps the
 * value it was saved with, which is what every other unanswered placeholder does.
 */
function refreshGlobals() {
    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const date = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate());
    globals = {
        MACHINE:    machineName,
        PID:        processId,
        DATESTAMP:  date,
        PREVDATESTAMP: stampOf(businessDay(now, -1)),
        NEXTDATESTAMP: stampOf(businessDay(now, 1)),
        DATETIME:   date + pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds()),
        DATETIMEHR: now.toLocaleString(),
        UUID:       newUuid(),
        // A boolean rather than the string "true", so an input that is nothing but ${DEBUG}
        // passes it through as one — the same rule a checkbox control's value follows.
        DEBUG:      pageDebug()
    };
    (page.variables || []).forEach(variable => {
        if (!variable || !variable.name) return;
        globals[variable.name] = resolveTemplate(variable.value || '');
    });
}

/**
 * Whether this page is keeping the detail behind its calls — what ${DEBUG} comes to, and the
 * one question every piece of the keeping asks before it keeps anything.
 *
 * <p>Read through a function rather than off the page directly because it is asked in the middle
 * of a run, and a page that has never been hydrated — or one being previewed before it is saved
 * — should still answer something rather than undefined.
 */
function pageDebug() {
    return !page || page.debug !== false;
}

/**
 * The nearest business day in the given direction — one day off the one given, then on past any
 * Saturday and Sunday. Weekends only: there is no holiday calendar here, and guessing at one
 * would be worse than a rule everybody can state. The same rule the server applies to the same
 * two names — see AppExecutionService#businessDay.
 *
 * @param step -1 for the previous business day, +1 for the next
 */
function businessDay(from, step) {
    const day = new Date(from.getFullYear(), from.getMonth(), from.getDate());
    do {
        day.setDate(day.getDate() + step);
    } while (day.getDay() === 0 || day.getDay() === 6);
    return day;
}

/** A date as the yyyyMMdd the datestamp built-ins are written in. */
function stampOf(day) {
    const pad = n => String(n).padStart(2, '0');
    return day.getFullYear() + pad(day.getMonth() + 1) + pad(day.getDate());
}

/** A UUID, from the browser's own generator where there is one and from Math.random otherwise. */
function newUuid() {
    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, ch => {
        const r = Math.random() * 16 | 0;
        return (ch === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
}

/**
 * What one call resolves its templates against, over and above the page and its variables: the
 * row it is being made for, which row that is, and a UUID of its own.
 *
 * <p>The UUID is here rather than only in {@link #refreshGlobals} because "a unique uuid" over a
 * fan-out of forty rows means forty of them — a correlation id every call shares is no
 * correlation id at all. Written twice inside one call it is still one value, since it is settled
 * once, here, before anything reads it.
 *
 * @param row   the grid row this call is for, or nothing for an action that runs once
 * @param index that row's place in the rows being run over, from 0
 */
function actionScope(row, index) {
    const scope = { UUID: newUuid() };
    if (row && typeof row === 'object') {
        // The row's own columns win over the UUID above, and ROWNUM below wins over the row: a
        // column called UUID is the endpoint's data and belongs to the row, while ROWNUM is not
        // data at all and has one true answer.
        Object.assign(scope, row);
        scope.ROWNUM = (index || 0) + 1;
        Object.defineProperty(scope, ROW_SCOPE_MARK, { value: true });
    }
    return scope;
}

/**
 * Replaces ${field} / $field in each input with the page's current values — or, for an action
 * fanned out over a grid, with the row's own columns before the page's values. See
 * {@link #scopedValue}.
 */
function resolveInputs(inputs, row) {
    const resolved = {};
    Object.entries(inputs || {}).forEach(([name, template]) => {
        if (typeof template !== 'string') { resolved[name] = template; return; }
        const whole = template.match(/^\$\{([A-Za-z0-9_.\-]+)\}$|^\$([A-Za-z_][A-Za-z0-9_]*)$/);
        if (whole) {
            const field = whole[1] || whole[2];
            // A template that is nothing but one placeholder passes the value through with its
            // own type, so a checkbox stays a boolean instead of becoming "true". A placeholder
            // nothing in scope answers to is left out entirely, so the instance keeps the value
            // it was saved with rather than being handed an empty one.
            if (scopedHas(field, row)) resolved[name] = scopedValue(field, row);
            return;
        }
        resolved[name] = template.replace(/\$\{([A-Za-z0-9_.\-]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g,
            (match, braced, bare) => {
                const value = scopedValue(braced || bare, row);
                return value === undefined || value === null ? match
                    : typeof value === 'object' ? JSON.stringify(value) : String(value);
            });
    });
    return resolved;
}

/**
 * A single template resolved the same way {@link #resolveInputs} resolves each input — but
 * missing values disappear rather than surviving as literal {@code ${name}} text, since this
 * feeds the environment override, where an unresolved placeholder is not a sensible thing to
 * send: it should mean "no override" instead.
 */
function resolveTemplate(template, row) {
    if (!template) return '';
    return String(template).replace(/\$\{([A-Za-z0-9_.\-]+)\}|\$([A-Za-z_][A-Za-z0-9_]*)/g,
        (match, braced, bare) => {
            const value = scopedValue(braced || bare, row);
            return value === undefined || value === null ? ''
                : typeof value === 'object' ? JSON.stringify(value) : String(value);
        });
}

/**
 * Runs one instance and hands back the whole execution record — the response and the call's own
 * metadata together. Whether the caller wants rows, one attribute, or the status code is a
 * separate question answered by {@link #rootFor}, since the same run can feed a grid, a dropdown,
 * a text box or a metadata panel.
 *
 * <p>The call itself is unchanged by the page's DEBUG switch — the request that goes out and the
 * answer handed back are the same either way. What the switch reaches is what is kept once the
 * answer is in: see {@link #runDetail} for this side of it and the run endpoint for the server's.
 *
 * <p>Nothing is thrown for a failed call: a 500 is a perfectly good thing to bind metadata from,
 * and it is the caller that knows whether this run was allowed to fail. See {@link #failureMessage}
 * and {@link #bindFailure}.
 *
 * @param environment  overrides which of the instance's environments this call goes to; blank
 *                     leaves the instance's own environment untouched
 * @param metadataOnly when true the bodies are left on the server — nothing downstream is going
 *                     to read them, and a 30 MB response is not worth the wire or the heap
 * @param ownCall      keeps this call off the trigger's shared cache. Two actions that ask for
 *                     the same instance, environment and inputs otherwise share one response,
 *                     which is what you want when they only differ in how they read it and
 *                     exactly what you do not want when the call itself is the point — a POST
 *                     that re-sends something has to go out as many times as it is asked to
 */
async function runExecution(instanceId, inputs, name, environment, metadataOnly, ownCall) {
    if (!instanceId) throw new Error(name + ': no use case instance is configured.');
    const request = {
        appUseCaseInstanceId: instanceId,
        inputs: inputs,
        environment: environment || '',
        includePayload: !metadataOnly,
        // What this call needs and what the server should go on holding afterwards are two
        // different questions, which is why this is not includePayload: a DEBUG-off page still
        // wants the body — it is about to bind it into a grid — and still does not want it filed
        // away for a "fetch bodies" button nobody is going to press.
        debug: pageDebug()
    };
    if (ownCall || !callCache) return AC.api('POST', '/appcatalog/pages/run', request);

    // Everything the server is told, with the inputs put in a fixed order so two actions that
    // happen to list them differently still recognise each other as the same call. The promise
    // is what is cached, not the result, so actions asking at the same time share one flight.
    const key = JSON.stringify([request.appUseCaseInstanceId, request.environment, request.includePayload,
        Object.keys(inputs || {}).sort().map(k => [k, inputs[k]])]);
    if (!callCache.has(key)) callCache.set(key, AC.api('POST', '/appcatalog/pages/run', request));
    return callCache.get(key);
}

/**
 * What to say about a call that did not come back 2xx, or the empty string when it did — which
 * makes it the test for whether a result succeeded as well as the words for when it did not.
 */
function failureMessage(result, name) {
    if (result && result.status === 'SUCCESS') return '';
    if (!result) return name + ' failed: nothing came back from the call.';
    return name + ' failed: ' + (result.error || ('HTTP ' + (result.statusCode || '?'))) + '.';
}

/**
 * Whether a result came back with something worth reading — which is what decides, for a call
 * that failed, between binding its body and only reporting what went wrong. The server's own
 * transform counts even when it produced something falsy, since that is still what it made of
 * the response; a body of nothing but whitespace does not.
 */
function hasPayload(result) {
    if (!result) return false;
    if (result.transformedResponse !== undefined && result.transformedResponse !== null) return true;
    return !!(result.responseBody && String(result.responseBody).trim());
}

/**
 * The response body of a result, parsed — the transform's output when the instance has one.
 *
 * <p>A body that is not JSON is handed back as the text it arrived as rather than as nothing,
 * which is what makes an <code>xml&#8594;json</code> step possible: the step needs the document,
 * and by the time anything else looks at it the parse has already failed. A path read out of a
 * string finds nothing, exactly as it found nothing in the null this used to return.
 */
function payloadOf(result) {
    let data = result.transformedResponse;
    if (data === undefined || data === null) {
        try { data = JSON.parse(result.responseBody || 'null'); } catch (e) { data = result.responseBody; }
    }
    return data;
}

/**
 * The call's metadata as a flat object, which is what makes it bindable by exactly the machinery
 * the payload uses: a key/value grid of the whole thing, a text box showing
 * <code>statusCode</code>, a stacked grid per run. Flat and shallow on purpose — every value here
 * is meant to be read in a cell without being drilled into.
 *
 * <p>Sizes come off the record when the server computed them and off the bodies otherwise: a run
 * that shipped its payload reports them as null, since nothing had dropped the bodies to measure.
 */
function metaOf(result) {
    const size = (reported, body) =>
        (reported !== undefined && reported !== null) ? reported : (body ? String(body).length : 0);
    return {
        executionId:  result.executionId,
        status:       result.status,
        statusCode:   result.statusCode,
        httpMethod:   result.httpMethod,
        url:          result.url,
        timeTaken:    result.timeTaken,
        appName:      result.appName,
        environment:  result.environment,
        envClass:     result.envClass,
        useCase:      result.useCase,
        instanceLabel:        result.instanceLabel,
        appUseCaseInstanceId: result.appUseCaseInstanceId,
        requestSize:  size(result.requestBodySize, result.requestBody),
        responseSize: size(result.responseBodySize, result.responseBody),
        executedVia:  result.executedVia,
        startedAt:    result.startedAt,
        startedAtText: result.startedAt ? new Date(result.startedAt).toLocaleString() : '',
        runIndex:     result.runIndex,
        runCount:     result.runCount,
        unresolvedVariables: (result.unresolvedVariables || []).join(', '),
        error:        result.error || ''
    };
}

/**
 * One call as the run is going to keep it, which on a page with its DEBUG switch off is rather
 * less than what came back.
 *
 * <p>Nothing here touches what the page does with the call. The result itself is handed on whole
 * and bound exactly as it always was — the grid fills, the transform runs, the dropdown gets its
 * options — and only the copy kept behind in {@code lastRun} for Technical Details is trimmed.
 * That copy is the expensive one: it outlives the run, and on a page left open all afternoon it
 * is forty calls' worth of request and response bodies plus the parsed object beside each.
 *
 * <p>What goes is what can be arbitrarily large: the two bodies and what the server made of the
 * response. Their sizes are measured first and kept, so the summary table still says how big the
 * call was — most of a performance question is answered by the size and the timing rather than
 * by the text. The headers stay for the same reason the server keeps them on a payload-free
 * copy: a few hundred bytes even on a chatty endpoint, and the first thing anyone reads when a
 * call comes back wrong.
 */
function runDetail(result) {
    if (!result || pageDebug()) return result;
    const light = Object.assign({}, result);
    light.requestBodySize  = techSize(result.requestBodySize, result.requestBody);
    light.responseBodySize = techSize(result.responseBodySize, result.responseBody);
    light.requestBody = null;
    light.responseBody = null;
    light.transformedResponse = null;
    // Tells the report which absence this is. A metadata action's bodies are on the server and
    // can be pulled back; these were never kept anywhere, so the report says so plainly rather
    // than offering a button that would come back with nothing.
    light.bodiesDropped = true;
    return light;
}

/**
 * What a grid says about the call that filled it: the outcome its name reports, the record its
 * metadata bar folds out, and — when it failed — why.
 *
 * <p>A record is kept for a failure as much as for a success, and is in fact worth more there: a
 * grid that came back empty because the endpoint answered 503 and a grid that came back empty
 * because there was nothing to return look identical until something says which happened.
 */
function callRecord(result, status, error, call, note) {
    return {
        status: status,
        meta: result ? metaOf(result) : null,
        // What to say in place of the method-status-timing line when there was no call to make
        // one out of. Blank for every ordinary action, which has a call and describes it.
        note: note || '',
        error: error || '',
        expanded: false,
        // Where in the last run this call sits, so what shows the record can offer the request
        // and the response behind it. Stamped with the run it belongs to as well: a grid keeps
        // its metadata bar across later triggers, and by then the same number would open a
        // different call — see #showTechDetails.
        call: (call === undefined || call === null) ? null : call,
        runAt: lastRun ? lastRun.at : null
    };
}

/**
 * Marks whatever an action was aimed at as failed, so the failure is visible where the rows or
 * the wedges were meant to be rather than only in the list at the top of the page. A "new grid"
 * target still gets its grid — an empty one carrying the status and the URL, which is the whole
 * of what there is to report.
 *
 * <p>Also used for an action that was never sent, where there is no result at all: the record is
 * then the message alone, which is the truthful thing to put where the rows would have been.
 */
function noteTargetFailure(action, name, result, message, call) {
    bindingsOf(action).forEach(binding =>
        noteOneTargetFailure(binding, bindingName(binding, name), result, message, call));
}

/** {@link #noteTargetFailure} for one of an action's targets. */
function noteOneTargetFailure(action, name, result, message, call) {
    const record = callRecord(result, 'FAILED', message, call);
    if (action.targetControlId === NEW_GRID) {
        pushStackedGrid(name, [], null, record);
        return;
    }
    const target = findControl(action.targetControlId);
    if (!target) return;
    if (target.type === 'tabs') {
        // A fan-out that never got as far as sending anything has no tabs to report into, so the
        // ones it left behind last time go rather than standing as this run's answer. What
        // happened is in the error list, which is where a failure with no grid to sit in belongs.
        clearFanTabs(target.controlId, action.actionId);
        paintTabs(target);
    } else if (target.type === 'grid') {
        gridMeta[target.controlId] = record;
        paintGrid(target.controlId);
        // A chart drawn from this grid is drawn from rows that never came, and says so the same way.
        chartsFromGrid(target.controlId).forEach(chart => {
            clearChartData(chart);
            pieMeta[chart.controlId] = record;
            paintChart(chart);
        });
        // As is a grid copying its rows from it.
        gridsFromGrid(target.controlId).forEach(copy => {
            if (copy.controlId === target.controlId) return;
            delete gridState[copy.controlId];
            gridMeta[copy.controlId] = record;
            paintGrid(copy.controlId);
        });
    } else if (isChart(target.type)) {
        // The slices go as well as the record arriving: a chart still showing the wedges the
        // designer typed in, under a call that failed, reads as a chart that was filled.
        clearChartData(target);
        pieMeta[target.controlId] = record;
        paintChart(target);
    }
}

/** A byte count as something readable in a one-line summary. */
function formatBytes(bytes) {
    if (bytes === undefined || bytes === null || isNaN(bytes)) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

/**
 * Which object an action's paths are read out of: the body, or the call's metadata, put through
 * the action's chain of transforms. Order matters and is deliberate — the chain reshapes, then
 * the path picks out of what it produced, so the steps can turn an awkward response into the
 * plain array a grid wants and the path can stay empty.
 */
async function rootFor(result, action, name) {
    const root = isMetadataAction(action) ? metaOf(result) : payloadOf(result);
    return applyTransforms(root, action, name);
}

/** One of the page's named steps by name, or nothing. */
function transformNamed(name) {
    return (page.transforms || []).find(t => t.name === name) || null;
}

/**
 * Runs the action's chain, each step over what the one before it produced, or hands the data
 * straight back when the chain is empty. A name the library no longer holds is skipped rather
 * than fatal: binding the response as it arrived is what every action did before transforms
 * existed, so a deleted step degrades to the old behaviour rather than breaking the page.
 */
async function applyTransforms(data, action, name) {
    let current = data;
    for (const stepName of (action && action.transformNames) || []) {
        current = await applyTransformStep(current, stepName, name);
    }
    return current;
}

/** One step of a chain: an XML parse, or a JSONata evaluation, over whatever it was handed. */
async function applyTransformStep(data, stepName, name) {
    const transform = transformNamed(stepName);
    if (!transform) return data;
    if (transform.type === 'XML2JSON') return xmlToJsonValue(data, stepName, name);
    // A step naming a shared expression the library has not got is fatal, unlike a chain naming
    // a step the page has not got: the missing step was removed from this page by whoever was
    // editing it, while the missing library entry was removed somewhere else entirely, and
    // binding the unreshaped response would put the wrong thing on screen with no sign of why.
    if (transform.jsonataRef && !sharedJsonata(transform.jsonataRef)) {
        throw new Error(name + ': transform "' + stepName + '" names the shared JSONata "'
            + transform.jsonataRef + '", which is not in the library.');
    }
    const expression = transformExpression(transform);
    if (!expression || !String(expression).trim()) return data;
    if (typeof jsonata !== 'function') {
        throw new Error(name + ': the JSONata library did not load, so "' + stepName
            + '" cannot run — this page needs the network for it.');
    }
    // Resolved before it is compiled, and cached under the resolved text: two runs with two
    // different order ids are two expressions, and handing the second one the first one's
    // compiled form would quietly read the wrong row.
    const text = resolveExpression(expression, stepName, name);
    try {
        if (!compiledTransforms.has(text)) compiledTransforms.set(text, jsonata(text));
        return await compiledTransforms.get(text).evaluate(data);
    } catch (e) {
        compiledTransforms.delete(text);
        throw new Error(name + ': JSONata "' + stepName + '" failed: ' + (e.message || e));
    }
}

/**
 * A JSONata expression with the page's own values filled in, so a step can be written against
 * what the operator entered rather than against a value fixed when the page was designed:
 * {@code data[id = "${orderId}"].lines} keeps the lines of the order that was actually asked
 * about. The same braced grammar {@link #resolvePath} uses, for the same reason — one page, one
 * way of naming a control.
 *
 * <p>Only the braced form is taken. JSONata spends {@code $} on itself — {@code $sum},
 * {@code $map}, {@code $$}, and a bare {@code $} for the context — so claiming {@code $name}
 * here would rewrite the language out from under whoever wrote the expression;
 * <code>${name}</code> is not JSONata syntax at all.
 *
 * <p>Substituted as written, without quoting: whether a value belongs in the expression as a
 * string or as a number is the author's decision, made by writing {@code id = "${orderId}"} or
 * {@code seq = ${seq}}. Quoting here would take that choice away.
 *
 * <p>An unanswered placeholder throws rather than becoming empty, exactly as it does in a path:
 * an empty filter silently matches nothing, and "the grid came back empty" is a far worse thing
 * to hand someone than "the expression needs a value this page has not got".
 */
function resolveExpression(expression, stepName, name) {
    return String(expression).replace(/\$\{([A-Za-z0-9_.\-]+)\}/g, (match, field) => {
        const value = values[field];
        if (value === undefined || value === null || value === '') {
            throw new Error(name + ': transform "' + stepName + '" needs ' + match
                + ', and "' + field + '" has no value on this page.');
        }
        return String(value);
    });
}

/**
 * The XML step. It converts a document, so it wants the response as text — which is what it gets
 * when it runs first, since a body that would not parse as JSON is passed along as it arrived.
 * Handed anything else, it says so rather than quietly producing an object of nothing: a chain
 * with this step in the wrong place is a mistake worth reading about.
 */
function xmlToJsonValue(data, stepName, name) {
    if (data === null || data === undefined || data === '') {
        throw new Error(name + ': transform "' + stepName + '" had no XML to convert — the response was empty.');
    }
    if (typeof data !== 'string') {
        throw new Error(name + ': transform "' + stepName + '" converts XML text, but this far along the chain '
            + 'it was handed ' + (Array.isArray(data) ? 'an array' : 'a ' + typeof data)
            + ' — an xml→json step belongs first, on the body as it arrived.');
    }
    const doc = new DOMParser().parseFromString(data.trim(), 'application/xml');
    const failure = doc.querySelector('parsererror');
    if (failure) {
        throw new Error(name + ': transform "' + stepName + '" could not parse the response as XML: '
            + failure.textContent.trim().split('\n')[0]);
    }
    return xmlNodeToObj(doc.documentElement);
}

/**
 * An XML element as a plain object, the same shape the catalog's XML-to-JSON utility produces —
 * elements become keys, a tag that repeats becomes an array, attributes land under
 * <code>@attributes</code>, text under <code>#text</code>, and an element that is only text
 * collapses to that text so a leaf reads as a value in a grid cell.
 */
function xmlNodeToObj(node) {
    const obj = {};
    if (node.attributes && node.attributes.length > 0) {
        obj['@attributes'] = {};
        for (const attr of node.attributes) obj['@attributes'][attr.name] = attr.value;
    }
    for (const child of node.childNodes) {
        if (child.nodeType === Node.TEXT_NODE || child.nodeType === Node.CDATA_SECTION_NODE) {
            const text = child.nodeValue.trim();
            if (text) obj['#text'] = (obj['#text'] ? obj['#text'] + text : text);
        } else if (child.nodeType === Node.ELEMENT_NODE) {
            const key = child.tagName;
            const value = xmlNodeToObj(child);
            if (obj[key] === undefined) obj[key] = value;
            else if (Array.isArray(obj[key])) obj[key].push(value);
            else obj[key] = [obj[key], value];
        }
    }
    const keys = Object.keys(obj);
    return keys.length === 1 && keys[0] === '#text' ? obj['#text'] : obj;
}

function isMetadataAction(action) {
    return (action && action.source) === 'METADATA';
}

/**
 * Runs an instance and hands back its payload, failing loudly — the older, narrower contract,
 * still exactly what a select filling its own options wants. A failed call is nothing to a
 * dropdown: there is no record beside it to say the list is an error rather than the choices,
 * so an empty list and the reason are the honest answer.
 */
async function runInstance(instanceId, inputs, name, environment) {
    const result = await runExecution(instanceId, inputs, name, environment, false);
    const failure = failureMessage(result, name);
    if (failure) throw new Error(failure);
    return payloadOf(result);
}

/** The array a grid or a dropdown needs, or an explanation of why the response is not one. */
function rowsAt(data, arrayPath, name) {
    const found = pathGet(data, arrayPath);
    if (found === undefined || found === null) throw new Error(name + ': nothing found at path "' + (arrayPath || '') + '".');
    if (!Array.isArray(found)) throw new Error(name + ': expected an array' + (arrayPath ? ' at "' + arrayPath + '"' : '') + ', got ' + typeof found + '.');
    return found;
}

/**
 * The rows a grid-bound action produces. An array works exactly like {@link #rowsAt} always did;
 * when {@link AppPageAction#keyValueGrid} is on and the response is a JSON object instead, its
 * own top-level properties become the rows of a two-column key/value grid rather than failing
 * the action.
 *
 * <p>A metadata action is never an array — the record it binds is one call — so an object there
 * is always meant, and the checkbox chooses how to read it: down the page as key/value, which is
 * how a "call details" panel wants it, or across as a single row, which is what makes each run
 * stack into a table comparable with the ones above it.
 */
function rowsForGridAction(data, action, arrayPath, name) {
    const found = pathGet(data, arrayPath);
    if (found === undefined || found === null) throw new Error(name + ': nothing found at path "' + (arrayPath || '') + '".');
    if (Array.isArray(found)) return { rows: found, columns: null };
    if (typeof found === 'object') {
        if (action.keyValueGrid) {
            return { rows: keyValueRows(found, action.scalarsOnly), columns: ['key', 'value'] };
        }
        if (isMetadataAction(action)) {
            return { rows: [action.scalarsOnly ? scalarProperties(found) : found], columns: null };
        }
    }
    throw new Error(name + ': expected an array' + (arrayPath ? ' at "' + arrayPath + '"' : '') + ', got ' + typeof found + '.');
}

/**
 * Whether a value is something a cell can actually hold: text, a number, true/false, or nothing.
 * Null counts — an empty cell is a perfectly good reading of a property that is not set — and
 * everything else is a document in its own right that a grid has no shape for.
 */
function isScalarCell(value) {
    return value === null || typeof value !== 'object';
}

/**
 * A JSON object as the rows of a two-column key/value grid: a row per property, in the order the
 * response listed them.
 *
 * @param scalarsOnly leave the properties that are objects or arrays out altogether, rather than
 *                    putting each one in as the JSON text it is — see {@link #scalarsOnlyBox}
 */
function keyValueRows(object, scalarsOnly) {
    return Object.entries(object)
        .filter(([, value]) => !scalarsOnly || isScalarCell(value))
        .map(([key, value]) => ({ key: key, value: isScalarCell(value) ? value : JSON.stringify(value) }));
}

/**
 * An object with only its plain attributes left — the across-the-page reading of the same
 * narrowing, for a metadata record bound as one row rather than down the page.
 */
function scalarProperties(object) {
    const out = {};
    Object.entries(object).forEach(([key, value]) => { if (isScalarCell(value)) out[key] = value; });
    return out;
}

/**
 * Reads a value out of a response by path. Beyond the dotted names it has always taken —
 * {@code $.data.items[0].name} still means what it meant:
 *
 * <ul>
 *   <li>{@code /} separates segments as well as {@code .}, so a path written the way the people
 *       who own the endpoint write it works as written;</li>
 *   <li>{@code [id="A-7"]} keeps the elements whose field matches, and {@code [id!="A-7"]} the
 *       ones whose does not — a filter always hands back a list, so a grid bound to one that
 *       matched a single row gets a one-row table rather than an object it would refuse;</li>
 *   <li>a name read off an array maps over its elements and flattens what comes back, the way
 *       JSONata does, so {@code data[id="A-7"]/referenceEntities} reaches the entities of the row
 *       that matched with no index in between.</li>
 * </ul>
 *
 * <p>Placeholders are long gone by the time this runs — see {@link #resolvePath}.
 */
function pathGet(data, path) {
    if (!path) return data;
    const text = String(path).replace(/^\$\.?/, '');
    // A name, or a bracket and whatever is inside it. Separators are simply what is left over.
    const token = /([^.\/\[\]]+)|\[([^\]]*)\]/g;
    let current = data;
    let match;
    while ((match = token.exec(text)) !== null) {
        if (current === undefined || current === null) return current;
        current = match[1] !== undefined ? nameStep(current, match[1]) : filterStep(current, match[2].trim());
    }
    return current;
}

/**
 * One name of a path. Reading a name off an array maps over it instead of coming back undefined,
 * which is what makes a filter worth having: the segment after it would otherwise need an index
 * to get past the list the filter produced.
 */
function nameStep(current, key) {
    if (!Array.isArray(current) || /^\d+$/.test(key)) return current[key];
    const out = [];
    let flattened = false;
    current.forEach(item => {
        const value = (item === undefined || item === null) ? undefined : item[key];
        if (value === undefined || value === null) return;
        if (Array.isArray(value)) { flattened = true; out.push(...value); }
        else out.push(value);
    });
    // One match that was not itself a list reads as the thing rather than as a list holding it —
    // the same collapse JSONata makes, and what a value path bound to a text box wants.
    return (out.length === 1 && !flattened) ? out[0] : out;
}

/** A bracket: an index, or a comparison that keeps the elements it matches. */
function filterStep(current, inside) {
    if (inside === '') return current;
    if (/^\d+$/.test(inside)) return current[Number(inside)];
    const parts = inside.match(/^(.+?)\s*(!=|=)\s*([\s\S]*)$/);
    if (!parts) return undefined;
    const key = parts[1].trim();
    const negate = parts[2] === '!=';
    // Quotes are optional: the value is compared as text either way, since that is the only
    // comparison that behaves the same for an id of 7 and an id of "A-7".
    const wanted = parts[3].trim().replace(/^(["'])([\s\S]*)\1$/, '$2');
    const list = Array.isArray(current) ? current : [current];
    return list.filter(item => {
        const value = (item === undefined || item === null) ? undefined : pathGet(item, key);
        const same = String(value === undefined || value === null ? '' : value) === wanted;
        return negate ? !same : same;
    });
}

/**
 * The rows a chart-bound action produces, and the fields that read them. An array is a row per
 * element, read by the name (or category) field and the value fields the action names. A JSON
 * object is charted as its own properties, because <code>{"OPEN": 12, "CLOSED": 3}</code> is
 * already a chart and making the page reshape it into a list of two-key rows first would be
 * ceremony for nothing — so it becomes those rows, under <code>key</code> and <code>value</code>.
 * But only where the action has not named its fields, since an action that has said what names a
 * mark and what sizes it is describing rows, and one row is what an object then is.
 *
 * <p>Nothing is rejected for being unchartable here. A row whose value is not a number is listed
 * beside the chart as uncharted — the same treatment a slice typed into the designer gets, and
 * better than failing the whole action over one row of forty.
 *
 * @return { rows, keyField, valueFields }
 */
function chartRowsAt(data, action, arrayPath, name) {
    const found = pathGet(data, arrayPath);
    if (found === undefined || found === null) {
        throw new Error(name + ': nothing found at path "' + (arrayPath || '') + '".');
    }
    const keyField = (action.keyField || '').trim();
    const valueFields = valueFieldsOf(action);
    if (Array.isArray(found)) return { rows: found, keyField: keyField, valueFields: valueFields };
    if (typeof found === 'object') {
        // One row rather than a map, wherever the action named the fields that make a row into a
        // mark. A path reaches here without meaning anything different from the array case: a
        // name read off a list hands back the single match itself rather than a list of one (see
        // #nameStep), so the same action that charts two rows correctly would otherwise chart a
        // one-row answer as that row's own field names — "status" and "count" as the wedges.
        if (keyField || valueFields.length) return { rows: [found], keyField: keyField, valueFields: valueFields };
        return { rows: Object.entries(found).map(([key, value]) => ({ key: key, value: value })),
                 keyField: 'key', valueFields: ['value'] };
    }
    throw new Error(name + ': expected an array or an object'
        + (arrayPath ? ' at "' + arrayPath + '"' : '') + ', got ' + typeof found + '.');
}

/** The value columns an action names: one, several comma-separated, or none. */
function valueFieldsOf(action) {
    return String((action && action.valueField) || '').split(',').map(f => f.trim()).filter(Boolean);
}

/**
 * The pies a chart draws out of its rows: one, or one per value column when several are named,
 * each titled with the column that sizes it.
 *
 * <p>A name field with no value field over rows of objects is a tally — [{status:"UP"},
 * {status:"DOWN"}, {status:"UP"}] charts as UP 2, DOWN 1 — since the row itself can never be the
 * number there.
 */
function pieSeriesOf(shape) {
    const { rows, keyField, valueFields } = shape;
    if (keyField && !valueFields.length && rows.some(isObjectRow)) {
        return [{ title: '', field: '', slices: tallySlices(rows, keyField) }];
    }
    if (valueFields.length <= 1) {
        return [{ title: '', field: valueFields[0] || '',
                  slices: rows.map((row, i) => sliceOf(row, keyField, valueFields[0] || '', i)) }];
    }
    return valueFields.map(field => ({ title: field, field: field,
        slices: rows.map((row, i) => sliceOf(row, keyField, field, i)) }));
}

function isObjectRow(row) {
    return row !== null && typeof row === 'object';
}

/**
 * One row as a slice. A blank name field falls back to the row's place in the list, and a blank
 * value field means the row itself is the number — between them, a bare array of numbers charts
 * as 1, 2, 3 with no fields named at all, which is the shape a JSONata step most easily produces.
 */
function sliceOf(row, keyField, valueField, index) {
    const object = isObjectRow(row);
    const key = keyField ? (object ? rowField(row, keyField) : undefined) : index + 1;
    const value = valueField ? (object ? rowField(row, valueField) : undefined) : row;
    const slice = { key: (key === undefined || key === null) ? '' : String(key), value: value, row: index };
    if (keyField && slice.key === '') slice.missing = 'row ' + (index + 1) + ' has no "' + keyField + '"';
    return slice;
}

/**
 * A row's field by name, falling back to a case-insensitive match: "STATUS" finds "status". Column
 * names are matched this way everywhere on the page — see #cellText.
 */
function rowField(row, field) {
    if (!isObjectRow(row)) return undefined;
    if (field in row) return row[field];
    const lower = String(field).toLowerCase();
    const match = Object.keys(row).find(k => k.toLowerCase() === lower);
    return match === undefined ? undefined : row[match];
}

/** One slice per distinct name, sized by how many rows carry it, in the order names first appear. */
function tallySlices(rows, keyField) {
    const counts = new Map();
    const missing = [];
    rows.forEach((row, i) => {
        const slice = sliceOf(row, keyField, '', i);
        if (slice.key === '') { missing.push(slice); return; }
        counts.set(slice.key, (counts.get(slice.key) || 0) + 1);
    });
    return Array.from(counts, ([key, count]) => ({ key: key, value: count })).concat(missing);
}

/**
 * A bar chart's model out of its rows: a category per distinct value of the category column, in
 * the order they first appear, and a series per value column — or one, "count", counting the rows
 * in each category when no value column is named. A named column is added up across the rows of a
 * category, so a response that already has one row per category charts that row's value as it is.
 *
 * <p>A value that is not a number, or is below zero, is left out of its category's sum and listed
 * as uncharted, the rule a pie follows. No category column puts every row in a category of its own
 * under its place in the list.
 */
function barModelOf(shape) {
    const { rows, keyField, valueFields } = shape;
    const categories = [];
    const at = new Map();
    const problems = [];
    const counting = !valueFields.length;
    const series = (counting ? ['count'] : valueFields).map(name => ({ name: name, values: [] }));

    rows.forEach((row, i) => {
        const raw = keyField ? rowField(row, keyField) : i + 1;
        if (keyField && (raw === undefined || raw === null || raw === '')) {
            problems.push('row ' + (i + 1) + ' has no "' + keyField + '"');
            return;
        }
        const category = typeof raw === 'object' ? JSON.stringify(raw) : String(raw);
        if (!at.has(category)) {
            at.set(category, categories.length);
            categories.push(category);
            series.forEach(s => s.values.push(counting ? 0 : NaN));
        }
        const k = at.get(category);
        if (counting) { series[0].values[k]++; return; }
        series.forEach(s => {
            // A plain number off a row of numbers, or the named column off a row of objects.
            const cell = isObjectRow(row) ? rowField(row, s.name) : row;
            const number = sliceNumber(cell);
            if (!Number.isFinite(number) || number < 0) {
                problems.push('"' + category + '" ' + s.name + ' = '
                    + (cell === undefined || cell === null || cell === '' ? '(blank)' : cellText(cell)));
                return;
            }
            s.values[k] = (Number.isFinite(s.values[k]) ? s.values[k] : 0) + number;
        });
    });
    return { categories: categories, series: series, problems: problems, counting: counting };
}

/**
 * Puts what an action bound on a chart. Held beside the chart rather than written into it, exactly
 * as a grid's rows are held beside the grid: the slices typed into the designer are the page, and
 * what a call returned is this run. Overwriting the first with the second would make previewing a
 * page an edit to it.
 */
function bindChart(control, model) {
    pieData[control.controlId] = model;
    delete chartPick[control.controlId];
    paintChart(control);
}

/**
 * Draws a chart from rows — whatever brought them: an action aimed at the chart, or the grid the
 * chart draws itself from. The rows are kept so the operator can re-read them by another slice name
 * field (see #pickChartKey), and a field the operator already picked is applied to them here, as
 * long as these rows still have that column.
 */
function drawChartFrom(control, shape, record, name, call) {
    chartSource[control.controlId] = { shape: shape, record: record, name: name, call: call };
    const picked = chartKeyPick[control.controlId];
    if (picked !== undefined && (picked === '' || chartColumns(shape.rows).includes(picked))) {
        shape = Object.assign({}, shape, { keyField: picked });
    }
    pieMeta[control.controlId] = record;
    if (control.type === 'bar') {
        bindChart(control, barModelOf(shape));
        return;
    }
    if (isSeries(control.type)) {
        bindChart(control, tsModelOf(shape, control));
        return;
    }
    const pies = pieSeriesOf(shape);
    if (control.type === 'piegrid') bindPieGrids(control, shape, pies, record, name, call);
    bindChart(control, pies);
}

/** The charts on this page that draw themselves from a grid. */
function chartsFromGrid(gridId) {
    return page.controls.filter(c => isChart(c.type) && c.sourceGridControlId && c.sourceGridControlId === gridId);
}

/** The grids on this page that copy their rows from a grid. */
function gridsFromGrid(gridId) {
    return page.controls.filter(c => c.type === 'grid' && c.sourceGridControlId && c.sourceGridControlId === gridId);
}

// The grids being filled from a grid right now, so a loop the save somehow let through stops after
// one lap instead of filling forever.
const feedingGrids = new Set();

/**
 * A grid has finished filling: every chart drawn from it is drawn again from its rows — all of
 * them, after the grid's display filter, rather than what the operator's filter boxes show, since
 * those change with every keystroke and a chart redrawn as someone types is not what was asked for.
 * The grid's own call record goes with them, so a chart over a failed call says it failed.
 */
function feedChartsFromGrid(gridId) {
    const charts = chartsFromGrid(gridId);
    const grids = gridsFromGrid(gridId);
    const state = gridState[gridId];
    if ((!charts.length && !grids.length) || !state) return;
    const grid = findControl(gridId);
    const record = gridMeta[gridId] ? Object.assign({}, gridMeta[gridId]) : callRecord(null, 'SUCCESS', '', null, 'from a grid');
    // A grid drawn from this one takes the same rows through its own columns, display filter, sort
    // and error check — and whatever is drawn from it is fed in turn, by its own setGridData.
    grids.forEach(target => {
        if (feedingGrids.has(target.controlId)) return;
        feedingGrids.add(target.controlId);
        try {
            gridMeta[target.controlId] = Object.assign({}, record);
            bindGrid(target, state.rows);
        } catch (e) {
            addError(controlTitle(target) + ': could not be filled from "' + controlTitle(grid) + '": ' + (e.message || String(e)));
        } finally {
            feedingGrids.delete(target.controlId);
        }
    });
    charts.forEach(chart => {
        const shape = {
            rows: state.rows,
            keyField: (chart.gridKeyField || '').trim(),
            valueFields: valueFieldsOf({ valueField: chart.gridValueField })
        };
        try {
            drawChartFrom(chart, shape, record, controlTitle(chart) + ' (from ' + controlTitle(grid) + ')', record.call);
        } catch (e) {
            addError(controlTitle(chart) + ': could not be drawn from "' + controlTitle(grid) + '": ' + (e.message || String(e)));
        }
    });
}

/** The columns a chart's rows carry, which are what its slice name field can be picked from. */
function chartColumns(rows) {
    return (rows || []).some(isObjectRow) ? columnsOf(rows.filter(isObjectRow)) : [];
}

/**
 * The dropdown on a running chart naming the column its slices (or a bar chart's categories) are
 * named by. Only there once the chart has rows of objects to re-read — typed-in slices have no
 * columns to choose between.
 */
function chartKeyPicker(c) {
    const source = chartSource[c.controlId];
    if (!source) return '';
    const columns = chartColumns(source.shape.rows);
    if (!columns.length) return '';
    const picked = chartKeyPick[c.controlId];
    const current = picked !== undefined && (picked === '' || columns.includes(picked)) ? picked : source.shape.keyField;
    // Matched as the chart matches it, regardless of case, so "STATUS" on the action selects "status".
    const selected = columns.find(col => col.toLowerCase() === String(current || '').toLowerCase()) || '';
    const series = isSeries(c.type);
    return '<span class="chart-key"><span>' + (series ? 'Lines By' : c.type === 'bar' ? 'Category' : 'Slice Name') + '</span>'
        + '<select onchange="pickChartKey(\'' + AC.attr(c.controlId) + '\', this.value)" title="The column each '
            + (series ? 'line' : c.type === 'bar' ? 'bar' : 'slice') + ' is named by">'
        + '<option value=""' + (selected ? '' : ' selected') + '>' + (series ? '— one line —' : '— row number —') + '</option>'
        + columns.map(col => '<option value="' + AC.attr(col) + '"' + (col === selected ? ' selected' : '') + '>'
            + AC.esc(col) + '</option>').join('')
        + '</select></span>';
}

/** The operator picked another slice name field: the same rows, drawn again by that column. */
function pickChartKey(controlId, field) {
    const control = findControl(controlId);
    const source = chartSource[controlId];
    if (!control || !source) return;
    chartKeyPick[controlId] = field;
    drawChartFrom(control, source.shape, source.record, source.name, source.call);
}

/** What a chart holds from the run, gone — and a pie with grids' grids with it. */
function clearChartData(control) {
    delete pieData[control.controlId];
    delete chartSource[control.controlId];
    delete chartPick[control.controlId];
    if (control.type !== 'piegrid') return;
    delete pieGridRows[control.controlId];
    const tabs = findControl(control.tabsControlId);
    if (tabs && fanTabs[tabs.controlId]) {
        clearFanTabs(tabs.controlId, pieGridMarker(control));
        paintTabs(tabs);
    }
}

/** Draws any kind of chart. */
function chartRun(control, zoom) {
    if (control.type === 'bar') return barRun(control, zoom);
    if (isSeries(control.type)) return tsRun(control, zoom);
    return pieRun(control, zoom);
}

/** Redraws one chart where it stands, without disturbing the rest of the page. */
function paintChart(control) {
    const host = document.getElementById('rc-' + control.controlId);
    // The big copy is drawn from the same run data, so it is redrawn whenever the small one is:
    // a call that lands while a chart is open fills what the operator is actually looking at.
    if (zoomedChart === control.controlId) renderChartZoom();
    // Laid out as a tab, its name and its outcome are on the strip rather than on the chart.
    if (tabsHolding(control.controlId)) paintChartTabStatus(control.controlId);
    // And a chart inside a group is part of what that group's badge is claiming.
    paintTabsetStatuses();
    if (!host) return;
    host.innerHTML = chartRun(control);
    if (control.type === 'piegrid' || sliceFilterTarget(control)) wireSliceClicks(host, control);
}

/**
 * Opens a chart over the page at the size it actually needs.
 *
 * <p>Nothing about the chart changes: it is the same control, drawn again from the same run data
 * at a bigger measurement, so the slice name dropdown, the wedges a pie with grids opens its
 * grids from and the failure it reports are all the ones on the page — there is no second chart
 * here to fall out of step with the first.
 */
function openChartZoom(controlId) {
    zoomedChart = controlId;
    renderChartZoom();
}

function closeChartZoom() {
    zoomedChart = null;
    renderChartZoom();
}

/** Draws whichever chart is open over the page, or takes the overlay away when none is. */
function renderChartZoom() {
    const host = document.getElementById('chartZoom');
    if (!host) return;
    const control = zoomedChart ? findControl(zoomedChart) : null;
    if (!control || !isChart(control.type) || mode !== 'run') {
        zoomedChart = null;
        host.innerHTML = '';
        host.style.display = 'none';
        return;
    }
    // Most of the window, less the dialog's own chrome — and never so small that the big copy is
    // no bigger than the one it was opened from.
    const height = Math.max(Math.round(window.innerHeight * 0.66), 320);
    host.style.display = '';
    host.innerHTML = '<div class="chart-zoom-box">'
        + '<div class="chart-zoom-head"><span class="chart-zoom-title">' + AC.esc(controlTitle(control)) + '</span>'
            + (control.type === 'piegrid'
                ? '<span class="hint" style="margin:0">Click a slice to open its grid — the chart closes to show it.</span>'
                : '')
            + '<button type="button" class="tool-btn" data-zoom-close>Close</button></div>'
        + '<div class="chart-zoom-body">'
            + chartRun(control, { height: height })
        + '</div></div>';
    host.querySelectorAll('[data-zoom-close]').forEach(el => el.addEventListener('click', closeChartZoom));
    if (control.type === 'piegrid') wireSliceClicks(host, control);
}

// Clicking the dark outside it closes it, as it does on every other dialog on this screen; a
// click inside the box is a click on the chart and must not.
document.getElementById('chartZoom').addEventListener('click', e => {
    if (e.target === e.currentTarget) closeChartZoom();
});
document.addEventListener('keydown', e => { if (e.key === 'Escape' && zoomedChart) closeChartZoom(); });
// The overlay is measured against the window, so a window that changes size is measured again.
window.addEventListener('resize', () => { if (zoomedChart) renderChartZoom(); });

// ── Pie + grids ───────────────────────────────────────────────────────────
// A pie chart that also puts the rows it was drawn from into a grid per pie, as tabs of a tab set
// the designer picked. Clicking a slice opens that pie's grid filtered to the slice's rows.

/** How a pie with grids marks the tabs it added, so it clears its own and nobody else's. */
function pieGridMarker(control) {
    return 'piegrid:' + control.controlId;
}

function pieGridId(control, series) {
    return 'pg-' + control.controlId + '-' + series;
}

/**
 * A grid per pie in the chart's tab set, each holding every row the chart was drawn from. The
 * chart's previous grids go first, so a second run over a different set of value columns does not
 * leave the first run's tabs standing.
 */
function bindPieGrids(control, shape, pies, record, name, call) {
    const tabs = findControl(control.tabsControlId);
    if (!tabs || tabs.type !== 'tabs') {
        addError(name + ': "' + controlTitle(control) + '" has no tab set to put its grids in — pick one on the chart.', call);
        return;
    }
    clearFanTabs(tabs.controlId, pieGridMarker(control));
    pieGridRows[control.controlId] = { rows: shape.rows, keyField: shape.keyField };
    const added = pies.map((pie, s) => {
        const gridId = pieGridId(control, s);
        const title = pies.length > 1 ? controlTitle(control) + ' · ' + pie.title : controlTitle(control);
        gridMeta[gridId] = Object.assign({}, record);
        setGridData(gridId, shape.rows, null, title);
        return { gridId: gridId, title: title, actionId: pieGridMarker(control) };
    });
    fanTabs[tabs.controlId] = (fanTabs[tabs.controlId] || []).concat(added);
    paintTabs(tabs);
}

/**
 * The grid a pie's slice click narrows: the grid the pie is drawn from.
 *
 * <p>A pie drawn from a grid is a count of that grid's own rows, wedge by wedge — so a wedge is
 * a question about rows that are already on the page, under a heading the operator is already
 * reading. "Forty of them are REJECTED" and "which forty" are one click apart, and before this
 * the answer was to find the status column in the filter row and type the wedge's name into it.
 *
 * <p>Only a plain pie, and only one drawn from a grid. A pie with grids has grids of its own to
 * open and answers a click by opening them — see {@link #pickSlice} — and a pie filled straight
 * by an action has no grid on the page holding the rows it was counted from.
 */
function sliceFilterTarget(c) {
    if (!c || c.type !== 'pie' || !c.sourceGridControlId) return null;
    const grid = findControl(c.sourceGridControlId);
    return grid && grid.type === 'grid' ? grid : null;
}

/**
 * The rows a chart's slices were drawn from and the field naming a slice, wherever they are held:
 * on a pie with grids, beside the grids it filled; on any other chart, in the rows it was last
 * drawn from. The field is the one actually in force, so a slice picked after the operator has
 * re-read the chart by another column tests that column.
 */
function chartRowsHeld(controlId) {
    const held = pieGridRows[controlId];
    if (held) return held;
    const source = chartSource[controlId];
    if (!source || !source.shape) return null;
    const shape = source.shape;
    const picked = chartKeyPick[controlId];
    const keyField = picked !== undefined && (picked === '' || chartColumns(shape.rows).includes(picked))
        ? picked : shape.keyField;
    return { rows: shape.rows, keyField: keyField };
}

/**
 * What a grid is pinned to when one of this chart's slices is clicked: the rows whose name field
 * holds the slice's name, or — on a chart with no name field, where each row is its own slice —
 * that one row.
 *
 * <p>Exact rather than the filter row's "contains": the slice OPEN is not also the rows that say
 * REOPENED, and a wedge that says 40 has to show 40 rows or it has told the operator something
 * untrue.
 */
function slicePin(controlId, held, slice) {
    const keyField = held.keyField;
    if (!keyField) {
        const row = held.rows[slice.row];
        return { owner: controlId, label: 'row ' + (slice.row + 1), test: r => r === row };
    }
    return { owner: controlId, label: keyField + ' = ' + slice.key,
             test: r => {
                 const v = rowField(r, keyField);
                 return (v === undefined || v === null ? '' : String(v)) === slice.key;
             } };
}

/** Makes every wedge and legend row of a clickable pie narrow what it was counted out of. */
function wireSliceClicks(host, control) {
    host.querySelectorAll('[data-slice]').forEach(el => {
        const pick = () => pickSlice(control.controlId, +el.dataset.series, +el.dataset.slice);
        el.addEventListener('click', pick);
        el.addEventListener('keydown', e => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            pick();
        });
    });
}

/**
 * A slice clicked: the grid behind it shows only the rows that slice stands for. Clicking the
 * slice already picked takes the filter off again.
 *
 * <p>Which grid depends on what kind of pie it is, and the two are the same gesture answered the
 * same way. A pie with grids has a grid of its own per pie, in a tab set: that grid comes to the
 * front of the set, narrowed, and the other pies' grids go back to every row, since only one
 * slice across the chart is picked at a time. A plain pie drawn from a grid narrows that grid
 * where it already sits on the page — the rows it was counted out of, under a heading the
 * operator is already reading.
 */
function pickSlice(controlId, series, index) {
    const control = findControl(controlId);
    if (!control) return;
    const held = chartRowsHeld(controlId);
    if (!held) return;
    const pie = drawnPies(control)[series];
    const slice = pie && pie.slices[index];
    if (!slice) return;
    const previous = chartPick[controlId];
    const again = previous && previous.series === series && previous.key === slice.key;
    const source = sliceFilterTarget(control);

    if (source) {
        const state = gridState[source.controlId];
        if (state) {
            state.pinned = again ? null : slicePin(controlId, held, slice);
            invalidateView(state);
        }
    } else {
        drawnPies(control).forEach((p, s) => {
            const state = gridState[pieGridId(control, s)];
            if (!state) return;
            state.pinned = !again && s === series ? slicePin(controlId, held, slice) : null;
            invalidateView(state);
        });
    }
    if (again) delete chartPick[controlId];
    else chartPick[controlId] = { series: series, key: slice.key };

    // Picking a slice is asking to see its rows, and the rows are on the page behind the big
    // copy of the chart — so the big copy gets out of the way. Clicking the picked slice again is
    // taking the filter off rather than asking to see anything, and leaves it open.
    if (zoomedChart === controlId && !again) closeChartZoom();

    if (source) {
        paintGrid(source.controlId);
        // Brought into view only on a pick. Taking the filter off is not a request to look at
        // anything, and scrolling then would move the page under a pointer that had just
        // clicked to stay where it was.
        const host = document.querySelector('[data-grid="' + CSS.escape(source.controlId) + '"]');
        if (host && !again) host.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        paintChart(control);
        return;
    }

    const tabs = findControl(control.tabsControlId);
    if (tabs) {
        activeTab[tabs.controlId] = pieGridId(control, series);
        collapsedTabs[tabs.controlId] = false;
        paintTabs(tabs);
        applyRunPlacement();
        const host = document.getElementById('rc-' + tabs.controlId);
        if (host && !again) host.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    paintChart(control);
}

/** Fills a text box or text area from one attribute of a response. */
function bindValue(control, value, valuePath, name, call) {
    if (value === undefined || value === null) {
        addError(name + ': nothing found at path "' + (valuePath || '') + '".', call);
        return;
    }
    const text = control.type === 'textarea'
        ? formatText(control, value)
        : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value);
    values[control.fieldName] = text;
    const input = document.querySelector('#rc-' + CSS.escape(control.controlId) + ' [data-field]');
    if (input) input.value = text;
}

/**
 * A value as a text area set to pretty-print shows it. An object is already JSON, so it is
 * written out indented whichever format was asked for; text is parsed as the format and laid out
 * again, and text that does not parse goes in exactly as it came rather than not at all.
 */
function formatText(control, value) {
    if (value === undefined || value === null) return '';
    if (typeof value === 'object') return JSON.stringify(value, null, 2);
    const text = String(value);
    const format = control.textFormat || 'NONE';
    if (!text.trim() || format === 'NONE') return text;
    if (format === 'JSON') {
        try { return JSON.stringify(JSON.parse(text), null, 2); } catch (e) { return text; }
    }
    if (format === 'XML') return prettyXml(text);
    return text;
}

/** XML text indented two spaces a level, or the text untouched when it is not well-formed XML. */
function prettyXml(text) {
    const doc = new DOMParser().parseFromString(text.trim(), 'application/xml');
    if (doc.getElementsByTagName('parsererror').length) return text;
    const escText = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const escAttr = s => escText(s).replace(/"/g, '&quot;');
    const lines = [];
    const declaration = /^\s*(<\?xml[^?]*\?>)/.exec(text);
    if (declaration) lines.push(declaration[1]);

    const walk = (node, depth) => {
        const pad = '  '.repeat(depth);
        switch (node.nodeType) {
            case Node.ELEMENT_NODE: {
                const open = '<' + node.nodeName + [...node.attributes]
                    .map(a => ' ' + a.name + '="' + escAttr(a.value) + '"').join('');
                // Whitespace between tags is layout, which is being redone here, so it is dropped.
                const kids = [...node.childNodes].filter(n => !(n.nodeType === Node.TEXT_NODE && !n.nodeValue.trim()));
                if (!kids.length) { lines.push(pad + open + '/>'); return; }
                // A leaf keeps its text on the same line as its tags: <name>value</name>.
                if (kids.length === 1 && kids[0].nodeType === Node.TEXT_NODE) {
                    lines.push(pad + open + '>' + escText(kids[0].nodeValue.trim()) + '</' + node.nodeName + '>');
                    return;
                }
                lines.push(pad + open + '>');
                kids.forEach(k => walk(k, depth + 1));
                lines.push(pad + '</' + node.nodeName + '>');
                return;
            }
            case Node.TEXT_NODE:
                lines.push(pad + escText(node.nodeValue.trim()));
                return;
            case Node.CDATA_SECTION_NODE:
                lines.push(pad + '<![CDATA[' + node.nodeValue + ']]>');
                return;
            case Node.COMMENT_NODE:
                lines.push(pad + '<!--' + node.nodeValue + '-->');
                return;
            case Node.PROCESSING_INSTRUCTION_NODE:
                lines.push(pad + '<?' + node.target + ' ' + node.data + '?>');
                return;
        }
    };
    [...doc.childNodes].forEach(n => walk(n, 0));
    return lines.join('\n');
}

/**
 * Points a link at what an action bound. An address that cannot be used is reported rather than
 * dropped: a link that quietly stopped being one, on a page whose call succeeded, is a thing
 * nobody can account for — and the value is worth reading, since a response carrying an object
 * where a URL was expected is usually a value path that named the wrong thing.
 */
function bindLink(control, value, valuePath, name, call) {
    // A link pointed at another page is not a place for an address to land: it has a
    // destination already, chosen rather than typed, and quietly replacing it would send the
    // operator somewhere the page plainly says it goes. Said out loud rather than ignored,
    // since an action aimed here is wiring somebody meant to work.
    if (control.linkPageName) {
        addError(name + ': "' + controlTitle(control) + '" opens the page "' + control.linkPageName
            + '", so there is nowhere for a bound address to go. Point the link at a web address '
            + 'instead, or aim this action elsewhere.', call);
        return;
    }
    if (value === undefined || value === null) {
        addError(name + ': nothing found at path "' + (valuePath || '') + '".', call);
        return;
    }
    const url = typeof value === 'object' ? JSON.stringify(value) : String(value).trim();
    linkUrls[control.controlId] = url;
    paintLink(control);
    if (url && !safeUrl(url)) {
        addError(name + ': "' + url + '" is not an http or https address, so "' + controlTitle(control)
            + '" was left without one.', call);
    }
}

// ── Grids ────────────────────────────────────────────────────────────────
// Every grid on a running page — the ones placed in the layout and the ones an action stacks —
// is the same thing: rows, the columns to show them under, and whatever sort and column filters
// the operator has applied. The rows are kept as they arrived so filtering and sorting stay
// views over them rather than edits to them, and so an export can follow what is on screen.

// ── Checking the rows ────────────────────────────────────────────────────
// A grid already says whether the call behind it worked. Whether what came back is *right* is a
// different question and only the rows can answer it: fifteen rows back, three of which
// reconciled to nothing, is a successful call and a failed run, and the only way to see that was
// to read the rows. A grid may carry an expression — STATUS != SUCCESS || RECORDCOUNT = 0 —
// that every row is put through as the rows arrive. Rows it calls true are the errors: drawn in
// red, and counted into the grid's own name.
//
// A bare word is a column of the row where the row has one of that name and the literal text it
// is otherwise, which is what lets the expression be written the way anyone would say it with
// neither side quoted. Columns are matched case-insensitively, so STATUS finds "status": the
// expression is written by someone reading the grid, not the JSON behind it.
//
// Mirrors AppPageRowCheck.java, which reads the same grammar when the page is saved so an
// expression that cannot be parsed is refused where the designer can fix it rather than
// discovered by an operator wondering why a grid of failures came out entirely green.

/** Longest first, so != is read as one operator rather than as ! then =. */
const ROW_CHECK_OPERATORS = ['==', '!=', '<>', '>=', '<=', '!~', '=', '>', '<', '~'];
/** The characters an operator is built out of, and therefore what ends a bare word. */
const ROW_CHECK_OP_CHARS = '=!<>~&|';

/** Reads an expression into tokens: words, quoted text, operators and brackets. */
function scanRowCheck(text) {
    const out = [];
    let i = 0;
    while (i < text.length) {
        const ch = text[i];
        if (/\s/.test(ch)) { i++; continue; }
        if (ch === '(' || ch === ')') { out.push({ kind: ch, text: ch }); i++; continue; }
        if (ch === '"' || ch === "'") {
            const end = text.indexOf(ch, i + 1);
            if (end < 0) throw new Error('a quote is never closed: ' + text.slice(i));
            out.push({ kind: 'text', text: text.slice(i + 1, end) });
            i = end + 1;
            continue;
        }
        if (ROW_CHECK_OP_CHARS.includes(ch)) {
            const two = text.slice(i, i + 2);
            if (two === '&&' || two === '||' || ROW_CHECK_OPERATORS.includes(two)) {
                out.push({ kind: 'op', text: two });
                i += 2;
                continue;
            }
            // "!" on its own is the negation rather than a comparison, so it is let through here
            // even though it is not one of them — "!=" was already taken above.
            if (ROW_CHECK_OPERATORS.includes(ch) || ch === '!') { out.push({ kind: 'op', text: ch }); i++; continue; }
            throw new Error("'" + ch + "' is not a test this understands");
        }
        let end = i;
        while (end < text.length && !/\s/.test(text[end])
               && !'()\'"'.includes(text[end]) && !ROW_CHECK_OP_CHARS.includes(text[end])) end++;
        out.push({ kind: 'word', text: text.slice(i, end) });
        i = end;
    }
    return out;
}

/**
 * The expression as a tree, or what is wrong with it. Compiled once when a grid is filled rather
 * than per row: a 27,000-row result would otherwise be 27,000 trips through the scanner.
 */
function parseRowCheck(text) {
    try {
        const s = { tokens: scanRowCheck(text), at: 0 };
        const node = rcOr(s);
        if (s.at < s.tokens.length)
            throw new Error("nothing joins on to '" + s.tokens[s.at].text + "'");
        return { ok: true, node: node };
    } catch (e) {
        return { ok: false, error: e.message };
    }
}

function rcPeek(s)          { return s.at < s.tokens.length ? s.tokens[s.at] : null; }
function rcIsOp(s, symbol)  { const t = rcPeek(s); return !!t && t.kind === 'op' && t.text === symbol; }
function rcIsWord(s, word)  { const t = rcPeek(s); return !!t && t.kind === 'word' && t.text.toLowerCase() === word; }
function rcIsJoin(s, symbol, word) { return rcIsOp(s, symbol) || rcIsWord(s, word); }

function rcOr(s) {
    let node = rcAnd(s);
    while (rcIsJoin(s, '||', 'or')) { s.at++; node = { n: 'or', a: node, b: rcAnd(s) }; }
    return node;
}

function rcAnd(s) {
    let node = rcNot(s);
    while (rcIsJoin(s, '&&', 'and')) { s.at++; node = { n: 'and', a: node, b: rcNot(s) }; }
    return node;
}

function rcNot(s) {
    if (rcIsOp(s, '!') || rcIsWord(s, 'not')) { s.at++; return { n: 'not', a: rcNot(s) }; }
    return rcComparison(s);
}

function rcComparison(s) {
    const left = rcTerm(s);
    const next = rcPeek(s);
    if (!next || next.kind !== 'op' || !ROW_CHECK_OPERATORS.includes(next.text)) return left;
    s.at++;
    return { n: 'cmp', op: next.text, left: left, right: rcTerm(s) };
}

function rcTerm(s) {
    const token = rcPeek(s);
    if (!token) throw new Error('the expression stops before it says anything');
    if (token.kind === '(') {
        s.at++;
        const inner = rcOr(s);
        if (!rcPeek(s) || rcPeek(s).kind !== ')') throw new Error('a bracket is never closed');
        s.at++;
        return inner;
    }
    if (token.kind === 'word' || token.kind === 'text') {
        // A joining word is not a value: "STATUS = or FAILED" is a missing right-hand side
        // rather than a comparison against the word "or".
        if (token.kind === 'word' && ['or', 'and', 'not'].includes(token.text.toLowerCase()))
            throw new Error("'" + token.text + "' joins two tests, so it cannot be one side of one");
        s.at++;
        return { n: 'term', quoted: token.kind === 'text', text: token.text };
    }
    throw new Error("expected a column or a value, found '" + token.text + "'");
}

/**
 * One cell of a row by column name, matched exactly and then case-insensitively, or null where
 * the row has no such column — which is what makes the name a literal instead.
 */
function rowCell(row, name) {
    if (!row || typeof row !== 'object') return null;
    if (Object.prototype.hasOwnProperty.call(row, name)) return cellText(row, name);
    const key = Object.keys(row).find(k => k.toLowerCase() === name.toLowerCase());
    return key === undefined ? null : cellText(row, key);
}

/** What one side of a comparison is worth for this row: a cell, or the text itself. */
function rowCheckValue(node, row) {
    if (node.quoted) return node.text;
    const cell = rowCell(row, node.text);
    return cell === null ? node.text : cell;
}

/**
 * One comparison. Numbers compare as numbers and everything else as case-insensitive text,
 * which is the rule the grid already sorts and filters a column by — see {@link #compareCells}.
 */
function compareRowCheck(op, left, right) {
    const numeric = left !== '' && right !== '' && !isNaN(Number(left)) && !isNaN(Number(right));
    const same = numeric ? Number(left) === Number(right) : left.toLowerCase() === right.toLowerCase();
    switch (op) {
        case '=': case '==':  return same;
        case '!=': case '<>': return !same;
        case '~':  return left.toLowerCase().includes(right.toLowerCase());
        case '!~': return !left.toLowerCase().includes(right.toLowerCase());
        default: {
            const order = numeric ? Number(left) - Number(right) : compareCells(left, right);
            return op === '>' ? order > 0 : op === '>=' ? order >= 0
                 : op === '<' ? order < 0 : order <= 0;
        }
    }
}

/** A value standing on its own as a test — an empty cell, a "false" or a zero is not an error. */
function rowCheckTruthy(text) {
    const value = text.trim().toLowerCase();
    return value !== '' && value !== 'false' && value !== '0' && value !== 'null';
}

function evalRowCheck(node, row) {
    switch (node.n) {
        case 'or':  return evalRowCheck(node.a, row) || evalRowCheck(node.b, row);
        case 'and': return evalRowCheck(node.a, row) && evalRowCheck(node.b, row);
        case 'not': return !evalRowCheck(node.a, row);
        case 'cmp': return compareRowCheck(node.op, rowCheckValue(node.left, row), rowCheckValue(node.right, row));
        default:    return rowCheckTruthy(rowCheckValue(node, row));
    }
}

/**
 * The expression a grid checks its rows with, or nothing — stacked grids have no control. A tab
 * a fan-out added has none either, and checks with the one written on the action that added it.
 */
function rowCheckOf(gridId) {
    if (fanRowChecks[gridId]) return fanRowChecks[gridId];
    const control = findControl(gridId);
    return control && control.type === 'grid' ? (control.rowErrorExpression || '').trim() : '';
}

/** The expression a grid keeps its rows by, found the same way as {@link #rowCheckOf}. */
function displayFilterOf(gridId) {
    if (fanDisplayFilters[gridId]) return fanDisplayFilters[gridId];
    const control = findControl(gridId);
    return control && control.type === 'grid' ? (control.displayFilterExpression || '').trim() : '';
}

/**
 * The rows a grid's display filter keeps — those it comes out true for — and how many it dropped.
 * Applied once, as the grid is filled, so everything downstream of the rows — the error check,
 * the counts, the status, the exports — is about what the grid shows. A filter that cannot be read
 * or throws keeps every row and says why, rather than silently emptying the grid.
 */
function applyDisplayFilter(rows, expression) {
    if (!expression) return { rows: rows, hidden: 0, error: '' };
    const parsed = parseRowCheck(expression);
    if (!parsed.ok) return { rows: rows, hidden: 0, error: parsed.error };
    try {
        const kept = rows.filter(row => evalRowCheck(parsed.node, row));
        return { rows: kept, hidden: rows.length - kept.length, error: '' };
    } catch (e) {
        return { rows: rows, hidden: 0, error: e.message || String(e) };
    }
}

/**
 * Runs the grid's check over every row it has just been given, once, and records which rows
 * failed it. Identity rather than index: the rows are filtered and sorted into a different order
 * the moment anybody touches the grid, and the row object is the only thing that survives that.
 */
function applyRowCheck(state, expression) {
    state.errorRows = null;
    state.errorCount = 0;
    state.checkError = '';
    // Left on, it would empty the grid: a run that fixed everything the last one flagged would
    // look like a run that returned nothing. The tick box goes when there is nothing to tick.
    state.errorsOnly = false;
    if (!expression) return;
    const parsed = parseRowCheck(expression);
    if (!parsed.ok) { state.checkError = parsed.error; return; }
    const failed = new Set();
    for (const row of state.rows) {
        let bad;
        // A check that throws on a row is a broken check rather than a bad row, so the grid says
        // so once instead of marking every row after it — the rows are the one thing here that
        // is not in question.
        try { bad = evalRowCheck(parsed.node, row); }
        catch (e) { state.checkError = e.message; state.errorRows = null; state.errorCount = 0; return; }
        if (bad) failed.add(row);
    }
    state.errorRows = failed;
    state.errorCount = failed.size;
}

/**
 * `forcedColumns` overrides the grid's own configured columns — used for a key/value result.
 *
 * <p>`append` adds the rows to the ones the grid already holds instead of replacing them. It
 * falls back to replacing on a grid that is holding nothing yet — the first run of an appending
 * action, and the one after the grid was cleared — since there is nothing to add to.
 */
function bindGrid(control, rows, forcedColumns, append) {
    const columns = forcedColumns || control.columns;
    if (append && gridState[control.controlId]) addGridData(control.controlId, rows, columns);
    else setGridData(control.controlId, rows, columns, controlTitle(control));
}

/**
 * The order a grid starts in, as its designer set it: the column to sort by and which way round,
 * or nothing at all for a grid that shows its rows in the order they arrived.
 *
 * <p>Read off the control the same way the row check is, and ignored when the column named is not
 * one this result actually carries — a grid whose columns follow the data can be filled by two
 * different calls, and sorting by a field that is not there would order every row by the empty
 * string and put a heading arrow over a column nobody can see.
 */
function defaultSortOf(gridId, columns) {
    const control = findControl(gridId);
    if (!control || control.type !== 'grid') return null;
    const wanted = (control.sortColumn || '').trim().toLowerCase();
    const column = wanted && columns.find(c => String(c).toLowerCase() === wanted);
    if (!column) return null;
    return { column: column, direction: control.sortDirection === 'DESC' ? -1 : 1 };
}

/**
 * A row cap as a number the grid can use: a whole count of rows, or 0 for "every one of them".
 * Anything unreadable, negative or fractional reads as no cap rather than as an error — the
 * value arrives from a typed box at run time and from a saved page that may predate the setting,
 * and a grid that refused to draw because a cap was mistyped would be worse than one that
 * ignored it.
 */
function normalizeTopRows(value) {
    const n = Math.floor(Number(value));
    return isFinite(n) && n > 0 ? n : 0;
}

/**
 * How many rows the grid's designer means it to show, at most, once its rows are in order —
 * a "top 10 slowest" panel rather than a grid the operator has to cut down by hand every run.
 *
 * <p>Only a starting cap, exactly as {@link #defaultSortOf} is only a starting order: the box in
 * the grid's toolbar carries this number and the operator can raise it, lower it or clear it.
 */
function defaultTopOf(gridId) {
    const control = findControl(gridId);
    if (!control || control.type !== 'grid') return 0;
    return normalizeTopRows(control.topRows);
}

/** The columns a grid's designer asked to see first, or none for one that named none. */
function leadColumnsOf(gridId) {
    const control = findControl(gridId);
    return control && control.type === 'grid' ? (control.leadColumns || []) : [];
}

/** The columns a grid's designer asked it not to draw, or none — see {@link #showableColumns}. */
function hiddenColumnsOf(gridId) {
    const control = findControl(gridId);
    return control && control.type === 'grid' ? (control.hiddenColumns || []) : [];
}

/**
 * The columns a grid draws: what the rows carry, in the grid's own order, less the ones it was
 * told to hide.
 *
 * <p>The hiding happens here, on the list of columns, rather than on the rows or in the table —
 * which is what makes it one setting rather than four. The filter row, the sort, both exports,
 * "View as HTML" and Analyze are all written against this list, so a column that is not in it is
 * gone from all of them at once, and none of them has to know the setting exists.
 *
 * <p>The rows keep the value either way. A hidden column is still there to be read by the error
 * check, the display filter, a clickable column's assignments, a fan-out running over these rows,
 * and anything resolving <code>${column}</code> — it is off the screen, not out of the data.
 */
function showableColumns(gridId, columns) {
    const hidden = hiddenColumnsOf(gridId)
        .map(name => String(name).trim().toLowerCase()).filter(Boolean);
    const ordered = orderColumns(columns, leadColumnsOf(gridId));
    if (!hidden.length) return ordered;
    return ordered.filter(column => !hidden.includes(String(column).toLowerCase()));
}

/**
 * A grid's columns in the order its designer asked for: the ones named under First Columns, in
 * that order, and then every other column exactly as it arrived.
 *
 * <p>For the answer that carries thirty fields because that is what the endpoint returns, of
 * which two are the ones anybody actually reads. Naming those two under Columns would work and
 * would throw the other twenty-eight away — which is the wrong trade for a screen somebody is
 * looking at to find out what happened. Here nothing is dropped; the ones that matter are simply
 * at the near end of the scroll.
 *
 * <p>Matched without regard to case, the way every other place a column is named by hand is, and
 * a name the rows do not carry is passed over rather than adding an empty column — a grid can be
 * filled by two different calls, and a heading over nothing would be a column that is not there.
 */
function orderColumns(columns, lead) {
    if (!lead || !lead.length) return columns;
    const taken = new Set();
    const first = [];
    lead.forEach(wanted => {
        const name = String(wanted).trim().toLowerCase();
        if (!name) return;
        const found = columns.find(column => !taken.has(column) && String(column).toLowerCase() === name);
        if (found === undefined) return;
        taken.add(found);
        first.push(found);
    });
    return first.concat(columns.filter(column => !taken.has(column)));
}

/**
 * Works out the columns a grid actually draws from the ones it has to offer and the operator's
 * own pick of them — see {@link #gridColumnsBox}.
 *
 * <p>Two lists rather than one because they answer different questions. <code>allColumns</code> is
 * everything this answer carries that the designer did not hide, in the order it is offered in;
 * <code>columns</code> is what is on screen, and is what the table, the filter row, the sort, both
 * exports, "View as HTML" and Analyze have always read. So turning a column off takes it out of
 * all of them at once and none of them has to know the chooser exists — exactly the bargain
 * {@link #showableColumns} strikes for the designer's own hidden columns.
 *
 * <p>With a previous order handed in — a refill of a grid the operator had already arranged — the
 * new answer's columns are put back into that order, the ones it named first and anything new
 * after them, which is {@link #orderColumns} doing for the operator what it does for the
 * designer's First Columns.
 *
 * <p>Turning every column off would leave a table of nothing, which is never what was meant, so
 * the pick is dropped rather than obeyed.
 */
function applyColumnPick(state, previousOrder) {
    if (previousOrder && previousOrder.length) {
        state.allColumns = orderColumns(state.allColumns, previousOrder);
    }
    let drawn = state.allColumns.filter(column => !state.colsOff.has(String(column).toLowerCase()));
    if (!drawn.length) {
        state.colsOff.clear();
        drawn = state.allColumns.slice();
    }
    state.columns = drawn;
}

/** Whether a grid opens with its text wrapped, as its designer set it. */
function wrapTextOf(gridId) {
    const control = findControl(gridId);
    return !!(control && control.type === 'grid' && control.wrapText);
}

function setGridData(gridId, rows, fixedColumns, title) {
    // Whether the text is wrapped is the operator's reading of the grid rather than a fact about
    // the call, so a second run leaves it where they put it — the same bargain the row cap and
    // the column filters would strike if a refill were not the moment those stop being true.
    const wrapped = gridState[gridId] ? gridState[gridId].wrap : null;
    // And for the same reason, which columns the operator chose to look at and the order they put
    // them in: both are about how this grid is being read, not about the answer in it. Carried
    // across as names and matched against whatever the new answer carries — see #applyColumnPick.
    // A column the new answer does not have is simply not there to draw; one it has that the
    // operator had turned off stays off, since "do not show me that" is about the column rather
    // than about the call that happened to be carrying it.
    const previous = gridState[gridId];
    // The chooser closes on a refill, so the listener waiting for the click that would have shut
    // it goes with the state it belonged to — see #wireColumnChooser.
    if (previous && previous.colsCloser) document.removeEventListener('mousedown', previous.colsCloser, true);
    // Columns are read off the response before it is filtered, so a filter that keeps nothing
    // still leaves the grid its headings. And put in the grid's own order as they are read, so
    // everything downstream — the table, the filter row, both exports, Analyze — reads one list
    // rather than each having to know what goes first.
    const columns = showableColumns(gridId,
        (fixedColumns && fixedColumns.length) ? fixedColumns : columnsOf(rows));
    const shown = applyDisplayFilter(rows || [], displayFilterOf(gridId));
    rows = shown.rows;
    const start = defaultSortOf(gridId, columns);
    gridState[gridId] = {
        rows: rows,
        columns: columns,
        filters: {},
        sort: start ? start.column : null,
        direction: start ? start.direction : 1,
        topRows: defaultTopOf(gridId),   // 0 for every row; see normalizeTopRows
        cappedOut: 0,       // how many matching rows that cap is holding back, if any
        title: title,
        shown: GRID_PAGE,   // how many of the matching rows are actually in the DOM
        view: null,         // the filtered/sorted rows, cached until something invalidates them
        errorRows: null,    // the rows this grid's own check called wrong, by identity
        errorCount: 0,
        errorsOnly: false,  // whether the operator has asked to see only those — see #gridErrorsBox
        checkError: '',     // what was wrong with the check itself, if anything
        filteredOut: shown.hidden,   // rows of the response the display filter kept off the grid
        filterError: shown.error,    // what was wrong with the display filter, if anything
        // How the rows are drawn: one line a cell with the wide columns off the right-hand edge,
        // or every column on screen with the text wrapped. The designer sets which it opens as
        // and the operator moves it from the toolbar — see #gridWrapBox.
        wrap: wrapped === null ? wrapTextOf(gridId) : wrapped,
        // Which columns this grid has to offer, in the order they are offered in — the operator's
        // order once they have moved any. `columns` above is what is drawn: these less the ones
        // they turned off. See #applyColumnPick.
        allColumns: columns,
        // The order the designer's settings put them in, kept so Reset has something to go back
        // to once the operator has moved them about.
        baseColumns: columns.slice(),
        // Names of the columns turned off, lower-cased the way every hand-named column is matched.
        colsOff: previous ? previous.colsOff : new Set(),
        colsOpen: false     // whether the column chooser is folded out — see #gridColumnsBox
    };
    applyColumnPick(gridState[gridId], previous ? previous.allColumns : null);
    // Every row is judged as the grid fills, not as it is drawn: only a window of a large result
    // is ever in the document, and "5 errors of 27,000" has to be true of all of them.
    applyRowCheck(gridState[gridId], rowCheckOf(gridId));
    paintGrid(gridId);
    // The grid holds every row it is going to now, so whatever charts itself from it can be drawn.
    feedChartsFromGrid(gridId);
}

/**
 * Adds a call's rows to the ones a grid already holds — see {@link #bindGrid} — so several runs
 * read as one table rather than as whichever was last.
 *
 * <p>What the operator did to the grid survives: its sort, its filters, its row cap and the
 * column it is ordered by are about the table rather than about the call that filled it, and an
 * action adding to it has not changed any of them. Only the cached view goes, since the rows it
 * was computed from are no longer all of them.
 *
 * <p>Columns are the union of what the grid has and what arrived, in the order they first
 * appeared: a later answer carrying a field the first did not adds a column at the end rather
 * than being dropped into a grid with nowhere to put it. A grid laid out with its own fixed
 * columns is unaffected — every answer is bound under those same columns.
 */
function addGridData(gridId, rows, fixedColumns) {
    const state = gridState[gridId];
    // The display filter is the grid's own and applies to every row that ever reaches it, so
    // these are put through it exactly as the first call's were — and what it dropped is added
    // to the running count rather than replacing it.
    const shown = applyDisplayFilter(rows || [], displayFilterOf(gridId));
    const columns = (fixedColumns && fixedColumns.length) ? fixedColumns : columnsOf(shown.rows);
    // Onto what the grid has to offer rather than onto what it is drawing: a column this call
    // introduced is a column the chooser can now offer, and one the operator has already turned
    // off does not come back on because a second call carried it too.
    columns.forEach(column => { if (!state.baseColumns.includes(column)) state.baseColumns.push(column); });
    // And back into the grid's order, since a column the earlier calls did not carry still
    // belongs at the front if that is where it was named — and out of it again where it is one
    // the grid hides, which a later call is as free to introduce as an earlier one was.
    state.baseColumns = showableColumns(gridId, state.baseColumns);
    // Then back into the operator's, where they have made one: an answer arriving into a grid
    // they have already arranged adds its new columns at the end rather than undoing the
    // arrangement.
    const arranged = state.allColumns;
    state.allColumns = state.baseColumns.slice();
    applyColumnPick(state, arranged);
    state.rows = state.rows.concat(shown.rows);
    state.filteredOut += shown.hidden;
    state.filterError = shown.error;
    invalidateView(state);
    // Run again over the whole table, not just the arrivals: "5 errors of 27,000" has to be true
    // of every row the grid is holding, and the rows from earlier calls are still among them.
    applyRowCheck(state, rowCheckOf(gridId));
    paintGrid(gridId);
    feedChartsFromGrid(gridId);
}

/**
 * The columns a set of rows implies. Only the first {@link #COLUMN_SCAN} rows are looked at: a
 * response whose hundredth row introduces a new field is vanishingly rare next to the cost of
 * walking every key of every row, and that walk used to build one intermediate array holding a
 * string per field per row before the Set ever saw it.
 */
function columnsOf(rows) {
    const found = new Set();
    for (let i = 0; i < rows.length && i < COLUMN_SCAN; i++) {
        const row = rows[i];
        if (row && typeof row === 'object') Object.keys(row).forEach(key => found.add(key));
        else found.add('value');
    }
    return [...found];
}

/** One cell as the text it is shown, filtered, sorted and exported by. */
function cellText(row, column) {
    // Column names ignore case: a grid laid out with "Status" shows, sorts and filters the rows'
    // "status" — an exact match first, and the first key that differs only in case after it.
    const cell = (row && typeof row === 'object') ? rowField(row, column) : row;
    if (cell === undefined || cell === null) return '';
    return typeof cell === 'object' ? JSON.stringify(cell) : String(cell);
}

/**
 * Every row that matches the filters, in the chosen order. Cached on the state and thrown away
 * by {@link #invalidateView} whenever a filter or the sort changes, so scrolling further down a
 * 27,000-row result does not re-filter and re-sort it for each page shown.
 *
 * <p>The sort decorates rather than comparing cells in place: the old form called
 * {@link #cellText} — and so <code>JSON.stringify</code> on any object cell — twice per
 * comparison, which is O(n log n) stringifications of the same values. Now each row's key is
 * computed once.
 */
function visibleRows(state) {
    if (state.view) return state.view;

    const filters = Object.entries(state.filters)
        .filter(([, text]) => text && text.trim())
        .map(([column, text]) => [column, text.trim().toLowerCase()]);

    let rows = filters.length
        ? state.rows.filter(row => filters.every(([column, text]) =>
            cellText(row, column).toLowerCase().includes(text)))
        : state.rows;
    // A slice clicked on the pie that fills this grid narrows it first-hand and exactly.
    if (state.pinned) rows = rows.filter(state.pinned.test);
    // And the one narrowing that is not about a column at all: the rows the grid's own check
    // called wrong. Applied here with the filters rather than over the drawn rows, so it counts,
    // sorts, caps and exports as every other narrowing does — "export the failures" is the
    // request this exists for.
    if (state.errorsOnly && state.errorRows) rows = rows.filter(row => state.errorRows.has(row));

    if (state.sort) {
        const column = state.sort;
        rows = rows.map(row => ({ row, key: cellText(row, column) }));
        rows.sort((a, b) => compareCells(a.key, b.key) * state.direction);
        rows = rows.map(entry => entry.row);
    }
    // The cap goes on last, and that is the whole point of it: "the top 10" means the ten rows
    // that come first once the filters have chosen which rows are in play and the sort has put
    // them in order. Applied any earlier it would keep ten arbitrary rows and then sort those,
    // which is a different — and wrong — answer. Sliced rather than truncated in place, since
    // with no filter and no sort `rows` is still the grid's own array.
    state.cappedOut = state.topRows > 0 ? Math.max(rows.length - state.topRows, 0) : 0;
    if (state.cappedOut) rows = rows.slice(0, state.topRows);
    state.view = rows;
    return rows;
}

/** Drops the cached view — the next paint recomputes it. */
function invalidateView(state) {
    state.view = null;
    state.shown = GRID_PAGE;
}

/** Numbers compare as numbers so a column of ids does not sort 1, 10, 2. */
function compareCells(a, b) {
    if (a !== '' && b !== '' && !isNaN(Number(a)) && !isNaN(Number(b))) return Number(a) - Number(b);
    return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

/**
 * The grid's outcome, wherever its name is drawn — above the grid itself, on the tab that shows
 * it, in the head of a stacked one. Written into whatever placeholders are on the page rather
 * than redrawing any of them, so a tab strip does not have to be rebuilt (and the tab you are
 * looking at reselected) every time one of its grids is filled.
 */
function paintGridStatus(gridId) {
    document.querySelectorAll('[data-grid-status="' + CSS.escape(gridId) + '"]').forEach(el => {
        const info = gridMeta[gridId];
        const outcome = gridOutcome(gridId);
        el.className = 'grid-status' + (outcome ? ' ' + GRID_OUTCOME_CLASS[outcome] : '');
        el.textContent = outcome.toLowerCase();
        el.title = info && info.error ? info.error
            : outcome === 'ERROR' ? (info ? 'The call worked, but ' : '') + gridConcern(gridId)
            : '';
    });
    paintGridCheck(gridId);
    paintGridVerdict(gridId);
    // A grid inside a group of tabs is part of what that group's own badge is claiming, however
    // many strips up it is drawn.
    paintTabsetStatuses();
}

/** The badge's colour for each outcome. */
const GRID_OUTCOME_CLASS = { SUCCESS: 'ok', FAILURE: 'err', ERROR: 'error' };

/**
 * What happened to the grid, all told: FAILURE when the call behind it failed, ERROR when the
 * call worked and the grid's own reading of what came back says something is wrong, SUCCESS when
 * neither, or blank while there is nothing to judge. A failed call outranks everything below it:
 * it leaves no rows, or the rows of an error response, and neither says anything about whether
 * the answer was right.
 *
 * <p>This is the one answer the whole strip is built on — it is what a grid's own badge shows,
 * what the tab over it shows, and what a group of tabs rolls up (see {@link #tabsOutcome}) — so
 * everything the grid says about itself has to be in it. All three of the grid's readings are:
 * rows matching its error check, a check that could not be run at all, and a status condition
 * that came out FAILED. A grid drawn in red under a badge reading <b>success</b>, and a tab over
 * it claiming the same, is the page contradicting itself about the only thing it is there to say.
 *
 * <p>And it answers for a grid no call ever filled. Rows reach a grid other ways — a static
 * dataset as the page opens, another grid feeding this one — and a grid holding fifty-eight rows
 * with three of them wrong has plainly got something to say, whether or not there is a call
 * record beside it. Blank is kept for a grid with nothing in it and nothing to judge it by, which
 * is the one case that should not count for or against the group it is in.
 */
function gridOutcome(gridId) {
    const info = gridMeta[gridId];
    if (info && info.status !== 'SUCCESS') return 'FAILURE';
    if (gridConcern(gridId)) return 'ERROR';
    if (info) return 'SUCCESS';
    // No call behind it: it counts as a success only where it was actually judged, so a grid
    // sitting empty with no check on it stays out of the tally rather than padding it.
    const state = gridState[gridId];
    const judged = !!rowCheckOf(gridId) || !!(gridVerdict(gridId) || {}).status;
    return state && state.rows.length && judged ? 'SUCCESS' : '';
}

/**
 * What the grid itself says is wrong with what it is holding, in the words its own badges use —
 * or nothing, when it says nothing is. The reason {@link #gridOutcome} reads ERROR, and the
 * sentence under the pointer on every badge that reads it.
 */
function gridConcern(gridId) {
    const state = gridState[gridId];
    if (state && state.checkError) return 'This grid\'s row check could not be run: ' + state.checkError;
    if (state && state.errorCount > 0) {
        return state.errorCount.toLocaleString() + ' of its ' + state.rows.length.toLocaleString()
            + ' rows match the error check.';
    }
    const verdict = gridVerdict(gridId);
    if (verdict && verdict.status === 'FAILED') {
        return 'Its status condition ' + verdict.control.statusCondition + ' is not met — ROWCOUNT='
            + verdict.count.toLocaleString() + '.';
    }
    return '';
}

/**
 * The grid's status as its designer defined it — a row count test over the rows left after
 * filtering — or null for a grid that has none. FAILED outright when the call behind it failed:
 * a failed call returns no rows, and ROWCOUNT=0 must not read that as "no errors found".
 * Blank while the grid holds nothing yet.
 */
function gridVerdict(gridId) {
    const control = findControl(gridId);
    if (!control || control.type !== 'grid' || !control.statusCondition) return null;
    const state = gridState[gridId];
    const info = gridMeta[gridId];
    if (info && info.status === 'FAILED') return { status: 'FAILED', count: state ? visibleRows(state).length : 0, control };
    if (!state) return { status: '', count: 0, control };
    const count = visibleRows(state).length;
    const pass = control.statusCondition === 'ROWCOUNT>0'  ? count > 0
               : control.statusCondition === 'ROWCOUNT>=0' ? count >= 0
               : control.statusCondition === 'ROWCOUNT=0'  ? count === 0
               : false;
    return { status: pass ? 'SUCCESS' : 'FAILED', count, control };
}

/**
 * Writes the grid's status into its variable and onto its badge. Called wherever the rows the
 * grid holds, or the filters over them, change — so ${ordersStatus} is always true of what the
 * grid shows now.
 */
function paintGridVerdict(gridId) {
    const verdict = gridVerdict(gridId);
    if (verdict && verdict.control.statusVariable) values[verdict.control.statusVariable] = verdict.status;
    document.querySelectorAll('[data-grid-verdict="' + CSS.escape(gridId) + '"]').forEach(el => {
        el.className = 'grid-check';
        el.textContent = '';
        el.title = '';
        if (!verdict || !verdict.status) return;
        const ok = verdict.status === 'SUCCESS';
        el.className = 'grid-check ' + (ok ? 'ok' : 'err');
        // Worded as what it is about — the row count — rather than as a bare SUCCESS. Beside a
        // check reading "3 ERROR / 58 SUCCESS" the old wording was the same green word for a
        // different question, and a tab carrying both read as a tab saying the rows were fine
        // when what it meant was that there were some. The variable behind it is untouched:
        // ${name} is still SUCCESS or FAILED, which is what a page written against it expects.
        el.textContent = 'ROWCOUNT=' + verdict.count.toLocaleString() + (ok ? ' met' : ' not met');
        el.title = verdict.control.statusCondition + (ok ? ' is met' : ' is not met')
            + (verdict.control.statusVariable ? ' — read as ${' + verdict.control.statusVariable
                + '}, which is ' + verdict.status : '')
            + '. It counts the rows and says nothing about whether they are right.';
    });
}

/**
 * The grid's own verdict on its rows, drawn wherever its name is: beside the label, on the tab
 * that shows it, in the head of a stacked one.
 *
 * <p>Kept apart from the badge above rather than folded into it, because the two answer
 * different questions and a grid can plainly be one and not the other: the call succeeded and
 * five of the fifteen rows it returned are wrong. Both counts are over every row the grid holds,
 * not the window of them currently drawn and not what the filters have left — "5 ERROR" that
 * changed as you typed in a filter box would be a different claim entirely.
 */
function paintGridCheck(gridId) {
    const state = gridState[gridId];
    document.querySelectorAll('[data-grid-check="' + CSS.escape(gridId) + '"]').forEach(el => {
        el.className = 'grid-check';
        el.textContent = '';
        el.title = '';
        if (!state) return;
        if (state.checkError) {
            el.className = 'grid-check err';
            el.textContent = 'check failed';
            el.title = 'This grid\'s row check could not be run: ' + state.checkError;
            return;
        }
        if (!state.errorRows) return;   // no check on this grid, which is most of them
        const bad = state.errorCount;
        const good = state.rows.length - bad;
        el.className = 'grid-check ' + (bad ? 'err' : 'ok');
        el.textContent = bad.toLocaleString() + ' ERROR / ' + good.toLocaleString() + ' SUCCESS';
        el.title = bad ? bad.toLocaleString() + ' of ' + state.rows.length.toLocaleString()
                + ' rows match this grid\'s error check.'
            : 'No row matches this grid\'s error check.';
    });
}

/**
 * The call behind the grid, folded away at the top of it: what went out, what came back, how
 * long it took and how big it was. Collapsed by default because on a page that is working none
 * of it is what you are looking at, and one line from it — the method, the status, the timing,
 * the size — is enough to see that it worked. Open, it is the whole record, which is what you
 * want the moment it stops working.
 */
function gridMetaBar(gridId) {
    const info = gridMeta[gridId];
    if (!info) return '';
    const m = info.meta || {};
    const summary = [
        m.httpMethod,
        m.statusCode ? 'HTTP ' + m.statusCode : '',
        (m.timeTaken !== undefined && m.timeTaken !== null) ? m.timeTaken + ' ms' : '',
        formatBytes(m.responseSize)
    ].filter(Boolean).join(' · ');

    // Nothing to open where nothing was recorded: an action that made no call — a performance
    // summary — has no URL, no status code and no timing, so the bar says what filled the grid
    // and stops there rather than offering a caret onto an empty panel.
    const openable = !!info.meta || !!info.error;

    return '<div class="grid-meta">'
        + '<button type="button" class="grid-meta-head"' + (openable ? ' data-act="meta"' : ' disabled') + '>'
            + (openable ? '<span class="caret' + (info.expanded ? ' open' : '') + '">&#9656;</span>' : '')
            + '<span class="grid-status ' + GRID_OUTCOME_CLASS[gridOutcome(gridId)] + '">'
                + gridOutcome(gridId).toLowerCase() + '</span>'
            + '<span class="grid-meta-sum">' + AC.esc(summary || info.note || 'call details') + '</span>'
            + '<span class="grid-meta-url">' + AC.esc(m.url || '') + '</span>'
        + '</button>'
        + (openable && info.expanded ? '<div class="grid-meta-body">' + gridMetaRows(m, info.error)
            + (techButton(info) ? '<div class="wide">' + techButton(info) + '</div>' : '')
            + '</div>' : '')
        + '</div>';
}

/** The record's fields, in the order someone diagnosing a call reads them. */
const META_ROWS = [
    ['URL', 'url', true], ['Method', 'httpMethod'], ['Status', 'status'], ['Status code', 'statusCode'],
    ['Time taken', 'timeTaken'], ['Response size', 'responseSize'], ['Request size', 'requestSize'],
    ['App', 'appName'], ['Environment', 'environment'], ['Env class', 'envClass'], ['Use case', 'useCase'],
    ['Instance', 'instanceLabel'], ['Executed via', 'executedVia'], ['Started', 'startedAtText'],
    ['Execution id', 'executionId'], ['Unresolved variables', 'unresolvedVariables', true]
];

function gridMetaRows(m, error) {
    const cell = (label, value, wide, bad) =>
        (value === undefined || value === null || value === '') ? ''
            : '<div' + (wide ? ' class="wide"' : '') + '><div class="mk">' + AC.esc(label) + '</div>'
                + '<div class="mv' + (bad ? ' err' : '') + '">' + AC.esc(value) + '</div></div>';

    const cells = [cell('What went wrong', error, true, true)].concat(META_ROWS.map(row => {
        const [label, key, wide] = row;
        let value = m[key];
        if (key === 'timeTaken' && value !== undefined && value !== null) value = value + ' ms';
        if (key === 'responseSize' || key === 'requestSize') value = formatBytes(value);
        return cell(label, value, wide);
    })).filter(Boolean);

    return cells.length ? cells.join('')
        : '<div class="wide"><div class="mv">Nothing was recorded about this call.</div></div>';
}

/**
 * Whether this grid on the running page is a grid control the designer laid out, rather than one
 * built while the page ran — a stacked grid from a "new grid" target, a tab a fan-out added, or
 * the grid behind a pie's slice. Only a placed one outlives the run that filled it and so is the
 * only one with anything to empty: the others are taken away whole instead.
 */
function isPlacedGrid(gridId) {
    const control = findControl(gridId);
    return !!control && control.type === 'grid';
}

/**
 * Empties one grid where it stands — its rows, the record of the call that filled them, and the
 * filters and sort that were about those rows — leaving it reading "No data yet" as it did
 * before anything ran.
 *
 * <p>The counterpart to an action that adds to a grid rather than replacing it: a table built up
 * over several runs needs somewhere to start again from, and Reset empties the whole page, which
 * is more than an operator part-way through building one table is asking for.
 *
 * <p>Whatever draws itself from this grid is emptied with it, down the chain: a chart or a
 * second grid sourced from one that no longer has any rows would otherwise be left showing the
 * run it was fed by, which is the one thing the operator has just said is gone.
 */
function clearGridRows(gridId, seen) {
    const control = findControl(gridId);
    if (!control) return;
    // A page saved with two grids feeding each other would otherwise clear forever, the same
    // reason filling them is guarded — see feedingGrids.
    const done = seen || new Set();
    if (done.has(gridId)) return;
    done.add(gridId);
    clearControl(control);
    chartsFromGrid(gridId).forEach(chart => clearControl(chart));
    gridsFromGrid(gridId).forEach(grid => clearGridRows(grid.controlId, done));
}

function paintGrid(gridId) {
    paintGridStatus(gridId);
    const host = document.querySelector('[data-grid="' + CSS.escape(gridId) + '"]');
    if (!host) return;
    const state = gridState[gridId];
    const info = gridMeta[gridId];
    if (!state) {
        // A failed call leaves no rows, so what happened to it is all this grid has to show —
        // and is exactly what someone looking at an empty grid needs.
        host.innerHTML = gridMetaBar(gridId)
            + '<div class="grid-box"><div class="grid-empty">'
            + AC.esc(info && info.error ? info.error : 'No data yet.') + '</div></div>';
        wireGridMeta(host, gridId);
        return;
    }

    const rows = visibleRows(state);

    // "Clear filters" is always in the markup and only shown when it would do something —
    // typing in a filter redraws the rows alone, and a button that appeared then disappeared
    // would move the others out from under the pointer.
    host.innerHTML = gridMetaBar(gridId)
        + '<div class="grid-tools">'
            + '<span class="grid-count">' + AC.esc(gridCount(state, rows)) + '</span>'
            + (state.pinned ? '<span class="grid-pin" title="Filtered by the slice clicked on the chart">'
                + AC.esc(state.pinned.label) + '<button type="button" data-act="unpin" title="Show every row">×</button></span>' : '')
            + gridErrorsBox(state)
            + gridWrapBox(state)
            + gridColumnsBox(state)
            + gridTopBox(state)
            + '<button class="tool-btn" data-act="clear"' + (isFiltered(state) ? '' : ' hidden') + '>Clear filters</button>'
            // Only where there is a control to clear: a stacked grid has an × of its own that
            // takes the whole grid away, and a pie's grid is redrawn from the chart's own rows.
            + (isPlacedGrid(gridId) ? '<button class="tool-btn" data-act="empty" title="Take every row off this grid">Clear rows</button>' : '')
            + '<button class="tool-btn" data-act="csv" title="Comma separated, quoted where a value needs it">Export CSV</button>'
            // Pipe separated for the loaders and scripts downstream, which meet a comma inside a
            // value far more often than they meet a pipe inside one.
            + '<button class="tool-btn" data-act="psv" title="Pipe separated, quoted where a value needs it">Export PSV</button>'
            + '<button class="tool-btn" data-act="html">View as HTML</button>'
            + '<button class="tool-btn" data-act="analyze" title="Pivot these rows on their own screen">Analyze</button>'
            // Not an export: the rows stay here, in the dataset library, where anything that
            // reads a dataset can name them rather than be handed a file.
            + '<button class="tool-btn" data-act="dataset" title="Keep these rows in the dataset library under a name">Save as dataset</button>'
        + '</div>'
        + '<div class="grid-box' + (state.wrap ? ' wrap' : '') + '">'
            + (state.rows.length ? gridTable(state, rows, gridId)
                // A grid that failed has no rows for the same reason it has no answer, so it
                // says why rather than "no rows returned", which would claim the call worked.
                : '<div class="grid-empty">' + AC.esc(info && info.status === 'FAILED' && info.error
                    ? info.error : 'No rows returned.') + '</div>')
        + '</div>'
        + moreBar(state, rows);

    host.querySelectorAll('[data-act]').forEach(el => el.addEventListener('click', () => {
        if (el.dataset.act === 'csv')   exportDelimited(gridId, 'csv');
        if (el.dataset.act === 'psv')   exportDelimited(gridId, 'psv');
        if (el.dataset.act === 'html')  viewAsHtml(gridId);
        if (el.dataset.act === 'analyze') analyzeGrid(gridId);
        if (el.dataset.act === 'dataset') saveGridAsDataset(gridId);
        if (el.dataset.act === 'more')  showMore(gridId, GRID_PAGE);
        if (el.dataset.act === 'all')   showMore(gridId, Infinity);
        if (el.dataset.act === 'meta')  toggleGridMeta(gridId);
        if (el.dataset.act === 'unpin') { unpinGrid(gridId); paintGrid(gridId); }
        if (el.dataset.act === 'empty') clearGridRows(gridId);
        if (el.dataset.act === 'cols')  { state.colsOpen = !state.colsOpen; paintGrid(gridId); }
        if (el.dataset.act === 'cols-all')   resetGridColumns(gridId, false);
        if (el.dataset.act === 'cols-reset') resetGridColumns(gridId, true);
        if (el.dataset.act === 'clear') {
            state.filters = {};
            state.errorsOnly = false;
            unpinGrid(gridId);
            invalidateView(state);
            paintGrid(gridId);
        }
    }));
    host.querySelectorAll('[data-errors-only]').forEach(el => el.addEventListener('change', () => {
        state.errorsOnly = el.checked;
        invalidateView(state);
        paintGrid(gridId);
    }));
    // The rows are unchanged — only how they are drawn — so the view is not invalidated and the
    // filters, the sort and the cap all survive the switch.
    host.querySelectorAll('[data-wrap]').forEach(el => el.addEventListener('change', () => {
        state.wrap = el.checked;
        paintGrid(gridId);
    }));
    wireColumnChooser(host, gridId, state);
    wireCellLinks(host, gridId);
    wireCellExpanders(host);
    host.querySelectorAll('[data-sort]').forEach(el => el.addEventListener('click', () => {
        const column = el.dataset.sort;
        state.direction = state.sort === column ? -state.direction : 1;
        state.sort = column;
        invalidateView(state);
        paintGrid(gridId);
    }));
    host.querySelectorAll('[data-top]').forEach(el => el.addEventListener('input', () => {
        state.topRows = normalizeTopRows(el.value);
        // Debounced for the reason the column filters are: "250" is typed as 2, then 25, then
        // 250, and re-sorting a 27,000-row grid twice on the way to the number meant is the
        // cost that makes a big grid feel broken. Only the rows are redrawn when it settles,
        // so the caret stays in the box being typed into.
        clearTimeout(state.topTimer);
        state.topTimer = setTimeout(() => {
            invalidateView(state);
            refreshGridRows(gridId);
        }, FILTER_DEBOUNCE);
    }));
    host.querySelectorAll('[data-filter]').forEach(el => el.addEventListener('input', () => {
        state.filters[el.dataset.filter] = el.value;
        // Filtering tens of thousands of rows on every keystroke is what makes a big grid feel
        // broken, so the redraw waits until typing pauses. Only the rows are redrawn when it
        // does: rebuilding the header would take the caret with it.
        clearTimeout(state.filterTimer);
        state.filterTimer = setTimeout(() => {
            invalidateView(state);
            refreshGridRows(gridId);
        }, FILTER_DEBOUNCE);
    }));
}

/**
 * The "showing 200 of 27,000" footer. Rendering every row is what put the tab on the floor: a
 * 27,000-row response over twenty columns is over half a million table cells, and the browser
 * needs far more memory per cell than the row behind it costs. The rows all stay in memory —
 * they are cheap, and the filters, the sort and both exports still see every one of them — but
 * only a window of them is ever in the document.
 */
function moreBar(state, rows) {
    const hidden = rows.length - Math.min(state.shown, rows.length);
    if (hidden <= 0) return '';
    return '<div class="grid-more">'
        + '<button class="tool-btn" data-act="more">Show ' + Math.min(GRID_PAGE, hidden).toLocaleString() + ' more</button>'
        + '<button class="tool-btn" data-act="all">Show all ' + rows.length.toLocaleString() + '</button>'
        + '<span class="hint">' + hidden.toLocaleString() + ' more not shown — filter, sort or export to reach them.</span>'
        + '</div>';
}

/**
 * The tick boxes and the arrows inside the column chooser, and the click anywhere else on the
 * page that shuts it.
 *
 * <p>The closer goes on the document rather than on the grid because what shuts a fold-out is a
 * click that did not land in it, wherever that is; on mousedown rather than click so it shuts
 * before whatever was aimed at underneath happens. One at a time per grid — every tick repaints
 * the chooser, and a listener added per paint would be a listener per tick.
 */
function wireColumnChooser(host, gridId, state) {
    host.querySelectorAll('[data-col-show]').forEach(el => el.addEventListener('change', () =>
        showGridColumn(gridId, el.dataset.colShow, el.checked)));
    host.querySelectorAll('[data-col-move]').forEach(el => el.addEventListener('click', () =>
        moveGridColumn(gridId, el.dataset.colMove, +el.dataset.colDelta)));

    if (!state.colsOpen) {
        if (state.colsCloser) {
            document.removeEventListener('mousedown', state.colsCloser, true);
            state.colsCloser = null;
        }
        return;
    }
    // A grid over on the right-hand side of the page would open its chooser off the edge, so the
    // one that would is hung from its right instead. Measured rather than guessed from the
    // column the grid was laid out in: what matters is where it actually ended up on this screen.
    const pop = host.querySelector('[data-cols-pop]');
    if (pop && pop.getBoundingClientRect().right > document.documentElement.clientWidth - 8) {
        pop.classList.add('from-right');
    }
    if (state.colsCloser) return;
    state.colsCloser = e => {
        if (e.target.closest && e.target.closest('.grid-cols')) return;
        document.removeEventListener('mousedown', state.colsCloser, true);
        state.colsCloser = null;
        state.colsOpen = false;
        paintGrid(gridId);
    };
    document.addEventListener('mousedown', state.colsCloser, true);
}

/** The metadata bar is the only thing to wire on a grid that has no rows to draw. */
function wireGridMeta(host, gridId) {
    const head = host.querySelector('[data-act="meta"]');
    if (head) head.addEventListener('click', () => toggleGridMeta(gridId));
}

function toggleGridMeta(gridId) {
    const info = gridMeta[gridId];
    if (!info) return;
    info.expanded = !info.expanded;
    paintGrid(gridId);
}

function showMore(gridId, by) {
    const state = gridState[gridId];
    if (!state) return;
    const rows = visibleRows(state);
    if (by === Infinity && rows.length > BIG_GRID
        && !confirm('Put all ' + rows.length.toLocaleString() + ' rows on the page?\n\n'
            + 'That is roughly ' + (rows.length * state.columns.length).toLocaleString()
            + ' cells and may make the tab slow or run it out of memory. Exporting keeps every row '
            + 'without drawing it.')) return;
    state.shown = by === Infinity ? rows.length : state.shown + by;
    paintGrid(gridId);
}

function isFiltered(state) {
    return !!state.pinned || !!state.errorsOnly
        || Object.values(state.filters).some(text => text && text.trim());
}

/** Takes a slice's filter off a grid, and the pick off the chart that put it there. */
function unpinGrid(gridId) {
    const state = gridState[gridId];
    if (!state || !state.pinned) return;
    const owner = findControl(state.pinned.owner);
    state.pinned = null;
    invalidateView(state);
    if (owner) { delete chartPick[owner.controlId]; paintChart(owner); }
}

/**
 * The row cap, as the operator sees it: how many rows to keep once the grid is filtered and in
 * order. Blank for all of them, which is what a grid whose designer set no cap opens on.
 *
 * <p>Separate from the "show 200 more" footer below the grid, which is only about how much of
 * the answer is in the document at once — every row past it is still filtered, sorted, counted
 * and exported. This is the narrower question, and is answered before any of those: a grid
 * capped at 10 has ten rows, and ten is what its exports and its ROWCOUNT carry.
 */
/**
 * The switch between the two ways of reading a table.
 *
 * <p>Off — how a grid has always drawn — every cell is one line, and a column holding a stack
 * trace or a JSON blob is as wide as its widest value, which pushes the columns after it off the
 * right-hand edge. Fine for a table of ids and statuses, useless for one of messages.
 *
 * <p>On, the columns share the width between them, so every one of them is on screen at once, and
 * a cell takes as many lines as it needs. Cells that would run long are cut off at a few lines
 * with a button to open that one out, so a single enormous value cannot make one row as tall as
 * the screen and push everything else off the bottom — which is the state that makes wrapping
 * worse than the scroll it replaced.
 *
 * <p>In the toolbar rather than in the designer alone because which reading is wanted is a
 * question about what is being asked of the rows right now, and it changes twice while asking it.
 */
function gridWrapBox(state) {
    // The same box the errors tick is drawn as — it is the same kind of switch over the same
    // rows — but lit blue rather than red when it is on: wrapped text is a way of reading the
    // grid, and red beside a table means something in it is wrong.
    return '<label class="grid-errors-only grid-wrap-box' + (state.wrap ? ' on' : '') + '"'
        + ' title="Fit every column on screen and let the cells run to as many lines as they need">'
        + '<input type="checkbox" data-wrap' + (state.wrap ? ' checked' : '') + '>Wrap text</label>';
}

/**
 * The column chooser: which of the columns this answer carries are on screen, and in what order.
 *
 * <p>The designer already answers this for the page — Columns, First Columns and Hidden Columns
 * between them say which columns a grid draws and which come first. This is the same question
 * asked by the person looking at the table, and it is asked for a different reason: the designer
 * is arranging the grid for every run of the page, and the operator is arranging it for the
 * question they are asking of these rows right now. A response of thirty columns is read four at
 * a time, and which four changes twice while reading it — the same argument that puts Wrap text
 * in the toolbar rather than in the designer alone.
 *
 * <p>So it is the operator's reading of the grid, not a change to the page: nothing is saved, and
 * the rows are untouched. A column that is off is off the screen and out of the filter row, the
 * sort, both exports, "View as HTML" and Analyze — because all of those read the drawn columns —
 * and is still there for the error check, a fan-out, a lookup and anything reading
 * <code>${column}</code>, exactly as a designer's hidden column is.
 *
 * <p>Ticks and arrows rather than dragging. Dragging is the better gesture for putting four things
 * in an order and the worse one for a list of thirty inside a popup inside a scrolling page, which
 * is the list this actually has to handle.
 */
function gridColumnsBox(state) {
    const all = state.allColumns || [];
    if (!all.length) return '';
    const off = all.length - state.columns.length;
    // Lit whenever the grid is not showing what the page would have shown — columns turned off, or
    // the same columns in an order the operator put them in. A grid showing four of twenty has to
    // say so on the toolbar; otherwise the next person to look at it reads a short answer.
    const arranged = off > 0 || all.join('\u0000') !== (state.baseColumns || []).join('\u0000');
    return '<span class="grid-cols">'
        + '<button class="tool-btn' + (arranged ? ' picked' : '') + '" data-act="cols"'
            + ' title="Choose which columns this grid shows, and the order they are in">Columns'
            + (off ? ' (' + state.columns.length + ' of ' + all.length + ')' : '')
        + '</button>'
        + (state.colsOpen ? gridColumnsPop(state) : '')
        + '</span>';
}

/** The chooser folded out: a row per column, in the order the grid is drawing them. */
function gridColumnsPop(state) {
    const all = state.allColumns;
    return '<div class="grid-cols-pop" data-cols-pop>'
        + '<div class="grid-cols-list">' + all.map((column, i) => {
            const on = !state.colsOff.has(String(column).toLowerCase());
            // Plain escaping, not attr(): these come back through dataset as the column key
            // itself, and a name carrying an apostrophe has to survive the round trip — the same
            // reason the sort and filter headers are written this way.
            const name = AC.esc(column);
            return '<div class="grid-cols-row' + (on ? '' : ' off') + '">'
                + '<label><input type="checkbox" data-col-show="' + name + '"' + (on ? ' checked' : '') + '>'
                + '<span title="' + AC.attr(column) + '">' + name + '</span></label>'
                // Disabled at the ends rather than left out, so the rows do not change width as
                // a column is walked up the list and the next arrow is still under the pointer.
                + '<button class="tool-btn" data-col-move="' + name + '" data-col-delta="-1" title="Earlier"'
                    + (i === 0 ? ' disabled' : '') + '>&#8593;</button>'
                + '<button class="tool-btn" data-col-move="' + name + '" data-col-delta="1" title="Later"'
                    + (i === all.length - 1 ? ' disabled' : '') + '>&#8595;</button>'
                + '</div>';
        }).join('') + '</div>'
        + '<div class="grid-cols-foot">'
            + '<button class="tool-btn" data-act="cols-all" title="Show every column this answer carries">Show all</button>'
            + '<button class="tool-btn" data-act="cols-reset" title="Back to the columns and the order the page was designed with">Reset</button>'
            + '<span class="hint">' + state.columns.length + ' of ' + all.length + ' shown</span>'
        + '</div></div>';
}

/**
 * Turns one column on or off.
 *
 * <p>Its filter and its sort go with it. A column that is not on screen cannot be seen to be
 * filtering the table or ordering it, and a grid narrowed by a filter nobody can find is the one
 * way this could quietly lie about the rows — so what goes off the screen stops acting on it.
 */
function showGridColumn(gridId, column, on) {
    const state = gridState[gridId];
    if (!state) return;
    const key = String(column).toLowerCase();
    if (on) state.colsOff.delete(key);
    else {
        state.colsOff.add(key);
        if (state.filters[column]) { delete state.filters[column]; invalidateView(state); }
        if (state.sort && String(state.sort).toLowerCase() === key) { state.sort = null; invalidateView(state); }
    }
    applyColumnPick(state, null);
    paintGrid(gridId);
}

/** Moves one column a place earlier or later, whether it is on screen or not. */
function moveGridColumn(gridId, column, delta) {
    const state = gridState[gridId];
    if (!state) return;
    const at = state.allColumns.indexOf(column);
    const to = at + delta;
    if (at === -1 || to < 0 || to >= state.allColumns.length) return;
    [state.allColumns[at], state.allColumns[to]] = [state.allColumns[to], state.allColumns[at]];
    applyColumnPick(state, null);
    paintGrid(gridId);
}

/** Every column back on screen, in the order the page was designed to show them. */
function resetGridColumns(gridId, orderToo) {
    const state = gridState[gridId];
    if (!state) return;
    state.colsOff.clear();
    if (orderToo) state.allColumns = (state.baseColumns || state.allColumns).slice();
    applyColumnPick(state, null);
    paintGrid(gridId);
}

function gridTopBox(state) {
    // Lit only when the number is actually holding rows back — a cap of 500 over 30 rows is set
    // but doing nothing, and highlighting it would point at a limit nobody is hitting.
    return '<label class="grid-top' + (state.cappedOut ? ' capped' : '') + '"'
        + ' title="Keep only the first rows once the grid is filtered and sorted. Blank for every row.">Top'
        + '<input type="number" min="0" step="1" placeholder="all" data-top'
        + ' value="' + (state.topRows > 0 ? state.topRows : '') + '"></label>';
}

/**
 * The tick box that leaves only the rows the grid's check called wrong.
 *
 * <p>Drawn only on a grid that has some, which is the whole of when it means anything: a grid
 * with no check has no verdict to narrow by, and one whose every row passed would offer a box
 * that empties it. A grid saying "5 ERROR / 2,000 SUCCESS" is the case — the five are what
 * somebody opened the page to see, and finding them by typing into a column filter means already
 * knowing which column went wrong.
 *
 * <p>The error rows are held by identity rather than by any column, so this is a narrowing no
 * amount of typing into the filter row could reproduce.
 */
function gridErrorsBox(state) {
    if (!state.errorRows || !state.errorCount) return '';
    return '<label class="grid-errors-only' + (state.errorsOnly ? ' on' : '') + '"'
        + ' title="Show only the rows this grid' + Q + 's error check called wrong">'
        + '<input type="checkbox" data-errors-only' + (state.errorsOnly ? ' checked' : '') + '>'
        + 'Errors only (' + state.errorCount.toLocaleString() + ')</label>';
}

function gridCount(state, rows) {
    const total = state.rows.length;
    const drawn = Math.min(state.shown, rows.length);
    const matching = rows.length === total ? total.toLocaleString()
        : rows.length.toLocaleString() + ' of ' + total.toLocaleString();
    // Named whenever it is doing something, because "10 of 27,000 rows" beside a grid with no
    // filter typed into it otherwise looks like the call came back short.
    return (drawn < rows.length ? 'showing ' + drawn.toLocaleString() + ' · ' : '')
         + (state.cappedOut ? 'top ' + state.topRows.toLocaleString() + ' · ' : '')
         + matching + ' row' + (total === 1 ? '' : 's')
         // Said out loud beside the count, so "3 of 2,005 rows" never reads as a call that came
         // back short when it is the operator's own tick box holding the rest back.
         + (state.errorsOnly && state.errorRows ? ' · errors only' : '')
         + (state.filteredOut ? ' · ' + state.filteredOut.toLocaleString() + ' hidden by the display filter' : '')
         + (state.filterError ? ' · display filter not applied: ' + state.filterError : '');
}

function gridTable(state, rows, gridId) {
    const arrow = column => state.sort !== column ? ''
        : '<span class="sort-arrow">' + (state.direction > 0 ? '▲' : '▼') + '</span>';
    return '<table><thead>'
        + '<tr>' + state.columns.map(column =>
            // Plain escaping, not attr(): these come back through dataset as the column key
            // itself, and a name carrying an apostrophe has to survive the round trip.
            '<th class="sortable" data-sort="' + AC.esc(column) + '" title="Sort by ' + AC.esc(column) + '">'
            + AC.esc(column) + arrow(column) + '</th>').join('') + '</tr>'
        + '<tr class="filter-row">' + state.columns.map(column =>
            '<th><input type="text" placeholder="filter" data-filter="' + AC.esc(column) + '"'
            + ' value="' + AC.esc(state.filters[column] || '') + '"></th>').join('') + '</tr>'
        + '</thead><tbody>' + gridRows(state, rows, gridId) + '</tbody></table>';
}

/**
 * The columns of this grid that drill down, as a set. Empty for a stacked grid and for the one
 * a "new grid" target builds: neither has a control behind it to have been configured, so their
 * cells are text like they always were.
 */
function clickableColumns(gridId) {
    const control = gridOwner(gridId);
    if (!control) return new Set();
    return new Set((control.columnLinks || []).map(link => link.column).filter(Boolean).map(c => c.toLowerCase()));
}

/** One of a grid's clickable columns by name, whatever case either is written in. */
function columnLinkNamed(control, column) {
    const wanted = String(column || '').toLowerCase();
    return ((control && control.columnLinks) || []).find(l => String(l.column || '').toLowerCase() === wanted);
}

/**
 * Only the window of rows currently shown — see {@link #moreBar} for why that is not all of them.
 *
 * <p>A cell in a clickable column carries the column and its place in the rows as they are
 * currently filtered and sorted, which is what {@link #gridRows} is handed and what the click
 * reads back. An index into the filtered view rather than into the rows as they arrived: the two
 * differ the moment anything is filtered, and the view is the only one of them the operator can
 * see to point at.
 */
function gridRows(state, rows, gridId) {
    if (!rows.length) return '<tr><td colspan="' + state.columns.length
        + '"><div class="grid-empty">No rows match the filters.</div></td></tr>';
    const clickable = clickableColumns(gridId);
    const rowLive = !!rowClickOf(gridId);
    const limit = Math.min(state.shown, rows.length);
    const bad = state.errorRows;
    const out = [];
    for (let i = 0; i < limit; i++) {
        const classes = (bad && bad.has(rows[i]) ? 'row-error ' : '') + (rowLive ? 'row-link' : '');
        // The row carries its place in the view exactly as a drilling cell does, and is read back
        // the same way — see #runRowClick.
        const rowAttrs = (classes.trim() ? ' class="' + classes.trim() + '"' : '')
            + (rowLive ? ' role="button" tabindex="0" data-row-click="' + i + '"' : '');
        out.push('<tr' + rowAttrs + '>' + state.columns.map(column => {
            // Plain escaping, not attr(): the column comes back through dataset as the key
            // itself, so a name carrying an apostrophe has to survive the round trip.
            const drill = clickable.has(String(column).toLowerCase())
                ? ' class="cell-link" role="button" tabindex="0" data-cell-link="' + AC.esc(column) + '" data-cell-row="' + i + '"'
                : '';
            return '<td' + drill + '>' + cellBody(cellText(rows[i], column), state.wrap) + '</td>';
        }).join('') + '</tr>');
    }
    return out.join('');
}

/**
 * How long a value has to be before a wrapped cell is drawn with a way to open it out. A count of
 * characters rather than a measurement of the drawn cell: measuring means reading back the layout
 * of every cell of every row, which is the one thing a grid of twenty-seven thousand rows cannot
 * afford to do, and the cost of being wrong is a button on a cell that did not need one.
 */
const WRAP_EXPAND_AT = 140;

/**
 * What goes inside a cell.
 *
 * <p>Unwrapped, the text and nothing else — the markup a grid has always drawn, unchanged, since
 * every row of every grid goes through here and the common case should cost nothing.
 *
 * <p>Wrapped, the text in a box the stylesheet can cut off at a few lines, and — where the value
 * is long enough to be cut off — a button that opens that one cell out and closes it again. Per
 * cell rather than per row: the reason to open one is that a single column of it is a message or
 * a payload, and taking the whole row to that height would push its neighbours off the screen for
 * the sake of one value.
 */
function cellBody(text, wrap) {
    if (!wrap) return AC.esc(text);
    const long = text.length > WRAP_EXPAND_AT;
    return '<div class="cell-wrap">' + AC.esc(text) + '</div>'
        + (long ? '<button type="button" class="cell-more" data-cell-more'
                + ' title="Show all of this value">&#8942;</button>' : '');
}

/**
 * Opens a wrapped cell out, or shuts it again. Done to the cell in the document rather than by
 * redrawing the rows, because it is one cell changing height and a redraw would lose every other
 * cell the operator had opened on the way down the table.
 *
 * <p>Delegated from the grid rather than bound per cell: a window of a grid is two hundred rows
 * over twenty columns, and four thousand listeners for a button that is clicked twice is a cost
 * worth not paying. The click is stopped before it reaches the row underneath, which on a grid
 * with clickable rows would otherwise drill down on the way to opening a cell.
 */
function wireCellExpanders(host) {
    // The host outlives every repaint of what is inside it, so the listener goes on once and is
    // still there for rows drawn long afterwards — wiring it per paint would stack up a copy per
    // run and open and shut the cell as many times as there were runs.
    if (host.dataset.expanders) return;
    host.dataset.expanders = '1';
    host.addEventListener('click', e => {
        const button = e.target.closest && e.target.closest('[data-cell-more]');
        if (!button || !host.contains(button)) return;
        e.stopPropagation();
        e.preventDefault();
        const cell = button.closest('td');
        if (!cell) return;
        const open = cell.classList.toggle('cell-open');
        button.title = open ? 'Show less of this value' : 'Show all of this value';
    });
}

/**
 * Wires the cells that drill down. Called wherever rows are written, which is both places they
 * are: the whole grid being painted and the body alone being refreshed after a filter or a sort.
 * Bound per cell rather than delegated from the host, since the host survives a repaint and
 * would collect a listener each time.
 */
function wireCellLinks(host, gridId) {
    host.querySelectorAll('[data-cell-link]').forEach(cell => {
        const run = e => {
            // A drilling cell sits inside a row that may itself be clickable, and the cell is the
            // narrower thing the operator aimed at: it answers the click, and the row does not
            // also answer it. Without this, clicking an order id would drill down and then
            // immediately run whatever the row runs over the top of it.
            if (e) e.stopPropagation();
            // Narrower still: the button that opens a wrapped cell out is inside the cell, and is
            // asking to read the value rather than to go wherever the value leads. It sits on the
            // cell it belongs to, so this is the only place that can tell the two apart.
            if (e && e.target && e.target.closest && e.target.closest('[data-cell-more]')) return;
            runColumnLink(gridId, cell.dataset.cellLink, +cell.dataset.cellRow, cell);
        };
        cell.addEventListener('click', run);
        cell.addEventListener('keydown', e => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            run(e);
        });
    });
    host.querySelectorAll('[data-row-click]').forEach(row => {
        const run = e => {
            // The same exception a drilling cell makes, for the same reason: opening a cell out
            // to read it is not asking the row to go anywhere.
            if (e && e.target && e.target.closest && e.target.closest('[data-cell-more]')) return;
            runRowClick(gridId, +row.dataset.rowClick, row);
        };
        row.addEventListener('click', run);
        row.addEventListener('keydown', e => {
            // Space scrolls a page by default, which on a grid of rows is the last thing wanted.
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            run();
        });
    });
}

function refreshGridRows(gridId) {
    const host = document.querySelector('[data-grid="' + CSS.escape(gridId) + '"]');
    const state = gridState[gridId];
    if (!host || !state) return;
    const rows = visibleRows(state);
    const body = host.querySelector('tbody');
    if (body) { body.innerHTML = gridRows(state, rows, gridId); wireCellLinks(body, gridId); }
    host.querySelector('.grid-count').textContent = gridCount(state, rows);
    // The whole badge, not only the verdict: a status condition is a count of the rows left after
    // filtering, so filtering can turn it from met to unmet — and that is part of what the grid's
    // outcome, the tab over it and the group above that are all claiming. See #gridOutcome.
    paintGridStatus(gridId);
    // The cap's box is left exactly as typed — replacing it would take the caret out of the
    // number being typed — and only its highlight is moved to match what the number now does.
    const top = host.querySelector('.grid-top');
    if (top) top.classList.toggle('capped', !!state.cappedOut);
    const clear = host.querySelector('[data-act="clear"]');
    if (clear) clear.hidden = !isFiltered(state);
    // The footer's counts move with the filter, and it appears and disappears with it.
    const more = host.querySelector('.grid-more');
    const wanted = moreBar(state, rows);
    if (more) more.outerHTML = wanted;
    else if (wanted) host.insertAdjacentHTML('beforeend', wanted);
    host.querySelectorAll('.grid-more [data-act]').forEach(el => el.addEventListener('click', () => {
        showMore(gridId, el.dataset.act === 'all' ? Infinity : GRID_PAGE);
    }));
}

/**
 * A target of "new grid" builds another grid per run instead of overwriting one, newest first,
 * so two runs can be read against each other. Each keeps its own filters and sort.
 */
function pushStackedGrid(name, rows, columns, record) {
    const gridId = 'stacked-' + (++stackedCount);
    const box = document.createElement('div');
    box.className = 'stacked-grid';
    box.innerHTML = '<div class="stacked-head">'
            + '<span class="stacked-title">' + AC.esc(name) + '</span>'
            + '<span class="grid-status" data-grid-status="' + AC.attr(gridId) + '"></span>'
            + '<span class="grid-check" data-grid-check="' + AC.attr(gridId) + '"></span>'
            + '<span class="stacked-when">' + AC.esc(new Date().toLocaleTimeString()) + '</span>'
            + '<button class="icon-btn" title="Remove this grid">×</button>'
        + '</div>'
        + '<div class="data-grid" data-grid="' + AC.attr(gridId) + '"></div>';
    box.querySelector('.icon-btn').addEventListener('click', () => {
        box.remove();
        delete gridState[gridId];
        delete gridMeta[gridId];
    });
    document.getElementById('stackedGrids').prepend(box);
    if (record) gridMeta[gridId] = record;
    setGridData(gridId, rows, columns || null, name);
    return gridId;
}

// ── Taking a grid elsewhere ──────────────────────────────────────────────
// Every export follows what is on screen — the filters and the sort the operator applied — since
// that selection is usually the reason they are exporting at all.

// A comma for the spreadsheet someone opens it in, a pipe for the loader or script someone feeds
// it to: the same rows, quoted the same way, only the separator differs.
const DELIMITED = {
    // The BOM is what makes Excel read the file as UTF-8 rather than the local code page.
    csv: { delimiter: ',', type: 'text/csv;charset=utf-8', bom: true },
    // No BOM on a pipe file: what reads it is usually something that would carry those bytes
    // into the first column's name rather than strip them, and Excel cannot split on pipes anyway.
    psv: { delimiter: '|', type: 'text/plain;charset=utf-8', bom: false }
};

function exportDelimited(gridId, format) {
    const state = gridState[gridId];
    const spec = DELIMITED[format] || DELIMITED.csv;
    const rows = visibleRows(state);
    const cell = text => delimitedCell(text, spec.delimiter);
    const lines = [state.columns.map(cell).join(spec.delimiter)]
        .concat(rows.map(row => state.columns.map(column => cell(cellText(row, column))).join(spec.delimiter)));
    download(fileName(state.title, format), spec.type,
        (spec.bom ? String.fromCharCode(0xFEFF) : '') + lines.join('\r\n'));
}

/** One value as the file carries it: quoted, CSV-style, when it holds the separator, a quote or a line break. */
function delimitedCell(text, delimiter) {
    const value = String(text === undefined || text === null ? '' : text);
    return value.indexOf(delimiter) >= 0 || /["\r\n]/.test(value)
        ? '"' + value.replace(/"/g, '""') + '"' : value;
}

function download(name, type, content) {
    const url = URL.createObjectURL(new Blob([content], { type: type }));
    const link = document.createElement('a');
    link.href = url;
    link.download = name;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
}

/** Opens the rows as a plain HTML table in their own tab — printable, and easy to paste on. */
function viewAsHtml(gridId) {
    const state = gridState[gridId];
    const rows = visibleRows(state);
    const title = state.title || 'Grid';
    const html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
        + '<title>' + AC.esc(title) + '</title><style>'
        + 'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#172b4d;margin:24px}'
        + 'h1{font-size:18px;margin:0 0 4px}p{font-size:12px;color:#5e6c84;margin:0 0 16px}'
        + 'table{border-collapse:collapse;font-size:13px}'
        + 'th,td{border:1px solid #dfe1e6;padding:6px 10px;text-align:left;vertical-align:top}'
        + 'th{background:#f4f5f7;font-weight:600}tr:nth-child(even) td{background:#fafbfc}'
        // The verdict travels with the rows: a table printed or mailed on without it would show
        // the failures as ordinary rows, which is the one thing the reader must not miss.
        + 'tr.row-error td{background:#ffebe6!important;color:#bf2600}'
        + '</style></head><body><h1>' + AC.esc(title) + '</h1>'
        + '<p>' + rows.length + ' row' + (rows.length === 1 ? '' : 's')
        + (state.errorRows ? ' · ' + state.errorCount + ' ERROR / ' + (state.rows.length - state.errorCount) + ' SUCCESS' : '')
        + ' · ' + AC.esc(new Date().toLocaleString()) + '</p>'
        + '<table><thead><tr>' + state.columns.map(column => '<th>' + AC.esc(column) + '</th>').join('') + '</tr></thead>'
        + '<tbody>' + rows.map(row =>
            '<tr' + (state.errorRows && state.errorRows.has(row) ? ' class="row-error"' : '') + '>'
            + state.columns.map(column =>
                '<td>' + AC.esc(cellText(row, column)) + '</td>').join('') + '</tr>').join('') + '</tbody></table>'
        + '</body></html>';

    const win = window.open('', '_blank');
    if (!win) { addError('The browser blocked the new tab — allow pop-ups to view a grid as HTML.'); return; }
    win.document.write(html);
    win.document.close();
}

function fileName(title, extension) {
    const base = (title || 'grid').replace(/[^\w.\- ]+/g, '_').trim() || 'grid';
    return base + '-' + new Date().toISOString().slice(0, 10) + '.' + extension;
}

// ── Keeping a grid's rows as a static dataset ────────────────────────────
// An export leaves the rows in a file on one person's machine. This leaves them in the dataset
// library under a name, where the pages, dropdowns and lookups that read datasets can name them
// — the way to turn "what this call returned today" into a list the next run can work against.
//
// The rows saved are the rows on screen: filters, the pinned slice, the errors-only tick and the
// sort, exactly as both exports and Analyze take them. Saved as a pasted dataset, since its rows
// came from a run rather than from anywhere that could be loaded again.

/**
 * Serialises rows to the tab-separated text a pasted dataset stores, header row first — the same
 * shape someone pasting a block of a spreadsheet into the dataset library produces. Object cells
 * are written as JSON, which is what {@link #cellText} already does for every other way these
 * rows leave the page.
 *
 * <p>Line breaks inside a value always go, since one would otherwise start a new row. Which
 * other character has to go depends on how many columns there are, because the library splits a
 * pasted block on the first of tab, comma or pipe that its header line holds: two columns or
 * more always put a tab there, so a tab is the only thing that could move a value into the wrong
 * cell. One column puts none of the three there — so the single name is kept clear of comma and
 * pipe, which settles the split on pipe, and pipes go from the values, which would otherwise be
 * cut short at the first one. Commas survive either way, being the one of the three that turns
 * up in real values.
 */
function toPasteText(columns, rows) {
    const single = columns.length < 2;
    const flat = (value, pattern) =>
        String(value === undefined || value === null ? '' : value).replace(pattern, ' ');
    const lines = [columns.map(column => flat(column, single ? /[\t\r\n,|]+/g : /[\t\r\n]+/g)).join('\t')];
    rows.forEach(row => lines.push(columns
        .map(column => flat(cellText(row, column), single ? /[\t\r\n|]+/g : /[\t\r\n]+/g)).join('\t')));
    return lines.join('\n');
}

/**
 * Whether the library already holds {@code name}, and what it holds — so the operator is warned
 * with the thing they would be replacing rather than with a bare "are you sure".
 *
 * <p>Asked with fetch rather than {@link AC#api} on purpose: "no such dataset" comes back as a
 * 404, which is the answer here and not a failure, and api() cannot tell it from one.
 *
 * @return the existing dataset's summary, null when the name is free, and a thrown Error when
 *         the library could not be asked — which must not be read as "the name is free".
 */
async function existingDataset(name) {
    const res = await fetch('/staticdataset/' + encodeURIComponent(name));
    if (res.status === 404) return null;
    if (!res.ok) throw new Error('could not check whether "' + name + '" is taken (HTTP ' + res.status + ')');
    return await res.json();
}

async function saveGridAsDataset(gridId) {
    const state = gridState[gridId];
    if (!state) return;
    if (!state.columns.length) {
        AC.setStatus('runStatus', 'There is nothing to save — this grid has no columns yet.', 'error');
        return;
    }
    const rows = visibleRows(state);

    const suggested = ((state.title || 'grid').replace(/[^\w-]+/g, '-').replace(/^-+|-+$/g, '') || 'grid')
        + '-' + new Date().toISOString().slice(0, 10);
    const raw = prompt('Keep the ' + rows.length.toLocaleString() + ' row'
        + (rows.length === 1 ? '' : 's') + ' shown as a static dataset.\n\nDataset name:', suggested);
    if (raw === null) return;
    const name = raw.trim();
    if (!name) return;
    // The same names the dataset library itself accepts: the name goes in a URL path and is
    // typed back into every control that reads the dataset.
    if (!/^[\w-]+$/.test(name)) {
        AC.setStatus('runStatus', 'A dataset name can hold only letters, digits, _ or -.', 'error');
        return;
    }

    AC.setStatus('runStatus', 'Saving ' + rows.length.toLocaleString() + ' row'
        + (rows.length === 1 ? '' : 's') + ' as "' + name + '"…');
    try {
        const existing = await existingDataset(name);
        if (existing && !confirm('A dataset named "' + name + '" already exists — '
                + String(existing.source || '').toUpperCase() + ', '
                + (existing.count || 0).toLocaleString() + ' row'
                + ((existing.count || 0) === 1 ? '' : 's') + '.\n\n'
                + 'Replace what it holds with these ' + rows.length.toLocaleString() + ' row'
                + (rows.length === 1 ? '' : 's') + '? Everything that reads it will read these '
                + 'instead, and where it loaded from is forgotten.')) {
            AC.setStatus('runStatus', 'Nothing saved — "' + name + '" was left as it was.');
            return;
        }

        const body = { name: name, source: 'paste', location: toPasteText(state.columns, rows), arrayElement: null };
        const saved = existing
            ? await AC.api('PUT', '/staticdataset/' + encodeURIComponent(name), body)
            : await AC.api('POST', '/staticdataset', body);

        // The library this page read as it opened, and the rows it has already fetched from it,
        // are both a version behind now — a control sourced from this dataset would otherwise
        // keep offering what it held before the overwrite for as long as the page stays open.
        try { datasets = await AC.api('GET', '/staticdataset'); } catch (e) { /* the save stands */ }
        if (datasetCache) datasetCache.delete(name);

        const count = saved && saved.count !== undefined ? saved.count : rows.length;
        AC.setStatus('runStatus', (existing ? 'Replaced "' : 'Saved "') + name + '" — '
            + Number(count).toLocaleString() + ' row' + (Number(count) === 1 ? '' : 's') + '.'
            + (saved && saved.error ? ' ' + saved.error : ''),
            saved && saved.error ? 'error' : 'ok');
    } catch (e) {
        AC.setStatus('runStatus', 'Could not save "' + name + '": ' + e.message, 'error');
    }
}

// ── Analyzing a grid ─────────────────────────────────────────────────────
// Rows are one shape for an answer and a poor one for a question like "how many breaks per desk
// per day". Analyze opens gridanalyzer.html on the rows the operator can currently see —
// filters and sort included, exactly like both exports — and that screen pivots them: any
// column down the side, any column across the top, and sum, count, unique, average, min or max
// on any column in the cells.
//
// The rows go over by postMessage rather than in the URL or in storage: a grid here routinely
// runs to tens of thousands of rows, which fits in neither, and a structured clone hands the
// objects over without ever serialising them to text. The analyzer cannot be handed anything
// until its document exists, so it asks — quoting the token it was opened under, since several
// grids may be being analyzed at once.

/** Rows waiting for the analyzer window that was opened for them, by handover token. */
const analyzerHandoffs = new Map();
let analyzerCount = 0;

function analyzeGrid(gridId) {
    const state = gridState[gridId];
    if (!state) return;
    const token = 'ga-' + (++analyzerCount) + '-' + Date.now();
    const win = window.open('gridanalyzer.html?t=' + encodeURIComponent(token), '_blank');
    if (!win) { addError('The browser blocked the new tab — allow pop-ups to analyze a grid.'); return; }
    analyzerHandoffs.set(token, {
        title: state.title || 'Grid',
        columns: state.columns.slice(),
        rows: visibleRows(state),
        page: analyzerPageInfo(gridId)
    });
    // A window that never asks — blocked, closed, or navigated away from — would otherwise leave
    // its rows held here for as long as the page is open.
    setTimeout(() => analyzerHandoffs.delete(token), 60000);
}

// ── Adding an analysis to the page ───────────────────────────────────────
// The analyzer's "Add to page as action": a page action that is the action which filled the grid
// analyzed — the same instance, inputs and reading of the response — with the analyzer's pivot on
// it and the grid chosen there as its target. It is attached to every trigger the original is
// attached to, so the two go out in the same trigger and share one call through the call cache.

/**
 * What the analyzer is told about where its rows came from, when an analysis of them can be added
 * back: null for a grid no action filled, and for one whose action already groups its rows —
 * those rows are a pivot's output, and pivoting the call again over them would not reproduce it.
 */
function analyzerPageInfo(gridId) {
    const state = gridState[gridId];
    const filler = state && state.filledBy;
    if (!filler || GridPivot.isActive(filler.pivot)) return null;
    const original = filler.bindingOf || filler;
    return {
        gridId: gridId,
        actionId: original.actionId,
        actionLabel: original.actionLabel || original.appUseCaseInstanceId || 'Untitled action',
        grids: page.controls.filter(c => c.type === 'grid')
            .map(c => ({ controlId: c.controlId, title: controlTitle(c) })),
        saved: !!savedPageName,
        pageName: savedPageName || page.pageName || ''
    };
}

/**
 * Adds the analyzer's pivot to the page as an action and reports what it did.
 *
 * @return a message for the analyzer; throws with the reason when nothing was added
 */
async function addAnalysisAction(message) {
    const state = gridState[message.gridId];
    const filler = state && state.filledBy;
    if (!filler) throw new Error('The grid analyzed has since been cleared or refilled — run the page again and re-open Analyze.');
    if (!GridPivot.isActive(message.pivot)) throw new Error('The analysis groups nothing yet.');

    const target = message.targetControlId;
    const targetControl = target === NEW_GRID ? null : findControl(target);
    if (target !== NEW_GRID && (!targetControl || targetControl.type !== 'grid')) {
        throw new Error('The grid chosen to show the result is no longer on this page.');
    }
    if (target === message.gridId) {
        throw new Error('The result cannot go into the grid it was analyzed from — the next run would group the grouped table.');
    }

    const original = filler.bindingOf || filler;
    // A further target has already been laid over its action (see #bindingsOf), so either way
    // the filler reads as one complete action; cloned without the link back to its original.
    const copy = cloneValue(Object.assign({}, filler, { bindingOf: undefined }));
    copy.actionId = newActionId();
    copy.actionLabel = uniqueLabel((message.label || '').trim() || (original.actionLabel || 'Action') + ' — analysis',
        allActions().map(a => a.actionLabel || ''));
    copy.targetControlId = target;
    copy.extraBindings = [];
    copy.pivot = message.pivot;
    // A pivot is a new reading of the one response, not a reason to send it twice.
    copy.ownCall = false;
    // A tab per row has no one grid to group; this collects into the grid chosen instead.
    if (copy.rowOutputMode === 'TABS') copy.rowOutputMode = 'ROWS';
    hydrateAction(copy);
    page.actions = page.actions || [];
    page.actions.push(copy);

    // Wherever the original is run from, this runs too.
    const attachedTo = [];
    const inLibrary = (page.actions || []).some(a => a.actionId === original.actionId);
    page.controls.forEach(c => {
        const runsIt = (inLibrary && (c.actionIds || []).includes(original.actionId))
            || (c.actions || []).some(a => a.actionId === original.actionId);
        if (runsIt) {
            c.actionIds = (c.actionIds || []).concat([copy.actionId]);
            attachedTo.push(controlTitle(c));
        }
        (c.columnLinks || []).forEach(link => {
            if ((link.actionIds || []).includes(original.actionId)) {
                link.actionIds = link.actionIds.concat([copy.actionId]);
                attachedTo.push(controlTitle(c) + ' · ' + link.column);
            }
        });
        if (c.rowClick && (c.rowClick.actionIds || []).includes(original.actionId)) {
            c.rowClick.actionIds = c.rowClick.actionIds.concat([copy.actionId]);
            attachedTo.push(controlTitle(c) + ' · row');
        }
    });
    if ((page.onLoadActionIds || []).includes(original.actionId)) {
        page.onLoadActionIds = page.onLoadActionIds.concat([copy.actionId]);
        attachedTo.push('page load');
    }

    const where = target === NEW_GRID ? 'a new grid each run' : '"' + controlTitle(targetControl) + '"';
    let said = 'Added "' + copy.actionLabel + '", filling ' + where
        + (attachedTo.length ? ', run by ' + attachedTo.join(', ') : ' — attached to nothing yet') + '.';

    if (message.save) {
        await savePage();
        const saved = (page.actions || []).some(a => a.actionId === copy.actionId);
        const status = document.getElementById('statusBar');
        if (!saved || (status && status.classList.contains('error'))) {
            throw new Error('Added, but the page did not save: ' + ((status && status.textContent) || 'unknown error')
                + ' — open the designer to put it right.');
        }
        said += ' Page saved.';
    } else {
        said += ' Save the page from the designer to keep it.';
    }

    if (message.runNow && mode === 'run') {
        // Looked up again: saving hands back a fresh copy of the page.
        const added = (page.actions || []).find(a => a.actionId === copy.actionId) || copy;
        clearActionTargets([added], null);
        runActions([added], added.actionLabel, null, false);
        said += ' Running it now.';
    }
    AC.setStatus('runStatus', said, 'ok');
    return said;
}

window.addEventListener('message', async event => {
    if (event.origin !== location.origin) return;
    const message = event.data;
    if (!message || message.type !== 'grid-analyzer-add-action') return;
    const reply = (ok, text) => event.source && event.source.postMessage({ type: 'grid-analyzer-add-action-result',
        token: message.token, requestId: message.requestId, ok: ok, message: text }, location.origin);
    try {
        reply(true, await addAnalysisAction(message));
    } catch (e) {
        reply(false, e.message || String(e));
    }
});

window.addEventListener('message', event => {
    if (event.origin !== location.origin) return;
    const message = event.data;
    if (!message || message.type !== 'grid-analyzer-ready') return;
    const payload = analyzerHandoffs.get(message.token);
    if (!payload) return;
    analyzerHandoffs.delete(message.token);
    event.source.postMessage({ type: 'grid-analyzer-data', token: message.token, payload: payload }, location.origin);
});

// ── The technical details of the last trigger ────────────────────────────
// A page hides the calls behind it on purpose: the operator presses a button and gets rows. The
// moment something is wrong, that is exactly the wrong shape — the question stops being "what
// does the order say" and becomes "what did we send, where, and what came back". This lays every
// call the last trigger made out in full, one section per action, and hands the whole thing over
// as a standalone HTML file, because the person who can answer the question is usually not the
// person looking at the page.

/** Header names whose value is a credential rather than a detail. Masked unless asked for. */
const SECRET_HEADERS = ['authorization', 'proxy-authorization', 'cookie', 'set-cookie',
                        'x-api-key', 'api-key', 'x-auth-token'];

/**
 * Above this many characters a body renders truncated. A browser stalls long before a 30 MB
 * response is laid out, and nobody reads one in a panel anyway — the point here is the first
 * screenful, which is where the error message lives.
 */
const BODY_RENDER_LIMIT = 200000;

/**
 * The look of the report, written once and used twice: injected into this page so the panel can
 * use it, and inlined into the document the panel exports. One stylesheet rather than two, so
 * what someone is sent is what the operator was looking at rather than an approximation of it.
 */
const TECH_CSS = [
    '.tech-doc { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;',
    '            color: #172b4d; background: #fff; margin: 0; padding: 24px; }',
    '.tech-report { font-size: 13px; }',
    '.tech-report h1 { font-size: 17px; font-weight: 600; margin: 0 0 4px; }',
    '.tech-report .tech-when { font-size: 12px; color: #5e6c84; margin: 0 0 14px; }',
    '.tech-wrap { overflow-x: auto; }',
    '.tech-table { width: 100%; border-collapse: collapse; font-size: 12px; }',
    '.tech-table th, .tech-table td { border: 1px solid #dfe1e6; padding: 5px 8px; text-align: left; vertical-align: top; }',
    '.tech-table th { background: #f4f5f7; font-weight: 600; white-space: nowrap; }',
    '.tech-table tbody tr:nth-child(even) td { background: #fafbfc; }',
    '.tech-table .mono { font-family: "Cascadia Code", Consolas, monospace; word-break: break-all; }',
    '.tech-table.kv td:first-child { width: 190px; font-weight: 600; color: #5e6c84; }',
    '.tech-table.kv td { word-break: break-word; }',
    '.tech-call { border: 1px solid #dfe1e6; border-radius: 5px; margin-top: 14px; padding: 12px; background: #fff; }',
    '.tech-call h2 { font-size: 13px; font-weight: 600; margin: 0 0 10px;',
    '                display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }',
    '.tech-num { font-size: 10px; font-weight: 700; color: #fff; background: #0052cc; border-radius: 9px; padding: 1px 7px; }',
    '.tech-block { margin-top: 10px; }',
    '.tech-block h3 { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: .4px;',
    '                 color: #5e6c84; margin: 0 0 5px; display: flex; align-items: baseline; gap: 8px; }',
    '.tech-size { font-size: 10px; font-weight: 500; text-transform: none; letter-spacing: 0; color: #97a0af; }',
    '.tech-body { font-family: "Cascadia Code", Consolas, monospace; font-size: 11px;',
    '             background: #f7f8f9; border: 1px solid #e4e6ea; border-radius: 3px; padding: 8px;',
    '             margin: 0; max-height: 340px; overflow: auto; white-space: pre-wrap; word-break: break-word; }',
    '.tech-muted { font-size: 12px; color: #97a0af; font-style: italic; margin: 0; }',
    '.tech-err { color: #bf2600; font-style: normal; }',
    '.tech-badge { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .3px;',
    '              padding: 1px 6px; border-radius: 8px; flex: none; }',
    '.tech-badge.ok  { background: #e3fcef; color: #006644; }',
    '.tech-badge.err { background: #ffebe6; color: #bf2600; }',
    // Only ever set on the page: an export is the whole report, and one section of a saved file
    // outlined for a reason the reader was not there for would only puzzle them.
    '.tech-call.tech-focus { border-color: #0052cc; box-shadow: 0 0 0 2px rgba(0,82,204,.18); }',
    '.tech-note { font-size: 11px; color: #97a0af; margin: 14px 0 0; }',
    // The panel is the report inside the editor dialog, given the width a URL and a JSON body
    // need. Only the dialog is page-only; everything above travels with the export.
    '.tech-box { width: min(1100px, 100%); }',
    '.tech-box .editor-head button { flex: none; }',
    '.tech-secrets { display: flex; align-items: center; gap: 6px; font-size: 12px; color: #5e6c84; flex: none; }',
    '@media print { .tech-body { max-height: none; } .tech-call { break-inside: avoid; } }'
].join('\n');

// ── The panel ────────────────────────────────────────────────────────────

/**
 * @param focus which call to open on, when the panel was opened from a particular failure rather
 *              than from the toolbar. Out of range is treated as no focus: the report is still
 *              the right thing to be looking at, and refusing to open it would leave the person
 *              who asked with nothing.
 */
function showTechDetails(focus) {
    if (!lastRun || !lastRun.calls.length) return;
    const on = (focus === undefined || focus === null || !lastRun.calls[focus]) ? null : focus;
    techPanel = { secrets: false, focus: on, scrolled: false };
    renderTechPanel();
}

function closeTechDetails() {
    techPanel = null;
    const host = document.getElementById('detailsHost');
    if (host) host.innerHTML = '';
}

/**
 * Credentials are off every time the panel opens rather than remembered, because the button
 * beside this one writes a file that gets mailed to someone. Turning them on is a decision
 * about that file, and a decision like that should be taken again each time.
 */
function toggleTechSecrets(on) {
    if (!techPanel) return;
    techPanel.secrets = on;
    renderTechPanel();
}

function renderTechPanel() {
    const host = document.getElementById('detailsHost');
    if (!host) return;
    if (!techPanel || !lastRun) { host.innerHTML = ''; return; }

    host.innerHTML = '<div class="editor-modal" onclick="if (event.target === this) closeTechDetails()">'
        + '<div class="editor-box tech-box">'
            + '<div class="editor-head">'
                + '<span class="editor-title">Technical Details · ' + AC.esc(oneLine(lastRun.label || 'Last trigger')) + '</span>'
                + '<button class="tool-btn" onclick="openTechHtml()" title="Open this report in its own tab, as plain HTML">Open as HTML</button>'
                + '<button class="tool-btn" onclick="downloadTechHtml()" title="Save it as a self-contained HTML file to send on">Download</button>'
                + '<button class="tool-btn" onclick="copyTechHtml()" title="Copy the whole HTML document to the clipboard">Copy</button>'
                + '<button class="icon-btn" onclick="closeTechDetails()" title="Close">×</button>'
            + '</div>'
            + '<div class="editor-body" id="techBody">' + techReport(false) + '</div>'
            + '<div class="editor-foot">'
                + '<label class="tech-secrets" title="Off, an Authorization header or a JWT is shown as its scheme alone. '
                    + 'This report is meant to be sent to someone, and a live token is not a technical detail worth mailing.">'
                    + '<input type="checkbox"' + (techPanel.secrets ? ' checked' : '')
                    + ' onchange="toggleTechSecrets(this.checked)"> Show credentials</label>'
                + '<span id="techStatus" class="status-bar"></span>'
            + '</div>'
        + '</div>'
    + '</div>';

    // Opened from one failure: that call is outlined and brought into view, so a trigger with six
    // sections opens on the one that was asked about rather than at the top of a report the
    // reader then has to search. Scrolled once only — turning credentials on or fetching a body
    // redraws this, and dragging the panel back up under someone reading it would be rude.
    if (techPanel.focus !== null) {
        const section = host.querySelectorAll('.tech-call')[techPanel.focus];
        if (section) {
            section.classList.add('tech-focus');
            if (!techPanel.scrolled) { section.scrollIntoView({ block: 'start' }); techPanel.scrolled = true; }
        }
    }
}

// ── The report itself ────────────────────────────────────────────────────

/**
 * Every call the last trigger made: a table across the top to see them against each other, then
 * one section per action with the whole of what went out and what came back.
 *
 * @param forExport swaps the panel's buttons for what they would have fetched. The document this
 *                  produces has no page behind it, so anything that would have called back to
 *                  this server has to read as a statement of fact instead.
 */
function techReport(forExport) {
    const calls = lastRun ? lastRun.calls : [];
    const masked = !(techPanel && techPanel.secrets);
    return '<div class="tech-report">'
        + '<h1>' + AC.esc(page.title || page.pageName || 'Untitled page') + '</h1>'
        + '<p class="tech-when">' + AC.esc(lastRun ? (lastRun.label || 'Trigger') : 'Nothing has run')
            + ' · ' + calls.length + ' call' + (calls.length === 1 ? '' : 's')
            + ' · ' + AC.esc(lastRun ? new Date(lastRun.at).toLocaleString() : '') + '</p>'
        + techSummaryTable(calls)
        + calls.map((call, i) => techCallSection(call, i, forExport)).join('')
        + (masked ? '<p class="tech-note">Authorization, cookie and API-key headers are shown masked, '
            + 'as is any JWT this run fetched. Tick "Show credentials" before exporting if whoever '
            + 'receives this is meant to replay the call.</p>' : '')
        // Said once at the top as well as in each empty body block, because the first question
        // somebody handed this report asks is why half of it is missing, and the answer is a
        // setting on the page rather than anything that went wrong with the run.
        + (calls.some(call => call.result && call.result.bodiesDropped)
            ? '<p class="tech-note">This page has <code>${DEBUG}</code> set to false, so its requests '
                + 'and responses are not kept. Every call is still reported — where it went, what it '
                + 'answered, how long it took, how big it was and its headers — with the bodies '
                + 'themselves left out.</p>' : '')
        + '</div>';
}

/** The calls against each other — which one failed, where it went, how long it took. */
function techSummaryTable(calls) {
    const rows = calls.map((call, i) => {
        const m = call.result || {};
        return '<tr>'
            + '<td>' + (i + 1) + '</td>'
            + '<td>' + AC.esc(call.name) + '</td>'
            + '<td>' + AC.esc(m.httpMethod || '') + '</td>'
            + '<td class="mono">' + AC.esc(m.url || '') + '</td>'
            + '<td>' + techOutcome(call) + '</td>'
            + '<td>' + AC.esc(m.statusCode === undefined || m.statusCode === null ? '' : m.statusCode) + '</td>'
            + '<td>' + AC.esc(m.timeTaken === undefined || m.timeTaken === null ? '' : m.timeTaken + ' ms') + '</td>'
            + '<td>' + AC.esc(formatBytes(techSize(m.requestBodySize, m.requestBody))) + '</td>'
            + '<td>' + AC.esc(formatBytes(techSize(m.responseBodySize, m.responseBody))) + '</td>'
            + '</tr>';
    }).join('');
    return '<div class="tech-wrap"><table class="tech-table"><thead><tr>'
        + ['#', 'Action', 'Method', 'URL', 'Outcome', 'Code', 'Time', 'Request', 'Response']
            .map(head => '<th>' + head + '</th>').join('')
        + '</tr></thead><tbody>' + rows + '</tbody></table></div>';
}

/**
 * One action in full. The order is the order a call is read in: what was sent, then what came
 * back, then — if the page could not use it — why.
 */
function techCallSection(call, index, forExport) {
    const m = call.result || {};
    // A performance action reads this server's own run history, so there is no request line, no
    // response and no status code — only what it was asked and whether it answered. Saying that
    // plainly beats an empty call section that looks like one that failed to record itself.
    if (call.performance) {
        return '<section class="tech-call">'
            + '<h2><span class="tech-num">' + (index + 1) + '</span>' + AC.esc(call.name)
            + '<span class="tech-badge ' + (call.error ? 'err' : 'ok') + '">'
            + (call.error ? 'failed' : 'summary') + '</span></h2>'
            + '<p class="tech-muted">Summarised from this server' + Q + 's own run history — no call was made, '
            + 'so there is no request or response to show.</p>'
            + techKeyValueBlock('Filters Applied', call.inputs)
            + (call.error ? '<div class="tech-block"><h3>What Went Wrong</h3>'
                + '<p class="tech-muted tech-err">' + AC.esc(call.error) + '</p></div>' : '')
            + '</section>';
    }
    // A dataset action reads the list this server already holds, so — as with a summary — there is
    // no request line, no response and no status code. What there is worth showing is which dataset
    // and what it was narrowed by, which is the whole of what produced the rows.
    if (call.dataset) {
        return '<section class="tech-call">'
            + '<h2><span class="tech-num">' + (index + 1) + '</span>' + AC.esc(call.name)
            + '<span class="tech-badge ' + (call.error ? 'err' : 'ok') + '">'
            + (call.error ? 'failed' : 'dataset') + '</span></h2>'
            + '<p class="tech-muted">Read from static dataset <b>' + AC.esc(call.datasetName || 'not chosen') + '</b> — '
            + 'no call was made, so there is no request or response to show.</p>'
            + techKeyValueBlock('Filter Applied', call.inputs)
            + (call.error ? '<div class="tech-block"><h3>What Went Wrong</h3>'
                + '<p class="tech-muted tech-err">' + AC.esc(call.error) + '</p></div>' : '')
            + '</section>';
    }
    // A comparison that got as far as sending anything replaced this entry with one per side, so
    // seeing it still marked as a comparison means it never sent: its two environments could not
    // be worked out from the page. There are no calls to show, and saying that beats an empty
    // call section that looks like one which failed to record itself.
    if (call.compare) {
        return '<section class="tech-call">'
            + '<h2><span class="tech-num">' + (index + 1) + '</span>' + AC.esc(call.name)
            + '<span class="tech-badge err">not sent</span></h2>'
            + '<p class="tech-muted">A comparison of two environments that never went out, so there is no '
            + 'request or response to show for either side.</p>'
            + (call.error ? '<div class="tech-block"><h3>What Went Wrong</h3>'
                + '<p class="tech-muted tech-err">' + AC.esc(call.error) + '</p></div>' : '')
            + '</section>';
    }
    return '<section class="tech-call">'
        + '<h2><span class="tech-num">' + (index + 1) + '</span>' + AC.esc(call.name) + techOutcome(call)
            + (!forExport && techBodiesWithheld(call)
                ? '<button class="tool-btn" onclick="fetchTechBodies(' + index + ')" '
                    + 'title="This action only asked for metadata, so its bodies stayed on the server. Pull them back.">'
                    + 'Fetch bodies</button>' : '')
        + '</h2>'
        + techFacts(call)
        + techKeyValueBlock('Inputs Sent', call.inputs)
        + techHeaderBlock('Request Headers', m.requestHeaders)
        + techBodyBlock('Request Body', m.requestBody, techSize(m.requestBodySize, m.requestBody),
                forExport, m.bodiesDropped)
        + techHeaderBlock('Response Headers', m.responseHeaders)
        + techBodyBlock('Response Body', m.responseBody, techSize(m.responseBodySize, m.responseBody),
                forExport, m.bodiesDropped)
        + (call.error ? '<div class="tech-block"><h3>What Went Wrong</h3>'
            + '<p class="tech-muted tech-err">' + AC.esc(call.error) + '</p></div>' : '')
        + '</section>';
}

/**
 * What the call was, as a badge. The HTTP outcome and whether the page could use it are two
 * different questions and both get answered: a 200 whose response no path could be read out of
 * is a success that produced nothing, and reporting it as either alone would mislead.
 */
function techOutcome(call) {
    const status = (call.result && call.result.status) || 'ERROR';
    const ok = status === 'SUCCESS';
    return '<span class="tech-badge ' + (ok ? 'ok' : 'err') + '">' + AC.esc(status.toLowerCase()) + '</span>'
        + (ok && call.error ? '<span class="tech-badge err" title="The call came back, but the page could not '
            + 'bind what it wanted out of it.">not bound</span>' : '');
}

/** The run's own record: the request line first, then everything that identifies the call. */
function techFacts(call) {
    const m = call.result || {};
    const facts = [
        ['Request', ((m.httpMethod || '') + ' ' + (m.url || '')).trim(), true],
        ['Status', m.status],
        ['Status code', m.statusCode],
        ['Time taken', (m.timeTaken === undefined || m.timeTaken === null) ? '' : m.timeTaken + ' ms'],
        ['App', m.appName],
        ['Environment', m.environment],
        ['Env class', m.envClass],
        ['Use case', m.useCase],
        ['Instance', m.instanceLabel || call.instanceId],
        ['Environment override', call.environment],
        ['Executed via', m.executedVia],
        ['Started', m.startedAt ? new Date(m.startedAt).toLocaleString() : ''],
        ['Execution id', m.executionId, true],
        ['Unresolved variables', (m.unresolvedVariables || []).join(', ')],
        ['JWT token', techMask(m.jwtToken), true]
    ];
    const rows = facts.map(([label, value, mono]) =>
        (value === undefined || value === null || value === '') ? ''
            : '<tr><td>' + AC.esc(label) + '</td><td' + (mono ? ' class="mono"' : '') + '>'
                + AC.esc(value) + '</td></tr>').filter(Boolean).join('');
    return '<div class="tech-block"><h3>Call</h3>'
        + '<div class="tech-wrap"><table class="tech-table kv"><tbody>' + rows + '</tbody></table></div></div>';
}

/**
 * One header set as a name/value table. A request header arrives as a plain string and a
 * response header as a list, since a name may repeat there; both read the same way once joined.
 */
function techHeaderBlock(title, headers) {
    const names = headers ? Object.keys(headers) : [];
    if (!names.length) return '';
    const pairs = {};
    names.forEach(name => {
        const raw = headers[name];
        pairs[name] = Array.isArray(raw) ? raw.join(', ')
            : String(raw === undefined || raw === null ? '' : raw);
    });
    return techKeyValueBlock(title, pairs, true);
}

/**
 * A flat map as a two-column grid — headers, and the inputs the page resolved. Sorted by name so
 * two calls' header sets can be read against each other rather than in whatever order they
 * happened to arrive.
 */
function techKeyValueBlock(title, map, secrets) {
    const names = map ? Object.keys(map) : [];
    if (!names.length) return '';
    const rows = names.slice().sort((a, b) => a.localeCompare(b)).map(name => {
        const raw = map[name];
        const value = (raw === undefined || raw === null) ? ''
            : (typeof raw === 'object' ? AC.prettyJson(raw) : String(raw));
        return '<tr><td>' + AC.esc(name) + '</td><td class="mono">'
            + AC.esc(secrets ? techSecretValue(name, value) : value) + '</td></tr>';
    }).join('');
    return '<div class="tech-block"><h3>' + AC.esc(title) + '<span class="tech-size">'
            + names.length + '</span></h3>'
        + '<div class="tech-wrap"><table class="tech-table kv"><tbody>' + rows + '</tbody></table></div></div>';
}

/**
 * One body. Present, it is printed — pretty-printed when it is JSON small enough to be worth
 * reformatting, and truncated past what a browser lays out happily. Absent, it says which of the
 * three absences it is: there was nothing to send; this action only asked for the metadata, so
 * the bodies were deliberately left on the server and can be pulled back (see
 * {@link #fetchTechBodies}); or the page has its DEBUG switch off and nothing kept them at all.
 *
 * <p>The last is worth spelling out rather than showing as an empty block. A body that is gone
 * because somebody turned the detail off is not a body that went missing, and whoever is reading
 * the report — very likely not whoever turned it off — should be told which it is.
 */
function techBodyBlock(title, body, size, forExport, dropped) {
    const text = (body === undefined || body === null) ? '' : String(body);
    const head = '<div class="tech-block"><h3>' + AC.esc(title);

    if (!text) {
        return head + (size ? '<span class="tech-size">' + AC.esc(formatBytes(size)) + '</span>' : '') + '</h3>'
            + '<p class="tech-muted">' + (!size ? 'Empty.' : dropped
                ? 'Not kept — this page has <code>${DEBUG}</code> set to false, so the call was made, bound '
                    + 'and let go. The size above is what actually went over the wire. Turn DEBUG back on in '
                    + 'the page' + Q + 's variables and trigger it again to read the body itself.'
                : 'Left on the server — this action read the call\'s metadata, so its bodies were never sent '
                    + 'to the page.' + (forExport ? '' : ' Use "Fetch bodies" above.')) + '</p></div>';
    }

    const pretty = text.length <= BODY_RENDER_LIMIT ? techPretty(text) : text;
    const shown = pretty.length > BODY_RENDER_LIMIT ? pretty.slice(0, BODY_RENDER_LIMIT) : pretty;
    return head + '<span class="tech-size">' + AC.esc(formatBytes(text.length)) + '</span></h3>'
        + '<pre class="tech-body">' + AC.esc(shown) + '</pre>'
        + (shown.length < pretty.length
            ? '<p class="tech-muted">Shown to the first ' + AC.esc(formatBytes(BODY_RENDER_LIMIT))
                + ' — the rest is on the execution itself.</p>' : '')
        + '</div>';
}

/** JSON laid out to be read; anything else exactly as it went over the wire. */
function techPretty(text) {
    try { return JSON.stringify(JSON.parse(text), null, 2); } catch (e) { return text; }
}

/** A body's length: what the server reported when it dropped the body, what is there otherwise. */
function techSize(reported, body) {
    if (reported !== undefined && reported !== null) return reported;
    return body ? String(body).length : 0;
}

/** Whether this call's bodies are on the server rather than on the page, and can be pulled back. */
function techBodiesWithheld(call) {
    const m = call.result;
    if (!m || !m.executionId) return false;
    // Dropped is not withheld. A DEBUG-off run told the server not to file itself away either,
    // so there is nothing at the far end of that button — see #runDetail.
    if (m.bodiesDropped) return false;
    return (!m.requestBody && techSize(m.requestBodySize, null) > 0)
        || (!m.responseBody && techSize(m.responseBodySize, null) > 0);
}

/**
 * Pulls back the bodies a metadata action told the server not to send. Fetched a call at a time
 * and only when asked: not shipping a 30 MB response is the whole point of a metadata action,
 * and undoing that for every call the moment this panel opens would undo it too.
 *
 * <p>The record is replaced rather than edited, since two actions over the same endpoint share
 * one response object and only the one that was asked about should change.
 */
async function fetchTechBodies(index) {
    const call = lastRun && lastRun.calls[index];
    if (!call || !call.result || !call.result.executionId) return;
    AC.setStatus('techStatus', 'Fetching the bodies…');
    try {
        const full = await AC.api('GET', '/appcatalog/executions/' + encodeURIComponent(call.result.executionId));
        call.result = Object.assign({}, call.result, {
            requestBody: full.requestBody,
            responseBody: full.responseBody,
            requestHeaders: full.requestHeaders || call.result.requestHeaders,
            responseHeaders: full.responseHeaders || call.result.responseHeaders
        });
        renderTechPanel();
        // Said after the redraw, which builds the bar this writes into.
        AC.setStatus('techStatus', (full.requestBody || full.responseBody)
            ? 'Bodies fetched.' : 'The server no longer holds this run\'s bodies.', 'ok');
    } catch (e) {
        AC.setStatus('techStatus', 'Could not fetch the bodies: ' + e.message, 'error');
    }
}

/**
 * A credential as it should appear. Masked to its scheme — "Bearer ••••••••" answers most of
 * what anyone wants to know from it — unless the operator has explicitly asked otherwise.
 * Applied here rather than where it is displayed, so the exported file cannot diverge from the
 * screen it was exported from.
 */
function techMask(value) {
    if (!value || (techPanel && techPanel.secrets)) return value || '';
    const space = String(value).indexOf(' ');
    return (space > 0 && space < 12 ? String(value).slice(0, space + 1) : '') + '••••••••';
}

function techSecretValue(name, value) {
    return SECRET_HEADERS.includes(String(name).toLowerCase()) ? techMask(value) : value;
}

// ── Taking the report elsewhere ──────────────────────────────────────────

/**
 * The report as a document that stands on its own — the same markup and the same stylesheet,
 * with nothing behind it. This is the thing that gets attached to a mail: whoever opens it needs
 * no access to this server, and it says what was sent and what came back without them having to
 * reproduce the click that produced it.
 */
function techDocument() {
    const title = 'Technical details · ' + (page.title || page.pageName || 'page');
    return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
        + '<title>' + AC.esc(title) + '</title><style>' + TECH_CSS + '</style></head>'
        + '<body class="tech-doc">' + techReport(true) + '</body></html>';
}

function openTechHtml() {
    const win = window.open('', '_blank');
    if (!win) {
        AC.setStatus('techStatus', 'The browser blocked the new tab — allow pop-ups to open the report as HTML.', 'error');
        return;
    }
    win.document.write(techDocument());
    win.document.close();
}

function downloadTechHtml() {
    download(fileName((page.pageName || page.title || 'page') + '-technical-details', 'html'),
             'text/html;charset=utf-8', techDocument());
    AC.setStatus('techStatus', 'Saved.', 'ok');
}

async function copyTechHtml() {
    try {
        await navigator.clipboard.writeText(techDocument());
        AC.setStatus('techStatus', 'Copied — paste it into a file or a mail.', 'ok');
    } catch (e) {
        AC.setStatus('techStatus', 'Could not copy: ' + e.message, 'error');
    }
}

// ── Keyboard ─────────────────────────────────────────────────────────────

/**
 * The layout keys. Dragging is how a control is placed; these are how it is placed exactly —
 * lining two fields up to the column is something a mouse is bad at, and the arrow keys do what
 * typing into the row and column boxes does, through the same setter and the same clamping.
 *
 * <p>Design mode only, with something selected, and never while the caret is in a box: an arrow
 * key inside a text field moves the caret and Backspace deletes a character, and neither is this.
 * Nothing fires while an editor is open over the page either — that dialog has the keyboard.
 */
document.addEventListener('keydown', e => {
    if (mode !== 'design' || editor || !selectedId) return;
    if (e.target && e.target.closest && e.target.closest('input, textarea, select, [contenteditable="true"]')) return;
    const control = findControl(selectedId);
    if (!control) return;

    if ((e.ctrlKey || e.metaKey) && (e.key || '').toLowerCase() === 'd') {
        // Ctrl+D is the browser's bookmark, and this is a designer: what the key means here is
        // "another one of these", which is what it means in every other design tool.
        e.preventDefault();
        cloneControl();
        return;
    }
    if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault();
        deleteControl();
        return;
    }

    // A tab of a tab set fills its tab, so it has no row or column to nudge — moving one would
    // edit numbers that draw nothing. Everything else, panels and their contents included, is
    // laid out by these four.
    const holder = heldBy(control.controlId);
    if (holder && holder.type === 'tabs') return;
    // Shift resizes instead of moving: the same two axes, the same step, the other end of the
    // control. Half a row vertically because half a row is as fine as the grid is drawn.
    const moves = {
        ArrowLeft:  e.shiftKey ? ['span', (control.span || 1) - 1]    : ['col', (control.col || 0) - 1],
        ArrowRight: e.shiftKey ? ['span', (control.span || 1) + 1]    : ['col', (control.col || 0) + 1],
        ArrowUp:    e.shiftKey ? ['rowSpan', rowSpanOf(control) - 0.5] : ['row', (control.row || 0) - 0.5],
        ArrowDown:  e.shiftKey ? ['rowSpan', rowSpanOf(control) + 0.5] : ['row', (control.row || 0) + 0.5]
    };
    const move = moves[e.key];
    if (!move) return;
    e.preventDefault();
    setProp(move[0], move[1]);
    // setProp leaves the properties panel alone so typing into it keeps the caret; nothing is
    // being typed into here, and the row and column boxes should show where the control now is.
    renderProps();
});

/**
 * Ctrl+S saves, from wherever the caret is — mid-word in the title box included, since savePage
 * reads the header boxes itself. The one shortcut that is worth having while typing, and the
 * cheapest answer to the guard below ever having to ask anything.
 */
document.addEventListener('keydown', e => {
    if (!(e.ctrlKey || e.metaKey) || (e.key || '').toLowerCase() !== 's') return;
    if (STANDALONE || editor || mode !== 'design') return;
    e.preventDefault();
    savePage();
});

/**
 * The browser's own guard, for closing the tab, reloading, or following a link out of the
 * designer. It carries no message of its own — browsers stopped showing one years ago — but it is
 * the only thing between an afternoon's layout and a middle click on the wrong tab.
 *
 * <p>Never in standalone mode: that reader is running the page, not building it, and a page being
 * run is never dirty in the first place.
 */
window.addEventListener('beforeunload', e => {
    if (STANDALONE || !isDirty()) return;
    e.preventDefault();
    e.returnValue = '';
});

// ── Start ────────────────────────────────────────────────────────────────

AC.applyEmbedding();
// The report's stylesheet is a JS constant so the exported file can carry it verbatim; this is
// the page's copy of it, and the only reason the panel looks like the document it produces.
document.head.insertAdjacentHTML('beforeend', '<style>' + TECH_CSS + '</style>');
start();

/**
 * apppage.html?page=x&mode=run opens a saved page straight into its running form — the link
 * handed to whoever is meant to use the page rather than build it. That reader has no business
 * with the builder's chrome, so the page picker, the name and description fields and the
 * designer's own heading are all dropped: the form itself is the whole screen.
 */
async function start() {
    const wanted = PAGE_PARAMS.get('page');

    await loadCatalog();
    if (!wanted) return;
    if (!pages.some(p => p.pageName === wanted)) {
        // Said in the builder's status bar, so the chrome stays put until there is a page to show.
        AC.setStatus('statusBar', 'Could not open page "' + wanted + '": no such page.', 'error');
        return;
    }

    document.getElementById('pageSelect').value = wanted;
    await onPageSelected();
    if (STANDALONE) {
        document.body.classList.add('standalone');
        if (isChildPage()) document.body.classList.add('child-page');
        setMode('run');
    }
}
